    private fun isGatewaySessionReadyForCurrentActor(
        session: GatewayFieldSession? = gatewayFieldSession,
    ): Boolean {
        val actorId = currentReporterUserId()
        val processSnapshot = GatewaySessionProcessCoordinator.snapshot()
        return !processSnapshot.storageBlocked &&
            session != null &&
            processSnapshot.session === session &&
            session.verificationState == GatewaySessionVerificationState.VERIFIED &&
            session.isUsableFor(actorId) &&
            (developmentQuickStartEnabled || permissionSessionPolicy.isAuthenticatedFor(actorId))
    }

    private fun integratedConsentRefreshSessionOrNull(): GatewayFieldSession? {
        val session = gatewayFieldSession ?: return null
        if (isGatewaySessionReadyForCurrentActor(session)) return session
        val processSnapshot = GatewaySessionProcessCoordinator.snapshot()
        val onboardingActorId = firstRunOnboardingSnapshot.takeIf {
            it.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 && !it.isComplete
        }?.verifiedActorBinding?.value
        val readyForOnboardingRefresh =
            onboardingActorId != null &&
                processSnapshot.session === session &&
                !processSnapshot.storageBlocked &&
                !processSnapshot.deletionRecoveryOnly &&
                session.sessionScope == GatewaySessionScope.GENERAL &&
                session.verificationState == GatewaySessionVerificationState.VERIFIED &&
                session.actorId == onboardingActorId &&
                session.isUsableFor(onboardingActorId) &&
                session.gatewayBaseUrl == configuredGatewayOriginOrNull() &&
                reporterUserId == onboardingActorId &&
                priorityUserOnboardingActorId == onboardingActorId
        if (readyForOnboardingRefresh) return session
        clearExpiredGatewaySessionIfCurrent(session)
        return null
    }

    private fun clearExpiredGatewaySessionIfCurrent(session: GatewayFieldSession) {
        if (
            session.verificationState != GatewaySessionVerificationState.VERIFIED ||
            session.isUsableFor(session.actorId)
        ) return
        val process = GatewaySessionProcessCoordinator.snapshot()
        clearGatewaySession(
            logoutRemote = false,
            expectedSession = session,
            expectedProcessGeneration = process.generation,
        )
    }

    private fun isCurrentGatewaySession(session: GatewayFieldSession): Boolean =
        isGatewaySessionReadyForCurrentActor(session)

    private fun gatewayFailureUiGuardOrNull(
        session: GatewayFieldSession,
        expectedAuthenticationFailure: Boolean,
    ): GatewayFailureUiGuard? {
        if (expectedAuthenticationFailure) {
            val clearedGeneration = clearGatewaySession(
                logoutRemote = false,
                expectedSession = session,
            ) ?: return null
            return GatewayFailureUiGuard(
                generation = clearedGeneration,
                expectedAuthenticationFailure = true,
            )
        }
        return if (!isGatewaySessionReadyForCurrentActor(session)) {
            null
        } else {
            GatewayFailureUiGuard(
                generation = gatewaySessionGeneration,
                expectedAuthenticationFailure = false,
            )
        }
    }

    private fun isGatewayFailureUiGuardCurrent(
        session: GatewayFieldSession,
        guard: GatewayFailureUiGuard,
    ): Boolean {
        return if (gatewaySessionGeneration != guard.generation) {
            false
        } else if (guard.expectedAuthenticationFailure) {
            gatewayFieldSession == null
        } else {
            isGatewaySessionReadyForCurrentActor(session)
        }
    }

    private fun prepareReportMetadataContext() {
        reportApkSha256 = computeApkSha256()
        reportRuntimeConfig = loadReportRuntimeConfig()
    }

    private fun loadReportRuntimeConfig(): TwoModelRuntimeConfig? {
        return try {
            val runtimeJson = assets.open("model-config/two_model_runtime.json").bufferedReader().use { it.readText() }
            reportModelConfigSha256 = sha256Hex(runtimeJson.toByteArray())
            TwoModelRuntimeConfig.load(this)
        } catch (_: Exception) {
            null
        }
    }

    private fun computeApkSha256(): String? {
        return try {
            val digest = MessageDigest.getInstance("SHA-256")
            FileInputStream(applicationInfo.sourceDir).use { inputStream ->
                val buffer = ByteArray(1 shl 16)
                while (true) {
                    val read = inputStream.read(buffer)
                    if (read <= 0) break
                    digest.update(buffer, 0, read)
                }
            }
            hexEncoded(digest.digest())
        } catch (_: Exception) {
            null
        }
    }

    private fun sha256Hex(bytes: ByteArray): String {
        return hexEncoded(MessageDigest.getInstance("SHA-256").digest(bytes))
    }

    private fun hexEncoded(bytes: ByteArray): String {
        return bytes.joinToString("") { "%02x".format(it.toInt() and 0xFF) }
    }

    private fun resolveReportSourceModel(modelKey: String?): String? {
        val runtimeSourceModel = reportRuntimeConfig?.sourceModelForReportModel(modelKey)
        return runtimeSourceModel ?: modelKey?.let { "android/$it" }
    }

    private fun resolveReportThreshold(modelKey: String?, className: String): Float? {
        return reportRuntimeConfig?.thresholdForReportClass(modelKey, className)
    }

    override fun onResume() {
        super.onResume()
        accountRequestFence.enteredForeground()
        feedbackLifecycleGeneration += 1
        isActivityForeground = true
        runtimeLoadObservationSource.start()
        cancelForegroundHomeWakeListening(resetFailure = true)
        revalidateUserReportAuthorityOnResume()
        if (::firstRunWaitingCard.isInitialized) {
            updateFirstRunWaitingDots(firstRunWaitingCard.visibility == View.VISIBLE)
        }
        if (!privacyStartupInspectionComplete) {
            completePrivacyStartupReadyIfForeground()
            return
        }
        resumeWalkSafeRuntimeAfterPrivacyStartupInspection()
    }

    override fun onWindowFocusChanged(hasFocus: Boolean) {
        super.onWindowFocusChanged(hasFocus)
        if (
            !hasFocus ||
            !isActivityForeground ||
            !privacyStartupInspectionComplete ||
            privacyStartupInspectionDestroyed
        ) return
        if (postLoginDeviceCheckSnapshot.passesFeatureGate) {
            refreshStartupCapabilityUi()
        }
    }

    private fun resumeWalkSafeRuntimeAfterPrivacyStartupInspection() {
        retryPendingBackendDeviceRestore()
        if (permissionRecoveryGate.blocksAutomaticResourceStart) {
            permissionRecoveryGate = permissionRecoveryGate.recheckRequired()
            persistPermissionRecoveryGate()
        }
        revalidateCompletedPostLoginDeviceCheckPrerequisites()
        if (advanceEmailStagesWithRestoredDeviceCheck()) {
            onFirstRunOnboardingStateChanged(
                announcement = "저장된 기기 점검 결과를 적용했습니다. 안전교육을 완료하세요.",
                preservePostLoginDeviceCheck = true,
            )
        }
        storedMetricDepthRefreshRetryAllowed = true
        maybeStartStoredMetricDepthRefresh()
        handleWalkSessionForegroundReturn()
        revalidateGatewayWalkAfterForegroundReturn()
        applyObservedPermissionStateChange("app_resumed")
        requestInitialAppEntryPermissionsIfNeeded()
        syncActiveSessionScreenPolicy()
        recheckVoiceDataAfterSettingsIfNeeded()
        refreshStartupCapabilityUi()
        if (
            postLoginDeviceCheckBackgroundFailurePending &&
            postLoginDeviceCheckSnapshot.state == PostLoginDeviceCheckState.FAIL &&
            postLoginDeviceCheckSnapshot.failure == PostLoginDeviceCheckFailure.BACKGROUNDED
        ) {
            postLoginDeviceCheckBackgroundFailurePending = false
            announcePostLoginDeviceCheckTerminal(
                "기기 점검이 중지되었습니다. " +
                    postLoginDeviceCheckFailureMessage(
                        PostLoginDeviceCheckFailure.BACKGROUNDED,
                    ),
            )
        }
        updateIntegratedConsentUi()
        updateReportPrivacyConsentUi()
        completePermissionRecoveryRecheckIfPossible()
        maybeStartPausedReportQueueRecoveryObservation()
        if (postLoginDeviceCheckPermissionResultPending) {
            val permissionBinding = postLoginDeviceCheckPendingPermissionBinding
            postLoginDeviceCheckPermissionResultPending = false
            postLoginDeviceCheckPendingPermissionBinding = null
            permissionBinding?.let(::completePostLoginDeviceCheckPermissionObservation)
        }
        if (::fieldSessionLog.isInitialized) fieldSessionLog.recordEvent("app_resumed")
        if (
            session == null &&
            actionMode == ActionMode.OPEN_SETTINGS &&
            checkSelfPermission(Manifest.permission.CAMERA) == PackageManager.PERMISSION_GRANTED
        ) {
            setActionButton("ARCore Depth 시작", ActionMode.START, enabled = true)
            updateStatus("ARCore Depth 대기", "카메라 권한이 허용되었습니다. ARCore Depth를 시작할 수 있습니다.")
        }
        scheduleDeviceRuntimeCalibration()
    }

    @SuppressLint("GestureBackNavigation")
    @Suppress("OVERRIDE_DEPRECATION")
    override fun onBackPressed() {
        walkBackDispatcher.onBackPressed()
    }

    private fun handleWalkScreenBackPressed(): Boolean {
        if (handleNativeFeatureBackPressed()) return true
        cancelNativePendingFeatureEntry()
        val state = walkSessionLifecycle.snapshot().state
        if (state != WalkSessionState.ACTIVE && state != WalkSessionState.PAUSED) return false
        transitionWalkSession(WalkSessionEvent.EndRequested)
        persistWalkSessionInterruptionMarker()
        cancelWalkSessionOutputs("system_back_exit_confirmed")
        finish()
        return true
    }

    private fun showWalkExitConfirmationDialog() {
        if (walkExitConfirmationDialog?.isShowing == true) return
        val dialog = AlertDialog.Builder(this)
            .setTitle(R.string.walk_exit_confirmation_title)
            .setMessage(R.string.walk_exit_confirmation_message)
            .setPositiveButton(R.string.walk_exit_confirmation_positive) { _, _ ->
                transitionWalkSession(WalkSessionEvent.EndRequested)
                persistWalkSessionInterruptionMarker()
                cancelWalkSessionOutputs("system_back_exit_confirmed")
                finish()
            }
            .setNegativeButton(R.string.walk_exit_confirmation_negative) { current, _ ->
                walkSessionResumeRetryRequiresUserAction = true
                syncActiveSessionScreenPolicy()
                current.dismiss()
            }
            .setOnCancelListener {
                walkSessionResumeRetryRequiresUserAction = true
                syncActiveSessionScreenPolicy()
            }
            .create()
        walkExitConfirmationDialog = dialog
        dialog.setOnDismissListener {
            if (walkExitConfirmationDialog === dialog) {
                walkExitConfirmationDialog = null
            }
        }
        dialog.show()
    }

    override fun onSaveInstanceState(outState: Bundle) {
        outState.putBoolean(STATE_INITIAL_APP_PERMISSION_RE_REQUESTED, initialAppPermissionReRequestedThisLaunch)
        if (::userReportController.isInitialized) {
            userReportController.snapshot().statusFilter?.let { filter ->
                outState.putString(STATE_USER_REPORT_STATUS_FILTER, filter.wireValue)
            } ?: outState.remove(STATE_USER_REPORT_STATUS_FILTER)
        }
        super.onSaveInstanceState(outState)
    }

    override fun onPause() {
        cancelDeviceRuntimeCalibration("backgrounded")
        runtimeLoadMonitor.pause()
        if (runtimeLoadObservationSourceHolder.isInitialized()) runtimeLoadObservationSource.pause()
        runtimeLoadNormalFrameAtMs = null
        cancelForegroundHomeWakeAcknowledgement()
        cancelForegroundHomeWakeListening()
        clearHomeDestinationVoiceDialog(VoiceDialogDiagnosticReason.BACKGROUNDED)
        clearPendingExplicitRouteStart()
        cancelDestinationSearchLocation()
        cancelNativePrewalkPreparation(cancelFeatureEntry = true)
        cancelUserReportAuthorityExpirySchedule()
        if (::firstRunWaitingCard.isInitialized) updateFirstRunWaitingDots(active = false)
        stopHandsFreeVoiceService()
        cancelGatewaySpeechInteraction("app_paused")
        if (::rawCollectionRuntimeCoordinator.isInitialized) {
            rawCollectionUploadWalkId = null
            rawCollectionRuntimeCoordinator.cancelActiveUpload()
            revalidateRawCollectionRuntime()
        }
        val previousDeviceCheck = postLoginDeviceCheckSnapshot
        val ownedPermissionDialog = postLoginDeviceCheckPermissionRequestCode?.let {
            permissionRequestLeases.containsKey(it)
        } == true
        postLoginDeviceCheckSnapshot = PostLoginDeviceCheckPolicy.onBackground(
            snapshot = previousDeviceCheck,
            binding = previousDeviceCheck.bindingOrNull,
            ownsPermissionDialog = ownedPermissionDialog,
        )
        if (postLoginDeviceCheckSnapshot != previousDeviceCheck) {
            postLoginDeviceCheckBackgroundFailurePending =
                postLoginDeviceCheckSnapshot.failure ==
                PostLoginDeviceCheckFailure.BACKGROUNDED
            cancelPostLoginDeviceCheckRuntime("app_paused")
        }
        accountRequestFence.enteredBackground()
        emailOtpRequestRetryPolicy.suspendForLifecycle()
        cancelReportQueueDrain()
        if (!privacyStartupInspectionComplete) {
            isActivityForeground = false
            feedbackLifecycleGeneration += 1
            super.onPause()
            return
        }
        pauseWalkSafeRuntime()
        if (::cameraFallbackLifecycleOwner.isInitialized) {
            cameraFallbackLifecycleOwner.moveTo(Lifecycle.State.CREATED)
        }
        super.onPause()
    }

    internal fun pauseWalkSafeRuntime() {
        cancelPendingPriorityUserTrainingFeedback()
        invalidatePendingExplicitReport()
        if (::walkSessionLifecycle.isInitialized) {
            transitionWalkSession(WalkSessionEvent.EnteredBackground)
            persistWalkSessionInterruptionMarker()
        }
        invalidateOfficialEnvironmentEvidence("app_paused")
        invalidatePhoneMountingEvidence("app_paused")
        isActivityForeground = false
        feedbackLifecycleGeneration += 1
        if (::surfaceView.isInitialized) {
            syncGlSurfaceRenderMode(forceFrame = true)
            surfaceView.onPause()
        }
        invalidateRuntimeMetricEvidence("app_paused")
        confirmedStartupCapabilityDecision = null
        startupCapabilityConfirmationPending = false
        walkSessionResumePromptPending = false
        walkSessionResumeRetryRequiresUserAction = false
        walkSessionResumeConfirmationToken = null
        gatewayWalkResumeRevalidationPending = false
        cancelPendingGatewayWalkStart()
        invalidateArCoreAvailabilityRecheck()
        cancelVoiceCommandRecognition()
        synchronized(reportUploadSafetyLock) {
            reportUploadSafetyGeneration += 1L
            reportPrivacyConsentSession.cancelActiveCalls()
        }
        invalidateFrameStateForPause()
        val navigationCancellation = cancelNavigationRequestsForPause()
        suspendNavigationForRecovery(navigationCancellation)
        syncActiveSessionScreenPolicy()
        if (::statusText.isInitialized) pendingTalkBackInteraction?.let(statusText::removeCallbacks)
        pendingTalkBackInteraction = null
        cancelPendingFeedbackTerminalResolution()
        latestFeedbackDeliveryState = FeedbackDeliveryState()
        lastRiskAnnouncementRank = -1
        lastRiskAnnouncementTrackId = ""
        riskAnnouncementHoldUntilMs = 0L
        navigationAnnouncementHoldUntilMs = 0L
        lastAdvisoryAnnouncementMs = 0L
        lastAdvisoryAnnouncement = ""
        if (::fieldSessionLog.isInitialized) fieldSessionLog.recordEvent("app_paused")
        if (
            ::fieldSessionLog.isInitialized &&
            permissionRecoveryGate.blocksAutomaticResourceStart
        ) {
            fieldSessionLog.blockActiveSessionRestore()
        }
        stopLocationUpdates()
        stopStepTracking()
        if (::phoneMountingSensorProbe.isInitialized) phoneMountingSensorProbe.stop()
        if (::earthOrientationTracker.isInitialized) earthOrientationTracker.stop()
        feedbackPolicy.cancelPendingFeedbackDeliveries()
        nonMetricAdvisoryPolicy.reset()
        feedbackActuator?.close()
        feedbackActuator = null
        session?.pause()
    }

    private fun invalidateFrameStateForPause() {
        synchronized(frameStateLock) {
            detectorGeneration += 1
            resetVisualTrackingState()
            latestDetectionSnapshot = DetectionSnapshot.empty()
            latestExplicitReportOutput = null
            latestExplicitReportImage = null
            latestExplicitReportGateState = null
            latestExplicitReportCapturedAtMs = 0L
            latestReportCandidateStatus = "reportCandidate=blocked:runtime_paused"
            frameCaptureRequested.set(false)
            reportLocationStartScheduled.set(false)
            adaptiveInferencePacing.reset()
            lastOverlayUpdateMs = 0L
            lastUiUpdateMs = 0L
            latestTactileRouteState = "localRoute=tmap:tactile_not_visible"
            objectDepthPipeline = ObjectDepthRuntimePipeline(rawDepthMotionOnly = true).also { pipeline ->
                pipeline.setUserStepLength(stepLengthEstimator.stepLengthM)
            }
            captureLog.clear()
        }
        if (::debugBboxOverlay.isInitialized) runOnUiThread { debugBboxOverlay.clear() }
        if (::debugFrameCaptureButton.isInitialized) runOnUiThread { updateFrameCaptureButton() }
    }

    override fun onDestroy() {
        if (runtimeLoadObservationSourceHolder.isInitialized()) runtimeLoadObservationSource.close()
        synchronized(frameStateLock) {
            detectorClosing = true
            detectorLoadGeneration += 1L
        }
        cancelDestinationSearchLocation()
        initialAppPermissionExitDialog?.dismiss()
        initialAppPermissionExitDialog = null
        cancelNativePrewalkPreparation(cancelFeatureEntry = true)
        cancelUserReportAuthorityExpirySchedule()
        invalidatePendingExplicitReport()
        closeHandsFreeVoice()
        cancelGatewaySpeechInteraction("app_destroyed")
        gatewaySpeechExecutor.shutdownNow()
        if (::rawCollectionRuntimeCoordinator.isInitialized) {
            rawCollectionUploadWalkId = null
            rawCollectionRuntimeCoordinator.cancelActiveUpload()
        }
        rawCollectionExecutor.shutdownNow()
        accountRequestFence.enteredBackground()
        cancelReportQueueDrain()
        reportQueueDrainExecutor.shutdownNow()
        clearUserReportRequestUiForAuthorityFence()
        if (::userReportController.isInitialized) userReportController.onDestroy()
        synchronized(privacyStartupInspectionLock) {
            privacyStartupInspectionDestroyed = true
            privacyStartupInspectionGeneration += 1L
        }
        unregisterGatewayCapacityNetworkObserver()
        cancelEncryptedRouteSnapshotExpirySchedule()
        pendingPrivacyStartupReadyAction = null
        if (!privacyStartupInspectionComplete) {
            if (::accountDeletionActivityLease.isInitialized) {
                accountDeletionProcessCoordinator.detach(accountDeletionActivityLease)
            }
            schedulePrivacyStartupResourcesClose()
            reportCleanupExecutor.shutdown()
            if (::cameraFallbackLifecycleOwner.isInitialized) {
                cameraFallbackLifecycleOwner.moveTo(Lifecycle.State.DESTROYED)
            }
            routeExecutor.shutdownNow()
            super.onDestroy()
            return
        }
        if (::accountDeletionActivityLease.isInitialized) {
            accountDeletionProcessCoordinator.detach(accountDeletionActivityLease)
        }
        synchronized(legacyPendingReportQueuePurgeLock) {
            reportCleanupDestroyed = true
            reportCleanupGeneration += 1L
            legacyPendingReportQueuePurgeInFlight = false
            legacyPendingReportQueuePurgeWaiters.clear()
        }
        reportCleanupExecutor.shutdownNow()
        synchronized(integratedConsentLock) {
            integratedConsentRequestGeneration += 1L
            integratedConsentCall?.cancel()
            integratedConsentBootstrapCall?.cancel()
            integratedConsentCall = null
            integratedConsentBootstrapCall = null
            integratedConsentRequestInFlight = false
        }
        synchronized(accountDeletionLock) {
            accountDeletionRequestGeneration += 1L
            accountDeletionCall?.cancel()
            accountDeletionCall = null
            accountDeletionRequestInFlight = false
        }
        GatewaySessionProcessCoordinator.detach(gatewaySessionOwner)
        if (::gatewayWalkRenewalHandler.isInitialized) {
            gatewayWalkRenewalHandler.removeCallbacksAndMessages(null)
        }
        gatewayWalkAuthorityController.reset()
        gatewayWalkStartConfirmationToken = null
        gatewayWalkTakeoverPromptPending = false
        gatewayWalkTakeoverPromptOperationId = null
        gatewayWalkResumeRevalidationPending = false
        cancelNavigationRequestsForDestroy()
        isActivityForeground = false
        if (::surfaceView.isInitialized) {
            syncGlSurfaceRenderMode(forceFrame = true)
            surfaceView.onPause()
        }
        invalidateRuntimeMetricEvidence("app_destroyed")
        invalidateOfficialEnvironmentEvidence("app_destroyed")
        invalidatePhoneMountingEvidence("app_destroyed")
        invalidateArCoreAvailabilityRecheck()
        cancelPendingFeedbackTerminalResolution()
        latestFeedbackDeliveryState = FeedbackDeliveryState()
        syncActiveSessionScreenPolicy()
        if (::cameraFallbackLifecycleOwner.isInitialized) {
            cameraFallbackLifecycleOwner.moveTo(Lifecycle.State.DESTROYED)
        }
        stopCameraFallbackSession()
        stopDepthSession(closeSession = true)
        stopLocationUpdates()
        stopStepTracking()
        if (::earthOrientationTracker.isInitialized) earthOrientationTracker.stop()
        gnssQualityObserver?.close()
        gnssQualityObserver = null
        pedestrianMotionTracker?.close()
        pedestrianMotionTracker = null
        positioningCoordinator.reset()
        schedulePrivacyStartupResourcesClose()
        feedbackPolicy.cancelPendingFeedbackDeliveries()
        feedbackActuator?.close()
        feedbackActuator = null
        cancelVoiceCommandRecognition()
        speechRecognizer?.destroy()
        speechRecognizer = null
        if (::startupCapabilityProbe.isInitialized) {
            startupCapabilityProbe.close()
        }
        if (::walkSessionResourceProbe.isInitialized) {
            walkSessionResourceProbe.close()
        }
        permissionRequestLeases.clear()
        permissionRequestGenerationByPurpose.clear()
        synchronized(reportUploadSafetyLock) {
            reportUploadSafetyGeneration += 1L
            reportPrivacyConsentSession.cancelActiveCalls()
        }
        routeExecutor.shutdownNow()
        closeDetectorAsync()
        super.onDestroy()
    }

    @Deprecated("Activity result API retained for the existing SAF document flow")
    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (requestCode == REQUEST_POSITION_FIELD_EXPORT) {
            handlePositionFieldExportResult(resultCode, data)
        }
    }

    override fun onRequestPermissionsResult(
        requestCode: Int,
        permissions: Array<out String>,
        grantResults: IntArray,
    ) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults)
        val lease = permissionRequestLeases.remove(requestCode) ?: return
        if (
            lease.purpose == PermissionRequestPurpose.WALK_SESSION &&
            walkSessionPermissionRequestCode == requestCode
        ) {
            walkSessionPermissionRequestCode = null
            walkSessionPermissionRequestInFlight = false
        }
        if (!isPermissionRequestLeaseCurrent(lease)) return
        val observed = currentObservedPermissionSnapshot()
        val missingRequested = lease.requestedPermissions
            .filterNot(observed::isGranted)
            .toSet()
        if (lease.purpose == PermissionRequestPurpose.WALK_SESSION) {
            permissionRecoveryGate = PermissionRecoveryGate()
            persistPermissionRecoveryGate()
        }
        when (lease.purpose) {
            PermissionRequestPurpose.INITIAL_APP_ENTRY ->
                handleInitialAppEntryPermissionResult()
            PermissionRequestPurpose.POST_LOGIN_DEVICE_CHECK ->
                lease.postLoginBinding?.let(::handlePostLoginDeviceCheckPermissionResult)
            PermissionRequestPurpose.METRIC_PREFLIGHT_CAMERA ->
                handleMetricPreflightCameraPermissionResult()
            PermissionRequestPurpose.WALK_SESSION -> handleWalkSessionPermissionResult()
            PermissionRequestPurpose.RUNTIME_CAMERA -> handleCameraPermissionResult()
            PermissionRequestPurpose.NAVIGATION -> handleNavigationPermissionResult()
            PermissionRequestPurpose.VOICE_COMMAND -> handleVoicePermissionResult()
        }
        applyObservedPermissionStateChange(
            "permission_result_${lease.purpose.name.lowercase(Locale.US)}",
        )
        if (
            lease.purpose == PermissionRequestPurpose.WALK_SESSION &&
            missingRequested.isNotEmpty()
        ) {
            showPermissionDenialPanel(
                missingPermissions = missingRequested,
                reason = "permission_result_walk_session",
            )
        }
    }

    private fun requestPermissionsWithLease(
        permissions: Array<String>,
        purpose: PermissionRequestPurpose,
    ): Int? {
        if (!firstRunPermissionRequestAllowed(purpose)) return null
        val postLoginBinding = if (purpose == PermissionRequestPurpose.POST_LOGIN_DEVICE_CHECK) {
            postLoginDeviceCheckSnapshot.bindingOrNull?.takeIf {
                isPostLoginDeviceCheckSnapshotBindingLive(it)
            } ?: return null
        } else {
            null
        }
        val epoch = walkSessionLifecycle.snapshot().epoch
        val requestedPermissions = permissions.mapNotNull { it.toObservedPermission() }.toSet()
        if (purpose == PermissionRequestPurpose.WALK_SESSION) {
            permissionRecoveryGate = permissionRecoveryGate.requestPending(requestedPermissions)
            persistPermissionRecoveryGate()
            if (::fieldSessionLog.isInitialized) {
                fieldSessionLog.blockActiveSessionRestore()
            }
        }
        val generation = (permissionRequestGenerationByPurpose[purpose] ?: 0L) + 1L
        permissionRequestGenerationByPurpose[purpose] = generation
        var requestCode = nextPermissionRequestCode
        while (permissionRequestLeases.containsKey(requestCode)) {
            requestCode += 1
            if (requestCode > PERMISSION_REQUEST_CODE_MAX) {
                requestCode = PERMISSION_REQUEST_CODE_MIN
            }
            check(requestCode != nextPermissionRequestCode) {
                "No permission request code is available"
            }
        }
        nextPermissionRequestCode = requestCode + 1
        if (nextPermissionRequestCode > PERMISSION_REQUEST_CODE_MAX) {
            nextPermissionRequestCode = PERMISSION_REQUEST_CODE_MIN
        }
        permissionRequestLeases[requestCode] = PermissionRequestLease(
            purpose = purpose,
            epoch = epoch,
            generation = generation,
            firstRunLease = currentFirstRunAsyncLease(),
            requestedPermissions = requestedPermissions,
            postLoginBinding = postLoginBinding,
        )
        try {
            requestPermissions(permissions, requestCode)
        } catch (error: RuntimeException) {
            permissionRequestLeases.remove(requestCode)
            if (purpose == PermissionRequestPurpose.WALK_SESSION) {
                enterPermissionRecoveryBarrier(
                    missingPermissions = requestedPermissions,
                    reason = "permission_request_failed",
                )
            }
            throw error
        }
        return requestCode
    }

    private fun isPermissionRequestLeaseCurrent(
        lease: PermissionRequestLease,
    ): Boolean {
        if (lease.purpose != PermissionRequestPurpose.INITIAL_APP_ENTRY) {
            if (!isFirstRunAsyncLeaseCurrent(lease.firstRunLease)) return false
            if (!firstRunPermissionRequestAllowed(lease.purpose)) return false
        }
        if (
            permissionRequestGenerationByPurpose[lease.purpose] !=
            lease.generation
        ) return false
        if (lease.purpose == PermissionRequestPurpose.INITIAL_APP_ENTRY) {
            return privacyStartupInspectionComplete &&
                !privacyStartupInspectionDestroyed
        }
        if (lease.purpose == PermissionRequestPurpose.POST_LOGIN_DEVICE_CHECK) {
            return lease.postLoginBinding?.let(::isPostLoginDeviceCheckSnapshotBindingLive) == true
        }
        val snapshot = walkSessionLifecycle.snapshot()
        if (snapshot.epoch != lease.epoch) return false
        return when (lease.purpose) {
            PermissionRequestPurpose.INITIAL_APP_ENTRY -> false
            PermissionRequestPurpose.POST_LOGIN_DEVICE_CHECK -> false
            PermissionRequestPurpose.METRIC_PREFLIGHT_CAMERA,
            PermissionRequestPurpose.WALK_SESSION,
            -> snapshot.isForeground &&
                snapshot.state in setOf(WalkSessionState.READY, WalkSessionState.PAUSED)
            PermissionRequestPurpose.RUNTIME_CAMERA,
            PermissionRequestPurpose.NAVIGATION,
            PermissionRequestPurpose.VOICE_COMMAND,
            -> walkSessionLifecycle.isRuntimeEpochCurrent(lease.epoch)
        }
    }

    private fun handleMetricPreflightCameraPermissionResult() {
        val generation = pendingMetricPreflightPermissionGeneration ?: return
        pendingMetricPreflightPermissionGeneration = null
        if (!isRuntimeMetricPreflightAttemptCurrent(generation, metricPreflightLifecycleGeneration)) return
        if (hasCameraPermission()) {
            startRuntimeMetricPreflight(generation, metricPreflightLifecycleGeneration)
        } else {
            refreshStartupCapabilityUi()
            val detail = if (shouldShowRequestPermissionRationale(Manifest.permission.CAMERA)) {
                "실제 미터 거리 기능을 확인하려면 카메라 권한이 필요합니다."
            } else {
                "Android 앱 설정에서 카메라 권한을 허용한 뒤 다시 확인하세요."
            }
            updateStatus("카메라 권한 필요", detail)
        }
    }

    private fun handleWalkSessionPermissionResult() {
        walkSessionPermissionRequestInFlight = false
        if (!isActivityForeground) return
        val decision = startupCapabilityDecision ?: return
        val action = if (
            walkSessionLifecycle.snapshot().state == WalkSessionState.PAUSED
        ) {
            WalkSessionAction.RESUME_WALK
        } else {
            WalkSessionAction.START_WALK
        }
        val missingRequired = missingRequiredWalkSessionPermissions(action)
        val missing = missingWalkSessionPermissions(decision)
        refreshStartupCapabilityUi()
        if (missingRequired.isNotEmpty()) {
            updateStatus(
                "필수 권한 필요",
                "보행 안내를 시작하지 않았습니다. 필요한 권한: " +
                    missingRequired.joinToString(", ") { it.permissionLabelKo() },
            )
        } else if (missing.isNotEmpty()) {
            updateStatus(
                "일부 기능 권한 없음",
                "허용된 기능으로 계속합니다. 사용할 때 다시 확인할 권한: " +
                    missing.joinToString(", ") { it.permissionLabelKo() },
            )
        }
    }

    private fun handleCameraPermissionResult() {
        if (permissionRecoveryGate.blocksAutomaticResourceStart) return
        if (hasCameraPermission()) {
            setActionButton("ARCore Depth 시작", ActionMode.START, enabled = true)
            startConfirmedRuntimeAfterCameraPermission()
        } else {
            if (shouldShowRequestPermissionRationale(Manifest.permission.CAMERA)) {
                setActionButton("카메라 권한 다시 요청", ActionMode.START, enabled = true)
                updateStatus("카메라 권한 필요", "ARCore Depth를 시작하려면 카메라 권한을 허용해야 합니다.")
            } else {
                setActionButton("앱 설정 열기", ActionMode.OPEN_SETTINGS, enabled = true)
                updateStatus("카메라 권한 차단됨", "Android 앱 설정에서 카메라 권한을 허용한 뒤 다시 시작하세요.")
            }
        }
    }

    private fun handleNavigationPermissionResult() {
        if (permissionRecoveryGate.blocksAutomaticResourceStart && !developmentGuidanceStartBypassEnabled) return
        if (hasLocationPermission()) {
            if (isRouteActive || navigationPermissionsRequestedForRoute || navigationPermissionsRequestedForReport || isFieldSessionActive()) {
                startLocationUpdatesIfAllowed(forceRestart = true)
            }
        } else if (!hasLocationPermission()) {
            updateNavigationStatus("navigation=gps_permission_missing")
        }
        if (hasActivityRecognitionPermission()) {
            if (isRouteActive || navigationPermissionsRequestedForRoute || isFieldSessionActive()) {
                startStepTrackingIfAllowed()
            }
        } else if (isRouteActive || navigationPermissionsRequestedForRoute || isFieldSessionActive()) {
            updateNavigationStatus("navigation=activity_recognition_permission_missing step_fallback_wait")
        }
    }

    private fun handleVoicePermissionResult() {
        if (permissionRecoveryGate.blocksAutomaticResourceStart) return
        if (hasRecordAudioPermission()) {
            startVoiceCommandRecognition()
        } else {
            updateNavigationStatus("voice=record_audio_permission_missing")
            speakInteraction("음성 명령을 사용하려면 마이크 권한이 필요합니다.")
        }
    }

    override fun onSurfaceCreated(gl: GL10?, config: EGLConfig?) {
        backgroundRenderer.createOnGlThread()
        synchronized(frameStateLock) {
            if (!visualFrameTracker.initialize()) latestVisualTrackingStatus = "visual=native_initialization_failed"
        }
        cameraTextureBound = false
        cameraTextureId = createExternalCameraTexture()
        bindCameraTextureIfReady()
    }

    override fun onSurfaceChanged(gl: GL10?, width: Int, height: Int) {
        if (surfaceWidth != width || surfaceHeight != height) resetVisualTrackingState()
        surfaceWidth = width
        surfaceHeight = height
        GLES20.glViewport(0, 0, width, height)
        updateDisplayGeometryIfReady()
    }

    private fun resetVisualTrackingState() = synchronized(frameStateLock) {
        invalidateUnknownObjectObservations()
        unknownLoadControl.pause()
        latestUnknownLoadObservation = null
        visualFrameTracker.clear()
        visualTrackingBudget.reset()
        runtimeCameraFrameBudgetMs = null
        runtimeLoadNormalFrameAtMs = null
        runtimeLoadMonitor.reset()
        currentVisualTrackingBudgetNs = 5_000_000L
        visualGeometryVersion += 1L
        lastVisualFrameKey = null
        lastRuntimeCameraFrameId = 0L
        latestVisualOverlayFrameId = 0L
        latestVisualTrackingStatus = "visual=waiting_for_new_capture"
        currentObjectDepthPipeline = ObjectDepthRuntimePipeline(
            rawDepthMotionOnly = true,
            tracker = ObjectTracker(trackIdPrefix = "visual-$visualGeometryVersion-track-"),
        ).also { it.setUserStepLength(stepLengthEstimator.stepLengthM) }
    }

    private fun hasFreshVisualSource(nowElapsedRealtimeMs: Long): Boolean {
        val source = latestDetectionSnapshot
        val capturedAt = source.capturedAtElapsedRealtimeMs ?: return false
        return !source.partial && source.detections.isNotEmpty() &&
            source.frameEvidence?.visualFrameKey != null &&
            nowElapsedRealtimeMs - capturedAt in 0L..MAX_DEPTH_DETECTION_SOURCE_AGE_MS
    }

    private fun captureVisualTrackingFrame(
        provider: ArCoreFrameProvider,
        frame: Frame,
        snapshot: DepthFrameSnapshot,
        capturedAtElapsedRealtimeMs: Long,
        frameGeneration: Int,
        walkEpoch: WalkRuntimeEpoch,
        arGeneration: Long,
    ): GrayTrackingFrame? {
        if (!postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION)) return null
        val geometryVersion = synchronized(frameStateLock) {
            if (!isCurrentFrameGeneration(frameGeneration, walkEpoch) || !detectorAvailable) return null
            visualGeometryVersion
        }
        val gray = try {
            provider.acquireCameraImageOrNull(frame)?.use { image ->
                if (image.timestamp <= 0L || image.timestamp != snapshot.cameraImageTimestampNs) return@use null
                val plane = image.planes.firstOrNull() ?: return@use null
                GrayTrackingFrame.copyFromLuma(
                    VisualFrameKey(arGeneration, frame.timestamp, image.timestamp, capturedAtElapsedRealtimeMs, geometryVersion),
                    image.width, image.height, plane.buffer, plane.rowStride, plane.pixelStride,
                )
            }
        } catch (_: IllegalArgumentException) {
            null
        } catch (_: IllegalStateException) {
            null
        } ?: return null
        return synchronized(frameStateLock) {
            if (!isCurrentFrameGeneration(frameGeneration, walkEpoch) || visualGeometryVersion != geometryVersion) return null
            // A repeated Session.update is not another camera observation or a new capture time.
            val previous = lastVisualFrameKey
            if (previous != null && previous.epoch == arGeneration && previous.frameId >= gray.key.frameId) return null
            val admission = visualFrameTracker.offerFrame(gray)
            if (!admission.accepted) return null
            if (admission.reset) {
                currentObjectDepthPipeline = ObjectDepthRuntimePipeline(
                    rawDepthMotionOnly = true,
                    tracker = ObjectTracker(trackIdPrefix = "visual-$geometryVersion-${gray.key.frameId}-track-"),
                ).also { it.setUserStepLength(stepLengthEstimator.stepLengthM) }
            }
            lastVisualFrameKey = gray.key
            currentVisualTrackingBudgetNs = visualTrackingBudget.budgetForFrame(gray.key)
            gray
        }
    }

    /** Keeps preview, coordinate mapping and depth acquisition on the same ARCore frame. */
    override fun onDrawFrame(gl: GL10?) {
        GLES20.glClearColor(0f, 0f, 0f, 1f)
        GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT or GLES20.GL_DEPTH_BUFFER_BIT)

        val frameGeneration = synchronized(frameStateLock) {
            if (!isActivityForeground) return
            detectorGeneration
        }

        val arLease = synchronized(runtimeMetricStateLock) {
            val currentSession = session ?: return
            val currentProvider = frameProvider ?: return
            ArSessionLease(
                session = currentSession,
                provider = currentProvider,
                purpose = arSessionPurpose,
                generation = arSessionGeneration,
            )
        }
        bindCameraTextureIfReady()
        if (!cameraTextureBound) return
        if (!isArSessionLeaseCurrent(arLease)) return
        val frameWalkEpoch = walkSessionLifecycle.snapshot().epoch

        val frame = try {
            arLease.session.update()
        } catch (error: CameraNotAvailableException) {
            handleRuntimeMetricFrameFailure(
                "카메라 사용 불가",
                error.message ?: "ARCore frame update 실패",
                arLease.purpose,
                arLease.generation,
                frameWalkEpoch,
            )
            return
        } catch (error: RuntimeException) {
            handleRuntimeMetricFrameFailure(
                "ARCore frame 대기",
                error.message ?: "frame update 준비 중",
                arLease.purpose,
                arLease.generation,
                frameWalkEpoch,
            )
            return
        }
        if (!isArSessionLeaseCurrent(arLease)) return
        if (frame.hasDisplayGeometryChanged()) {
            resetVisualTrackingState()
            updateDisplayGeometryIfReady()
            runOnUiThread {
                if (isArSessionLeaseCurrent(arLease) &&
                    isCurrentFrameGeneration(frameGeneration, frameWalkEpoch)
                ) debugBboxOverlay.clear()
            }
        }

        val provider = arLease.provider
        backgroundRenderer.draw(frame, cameraTextureId)
        val timestampMs = frame.timestamp / 1_000_000L
        val nowMs = System.currentTimeMillis()
        val elapsedRealtimeMs = SystemClock.elapsedRealtime()
        val includeFullDepthWhenRawAvailable = arLease.purpose == ArSessionPurpose.PREFLIGHT ||
            synchronized(frameStateLock) {
                detectorAvailable &&
                    !detectionInFlight.get() &&
                    adaptiveInferencePacing.isDue(elapsedRealtimeMs)
            } || unknownFrameCaptureIsDue(elapsedRealtimeMs) || hasFreshVisualSource(elapsedRealtimeMs)
        val depthProcessingStartedMs = SystemClock.elapsedRealtime()
        val snapshot = if (arLease.purpose == ArSessionPurpose.PREFLIGHT) {
            provider.acquirePreflightDepthBundle(frame).toSnapshotAndClose()
        } else {
            provider.acquireDepthSnapshot(
                frame,
                includeFullDepthWhenRawAvailable = includeFullDepthWhenRawAvailable,
            )
        }
        val depthProcessingMs = SystemClock.elapsedRealtime() - depthProcessingStartedMs
        if (!isArSessionLeaseCurrent(arLease)) return
        if (arLease.purpose == ArSessionPurpose.PREFLIGHT) {
            handleRuntimeMetricPreflightFrame(
                frame = frame,
                snapshot = snapshot,
                observedAtElapsedRealtimeMs = elapsedRealtimeMs,
                expectedArSessionGeneration = arLease.generation,
                expectedWalkEpoch = frameWalkEpoch,
            )
            return
        }
        if (arLease.purpose != ArSessionPurpose.RUNTIME || !isStartupCapabilityConfirmed()) {
            runtimeMetricOutputAllowed = false
            return
        }
        val walkEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull()
        if (walkEpoch == null) {
            runtimeMetricOutputAllowed = false
            return
        }
        updateRuntimeMetricOutputGate(
            frame = frame,
            snapshot = snapshot,
            observedAtElapsedRealtimeMs = elapsedRealtimeMs,
            expectedArSessionGeneration = arLease.generation,
            expectedWalkEpoch = walkEpoch,
        )
        synchronized(frameStateLock) {
            if (!isCurrentFrameGeneration(frameGeneration, walkEpoch)) return
            // Repeated frames still pass the elapsed-time loss gate above, but cannot renew evidence.
            if (frame.timestamp <= lastRuntimeCameraFrameId) return
            lastRuntimeCameraFrameId = frame.timestamp
        }
        val expectedFps = arLease.session.cameraConfig.fpsRange.lower
        runtimeCameraFrameBudgetMs = expectedFps.takeIf { it > 0 }?.let { kotlin.math.ceil(1000.0 / it).toLong() }
        runtimeLoadFrameScope = RuntimeFeatureScope.CAMERA_TRACKING_METRIC_DEPTH
        runtimeLoadNormalFrameAtMs = if (runtimeMetricOutputAllowed && frame.camera.trackingState == TrackingState.TRACKING)
            SystemClock.elapsedRealtime() else null
        observeRuntimeInferenceLoad(inputObserved = true)
        val grayFrame = captureVisualTrackingFrame(
            provider, frame, snapshot, elapsedRealtimeMs, frameGeneration, walkEpoch, arLease.generation,
        )
        scheduleUnknownDetectionIfDue(
            provider, frame, snapshot, elapsedRealtimeMs, frameGeneration, walkEpoch, arLease,
        )
        scheduleDetectionIfDue(
            provider,
            frame,
            timestampMs,
            nowMs,
            elapsedRealtimeMs,
            snapshot,
            frameGeneration,
            walkEpoch,
            arLease.generation,
            grayFrame?.key,
        )
        val currentFrameTracking = frame.camera.trackingState == TrackingState.TRACKING
        if (!currentRuntimeVisualDepthProcessingAllowsWork(arLease, frame.timestamp, currentFrameTracking)) {
            if (cameraScreenVisible && elapsedRealtimeMs - lastCameraScreenFrameUiMs >= 250L) {
                lastCameraScreenFrameUiMs = elapsedRealtimeMs
                val observed = latestDetectionSnapshot
                val sourceAt = observed.capturedAtElapsedRealtimeMs
                val fresh = sourceAt != null && elapsedRealtimeMs - sourceAt in 0L..MAX_OVERLAY_DETECTION_SOURCE_AGE_MS
                val boxes = buildDebugOverlayBoxes(frame,
                    if (fresh) observed.detections else emptyList(), null,
                    grayFrame?.sourceWidth, grayFrame?.sourceHeight)
                val message = "ARCore ${frame.camera.trackingState}\n${snapshot.statusTextForNoDetection()}\n" +
                    observed.debugStatusText(nowMs, timestampMs,
                        MAX_OVERLAY_DETECTION_SOURCE_AGE_MS, MAX_OVERLAY_DETECTION_FRAME_DELTA_MS)
                val displayFrameId = observed.frameEvidence?.frameId ?: frame.timestamp
                runOnUiThread {
                    if (cameraScreenVisible && isArSessionLeaseCurrent(arLease)) {
                        cameraScreenStatus.text = message
                        if (fresh && sourceAt != null) debugBboxOverlay.updateMapped(
                            boxes, displayFrameId, sourceAt,
                            sourceComplete = true, animate = false)
                        else debugBboxOverlay.clear()
                    }
                }
            }
            return
        }
        val detectionSnapshot = latestDetectionSnapshot
        val overlaySelection = synchronized(frameStateLock) {
            if (!isCurrentFrameGeneration(frameGeneration, walkEpoch)) return
            selectOverlayDetections(detectionSnapshot, nowMs, timestampMs)
        }
        val frozenPreparedFrame = if (currentRuntimeMetricOutputAllowsWork(arLease.generation)) this.prepareTactileFrameDispatch(
            detectionSnapshot = detectionSnapshot,
            nowMs = nowMs,
            currentFrameTimestampMs = timestampMs,
            maxDetectionSourceAgeMs = MAX_DEPTH_DETECTION_SOURCE_AGE_MS,
            maxDetectionFrameDeltaMs = MAX_DEPTH_DETECTION_FRAME_DELTA_MS,
            detectionAgeMs = detectionSnapshot.sourceAgeMs(nowMs),
            coordinator = frozenReportFrameCoordinator,
        ) { evidence, depthDetections ->
            synchronized(frameStateLock) {
                if (!isCurrentFrameGeneration(frameGeneration, walkEpoch)) {
                    emptyList()
                } else {
                    objectDepthPipeline.process(
                        snapshot = evidence.depthSnapshot,
                        frameId = evidence.frameId,
                        timestampMs = evidence.frameTimestampMs,
                        detections = depthDetections,
                        detectionSequenceId = evidence.frameId,
                        detectionCompleted = true,
                        mapper = requireNotNull(evidence.depthMapper),
                        motionContext = evidence.motionContext,
                        imageQuarterTurns = evidence.imageQuarterTurns,
                    )
                }
            }
        } else null
        val frozenReportOutputs = frozenPreparedFrame?.frame?.guidance?.outputs.orEmpty()
        val trackingPriority = PrimaryTrackingPriorityPolicy.sourceIndices(
            detectionSnapshot.detections, frozenReportOutputs,
            detectionSnapshot.frameEvidence?.frameId ?: 0L, detectionSnapshot.sourceAgeMs(nowMs))
        val trackingProcessingStartedMs = SystemClock.elapsedRealtime()
        val trackingResult = synchronized(frameStateLock) {
            val sourceKey = detectionSnapshot.frameEvidence?.visualFrameKey
            if (!isCurrentFrameGeneration(frameGeneration, walkEpoch)) return
            if (grayFrame == null || sourceKey == null || detectionSnapshot.partial) null
            else visualFrameTracker.trackFrom(
                sourceKey, detectionSnapshot.detections, grayFrame.key, completed = true,
                observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                executionBudgetNs = currentVisualTrackingBudgetNs,
                uprightQuarterTurns = detectionSnapshot.frameEvidence?.imageQuarterTurns ?: 0,
                prioritySourceIndices = trackingPriority,
            )
        }
        runtimeLoadObservationSource.recordFrame(
            cameraTimestampNs = snapshot.cameraImageTimestampNs ?: frame.timestamp,
            observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
            depthProcessingMs = depthProcessingMs,
            trackingProcessingMs = if (grayFrame != null) SystemClock.elapsedRealtime() - trackingProcessingStartedMs else null,
            trackingBudgetMs = kotlin.math.ceil(currentVisualTrackingBudgetNs / 1_000_000.0).toLong(),
            environmentKey = runtimeLoadEnvironmentKey(),
        )
        val currentEvidence = if (grayFrame != null && trackingResult != null) {
            val currentViewBasis = FloatArray(6)
            frame.transformCoordinates2d(Coordinates2d.IMAGE_NORMALIZED,
                floatArrayOf(0f, 0f, 1f, 0f, 0f, 1f), Coordinates2d.VIEW, currentViewBasis)
            DetectionFrameEvidence(
                frameId = frame.timestamp,
                frameTimestampMs = timestampMs,
                depthSnapshot = snapshot,
                depthMapper = createFrozenDepthMapper(
                    frame, frame.timestamp, grayFrame.sourceWidth, grayFrame.sourceHeight, snapshot,
                    allowMissingDepth = true,
                ),
                tactileContext = buildTactileProjectionContext(frame, elapsedRealtimeMs),
                motionContext = buildDepthMotionContext(elapsedRealtimeMs),
                navigationActive = isRouteActive && !routeRequestInFlight.get(),
                tmapOnRoute = latestTmapOnRoute,
                visualFrameKey = grayFrame.key,
                imageQuarterTurns = UprightCameraImage.quarterTurns(currentViewBasis),
            )
        } else null
        val currentObservation = if (trackingResult != null && currentEvidence != null) {
            CurrentTrackedFrameEvidence.fromTrackingResult(
                detectionSnapshot, trackingResult, currentEvidence, SystemClock.elapsedRealtime(),
            )
        } else null
        val overlayDetections = currentObservation?.observation?.trackedObservations.orEmpty().mapNotNull { it.geometry }
        var overlayDebugState = overlaySelection.debugState.copy(
            selection = "current_visual_observation",
            detectionCount = overlayDetections.size,
            holdApplied = false,
        )
        latestVisualTrackingStatus = trackingResult?.let { result ->
            "visual=${overlayDetections.size}/${result.observations.size} " +
                "cost=${result.metrics.durationNs / 1_000_000L}ms " +
                "budget=${result.metrics.executionBudgetNs / 1_000_000L}ms overrun=${result.metrics.executionBudgetOverrun} " +
                "lost=${result.observations.mapNotNull { it.failure }.distinct().joinToString()}"
        } ?: "visual=source_or_current_image_unavailable"
        if (!currentRuntimeVisualDepthProcessingAllowsWork(arLease, frame.timestamp, currentFrameTracking)) return
        val currentFrame = tactileFrameCoordinator.processTrackedObservation(
            frame = currentObservation,
            nowElapsedRealtimeMs = SystemClock.elapsedRealtime(),
            navigationActiveNow = isRouteActive && !routeRequestInFlight.get(),
            tmapOnRouteNow = latestTmapOnRoute,
            activeRouteId = routeNavigator.currentRouteId(),
        ) { observation, evidence ->
            synchronized(frameStateLock) {
                if (!isCurrentFrameGeneration(frameGeneration, walkEpoch) ||
                    !currentRuntimeVisualDepthProcessingAllowsWork(arLease, frame.timestamp, currentFrameTracking)) emptyList()
                else currentObjectDepthPipeline.processTrackedObservation(
                    snapshot = evidence.depthSnapshot,
                    observation = observation,
                    mapper = requireNotNull(evidence.depthMapper),
                    mapperFrameId = evidence.depthMapper.frameId,
                    nowElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                    motionContext = evidence.motionContext,
                    imageQuarterTurns = evidence.imageQuarterTurns,
                )
            }
        }
        val preparedTactileFrame = ProductionPreparedTactileFrameDispatch(currentFrame)
        val tactileFrame = preparedTactileFrame.frame
        synchronized(frameStateLock) {
            if (!isCurrentFrameGeneration(frameGeneration, walkEpoch)) return
            latestTactileRouteState =
                "localRoute=${tactileFrame.guidance.decision.mode.wireValue}:${tactileFrame.guidance.decision.reason}"
        }
        val matchedEvidence = tactileFrame.matchedEvidence
        val depthDetections = tactileFrame.depthDetections
        val depthMapper = matchedEvidence?.depthMapper
        val depthInputDetections = if (depthMapper == null) emptyList() else depthDetections
        val guidanceOutputs = tactileFrame.guidance.outputs
        val bestOutput = AndroidRiskSelectionPolicy.selectBestOutput(guidanceOutputs)
        val currentCapturedAtElapsedMs = grayFrame?.key?.capturedAtElapsedRealtimeMs
        val reportOutput = AndroidRiskSelectionPolicy.selectReportOutput(frozenReportOutputs)
        val automaticReportOutput = AndroidRiskSelectionPolicy.selectAutomaticReportOutput(frozenReportOutputs)
        val independentFeedbackBatches = freshUnknownFeedbackBatches(SystemClock.elapsedRealtime())
        val prioritizedFeedbackOutputs = AndroidRiskSelectionPolicy.prioritizedFeedbackOutputs(
            guidanceOutputs + independentFeedbackBatches.flatMap { it.outputs },
        )
        val feedbackGateOutput = prioritizedFeedbackOutputs.firstOrNull { output ->
            output.source.metric && output.confidence.finalScore >= FEEDBACK_MIN_DEPTH_CONFIDENCE
        }
        val shouldUpdateOverlay = synchronized(frameStateLock) {
            if (!isCurrentFrameGeneration(frameGeneration, walkEpoch)) return
            currentObservation != null ||
                elapsedRealtimeMs - lastOverlayUpdateMs >= OVERLAY_UPDATE_INTERVAL_MS || overlayDetections.isEmpty()
        }
        if (shouldUpdateOverlay) {
            val mappedViewportWidth = surfaceWidth
            val mappedViewportHeight = surfaceHeight
            val overlayBoxes = buildDebugOverlayBoxes(
                frame, overlayDetections,
                bestOutput?.takeIf { it.frameId == grayFrame?.key?.frameId },
                grayFrame?.sourceWidth, grayFrame?.sourceHeight,
            )
            val overlayPrediction = bestOutput?.takeIf { it.frameId == grayFrame?.key?.frameId }?.prediction
            val unpredictedOverlayBoxes = if (overlayPrediction == null) overlayBoxes else buildDebugOverlayBoxes(
                frame, overlayDetections, bestOutput?.copy(prediction = null),
                grayFrame?.sourceWidth, grayFrame?.sourceHeight,
            )
            synchronized(frameStateLock) {
                if (!isCurrentFrameGeneration(frameGeneration, walkEpoch)) return
                lastOverlayUpdateMs = elapsedRealtimeMs
            }
            overlayDebugState = overlayDebugState.copy(boxCount = overlayBoxes.size)
            val sourceFrameId = grayFrame?.key?.frameId
            val sourceCapturedAt = detectionSnapshot.capturedAtElapsedRealtimeMs
            synchronized(frameStateLock) { latestVisualOverlayFrameId = sourceFrameId ?: 0L }
            runOnUiThread {
                if (isCurrentFrameGeneration(frameGeneration, walkEpoch) && isArSessionLeaseCurrent(arLease)) {
                    if (debugBboxOverlay.width != mappedViewportWidth || debugBboxOverlay.height != mappedViewportHeight) {
                        return@runOnUiThread
                    }
                    if (synchronized(frameStateLock) { latestVisualOverlayFrameId != (sourceFrameId ?: 0L) }) return@runOnUiThread
                    if (sourceFrameId == null || sourceCapturedAt == null) {
                        debugBboxOverlay.clear()
                    } else {
                        val predictionRemainingMs = predictionDisplayRemainingMs(
                            overlayPrediction, currentCapturedAtElapsedMs, SystemClock.elapsedRealtime(),
                        )?.takeIf {
                            currentRuntimeVisualDepthProcessingAllowsWork(arLease, frame.timestamp, currentFrameTracking)
                        }
                        debugBboxOverlay.updateMapped(
                            if (predictionRemainingMs != null) overlayBoxes else unpredictedOverlayBoxes,
                            sourceFrameId, sourceCapturedAt,
                            sourceComplete = true,
                            animate = false,
                        )
                        if (predictionRemainingMs != null) debugBboxOverlay.postDelayed({
                            if (isCurrentFrameGeneration(frameGeneration, walkEpoch) && isArSessionLeaseCurrent(arLease) &&
                                synchronized(frameStateLock) { latestVisualOverlayFrameId == sourceFrameId }
                            ) debugBboxOverlay.updateMapped(
                                unpredictedOverlayBoxes, sourceFrameId, sourceCapturedAt,
                                sourceComplete = true, animate = false,
                            )
                        }, predictionRemainingMs + 1L)
                    }
                }
            }
        }
        if (!isCurrentFrameGeneration(frameGeneration, walkEpoch)) return
        if (!currentRuntimeMetricOutputAllowsWork(arLease.generation)) {
            if (cameraScreenVisible && elapsedRealtimeMs - lastCameraScreenFrameUiMs >= 250L) {
                lastCameraScreenFrameUiMs = elapsedRealtimeMs
                var renderedGapStatus: String? = null
                fun renderGapStatus() {
                    if (cameraScreenVisible && isCurrentFrameGeneration(frameGeneration, walkEpoch) &&
                        isArSessionLeaseCurrent(arLease) && lastCameraScreenFrameUiMs == elapsedRealtimeMs &&
                        currentCapturedAtElapsedMs != null
                    ) {
                        if (renderedGapStatus != null && cameraScreenStatus.text.toString() != renderedGapStatus) return
                        val displayAtMs = SystemClock.elapsedRealtime()
                        val metricRecovered = currentRuntimeMetricOutputAllowsWork(arLease.generation)
                        val predictions = if (metricRecovered || !currentRuntimeVisualDepthProcessingAllowsWork(
                            arLease, frame.timestamp, currentFrameTracking,
                        )) emptyList() else guidanceOutputs.mapNotNull { output ->
                            val predicted = output.prediction ?: return@mapNotNull null
                            val remaining = predictionDisplayRemainingMs(predicted, currentCapturedAtElapsedMs, displayAtMs)
                                ?: return@mapNotNull null
                            remaining to String.format(Locale.US, "%s · 예측 %.2fm ±%.2fm · 공백 %dms",
                                output.className, predicted.distanceM, predicted.errorBoundM, predicted.horizonMs - remaining)
                        }.take(3)
                        val status = (if (metricRecovered) "Depth 재수신 · 거리 갱신 대기\n" else
                            "Depth 일시 공백 · 현재 추적 ${overlayDetections.size}개\n") +
                            predictions.joinToString("\n") { it.second }.ifEmpty { "예측 근거 부족 · 거리 확인 대기" } +
                            "\n$latestVisualTrackingStatus\n$unknownRuntimeStatus"
                        cameraScreenStatus.text = status
                        renderedGapStatus = status
                        predictions.minOfOrNull { it.first }?.let { remaining ->
                            cameraScreenStatus.postDelayed({ renderGapStatus() }, remaining + 1L)
                        }
                    }
                }
                runOnUiThread { renderGapStatus() }
            }
            return
        }
        val captureLogEntry = buildCaptureLogEntry(
            frameTimestampMs = timestampMs,
            nowMs = nowMs,
            detectionSnapshot = detectionSnapshot,
            overlayDebugState = overlayDebugState,
            detectionsUsedForDepth = depthInputDetections,
            snapshot = matchedEvidence?.depthSnapshot ?: snapshot,
            bestOutput = bestOutput,
            depthTransformPath = if (depthMapper == null) "unavailable" else "current_visual_image_to_texture_normalized",
            depthFallbackReason = when {
                matchedEvidence == null -> "matched_detection_frame_evidence_unavailable"
                depthMapper == null -> "frozen_depth_mapper_unavailable"
                depthDetections.isNotEmpty() && depthInputDetections.isEmpty() -> "depth_input_suppressed"
                else -> null
            },
        )
        synchronized(frameStateLock) {
            if (
                !isCurrentFrameGeneration(frameGeneration, walkEpoch) ||
                !currentRuntimeMetricOutputAllowsWork(arLease.generation)
            ) return
            captureLog.append(captureLogEntry)
            runIfActivityOriginalUploadAllowed {
                if (metadataLogUploader.isEnabled()) {
                    metadataLogUploader.enqueue(captureLogEntry)
                }
            }
        }
        val deviceGateState = buildDeviceGateState(
            bestOutput = feedbackGateOutput,
            staleReason = if (independentFeedbackBatches.isNotEmpty()) null else captureLogEntry.staleReason,
            expectedRuntimeMetricGeneration = arLease.generation,
        )
        val reportGateState = buildDeviceGateState(
            bestOutput = automaticReportOutput,
            staleReason = captureLogEntry.staleReason,
            expectedRuntimeMetricGeneration = arLease.generation,
        )
        val explicitReportGateState = buildDeviceGateState(
            bestOutput = reportOutput,
            staleReason = captureLogEntry.staleReason,
            expectedRuntimeMetricGeneration = arLease.generation,
        )
        val freshLocation = freshTrustedLocationOrNull()
        val locationAgeMs = freshLocation?.let { trusted ->
            (SystemClock.elapsedRealtime() - trusted.elapsedRealtimeMs).coerceAtLeast(0L)
        }
        synchronized(frameStateLock) {
            if (
                !isCurrentFrameGeneration(frameGeneration, walkEpoch) ||
                !currentRuntimeMetricOutputAllowsWork(arLease.generation)
            ) return
            fieldSessionLog.appendTelemetry(
                entry = captureLogEntry,
                runtime = FieldRuntimeSnapshot(
                    stepCount = latestStepCount,
                    stepLengthM = stepLengthEstimator.stepLengthM,
                    routeActive = isRouteActive,
                    navigationState = latestNavigationState,
                    deviceGateAllowsAlerts = deviceGateState.alertsAllowed,
                    deviceGateAllowsReports = reportGateState.reportCandidatesAllowed,
                    reportCandidateState = latestReportCandidateStatus,
                    trustedLocationAvailable = freshLocation != null,
                    locationAccuracyM = freshLocation?.accuracyM,
                    locationAgeMs = locationAgeMs,
                    headingDeg = latestHeadingDeg,
                ),
            )
        }
        if (
            !publishCurrentFrameReportState(
                frameGeneration = frameGeneration,
                expectedRuntimeMetricGeneration = arLease.generation,
                automaticReportOutput = automaticReportOutput,
                reportGateState = reportGateState,
                explicitReportOutput = reportOutput,
                explicitReportGateState = explicitReportGateState,
                reportImage = detectionSnapshot.reportImage,
                nowMs = nowMs,
                capturedAtMs = detectionSnapshot.capturedAtMs ?: nowMs,
                expectedWalkEpoch = walkEpoch,
            )
        ) return
        if (!currentRuntimeMetricOutputAllowsWork(arLease.generation)) return
        dispatchTactileFrameFeedback(
            frame = tactileFrame,
            stale = captureLogEntry.staleReason != null,
            deviceGateAllowsAlerts = deviceGateState.alertsAllowed,
            nowMs = SystemClock.elapsedRealtime(),
            independentFreshOutputs = freshUnknownFeedbackBatches(SystemClock.elapsedRealtime()),
            warningContext = grayFrame?.let { current ->
                kr.co.hanium.dreamup.walksafe.navigation.WarningRegionContext(
                    epoch = walkEpoch,
                    geometryId = "${arLease.generation}:${current.key.geometryVersion}:${current.sourceWidth}x${current.sourceHeight}",
                    detectorGeneration = frameGeneration,
                )
            },
        )
        val shouldUpdateUi = synchronized(frameStateLock) {
            if (!isCurrentFrameGeneration(frameGeneration, walkEpoch)) return
            if (elapsedRealtimeMs - lastUiUpdateMs < UI_UPDATE_INTERVAL_MS) {
                false
            } else {
                lastUiUpdateMs = elapsedRealtimeMs
                true
            }
        }
        if (!shouldUpdateUi) return

        runOnUiThread {
            if (!isCurrentFrameGeneration(frameGeneration, walkEpoch)) return@runOnUiThread
            val gateText = deviceGateState.statusText()
            if (bestOutput == null) {
                updateStatus(
                    status = if (depthSupported) "카메라/Depth 수신 중" else "Depth 미지원 fallback 대기",
                    detail = "${snapshot.statusTextForNoDetection()}\n" +
                        "${detectionSnapshot.debugStatusText(nowMs, timestampMs, MAX_OVERLAY_DETECTION_SOURCE_AGE_MS, MAX_OVERLAY_DETECTION_FRAME_DELTA_MS)}\n" +
                        "$gateText · $latestTactileRouteState · ${feedbackActuatorStatusText()} · $latestReportCandidateStatus · steps=$latestStepCount stepLength=${meters(stepLengthEstimator.stepLengthM)}\n" +
                        "${currentUserMotionStatusText()}\n" +
                        "${adaptiveInferencePacingStatusText()}\n${latestVisualTrackingStatus}\n" +
                        "$detectorStatusText\n$unknownRuntimeStatus\n" +
                        "${metadataLogUploader.statusText()}\n" +
                        captureLog.summaryText(),
                )
            } else {
                updateStatus(
                    status = "객체별 depth 수신 중",
                    detail = "${bestOutput.debugSummaryText()}\n" +
                        "${detectionSnapshot.debugStatusText(nowMs, timestampMs, MAX_OVERLAY_DETECTION_SOURCE_AGE_MS, MAX_OVERLAY_DETECTION_FRAME_DELTA_MS)}\n" +
                        "${bestOutput.debugGeometryText()}\n" +
                        "$gateText · $latestTactileRouteState · ${feedbackActuatorStatusText()} · $latestReportCandidateStatus · steps=$latestStepCount stepLength=${meters(stepLengthEstimator.stepLengthM)}\n" +
                        "${currentUserMotionStatusText()}\n" +
                        "${adaptiveInferencePacingStatusText()}\n${latestVisualTrackingStatus}\n" +
                        "$detectorStatusText\n$unknownRuntimeStatus\n" +
                        "${metadataLogUploader.statusText()}\n" +
                        captureLog.summaryText(),
                )
            }
            updateDebugUploadButton()
        }
    }

    private fun handleRuntimeMetricPreflightFrame(
        frame: Frame,
        snapshot: DepthFrameSnapshot,
        observedAtElapsedRealtimeMs: Long,
        expectedArSessionGeneration: Long,
        expectedWalkEpoch: WalkRuntimeEpoch,
    ) {
        val evaluator = runtimeMetricPreflightSession ?: return
        if (
            arSessionPurpose != ArSessionPurpose.PREFLIGHT ||
            arSessionGeneration != expectedArSessionGeneration ||
            evaluator.generation != runtimeMetricPreflightGeneration ||
            walkSessionLifecycle.snapshot().epoch != expectedWalkEpoch
        ) {
            return
        }
        val validSamples = snapshot.runtimeMetricValidSampleCount(requireFreshRaw = true)
        frameProvider?.recordPreflightSamples(validSamples)
        val result = evaluator.observe(
            RuntimeMetricFrameEvidence(
                generation = evaluator.generation,
                frameTimestampNanos = frame.timestamp,
                observedAtElapsedRealtimeMs = observedAtElapsedRealtimeMs,
                tracking = frame.camera.trackingState == TrackingState.TRACKING,
                metricDepthAvailable = snapshot.hasFreshMetricRawDepth || snapshot.hasFreshFullDepth,
                validMetricSamplesInRange = validSamples,
            ),
        )
        if (
            result.status != RuntimeMetricPreflightStatus.IN_PROGRESS &&
            metricPreflightTerminalDispatchedGeneration != result.generation
        ) {
            metricPreflightTerminalDispatchedGeneration = result.generation
            val lifecycleGeneration = metricPreflightLifecycleGeneration
            runOnUiThread {
                finishRuntimeMetricPreflight(
                    result,
                    expectedArSessionGeneration = expectedArSessionGeneration,
                    expectedLifecycleGeneration = lifecycleGeneration,
                )
            }
        }
    }

    private fun handleRuntimeMetricFrameFailure(
        status: String,
        detail: String,
        expectedPurpose: ArSessionPurpose,
        expectedArSessionGeneration: Long,
        expectedWalkEpoch: WalkRuntimeEpoch,
    ) {
        if (
            arSessionPurpose != expectedPurpose ||
            arSessionGeneration != expectedArSessionGeneration ||
            walkSessionLifecycle.snapshot().epoch != expectedWalkEpoch
        ) return
        runtimeMetricOutputAllowed = false
        runtimeVisualDepthFrameTracking = false
        if (
            expectedPurpose == ArSessionPurpose.RUNTIME &&
            firstRunOnboardingComplete()
        ) {
            observeOfficialEnvironmentCameraFrame(
                epoch = expectedWalkEpoch,
                observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                frameAvailable = false,
            )
        }
        val expectedLifecycleGeneration = metricPreflightLifecycleGeneration
        when (expectedPurpose) {
            ArSessionPurpose.PREFLIGHT -> {
                val active = runtimeMetricPreflightSession ?: return
                val result = active.failTransiently(SystemClock.elapsedRealtime())
                if (metricPreflightTerminalDispatchedGeneration == result.generation) return
                metricPreflightTerminalDispatchedGeneration = result.generation
                runOnUiThread {
                    finishRuntimeMetricPreflight(
                        result,
                        expectedArSessionGeneration = expectedArSessionGeneration,
                        expectedLifecycleGeneration = expectedLifecycleGeneration,
                    )
                }
            }
            ArSessionPurpose.RUNTIME -> runOnUiThread {
                handleRuntimeMetricLoss(expectedArSessionGeneration)
            }
            ArSessionPurpose.NONE -> runOnUiThread { updateStatus(status, detail) }
        }
    }

    private fun isArSessionLeaseCurrent(lease: ArSessionLease): Boolean =
        synchronized(runtimeMetricStateLock) {
            session === lease.session &&
                frameProvider === lease.provider &&
                arSessionPurpose == lease.purpose &&
                arSessionGeneration == lease.generation
        }

    private fun currentRuntimeMetricOutputAllowsWork(expectedGeneration: Long? = null): Boolean =
        synchronized(runtimeMetricStateLock) {
            firstRunOnboardingComplete() &&
                isWalkSessionRuntimeActive() &&
                isActivityForeground &&
                cameraEnvironmentOutputsAllowed() &&
                phoneMountingOutputsAllowed &&
                arSessionPurpose == ArSessionPurpose.RUNTIME &&
                (expectedGeneration == null || arSessionGeneration == expectedGeneration) &&
                session != null &&
                frameProvider != null &&
                runtimeMetricOutputAllowed &&
                startupCapabilityDecision?.allowsMetricDistance() == true &&
                isStartupCapabilityConfirmed()
        }

    /** Allows only current visual observations through a short depth gap, never metric consumers. */
    private fun currentRuntimeVisualDepthProcessingAllowsWork(
        lease: ArSessionLease,
        frameTimestampNanos: Long,
        tracking: Boolean,
    ): Boolean = synchronized(runtimeMetricStateLock) {
        if (!tracking || frameTimestampNanos <= 0L ||
            frameTimestampNanos != runtimeMetricLastFrameTimestampNanos || !isArSessionLeaseCurrent(lease)
        ) return@synchronized false
        if (currentRuntimeMetricOutputAllowsWork(lease.generation)) return@synchronized true
        firstRunOnboardingComplete() &&
            isWalkSessionRuntimeActive() &&
            isActivityForeground &&
            cameraEnvironmentOutputsAllowed() &&
            phoneMountingOutputsAllowed &&
            arSessionPurpose == ArSessionPurpose.RUNTIME &&
            session != null && frameProvider != null &&
            runtimeMetricActivationSession == null &&
            startupCapabilityDecision?.allowsMetricDistance() == true &&
            isStartupCapabilityConfirmed() &&
            allowsRuntimeDepthGapProcessing(
                frameTimestampNanos = frameTimestampNanos,
                latestFrameTimestampNanos = runtimeMetricLastFrameTimestampNanos,
                observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                lastValidFrameAtElapsedRealtimeMs = runtimeMetricLastValidFrameAtMs,
                tracking = tracking,
            )
    }

    /** Prediction age uses camera time; only its remaining duration crosses to elapsed UI time. */
    private fun predictionDisplayRemainingMs(
        prediction: PredictedDepthEstimate?,
        capturedAtElapsedRealtimeMs: Long?,
        displayAtElapsedRealtimeMs: Long,
    ): Long? {
        val predicted = prediction ?: return null
        val capturedAtMs = capturedAtElapsedRealtimeMs ?: return null
        if (!DepthPredictionPresentation.isCurrent(predicted, capturedAtMs, displayAtElapsedRealtimeMs)) return null
        return DepthPredictionPresentation.validUntilMs(predicted, capturedAtMs)?.minus(displayAtElapsedRealtimeMs)
    }

    private fun updateRuntimeMetricOutputGate(
        frame: Frame,
        snapshot: DepthFrameSnapshot,
        observedAtElapsedRealtimeMs: Long,
        expectedArSessionGeneration: Long,
        expectedWalkEpoch: WalkRuntimeEpoch,
    ) {
        val activation = synchronized(runtimeMetricStateLock) {
            if (
                !isWalkSessionRuntimeActive() ||
                !walkSessionLifecycle.isRuntimeEpochCurrent(expectedWalkEpoch) ||
                startupCapabilityDecision?.allowsMetricDistance() != true ||
                arSessionPurpose != ArSessionPurpose.RUNTIME ||
                arSessionGeneration != expectedArSessionGeneration ||
                !isActivityForeground ||
                !isStartupCapabilityConfirmed()
            ) {
                runtimeMetricOutputAllowed = false
                runtimeVisualDepthFrameTracking = false
                return
            }
            runtimeMetricActivationSession
        }
        val validSamples = snapshot.runtimeMetricValidSampleCount()
        val frameEvidence = RuntimeMetricFrameEvidence(
            generation = expectedArSessionGeneration,
            frameTimestampNanos = frame.timestamp,
            observedAtElapsedRealtimeMs = observedAtElapsedRealtimeMs,
            tracking = frame.camera.trackingState == TrackingState.TRACKING,
            metricDepthAvailable = snapshot.hasMetricRawDepth || snapshot.hasFreshFullDepth,
            validMetricSamplesInRange = validSamples,
        )
        if (activation != null) {
            val result = activation.observe(frameEvidence)
            var activated = false
            var lost = false
            synchronized(runtimeMetricStateLock) {
                val stillCurrent =
                    isWalkSessionRuntimeActive() &&
                        arSessionPurpose == ArSessionPurpose.RUNTIME &&
                        arSessionGeneration == expectedArSessionGeneration &&
                        runtimeMetricActivationSession === activation &&
                        isActivityForeground &&
                        startupCapabilityDecision?.allowsMetricDistance() == true &&
                        isStartupCapabilityConfirmed()
                if (!stillCurrent) {
                    runtimeMetricOutputAllowed = false
                } else if (result.status == RuntimeMetricPreflightStatus.AVAILABLE) {
                    runtimeMetricOutputAllowed = frameEvidence.tracking &&
                        frameEvidence.metricDepthAvailable &&
                        frameEvidence.validMetricSamplesInRange >=
                        RuntimeMetricPreflightPolicy.MIN_VALID_SAMPLES_PER_PASSING_FRAME
                    runtimeMetricActivationSession = null
                    runtimeMetricLastFrameTimestampNanos = frame.timestamp
                    if (runtimeMetricOutputAllowed) {
                        runtimeMetricLastValidFrameAtMs = observedAtElapsedRealtimeMs
                        activated = runtimeMetricInitialNavigationStartPending
                    }
                    runtimeVisualDepthFrameTracking = frameEvidence.tracking && runtimeMetricOutputAllowed
                } else {
                    runtimeMetricOutputAllowed = false
                    lost = result.status == RuntimeMetricPreflightStatus.UNKNOWN
                }
            }
            if (activated) {
                runOnUiThread {
                    startInitialNavigationServicesIfCurrent(expectedArSessionGeneration)
                }
            } else if (lost) {
                runOnUiThread { handleRuntimeMetricLoss(expectedArSessionGeneration) }
            }
            return
        }

        val samplesAreValid = frameEvidence.tracking &&
            frameEvidence.metricDepthAvailable &&
            frameEvidence.validMetricSamplesInRange >=
            RuntimeMetricPreflightPolicy.MIN_VALID_SAMPLES_PER_PASSING_FRAME
        var shouldHandleLoss = false
        var shouldStartNavigation = false
        synchronized(runtimeMetricStateLock) {
            val stillCurrent =
                arSessionPurpose == ArSessionPurpose.RUNTIME &&
                    arSessionGeneration == expectedArSessionGeneration &&
                    runtimeMetricActivationSession == null &&
                    isActivityForeground &&
                    startupCapabilityDecision?.allowsMetricDistance() == true &&
                    isStartupCapabilityConfirmed()
            if (!stillCurrent) {
                runtimeMetricOutputAllowed = false
                runtimeVisualDepthFrameTracking = false
                return
            }
            val assessment = assessRuntimeDepthFrame(
                frameTimestampNanos = frame.timestamp,
                previousFrameTimestampNanos = runtimeMetricLastFrameTimestampNanos,
                observedAtElapsedRealtimeMs = observedAtElapsedRealtimeMs,
                lastValidFrameAtElapsedRealtimeMs = runtimeMetricLastValidFrameAtMs,
                samplesAreValid = samplesAreValid,
                staleTimeoutMs = RUNTIME_METRIC_STALE_TIMEOUT_MS,
            )
            if (assessment.isNewFrame) {
                runtimeMetricLastFrameTimestampNanos = frame.timestamp
            }
            shouldStartNavigation = assessment.outputAllowed && runtimeMetricInitialNavigationStartPending
            runtimeMetricOutputAllowed = assessment.outputAllowed
            runtimeVisualDepthFrameTracking = frameEvidence.tracking && frame.timestamp > 0L &&
                frame.timestamp == runtimeMetricLastFrameTimestampNanos
            if (assessment.refreshesLastValidTime) {
                runtimeMetricLastValidFrameAtMs = observedAtElapsedRealtimeMs
            }
            shouldHandleLoss = assessment.shouldHandleLoss
        }
        if (!runtimeMetricOutputAllowed) clearExplicitReportFrameState("runtime_metric_frame_invalid")
        if (shouldStartNavigation) {
            runOnUiThread {
                startInitialNavigationServicesIfCurrent(expectedArSessionGeneration)
            }
        }
        if (shouldHandleLoss) {
            runOnUiThread { handleRuntimeMetricLoss(expectedArSessionGeneration) }
        }
    }

    private fun startInitialNavigationServicesIfCurrent(expectedArSessionGeneration: Long) {
        synchronized(runtimeMetricStateLock) {
            if (
                !runtimeMetricInitialNavigationStartPending ||
                !currentRuntimeMetricOutputAllowsWork(expectedArSessionGeneration)
            ) return
            startNavigationServicesIfNeeded()
            runtimeMetricInitialNavigationStartPending = false
        }
    }

    private fun handleRuntimeMetricLoss(expectedArSessionGeneration: Long) {
        if (
            arSessionPurpose != ArSessionPurpose.RUNTIME ||
            arSessionGeneration != expectedArSessionGeneration ||
            startupCapabilityDecision?.allowsMetricDistance() != true
        ) {
            return
        }
        val availability = runCatching {
            ArCoreApk.getInstance().checkAvailability(this)
        }.getOrDefault(ArCoreApk.Availability.UNKNOWN_ERROR)
        stopDepthSession(closeSession = true)
        updateStatus(
            "미터 거리 기능 제한",
            "실제 거리 프레임을 더 이상 확인할 수 없어 미터 거리 안내만 제한했습니다. " +
                "현재 사용 가능한 다른 기능은 계속됩니다.",
        )
        requestCameraFallbackStart(CameraFallbackStartReason.RUNTIME_METRIC_LOST, availability)
    }

    private fun clearExplicitReportFrameState(reason: String) {
        synchronized(frameStateLock) {
            latestExplicitReportOutput = null
            latestExplicitReportImage = null
            latestExplicitReportGateState = null
            latestExplicitReportCapturedAtMs = 0L
            latestReportCandidateStatus = "reportCandidate=blocked:$reason"
        }
    }

    private fun DepthFrameSnapshot.runtimeMetricValidSampleCount(
        requireFreshRaw: Boolean = false,
    ): Int = validMetricSampleCount(
        minimumRawConfidence = RUNTIME_METRIC_MIN_RAW_CONFIDENCE,
        minimumDistanceMeters = RuntimeMetricPreflightPolicy.MIN_VALID_DISTANCE_METERS,
        maximumDistanceMeters = RuntimeMetricPreflightPolicy.MAX_VALID_DISTANCE_METERS,
        requireFreshRaw = requireFreshRaw,
    )

    private fun accessibilityTargetSizePx(): Int =
        (WS_TOUCH_MIN_DP * resources.displayMetrics.density).roundToInt()

    private fun applyAccessibleControlDefaults(root: View) {
        if (root is Button && root !is CompoundButton) {
            applyWsButtonStyle(root, WS_TOUCH_WALK_ACTION_DP)
        }
        if (root is EditText) applyWsFieldStyle(root)
        if (root is LinearLayout && root.orientation == LinearLayout.VERTICAL) {
            applyWsStackSpacing(root)
        }
        if (root is CompoundButton) {
            root.buttonTintList = ColorStateList(
                arrayOf(intArrayOf(android.R.attr.state_checked), intArrayOf()),
                intArrayOf(WS_COLOR_PRIMARY_ACTION_FILL, WS_COLOR_BUTTON_BORDER),
            )
            root.setTextColor(WS_COLOR_BUTTON_TEXT)
        }
        if (root is Button || root is EditText || root is CheckBox) {
            val targetSize = accessibilityTargetSizePx()
            root.minimumHeight = maxOf(root.minimumHeight, targetSize)
            root.minimumWidth = maxOf(root.minimumWidth, targetSize)
            val minimumTextSizePx = TypedValue.applyDimension(
                TypedValue.COMPLEX_UNIT_SP,
                MIN_INTERACTIVE_TEXT_SP,
                resources.displayMetrics,
            )
            if (root.textSize < minimumTextSizePx) {
                root.setTextSize(TypedValue.COMPLEX_UNIT_SP, MIN_INTERACTIVE_TEXT_SP)
            }
            root.importantForAccessibility = View.IMPORTANT_FOR_ACCESSIBILITY_YES
        }
        if (root is ViewGroup) {
            for (index in 0 until root.childCount) {
                applyAccessibleControlDefaults(root.getChildAt(index))
            }
        }
    }

    private fun applyWsStackSpacing(stack: LinearLayout) {
        if (stack.childCount < 2) return
        val children = (0 until stack.childCount).map(stack::getChildAt)
        val gap = (WS_GROUP_GAP_DP * resources.displayMetrics.density).roundToInt()
        children.dropLast(1).forEach { child ->
            (child.layoutParams as? LinearLayout.LayoutParams)?.let { params ->
                if (params.bottomMargin == 0) params.bottomMargin = gap
            }
        }
    }

    private fun applyWsSecondaryButtonStyle(button: Button) {
        applyWsButtonStyle(button, 144f)
    }

    private fun applyWsStatusText(view: TextView, message: String) {
        val lines = message.split("\n")
        val causeIndex = lines.indexOfFirst { it.startsWith("원인:") }
        val statusIndex = if (causeIndex > 0) causeIndex - 1 else -1
        val builder = SpannableStringBuilder()
        lines.forEachIndexed { index, line ->
            val start = builder.length
            builder.append(line)
            val end = builder.length
            val labelEnd = LABEL_PREFIXES.firstOrNull { line.startsWith(it) }?.length
            when {
                index == statusIndex -> {
                    builder.setSpan(
                        StyleSpan(Typeface.BOLD),
                        start,
                        end,
                        Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
                    )
                    builder.setSpan(
                        ForegroundColorSpan(
                            if (line in BLOCKING_STATUS_WORDS) {
                                WS_COLOR_WARNING
                            } else {
                                WS_COLOR_EMPHASIS
                            },
                        ),
                        start,
                        end,
                        Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
                    )
                    builder.setSpan(
                        RelativeSizeSpan(1.15f),
                        start,
                        end,
                        Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
                    )
                }
                labelEnd != null -> {
                    builder.setSpan(
                        StyleSpan(Typeface.BOLD),
                        start,
                        start + labelEnd,
                        Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
                    )
                    builder.setSpan(
                        ForegroundColorSpan(WS_COLOR_BUTTON_TEXT),
                        start + labelEnd,
                        end,
                        Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
                    )
                }
                else -> builder.setSpan(
                    RelativeSizeSpan(0.94f),
                    start,
                    end,
                    Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
                )
            }
            if (index != lines.lastIndex) builder.append("\n")
        }
        view.text = builder
    }

    /**
     * 팀원 시안의 홈 카드 패턴을 기존 기능에만 연결한다. 카드 안 텍스트는 장식으로
     * 제외하고 카드 하나가 제목, 설명, 잠김 이유를 한 번에 읽도록 한다.
     */
    private fun wsHomeCard(
        title: String,
        subtitle: String,
        lockTitle: String,
        lockDetail: String,
        unlocked: () -> Boolean,
        onOpen: () -> Unit,
    ): View {
        val card = Button(this).apply {
            text = title
            applyWsSecondaryButtonStyle(this)
            importantForAccessibility = View.IMPORTANT_FOR_ACCESSIBILITY_YES
            setOnClickListener { onOpen() }
        }
        homeCardRefreshers += {
            card.isEnabled = !isWalkSessionRuntimeActive() || unlocked()
            card.contentDescription = if (unlocked()) {
                "$title. $subtitle"
            } else {
                "$title. $subtitle. 잠김. $lockTitle. $lockDetail"
            }
        }
        return card
    }

    private fun wsHomeCardFace(
        fill: Int,
        density: Float,
        focused: Boolean = false,
    ): GradientDrawable = GradientDrawable().apply {
        shape = GradientDrawable.RECTANGLE
        cornerRadius = WS_CARD_CORNER_RADIUS_DP * density
        setColor(fill)
        if (focused) {
            setStroke((WS_CARD_FOCUS_RING_DP * density).roundToInt(), WS_COLOR_CARD_FOCUS)
        }
    }

    private fun showHomeCardLockNotice(title: String, detail: String) {
        speakInteraction("$title. $detail")
        AlertDialog.Builder(this)
            .setTitle(title)
            .setMessage(detail)
            .setPositiveButton("확인", null)
            .show()
            .getButton(AlertDialog.BUTTON_POSITIVE)
            .requestFocus()
    }

