    /**
     * 안전 고지는 목적·안전 확인 단계에서 확인 버튼보다 앞에 전문으로 보인다.
     * 확인 뒤에는 큰 글꼴에서 현재 행동을 가리지 않도록 카드를 숨기고, 정책 상수를
     * TalkBack 설명에 그대로 담은 펼침 버튼만 남긴다.
     */
    /**
     * 단계 문장 앞머리("첫 실행 N단계.")는 eyebrow 로 작고 흐리게, 나머지는 제목으로
     * 크고 굵게 보인다. 한 TextView 안에서 처리하므로 text 와 contentDescription 은
     * 전체 문장 그대로 남고 접근성 heading 계약이 유지된다.
     */
    private fun applyStageHeadingStyle(message: String) {
        if (!::firstRunOnboardingStatusText.isInitialized) return
        val separator = message.indexOf('.')
        if (separator <= 0 || separator + 1 >= message.length) {
            firstRunOnboardingStatusText.text = message
            return
        }
        val eyebrowEnd = separator + 1
        // 표시용으로만 줄을 나눈다. contentDescription 은 원문 그대로이므로 낭독은 변하지 않는다.
        val display = message.substring(0, eyebrowEnd) + "\n" +
            message.substring(eyebrowEnd).trimStart()
        val styled = SpannableString(display)
        styled.setSpan(
            RelativeSizeSpan(0.62f),
            0,
            eyebrowEnd,
            Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
        )
        styled.setSpan(
            ForegroundColorSpan(WS_COLOR_NOTICE_TEXT),
            0,
            eyebrowEnd,
            Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
        )
        styled.setSpan(
            StyleSpan(Typeface.BOLD),
            eyebrowEnd + 1,
            display.length,
            Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
        )
        firstRunOnboardingStatusText.text = styled
    }

    /**
     * 고지 카드 머리글. addView(productPurposeText) 가 오버레이에 직접 있어야 하는 계약
     * 때문에 별도 컨테이너로 감쌀 수 없어 같은 TextView 안에서 Spannable 로 처리한다.
     */
    private fun applyNoticeHeadingStyle(body: String) {
        if (!::productPurposeText.isInitialized) return
        val display = "$SAFETY_NOTICE_HEADING\n$body"
        val styled = SpannableString(display)
        val end = SAFETY_NOTICE_HEADING.length
        styled.setSpan(RelativeSizeSpan(0.78f), 0, end, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)
        styled.setSpan(StyleSpan(Typeface.BOLD), 0, end, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)
        styled.setSpan(
            ForegroundColorSpan(WS_COLOR_EMPHASIS),
            0,
            end,
            Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
        )
        productPurposeText.text = styled
        productPurposeText.contentDescription = display
    }

    private fun documentClauseOrNull(
        source: String,
        label: String,
        stops: List<String>,
    ): String? {
        val start = source.indexOf(label)
        if (start < 0) return null
        val rest = source.substring(start)
        val next = stops
            .mapNotNull { stop -> rest.indexOf(stop, label.length).takeIf { it > 0 } }
            .minOrNull()
        return if (next != null) rest.substring(0, next).trim() else rest.trim()
    }

    private fun applyWsClauseBox(view: TextView) {
        view.background = null
        view.setPadding(0, 0, 0, 0)
        view.textSize = 18f
        view.typeface = wsTypeface(Typeface.NORMAL)
        view.setTextColor(WS_COLOR_NOTICE_TEXT)
        view.setLineSpacing(0f, 1.65f)
        view.maxHeight = Int.MAX_VALUE
        view.isVerticalScrollBarEnabled = false
        view.movementMethod = null
        view.isClickable = false
        view.isLongClickable = false
        view.setOnTouchListener(null)
    }

    /** 승인된 통합 동의 전문에서 해당 항목의 조항만 잘라낸다. 새 문구를 만들지 않는다. */
    private fun consentClauseOrNull(label: String): String? {
        val source = INTEGRATED_CONSENT_DISCLOSURE_KO
        val start = source.indexOf("$label: ")
        if (start < 0) return null
        val rest = source.substring(start)
        val next = Regex("""\s\d\. """).find(rest, 1)?.range?.first
            ?: rest.indexOf(" 각 항목은")
        return if (next > 0) rest.substring(0, next).trim() else rest.trim()
    }

    private fun refreshFirstRunNoticeUi() {
        if (!::productPurposeText.isInitialized || !::firstRunNoticeToggleButton.isInitialized) return
        val visible = ::firstRunOnboardingSnapshot.isInitialized &&
            firstRunOnboardingSnapshot.stage == FirstRunOnboardingStage.PURPOSE_AND_SAFETY
        firstRunNoticeToggleButton.visibility = View.GONE
        productPurposeText.visibility = if (visible) View.VISIBLE else View.GONE
        if (visible) {
            productPurposeText.text =
                "이 앱은 모든 장애물과 위험을 감지하지 못하며, 안전한 보행을 보장하지 않습니다.\n\n" +
                "조명·날씨·주변 소음·휴대폰 장착 상태 등에 따라 인식과 안내가 늦거나 누락될 수 있습니다. " +
                "위치와 거리에도 오차가 생길 수 있습니다.\n\n" +
                "흰지팡이·안내견 등 기존 보조수단을 대신하지 않습니다. " +
                "안내가 없더라도 안전하다고 판단하지 마세요. " +
                "안내가 불확실하거나 위험하다고 느끼면 안전한 곳에서 멈추고 주변 도움을 요청하세요."
            productPurposeText.contentDescription = productPurposeText.text
            applyWsSafetyNoticeBody(productPurposeText)
        }
    }

    private fun linkFirstRunAccessibilityTraversal() {
        val controls = buildList<View> {
            add(firstRunNoticeToggleButton)
            add(productPurposeText)
            add(firstRunOnboardingStatusText)
            add(accountAccessStatusText)
            add(accountEmailInput)
            add(accountPasswordInput)
            add(accountLoginButton)
            add(accountSignupToggleButton)
            SIGNUP_DOCUMENT_VERSIONS.keys.forEach { key ->
                add(accountConsentChecks.getValue(key))
                add(accountConsentClauseTexts.getValue(key))
                add(accountConsentListenButtons.getValue(key))
            }
            add(accountConsentContinueButton)
            add(accountPasswordConfirmationInput)
            add(accountDateOfBirthInput)
            add(accountRequestOtpButton)
            add(accountOtpInput)
            add(accountCreateButton)
            add(accountSignupBackButton)
            add(accountSessionLogoutButton)
            add(firstRunPurposeButton)
            listOf(
                FirstRunAgeBand.ADULT_18_PLUS,
                FirstRunAgeBand.AGE_14_TO_17,
                FirstRunAgeBand.UNDER_14,
            ).forEach { ageBand -> add(firstRunAgeButtons.getValue(ageBand)) }
            add(firstRunDisclosureToggleButton)
            add(firstRunIntegratedConsentDisclosureText)
            add(firstRunConsentCountText)
            add(firstRunConsentAllButton)
            IntegratedConsentItem.entries.forEach { item ->
                add(firstRunConsentClauseTexts.getValue(item))
                add(firstRunIntegratedConsentButtons.getValue(item))
            }
            add(firstRunIntegratedConsentSaveButton)
            add(firstRunWaitingText)
        }
        controls.forEach { view ->
            if (view.id == View.NO_ID) view.id = View.generateViewId()
        }
        controls.zipWithNext().forEach { (previous, current) ->
            current.accessibilityTraversalAfter = previous.id
        }
        controls.filter(View::isFocusable).zipWithNext().forEach { (previous, current) ->
            previous.nextFocusForwardId = current.id
            previous.nextFocusDownId = current.id
            current.nextFocusUpId = previous.id
        }
    }

    private fun developmentQuickStartSessionOrNull(): GatewayFieldSession? {
        if (!developmentQuickStartEnabled) return null
        val process = GatewaySessionProcessCoordinator.snapshot()
        val session = process.session ?: return null
        return session.takeIf {
            !process.storageBlocked && !process.deletionRecoveryOnly &&
                !accountDeletionStateMachine.processingBlocked() &&
                it.sessionScope == GatewaySessionScope.GENERAL &&
                it.actorId == developmentQuickStartAuthenticatedActorId &&
                it.verificationState == GatewaySessionVerificationState.VERIFIED &&
                it.isUsableFor(it.actorId) &&
                it.gatewayBaseUrl == configuredGatewayOriginOrNull()
        }
    }

    private fun loginDevelopmentQuickStartAccount() {
        if (!developmentQuickStartEnabled || !isActivityForeground ||
            accountRequestFence.isInFlight()
        ) return
        if (developmentQuickStartSessionOrNull() != null) return
        developmentQuickStartLoginAttempted = true
        if (BuildConfig.DEVELOPMENT_QUICK_START_EMAIL.isBlank() ||
            BuildConfig.DEVELOPMENT_QUICK_START_PASSWORD.isBlank()
        ) {
            showAccountMessage("개발 APK에 테스트 계정 설정이 없습니다. 계정 설정을 포함해 다시 빌드하세요.")
            return
        }
        developmentQuickStartAuthenticatedActorId = null
        if (gatewayFieldSession != null) clearGatewaySession(logoutRemote = false)
        firstRunOnboardingSnapshot = FirstRunOnboardingPolicy.initialEmailAccount(
            epoch = nextFirstRunEpoch(),
        )
        developmentQuickStartStatusText?.text = "로컬 서버의 실제 테스트 계정에 연결하고 있습니다."
        loginEmailAccount(
            emailOverride = BuildConfig.DEVELOPMENT_QUICK_START_EMAIL,
            passwordOverride = BuildConfig.DEVELOPMENT_QUICK_START_PASSWORD,
        )
    }

    private fun startDevelopmentQuickStart() {
        if (!developmentQuickStartEnabled || !isActivityForeground) return
        if (walkSessionLifecycle.snapshot().state == WalkSessionState.PAUSED) {
            developmentQuickStartRequested = false
            window.decorView.removeCallbacks(developmentQuickStartRunnable)
            handleStartupCapabilityConfirmAction()
            return
        }
        if (isWalkSessionRuntimeActive()) {
            developmentQuickStartStatusText?.text = "개발 테스트가 실행 중입니다. 목적지·음성·신고 기능을 사용할 수 있습니다."
            return
        }
        if (gatewayWalkStartConfirmationToken != null) {
            developmentQuickStartStatusText?.text = "서버의 테스트 보행 시작 응답을 기다리고 있습니다."
            return
        }
        developmentQuickStartRequested = true
        developmentQuickStartDeadlineMs = SystemClock.elapsedRealtime() + 45_000L
        developmentQuickStartLoginAttempted = false
        developmentQuickStartPermissionsRequested = false
        developmentQuickStartConsentRequested = false
        advanceDevelopmentQuickStart()
    }

    private fun advanceDevelopmentQuickStart() {
        if (!developmentQuickStartEnabled || !developmentQuickStartRequested ||
            privacyStartupInspectionDestroyed
        ) return
        fun finish(message: String) {
            developmentQuickStartRequested = false
            window.decorView.removeCallbacks(developmentQuickStartRunnable)
            developmentQuickStartStatusText?.text = message
            updateFirstRunOnboardingUi()
        }
        fun awaitStep(message: String) {
            developmentQuickStartStatusText?.text = message
            window.decorView.removeCallbacks(developmentQuickStartRunnable)
            window.decorView.postDelayed(developmentQuickStartRunnable, 500L)
            updateFirstRunOnboardingUi()
        }
        if (SystemClock.elapsedRealtime() >= developmentQuickStartDeadlineMs) {
            finish("테스트 준비 시간 초과. ${developmentQuickStartStatusText?.text?.toString().orEmpty()} 다시 시도하세요.")
            return
        }
        if (!isActivityForeground) {
            awaitStep("권한 확인 또는 앱 복귀를 기다리고 있습니다.")
            return
        }
        val session = developmentQuickStartSessionOrNull()
        if (session == null) {
            if (!developmentQuickStartLoginAttempted && !accountRequestFence.isInFlight()) {
                loginDevelopmentQuickStartAccount()
            }
            if (!accountRequestFence.isInFlight()) {
                finish(accountAccessNotice ?: "테스트 계정 연결 실패. 로컬 서버 연결을 확인하고 다시 시도하세요.")
            } else {
                awaitStep("로컬 서버의 실제 테스트 계정 로그인을 확인하고 있습니다.")
            }
            return
        }
        reporterUserId = session.actorId
        priorityUserOnboardingActorId = session.actorId
        permissionSessionPolicy.authenticated(session.actorId)
        val missingPermissions = requiredPostLoginDeviceCheckPermissions()
        if (missingPermissions.isNotEmpty()) {
            if (!developmentQuickStartPermissionsRequested) {
                developmentQuickStartPermissionsRequested = true
                walkSessionPermissionRequestInFlight = true
                walkSessionPermissionRequestCode = requestPermissionsWithLease(
                    missingPermissions.toTypedArray(),
                    PermissionRequestPurpose.WALK_SESSION,
                )
                awaitStep("실제 카메라·위치·마이크·보행 센서 권한을 허용하세요.")
            } else if (walkSessionPermissionRequestInFlight) {
                awaitStep("Android 권한 선택을 기다리고 있습니다.")
            } else {
                finish("필요한 권한이 없습니다: ${missingPermissions.joinToString { it.permissionLabelKo() }}. 권한을 허용한 뒤 다시 시도하세요.")
            }
            return
        }
        ensureWalkSessionResourceMonitoring()
        if (!startupCapabilityProbeStarted) {
            startupCapabilityProbeStarted = true
            startupCapabilityProbe.start()
        }
        val consent = integratedConsentSession.currentConfirmationOrNull()
        if (consent?.selections?.rawSourceCollection != true ||
            consent?.selections?.automaticReporting != true
        ) {
            if (integratedConsentRequestInFlight) {
                awaitStep("실제 테스트 서버의 사진·위치·자동 신고 동의를 확인하고 있습니다.")
            } else if (consent == null && !integratedConsentBootstrapReady) {
                refreshIntegratedConsentFromServer()
                awaitStep("테스트 서버에서 현재 동의 상태를 가져오고 있습니다.")
            } else if (!developmentQuickStartConsentRequested) {
                developmentQuickStartConsentRequested = true
                integratedConsentDraft = (consent?.selections ?: integratedConsentDraft).copy(
                    rawSourceCollection = true,
                    automaticReporting = true,
                )
                persistIntegratedConsentDraft(announce = false)
                awaitStep("사진·위치·자동 신고 테스트 설정을 서버에 저장하고 있습니다.")
            } else {
                finish("테스트 서버의 신고 동의 확인을 완료하지 못했습니다. 연결 상태를 확인하고 다시 시도하세요.")
            }
            return
        }
        var walk = walkSessionLifecycle.snapshot()
        if (walk.state in setOf(WalkSessionState.SAFE_STOP, WalkSessionState.ENDED)) {
            startFreshWalk("development_quick_start")
            walk = walkSessionLifecycle.snapshot()
        }
        if (walk.state == WalkSessionState.PAUSED) {
            finish("보행이 일시정지되었습니다. 화면의 기존 재점검·보행 재개 버튼으로 계속하세요.")
            return
        }
        if (walk.state == WalkSessionState.ACTIVE) {
            finish("개발 기능 테스트 실행 중입니다.")
            return
        }
        val decision = resolveCurrentStartupCapabilityDecision()
        startupCapabilityDecision = decision
        val readiness = captureWalkSessionReadiness(decision, WalkSessionAction.START_WALK)
        if (!decision.mayConfirmAndStart || !readiness.isReady) {
            awaitStep("실제 실행 준비: ${readiness.blockingReasons.joinToString().ifBlank { decision.noticeKo }}")
            return
        }
        transitionWalkSession(WalkSessionEvent.InitialCheckCompleted(readiness))
        val token = walkSessionLifecycle.snapshot().confirmationToken
        if (token == null) {
            finish("테스트 보행 시작 상태를 만들지 못했습니다. 다시 시도하세요.")
            return
        }
        confirmedStartupCapabilityDecision = decision
        startupCapabilityRetryRequiresUserAction = false
        developmentQuickStartRequested = false
        developmentQuickStartStatusText?.text = "실제 서버 보행을 시작합니다. 거리·위험·신고 결과는 실제 카메라와 센서로 확인합니다."
        requestGatewayWalkStart(token)
        updateFirstRunOnboardingUi()
    }

    private fun firstRunOnboardingComplete(): Boolean {
        if (initialAppPermissionExitRequired) return false
        if (developmentGuidanceStartBypassEnabled && shouldShowNativeHome()) return true
        if (developmentQuickStartEnabled) return developmentQuickStartSessionOrNull() != null
        if (
            !::firstRunOnboardingSnapshot.isInitialized ||
            !firstRunOnboardingSnapshot.mayEnterWalk ||
            !postLoginDeviceCheckPassesFeatureGate() ||
            accountDeletionStateMachine.processingBlocked()
        ) return false
        return GatewaySessionProcessCoordinator.snapshot().restoredFirstRunSnapshot ==
            firstRunOnboardingSnapshot
    }

    private fun firstRunWaitingTextOrNull(snapshot: FirstRunOnboardingSnapshot): String? {
        if (snapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4) {
            return if (accountRequestFence.isInFlight()) {
                "인증번호 요청, 계정 생성 또는 로그인을 처리하고 있습니다. 잠시 기다려 주세요."
            } else {
                null
            }
        }
        return when (snapshot.stage) {
            FirstRunOnboardingStage.VERIFIED_SMS ->
                "운영 공급자의 SMS 검증 증거를 기다리고 있습니다. " +
                    "이 화면에서 아무것도 입력할 필요가 없습니다."
            FirstRunOnboardingStage.GUARDIAN_APPROVAL ->
                "미성년 사용자에게 필요한 보호자 확인 증거를 기다리고 있습니다. " +
                    "이 화면에서 아무것도 입력할 필요가 없습니다."
            FirstRunOnboardingStage.ACCOUNT_ACTIVATION ->
                "운영 계정 활성화 증거를 기다리고 있습니다. " +
                    "이 화면에서 아무것도 입력할 필요가 없습니다."
            FirstRunOnboardingStage.VERIFIED_LOGIN ->
                "검증된 로그인 증거를 기다리고 있습니다. " +
                    "이 화면에서 아무것도 입력할 필요가 없습니다."
            else -> null
        }
    }

    private fun updateFirstRunWaitingDots(active: Boolean) {
        val animationsEnabled = Settings.Global.getFloat(
            contentResolver,
            Settings.Global.ANIMATOR_DURATION_SCALE,
            1f,
        ) > 0f
        firstRunWaitingDots.forEachIndexed { index, dot ->
            if (!active || !animationsEnabled) {
                dot.clearAnimation()
                dot.alpha = FIRST_RUN_WAITING_DOT_MIN_ALPHA
                return@forEachIndexed
            }
            if (dot.animation != null) return@forEachIndexed
            dot.startAnimation(
                AlphaAnimation(FIRST_RUN_WAITING_DOT_MIN_ALPHA, 1f).apply {
                    duration = FIRST_RUN_WAITING_DOT_PERIOD_MS
                    startOffset = index * FIRST_RUN_WAITING_DOT_STAGGER_MS
                    repeatMode = Animation.REVERSE
                    repeatCount = Animation.INFINITE
                },
            )
        }
    }

    private fun postLoginDeviceCheckPassesFeatureGate(): Boolean {
        if (developmentQuickStartEnabled) {
            return isActivityForeground && developmentQuickStartSessionOrNull() != null
        }
        if (!isActivityForeground ||
            (!developmentPostLoginDeviceCheckBypassed &&
                !postLoginDeviceCheckSnapshot.passesFeatureGate)
        ) return false
        val process = GatewaySessionProcessCoordinator.snapshot()
        val session = process.session ?: return false
        val binding = postLoginDeviceCheckSnapshot.bindingOrNull
        if (binding == null && developmentPostLoginDeviceCheckBypassed) {
            return session.verificationState == GatewaySessionVerificationState.VERIFIED &&
                session.isUsableFor(session.actorId) && !process.storageBlocked &&
                !process.deletionRecoveryOnly
        }
        binding ?: return false
        return binding.actorId == session.actorId &&
            binding.sessionGeneration == process.generation &&
            session.verificationState == GatewaySessionVerificationState.VERIFIED &&
            session.isUsableFor(binding.actorId) &&
            !process.storageBlocked &&
            !process.deletionRecoveryOnly
    }

    private fun revalidateCompletedPostLoginDeviceCheckPrerequisites(): Boolean {
        if (!postLoginDeviceCheckSnapshot.passesFeatureGate) return false
        val actorId = postLoginDeviceCheckSnapshot.actorId
        val binding = actorId?.let(::currentPostLoginDeviceCheckResultBinding)
        val restored = binding?.let(postLoginDeviceCheckResultStore::restore)
        if (
            restored != null &&
            restored.state == postLoginDeviceCheckSnapshot.state &&
            restored.disabledFeatures == postLoginDeviceCheckSnapshot.disabledFeatures &&
            restored.cameraDependentChecksDeferred ==
            postLoginCameraDependentChecksDeferred
        ) return false

        cancelPostLoginDeviceCheckRuntime("saved_result_prerequisites_changed")
        postLoginDeviceCheckSnapshot = postLoginDeviceCheckSnapshot.copy(
            state = PostLoginDeviceCheckState.NOT_RUN,
            failure = null,
            disabledFeatures = emptySet(),
        )
        postLoginCameraDependentChecksDeferred = false
        metricDistanceCapabilityOverride = null
        runtimeObstacleDetectionCapabilityOverride = null
        onDeviceSpeechRecognitionCapabilityOverride = null
        offlineKoreanTextToSpeechCapabilityOverride = null
        return true
    }

    private fun currentPostLoginDeviceCheckResultBinding(
        actorId: String,
    ): PostLoginDeviceCheckResultBinding? {
        if (
            !::startupCapabilityProbe.isInitialized ||
            !::gatewaySessionStore.isInitialized
        ) return null
        val installationId = gatewaySessionStore.getOrCreateInstallDeviceId() ?: return null
        val startup = startupCapabilityProbe.snapshot()
        val offlineKoreanTextToSpeechAvailable =
            startup.offlineKoreanTextToSpeechAvailable
        val onDeviceSpeechRecognitionAvailable =
            startup.onDeviceSpeechRecognitionAvailable
        val environmentProfile = activeEnvironmentProfiles
        val deviceProfile = startupCapabilityProbe.deviceProfileMatch()
        return PostLoginDeviceCheckResultBinding(
            actorId = actorId,
            installationId = installationId,
            deviceManufacturer = Build.MANUFACTURER,
            deviceModel = Build.MODEL,
            deviceName = Build.DEVICE,
            osSdkInt = Build.VERSION.SDK_INT,
            osBuildFingerprint = Build.FINGERPRINT,
            appId = packageName,
            appVersionCode = BuildConfig.VERSION_CODE.toLong(),
            appVersionName = BuildConfig.VERSION_NAME,
            appSourceRevision = BuildConfig.WALKSAFE_SOURCE_COMMIT,
            probePolicyVersion = POST_LOGIN_DEVICE_CHECK_PROBE_POLICY_VERSION,
            environmentProfileId = environmentProfile?.bundleId,
            environmentProfileRevision = environmentProfile?.revision,
            approvedDeviceProfileRegistryRevision =
                WalkSafeApprovedDeviceProfiles.REGISTRY_REVISION,
            approvedDeviceProfileRegistrySha256 =
                WalkSafeApprovedDeviceProfiles.registryContentSha256,
            approvedDeviceProfileId = deviceProfile.profileId,
            approvedDeviceProfileVersion = deviceProfile.profileVersion,
            missingRequiredPermissions = requiredPostLoginDeviceCheckPermissions().toSet(),
            locationServiceEnabled = isLocationServiceEnabledForDeviceCheck(),
            voiceDisclosureAccepted = isHandsFreeVoiceDisclosureAccepted(),
            offlineKoreanTextToSpeechAvailable = offlineKoreanTextToSpeechAvailable,
            onDeviceSpeechRecognitionAvailable = onDeviceSpeechRecognitionAvailable,
        )
    }

    private fun bindPostLoginDeviceCheckSession(
        actorId: String?,
        sessionGeneration: Long?,
    ) {
        if (developmentQuickStartEnabled) return
        val previous = postLoginDeviceCheckSnapshot
        val next = PostLoginDeviceCheckPolicy.bindSession(
            previous,
            actorId,
            sessionGeneration,
        )
        val restored = if (
            actorId != null &&
            sessionGeneration != null &&
            next.state == PostLoginDeviceCheckState.NOT_RUN &&
            ::postLoginDeviceCheckResultStore.isInitialized
        ) {
            currentPostLoginDeviceCheckResultBinding(actorId)
                ?.let(postLoginDeviceCheckResultStore::restore)
        } else {
            null
        }
        val restoredSnapshot = restored?.let { result ->
            PostLoginDeviceCheckSnapshot(
                state = result.state,
                actorId = actorId,
                sessionGeneration = sessionGeneration,
                attemptGeneration = next.attemptGeneration.coerceAtLeast(1L),
                disabledFeatures = result.disabledFeatures,
            )
        } ?: next
        val sessionBindingChanged = next != previous
        if (restoredSnapshot != previous) cancelPostLoginDeviceCheckRuntime("session_changed")
        postLoginDeviceCheckSnapshot = restoredSnapshot
        if (restored != null) {
            postLoginCameraDependentChecksDeferred =
                restored.cameraDependentChecksDeferred
            postLoginMetricDepthState = restored.metricDepthState
            metricDistanceCapabilityOverride = if (restored.cameraDependentChecksDeferred) {
                false
            } else when (restored.metricDepthState) {
                PostLoginMetricDepthState.SUPPORTED -> true
                PostLoginMetricDepthState.EXPLICITLY_UNSUPPORTED -> false
                else -> null
            }
            runtimeObstacleDetectionCapabilityOverride = if (
                restored.cameraDependentChecksDeferred
            ) {
                false
            } else {
                null
            }
            onDeviceSpeechRecognitionCapabilityOverride = if (
                PostLoginDeviceCheckFeature.HANDS_FREE_VOICE in restored.disabledFeatures
            ) {
                false
            } else {
                null
            }
            offlineKoreanTextToSpeechCapabilityOverride = if (
                PostLoginDeviceCheckFeature.VOICE_GUIDANCE in restored.disabledFeatures
            ) {
                false
            } else {
                null
            }
            if (restored.metricDepthProbePolicyCurrent) {
                clearStoredMetricDepthRefresh()
            } else {
                prepareStoredMetricDepthRefresh(
                    snapshot = restoredSnapshot,
                    cameraDependentChecksDeferred =
                        restored.cameraDependentChecksDeferred,
                )
            }
        } else if (sessionBindingChanged) {
            clearStoredMetricDepthRefresh()
            postLoginCameraDependentChecksDeferred = false
            postLoginMetricDepthState = PostLoginMetricDepthState.PENDING
            metricDistanceCapabilityOverride = null
            runtimeObstacleDetectionCapabilityOverride = null
            onDeviceSpeechRecognitionCapabilityOverride = null
            offlineKoreanTextToSpeechCapabilityOverride = null
        }
        maybeStartStoredDeviceCheckBindingValidation()
        maybeStartStoredMetricDepthRefresh()
        if (::startupCapabilityText.isInitialized) refreshStartupCapabilityUi()
        if (postLoginDeviceCheckSnapshot.passesFeatureGate) scheduleDeviceRuntimeCalibration()
    }

    private fun prepareStoredMetricDepthRefresh(
        snapshot: PostLoginDeviceCheckSnapshot,
        cameraDependentChecksDeferred: Boolean,
    ) {
        val binding = snapshot.bindingOrNull ?: return
        if (!snapshot.passesFeatureGate) return
        storedMetricDepthRefreshContext = StoredMetricDepthRefreshContext(
            binding = binding,
            state = snapshot.state,
            disabledFeatures = snapshot.disabledFeatures.toSet(),
            cameraDependentChecksDeferred = cameraDependentChecksDeferred,
        )
        storedMetricDepthRefreshPending = true
        storedMetricDepthRefreshRetryAllowed = true
    }

    private fun clearStoredMetricDepthRefresh() {
        storedMetricDepthRefreshContext = null
        storedMetricDepthRefreshPending = false
        storedMetricDepthRefreshRetryAllowed = false
    }

    private fun isStoredMetricDepthRefreshContextCurrent(
        context: StoredMetricDepthRefreshContext,
    ): Boolean {
        val sessionBinding = currentPostLoginDeviceCheckSessionBinding() ?: return false
        val snapshot = postLoginDeviceCheckSnapshot
        return storedMetricDepthRefreshPending &&
            storedMetricDepthRefreshContext == context &&
            snapshot.passesFeatureGate &&
            snapshot.bindingOrNull == context.binding &&
            snapshot.state == context.state &&
            snapshot.disabledFeatures == context.disabledFeatures &&
            postLoginCameraDependentChecksDeferred ==
            context.cameraDependentChecksDeferred &&
            sessionBinding.actorId == context.binding.actorId &&
            sessionBinding.sessionGeneration == context.binding.sessionGeneration
    }

    private fun maybeStartStoredMetricDepthRefresh() {
        val context = storedMetricDepthRefreshContext ?: return
        if (
            !storedMetricDepthRefreshPending ||
            !storedMetricDepthRefreshRetryAllowed ||
            metricPreflightOwner != RuntimeMetricPreflightOwner.NONE ||
            !isActivityForeground ||
            isFinishing ||
            isDestroyed ||
            !::startupMetricPreflightButton.isInitialized ||
            !hasCameraPermission() ||
            isWalkSessionRuntimeActive() ||
            runtimeCameraStartBlockedByAnotherOwner() ||
            session != null ||
            arSessionPurpose != ArSessionPurpose.NONE ||
            !isStoredMetricDepthRefreshContextCurrent(context)
        ) return

        storedMetricDepthRefreshRetryAllowed = false
        metricPreflightOwner = RuntimeMetricPreflightOwner.STORED_DEPTH_REFRESH
        metricPreflightFirstRunLease = null
        metricPreflightPostLoginBinding = context.binding
        val generation = ++runtimeMetricPreflightGeneration
        metricPreflightLifecycleGeneration = feedbackLifecycleGeneration
        pendingMetricPreflightPermissionGeneration = null
        runtimeMetricOutputAllowed = false
        runtimeMetricInitialNavigationStartPending = false
        startRuntimeMetricPreflight(generation, metricPreflightLifecycleGeneration)
    }

    private fun completeStoredMetricDepthRefresh(
        metricDistanceSupported: Boolean?,
        completedBinding: PostLoginDeviceCheckBinding,
    ): Boolean {
        val context = storedMetricDepthRefreshContext ?: return false
        if (
            context.binding != completedBinding ||
            !isStoredMetricDepthRefreshContextCurrent(context)
        ) return false
        val metricDistanceAvailable = metricDistanceSupported ?: return false
        val metricDepthState = if (metricDistanceAvailable) {
            PostLoginMetricDepthState.SUPPORTED
        } else {
            PostLoginMetricDepthState.EXPLICITLY_UNSUPPORTED
        }
        val updatedDisabledFeatures = if (metricDistanceAvailable) {
            context.disabledFeatures - PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE
        } else {
            context.disabledFeatures + PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE
        }
        val updatedSnapshot = postLoginDeviceCheckSnapshot.copy(
            state = if (updatedDisabledFeatures.isEmpty()) {
                PostLoginDeviceCheckState.FULL
            } else {
                PostLoginDeviceCheckState.LIMITED
            },
            disabledFeatures = updatedDisabledFeatures,
        )
        val resultBinding =
            currentPostLoginDeviceCheckResultBinding(completedBinding.actorId)
                ?: return false
        if (
            !postLoginDeviceCheckResultStore.save(
                snapshot = updatedSnapshot,
                binding = resultBinding,
                cameraDependentChecksDeferred =
                    context.cameraDependentChecksDeferred,
                metricDepthState = metricDepthState,
            )
        ) return false

        postLoginDeviceCheckSnapshot = updatedSnapshot
        postLoginCameraDependentChecksDeferred =
            context.cameraDependentChecksDeferred
        postLoginMetricDepthState = metricDepthState
        metricDistanceCapabilityOverride = metricDistanceAvailable
        clearStoredMetricDepthRefresh()
        return true
    }

    private fun restoreBoundPostLoginDeviceCheckResultIfPossible(): Boolean {
        if (postLoginDeviceCheckSnapshot.state != PostLoginDeviceCheckState.NOT_RUN) return false
        val sessionBinding = currentPostLoginDeviceCheckSessionBinding() ?: return false
        if (currentPostLoginDeviceCheckResultBinding(sessionBinding.actorId) == null) return false
        bindPostLoginDeviceCheckSession(
            actorId = sessionBinding.actorId,
            sessionGeneration = sessionBinding.sessionGeneration,
        )
        return postLoginDeviceCheckSnapshot.passesFeatureGate
    }

    private fun maybeStartStoredDeviceCheckBindingValidation() {
        if (
            !::startupCapabilityProbe.isInitialized ||
            !::postLoginDeviceCheckResultStore.isInitialized ||
            startupCapabilityProbeStarted ||
            postLoginDeviceCheckSnapshot.state != PostLoginDeviceCheckState.NOT_RUN ||
            currentPostLoginDeviceCheckSessionBinding() == null ||
            !postLoginDeviceCheckResultStore.hasCurrentPolicyResultCandidate()
        ) return

        startupCapabilityProbe.close()
        startupCapabilityProbe = AndroidStartupCapabilityProbe(this) {
            completeVoiceDataInstallRecheckIfPossible()
            val bindingReady = currentPostLoginDeviceCheckSessionBinding()?.actorId?.let {
                currentPostLoginDeviceCheckResultBinding(it)
            } != null
            if (bindingReady) {
                storedDeviceCheckBindingValidationPending = false
                if (
                    restoreBoundPostLoginDeviceCheckResultIfPossible() &&
                    advanceEmailStagesWithRestoredDeviceCheck()
                ) {
                    onFirstRunOnboardingStateChanged(
                        announcement =
                            "저장된 기기 점검 결과를 적용했습니다. 안전교육을 완료하세요.",
                        preservePostLoginDeviceCheck = true,
                    )
                }
            }
            refreshStartupCapabilityUi()
        }
        storedDeviceCheckBindingValidationPending = true
        startupCapabilityProbeStarted = true
        if (runCatching { startupCapabilityProbe.start() }.isFailure) {
            startupCapabilityProbeStarted = false
            storedDeviceCheckBindingValidationPending = false
            startupCapabilityProbe.close()
        }
    }

    private fun firstRunStageNumber(snapshot: FirstRunOnboardingSnapshot): Int =
        if (snapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4) {
            when (snapshot.stage) {
                FirstRunOnboardingStage.EMAIL_OTP_ENROLLMENT -> 1
                FirstRunOnboardingStage.ACCOUNT_CREATED -> 2
                FirstRunOnboardingStage.VERIFIED_LOGIN -> 3
                FirstRunOnboardingStage.PURPOSE_AND_SAFETY -> 4
                FirstRunOnboardingStage.JIT_PERMISSION_OBSERVATION -> 5
                FirstRunOnboardingStage.DEVICE_CHECK -> 6
                FirstRunOnboardingStage.FP004_TRAINING -> 7
                FirstRunOnboardingStage.COMPLETE -> 7
                else -> 1
            }
        } else when (snapshot.stage) {
        FirstRunOnboardingStage.EMAIL_OTP_ENROLLMENT,
        FirstRunOnboardingStage.ACCOUNT_CREATED,
        -> 1
        FirstRunOnboardingStage.PURPOSE_AND_SAFETY -> 1
        FirstRunOnboardingStage.AGE_AND_GUARDIAN_NEED -> 2
        FirstRunOnboardingStage.INTEGRATED_CONSENT -> 3
        FirstRunOnboardingStage.LOCAL_CREDENTIAL_PHONE_SUBMISSION -> 4
        FirstRunOnboardingStage.VERIFIED_SMS -> 5
        FirstRunOnboardingStage.GUARDIAN_APPROVAL -> 6
        FirstRunOnboardingStage.ACCOUNT_ACTIVATION -> 7
        FirstRunOnboardingStage.VERIFIED_LOGIN -> 8
        FirstRunOnboardingStage.JIT_PERMISSION_OBSERVATION -> 9
        FirstRunOnboardingStage.DEVICE_CHECK -> 10
        FirstRunOnboardingStage.FP004_TRAINING -> 11
        FirstRunOnboardingStage.COMPLETE -> 12
        FirstRunOnboardingStage.BLOCKED_UNDER_14 -> 2
        }

    private fun firstRunStageCount(snapshot: FirstRunOnboardingSnapshot): Int =
        if (snapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4) {
            EMAIL_FIRST_RUN_STAGE_COUNT
        } else {
            FIRST_RUN_STAGE_COUNT
        }

    private fun updatePrivacySectionVisibility() {
        renderMainUi()
    }

    private fun updateRuntimeDebugControlsVisibility() {
        if (!::runtimeDebugControls.isInitialized) return
        runtimeDebugControls.visibility = View.GONE
    }

    private fun firstRunDeviceCheckAllowsPreflight(): Boolean =
        ::firstRunOnboardingSnapshot.isInitialized &&
            postLoginDeviceCheckSnapshot.state == PostLoginDeviceCheckState.RUNNING &&
            postLoginDeviceCheckSnapshot.bindingOrNull?.let {
                PostLoginDeviceCheckPolicy.isCurrent(postLoginDeviceCheckSnapshot, it) &&
                    isPostLoginDeviceCheckSessionBindingLive(it)
            } == true

    private fun maybeStartFirstRunDeviceCheckProbes() {
        if (!firstRunDeviceCheckAllowsPreflight()) return
        ensureWalkSessionResourceMonitoring()
        if (
            ::startupCapabilityProbe.isInitialized &&
            !startupCapabilityProbeStarted
        ) {
            startupCapabilityProbeStarted = true
            startupCapabilityProbe.start()
        }
    }

    private fun ensureWalkSessionResourceMonitoring() {
        if (!::walkSessionResourceProbe.isInitialized || walkSessionResourceProbeStarted) return
        walkSessionResourceProbeStarted = true
        walkSessionResourceProbeStarted =
            runCatching {
                walkSessionResourceProbe.start {
                    observeWalkRuntimeResourceSafety()
                    maybeContinuePostLoginDeviceCheck()
                    refreshStartupCapabilityUi()
                }
            }.getOrDefault(false)
    }

    private fun resetWalkSessionResourceProbe() {
        if (::walkSessionResourceProbe.isInitialized) walkSessionResourceProbe.close()
        walkSessionResourceProbe = AndroidWalkSessionResourceProbe(this)
        walkSessionResourceProbeStarted = false
    }

    private var postLoginResourceWaitThermal: Boolean? = null
    private val postLoginResourceWaitNotice: String?
        get() = postLoginResourceWaitThermal?.let { thermal ->
            if (postLoginDeviceCheckSnapshot.state == PostLoginDeviceCheckState.FAIL) {
                if (thermal) "발열 상태가 해소되지 않았습니다. 휴대전화가 식은 뒤 다시 점검하세요."
                else "배터리·저장공간·발열 상태를 확인하지 못했습니다. 다시 점검하세요."
            } else {
                if (thermal) "발열로 점검을 기다리고 있습니다. 휴대전화가 식은 뒤 계속합니다."
                else "배터리·저장공간·발열 상태를 확인하고 있습니다."
            }
        }

    private fun startPostLoginDeviceCheckRuntime(
        binding: PostLoginDeviceCheckBinding,
    ) {
        if (!isPostLoginDeviceCheckBindingCurrent(binding)) return
        postLoginResourceWaitThermal = null
        storedDeviceCheckBindingValidationPending = false
        if (::startupCapabilityProbe.isInitialized) startupCapabilityProbe.close()
        startupCapabilityProbe = AndroidStartupCapabilityProbe(this) {
            completeVoiceDataInstallRecheckIfPossible()
            maybeContinuePostLoginDeviceCheck(binding)
            refreshStartupCapabilityUi()
        }
        startupCapabilityProbeStarted = false
        resetWalkSessionResourceProbe()
        postLoginMetricPreflightStarted = false
        lateinit var timeout: Runnable
        timeout = Runnable {
            if (
                postLoginDeviceCheckOverallTimeout !== timeout ||
                !isPostLoginDeviceCheckBindingCurrent(binding)
            ) return@Runnable
            postLoginDeviceCheckOverallTimeout = null
            val previous = postLoginDeviceCheckSnapshot
            postLoginDeviceCheckSnapshot = PostLoginDeviceCheckPolicy.timeout(
                snapshot = previous,
                binding = binding,
                foreground = isActivityForeground,
            )
            if (postLoginDeviceCheckSnapshot != previous) {
                cancelPostLoginDeviceCheckRuntime("check_timeout")
                announcePostLoginDeviceCheckTerminal(
                    "기기 점검 시간이 초과되었습니다. 화면의 대기 항목을 확인하세요.",
                )
                updateStatus(
                    "기기 점검 시간 초과",
                    postLoginDeviceCheckFailureMessage(postLoginDeviceCheckSnapshot.failure),
                )
                refreshStartupCapabilityUi()
            }
        }
        postLoginDeviceCheckOverallTimeout = timeout
        startupCapabilityText.postDelayed(timeout, POST_LOGIN_DEVICE_CHECK_TIMEOUT_MS)
        prepareHandsFreeVoiceModel()
        loadDetectorForPostLoginDeviceCheck()
        maybeStartFirstRunDeviceCheckProbes()
        maybeContinuePostLoginDeviceCheck(binding)
    }

    private fun maybeContinuePostLoginDeviceCheck(
        expectedBinding: PostLoginDeviceCheckBinding? = null,
    ) {
        val binding = expectedBinding ?: postLoginDeviceCheckSnapshot.bindingOrNull ?: return
        if (!isPostLoginDeviceCheckBindingCurrent(binding)) return
        val observation = currentPostLoginDeviceCheckObservation()
        val resources = walkSessionResourceProbe.snapshot()
        postLoginResourceWaitThermal = if (
            resources.measurementReadinessStatus == WalkSessionReadinessStatus.PENDING
        ) resources.thermalThrottled == true else null
        evaluatePostLoginDeviceCheck(binding, observation)
        if (postLoginDeviceCheckSnapshot.state != PostLoginDeviceCheckState.RUNNING) return
        val automaticPrerequisitesPending = listOf(
            observation.minimumAndroidVersion,
            observation.coreHardwareAndServices,
            observation.deviceResources,
            observation.detector,
            observation.koreanTextToSpeech,
        ).any { it == PostLoginDeviceCheckSignal.PENDING }
        if (automaticPrerequisitesPending) return
        if (observation.cameraPipeline == PostLoginDeviceCheckSignal.PENDING) {
            startPostLoginCameraPipelinePreflight(binding)
            return
        }
        when (observation.metricDepth) {
            PostLoginMetricDepthState.PENDING -> if (!postLoginMetricPreflightStarted) {
                beginRuntimeMetricPreflight()
            }
            PostLoginMetricDepthState.EXPLICITLY_UNSUPPORTED -> Unit
            else -> Unit
        }
        evaluatePostLoginDeviceCheck(binding)
    }

    private fun evaluatePostLoginDeviceCheck(
        expectedBinding: PostLoginDeviceCheckBinding? = null,
        observation: PostLoginDeviceCheckObservation =
            currentPostLoginDeviceCheckObservation(),
    ) {
        val binding = expectedBinding ?: postLoginDeviceCheckSnapshot.bindingOrNull ?: return
        if (!isPostLoginDeviceCheckSnapshotBindingLive(binding)) return
        val previous = postLoginDeviceCheckSnapshot
        val next = PostLoginDeviceCheckPolicy.evaluate(
            snapshot = previous,
            binding = binding,
            foreground = isActivityForeground,
            observation = observation,
        )
        postLoginDeviceCheckSnapshot = next
        if (next == previous) return
        when (next.state) {
            PostLoginDeviceCheckState.FULL,
            PostLoginDeviceCheckState.LIMITED,
            -> completePostLoginDeviceCheckPass(next.state)
            PostLoginDeviceCheckState.FAIL -> {
                cancelPostLoginDeviceCheckRuntime("terminal_failure")
                val detail = postLoginDeviceCheckFailureMessage(next.failure)
                announcePostLoginDeviceCheckTerminal(
                    "기기 점검에 실패했습니다. $detail",
                )
                updateStatus("기기 점검 실패", detail)
                refreshStartupCapabilityUi()
            }
            else -> Unit
        }
    }

    private fun currentPostLoginDeviceCheckObservation(): PostLoginDeviceCheckObservation {
        val startup = startupCapabilityProbe.snapshot()
        val speechRecognitionAvailable =
            onDeviceSpeechRecognitionCapabilityOverride
                ?: startup.onDeviceSpeechRecognitionAvailable
        val koreanTextToSpeechAvailable =
            offlineKoreanTextToSpeechCapabilityOverride
                ?: startup.offlineKoreanTextToSpeechAvailable
        val coreSignals = listOf(
            startup.cameraAvailable,
            startup.gpsAvailable,
            startup.microphoneAvailable,
        )
        val resources = walkSessionResourceProbe.snapshot()
        val detectorUnavailable =
            detectorLoadAttempted && (!detectorConfigLoaded || !detectorAvailable)
        val cameraPermissionGranted = hasCameraPermission()
        val cameraPipeline = when {
            startup.cameraAvailable == false ||
                !cameraPermissionGranted ||
                detectorUnavailable -> PostLoginDeviceCheckSignal.UNAVAILABLE
            else -> postLoginCameraPipelineSignal
        }
        val metricDepth = when {
            !cameraPermissionGranted || startup.cameraAvailable == false ->
                PostLoginMetricDepthState.UNKNOWN
            startup.metricDistanceAvailable == false ->
                PostLoginMetricDepthState.EXPLICITLY_UNSUPPORTED
            else -> postLoginMetricDepthState
        }
        val unsupportedFeatures = buildSet {
            val obstacleDetectionUnavailable =
                startup.cameraAvailable == false ||
                    detectorUnavailable
            if (obstacleDetectionUnavailable) {
                add(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION)
            }
            if (
                obstacleDetectionUnavailable ||
                metricDepth in setOf(
                    PostLoginMetricDepthState.EXPLICITLY_UNSUPPORTED,
                    PostLoginMetricDepthState.UNKNOWN,
                    PostLoginMetricDepthState.TIMED_OUT,
                )
            ) {
                add(PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE)
            }
            if (startup.gpsAvailable == false) {
                add(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE)
            }
            if (
                startup.microphoneAvailable == false ||
                    speechRecognitionAvailable == false ||
                    postLoginWakePhraseSignal == PostLoginDeviceCheckSignal.UNAVAILABLE ||
                    handsFreeVoiceModelPreparationFailed
            ) {
                add(PostLoginDeviceCheckFeature.HANDS_FREE_VOICE)
            }
            if (koreanTextToSpeechAvailable == false) {
                add(PostLoginDeviceCheckFeature.VOICE_GUIDANCE)
            }
        }
        return PostLoginDeviceCheckObservation(
            minimumAndroidVersion = startup.androidVersionSupported.toDeviceCheckSignal(),
            requiredPermissions = if (requiredPostLoginDeviceCheckPermissions().isEmpty()) {
                PostLoginDeviceCheckSignal.READY
            } else {
                PostLoginDeviceCheckSignal.UNAVAILABLE
            },
            voiceDisclosure = isHandsFreeVoiceDisclosureAccepted().toDeviceCheckSignal(),
            coreHardwareAndServices = when {
                coreSignals.any { it == false } -> PostLoginDeviceCheckSignal.UNAVAILABLE
                coreSignals.any { it == null } -> PostLoginDeviceCheckSignal.PENDING
                else -> PostLoginDeviceCheckSignal.READY
            },
            locationService = if (isLocationServiceEnabledForDeviceCheck()) {
                PostLoginDeviceCheckSignal.READY
            } else {
                PostLoginDeviceCheckSignal.UNAVAILABLE
            },
            locationFix = postLoginLocationFixSignal,
            deviceResources = when (resources.measurementReadinessStatus) {
                WalkSessionReadinessStatus.READY,
                WalkSessionReadinessStatus.NOT_REQUIRED,
                -> PostLoginDeviceCheckSignal.READY
                WalkSessionReadinessStatus.PENDING -> PostLoginDeviceCheckSignal.PENDING
                WalkSessionReadinessStatus.UNAVAILABLE -> PostLoginDeviceCheckSignal.UNAVAILABLE
            },
            detector = when {
                !detectorLoadAttempted -> PostLoginDeviceCheckSignal.PENDING
                detectorConfigLoaded && detectorAvailable -> PostLoginDeviceCheckSignal.READY
                else -> PostLoginDeviceCheckSignal.UNAVAILABLE
            },
            cameraPipeline = cameraPipeline,
            koreanTextToSpeech = koreanTextToSpeechAvailable.toDeviceCheckSignal(),
            wakePhraseRecognition = when {
                !hasRecordAudioPermission() || startup.microphoneAvailable == false ||
                    handsFreeVoiceModelPreparationFailed -> PostLoginDeviceCheckSignal.UNAVAILABLE
                else -> postLoginWakePhraseSignal
            },
            metricDepth = metricDepth,
            unsupportedFeatures = unsupportedFeatures,
            blockingFailure = when {
                startup.androidVersionSupported == false ->
                    PostLoginDeviceCheckFailure.MINIMUM_ANDROID_VERSION
                resources.measurementReadinessStatus == WalkSessionReadinessStatus.UNAVAILABLE ->
                    PostLoginDeviceCheckFailure.DEVICE_RESOURCE
                koreanTextToSpeechAvailable == false ->
                    PostLoginDeviceCheckFailure.KOREAN_TTS_UNAVAILABLE
                else -> null
            },
        )
    }

    private fun completePostLoginDeviceCheckPass(state: PostLoginDeviceCheckState) {
        val completedBinding = postLoginDeviceCheckSnapshot.bindingOrNull
        val liveBinding = currentPostLoginDeviceCheckSessionBinding()
        if (completedBinding == null || liveBinding != completedBinding) {
            failPostLoginDeviceCheckForSessionChange()
            return
        }
        val cameraDependentChecksDeferred =
            postLoginCameraPipelineSignal != PostLoginDeviceCheckSignal.READY &&
                PostLoginDeviceCheckFeature.OBSTACLE_DETECTION !in
                postLoginDeviceCheckSnapshot.disabledFeatures
        val resultBinding =
            currentPostLoginDeviceCheckResultBinding(completedBinding.actorId)
        if (
            resultBinding == null ||
            !postLoginDeviceCheckResultStore.save(
                postLoginDeviceCheckSnapshot,
                resultBinding,
                cameraDependentChecksDeferred = cameraDependentChecksDeferred,
                metricDepthState = postLoginMetricDepthState,
            )
        ) {
            postLoginDeviceCheckSnapshot = postLoginDeviceCheckSnapshot.copy(
                state = PostLoginDeviceCheckState.FAIL,
                failure = PostLoginDeviceCheckFailure.RESULT_SAVE_FAILED,
                disabledFeatures = emptySet(),
            )
            cancelPostLoginDeviceCheckRuntime("result_save_failed")
            updateStatus(
                "기기 점검 결과 저장 실패",
                "점검 결과를 저장하지 못했습니다. 저장공간을 확인한 뒤 다시 시도하세요.",
            )
            refreshStartupCapabilityUi()
            return
        }
        postLoginCameraDependentChecksDeferred = cameraDependentChecksDeferred
        clearPostLoginDeviceCheckOverallTimeout()
        cancelPostLoginDeviceCheckFunctionalProbes()
        stopPostLoginCameraPipelinePreflight()
        val currentRestrictions = postLoginDeviceCheckDisabledFeatureText()
        val hasCurrentRestrictions = hasCurrentPostLoginDeviceRestrictions()
        val advancesFirstRun =
            firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 &&
                firstRunOnboardingSnapshot.stage == FirstRunOnboardingStage.DEVICE_CHECK
        if (advancesFirstRun) {
            postLoginDeviceCheckLastLiveStatus = null
            postLoginDeviceCheckLiveStatusText.text = ""
            postLoginDeviceCheckLiveStatusText.visibility = View.GONE
        } else {
            announcePostLoginDeviceCheckProgress(
                if (state == PostLoginDeviceCheckState.FULL && !hasCurrentRestrictions) {
                    "기기 점검을 모두 통과했습니다."
                } else if (state == PostLoginDeviceCheckState.FULL) {
                    "기기 사양 점검을 통과했습니다. 현재 권한으로 제한되는 기능: " +
                        currentRestrictions
                } else {
                    "기기 점검을 제한 모드로 통과했습니다. 제한 기능: " +
                        currentRestrictions
                },
            )
        }
        if (::rawCollectionRuntimeCoordinator.isInitialized) {
            val process = GatewaySessionProcessCoordinator.snapshot()
            val currentSession = process.session
            if (
                currentSession != null &&
                !process.storageBlocked &&
                !process.deletionRecoveryOnly
            ) {
                val deviceCheck = postLoginDeviceCheckSnapshot
                executeRawCollectionTask {
                    rawCollectionRuntimeCoordinator.resetForNewEnrollment(
                        session = currentSession,
                        sessionGeneration = process.generation,
                        deviceCheck = deviceCheck,
                    )
                }
                scheduleRawCollectionPausedUpload()
            }
        }
        if (advancesFirstRun) {
            val transition = FirstRunOnboardingPolicy.recordEmailDeviceCheckPassed(
                snapshot = firstRunOnboardingSnapshot,
                expectedEpoch = firstRunOnboardingSnapshot.epoch,
                expectedRevision = firstRunOnboardingSnapshot.revision,
            )
            if (!transition.accepted) return
            val actorId = transition.current.verifiedActorBinding?.value
            val process = GatewaySessionProcessCoordinator.snapshot()
            if (
                actorId == null ||
                !GatewaySessionProcessCoordinator.updateFirstRunSnapshot(
                    expectedGeneration = process.generation,
                    expectedActorId = actorId,
                    firstRunSnapshot = transition.current,
                )
            ) {
                failPostLoginDeviceCheckForSessionChange()
                return
            }
            firstRunOnboardingSnapshot = transition.current
            onFirstRunOnboardingStateChanged(
                announcement = if (
                    state == PostLoginDeviceCheckState.FULL &&
                    !hasCurrentRestrictions
                ) {
                    "기기 점검을 모두 통과했습니다. 휴대폰 사용 자세에 동의한 뒤 안전교육을 완료하세요."
                } else if (state == PostLoginDeviceCheckState.FULL) {
                    "기기 사양 점검을 통과했습니다. 현재 권한으로 제한되는 기능은 " +
                        "${currentRestrictions}입니다. 안전교육을 완료하세요."
                } else {
                    "기기 점검을 제한 모드로 통과했습니다. 제한 기능은 " +
                        "${currentRestrictions}입니다. 안전교육을 완료하세요."
                },
                preservePostLoginDeviceCheck = true,
            )
        } else if (
            firstRunOnboardingSnapshot.stage == FirstRunOnboardingStage.FP004_TRAINING &&
            priorityUserOnboardingPolicy.snapshot().trainingComplete
        ) {
            firstRunOnboardingSnapshot.verifiedActorBinding?.value?.let {
                completeFirstRunFp004TrainingIfReady(it)
            }
        }
        refreshStartupCapabilityUi()
        scheduleDeviceRuntimeCalibration()
    }

    private fun failPostLoginDeviceCheckForSessionChange() {
        postLoginDeviceCheckSnapshot = postLoginDeviceCheckSnapshot.copy(
            state = PostLoginDeviceCheckState.FAIL,
            failure = PostLoginDeviceCheckFailure.SESSION_CHANGED,
        )
        cancelPostLoginDeviceCheckRuntime("session_changed_before_pass")
        announcePostLoginDeviceCheckTerminal(
            "로그인 세션이 변경되어 기기 점검 결과를 적용하지 않았습니다.",
        )
        updateStatus(
            "로그인 다시 확인 필요",
            postLoginDeviceCheckFailureMessage(PostLoginDeviceCheckFailure.SESSION_CHANGED),
        )
        refreshStartupCapabilityUi()
    }

    private fun cancelPostLoginDeviceCheckRuntime(reason: String) {
        cancelDeviceRuntimeCalibration("device_check_$reason")
        clearPostLoginDeviceCheckOverallTimeout()
        cancelPostLoginDeviceCheckFunctionalProbes()
        if (
            postLoginMetricPreflightStarted ||
            metricPreflightPostLoginBinding != null ||
            arSessionPurpose == ArSessionPurpose.PREFLIGHT
        ) {
            invalidateRuntimeMetricEvidence("post_login_device_check_$reason")
        } else {
            metricPreflightPostLoginBinding = null
        }
        if (::startupCapabilityProbe.isInitialized && startupCapabilityProbeStarted) {
            startupCapabilityProbe.close()
            startupCapabilityProbeStarted = false
        }
        storedDeviceCheckBindingValidationPending = false
        if (::walkSessionResourceProbe.isInitialized && walkSessionResourceProbeStarted) {
            resetWalkSessionResourceProbe()
        }
        postLoginDeviceCheckPermissionRequestCode?.let { requestCode ->
            permissionRequestLeases.remove(requestCode)
        }
        postLoginDeviceCheckPermissionRequestCode = null
        postLoginDeviceCheckPermissionResultPending = false
        postLoginDeviceCheckPendingPermissionBinding = null
        postLoginMetricPreflightStarted = false
        stopPostLoginCameraPipelinePreflight()
        if (reason != "session_changed" && ::startupCapabilityText.isInitialized) {
            updateNavigationStatus("postLoginDeviceCheck=cancelled reason=$reason")
        }
    }

    private fun isLocationServiceEnabledForDeviceCheck(): Boolean {
        val manager = getSystemService(LocationManager::class.java) ?: return false
        return runCatching {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                manager.isLocationEnabled
            } else {
                @Suppress("DEPRECATION")
                (manager.isProviderEnabled(LocationManager.GPS_PROVIDER) ||
                    manager.isProviderEnabled(LocationManager.NETWORK_PROVIDER))
            }
        }.getOrDefault(false)
    }

    private fun locationFixUnavailability(): DeviceCheckLocationFixUnavailability {
        if (!isLocationServiceEnabledForDeviceCheck()) {
            return DeviceCheckLocationFixUnavailability.LOCATION_SERVICE_OFF
        }
        val activeProviders = runCatching {
            getSystemService(LocationManager::class.java)?.getProviders(true)
        }.getOrNull()
        return if (activeProviders != null &&
            activeProviders.none { it != LocationManager.PASSIVE_PROVIDER }
        ) DeviceCheckLocationFixUnavailability.PROVIDER_DISABLED
        else DeviceCheckLocationFixUnavailability.NO_FIX_RECEIVED
    }

    @SuppressLint("MissingPermission")
    private fun startPostLoginLocationFixProbe(binding: PostLoginDeviceCheckBinding) {
        cancelPostLoginLocationFixProbe()
        postLoginLocationFixDecision = null
        if (
            !isPostLoginDeviceCheckBindingCurrent(binding) ||
            !::fusedLocationClient.isInitialized ||
            !hasLocationPermission() ||
            !isLocationServiceEnabledForDeviceCheck()
        ) {
            if (!isLocationServiceEnabledForDeviceCheck()) {
                postLoginLocationFixDecision = DeviceCheckLocationFixPolicy.unavailable(
                    DeviceCheckLocationFixUnavailability.LOCATION_SERVICE_OFF,
                )
            }
            postLoginLocationFixTerminalFailure =
                PostLoginLocationFixTerminalFailure.REQUEST_FAILED
            postLoginLocationFixSignal = PostLoginDeviceCheckSignal.UNAVAILABLE
            recordPostLoginLocationTerminalDiagnostic(
                passed = false,
                terminalFailure = PostLoginLocationFixTerminalFailure.REQUEST_FAILED,
            )
            maybeContinuePostLoginDeviceCheck(binding)
            return
        }
        val generation = ++postLoginLocationFixGeneration
        postLoginLocationFixSignal = PostLoginDeviceCheckSignal.PENDING
        postLoginLocationFixDecision = null
        postLoginLocationFixTerminalFailure = null
        lateinit var callback: LocationCallback
        callback = object : LocationCallback() {
            override fun onLocationResult(result: LocationResult) {
                if (!isPostLoginLocationFixProbeCurrent(binding, generation, callback)) return
                val decisions = result.locations.map(::evaluatePostLoginLocationFix)
                decisions.forEach(::recordPostLoginLocationFixDiagnostic)
                val decision = DeviceCheckLocationFixPolicy.selectBatch(decisions)
                if (decision != null) postLoginLocationFixDecision = decision
                if (decision?.reason == DeviceCheckLocationFixReason.MOCK_LOCATION) {
                    finishPostLoginLocationFixProbe(
                        binding = binding,
                        generation = generation,
                        callback = callback,
                        passed = false,
                        terminalFailure = null,
                    )
                } else if (decision?.passed == true) {
                    finishPostLoginLocationFixProbe(
                        binding = binding,
                        generation = generation,
                        callback = callback,
                        passed = true,
                        terminalFailure = null,
                    )
                }
            }
        }
        postLoginLocationFixCallback = callback
        lateinit var timeout: Runnable
        timeout = Runnable {
            if (
                postLoginLocationFixTimeout !== timeout ||
                !isPostLoginLocationFixProbeCurrent(binding, generation, callback)
            ) return@Runnable
            finishPostLoginLocationFixProbe(
                binding = binding,
                generation = generation,
                callback = callback,
                passed = false,
                terminalFailure = PostLoginLocationFixTerminalFailure.TIMED_OUT,
            )
        }
        val request = LocationRequest.Builder(
            Priority.PRIORITY_HIGH_ACCURACY,
            POST_LOGIN_LOCATION_FIX_INTERVAL_MS,
        )
            .setGranularity(Granularity.GRANULARITY_FINE)
            .setMaxUpdateAgeMillis(DeviceCheckLocationFixPolicy.MAX_AGE_MS)
            .setMinUpdateIntervalMillis(POST_LOGIN_LOCATION_FIX_MIN_INTERVAL_MS)
            // Deliver early samples as well; the local policy keeps rejecting them until
            // a fresh, real fix within the functional accuracy range arrives.
            .setWaitForAccurateLocation(false)
            .setDurationMillis(POST_LOGIN_LOCATION_FIX_TIMEOUT_MS)
            .build()
        val registration = runCatching {
            fusedLocationClient.requestLocationUpdates(
                request,
                callback,
                Looper.getMainLooper(),
            )
        }.getOrElse {
            finishPostLoginLocationFixProbe(
                binding = binding,
                generation = generation,
                callback = callback,
                passed = false,
                terminalFailure = PostLoginLocationFixTerminalFailure.REQUEST_FAILED,
            )
            return
        }
        postLoginLocationFixTimeout = timeout
        startupCapabilityText.postDelayed(
            timeout,
            POST_LOGIN_LOCATION_FIX_TIMEOUT_MS +
                POST_LOGIN_LOCATION_FIX_CALLBACK_GRACE_MS,
        )
        registration
            .addOnSuccessListener(ContextCompat.getMainExecutor(this)) {
                if (!isPostLoginLocationFixProbeCurrent(binding, generation, callback)) {
                    fusedLocationClient.removeLocationUpdates(callback)
                }
            }
            .addOnFailureListener(ContextCompat.getMainExecutor(this)) {
                if (!isPostLoginLocationFixProbeCurrent(binding, generation, callback)) {
                    fusedLocationClient.removeLocationUpdates(callback)
                    return@addOnFailureListener
                }
                finishPostLoginLocationFixProbe(
                    binding = binding,
                    generation = generation,
                    callback = callback,
                    passed = false,
                    terminalFailure = PostLoginLocationFixTerminalFailure.REQUEST_FAILED,
                )
            }
    }

    private fun isPostLoginDeviceCheckBindingCurrent(binding: PostLoginDeviceCheckBinding): Boolean =
        isActivityForeground &&
            postLoginDeviceCheckSnapshot.state == PostLoginDeviceCheckState.RUNNING &&
            isPostLoginDeviceCheckSnapshotBindingLive(binding)

    private fun isPostLoginLocationFixProbeCurrent(
        binding: PostLoginDeviceCheckBinding,
        generation: Long,
        callback: LocationCallback,
    ): Boolean =
        generation == postLoginLocationFixGeneration &&
            postLoginLocationFixCallback === callback &&
            isPostLoginDeviceCheckBindingCurrent(binding)

    @Suppress("DEPRECATION")
    private fun evaluatePostLoginLocationFix(location: Location): DeviceCheckLocationFixDecision {
        val nowMs = SystemClock.elapsedRealtime()
        return DeviceCheckLocationFixPolicy.evaluate(
            DeviceCheckLocationFixObservation(
                latitude = location.latitude,
                longitude = location.longitude,
                accuracyMeters = location.accuracy.takeIf { location.hasAccuracy() },
                observedAtElapsedRealtimeMs =
                    location.elapsedRealtimeNanos / NANOS_PER_MILLISECOND,
                nowElapsedRealtimeMs = nowMs,
                mock = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
                    location.isMock
                } else {
                    location.isFromMockProvider
                },
            ),
        )
    }

    private fun recordPostLoginLocationFixDiagnostic(
        decision: DeviceCheckLocationFixDecision,
    ) {
        postLoginLocationFixDecision = decision
        if (BuildConfig.DEBUG) {
            android.util.Log.d(
                GPS_PREFLIGHT_LOG_TAG,
                "reason=${decision.reason} accuracyMeters=${decision.accuracyMeters} " +
                    "ageMs=${decision.ageMs}",
            )
        }
        refreshStartupCapabilityUi()
    }

    private fun finishPostLoginLocationFixProbe(
        binding: PostLoginDeviceCheckBinding,
        generation: Long,
        callback: LocationCallback,
        passed: Boolean,
        terminalFailure: PostLoginLocationFixTerminalFailure?,
    ) {
        if (!isPostLoginLocationFixProbeCurrent(binding, generation, callback)) return
        if (!passed && postLoginLocationFixDecision == null &&
            terminalFailure == PostLoginLocationFixTerminalFailure.TIMED_OUT
        ) {
            postLoginLocationFixDecision = DeviceCheckLocationFixPolicy.unavailable(locationFixUnavailability())
        }
        if (BuildConfig.DEBUG && !passed) {
            android.util.Log.d(
                GPS_PREFLIGHT_LOG_TAG,
                "postLogin=${terminalFailure?.name} " +
                    "lastReason=${postLoginLocationFixDecision?.reason} " +
                    "lastAccuracyMeters=${postLoginLocationFixDecision?.accuracyMeters}",
            )
        }
        recordPostLoginLocationTerminalDiagnostic(passed, terminalFailure)
        cancelPostLoginLocationFixProbe()
        postLoginLocationFixTerminalFailure = terminalFailure
        postLoginLocationFixSignal = if (passed) {
            PostLoginDeviceCheckSignal.READY
        } else {
            PostLoginDeviceCheckSignal.UNAVAILABLE
        }
        maybeContinuePostLoginDeviceCheck(binding)
        refreshStartupCapabilityUi()
    }

    @SuppressLint("ApplySharedPref")
    private fun recordPostLoginLocationTerminalDiagnostic(
        passed: Boolean,
        terminalFailure: PostLoginLocationFixTerminalFailure?,
    ) {
        val accuracy = postLoginLocationFixDecision?.accuracyMeters
        val accuracyBucket = when {
            accuracy == null || !accuracy.isFinite() -> "unknown"
            accuracy <= DeviceCheckLocationFixPolicy.MAX_ACCURACY_METERS -> "0_15m"
            accuracy <= 25f -> "over_15_to_25m"
            accuracy <= 50f -> "over_25_to_50m"
            accuracy <= 100f -> "over_50_to_100m"
            else -> "over_100m"
        }
        val ageMs = postLoginLocationFixDecision?.ageMs
        val ageBucket = when {
            ageMs == null -> "unknown"
            ageMs < 0L -> "future"
            ageMs <= DeviceCheckLocationFixPolicy.MAX_AGE_MS -> "fresh"
            else -> "stale"
        }
        val result = if (passed) "pass" else "fail"
        val reason = postLoginLocationFixDecision?.reason?.name
            ?: terminalFailure?.name
            ?: "UNKNOWN"
        if (::stepLengthPrefs.isInitialized) {
            stepLengthPrefs.edit()
                .putString(PREF_DEVICE_CHECK_LOCATION_RESULT, result)
                .putString(PREF_DEVICE_CHECK_LOCATION_REASON, reason)
                .putString(PREF_DEVICE_CHECK_LOCATION_ACCURACY_BUCKET, accuracyBucket)
                .putString(PREF_DEVICE_CHECK_LOCATION_AGE_BUCKET, ageBucket)
                .commit()
        }
        if (::fieldSessionLog.isInitialized) {
            fieldSessionLog.recordEvent(
                "post_login_location_check_terminal",
                mapOf(
                    "result" to result,
                    "reason" to reason,
                    "accuracy_bucket" to accuracyBucket,
                    "age_bucket" to ageBucket,
                ),
            )
        }
    }

    private fun cancelPostLoginLocationFixProbe() {
        postLoginLocationFixGeneration += 1L
        postLoginLocationFixTimeout?.let { timeout ->
            if (::startupCapabilityText.isInitialized) startupCapabilityText.removeCallbacks(timeout)
        }
        postLoginLocationFixTimeout = null
        val callback = postLoginLocationFixCallback
        postLoginLocationFixCallback = null
        if (::fusedLocationClient.isInitialized) {
            callback?.let(fusedLocationClient::removeLocationUpdates)
        }
    }

    private fun awaitCameraXClosed(
        camera: CameraXCamera?,
        onComplete: (closed: Boolean) -> Unit,
    ) {
        if (camera == null) {
            onComplete(true)
            return
        }
        val startedAtMs = SystemClock.elapsedRealtime()
        lateinit var poll: Runnable
        poll = Runnable {
            val closed = runCatching {
                camera.cameraInfo.cameraState.value?.type == CameraState.Type.CLOSED
            }.getOrDefault(false)
            when {
                closed -> onComplete(true)
                SystemClock.elapsedRealtime() - startedAtMs >=
                    CAMERA_X_RELEASE_TIMEOUT_MS -> onComplete(false)
                else -> cameraReleaseHandler.postDelayed(
                    poll,
                    CAMERA_X_RELEASE_POLL_INTERVAL_MS,
                )
            }
        }
        cameraReleaseHandler.post(poll)
    }

    private fun requestPostLoginDeviceCheckHaptic(binding: PostLoginDeviceCheckBinding) {
        postLoginHapticProbe?.close()
        postLoginHapticProbe = null
        if (!isPostLoginDeviceCheckBindingCurrent(binding)) return
        val probe = AndroidDeviceCheckHapticProbe(this)
        postLoginHapticProbe = probe
        postLoginHapticSignal = if (probe.requestTestVibration()) {
            PostLoginDeviceCheckSignal.PENDING
        } else {
            PostLoginDeviceCheckSignal.UNAVAILABLE
        }
        refreshStartupCapabilityUi()
    }

    private fun confirmPostLoginDeviceCheckHaptic(felt: Boolean) {
        val binding = postLoginDeviceCheckSnapshot.bindingOrNull ?: return
        if (
            !isPostLoginDeviceCheckBindingCurrent(binding) ||
            postLoginHapticSignal != PostLoginDeviceCheckSignal.PENDING
        ) return
        postLoginHapticProbe?.close()
        postLoginHapticProbe = null
        postLoginHapticSignal = if (felt) {
            PostLoginDeviceCheckSignal.READY
        } else {
            PostLoginDeviceCheckSignal.UNAVAILABLE
        }
        maybeContinuePostLoginDeviceCheck(binding)
        refreshStartupCapabilityUi()
    }

    private fun beginPostLoginWakePhraseProbeFromUserAction() {
        val binding = postLoginDeviceCheckSnapshot.bindingOrNull ?: return
        if (
            !isPostLoginDeviceCheckBindingCurrent(binding) ||
            postLoginWakePhraseSignal != PostLoginDeviceCheckSignal.PENDING ||
            postLoginWakePhraseProbe != null ||
            postLoginWakePhraseStartRunnable != null ||
            handsFreeVoiceModelDirectory == null
        ) return
        postLoginWakePhraseUserStarted = true
        refreshStartupCapabilityUi()
        lateinit var start: Runnable
        start = Runnable {
            if (postLoginWakePhraseStartRunnable !== start) return@Runnable
            postLoginWakePhraseStartRunnable = null
            if (!isPostLoginDeviceCheckBindingCurrent(binding)) return@Runnable
            maybeStartPostLoginWakePhraseProbe(binding)
        }
        postLoginWakePhraseStartRunnable = start
        startupCapabilityText.post(start)
    }

    private fun maybeStartPostLoginWakePhraseProbe(binding: PostLoginDeviceCheckBinding) {
        if (
            !postLoginWakePhraseUserStarted ||
            postLoginWakePhraseSignal != PostLoginDeviceCheckSignal.PENDING ||
            postLoginWakePhraseProbe != null ||
            !isPostLoginDeviceCheckBindingCurrent(binding)
        ) return
        val modelDirectory = handsFreeVoiceModelDirectory
        if (modelDirectory == null) {
            if (handsFreeVoiceModelPreparationFailed) {
                postLoginWakePhraseSignal = PostLoginDeviceCheckSignal.UNAVAILABLE
                evaluatePostLoginDeviceCheck(binding)
                refreshStartupCapabilityUi()
            }
            return
        }
        stopHandsFreeVoiceService()
        lateinit var probe: VoskWakePhraseProbe
        probe = VoskWakePhraseProbe(
            context = applicationContext,
            modelDirectory = modelDirectory,
            isInputSuppressed = ::isHandsFreeVoiceOutputActive,
            onReady = {
                if (
                    postLoginWakePhraseProbe === probe &&
                    isPostLoginDeviceCheckBindingCurrent(binding)
                ) {
                    logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.WAKE_UI_READY, backend = OfflineSpeechEngine.VOSK)
                    postLoginWakePhraseReadyCue?.close()
                    postLoginWakePhraseReadyCue =
                        AndroidDeviceCheckHapticProbe(this).also { it.requestTestVibration() }
                }
            },
            onResult = { result ->
                if (postLoginWakePhraseProbe !== probe) return@VoskWakePhraseProbe
                postLoginWakePhraseProbe = null
                postLoginWakePhraseReadyCue?.close()
                postLoginWakePhraseReadyCue = null
                if (!isPostLoginDeviceCheckBindingCurrent(binding)) return@VoskWakePhraseProbe
                val available =
                    result.availability == VoskWakePhraseProbeAvailability.AVAILABLE
                logVoiceInputDiagnostic(
                    VoiceInputDiagnosticEvent.WAKE_UI_RESULT,
                    backend = OfflineSpeechEngine.VOSK,
                    matched = available,
                    failure = result.failure,
                    streamingError = result.streamingError,
                )
                postLoginWakePhraseSignal = available.toDeviceCheckSignal()
                if (available) {
                    announcePostLoginDeviceCheckProgress("호출어 인식 시험을 통과했습니다.")
                }
                maybeContinuePostLoginDeviceCheck(binding)
                refreshStartupCapabilityUi()
            },
        )
        postLoginWakePhraseProbe = probe
        if (!probe.start()) {
            updateNavigationStatus("postLoginDeviceCheck=vosk_probe_start_failed")
        } else {
            updateNavigationStatus("postLoginDeviceCheck=vosk_wake_phrase_listening")
            refreshStartupCapabilityUi()
        }
    }

    private fun cancelPostLoginWakePhraseProbe() {
        postLoginWakePhraseStartRunnable?.let { start ->
            if (::startupCapabilityText.isInitialized) {
                startupCapabilityText.removeCallbacks(start)
            }
        }
        postLoginWakePhraseStartRunnable = null
        postLoginWakePhraseUserStarted = false
        val probe = postLoginWakePhraseProbe
        postLoginWakePhraseProbe = null
        probe?.cancel()
        postLoginWakePhraseReadyCue?.close()
        postLoginWakePhraseReadyCue = null
    }

    private fun announcePostLoginDeviceCheckProgress(message: String) {
        if (
            !::postLoginDeviceCheckLiveStatusText.isInitialized ||
            postLoginDeviceCheckLastLiveStatus == message
        ) return
        postLoginDeviceCheckLastLiveStatus = message
        postLoginDeviceCheckLiveStatusText.accessibilityLiveRegion =
            View.ACCESSIBILITY_LIVE_REGION_POLITE
        postLoginDeviceCheckLiveStatusText.visibility = View.VISIBLE
        postLoginDeviceCheckLiveStatusText.text = message
    }

    private fun announcePostLoginDeviceCheckTerminal(message: String) {
        if (!::postLoginDeviceCheckLiveStatusText.isInitialized) return
        postLoginDeviceCheckLastLiveStatus = message
        // Terminal text owns accessibility focus, so it must not also emit a live-region
        // announcement of the same sentence.
        postLoginDeviceCheckLiveStatusText.accessibilityLiveRegion =
            View.ACCESSIBILITY_LIVE_REGION_NONE
        postLoginDeviceCheckLiveStatusText.visibility = View.VISIBLE
        postLoginDeviceCheckLiveStatusText.text = message
        if (!isScreenReaderActive()) return
        postLoginDeviceCheckLiveStatusText.post {
            if (
                postLoginDeviceCheckSnapshot.state != PostLoginDeviceCheckState.FAIL ||
                !postLoginDeviceCheckLiveStatusText.isShown
            ) return@post
            postLoginDeviceCheckLiveStatusText.performAccessibilityAction(
                android.view.accessibility.AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS,
                null,
            )
        }
    }

    private fun clearPostLoginDeviceCheckOverallTimeout() {
        postLoginDeviceCheckOverallTimeout?.let { timeout ->
            if (::startupCapabilityText.isInitialized) startupCapabilityText.removeCallbacks(timeout)
        }
        postLoginDeviceCheckOverallTimeout = null
    }

    private fun cancelPostLoginDeviceCheckFunctionalProbes() {
        cancelPostLoginLocationFixProbe()
        cancelPostLoginWakePhraseProbe()
        postLoginHapticProbe?.close()
        postLoginHapticProbe = null
    }

    private fun Boolean?.toDeviceCheckSignal(): PostLoginDeviceCheckSignal = when (this) {
        true -> PostLoginDeviceCheckSignal.READY
        false -> PostLoginDeviceCheckSignal.UNAVAILABLE
        null -> PostLoginDeviceCheckSignal.PENDING
    }

    private fun postLoginDeviceCheckDisabledFeatureText(): String = buildList {
        currentPostLoginDisabledFeatures()
            .sortedBy(PostLoginDeviceCheckFeature::ordinal)
            .forEach { feature ->
                add(
                    when (feature) {
                        PostLoginDeviceCheckFeature.OBSTACLE_DETECTION -> "장애물 인식"
                        PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE -> "미터 거리 안내"
                        PostLoginDeviceCheckFeature.LOCATION_GUIDANCE -> "위치·경로 안내"
                        PostLoginDeviceCheckFeature.HANDS_FREE_VOICE -> if (
                            feature in postLoginDeviceCheckSnapshot.disabledFeatures ||
                            !hasRecordAudioPermission() ||
                            (
                                ::startupCapabilityProbe.isInitialized &&
                                    startupCapabilityProbe.snapshot()
                                        .onDeviceSpeechRecognitionAvailable == false
                            )
                        ) {
                            "호출어·음성 명령"
                        } else {
                            "호출어 대기"
                        }
                        PostLoginDeviceCheckFeature.VOICE_GUIDANCE -> "음성 안내"
                        PostLoginDeviceCheckFeature.HAPTIC_FEEDBACK -> "진동 알림"
                    },
                )
            }
        if (
            postLoginDeviceCheckSnapshot.passesFeatureGate &&
            !postLoginDeviceFeatureEnabled(
                PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE,
            )
        ) {
            add("카메라 기반 신고")
        }
        if (
            postLoginDeviceCheckSnapshot.passesFeatureGate &&
            !postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE)
        ) {
            add("위치가 필요한 신고")
        }
        if (
            postLoginDeviceCheckSnapshot.passesFeatureGate &&
            !hasActivityRecognitionPermission()
        ) {
            add("걸음 수 추적·정지 확인 후 대기 신고 자동 전송")
        }
    }.joinToString(", ")

    private fun hasCurrentPostLoginDeviceRestrictions(): Boolean =
        currentPostLoginDisabledFeatures().isNotEmpty() ||
            (
                postLoginDeviceCheckSnapshot.passesFeatureGate &&
                    !hasActivityRecognitionPermission()
            )

    private fun currentPostLoginDisabledFeatures(): Set<PostLoginDeviceCheckFeature> = buildSet {
        if (!developmentQuickStartEnabled) {
            addAll(postLoginDeviceCheckSnapshot.disabledFeatures)
            if (!postLoginDeviceCheckSnapshot.passesFeatureGate) return@buildSet
        }
        if (postLoginCameraDependentChecksDeferred) {
            add(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION)
            add(PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE)
        }
        if (runtimeObstacleDetectionCapabilityOverride == false) {
            add(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION)
        }
        if (metricDistanceCapabilityOverride == false) {
            add(PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE)
        }
        if (!hasCameraPermission()) {
            add(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION)
            add(PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE)
        }
        if (!hasLocationPermission() || !isLocationServiceEnabledForDeviceCheck()) {
            add(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE)
        }
        if (
            ::startupCapabilityProbe.isInitialized &&
            startupCapabilityProbe.snapshot().onDeviceSpeechRecognitionAvailable == false
        ) {
            add(PostLoginDeviceCheckFeature.HANDS_FREE_VOICE)
        }
        if (
            offlineKoreanTextToSpeechCapabilityOverride == false ||
            (
                ::startupCapabilityProbe.isInitialized &&
                    startupCapabilityProbe.snapshot().offlineKoreanTextToSpeechAvailable == false
            )
        ) {
            add(PostLoginDeviceCheckFeature.VOICE_GUIDANCE)
        }
        if (
            !hasRecordAudioPermission() ||
            !hasHandsFreeNotificationPermission() ||
            !isHandsFreeVoiceDisclosureAccepted()
        ) {
            add(PostLoginDeviceCheckFeature.HANDS_FREE_VOICE)
        }
    }

    private fun postLoginDeviceFeatureEnabled(feature: PostLoginDeviceCheckFeature): Boolean =
        developmentGuidanceStartBypassEnabled ||
            ((developmentQuickStartEnabled || postLoginDeviceCheckPassesFeatureGate()) &&
                feature !in currentPostLoginDisabledFeatures())

    private fun deferredCameraDependentChecksCanBeRetried(): Boolean =
        postLoginDeviceCheckSnapshot.passesFeatureGate &&
            postLoginCameraDependentChecksDeferred &&
            hasCameraPermission()

    private fun cameraAnalysisFeaturesEnabled(): Boolean =
        postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION) ||
            postLoginDeviceFeatureEnabled(
                PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE,
            )

    private fun terminalCameraDetectorStatusText(): String? {
        if (!postLoginDeviceCheckSnapshot.passesFeatureGate) return null
        return when {
            postLoginCameraDependentChecksDeferred ->
                if (hasCameraPermission()) "재점검 필요" else "권한 허용 후 재점검 필요"
            !postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION) ->
                "제한"
            !detectorLoadAttempted -> "통과 · 보행 시작 시 모델 재확인"
            detectorAvailable -> "통과"
            else -> "제한"
        }
    }

    private fun terminalMetricDistanceStatusText(): String? {
        if (!postLoginDeviceCheckSnapshot.passesFeatureGate) return null
        return when {
            postLoginCameraDependentChecksDeferred ->
                if (hasCameraPermission()) "재점검 필요" else "권한 허용 후 재점검 필요"
            postLoginMetricDepthState == PostLoginMetricDepthState.UNKNOWN ->
                "확인 불가(AR 서비스·권한 확인)"
            !postLoginDeviceFeatureEnabled(
                PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE,
            ) -> "제한(거리 제한 모드)"
            postLoginMetricDepthState == PostLoginMetricDepthState.SUPPORTED ->
                "지원"
            postLoginMetricDepthState == PostLoginMetricDepthState.PENDING ->
                "지원 확인 대기"
            else -> null
        }
    }

    private fun postLoginDeviceCheckItemsMessage(): String {
        val state = postLoginDeviceCheckSnapshot.state
        if (state == PostLoginDeviceCheckState.NOT_RUN) {
            return "항목별 상태: 점검 시작 전"
        }
        if (state == PostLoginDeviceCheckState.REQUESTING_PERMISSIONS) {
            return "항목별 상태: Android 권한 확인 중"
        }
        val observation = currentPostLoginDeviceCheckObservation()
        val startup = startupCapabilityProbe.snapshot()
        fun combined(vararg signals: PostLoginDeviceCheckSignal): PostLoginDeviceCheckSignal = when {
            signals.any { it == PostLoginDeviceCheckSignal.UNAVAILABLE } ->
                PostLoginDeviceCheckSignal.UNAVAILABLE
            signals.any { it == PostLoginDeviceCheckSignal.PENDING } ->
                PostLoginDeviceCheckSignal.PENDING
            else -> PostLoginDeviceCheckSignal.READY
        }
        fun label(
            signal: PostLoginDeviceCheckSignal,
            pending: String = "검사 중",
            unavailable: String = "제한",
        ): String = when (signal) {
            PostLoginDeviceCheckSignal.PENDING -> pending
            PostLoginDeviceCheckSignal.READY -> "통과"
            PostLoginDeviceCheckSignal.UNAVAILABLE -> unavailable
        }
        val microphoneText = if (!hasRecordAudioPermission()) {
            "제한(마이크 권한 필요)"
        } else {
            label(
                combined(
                    startup.microphoneAvailable.toDeviceCheckSignal(),
                    observation.wakePhraseRecognition,
                ),
                "확인 필요",
            )
        }
        val locationText = if (!hasLocationPermission()) {
            "제한(정확한 위치 권한 필요)"
        } else {
            label(
                combined(
                    startup.gpsAvailable.toDeviceCheckSignal(),
                    observation.locationService,
                ),
            )
        }
        val cameraPending = if (postLoginCameraPipelinePreflightActive) {
            "카메라·모델 실행 중"
        } else {
            "검사 대기"
        }
        val cameraText = terminalCameraDetectorStatusText() ?: if (
            postLoginCameraDependentChecksDeferred
        ) {
            if (hasCameraPermission()) "재점검 필요" else "권한 허용 후 재점검 필요"
        } else {
            label(
                combined(
                    startup.cameraAvailable.toDeviceCheckSignal(),
                    observation.detector,
                    observation.cameraPipeline,
                ),
                cameraPending,
            )
        }
        val distanceText = terminalMetricDistanceStatusText() ?: if (
            postLoginCameraDependentChecksDeferred
        ) {
            if (hasCameraPermission()) "재점검 필요" else "권한 허용 후 재점검 필요"
        } else when (observation.metricDepth) {
            PostLoginMetricDepthState.PENDING -> "지원 확인 중"
            PostLoginMetricDepthState.SUPPORTED -> "지원"
            PostLoginMetricDepthState.AVAILABLE -> "실측 확인"
            PostLoginMetricDepthState.EXPLICITLY_UNSUPPORTED -> "제한(거리 제한 모드)"
            PostLoginMetricDepthState.UNKNOWN -> "확인 불가(AR 서비스·권한 확인)"
            PostLoginMetricDepthState.TIMED_OUT -> "제한(측정 시간 초과)"
        }
        return listOf(
            "ARCore Depth\t$distanceText",
            "카메라\t$cameraText",
            "위치\t$locationText",
            "한국어 음성\t${label(observation.koreanTextToSpeech, "확인 중")}",
            "호출어\t$microphoneText",
            "기기 상태\t${postLoginResourceWaitNotice ?: label(observation.deviceResources, "상태 확인 중", "배터리·저장공간·발열 확인 필요")}",
        ).joinToString(separator = "\n")
    }

    private fun postLoginDeviceCheckPermissionLabel(permission: String): String = when (permission) {
        Manifest.permission.CAMERA -> "카메라"
        Manifest.permission.ACCESS_FINE_LOCATION,
        Manifest.permission.ACCESS_COARSE_LOCATION,
        -> "위치"
        Manifest.permission.RECORD_AUDIO -> "마이크"
        Manifest.permission.ACTIVITY_RECOGNITION -> "신체 활동"
        Manifest.permission.POST_NOTIFICATIONS -> "알림"
        else -> "필수 권한"
    }

    private fun postLoginDeviceCheckFailureMessage(
        failure: PostLoginDeviceCheckFailure?,
    ): String = when (failure) {
        PostLoginDeviceCheckFailure.BACKGROUNDED ->
            "점검 중 앱이 전경을 벗어났습니다. 앱으로 돌아와 다시 점검하세요."
        PostLoginDeviceCheckFailure.MINIMUM_ANDROID_VERSION ->
            "Android 12 이상이 필요합니다."
        PostLoginDeviceCheckFailure.REQUIRED_PERMISSION ->
            "카메라·정확한 위치·마이크·신체 활동·알림 권한을 허용한 뒤 다시 점검하세요."
        PostLoginDeviceCheckFailure.VOICE_DISCLOSURE_NOT_PERSISTED ->
            "호출어 음성 처리 안내 확인을 저장하지 못했습니다. 앱 저장공간을 확인한 뒤 다시 점검하세요."
        PostLoginDeviceCheckFailure.CORE_HARDWARE_OR_SERVICE ->
            "필수 기능 중 일부를 사용할 수 없습니다. 위의 사용할 수 없는 기능 목록을 확인하세요."
        PostLoginDeviceCheckFailure.LOCATION_SERVICE_DISABLED ->
            "Android 위치 서비스를 켠 뒤 다시 점검하세요."
        PostLoginDeviceCheckFailure.LOCATION_FIX_UNAVAILABLE ->
            postLoginLocationFixFailureMessage()
        PostLoginDeviceCheckFailure.DEVICE_RESOURCE ->
            "배터리·저장공간·발열 상태를 정상화한 뒤 다시 점검하세요."
        PostLoginDeviceCheckFailure.DETECTOR_UNAVAILABLE ->
            "기기 내 장애물 탐지 모델을 실행할 수 없습니다."
        PostLoginDeviceCheckFailure.CAMERA_PIPELINE_UNAVAILABLE -> when (
            postLoginCameraPipelineFailure
        ) {
            PostLoginCameraPipelineFailure.PERMISSION_OR_MODEL_UNAVAILABLE ->
                "카메라 권한 또는 기기 내 탐지 모델을 사용할 수 없습니다. 권한과 모델 상태를 확인하세요."
            PostLoginCameraPipelineFailure.CAMERA_RESOURCE_BUSY ->
                "다른 보행 또는 카메라 점검이 실행 중입니다. 실행 중인 점검을 끝낸 뒤 다시 시도하세요."
            PostLoginCameraPipelineFailure.BIND_FAILED ->
                "카메라를 열지 못했습니다. 다른 카메라 앱을 닫은 뒤 다시 점검하세요."
            PostLoginCameraPipelineFailure.NO_VALID_FRAME ->
                "점검 시간 안에 유효한 카메라 영상을 받지 못했습니다. 다른 카메라 앱을 닫고 다시 시도하세요."
            PostLoginCameraPipelineFailure.DETECTOR_FAILED ->
                "카메라 영상은 받았지만 기기 내 탐지 모델 실행을 확인하지 못했습니다. 앱을 다시 시작한 뒤 점검하세요."
            PostLoginCameraPipelineFailure.RELEASE_TIMED_OUT ->
                "카메라 점검을 끝냈지만 카메라 자원이 닫히지 않았습니다. 앱을 다시 시작한 뒤 점검하세요."
            PostLoginCameraPipelineFailure.TIMED_OUT ->
                "카메라와 기기 내 탐지 모델 점검 시간이 초과되었습니다. 잠시 후 다시 시도하세요."
            null ->
                "카메라 영상과 기기 내 탐지 모델을 함께 실행할 수 없습니다. 다시 점검하세요."
        }
        PostLoginDeviceCheckFailure.KOREAN_TTS_UNAVAILABLE ->
            "한국어 안내 음성을 실제로 만들지 못했습니다. 한국어 음성 데이터를 설치한 뒤 다시 점검하세요."
        PostLoginDeviceCheckFailure.WAKE_PHRASE_UNAVAILABLE ->
            "기기 내 음성 모델이 ‘길라잡이’를 인식하지 못했습니다. 조용한 곳에서 다시 점검하세요."
        PostLoginDeviceCheckFailure.HAPTIC_UNAVAILABLE ->
            "시험 진동을 확인하지 못했습니다. 진동 설정과 기기 상태를 확인하세요."
        PostLoginDeviceCheckFailure.DEPTH_UNKNOWN ->
            "거리 기능 상태를 확정하지 못했습니다. 잠시 후 다시 점검하세요."
        PostLoginDeviceCheckFailure.DEPTH_TIMEOUT ->
            "거리 측정 점검 시간이 초과되었습니다. 전경에서 다시 점검하세요."
        PostLoginDeviceCheckFailure.CHECK_TIMEOUT ->
            postLoginResourceWaitNotice?.let { "기기 점검 시간이 초과되었습니다. $it" }
                ?: "기기 점검을 완료하지 못했습니다. 화면의 대기 중 항목을 확인하고 다시 점검하세요."
        PostLoginDeviceCheckFailure.RESULT_SAVE_FAILED ->
            "기기 점검 결과를 저장하지 못했습니다. 저장공간을 확인하고 다시 점검하세요."
        PostLoginDeviceCheckFailure.SESSION_CHANGED,
        null,
        -> "로그인 세션이 변경되었습니다. 다시 로그인하고 점검하세요."
    }

    private fun postLoginLocationFixFailureMessage(): String {
        DeviceCheckLocationFixUnavailability.entries
            .firstOrNull { it.reason == postLoginLocationFixDecision?.reason }
            ?.let { return it.userActionKo }
        if (
            postLoginLocationFixTerminalFailure ==
            PostLoginLocationFixTerminalFailure.REQUEST_FAILED
        ) {
            return "Android 위치 요청을 시작하지 못했습니다. 앱의 정확한 위치 권한과 위치 서비스를 확인한 뒤 다시 점검하세요."
        }
        return when (postLoginLocationFixDecision?.reason) {
            DeviceCheckLocationFixReason.MOCK_LOCATION ->
                "모의 위치가 감지되어 통과시키지 않았습니다. 개발자 옵션의 모의 위치 앱을 끄고 다시 점검하세요."
            DeviceCheckLocationFixReason.ACCURACY_OUTSIDE_FUNCTIONAL_RANGE -> {
                val accuracy = postLoginLocationFixDecision?.accuracyMeters
                    ?.takeIf { it.isFinite() }
                    ?.let { String.format(Locale.US, "%.0f", it) }
                    ?: "확인 불가"
                "새 위치는 받았지만 추정 오차 범위가 약 ${accuracy}미터로 기능 점검 기준 " +
                    "${DeviceCheckLocationFixPolicy.MAX_ACCURACY_METERS.toInt()}미터를 넘었습니다. " +
                    "창가나 실외에서 다시 점검하세요."
            }
            DeviceCheckLocationFixReason.STALE ->
                "새 위치 대신 오래된 위치만 수신했습니다. 위치 서비스를 껐다 켠 뒤 창가나 실외에서 다시 점검하세요."
            DeviceCheckLocationFixReason.FUTURE_TIMESTAMP,
            DeviceCheckLocationFixReason.INVALID_COORDINATES,
            DeviceCheckLocationFixReason.ACCURACY_UNAVAILABLE,
            DeviceCheckLocationFixReason.ACCURACY_INVALID,
            -> "수신한 위치값이 유효하지 않았습니다. 위치 서비스를 껐다 켠 뒤 다시 점검하세요."
            DeviceCheckLocationFixReason.PASS ->
                "위치 수신 뒤 점검 상태가 변경되었습니다. 기기 점검을 다시 실행하세요."
            DeviceCheckLocationFixReason.LOCATION_SERVICE_OFF,
            DeviceCheckLocationFixReason.PROVIDER_DISABLED,
            DeviceCheckLocationFixReason.NO_FIX_RECEIVED,
            -> DeviceCheckLocationFixUnavailability.entries
                .first { it.reason == postLoginLocationFixDecision?.reason }
                .userActionKo
            null ->
                "점검 시간 안에 새 위치를 받지 못했습니다. 정확한 위치를 켜고 창가나 실외에서 다시 점검하세요."
        }
    }

    /** Proves the camera and production detector path before either FULL or LIMITED admission. */
    @androidx.annotation.OptIn(markerClass = [ExperimentalGetImage::class])
    private fun startPostLoginCameraPipelinePreflight(
        binding: PostLoginDeviceCheckBinding,
    ) {
        if (
            postLoginCameraPipelinePreflightActive ||
            !isPostLoginDeviceCheckBindingCurrent(binding)
        ) return
        if (postLoginCameraPipelineCleanupPending) {
            updateNavigationStatus("postLoginDeviceCheck=camera_cleanup_pending")
            return
        }
        if (cameraXReleaseBlocked) {
            postLoginCameraPipelineFailure =
                PostLoginCameraPipelineFailure.RELEASE_TIMED_OUT
            postLoginCameraPipelineSignal = PostLoginDeviceCheckSignal.UNAVAILABLE
            evaluatePostLoginDeviceCheck(binding)
            return
        }
        if (!hasCameraPermission() || !detectorAvailable) {
            postLoginCameraPipelineFailure =
                PostLoginCameraPipelineFailure.PERMISSION_OR_MODEL_UNAVAILABLE
            postLoginCameraPipelineSignal = PostLoginDeviceCheckSignal.UNAVAILABLE
            evaluatePostLoginDeviceCheck(binding)
            return
        }
        if (
            officialEnvironmentCameraPreflightActive ||
            officialEnvironmentCameraCleanupPending ||
            cameraFallbackCleanupPending ||
            cameraFallbackRequested ||
            cameraFallbackRunning ||
            arSessionPurpose != ArSessionPurpose.NONE ||
            session != null
        ) {
            postLoginCameraPipelineFailure = PostLoginCameraPipelineFailure.CAMERA_RESOURCE_BUSY
            postLoginCameraPipelineSignal = PostLoginDeviceCheckSignal.UNAVAILABLE
            evaluatePostLoginDeviceCheck(binding)
            return
        }
        val generation = ++postLoginCameraPipelineGeneration
        postLoginCameraPipelinePreflightActive = true
        postLoginCameraPipelineSignal = PostLoginDeviceCheckSignal.PENDING
        postLoginCameraPipelineFailure = null
        val terminalClaim = AtomicBoolean(false)
        postLoginCameraPipelineTerminalClaim = terminalClaim
        val lifecycleOwner = CameraFallbackLifecycleOwner().also {
            it.moveTo(Lifecycle.State.CREATED)
            it.moveTo(Lifecycle.State.RESUMED)
        }
        postLoginCameraPipelineLifecycleOwner = lifecycleOwner
        lateinit var timeout: Runnable
        timeout = Runnable {
            if (
                postLoginCameraPipelineTimeout !== timeout ||
                !isPostLoginCameraPipelinePreflightCurrent(binding, generation)
            ) return@Runnable
            if (!terminalClaim.compareAndSet(false, true)) return@Runnable
            finishPostLoginCameraPipelinePreflight(
                binding = binding,
                generation = generation,
                detectorSucceeded = false,
                failure = PostLoginCameraPipelineFailure.TIMED_OUT,
            )
        }
        postLoginCameraPipelineTimeout = timeout
        startupCapabilityText.postDelayed(timeout, POST_LOGIN_CAMERA_PIPELINE_TIMEOUT_MS)
        val providerFuture = ProcessCameraProvider.getInstance(this)
        providerFuture.addListener(
            {
                if (!isPostLoginCameraPipelinePreflightCurrent(binding, generation)) {
                    return@addListener
                }
                try {
                    val provider = providerFuture.get()
                    val resolutionSelector = ResolutionSelector.Builder()
                        .setResolutionStrategy(
                            ResolutionStrategy(
                                Size(CAMERA_FALLBACK_WIDTH, CAMERA_FALLBACK_HEIGHT),
                                ResolutionStrategy.FALLBACK_RULE_CLOSEST_LOWER_THEN_HIGHER,
                            ),
                        )
                        .build()
                    val analysis = ImageAnalysis.Builder()
                        .setResolutionSelector(resolutionSelector)
                        .setTargetRotation(displayRotation())
                        .setOutputImageFormat(ImageAnalysis.OUTPUT_IMAGE_FORMAT_YUV_420_888)
                        .setOutputImageRotationEnabled(true)
                        .setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST)
                        .build()
                    val frameClaimed = AtomicBoolean(false)
                    val attemptedFrames = AtomicInteger(0)
                    val passedFrames = AtomicInteger(0)
                    analysis.setAnalyzer(detectorExecutor) { imageProxy ->
                        if (!isPostLoginCameraPipelinePreflightCurrent(binding, generation)) {
                            imageProxy.close()
                            return@setAnalyzer
                        }
                        if (!frameClaimed.compareAndSet(false, true)) {
                            imageProxy.close()
                            return@setAnalyzer
                        }
                        var frameFailure = PostLoginCameraPipelineFailure.NO_VALID_FRAME
                        val detectorSucceeded = try {
                            val mediaImage = imageProxy.image
                            if (mediaImage == null) {
                                false
                            } else {
                                frameFailure = PostLoginCameraPipelineFailure.DETECTOR_FAILED
                                val result = frameDetector.detect(
                                    cameraImage = mediaImage,
                                    timestampMs =
                                        imageProxy.imageInfo.timestamp /
                                            NANOS_PER_MILLISECOND,
                                )
                                mediaImage.width > 0 &&
                                    mediaImage.height > 0 &&
                                    imageProxy.imageInfo.timestamp > 0L &&
                                    DeviceCheckDetectorExecutionPolicy.passes(result)
                            }
                        } catch (_: RuntimeException) {
                            false
                        } finally {
                            imageProxy.close()
                        }
                        // Count successful camera/model invocations, not detection accuracy.
                        val attempts = attemptedFrames.incrementAndGet()
                        val passes = if (detectorSucceeded) {
                            passedFrames.incrementAndGet()
                        } else {
                            passedFrames.get()
                        }
                        val verdict = DeviceCheckCameraSamplingPolicy.evaluate(attempts, passes)
                        if (verdict != DeviceCheckCameraSampleVerdict.CONTINUE) {
                            val sampleSucceeded =
                                verdict == DeviceCheckCameraSampleVerdict.PASSED
                            if (BuildConfig.DEBUG && !sampleSucceeded) {
                                android.util.Log.d(
                                    CAMERA_PREFLIGHT_LOG_TAG,
                                    "postLogin generation=$generation attempts=$attempts " +
                                        "passes=$passes reason=$frameFailure",
                                )
                            }
                            if (terminalClaim.compareAndSet(false, true)) {
                                runOnUiThread {
                                    finishPostLoginCameraPipelinePreflight(
                                        binding = binding,
                                        generation = generation,
                                        detectorSucceeded = sampleSucceeded,
                                        failure = if (sampleSucceeded) null else frameFailure,
                                    )
                                }
                            }
                        } else {
                            frameClaimed.set(false)
                        }
                    }
                    postLoginCameraPipelineProvider = provider
                    postLoginCameraPipelineAnalysis = analysis
                    postLoginCameraPipelineCamera = provider.bindToLifecycle(
                        lifecycleOwner,
                        CameraSelector.DEFAULT_BACK_CAMERA,
                        analysis,
                    )
                } catch (_: Exception) {
                    if (terminalClaim.compareAndSet(false, true)) {
                        finishPostLoginCameraPipelinePreflight(
                            binding = binding,
                            generation = generation,
                            detectorSucceeded = false,
                            failure = PostLoginCameraPipelineFailure.BIND_FAILED,
                        )
                    }
                }
            },
            ContextCompat.getMainExecutor(this),
        )
    }

    private fun isPostLoginCameraPipelinePreflightCurrent(
        binding: PostLoginDeviceCheckBinding,
        generation: Long,
    ): Boolean =
        postLoginCameraPipelinePreflightActive &&
            generation == postLoginCameraPipelineGeneration &&
            isActivityForeground &&
            postLoginDeviceCheckSnapshot.state == PostLoginDeviceCheckState.RUNNING &&
            PostLoginDeviceCheckPolicy.isCurrent(postLoginDeviceCheckSnapshot, binding) &&
            isPostLoginDeviceCheckSessionBindingLive(binding)

    private fun finishPostLoginCameraPipelinePreflight(
        binding: PostLoginDeviceCheckBinding,
        generation: Long,
        detectorSucceeded: Boolean,
        failure: PostLoginCameraPipelineFailure? = null,
    ) {
        if (!isPostLoginCameraPipelinePreflightCurrent(binding, generation)) return
        postLoginCameraPipelineFailure = if (detectorSucceeded) null else failure
        postLoginCameraPipelineSignal = if (detectorSucceeded) {
            PostLoginDeviceCheckSignal.READY
        } else {
            PostLoginDeviceCheckSignal.UNAVAILABLE
        }
        // The stop path continues the state machine only after the analyzer barrier and
        // owned CameraX use case release. Starting ARCore from this stack races the camera.
        stopPostLoginCameraPipelinePreflight()
        refreshStartupCapabilityUi()
    }

    private fun stopPostLoginCameraPipelinePreflight() {
        if (
            !postLoginCameraPipelinePreflightActive &&
            postLoginCameraPipelineProvider == null &&
            postLoginCameraPipelineCamera == null &&
            postLoginCameraPipelineAnalysis == null &&
            postLoginCameraPipelineLifecycleOwner == null
        ) return
        postLoginCameraPipelineTerminalClaim?.set(true)
        postLoginCameraPipelineTerminalClaim = null
        postLoginCameraPipelinePreflightActive = false
        postLoginCameraPipelineGeneration += 1L
        postLoginCameraPipelineTimeout?.let { timeout ->
            if (::startupCapabilityText.isInitialized) {
                startupCapabilityText.removeCallbacks(timeout)
            }
        }
        postLoginCameraPipelineTimeout = null
        val ownedProvider = postLoginCameraPipelineProvider
        val ownedCamera = postLoginCameraPipelineCamera
        val ownedAnalysis = postLoginCameraPipelineAnalysis
        val ownedLifecycleOwner = postLoginCameraPipelineLifecycleOwner
        postLoginCameraPipelineProvider = null
        postLoginCameraPipelineCamera = null
        postLoginCameraPipelineAnalysis = null
        postLoginCameraPipelineLifecycleOwner = null
        ownedAnalysis?.clearAnalyzer()
        val releaseClaim = AtomicBoolean(false)
        val analyzerBarrierTimedOut = AtomicBoolean(false)
        lateinit var release: Runnable
        lateinit var releaseDeadline: Runnable
        release = Runnable {
            if (!releaseClaim.compareAndSet(false, true)) return@Runnable
            cameraReleaseHandler.removeCallbacks(releaseDeadline)
            if (ownedAnalysis != null) {
                runCatching { ownedProvider?.unbind(ownedAnalysis) }
            }
            ownedLifecycleOwner?.moveTo(Lifecycle.State.DESTROYED)
            awaitCameraXClosed(ownedCamera) { closed ->
                postLoginCameraPipelineCleanupPending = false
                val releasedSafely = closed && !analyzerBarrierTimedOut.get()
                if (!releasedSafely) {
                    cameraXReleaseBlocked = true
                    postLoginCameraPipelineFailure =
                        PostLoginCameraPipelineFailure.RELEASE_TIMED_OUT
                    postLoginCameraPipelineSignal = PostLoginDeviceCheckSignal.UNAVAILABLE
                }
                val currentBinding = postLoginDeviceCheckSnapshot.bindingOrNull
                if (
                    currentBinding != null &&
                    postLoginDeviceCheckSnapshot.state == PostLoginDeviceCheckState.RUNNING &&
                    PostLoginDeviceCheckPolicy.isCurrent(
                        postLoginDeviceCheckSnapshot,
                        currentBinding,
                    )
                ) {
                    maybeContinuePostLoginDeviceCheck(currentBinding)
                }
                if (
                    ::startupCapabilityText.isInitialized &&
                    !isFinishing &&
                    !isDestroyed
                ) {
                    refreshStartupCapabilityUi()
                }
            }
            Unit
        }
        releaseDeadline = Runnable {
            analyzerBarrierTimedOut.set(true)
            release.run()
        }
        postLoginCameraPipelineCleanupPending =
            ownedAnalysis != null || ownedCamera != null
        if (ownedAnalysis == null) {
            release.run()
            return
        }
        cameraReleaseHandler.postDelayed(
            releaseDeadline,
            CAMERA_ANALYZER_RELEASE_BARRIER_TIMEOUT_MS,
        )
        try {
            detectorExecutor.execute {
                runOnUiThread(release)
            }
        } catch (_: RejectedExecutionException) {
            analyzerBarrierTimedOut.set(true)
            runOnUiThread(release)
        }
    }

    private fun currentFirstRunAsyncLease(): FirstRunAsyncLease =
        FirstRunAsyncLease(
            epoch = firstRunOnboardingSnapshot.epoch,
            revision = firstRunOnboardingSnapshot.revision,
            stage = firstRunOnboardingSnapshot.stage,
        )

    private fun isFirstRunAsyncLeaseCurrent(lease: FirstRunAsyncLease): Boolean =
        ::firstRunOnboardingSnapshot.isInitialized &&
            lease == currentFirstRunAsyncLease()

    private fun observeWalkRuntimeResourceSafety(
        expectedEpoch: WalkRuntimeEpoch? = null,
    ): Boolean {
        if (!::walkSessionLifecycle.isInitialized || !::walkSessionResourceProbe.isInitialized) {
            return true
        }
        val runtimeEpoch = expectedEpoch ?: walkSessionLifecycle.currentRuntimeEpochOrNull()
            ?: return true
        val resources = walkSessionResourceProbe.snapshot()
        latestInferenceThermalThrottled = resources.thermalThrottled
        if (developmentGuidanceStartBypassEnabled) {
            return walkSessionLifecycle.isRuntimeEpochCurrent(runtimeEpoch)
        }
        return walkRuntimeSafetyCoordinator.observe(
            WalkRuntimeSafetyObservation(
                epoch = runtimeEpoch,
                observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                batteryCritical = resources.batteryNotLow == false,
                storageCritical = resources.privateStorageAboveSystemLow == false,
                thermalCritical = resources.thermalBelowCritical == false,
            ),
        ).safetyOutputsAllowed
    }

    private fun firstRunPermissionRequestAllowed(
        purpose: PermissionRequestPurpose,
    ): Boolean = when (purpose) {
        PermissionRequestPurpose.INITIAL_APP_ENTRY ->
            isActivityForeground &&
                privacyStartupInspectionComplete &&
                !privacyStartupInspectionDestroyed
        PermissionRequestPurpose.POST_LOGIN_DEVICE_CHECK ->
            postLoginDeviceCheckSnapshot.state ==
                PostLoginDeviceCheckState.REQUESTING_PERMISSIONS &&
                firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 &&
                firstRunOnboardingSnapshot.stage in setOf(
                    FirstRunOnboardingStage.JIT_PERMISSION_OBSERVATION,
                    FirstRunOnboardingStage.DEVICE_CHECK,
                    FirstRunOnboardingStage.FP004_TRAINING,
                    FirstRunOnboardingStage.COMPLETE,
                )
        PermissionRequestPurpose.METRIC_PREFLIGHT_CAMERA ->
            firstRunDeviceCheckAllowsPreflight()
        PermissionRequestPurpose.WALK_SESSION,
        PermissionRequestPurpose.RUNTIME_CAMERA,
        PermissionRequestPurpose.NAVIGATION,
        PermissionRequestPurpose.VOICE_COMMAND,
        -> firstRunOnboardingComplete()
    }

    private fun startPostLoginDeviceCheckFromPrimaryAction() {
        val sessionBinding = currentPostLoginDeviceCheckSessionBinding()
        if (!isActivityForeground || sessionBinding == null) {
            updateStatus("로그인 확인 필요", "현재 로그인 세션을 확인한 뒤 기기 점검을 다시 시작하세요.")
            return
        }
        if (
            postLoginDeviceCheckSnapshot.state in setOf(
                PostLoginDeviceCheckState.REQUESTING_PERMISSIONS,
                PostLoginDeviceCheckState.RUNNING,
            )
        ) return
        if (!acknowledgeHandsFreeVoiceDisclosure()) {
            updateStatus(
                "안전 고지 저장 실패",
                "안전 고지 확인을 저장하지 못했습니다. 저장공간을 확인한 뒤 다시 시도하세요.",
            )
            return
        }
        beginPostLoginDeviceCheckFromUserAction(sessionBinding)
    }

    private fun handlePostLoginDeviceCheckPrimaryAction() {
        if (postLoginDeviceCheckSnapshot.passesFeatureGate) {
            if (!deferredCameraDependentChecksCanBeRetried()) return
            postLoginDeviceCheckSnapshot = postLoginDeviceCheckSnapshot.copy(
                state = PostLoginDeviceCheckState.NOT_RUN,
                failure = null,
                disabledFeatures = emptySet(),
            )
            metricDistanceCapabilityOverride = null
            runtimeObstacleDetectionCapabilityOverride = null
        }
        if (
            postLoginDeviceCheckSnapshot.state in setOf(
                PostLoginDeviceCheckState.REQUESTING_PERMISSIONS,
                PostLoginDeviceCheckState.RUNNING,
            )
        ) return
        startPostLoginDeviceCheckFromPrimaryAction()
    }

    private fun beginPostLoginDeviceCheckFromUserAction(
        expectedSession: PostLoginDeviceCheckBinding,
    ) {
        val processBinding = currentPostLoginDeviceCheckSessionBinding()
        if (
            !isActivityForeground ||
            processBinding == null ||
            processBinding.actorId != expectedSession.actorId ||
            processBinding.sessionGeneration != expectedSession.sessionGeneration
        ) return
        val started = PostLoginDeviceCheckPolicy.beginFromUserAction(
            snapshot = postLoginDeviceCheckSnapshot,
            actorId = processBinding.actorId,
            sessionGeneration = processBinding.sessionGeneration,
            foreground = true,
        )
        postLoginDeviceCheckSnapshot = started
        val binding = started.bindingOrNull ?: return
        postLoginDeviceCheckBackgroundFailurePending = false
        cancelPostLoginDeviceCheckRuntime("user_started_new_attempt")
        clearStoredMetricDepthRefresh()
        postLoginMetricDepthState = PostLoginMetricDepthState.PENDING
        postLoginCameraPipelineSignal = PostLoginDeviceCheckSignal.PENDING
        postLoginCameraPipelineFailure = null
        postLoginLocationFixSignal = PostLoginDeviceCheckSignal.PENDING
        postLoginLocationFixDecision = null
        postLoginLocationFixTerminalFailure = null
        postLoginWakePhraseSignal = PostLoginDeviceCheckSignal.PENDING
        postLoginWakePhraseUserStarted = false
        postLoginWakePhrasePromptFocused = false
        postLoginHapticSignal = PostLoginDeviceCheckSignal.PENDING
        postLoginHapticPromptFocused = false
        postLoginDeviceCheckLastLiveStatus = null
        if (::postLoginDeviceCheckLiveStatusText.isInitialized) {
            postLoginDeviceCheckLiveStatusText.accessibilityLiveRegion =
                View.ACCESSIBILITY_LIVE_REGION_POLITE
            postLoginDeviceCheckLiveStatusText.text = ""
            postLoginDeviceCheckLiveStatusText.visibility = View.GONE
        }
        metricDistanceCapabilityOverride = null
        runtimeObstacleDetectionCapabilityOverride = null
        onDeviceSpeechRecognitionCapabilityOverride = null
        offlineKoreanTextToSpeechCapabilityOverride = null
        postLoginDeviceCheckPermissionResultPending = false
        postLoginDeviceCheckPendingPermissionBinding = null
        val missing = requestedPostLoginDeviceCheckPermissions()
        if (missing.isEmpty()) {
            completePostLoginDeviceCheckPermissionObservation()
            return
        }
        postLoginDeviceCheckPermissionRequestCode = runCatching {
            requestPermissionsWithLease(
                missing.toTypedArray(),
                PermissionRequestPurpose.POST_LOGIN_DEVICE_CHECK,
            )
        }.getOrNull()
        if (postLoginDeviceCheckPermissionRequestCode == null) {
            completePostLoginDeviceCheckPermissionObservation()
        }
        refreshStartupCapabilityUi()
    }

    private fun handlePostLoginDeviceCheckPermissionResult(
        binding: PostLoginDeviceCheckBinding,
    ) {
        if (!isPostLoginDeviceCheckSnapshotBindingLive(binding)) return
        postLoginDeviceCheckPermissionRequestCode = null
        if (!isActivityForeground) {
            postLoginDeviceCheckPermissionResultPending = true
            postLoginDeviceCheckPendingPermissionBinding = binding
            return
        }
        completePostLoginDeviceCheckPermissionObservation(binding)
    }

    private fun completePostLoginDeviceCheckPermissionObservation(
        expectedBinding: PostLoginDeviceCheckBinding? = null,
    ) {
        val binding = expectedBinding ?: postLoginDeviceCheckSnapshot.bindingOrNull ?: return
        if (
            postLoginDeviceCheckSnapshot.state !=
            PostLoginDeviceCheckState.REQUESTING_PERMISSIONS
        ) return
        if (!isPostLoginDeviceCheckSnapshotBindingLive(binding)) return
        postLoginDeviceCheckSnapshot = PostLoginDeviceCheckPolicy.beginRunning(
            postLoginDeviceCheckSnapshot,
            binding,
            foreground = isActivityForeground,
        )
        if (
            firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 &&
            firstRunOnboardingSnapshot.stage ==
            FirstRunOnboardingStage.JIT_PERMISSION_OBSERVATION
        ) {
            val transition = FirstRunOnboardingPolicy.recordEmailJitPermissionObservation(
                snapshot = firstRunOnboardingSnapshot,
                expectedEpoch = firstRunOnboardingSnapshot.epoch,
                expectedRevision = firstRunOnboardingSnapshot.revision,
            )
            if (!transition.accepted) {
                cancelPostLoginDeviceCheckRuntime("jit_transition_rejected")
                return
            }
            firstRunOnboardingSnapshot = transition.current
            startPostLoginDeviceCheckRuntime(binding)
            onFirstRunOnboardingStateChanged(
                "권한 상태를 확인했습니다. 이제 기기 기능을 점검합니다.",
            )
            return
        }
        startPostLoginDeviceCheckRuntime(binding)
    }

    private fun requiredPostLoginDeviceCheckPermissions(): List<String> = buildList {
        if (!hasCameraPermission()) add(Manifest.permission.CAMERA)
        if (!hasLocationPermission()) {
            add(Manifest.permission.ACCESS_FINE_LOCATION)
            add(Manifest.permission.ACCESS_COARSE_LOCATION)
        }
        if (!hasRecordAudioPermission()) add(Manifest.permission.RECORD_AUDIO)
        if (
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q &&
            !hasActivityRecognitionPermission()
        ) {
            add(Manifest.permission.ACTIVITY_RECOGNITION)
        }
        if (
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU &&
            !hasHandsFreeNotificationPermission()
        ) {
            add(Manifest.permission.POST_NOTIFICATIONS)
        }
    }.distinct()

    private fun requestedPostLoginDeviceCheckPermissions(): List<String> =
        if (
            ::stepLengthPrefs.isInitialized &&
            stepLengthPrefs.getBoolean(
                PREF_INITIAL_APP_PERMISSION_REQUEST_COMPLETED,
                false,
            )
        ) {
            emptyList()
        } else {
            requiredPostLoginDeviceCheckPermissions()
        }

    // Retained through Activity recreation; a fresh launch may recover expired one-time grants.
    private var initialAppPermissionReRequestedThisLaunch = false

    private fun requestInitialAppEntryPermissionsIfNeeded() {
        if (!::stepLengthPrefs.isInitialized) return
        if (permissionRequestLeases.values.any {
                it.purpose == PermissionRequestPurpose.INITIAL_APP_ENTRY
            }
        ) return
        if (stepLengthPrefs.getBoolean(PREF_INITIAL_APP_PERMISSION_REQUEST_STARTED, false)) {
            initialAppPermissionReRequestedThisLaunch = true
            handleInitialAppEntryPermissionResult()
            return
        }
        val missing = requiredPostLoginDeviceCheckPermissions()
        if (missing.isEmpty()) {
            stepLengthPrefs.edit()
                .putBoolean(PREF_INITIAL_APP_PERMISSION_REQUEST_COMPLETED, true)
                .remove(PREF_INITIAL_APP_PERMISSION_REQUEST_STARTED)
                .commit()
            clearInitialAppPermissionLimitationsIfResolved()
            return
        }
        if (stepLengthPrefs.getBoolean(PREF_INITIAL_APP_PERMISSION_REQUEST_COMPLETED, false) &&
            initialAppPermissionReRequestedThisLaunch
        ) {
            showInitialAppPermissionLimitations(missing.toSet())
            return
        }
        launchInitialAppEntryPermissionRequest(missing)
    }

    private fun launchInitialAppEntryPermissionRequest(missing: List<String>) {
        initialAppPermissionReRequestedThisLaunch = true
        val attemptSaved = stepLengthPrefs.edit()
            .putBoolean(PREF_INITIAL_APP_PERMISSION_REQUEST_STARTED, true)
            .commit()
        if (!attemptSaved) {
            updateStatus(
                "앱 권한 요청 준비 실패",
                "권한 요청 상태를 저장하지 못했습니다. 앱을 다시 열어 확인하세요.",
            )
            return
        }
        updateStatus(
            "앱 권한 확인",
            "앱 사용에 필요한 Android 권한을 요청합니다. 필수 권한을 모두 허용해야 앱을 사용할 수 있습니다.",
        )
        val requestCode = runCatching {
            requestPermissionsWithLease(
                missing.toTypedArray(),
                PermissionRequestPurpose.INITIAL_APP_ENTRY,
            )
        }.getOrNull()
        if (requestCode == null) {
            stepLengthPrefs.edit()
                .remove(PREF_INITIAL_APP_PERMISSION_REQUEST_STARTED)
                .commit()
            updateStatus(
                "앱 권한 요청 실패",
                "권한 요청을 시작하지 못했습니다. 앱을 다시 열어 확인하세요.",
            )
        }
    }

    private fun handleInitialAppEntryPermissionResult() {
        val missingAtResult = requiredPostLoginDeviceCheckPermissions()
        if (missingAtResult.isNotEmpty()) {
            stepLengthPrefs.edit()
                .putBoolean(PREF_INITIAL_APP_PERMISSION_REQUEST_COMPLETED, true)
                .remove(PREF_INITIAL_APP_PERMISSION_REQUEST_STARTED)
                .commit()
            showInitialAppPermissionLimitations(missingAtResult.toSet())
            return
        }
        val saved = stepLengthPrefs.edit()
            .putBoolean(PREF_INITIAL_APP_PERMISSION_REQUEST_COMPLETED, true)
            .remove(PREF_INITIAL_APP_PERMISSION_REQUEST_STARTED)
            .commit()
        if (!saved) {
            updateStatus(
                "권한 확인 저장 실패",
                "권한 확인 상태를 저장하지 못해 다음 실행에서 다시 확인할 수 있습니다.",
            )
            return
        }
        val missing = requiredPostLoginDeviceCheckPermissions()
        if (missing.isEmpty()) {
            clearInitialAppPermissionLimitationsIfResolved()
            updateStatus("앱 권한 확인 완료", "필요한 Android 권한이 모두 허용되었습니다.")
            return
        }
        showInitialAppPermissionLimitations(missing.toSet())
    }

    private fun clearInitialAppPermissionLimitationsIfResolved() {
        if (requiredPostLoginDeviceCheckPermissions().isNotEmpty()) return
        val wasBlocked = initialAppPermissionExitRequired
        initialAppPermissionExitRequired = false
        initialAppPermissionExitDialog?.dismiss()
        initialAppPermissionExitDialog = null
        if (wasBlocked) renderMainUi()
    }

    private fun showInitialAppPermissionLimitations(missing: Set<String>) {
        showRequiredAppPermissionExit(missing)
    }

    private fun acknowledgeHandsFreeVoiceDisclosure(): Boolean {
        if (!::stepLengthPrefs.isInitialized) return false
        val saved = stepLengthPrefs.edit()
            .putInt(
                PREF_HANDS_FREE_VOICE_DISCLOSURE_VERSION,
                HANDS_FREE_VOICE_DISCLOSURE_VERSION,
            )
            .commit()
        if (!saved) updateNavigationStatus("voice_hands_free=disclosure_save_failed")
        return saved && isHandsFreeVoiceDisclosureAccepted()
    }

    private fun isHandsFreeVoiceDisclosureAccepted(): Boolean =
        ::stepLengthPrefs.isInitialized &&
            stepLengthPrefs.getInt(PREF_HANDS_FREE_VOICE_DISCLOSURE_VERSION, 0) ==
            HANDS_FREE_VOICE_DISCLOSURE_VERSION

    private fun currentPostLoginDeviceCheckSessionBinding(): PostLoginDeviceCheckBinding? {
        val process = GatewaySessionProcessCoordinator.snapshot()
        val session = process.session ?: return null
        val actorId = firstRunOnboardingSnapshot.verifiedActorBinding?.value ?: return null
        if (
            session.actorId != actorId ||
            session.verificationState != GatewaySessionVerificationState.VERIFIED ||
            !session.isUsableFor(actorId) ||
            process.storageBlocked ||
            process.deletionRecoveryOnly
        ) return null
        return PostLoginDeviceCheckBinding(
            actorId = actorId,
            sessionGeneration = process.generation,
            attemptGeneration = postLoginDeviceCheckSnapshot.attemptGeneration,
        )
    }

    private fun isPostLoginDeviceCheckSessionBindingLive(
        expected: PostLoginDeviceCheckBinding,
    ): Boolean = currentPostLoginDeviceCheckSessionBinding() == expected

    private fun isPostLoginDeviceCheckSnapshotBindingLive(
        expected: PostLoginDeviceCheckBinding,
    ): Boolean =
        PostLoginDeviceCheckPolicy.isCurrent(postLoginDeviceCheckSnapshot, expected) &&
            isPostLoginDeviceCheckSessionBindingLive(expected)

    private fun openPostLoginDeviceCheckSettings() {
        val failure = postLoginDeviceCheckSnapshot.failure
        val intent = when (failure) {
            PostLoginDeviceCheckFailure.LOCATION_SERVICE_DISABLED ->
                Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS)
            PostLoginDeviceCheckFailure.LOCATION_FIX_UNAVAILABLE -> when {
                postLoginLocationFixTerminalFailure ==
                    PostLoginLocationFixTerminalFailure.REQUEST_FAILED ->
                    Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                        data = Uri.fromParts("package", packageName, null)
                    }
                postLoginLocationFixDecision?.reason ==
                    DeviceCheckLocationFixReason.MOCK_LOCATION ->
                    Intent(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS)
                else -> Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS)
            }
            PostLoginDeviceCheckFailure.KOREAN_TTS_UNAVAILABLE ->
                Intent(TextToSpeech.Engine.ACTION_INSTALL_TTS_DATA)
            else -> if (
                postLoginDeviceCheckSnapshot.passesFeatureGate &&
                requiredPostLoginDeviceCheckPermissions().isEmpty() &&
                !isLocationServiceEnabledForDeviceCheck()
            ) {
                Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS)
            } else {
                Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                    data = Uri.fromParts("package", packageName, null)
                }
            }
        }
        runCatching { startActivity(intent) }.onFailure {
            runCatching {
                startActivity(
                    Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                        data = Uri.fromParts("package", packageName, null)
                    },
                )
            }
        }
    }

    private fun openVoiceDataInstallSettings() {
        val candidates = listOf(
            Intent(TextToSpeech.Engine.ACTION_INSTALL_TTS_DATA),
            Intent(ANDROID_TTS_SETTINGS_ACTION),
            Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                data = Uri.fromParts("package", packageName, null)
            },
        )
        val opened = candidates.any { intent ->
            runCatching {
                startActivity(intent)
                true
            }.getOrDefault(false)
        }
        if (opened) {
            voiceDataInstallRecheckPending = true
            voiceDataInstallRecheckInFlight = false
            updateStatus(
                "한국어 음성 데이터 설치",
                "한국어 음성 데이터를 설치한 뒤 WalkSafe로 돌아오면 사용 가능 여부를 다시 확인합니다.",
            )
            return
        }
        val detail = "휴대폰 설정에서 한국어 음성 데이터 설치 화면을 열 수 없습니다."
        updateStatus("음성 설정을 열 수 없음", detail)
        speakInteraction(detail)
    }

    private fun recheckVoiceDataAfterSettingsIfNeeded() {
        if (
            !voiceDataInstallRecheckPending ||
            voiceDataInstallRecheckInFlight ||
            !::startupCapabilityProbe.isInitialized
        ) return
        voiceDataInstallRecheckInFlight = true
        val started = runCatching {
            if (startupCapabilityProbeStarted) {
                startupCapabilityProbe.recheckOfflineKoreanTextToSpeech()
            } else {
                startupCapabilityProbe.close()
                startupCapabilityProbe = AndroidStartupCapabilityProbe(this) {
                    completeVoiceDataInstallRecheckIfPossible()
                    refreshStartupCapabilityUi()
                }
                startupCapabilityProbeStarted = true
                startupCapabilityProbe.start()
            }
        }.isSuccess
        if (!started) {
            startupCapabilityProbeStarted = false
            startupCapabilityProbe.close()
            voiceDataInstallRecheckPending = false
            voiceDataInstallRecheckInFlight = false
            updateStatus(
                "한국어 음성 데이터 확인 실패",
                "음성 데이터 상태를 다시 확인하지 못했습니다. 설치 버튼을 눌러 다시 시도하세요.",
            )
            return
        }
        if (voiceDataInstallRecheckPending && voiceDataInstallRecheckInFlight) {
            updateStatus(
                "한국어 음성 데이터 확인 중",
                "설치된 한국어 음성으로 실제 안내 파일을 만들 수 있는지 확인하고 있습니다.",
            )
        }
    }

    private fun completeVoiceDataInstallRecheckIfPossible() {
        if (!voiceDataInstallRecheckPending || !voiceDataInstallRecheckInFlight) return
        val available = startupCapabilityProbe.snapshot()
            .offlineKoreanTextToSpeechAvailable ?: return
        voiceDataInstallRecheckPending = false
        voiceDataInstallRecheckInFlight = false
        if (!available) {
            updateStatus(
                "한국어 음성 데이터 확인 필요",
                "한국어 오프라인 음성 안내를 아직 사용할 수 없습니다. 설치 상태를 확인한 뒤 다시 시도하세요.",
            )
            return
        }

        val current = postLoginDeviceCheckSnapshot
        if (
            current.passesFeatureGate &&
            PostLoginDeviceCheckFeature.VOICE_GUIDANCE in current.disabledFeatures
        ) {
            val remaining = current.disabledFeatures - PostLoginDeviceCheckFeature.VOICE_GUIDANCE
            val recovered = current.copy(
                state = if (remaining.isEmpty()) {
                    PostLoginDeviceCheckState.FULL
                } else {
                    PostLoginDeviceCheckState.LIMITED
                },
                failure = null,
                disabledFeatures = remaining,
            )
            if (
                current.actorId == null ||
                currentPostLoginDeviceCheckResultBinding(current.actorId)?.let { binding ->
                    postLoginDeviceCheckResultStore.save(
                        recovered,
                        binding,
                        cameraDependentChecksDeferred =
                            postLoginCameraDependentChecksDeferred,
                        metricDepthState = postLoginMetricDepthState,
                    )
                } != true
            ) {
                updateStatus(
                    "음성 기능 복구 저장 실패",
                    "한국어 음성 데이터는 확인했지만 점검 결과를 저장하지 못했습니다. 다시 시도하세요.",
                )
                return
            }
            postLoginDeviceCheckSnapshot = recovered
        }
        offlineKoreanTextToSpeechCapabilityOverride = true
        updateStatus(
            "한국어 음성 재점검 완료",
            "설치된 한국어 음성으로 실제 안내 생성을 다시 확인했습니다. 기기 점검 결과를 확인한 뒤 보행을 시작하거나 재개하세요.",
        )
    }

    private fun requireFirstRunOnboardingComplete(
        reason: String,
        announce: Boolean = true,
    ): Boolean {
        if (firstRunOnboardingComplete()) return true
        val stage = if (::firstRunOnboardingSnapshot.isInitialized) {
            firstRunOnboardingSnapshot.stage.name.lowercase(Locale.US)
        } else {
            "uninitialized"
        }
        updateNavigationStatus("firstRun=blocked reason=$reason stage=$stage")
        updateStatus(
            "첫 실행 등록 필요",
            "목적·연령·동의·본인 확인·로그인·권한·기기점검·안전교육을 순서대로 완료해야 합니다.",
        )
        if (announce && !isScreenReaderActive()) {
            speakInteraction("첫 실행 등록과 안전교육을 먼저 완료하세요.")
        }
        return false
    }

    private fun firstRunLocalRequest(
        action: String,
    ): FirstRunOnboardingAttemptRequest {
        val snapshot = firstRunOnboardingSnapshot
        val requestIdentity = sha256Hex(
            (
                "FP010|request|$action|${snapshot.epoch}|${snapshot.revision}|" +
                    snapshot.stage.name
            ).toByteArray(),
        )
        val attemptIdentity = sha256Hex(
            (
                "FP010|attempt|$action|${snapshot.epoch}|${snapshot.revision}|" +
                    snapshot.stage.name
            ).toByteArray(),
        )
        return FirstRunOnboardingAttemptRequest.forSnapshot(
            snapshot = snapshot,
            requestId = "req_$requestIdentity",
            attemptId = "att_$attemptIdentity",
        )
    }

    private fun firstRunLocalReceipt(action: String): FirstRunReceiptHash {
        val snapshot = firstRunOnboardingSnapshot
        return FirstRunReceiptHash.fromSha256Hex(
            sha256Hex(
                "FP010|$action|${snapshot.epoch}|${snapshot.revision}|${snapshot.stage.name}"
                    .toByteArray(),
            ),
        )
    }

    private fun acknowledgeFirstRunPurposeAndSafety() {
        if (
            firstRunOnboardingSnapshot.stage !=
            FirstRunOnboardingStage.PURPOSE_AND_SAFETY
        ) return
        if (!acknowledgeHandsFreeVoiceDisclosure()) {
            updateStatus(
                "안전 고지 저장 실패",
                "안전 고지 확인을 저장하지 못했습니다. 저장공간을 확인한 뒤 다시 시도하세요.",
            )
            return
        }
        val transition = FirstRunOnboardingPolicy.acknowledgePurposeAndSafety(
            snapshot = firstRunOnboardingSnapshot,
            request = firstRunLocalRequest("purpose_and_safety"),
            receiptHash = firstRunLocalReceipt("purpose_and_safety"),
        )
        if (!transition.accepted) return
        firstRunOnboardingSnapshot = transition.current
        onFirstRunOnboardingStateChanged(
            announcement = if (
                transition.current.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4
            ) {
                "목적과 안전 한계를 확인했습니다. 이제 권한과 기기 기능을 점검하세요."
            } else {
                "목적과 안전 한계를 확인했습니다. 연령 구간을 선택하세요."
            },
        )
    }

    private fun selectFirstRunAgeBand(ageBand: FirstRunAgeBand) {
        if (
            firstRunOnboardingSnapshot.stage !=
            FirstRunOnboardingStage.AGE_AND_GUARDIAN_NEED
        ) return
        val transition = FirstRunOnboardingPolicy.recordAgeAndGuardianNeed(
            snapshot = firstRunOnboardingSnapshot,
            request = firstRunLocalRequest("age_and_guardian_need_${ageBand.name}"),
            ageBand = ageBand,
            receiptHash = firstRunLocalReceipt("age_and_guardian_need_${ageBand.name}"),
        )
        if (!transition.accepted) return
        firstRunOnboardingSnapshot = transition.current
        val announcement = if (
            transition.current.stage ==
            FirstRunOnboardingStage.BLOCKED_UNDER_14
        ) {
            "만 14세 미만은 가입하거나 보행 기능을 사용할 수 없습니다."
        } else {
            "연령 구간을 확인했습니다. 네 가지 동의 항목을 각각 선택하고 서버 저장을 확인하세요."
        }
        onFirstRunOnboardingStateChanged(announcement)
    }

    private fun onFirstRunOnboardingStateChanged(
        announcement: String,
        preservePostLoginDeviceCheck: Boolean = false,
    ) {
        if (developmentQuickStartEnabled) {
            developmentQuickStartSessionOrNull()?.let { session ->
                reporterUserId = session.actorId
                priorityUserOnboardingActorId = session.actorId
                permissionSessionPolicy.authenticated(session.actorId)
            }
            updateFirstRunOnboardingUi()
            if (::startupCapabilityProbe.isInitialized) refreshStartupCapabilityUi()
            return
        }
        val rawWalkWasActive =
            ::walkSessionLifecycle.isInitialized &&
                walkSessionLifecycle.snapshot().state == WalkSessionState.ACTIVE
        val restoredDeviceCheckAdvanced = advanceEmailStagesWithRestoredDeviceCheck()
        val effectiveAnnouncement = if (restoredDeviceCheckAdvanced) {
            "저장된 기기 점검 결과를 적용했습니다. 안전교육을 완료하세요."
        } else {
            announcement
        }
        if (!preservePostLoginDeviceCheck) {
            invalidateRuntimeMetricEvidence("first_run_stage_changed")
        }
        if (!firstRunOnboardingComplete()) {
            if (
                ::gatewaySessionStore.isInitialized &&
                firstRunOnboardingSnapshot.flow !=
                FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4
            ) {
                clearGatewaySession(logoutRemote = true)
            }
            if (rawWalkWasActive) {
                enterWalkSessionSafetyStopAndCancelOutputs(
                    "first_run_onboarding_incomplete",
                )
            }
        }
        bindFirstRunVerifiedActorForTraining()
        val firstRunActorId = firstRunOnboardingSnapshot.verifiedActorBinding?.value
        if (
            firstRunActorId != null &&
            completeFirstRunFp004TrainingIfReady(firstRunActorId)
        ) return
        if (firstRunActorId != null) {
            val process = GatewaySessionProcessCoordinator.snapshot()
            val published = GatewaySessionProcessCoordinator.updateFirstRunSnapshot(
                expectedGeneration = process.generation,
                expectedActorId = firstRunActorId,
                firstRunSnapshot = firstRunOnboardingSnapshot,
            )
            if (published && process.session?.isBackendAccountDeviceBound == true) {
                val stored = gatewaySessionStore.updateBackendDeviceFirstRunSnapshot(
                    requireNotNull(process.session.versionOrNull), firstRunOnboardingSnapshot,
                )
                if (stored == GatewaySessionStoreResult.BLOCKED ||
                    stored == GatewaySessionStoreResult.STORAGE_FAILURE
                ) {
                    GatewaySessionProcessCoordinator.markStorageBlocked(process.generation)
                }
            }
        }
        maybeStartFirstRunDeviceCheckProbes()
        updateFirstRunOnboardingUi()
        if (::startupCapabilityProbe.isInitialized) refreshStartupCapabilityUi()
        focusCurrentFirstRunStage(firstRunOnboardingSnapshot.stage)
        if (!isScreenReaderActive()) {
            speakInteraction(effectiveAnnouncement)
        }
    }

    private fun advanceEmailStagesWithRestoredDeviceCheck(): Boolean {
        if (
            firstRunOnboardingSnapshot.flow != FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 ||
            !postLoginDeviceCheckPassesFeatureGate()
        ) return false
        var current = firstRunOnboardingSnapshot
        var advanced = false
        if (current.stage == FirstRunOnboardingStage.JIT_PERMISSION_OBSERVATION) {
            val transition = FirstRunOnboardingPolicy.recordEmailJitPermissionObservation(
                snapshot = current,
                expectedEpoch = current.epoch,
                expectedRevision = current.revision,
            )
            if (!transition.accepted) return false
            current = transition.current
            advanced = true
        }
        if (current.stage == FirstRunOnboardingStage.DEVICE_CHECK) {
            val transition = FirstRunOnboardingPolicy.recordEmailDeviceCheckPassed(
                snapshot = current,
                expectedEpoch = current.epoch,
                expectedRevision = current.revision,
            )
            if (!transition.accepted) return false
            current = transition.current
            advanced = true
        }
        if (advanced) firstRunOnboardingSnapshot = current
        return advanced
    }

    private fun focusCurrentFirstRunStage(stage: FirstRunOnboardingStage) {
        val target = when (stage) {
            FirstRunOnboardingStage.FP004_TRAINING ->
                if (shouldShowFirstRunPhonePosture()) priorityUserEducationProgressText
                else priorityUserOnboardingStatusText
            FirstRunOnboardingStage.COMPLETE -> return
            else -> return
        }
        val firstAction = when (stage) {
            FirstRunOnboardingStage.FP004_TRAINING ->
                if (shouldShowFirstRunPhonePosture()) {
                    when {
                        firstRunPhonePostureButton.isEnabled -> firstRunPhonePostureButton
                        !priorityUserOnboardingPolicy.snapshot().appUsageReviewed -> priorityUserEducationButton
                        priorityUserSafePlaceButton.isEnabled -> priorityUserSafePlaceButton
                        else -> priorityUserPracticeButtons.values.firstOrNull { it.isEnabled }
                            ?: priorityUserEducationAgreeButton
                    }
                } else priorityUserEducationButton
            FirstRunOnboardingStage.COMPLETE -> null
            else -> null
        }
        target.post {
            if (
                firstRunOnboardingSnapshot.stage != stage ||
                !target.isShown ||
                !::controlsScroll.isInitialized
            ) return@post
            firstAction?.takeIf { it.isShown && it.isEnabled }?.requestFocus()
            target.requestRectangleOnScreen(
                Rect(0, 0, target.width, target.height),
                true,
            )
            target.performAccessibilityAction(
                android.view.accessibility.AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS,
                null,
            )
        }
    }

    private fun bindFirstRunVerifiedActorForTraining() {
        val actorId =
            firstRunOnboardingSnapshot.verifiedActorBinding?.value ?: return
        val actorChanged =
            reporterUserId != actorId || priorityUserOnboardingActorId != actorId
        if (actorChanged) {
            invalidateOfficialEnvironmentEvidence("first_run_actor_bound")
            invalidatePhoneMountingEvidence("first_run_actor_bound")
        }
        if (gatewayFieldSession?.actorId != actorId) {
            clearGatewaySession(logoutRemote = true)
        }
        reporterUserId = actorId
        if (!permissionSessionPolicy.isAuthenticatedFor(actorId)) {
            permissionSessionPolicy.rememberActor(actorId)
        }
        restorePriorityUserOnboardingFromPrefs()
        val verifiedAgeBand = when (firstRunOnboardingSnapshot.ageBand) {
            FirstRunAgeBand.AGE_14_TO_17 -> PriorityUserAgeBand.AGE_14_TO_17
            FirstRunAgeBand.ADULT_18_PLUS -> PriorityUserAgeBand.ADULT_18_PLUS
            FirstRunAgeBand.VERIFIED_14_PLUS -> PriorityUserAgeBand.VERIFIED_14_PLUS
            FirstRunAgeBand.UNDER_14,
            null,
            -> return
        }
        val restored = priorityUserOnboardingPolicy.snapshot()
        val compatible = restored.ageBand == verifiedAgeBand
        priorityUserOnboardingPolicy = PriorityUserOnboardingPolicy(
            PriorityUserOnboardingSnapshot(
                ageBand = verifiedAgeBand,
                guardianVerified =
                    verifiedAgeBand == PriorityUserAgeBand.AGE_14_TO_17 &&
                        FirstRunOnboardingStage.GUARDIAN_APPROVAL in
                        firstRunOnboardingSnapshot.completedReceiptHashes,
                phonePostureAcknowledged = compatible && restored.phonePostureAcknowledged,
                practiceNecessityReviewed = compatible && restored.practiceNecessityReviewed,
                educationAccepted = compatible && restored.educationAccepted,
                usageConditionsAcknowledged = compatible && restored.usageConditionsAcknowledged,
                appUsageReviewed = compatible && restored.appUsageReviewed,
                appUsageAccepted = compatible && restored.appUsageAccepted,
                educationReviewed = compatible && restored.educationReviewed,
                safePracticePlaceConfirmed =
                    compatible && restored.safePracticePlaceConfirmed,
                completedPractices = if (compatible) {
                    restored.completedPractices
                } else {
                    emptySet()
                },
                hazardResponseConfirmed = compatible && restored.hazardResponseConfirmed,
            ),
        )
        if (firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 &&
            firstRunOnboardingSnapshot.isComplete &&
            !priorityUserOnboardingPolicy.snapshot().nativeEducationComplete
        ) {
            val restart = FirstRunOnboardingPolicy.restartFp004Training(firstRunOnboardingSnapshot)
            if (restart.accepted) {
                nativeCompletedFirstRunRecord = null
                firstRunOnboardingSnapshot = restart.current
                onFirstRunOnboardingStateChanged(
                    "사전 연습을 완료해 주세요. 기존 안전 교육과 기기 점검 기록은 유지합니다.",
                    preservePostLoginDeviceCheck = true,
                )
            }
        }
    }

    private fun bindAccountInputValidation(target: EditText) {
        target.addTextChangedListener(
            object : TextWatcher {
                override fun beforeTextChanged(
                    text: CharSequence?,
                    start: Int,
                    count: Int,
                    after: Int,
                ) = Unit

                override fun onTextChanged(
                    text: CharSequence?,
                    start: Int,
                    before: Int,
                    count: Int,
                ) = Unit

                override fun afterTextChanged(text: Editable?) {
                    target.error = null
                    if (accountInputErrorActive) {
                        accountInputErrorActive = false
                        accountAccessNotice = null
                        if (::firstRunOnboardingSnapshot.isInitialized) {
                            updateEmailAccountAccessUi(firstRunOnboardingSnapshot)
                        }
                    } else {
                        refreshAccountActionAvailability()
                    }
                }
            },
        )
    }

    private fun currentEmailAccountFormValidity(): EmailAccountFormValidity =
        EmailAccountFormPolicy.evaluate(
            email = accountEmailInput.text?.toString().orEmpty(),
            dateOfBirth = accountDateOfBirthInput.text?.toString().orEmpty(),
            password = accountPasswordInput.text?.toString().orEmpty(),
            passwordConfirmation =
                accountPasswordConfirmationInput.text?.toString().orEmpty(),
            otp = accountOtpInput.text?.toString().orEmpty(),
            selections = currentAccountConsentSelections(),
        )

    private fun refreshAccountConsentSpeechContext() {
        val context = reporterUserId to firstRunOnboardingSnapshot.epoch.toString()
        if (accountConsentSpeechResultContext == context) return
        stopAccountConsentSpeech()
        accountConsentSpeechResults.clear()
        accountConsentSpeechResultContext = context
        updateAccountConsentSpeechButtons()
    }

    private fun isAccountConsentClauseVisible(key: String): Boolean =
        isActivityForeground &&
            firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 &&
            firstRunOnboardingSnapshot.stage == FirstRunOnboardingStage.EMAIL_OTP_ENROLLMENT &&
            accountSignupExpanded && accountSignupStep == AccountSignupStep.CONSENT &&
            accountConsentCards[key]?.isShown == true &&
            accountConsentListenButtons[key]?.isShown == true

    private fun updateAccountConsentSpeechButtons() {
        accountConsentListenButtons.forEach { (key, button) ->
            val label = accountConsentChecks.getValue(key).text.toString()
                .removeSuffix(" 동의").removeSuffix(" 확인")
            val playing = accountConsentSpeechKey == key
            val completed = accountConsentSpeechResults[key]
            button.text = when {
                playing -> "$label 듣기 중지"
                completed == true -> "$label 다시 듣기"
                completed == false -> "$label 듣기 재시도"
                else -> "$label 듣기"
            }
            val playbackStatus = when {
                playing -> "약관 듣기 재생 중. 이번 듣기는 아직 완료되지 않았습니다."
                completed == true -> "이전 약관 듣기 완료."
                completed == false -> "약관 듣기 미완료."
                else -> "약관 듣기를 아직 완료하지 않았습니다."
            }
            button.contentDescription = button.text.toString() + ". " + playbackStatus +
                " 청취만으로 동의되지 않습니다."
        }
    }

    private fun stopAccountConsentSpeech() {
        if (accountConsentSpeechKey == null) return
        accountConsentSpeechGeneration += 1L
        accountConsentSpeechKey = null
        feedbackActuator?.cancelPriorityUserTrainingFeedback()
        updateAccountConsentSpeechButtons()
    }

    private fun playAccountConsentClause(key: String) {
        refreshAccountConsentSpeechContext()
        if (accountConsentSpeechKey == key) {
            stopAccountConsentSpeech()
            updateStatus("약관 듣기 중지", "듣기를 중지했습니다. 동의 항목은 변경되지 않았습니다.")
            return
        }
        if (!isAccountConsentClauseVisible(key) ||
            isWalkSessionRuntimeActive() || priorityUserEducationInFlight ||
            priorityUserPracticeInFlight != null) return
        val message = accountConsentClauseTexts[key]?.text?.toString()?.takeIf { it.isNotBlank() }
            ?: return
        stopAccountConsentSpeech()
        if (voiceRecognitionActive) cancelVoiceCommandRecognition()
        val generation = ++accountConsentSpeechGeneration
        val actorId = reporterUserId
        val onboardingEpoch = firstRunOnboardingSnapshot.epoch
        val lifecycleGeneration = feedbackLifecycleGeneration
        accountConsentSpeechKey = key
        updateAccountConsentSpeechButtons()
        val chunks = message.chunked(TextToSpeech.getMaxSpeechInputLength())
        val actuator = ensureFeedbackActuator()
        val handler = android.os.Handler(Looper.getMainLooper())
        val initializationDeadlineMs = SystemClock.elapsedRealtime() +
            AndroidFeedbackActuator.INITIALIZATION_READINESS_TIMEOUT_MS
        fun ownsPlayback(): Boolean = generation == accountConsentSpeechGeneration &&
            accountConsentSpeechKey == key
        fun finish(completed: Boolean) {
            if (!ownsPlayback()) return
            if (!isFeedbackLifecycleCurrent(lifecycleGeneration) ||
                reporterUserId != actorId || firstRunOnboardingSnapshot.epoch != onboardingEpoch ||
                !isAccountConsentClauseVisible(key) || isWalkSessionRuntimeActive() ||
                voiceRecognitionActive) {
                stopAccountConsentSpeech()
                return
            }
            accountConsentSpeechResults[key] = completed
            accountConsentSpeechGeneration += 1L
            accountConsentSpeechKey = null
            updateAccountConsentSpeechButtons()
            updateStatus(
                if (completed) "약관 듣기 완료" else "약관 듣기 미완료",
                if (completed) "내용을 확인한 뒤 해당 동의 항목을 직접 선택하세요. 청취는 동의가 아닙니다."
                else "안내를 끝까지 재생하지 못했습니다. 다시 듣거나 화면의 본문을 확인하세요. 동의는 변경되지 않았습니다.",
            )
        }
        fun playChunk(index: Int) {
            if (!ownsPlayback()) return
            if (!isFeedbackLifecycleCurrent(lifecycleGeneration) ||
                reporterUserId != actorId || firstRunOnboardingSnapshot.epoch != onboardingEpoch ||
                !isAccountConsentClauseVisible(key) || isWalkSessionRuntimeActive() ||
                voiceRecognitionActive) {
                stopAccountConsentSpeech()
                return
            }
            if (actuator.isSpeechInitializing()) {
                if (SystemClock.elapsedRealtime() >= initializationDeadlineMs) finish(false)
                else handler.postDelayed({ playChunk(index) }, 100L)
                return
            }
            val dispatch = actuator.speakConsentClause(
                message = chunks[index],
                onCompleted = {
                    runOnUiThread {
                        if (!ownsPlayback()) return@runOnUiThread
                        if (index + 1 < chunks.size) playChunk(index + 1)
                        else if (isFeedbackLifecycleCurrent(lifecycleGeneration) &&
                            reporterUserId == actorId &&
                            firstRunOnboardingSnapshot.epoch == onboardingEpoch &&
                            isAccountConsentClauseVisible(key)) finish(true)
                        else stopAccountConsentSpeech()
                    }
                },
                onFailed = { runOnUiThread { finish(false) } },
            )
            if (dispatch != NavigationSpeechDispatchResult.ACCEPTED) finish(false)
        }
        playChunk(0)
    }

    private fun refreshAccountConsentSummary() {
        if (!::accountConsentSummaryText.isInitialized) return
        val selections = currentAccountConsentSelections()
        val granted = listOf(
            selections.termsOfService,
            selections.privacyNotice,
            selections.locationTerms,
        ).count { it }
        val summary = if (selections.requiredGranted) {
            "필수 동의 3개를 모두 확인했습니다. 다음 가입 단계로 진행할 수 있습니다."
        } else {
            "필수 동의 3개 중 ${granted}개를 확인했습니다. 남은 필수 항목에 동의하세요."
        }
        if (accountConsentSummaryText.text != summary) {
            accountConsentSummaryText.text = summary
            accountConsentSummaryText.contentDescription = summary
        }
        if (::accountConsentAllCheck.isInitialized) {
            val allGranted = accountConsentChecks.values.all { it.isChecked }
            if (accountConsentAllCheck.isChecked != allGranted) {
                accountConsentAllCheck.isChecked = allGranted
            }
        }
    }

    private fun refreshAccountActionAvailability() {
        if (
            !::accountConsentContinueButton.isInitialized ||
            !::accountRequestOtpButton.isInitialized ||
            !::accountCreateButton.isInitialized ||
            !::accountLoginButton.isInitialized
        ) return
        val validity = currentEmailAccountFormValidity()
        val busy = accountRequestFence.isInFlight()
        val emailEntered = accountEmailInput.text?.toString().orEmpty().isNotBlank()
        val dateOfBirthEntered =
            accountDateOfBirthInput.text?.toString().orEmpty().isNotBlank()
        val passwordEntered = accountPasswordInput.text?.toString().orEmpty().isNotBlank()
        val passwordConfirmationEntered =
            accountPasswordConfirmationInput.text?.toString().orEmpty().isNotBlank()
        val otpEntered = accountOtpInput.text?.toString().orEmpty().isNotBlank()
        accountConsentContinueButton.isEnabled =
            validity.canContinueFromConsent && !busy
        accountRequestOtpButton.isEnabled =
            validity.requiredConsentsGranted &&
                emailEntered &&
                dateOfBirthEntered &&
                passwordEntered &&
                passwordConfirmationEntered &&
                !busy &&
                !emailEnrollmentStorageBlocked
        accountCreateButton.isEnabled =
            validity.requiredConsentsGranted &&
                emailEntered &&
                passwordEntered &&
                passwordConfirmationEntered &&
                otpEntered &&
                !busy &&
                !emailEnrollmentStorageBlocked
        accountLoginButton.isEnabled = if (backendDeviceRestorePending) {
            !busy && GatewaySessionProcessCoordinator.snapshot().inFlightOperationId == null
        } else {
            emailEntered && passwordEntered && !busy
        }
    }

    private fun currentAccountConsentSelections(): SignupConsentSelections =
        SignupConsentSelections(
            termsOfService = accountConsentChecks["terms_of_service"]?.isChecked == true,
            privacyNotice = accountConsentChecks["privacy_notice"]?.isChecked == true,
            locationTerms = accountConsentChecks["location_terms"]?.isChecked == true,
            rawOriginal = accountConsentChecks["raw_original"]?.isChecked == true,
            automaticReporting =
                accountConsentChecks["automatic_reporting"]?.isChecked == true,
            trainingReuse = accountConsentChecks["training_reuse"]?.isChecked == true,
        )

    private fun applyAccountConsentSelections(selections: SignupConsentSelections) {
        accountConsentChecks["terms_of_service"]?.isChecked = selections.termsOfService
        accountConsentChecks["privacy_notice"]?.isChecked = selections.privacyNotice
        accountConsentChecks["location_terms"]?.isChecked = selections.locationTerms
        accountConsentChecks["raw_original"]?.isChecked = selections.rawOriginal
        accountConsentChecks["automatic_reporting"]?.isChecked =
            selections.automaticReporting
        accountConsentChecks["training_reuse"]?.isChecked = selections.trainingReuse
        refreshAccountConsentSummary()
        refreshAccountActionAvailability()
    }

    private fun updateEmailAccountAccessUi(snapshot: FirstRunOnboardingSnapshot) {
        if (!::accountAccessControls.isInitialized || !::accountSignupControls.isInitialized) return
        refreshAccountConsentSpeechContext()
        if (accountConsentSpeechKey != null &&
            (snapshot.flow != FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 ||
                snapshot.stage != FirstRunOnboardingStage.EMAIL_OTP_ENROLLMENT ||
                !accountSignupExpanded || accountSignupStep != AccountSignupStep.CONSENT)) {
            stopAccountConsentSpeech()
        }
        val accountEntryScreen = isAccountEntryScreen()
        firstRunOnboardingStatusText.visibility =
            if (accountEntryScreen) View.GONE else View.VISIBLE
        runtimeSectionDivider?.visibility =
            if (accountEntryScreen) View.GONE else View.VISIBLE
        accountAccessStatusText.visibility = View.VISIBLE
        val emailFlow = snapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4
        val accountStage = snapshot.stage in setOf(
            FirstRunOnboardingStage.EMAIL_OTP_ENROLLMENT,
            FirstRunOnboardingStage.ACCOUNT_CREATED,
            FirstRunOnboardingStage.VERIFIED_LOGIN,
        )
        val expectedActorId = snapshot.verifiedActorBinding?.value
        val liveBinding = currentPostLoginDeviceCheckSessionBinding()
        val authenticated =
            emailFlow &&
                expectedActorId != null &&
                liveBinding?.actorId == expectedActorId &&
                !accountStage
        val reauthenticationRequired =
            emailFlow && expectedActorId != null && !accountStage && !authenticated
        val process = GatewaySessionProcessCoordinator.snapshot()
        val deletionRecoveryBlocksReauthentication =
            reauthenticationRequired &&
                (
                    process.deletionRecoveryOnly ||
                        process.session?.sessionScope ==
                        GatewaySessionScope.ACCOUNT_DELETION_RECOVERY
                    )
        val storageBlocksReauthentication =
            reauthenticationRequired && process.storageBlocked
        val staleGeneralSession =
            reauthenticationRequired &&
                process.session != null &&
                !deletionRecoveryBlocksReauthentication &&
                !storageBlocksReauthentication
        val reauthenticationBlocked =
            deletionRecoveryBlocksReauthentication ||
                storageBlocksReauthentication ||
                staleGeneralSession
        accountAccessControls.visibility =
            if (emailFlow && (accountStage || authenticated || reauthenticationRequired)) {
                View.VISIBLE
            } else {
                View.GONE
            }
        if (!emailFlow || (!accountStage && !authenticated && !reauthenticationRequired)) return
        accountSessionLogoutButton.visibility =
            if (authenticated || staleGeneralSession) View.VISIBLE else View.GONE
        accountSessionLogoutButton.text =
            if (staleGeneralSession) "이전 로그인 상태 정리" else "현재 계정 로그아웃"
        accountSessionLogoutButton.contentDescription = accountSessionLogoutButton.text
        accountLoginButton.text = "로그인"
        accountLoginButton.contentDescription = "이메일과 비밀번호로 로그인"
        if (backendDeviceRestorePending && !authenticated &&
            !process.storageBlocked && !process.deletionRecoveryOnly
        ) {
            accountAccessControls.visibility = View.VISIBLE
            accountAccessStatusText.visibility = View.VISIBLE
            wsFieldGroupOf(accountEmailInput).visibility = View.GONE
            wsFieldGroupOf(accountPasswordInput).visibility = View.GONE
            accountLandingHeader.visibility = View.GONE
            accountSignupControls.visibility = View.GONE
            accountSignupToggleButton.visibility = View.GONE
            accountSignupBackButton.visibility = View.GONE
            accountLoginButton.visibility = View.VISIBLE
            accountLoginButton.text = "저장된 로그인 다시 확인"
            accountLoginButton.contentDescription = accountLoginButton.text
            val verifying = process.inFlightOperationId != null
            accountLoginButton.isEnabled = !verifying
            if (accountSessionLogoutButton.parent == null) {
                accountAccessControls.addView(accountSessionLogoutButton)
            }
            accountSessionLogoutButton.visibility = View.VISIBLE
            accountSessionLogoutButton.isEnabled = !verifying
            accountSessionLogoutButton.text = "저장된 로그인 해제"
            accountSessionLogoutButton.contentDescription = accountSessionLogoutButton.text
            val message = if (verifying) "저장된 로그인을 확인하고 있습니다." else
                "인터넷에 연결한 뒤 저장된 로그인을 다시 확인하세요. 비밀번호를 다시 입력하지 않아도 됩니다."
            accountAccessStatusText.text = message
            accountAccessStatusText.contentDescription = message
            return
        }
        accountSessionLogoutButton.isEnabled = process.inFlightOperationId == null
        if (authenticated) {
            wsFieldGroupOf(accountEmailInput).visibility = View.GONE
            wsFieldGroupOf(accountPasswordInput).visibility = View.GONE
            accountLandingHeader.visibility = View.GONE
            accountLoginButton.visibility = View.GONE
            accountSignupToggleButton.visibility = View.GONE
            accountSignupControls.visibility = View.GONE
            val authenticatedStatus = if (snapshot.isComplete) {
                "로그인과 첫 실행 등록을 완료했습니다. 보행 전 실제 상태를 확인하세요."
            } else {
                "로그인했습니다. 다음 단계가 끝날 때까지 보행 기능은 잠깁니다."
            }
            accountAccessStatusText.text = authenticatedStatus
            accountAccessStatusText.contentDescription = authenticatedStatus
            accountAccessControls.visibility = View.GONE
            accountAccessStatusText.visibility = View.GONE
            accountSessionLogoutButton.visibility = View.GONE
            return
        }
        if (reauthenticationBlocked) {
            wsFieldGroupOf(accountEmailInput).visibility = View.GONE
            wsFieldGroupOf(accountPasswordInput).visibility = View.GONE
            accountLandingHeader.visibility = View.GONE
            accountLoginButton.visibility = View.GONE
            accountSignupToggleButton.visibility = View.GONE
            accountSignupControls.visibility = View.GONE
            val blockedStatus = when {
                deletionRecoveryBlocksReauthentication ->
                    "계정 삭제 복구 전용 로그인이 진행 중입니다. 계정 삭제 절차에서 계속하세요."
                storageBlocksReauthentication ->
                    "로그인 저장소가 안전 차단 상태입니다. 재로그인 전에 앱 지원 담당자에게 문의하세요."
                else ->
                    "이전 로그인 상태를 안전하게 정리해야 합니다. 정리한 뒤 다시 로그인하세요."
            }
            if (staleGeneralSession && accountSessionLogoutButton.parent == null) {
                accountAccessControls.addView(accountSessionLogoutButton)
            }
            accountAccessStatusText.text = blockedStatus
            accountAccessStatusText.contentDescription = blockedStatus
            return
        }
        val creating = snapshot.stage == FirstRunOnboardingStage.ACCOUNT_CREATED
        val verifiedLogin = snapshot.stage == FirstRunOnboardingStage.VERIFIED_LOGIN
        if (verifiedLogin || reauthenticationRequired) {
            accountSignupExpanded = false
            accountSignupStep = AccountSignupStep.CONSENT
        }
        val signupVisible =
            accountSignupExpanded && !verifiedLogin && !reauthenticationRequired
        if (!signupVisible) accountSignupStep = AccountSignupStep.CONSENT
        accountLandingHeader.visibility = View.GONE
        val busy = accountRequestFence.isInFlight()
        val inSignup = signupVisible && !creating
        val onConsentStep =
            inSignup && accountSignupStep == AccountSignupStep.CONSENT
        val onDetailsStep =
            signupVisible && (creating || accountSignupStep == AccountSignupStep.DETAILS)
        accountConsentStepControls.visibility =
            if (onConsentStep) View.VISIBLE else View.GONE
        accountDetailsStepControls.visibility =
            if (onDetailsStep) View.VISIBLE else View.GONE
        val credentialFieldsVisible = !onConsentStep
        wsFieldGroupOf(accountEmailInput).visibility =
            if (credentialFieldsVisible) View.VISIBLE else View.GONE
        wsFieldGroupOf(accountPasswordInput).visibility =
            if (credentialFieldsVisible) View.VISIBLE else View.GONE
        accountLoginButton.visibility = if (signupVisible) View.GONE else View.VISIBLE
        accountSignupToggleButton.visibility = when {
            verifiedLogin || reauthenticationRequired -> View.GONE
            signupVisible -> View.GONE
            else -> View.VISIBLE
        }
        accountSignupBackButton.visibility =
            if (signupVisible) View.VISIBLE else View.GONE
        accountSignupToggleButton.text =
            when {
                signupVisible -> "로그인 화면으로 돌아가기"
                creating -> "계정 만들기 계속"
                else -> "회원가입"
            }
        accountSignupToggleButton.contentDescription =
            when {
                signupVisible ->
                    "로그인 화면으로 돌아가기. 두 번 탭하여 가입 입력 접기"
                creating ->
                    "계정 만들기 계속, 가입 입력 접힘. 두 번 탭하여 펼치기"
                else ->
                    "새 계정 만들기, 가입 입력 접힘. 두 번 탭하여 펼치기"
            }
        accountSignupControls.visibility =
            if (signupVisible && !verifiedLogin) View.VISIBLE else View.GONE
        wsFieldGroupOf(accountDateOfBirthInput).visibility =
            if (onDetailsStep) View.VISIBLE else View.GONE
        wsFieldGroupOf(accountPasswordConfirmationInput).visibility =
            if (onDetailsStep) View.VISIBLE else View.GONE
        wsFieldGroupOf(accountOtpInput).visibility =
            if (creating && signupVisible) View.VISIBLE else View.GONE
        accountConsentDisclosureToggleButton.visibility = View.GONE
        accountConsentDisclosureToggleButton.text =
            if (accountConsentDisclosureExpanded) {
                "가입 동의 자세히 접기"
            } else {
                "가입 동의 자세히 보기"
            }
        accountConsentDisclosureToggleButton.contentDescription =
            if (accountConsentDisclosureExpanded) {
                "가입 동의 자세히 보기, 펼침. 두 번 탭하여 접기"
            } else {
                "가입 동의 자세히 보기, 접힘. 두 번 탭하여 펼치기"
            }
        accountConsentDisclosureText.visibility = View.GONE
        accountConsentCards.values.forEach { card ->
            card.visibility = if (onConsentStep) View.VISIBLE else View.GONE
        }
        accountConsentChecks.values.forEach { check -> check.isEnabled = !busy }
        accountConsentAllCheck.isEnabled = !busy
        accountRequestOtpButton.visibility =
            if (
                onDetailsStep &&
                snapshot.stage == FirstRunOnboardingStage.EMAIL_OTP_ENROLLMENT
            ) {
                View.VISIBLE
            } else {
                View.GONE
            }
        accountCreateButton.visibility =
            if (creating && signupVisible) View.VISIBLE else View.GONE
        accountSessionLogoutButton.visibility = View.GONE
        refreshAccountConsentSummary()
        refreshAccountActionAvailability()
        accountEmailInput.isEnabled = !busy
        accountDateOfBirthInput.isEnabled = !busy
        accountPasswordInput.isEnabled = !busy
        accountPasswordConfirmationInput.isEnabled = !busy
        accountOtpInput.isEnabled = !busy
        val partial = emailEnrollmentPartial
        val status = when {
            busy -> "계정 요청을 안전하게 처리하고 있습니다. 버튼을 다시 누르지 마세요."
            accountAccessNotice != null -> requireNotNull(accountAccessNotice)
            emailEnrollmentStorageBlocked ->
                "가입 임시 상태를 안전하게 저장할 수 없습니다. 기존 계정 로그인만 가능합니다."
            signupVisible && creating && partial != null -> null
            snapshot.stage == FirstRunOnboardingStage.VERIFIED_LOGIN ->
                "계정 생성이 완료되었습니다."
            reauthenticationRequired ->
                "다시 로그인해 주세요."
            else -> null
        }
        accountAccessStatusText.text = status
        accountAccessStatusText.contentDescription = status
        accountAccessStatusText.visibility = if (status == null) View.GONE else View.VISIBLE
    }

    private fun updateWalkReadinessSection() {
        if (
            !::walkReadinessControls.isInitialized ||
            !::walkReadinessSummaryText.isInitialized ||
            !::walkReadinessToggleButton.isInitialized
        ) return
        val walkState = if (::walkSessionLifecycle.isInitialized) {
            walkSessionLifecycle.snapshot().state
        } else {
            WalkSessionState.READY
        }
        if (walkState == WalkSessionState.ACTIVE) {
            walkReadinessControls.visibility = View.GONE
            walkReadinessSummaryText.visibility = View.GONE
            walkReadinessToggleButton.visibility = View.GONE
            return
        }
        if (walkReadinessControls.visibility == View.GONE) {
            walkReadinessSummaryText.visibility = View.GONE
            walkReadinessToggleButton.visibility = View.GONE
            return
        }
        val everythingPassed =
            walkState != WalkSessionState.PAUSED &&
                firstRunOnboardingComplete() &&
                postLoginDeviceCheckSnapshot.passesFeatureGate &&
                startupCapabilityDecision?.mayConfirmAndStart == true &&
                isStartupCapabilityConfirmed()
        if (!everythingPassed) {
            walkReadinessControls.visibility = View.VISIBLE
            walkReadinessSummaryText.visibility = View.GONE
            walkReadinessToggleButton.visibility = View.GONE
            return
        }
        walkReadinessToggleButton.visibility = View.VISIBLE
        walkReadinessToggleButton.text =
            if (walkReadinessExpanded) "기기 준비 상태 접기" else "기기 준비 상태 펼치기"
        walkReadinessToggleButton.contentDescription =
            if (walkReadinessExpanded) {
                "기기 준비 상태, 펼침. 두 번 탭하여 접기"
            } else {
                "기기 준비 상태, 접힘. 두 번 탭하여 펼치기"
            }
        walkReadinessControls.visibility =
            if (walkReadinessExpanded) View.VISIBLE else View.GONE
        walkReadinessSummaryText.visibility =
            if (walkReadinessExpanded) View.GONE else View.VISIBLE
        val summary = if (hasCurrentPostLoginDeviceRestrictions()) {
            val preparation = if (cameraAnalysisFeaturesEnabled()) {
                "장착과 사용 중인 기능 범위의 환경 점검을 통과했습니다."
            } else {
                "사용 중인 기능 범위의 환경 점검을 통과했고, " +
                    "제한된 카메라 장착 점검은 생략했습니다."
            }
            "기기 준비 완료. $preparation 현재 제한 기능: " +
                "${postLoginDeviceCheckDisabledFeatureText()}. " +
                "나머지 기능은 사용할 수 있습니다."
        } else {
            "기기 준비 완료. 장착, 환경, 기기 점검을 모두 통과했습니다."
        }
        walkReadinessSummaryText.text = summary
        walkReadinessSummaryText.contentDescription = summary
    }

    private fun updateFirstRunOnboardingUi() {
        if (
            !::firstRunOnboardingSnapshot.isInitialized ||
            !::firstRunOnboardingStatusText.isInitialized
        ) return
        val snapshot = firstRunOnboardingSnapshot
        val stageNumber = firstRunStageNumber(snapshot)
        val stageCount = firstRunStageCount(snapshot)
        val message = when (snapshot.stage) {
            FirstRunOnboardingStage.EMAIL_OTP_ENROLLMENT ->
                "첫 실행 $stageNumber/${stageCount}단계. 로그인하거나 새 계정을 만드세요."
            FirstRunOnboardingStage.ACCOUNT_CREATED ->
                "첫 실행 $stageNumber/${stageCount}단계. 인증번호를 입력해 계정을 만드세요."
            FirstRunOnboardingStage.PURPOSE_AND_SAFETY ->
                "첫 실행 $stageNumber/${stageCount}단계. 서비스 목적과 안전 한계를 확인하세요."
            FirstRunOnboardingStage.AGE_AND_GUARDIAN_NEED ->
                "첫 실행 $stageNumber/${stageCount}단계. 연령 구간을 확인하세요."
            FirstRunOnboardingStage.INTEGRATED_CONSENT ->
                "첫 실행 $stageNumber/${stageCount}단계. 필수·선택 동의를 확인하세요."
            FirstRunOnboardingStage.LOCAL_CREDENTIAL_PHONE_SUBMISSION ->
                "첫 실행 $stageNumber/${stageCount}단계. 본인 확인 제출 상태를 확인하세요."
            FirstRunOnboardingStage.VERIFIED_SMS ->
                "첫 실행 $stageNumber/${stageCount}단계. 인증 확인을 기다리는 중입니다."
            FirstRunOnboardingStage.GUARDIAN_APPROVAL ->
                "첫 실행 $stageNumber/${stageCount}단계. 보호자 확인을 기다리는 중입니다."
            FirstRunOnboardingStage.ACCOUNT_ACTIVATION ->
                "첫 실행 $stageNumber/${stageCount}단계. 계정 활성화를 기다리는 중입니다."
            FirstRunOnboardingStage.VERIFIED_LOGIN ->
                if (snapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4) {
                    "첫 실행 $stageNumber/${stageCount}단계. 만든 계정으로 로그인하세요."
                } else {
                    "첫 실행 $stageNumber/${stageCount}단계. 로그인 확인을 기다리는 중입니다."
                }
            FirstRunOnboardingStage.JIT_PERMISSION_OBSERVATION ->
                "첫 실행 $stageNumber/${stageCount}단계. 필요한 권한을 확인하세요."
            FirstRunOnboardingStage.DEVICE_CHECK ->
                "첫 실행 $stageNumber/${stageCount}단계. 기기 기능을 점검하세요."
            FirstRunOnboardingStage.FP004_TRAINING ->
                if (shouldShowFirstRunPhonePosture()) {
                    "사전 연습의 착용 방법과 사용 환경을 확인하고 안내를 끝까지 들어 주세요."
                } else {
                    "안전 제한 안내와 연습 필요성을 차례대로 들은 뒤 동의하세요."
                }
            FirstRunOnboardingStage.COMPLETE ->
                if (firstRunOnboardingComplete()) {
                    "첫 실행 $stageNumber/${stageCount}단계 완료. 첫 설정을 완료했습니다."
                } else {
                    "첫 실행 $stageNumber/${stageCount}단계 완료 기록은 있으나 " +
                        "현재 권한·안전 상태 재확인이 필요합니다. 기능은 잠겨 있습니다."
                }
            FirstRunOnboardingStage.BLOCKED_UNDER_14 ->
                "첫 실행 $stageNumber/${stageCount}단계. 만 14세 미만은 가입할 수 없습니다."
        }
        firstRunOnboardingStatusText.text = message
        firstRunOnboardingStatusText.contentDescription = message
        applyStageHeadingStyle(message)
        updateEmailAccountAccessUi(snapshot)
        firstRunPurposeButton.visibility =
            if (snapshot.stage == FirstRunOnboardingStage.PURPOSE_AND_SAFETY) {
                View.VISIBLE
            } else {
                View.GONE
            }
        firstRunPurposeButton.isEnabled =
            snapshot.stage == FirstRunOnboardingStage.PURPOSE_AND_SAFETY
        firstRunAgeButtons.forEach { (_, button) ->
            button.visibility =
                if (snapshot.stage == FirstRunOnboardingStage.AGE_AND_GUARDIAN_NEED) {
                    View.VISIBLE
                } else {
                    View.GONE
                }
            button.isEnabled =
                snapshot.stage == FirstRunOnboardingStage.AGE_AND_GUARDIAN_NEED
        }
        val integratedConsentVisible =
            snapshot.stage == FirstRunOnboardingStage.INTEGRATED_CONSENT
        if (::firstRunIntegratedConsentDisclosureText.isInitialized) {
            // 항목마다 승인 전문의 해당 조항을 이미 담고 있으므로, 문서 전체는 요청할 때만 편다.
            firstRunIntegratedConsentDisclosureText.visibility =
                if (integratedConsentVisible && firstRunDisclosureExpanded) {
                    View.VISIBLE
                } else {
                    View.GONE
                }
        }
        if (::firstRunDisclosureToggleButton.isInitialized) {
            firstRunDisclosureToggleButton.visibility =
                if (integratedConsentVisible) View.VISIBLE else View.GONE
            firstRunDisclosureToggleButton.text =
                if (firstRunDisclosureExpanded) "통합 동의 전문 접기" else "통합 동의 전문 보기"
            firstRunDisclosureToggleButton.contentDescription =
                firstRunDisclosureToggleButton.text
        }
        firstRunIntegratedConsentButtons.values.forEach { button ->
            button.visibility =
                if (integratedConsentVisible) View.VISIBLE else View.GONE
        }
        firstRunConsentCards.values.forEach { card ->
            card.visibility = if (integratedConsentVisible) View.VISIBLE else View.GONE
        }
        if (::firstRunConsentCountText.isInitialized) {
            firstRunConsentCountText.visibility =
                if (integratedConsentVisible) View.VISIBLE else View.GONE
        }
        if (::firstRunConsentAllButton.isInitialized) {
            firstRunConsentAllButton.visibility =
                if (integratedConsentVisible) View.VISIBLE else View.GONE
            val allGranted =
                IntegratedConsentItem.entries.all(integratedConsentDraft::isGranted)
            val label = if (allGranted) "네 항목 모두 거부" else INTEGRATED_CONSENT_ALL_LABEL
            firstRunConsentAllButton.text = label
            firstRunConsentAllButton.contentDescription = label
        }
        if (::firstRunIntegratedConsentSaveButton.isInitialized) {
            firstRunIntegratedConsentSaveButton.visibility =
                if (integratedConsentVisible) View.VISIBLE else View.GONE
        }
        updateIntegratedConsentUi()

        if (::firstRunWaitingCard.isInitialized) {
            val waitingText = firstRunWaitingTextOrNull(snapshot)
            firstRunWaitingCard.visibility =
                if (waitingText == null) View.GONE else View.VISIBLE
            if (waitingText != null && firstRunWaitingText.text != waitingText) {
                firstRunWaitingText.text = waitingText
                firstRunWaitingText.contentDescription = waitingText
            }
            updateFirstRunWaitingDots(
                active = waitingText != null && isActivityForeground,
            )
        }

        val mayTrain = !developmentQuickStartEnabled &&
            snapshot.stage == FirstRunOnboardingStage.FP004_TRAINING
        val showWalkPreparation = snapshot.isComplete ||
            (developmentQuickStartEnabled && firstRunOnboardingComplete())
        val showPhoneMountingPreparation =
            showWalkPreparation && cameraAnalysisFeaturesEnabled()
        val mayCheckDevice =
            !developmentQuickStartEnabled &&
                snapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 &&
                currentPostLoginDeviceCheckSessionBinding() != null &&
                snapshot.stage in setOf(
                    FirstRunOnboardingStage.JIT_PERMISSION_OBSERVATION,
                    FirstRunOnboardingStage.DEVICE_CHECK,
                    FirstRunOnboardingStage.FP004_TRAINING,
                    FirstRunOnboardingStage.COMPLETE,
                )
        val mayUseWalk = firstRunOnboardingComplete()
        val walkState = if (::walkSessionLifecycle.isInitialized) {
            walkSessionLifecycle.snapshot().state
        } else {
            WalkSessionState.READY
        }
        val walkScreenVisible = mayUseWalk && walkState in setOf(
            WalkSessionState.ACTIVE,
            WalkSessionState.PAUSED,
        )
        firstRunOnboardingControls.visibility =
            if (developmentQuickStartEnabled || walkScreenVisible) View.GONE else View.VISIBLE
        if (::priorityUserOnboardingControls.isInitialized) {
            priorityUserOnboardingControls.visibility =
                if (mayTrain) View.VISIBLE else View.GONE
            priorityUserAgeButtons.values.forEach { button ->
                button.visibility = View.GONE
                button.isEnabled = false
            }
            loginUserIdInput.visibility = View.GONE
            loginSaveButton.visibility = View.GONE
            accountLogoutButton.visibility = View.GONE
        }
        if (::officialEnvironmentStatusText.isInitialized) {
            officialEnvironmentStatusText.visibility =
                if (showWalkPreparation && !developmentGuidanceStartBypassEnabled) View.VISIBLE else View.GONE
            officialEnvironmentConfirmButton.visibility =
                if (showWalkPreparation && !developmentGuidanceStartBypassEnabled) View.VISIBLE else View.GONE
            phoneMountingStatusText.visibility =
                if (showWalkPreparation && !developmentGuidanceStartBypassEnabled) View.VISIBLE else View.GONE
            phoneMountingChestConfirmButton.visibility =
                if (showPhoneMountingPreparation && !developmentGuidanceStartBypassEnabled &&
                    (!developmentQuickStartEnabled || walkState != WalkSessionState.READY)
                ) View.VISIBLE else View.GONE
            phoneMountingNecklaceConfirmButton.visibility = View.GONE
        }
        if (::startupCapabilityText.isInitialized) {
            startupCapabilityText.visibility =
                if (mayCheckDevice) View.VISIBLE else View.GONE
            startupCapabilityConfirmButton.visibility =
                if (showWalkPreparation && !developmentGuidanceStartBypassEnabled) View.VISIBLE else View.GONE
        }
        if (::fieldSessionLogButton.isInitialized) {
            fieldSessionLogButton.visibility =
                if (mayUseWalk) View.VISIBLE else View.GONE
        }
        if (::walkReadinessControls.isInitialized) {
            val showReadiness = mayTrain || mayCheckDevice || showWalkPreparation
            walkReadinessControls.visibility =
                if (showReadiness && walkState != WalkSessionState.ACTIVE) {
                    View.VISIBLE
                } else {
                    View.GONE
                }
            updateWalkReadinessSection()
        }
        if (::walkStatusSection.isInitialized) {
            walkStatusSection.visibility = if (mayUseWalk) View.VISIBLE else View.GONE
        }
        if (::runtimeControls.isInitialized) {
            runtimeControls.visibility =
                if (
                    mayUseWalk &&
                    walkState == WalkSessionState.ACTIVE &&
                    !permissionRecoveryGate.blocksAutomaticResourceStart
                ) {
                    View.VISIBLE
                } else {
                    View.GONE
                }
        }
        if (::destinationQueryInput.isInitialized) updateWalkFeatureAvailabilityUi()
        if (developmentQuickStartEnabled) {
            developmentQuickStartButton?.isEnabled = !developmentQuickStartRequested &&
                !accountRequestFence.isInFlight() && !walkSessionPermissionRequestInFlight
            developmentQuickStartButton?.text = if (walkState == WalkSessionState.PAUSED) {
                "보행 재개 상태 확인"
            } else {
                "개발 기능 테스트 시작 / 다시 시도"
            }
        }
        refreshHomeCards()
        refreshFirstRunNoticeUi()
        if (::firstRunProgressBar.isInitialized) {
            firstRunProgressSegments.forEachIndexed { index, segment ->
                segment.setBackgroundColor(
                    if (index < stageNumber) WS_COLOR_EMPHASIS else WS_COLOR_LINE,
                )
            }
            firstRunProgressBar.visibility =
                if (developmentQuickStartEnabled || firstRunOnboardingComplete() || isAccountEntryScreen()) {
                    View.GONE
                } else {
                    View.VISIBLE
                }
        }
        updatePrivacySectionVisibility()
        renderMainUi()
    }

    private fun linkPriorityUserAccessibilityTraversal() {
        val controls = buildList<View> {
            add(priorityUserOnboardingStatusText)
            add(priorityUserEducationProgressText)
            add(priorityUserEducationBodyText)
            add(loginUserIdInput)
            add(loginSaveButton)
            add(accountLogoutButton)
            listOf(
                PriorityUserAgeBand.ADULT_18_PLUS,
                PriorityUserAgeBand.AGE_14_TO_17,
                PriorityUserAgeBand.UNDER_14,
            ).forEach { ageBand -> add(priorityUserAgeButtons.getValue(ageBand)) }
            add(priorityUserEducationButton)
            add(priorityUserSafePlaceButton)
            PriorityUserPractice.entries.forEach { practice ->
                add(priorityUserPracticeButtons.getValue(practice))
            }
            add(priorityUserResetButton)
        }
        controls.forEach { view ->
            if (view.id == View.NO_ID) view.id = View.generateViewId()
        }
        controls.zipWithNext().forEach { (previous, current) ->
            current.accessibilityTraversalAfter = previous.id
        }
        val focusableControls = controls.filter(View::isFocusable)
        focusableControls.zipWithNext().forEach { (previous, current) ->
            previous.nextFocusForwardId = current.id
            previous.nextFocusDownId = current.id
            current.nextFocusUpId = previous.id
        }
        loginUserIdInput.contentDescription = "교육 대상 로그인 ID 입력"
        loginSaveButton.contentDescription = "교육 대상 로그인 ID 확인"
        accountLogoutButton.contentDescription = "사용자 로그아웃"
    }

    private fun currentPriorityUserSupportEnvironment(
        decision: WalkSafeStartupCapabilityDecision? = startupCapabilityDecision,
    ): PriorityUserSupportEnvironment {
        val pending = decision?.pendingRequirements.orEmpty()
        val unavailable = decision?.unavailableRequirements.orEmpty()
        fun isAvailable(requirement: WalkSafeStartupRequirement): Boolean =
            decision != null && requirement !in pending && requirement !in unavailable
        return PriorityUserSupportEnvironment(
            screenReaderActive = isScreenReaderActive(),
            largeTextEnabled = resources.configuration.fontScale >= 1.3f,
            highContrastEnabled = Settings.Secure.getInt(
                contentResolver,
                "high_text_contrast_enabled",
                0,
            ) == 1,
            offlineKoreanVoiceAvailable = isAvailable(
                WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS,
            ),
            vibrationAvailable = startupCapabilityProbe.snapshot().vibrationAvailable == true,
        )
    }

    private fun updatePriorityUserOnboardingUi(
        capabilityDecision: WalkSafeStartupCapabilityDecision? = startupCapabilityDecision,
    ) {
        if (
            !::priorityUserOnboardingPolicy.isInitialized ||
            !::priorityUserOnboardingStatusText.isInitialized
        ) return
        if (firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4) {
            updateNativeSafetyEducationUi()
            return
        }
        firstRunPhonePostureControls.visibility = View.GONE
        priorityUserEducationBodyText.visibility = View.GONE
        priorityUserEducationProgressText.visibility = View.GONE
        priorityUserPracticeNecessityButton.visibility = View.GONE
        priorityUserEducationAgreeButton.visibility = View.GONE
        val environment = currentPriorityUserSupportEnvironment(capabilityDecision)
        val snapshot = priorityUserOnboardingPolicy.snapshot()
        val decision = priorityUserOnboardingPolicy.evaluate(
            environment = environment,
            walkIsActive = isWalkSessionRuntimeActive(),
        )
        val accountBound =
            reporterUserId != null &&
                priorityUserOnboardingActorId == reporterUserId
        val deviceGateOpen = postLoginDeviceCheckPassesFeatureGate()
        val trainingDeliveryInFlight =
            priorityUserEducationInFlight || priorityUserPracticeInFlight != null
        val accessibilityModes = buildList {
            if (environment.screenReaderActive) add("화면읽기 사용 중")
            if (environment.largeTextEnabled) add("큰 글자 사용 중")
            if (environment.highContrastEnabled) add("고대비 사용 중")
        }.ifEmpty { listOf("기본 표시 설정") }
        val remaining = decision.remainingPractices.joinToString(", ") {
            it.actionLabelKo.removeSuffix(" 연습")
        }
        val message = buildString {
            append("전맹·저시력 사용자를 같은 우선순위로 지원합니다.\n")
            append("연령: ${snapshot.ageBand.labelKo} · ${accessibilityModes.joinToString(" · ")}\n")
            if (accountBound) {
                if (deviceGateOpen) {
                    append(decision.noticeKo)
                } else {
                    append("안전교육 전에 권한과 기기 기능 점검을 다시 완료하세요.")
                }
            } else {
                append("먼저 교육 대상 로그인 ID를 입력하고 확인하세요.")
            }
            if (trainingDeliveryInFlight) {
                append("\n음성 재생과 진동 연습 확인이 끝날 때까지 기다리세요.")
            }
            if (remaining.isNotBlank()) append("\n남은 연습: $remaining")
        }
        priorityUserOnboardingStatusText.text = message
        priorityUserOnboardingStatusText.contentDescription = message
        priorityUserOnboardingStatusText.setTextColor(WS_COLOR_BUTTON_TEXT)
        val panelDensity = resources.displayMetrics.density
        priorityUserOnboardingControls.background = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = WS_CORNER_RADIUS_DP * panelDensity
            setColor(WS_COLOR_NOTICE_FILL)
            setStroke(
                ((if (environment.highContrastEnabled) 2f else 1f) * panelDensity).roundToInt(),
                if (environment.highContrastEnabled) WS_COLOR_BUTTON_BORDER else WS_COLOR_LINE,
            )
        }
        priorityUserOnboardingControls.setPadding(
            (16f * panelDensity).roundToInt(),
            (16f * panelDensity).roundToInt(),
            (16f * panelDensity).roundToInt(),
            (16f * panelDensity).roundToInt(),
        )
        priorityUserAgeButtons.forEach { (ageBand, button) ->
            button.isEnabled = accountBound && !trainingDeliveryInFlight
            button.text = "연령: ${ageBand.labelKo}" +
                if (snapshot.ageBand == ageBand) " · 선택됨" else ""
            button.contentDescription = button.text
        }
        val accountEligible =
            accountBound && deviceGateOpen && decision.mayActivateAccount
        priorityUserEducationButton.text = if (priorityUserPracticeInFlight != null) {
            "이번 연습 중지"
        } else if (priorityUserEducationInFlight) {
            "안전교육 듣기 중지"
        } else if (snapshot.educationReviewed) {
            "1. 안전 제한 안내 다시 듣기"
        } else {
            "1. 안전 제한 안내 듣기"
        }
        priorityUserEducationButton.contentDescription = priorityUserEducationButton.text
        priorityUserEducationButton.isEnabled = priorityUserPracticeInFlight != null || priorityUserEducationInFlight ||
            (accountEligible && !trainingDeliveryInFlight)
        priorityUserSafePlaceButton.isEnabled =
            accountEligible &&
                snapshot.educationReviewed &&
                !trainingDeliveryInFlight
        priorityUserPracticeButtons.forEach { (practice, button) ->
            val awaitingHazardResponse = practice == PriorityUserPractice.HAZARD_ALERT &&
                priorityUserPracticeAttemptToken?.let(priorityUserOnboardingPolicy::isHazardResponseReady) == true
            button.isEnabled =
                accountEligible &&
                    snapshot.safePracticePlaceConfirmed &&
                    !snapshot.requiresPracticeRestart &&
                    snapshot.nextRequiredPractice == practice &&
                    (!trainingDeliveryInFlight || awaitingHazardResponse)
            val completed = practice in snapshot.completedPractices
            val current = snapshot.nextRequiredPractice == practice
            button.text = if (awaitingHazardResponse) PriorityUserEducationPresentation.hazardResponseActionKo else practice.actionLabelKo +
                when {
                    completed -> " · 완료"
                    current -> " · 다음"
                    else -> " · 순서 대기"
                }
            button.contentDescription = button.text
        }
        priorityUserResetButton.isEnabled =
            accountBound &&
                deviceGateOpen &&
                !trainingDeliveryInFlight &&
                (
                    snapshot.educationReviewed ||
                        snapshot.safePracticePlaceConfirmed ||
                        snapshot.completedPractices.isNotEmpty()
                )
        loginUserIdInput.isEnabled = !trainingDeliveryInFlight
        loginSaveButton.isEnabled = !trainingDeliveryInFlight
        updateLoginButtonText()
    }

    private fun selectPriorityUserAgeBand(ageBand: PriorityUserAgeBand) {
        if (firstRunOnboardingSnapshot.ageBand != null) {
            updateStatus(
                "가입 연령 변경 불가",
                "첫 실행 등록에서 확인한 연령 구간을 안전교육 화면에서 바꿀 수 없습니다.",
            )
            return
        }
        if (
            reporterUserId == null ||
            priorityUserOnboardingActorId != reporterUserId
        ) {
            updateStatus(
                "교육 대상 ID 확인 필요",
                "연령대를 선택하기 전에 교육 대상 로그인 ID를 입력하고 확인하세요.",
            )
            return
        }
        cancelPendingPriorityUserTrainingFeedback()
        if (!beginPriorityUserProfileMutationOrFailClosed()) {
            updateStatus(
                "교육 상태 변경 실패",
                "변경 전 안전 표식을 저장하지 못해 현재 실행에서는 계정과 보행 기능을 열지 않습니다.",
            )
            enforcePriorityUserAccountEligibility()
            updatePriorityUserOnboardingUi()
            return
        }
        priorityUserOnboardingPolicy.selectAgeBand(ageBand)
        if (!persistPriorityUserOnboardingOrFailClosed()) {
            updateStatus(
                "교육 상태 저장 실패",
                "앱 전용 저장소를 확인할 수 없어 계정과 보행 기능을 열지 않습니다.",
            )
        }
        enforcePriorityUserAccountEligibility()
        updatePriorityUserOnboardingUi()
        updateLoginButtonText()
        updateBackendAuthButtonText()
        val notice = priorityUserOnboardingPolicy.evaluate(
            currentPriorityUserSupportEnvironment(),
        ).noticeKo
        speakInteraction(notice)
        if (::startupCapabilityProbe.isInitialized) refreshStartupCapabilityUi()
    }

    private fun reviewPriorityUserSafetyEducation() {
        if (priorityUserPracticeInFlight != null) {
            cancelPendingPriorityUserTrainingFeedback()
            updateStatus("이번 연습 중지", "이번 연습은 완료하지 않았습니다. 같은 연습 버튼으로 다시 시도하세요. 이전 완료 기록은 유지됩니다.")
            return
        }
        if (priorityUserEducationInFlight) {
            if (priorityUserEducationPlaybackIsPracticeNecessity) return
            cancelPendingPriorityUserTrainingFeedback()
            updateStatus(
                "안전교육 듣기 중지",
                "이번 재생은 완료로 기록하지 않습니다. 이미 완료한 청취 기록은 유지됩니다.",
            )
            return
        }
        if (firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4) {
            playNativeSafetyEducation(practiceNecessity = false)
            return
        }
        if (!requireDeviceCheckForPriorityUserTraining()) return
        val accountBlock = priorityUserOnboardingPolicy.accountBlockReason()
        val actorId = reporterUserId
        if (
            actorId == null ||
            priorityUserOnboardingActorId != actorId ||
            accountBlock != null
        ) {
            val notice = accountBlock?.noticeKo
                ?: "먼저 교육 대상 로그인 ID를 입력하고 확인하세요."
            speakInteraction(notice)
            return
        }
        if (priorityUserEducationInFlight || priorityUserPracticeInFlight != null) {
            updateStatus(
                "안전 제한 안내 재생 중",
                "현재 안내가 끝날 때까지 기다리세요.",
            )
            return
        }
        val policy = priorityUserOnboardingPolicy
        stopAccountConsentSpeech()
        if (voiceRecognitionActive) cancelVoiceCommandRecognition()
        val generation = ++priorityUserTrainingGeneration
        priorityUserEducationPlaybackIsPracticeNecessity = false
        priorityUserEducationInFlight = true
        updatePriorityUserOnboardingUi()
        updateStatus(
            "안전 제한 안내 재생 중",
            "오프라인 한국어 음성이 끝난 뒤에만 안내 완료를 기록합니다. 같은 버튼으로 중지할 수 있습니다.",
        )
        val completed = {
            runOnUiThread {
                if (
                    !isPriorityUserTrainingDeliveryCurrent(
                        generation = generation,
                        actorId = actorId,
                        policy = policy,
                    ) ||
                    !priorityUserEducationInFlight
                ) {
                    clearPriorityUserTrainingDeliveryIfOwned(
                        generation = generation,
                        actorId = actorId,
                        policy = policy,
                        token = null,
                    )
                    return@runOnUiThread
                }
                if (!beginPriorityUserProfileMutationOrFailClosed()) {
                    priorityUserTrainingGeneration += 1L
                    priorityUserEducationInFlight = false
                    updateStatus(
                        "안전 제한 안내 저장 실패",
                        "변경 전 안전 표식을 저장하지 못해 현재 실행에서는 계정과 보행 기능을 열지 않습니다.",
                    )
                    updatePriorityUserOnboardingUi()
                    if (::startupCapabilityProbe.isInitialized) {
                        refreshStartupCapabilityUi()
                    }
                    return@runOnUiThread
                }
                policy.reviewSafetyEducation(
                    voicePlaybackCompleted = true,
                )
                priorityUserTrainingGeneration += 1L
                priorityUserEducationInFlight = false
                if (!persistPriorityUserOnboardingOrFailClosed()) {
                    updateStatus(
                        "안전 제한 안내 저장 실패",
                        "교육 완료를 저장하지 못해 보행 기능을 열지 않습니다.",
                    )
                }
                updatePriorityUserOnboardingUi()
                if (::startupCapabilityProbe.isInitialized) {
                    refreshStartupCapabilityUi()
                }
            }
        }
        val failed = {
            failPriorityUserTrainingDelivery(
                generation = generation,
                actorId = actorId,
                policy = policy,
                token = null,
                detail = "음성 재생이 끝나지 않아 안내 완료를 기록하지 않았습니다. 같은 버튼을 다시 누르세요.",
            )
        }
        val dispatch = ensureFeedbackActuator().speakPriorityUserTraining(
            message = "WalkSafe는 흰지팡이와 안내견을 대신하지 않습니다. " +
                "위험 안내를 들으면 멈추세요. 실제 도로가 아닌 안전한 장소에서 먼저 연습하세요.",
            onCompleted = completed,
            onFailed = failed,
        )
        if (dispatch != NavigationSpeechDispatchResult.ACCEPTED) {
            failed()
        }
    }

    private fun confirmPriorityUserSafePracticePlace() {
        if (!requireDeviceCheckForPriorityUserTraining()) return
        val before = priorityUserOnboardingPolicy.snapshot()
        if (
            (before.safePracticePlaceConfirmed && !before.requiresPracticeRestart) ||
            !before.educationReviewed ||
            (shouldShowFirstRunPhonePosture() &&
                (!before.usageConditionsAcknowledged || !before.appUsageReviewed)) ||
            priorityUserEducationInFlight || priorityUserPracticeInFlight != null ||
            priorityUserOnboardingPolicy.accountBlockReason() != null
        ) {
            val notice = priorityUserOnboardingPolicy.evaluate(
                currentPriorityUserSupportEnvironment(),
            ).noticeKo
            speakInteraction(notice)
            return
        }
        if (!beginPriorityUserProfileMutationOrFailClosed()) {
            updateStatus(
                "안전한 연습 장소 저장 실패",
                "변경 전 안전 표식을 저장하지 못해 현재 실행에서는 계정과 보행 기능을 열지 않습니다.",
            )
            updatePriorityUserOnboardingUi()
            return
        }
        priorityUserOnboardingPolicy.confirmSafePracticePlace()
        val persisted = persistPriorityUserOnboardingOrFailClosed()
        if (!persisted) {
            updateStatus(
                "안전한 연습 장소 저장 실패",
                "확인 상태를 저장하지 못해 연습과 보행 기능을 열지 않습니다.",
            )
        }
        updatePriorityUserOnboardingUi()
        if (persisted) {
            speakInteraction("안전한 장소를 확인했습니다. 위험 안내 연습 버튼을 누르세요.")
        }
    }

    private fun performPriorityUserPractice(practice: PriorityUserPractice) {
        if (!requireDeviceCheckForPriorityUserTraining()) return
        if (practice == PriorityUserPractice.HAZARD_ALERT &&
            priorityUserPracticeInFlight == PriorityUserPractice.HAZARD_ALERT) {
            confirmPriorityUserHazardResponse()
            return
        }
        val actorId = reporterUserId
        val environment = currentPriorityUserSupportEnvironment()
        val voiceGuidanceEnabled =
            postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.VOICE_GUIDANCE)
        val hapticFeedbackEnabled =
            postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.HAPTIC_FEEDBACK)
        val before = priorityUserOnboardingPolicy.snapshot()
        val currentDecision = priorityUserOnboardingPolicy.evaluate(environment)
        if (
            actorId == null ||
            priorityUserOnboardingActorId != actorId ||
            currentDecision.accountBlockReason != null ||
            !before.educationReviewed ||
            !before.safePracticePlaceConfirmed ||
            before.requiresPracticeRestart ||
            (shouldShowFirstRunPhonePosture() &&
                (!before.usageConditionsAcknowledged || !before.appUsageReviewed)) ||
            priorityUserEducationInFlight ||
            priorityUserPracticeInFlight != null
        ) {
            speakInteraction(
                if (actorId == null || priorityUserOnboardingActorId != actorId) {
                    "먼저 교육 대상 로그인 ID를 입력하고 확인하세요."
                } else {
                    currentDecision.noticeKo
                },
            )
            return
        }
        val policy = priorityUserOnboardingPolicy
        val requiredDeliverySignals = buildSet {
            if (voiceGuidanceEnabled) add(PriorityUserPracticeDeliverySignal.SPEECH_PLAYBACK_COMPLETED)
            if (hapticFeedbackEnabled) add(PriorityUserPracticeDeliverySignal.VIBRATION_REQUEST_WINDOW_ELAPSED)
        }
        if (requiredDeliverySignals.isEmpty()) {
            updateStatus("연습 안내 수단 확인 필요", "음성 또는 진동을 사용할 수 있도록 기기 점검을 다시 완료하세요.")
            return
        }
        val token = policy.beginPractice(practice, requiredDeliverySignals)
        if (token == null) {
            val next = before.nextRequiredPractice
            speakInteraction(
                next?.let { "먼저 ${it.actionLabelKo} 버튼을 누르세요." }
                    ?: "필수 조작 연습을 이미 완료했습니다.",
            )
            return
        }
        val generation = ++priorityUserTrainingGeneration
        priorityUserPracticeInFlight = practice
        priorityUserPracticeAttemptToken = token
        stopAccountConsentSpeech()
        if (voiceRecognitionActive) cancelVoiceCommandRecognition()
        updatePriorityUserOnboardingUi()
        updateStatus(
            "${practice.actionLabelKo} 진행 중",
            "사용 가능한 안내 방식으로 ${practice.instructionKo}",
        )
        val failed = {
            failPriorityUserTrainingDelivery(
                generation = generation,
                actorId = actorId,
                policy = policy,
                token = token,
                detail = "음성 재생 또는 진동 요청 패턴을 끝까지 확인하지 못해 연습을 기록하지 않았습니다.",
            )
        }
        val actuator = ensureFeedbackActuator()
        if (hapticFeedbackEnabled) {
            val vibrationAccepted = actuator.playPriorityUserTrainingVibration(
                onWindowElapsed = {
                    recordPriorityUserPracticeDelivery(
                        generation = generation,
                        actorId = actorId,
                        policy = policy,
                        token = token,
                        signal =
                            PriorityUserPracticeDeliverySignal.VIBRATION_REQUEST_WINDOW_ELAPSED,
                    )
                },
                onFailed = failed,
            )
            if (!vibrationAccepted) {
                failed()
                return
            }
        }
        if (voiceGuidanceEnabled) {
            val speech = actuator.speakPriorityUserTraining(
                message = practice.instructionKo,
                onCompleted = {
                    recordPriorityUserPracticeDelivery(
                        generation = generation,
                        actorId = actorId,
                        policy = policy,
                        token = token,
                        signal = PriorityUserPracticeDeliverySignal.SPEECH_PLAYBACK_COMPLETED,
                    )
                },
                onFailed = failed,
            )
            if (speech != NavigationSpeechDispatchResult.ACCEPTED) {
                failed()
            }
        }
    }

    private fun confirmPriorityUserHazardResponse() {
        val actorId = reporterUserId ?: return
        val policy = priorityUserOnboardingPolicy
        val token = priorityUserPracticeAttemptToken ?: return
        if (priorityUserPracticeInFlight != PriorityUserPractice.HAZARD_ALERT ||
            !isPriorityUserTrainingDeliveryCurrent(priorityUserTrainingGeneration, actorId, policy) ||
            !policy.isHazardResponseReady(token)) return
        if (!beginPriorityUserProfileMutationOrFailClosed()) {
            cancelPendingPriorityUserTrainingFeedback()
            updateStatus("멈춤 확인 저장 실패", "연습 결과를 저장할 수 없어 이번 연습을 완료하지 않았습니다.")
            return
        }
        val after = policy.confirmHazardResponse(token)
        if (!persistPriorityUserOnboardingOrFailClosed()) {
            cancelPendingPriorityUserTrainingFeedback()
            updateStatus("멈춤 확인 저장 실패", "멈춤 확인을 저장하지 못했습니다. 저장 상태를 확인한 뒤 다시 연습하세요.")
            return
        }
        if (after.hazardResponseConfirmed) completePriorityUserPracticeStep(after, actorId)
    }

    private fun recordPriorityUserPracticeDelivery(
        generation: Long,
        actorId: String,
        policy: PriorityUserOnboardingPolicy,
        token: PriorityUserPracticeAttemptToken,
        signal: PriorityUserPracticeDeliverySignal,
    ) {
        runOnUiThread {
            if (
                !isPriorityUserTrainingDeliveryCurrent(
                    generation = generation,
                    actorId = actorId,
                    policy = policy,
                )
            ) {
                clearPriorityUserTrainingDeliveryIfOwned(
                    generation = generation,
                    actorId = actorId,
                    policy = policy,
                    token = token,
                )
                return@runOnUiThread
            }
            val before = policy.snapshot()
            if (!beginPriorityUserProfileMutationOrFailClosed()) {
                priorityUserTrainingGeneration += 1L
                priorityUserPracticeInFlight = null
                priorityUserPracticeAttemptToken = null
                policy.cancelPractice(token)
                feedbackActuator?.cancelPriorityUserTrainingFeedback()
                updateStatus(
                    "연습 결과 저장 실패",
                    "변경 전 안전 표식을 저장하지 못해 현재 실행에서는 계정과 보행 기능을 열지 않습니다.",
                )
                updatePriorityUserOnboardingUi()
                if (::startupCapabilityProbe.isInitialized) {
                    refreshStartupCapabilityUi()
                }
                return@runOnUiThread
            }
            val after = policy.recordPracticeDelivery(token, signal)
            val persisted = persistPriorityUserOnboardingOrFailClosed()
            if (!persisted) {
                priorityUserTrainingGeneration += 1L
                priorityUserPracticeInFlight = null
                priorityUserPracticeAttemptToken = null
                policy.cancelPractice(token)
                feedbackActuator?.cancelPriorityUserTrainingFeedback()
                updateStatus(
                    "연습 결과 저장 실패",
                    "연습 상태를 안전하게 저장하지 못해 계정과 보행 기능을 열지 않습니다.",
                )
                updatePriorityUserOnboardingUi()
                if (::startupCapabilityProbe.isInitialized) {
                    refreshStartupCapabilityUi()
                }
                return@runOnUiThread
            }
            if (after.completedPractices == before.completedPractices) {
                if (policy.isHazardResponseReady(token)) updatePriorityUserOnboardingUi()
                return@runOnUiThread
            }
            completePriorityUserPracticeStep(after, actorId)
        }
    }

    private fun completePriorityUserPracticeStep(after: PriorityUserOnboardingSnapshot, actorId: String) {
        val completedPractice = priorityUserPracticeInFlight
        priorityUserTrainingGeneration += 1L
        priorityUserPracticeInFlight = null
        priorityUserPracticeAttemptToken = null
        updateStatus(
            "연습 완료",
            "${completedPractice?.actionLabelKo ?: "필수 조작 연습"}을 완료했습니다.",
        )
        updatePriorityUserOnboardingUi()
        if (firstRunOnboardingSnapshot.flow != FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4) {
            if (after.interactivePracticeComplete) completeFirstRunFp004TrainingIfReady(actorId)
        }
        if (::startupCapabilityProbe.isInitialized) refreshStartupCapabilityUi()
    }

    private fun completeFirstRunFp004TrainingIfReady(actorId: String): Boolean {
        if (
            firstRunOnboardingSnapshot.stage !=
            FirstRunOnboardingStage.FP004_TRAINING
        ) return false
        if (firstRunOnboardingSnapshot.verifiedActorBinding?.value != actorId) return false
        if (priorityUserOnboardingActorId != actorId) return false
        if (!postLoginDeviceCheckPassesFeatureGate()) return false
        if (!currentFirstRunEducationEvidenceComplete()) return false
        val receipt = firstRunLocalReceipt(
            if (firstRunOnboardingSnapshot.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4) {
                "safety_and_usage_education_v2"
            } else {
                "fp004_training_complete"
            },
        )
        val started = FirstRunOnboardingPolicy.beginAttempt(
            snapshot = firstRunOnboardingSnapshot,
            request = firstRunLocalRequest("fp004_training_complete"),
        )
        val token = started.current.pendingAttempt ?: return false
        val evidence = FirstRunOnboardingEvidence.Fp004Training(receipt)
        val completed = FirstRunOnboardingPolicy.completeAttempt(
            snapshot = started.current,
            token = token,
            evidence = evidence,
            verifier = FirstRunOnboardingEvidenceVerifier {
                    presentedToken,
                    presentedEvidence,
                ->
                presentedToken === token &&
                    presentedEvidence === evidence &&
                    priorityUserOnboardingActorId == actorId &&
                    currentFirstRunEducationEvidenceComplete() &&
                    postLoginDeviceCheckPassesFeatureGate()
            },
        )
        if (!completed.accepted) return false
        if (completed.current.flow == FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 &&
            !persistNativeCompletedOnboarding(completed.current)) {
            updateStatus("안전교육 완료 저장 실패", "완료 기록을 저장하지 못했습니다. 다시 동의해 저장을 재시도하세요.")
            return false
        }
        val process = GatewaySessionProcessCoordinator.snapshot()
        if (
            !GatewaySessionProcessCoordinator.updateFirstRunSnapshot(
                expectedGeneration = process.generation,
                expectedActorId = actorId,
                firstRunSnapshot = completed.current,
            )
        ) {
            updateStatus(
                "안전교육 완료 저장 실패",
                "로그인 세션이 변경되어 완료 상태를 적용하지 않았습니다. 로그인 상태를 확인한 뒤 다시 시도하세요.",
            )
            return false
        }
        firstRunOnboardingSnapshot = completed.current
        onFirstRunOnboardingStateChanged(
            "안전 교육과 사전 연습을 완료했습니다. 홈으로 이동합니다.",
            preservePostLoginDeviceCheck = true,
        )
        return true
    }

    private fun failPriorityUserTrainingDelivery(
        generation: Long,
        actorId: String,
        policy: PriorityUserOnboardingPolicy,
        token: PriorityUserPracticeAttemptToken?,
        detail: String,
    ) {
        runOnUiThread {
            if (
                !isPriorityUserTrainingDeliveryCurrent(
                    generation = generation,
                    actorId = actorId,
                    policy = policy,
                )
            ) {
                clearPriorityUserTrainingDeliveryIfOwned(
                    generation = generation,
                    actorId = actorId,
                    policy = policy,
                    token = token,
                )
                return@runOnUiThread
            }
            priorityUserTrainingGeneration += 1L
            priorityUserEducationInFlight = false
            priorityUserPracticeInFlight = null
            priorityUserPracticeAttemptToken = null
            policy.cancelPractice(token)
            feedbackActuator?.cancelPriorityUserTrainingFeedback()
            updateStatus("교육·연습 다시 필요", detail)
            updatePriorityUserOnboardingUi()
        }
    }

    private fun requireDeviceCheckForPriorityUserTraining(): Boolean {
        if (postLoginDeviceCheckPassesFeatureGate()) return true
        updateStatus(
            "기기 점검 다시 필요",
            "안전교육과 조작 연습 전에 권한과 기기 기능 점검을 완료하세요.",
        )
        speakInteraction("먼저 권한과 기기 기능 점검을 완료하세요.")
        if (::startupCapabilityProbe.isInitialized) refreshStartupCapabilityUi()
        return false
    }

    private fun clearPriorityUserTrainingDeliveryIfOwned(
        generation: Long,
        actorId: String,
        policy: PriorityUserOnboardingPolicy,
        token: PriorityUserPracticeAttemptToken?,
    ) {
        if (
            generation != priorityUserTrainingGeneration ||
            actorId != priorityUserOnboardingActorId ||
            policy !== priorityUserOnboardingPolicy
        ) return
        priorityUserTrainingGeneration += 1L
        priorityUserEducationInFlight = false
        priorityUserPracticeInFlight = null
        priorityUserPracticeAttemptToken = null
        policy.cancelPractice(token)
        feedbackActuator?.cancelPriorityUserTrainingFeedback()
        updateStatus(
            "교육·연습 중지",
            "로그인 또는 기기 점검 상태가 변경되어 진행 중인 안내를 취소했습니다.",
        )
        updatePriorityUserOnboardingUi()
    }

    private fun isPriorityUserTrainingDeliveryCurrent(
        generation: Long,
        actorId: String,
        policy: PriorityUserOnboardingPolicy,
    ): Boolean =
        isActivityForeground &&
            generation == priorityUserTrainingGeneration &&
            actorId == reporterUserId &&
            actorId == priorityUserOnboardingActorId &&
            policy === priorityUserOnboardingPolicy &&
            firstRunOnboardingSnapshot.stage == FirstRunOnboardingStage.FP004_TRAINING &&
            firstRunOnboardingSnapshot.verifiedActorBinding?.value == actorId &&
            postLoginDeviceCheckPassesFeatureGate()

    private fun cancelPendingPriorityUserTrainingFeedback() {
        stopAccountConsentSpeech()
        priorityUserTrainingGeneration += 1L
        priorityUserEducationInFlight = false
        priorityUserPracticeInFlight = null
        priorityUserPracticeAttemptToken = null
        if (::priorityUserOnboardingPolicy.isInitialized) {
            priorityUserOnboardingPolicy.cancelPractice()
            priorityUserOnboardingPolicy.cancelAppUsageEducationPlayback()
        }
        feedbackActuator?.cancelPriorityUserTrainingFeedback()
        if (::priorityUserOnboardingStatusText.isInitialized) {
            updatePriorityUserOnboardingUi()
        }
    }

    private fun persistPriorityUserOnboardingOrFailClosed(): Boolean {
        if (persistPriorityUserOnboarding()) return true
        priorityUserOnboardingActorId?.let { actorId ->
            priorityUserStorageBlockedActorHashes.add(
                priorityUserActorSha256(actorId),
            )
        }
        priorityUserOnboardingPolicy = PriorityUserOnboardingPolicy()
        return false
    }

    private fun resetPriorityUserTraining() {
        nativeCompletedFirstRunRecord = null
        cancelPendingPriorityUserTrainingFeedback()
        invalidateOfficialEnvironmentEvidence("priority_user_training_reset")
        invalidatePhoneMountingEvidence("priority_user_training_reset")
        val actorId = priorityUserOnboardingActorId
        if (actorId == null || actorId != reporterUserId) {
            speakInteraction("먼저 교육 대상 로그인 ID를 입력하고 확인하세요.")
            return
        }
        val persisted = if (beginPriorityUserProfileMutationOrFailClosed()) {
            priorityUserOnboardingPolicy.resetTraining()
            persistPriorityUserOnboardingOrFailClosed()
        } else {
            false
        }
        if (!persisted) {
            updateStatus(
                "교육 재실행 저장 실패",
                "안전한 재실행 상태를 저장하지 못해 현재 실행에서는 계정과 보행 기능을 열지 않습니다.",
            )
        }
        val firstRunRestart =
            FirstRunOnboardingPolicy.restartFp004Training(
                firstRunOnboardingSnapshot,
            )
        if (firstRunRestart.accepted) {
            firstRunOnboardingSnapshot = firstRunRestart.current
            onFirstRunOnboardingStateChanged(
                "안전교육을 다시 완료해야 합니다. 완료 전까지 보행 기능을 사용하지 않습니다.",
            )
        } else if (isWalkSessionRuntimeActive()) {
            enterWalkSessionSafetyStopAndCancelOutputs(
                "priority_user_training_reset",
            )
            updateStatus(
                "교육 재실행 · 안전 중지",
                "교육과 네 가지 조작 연습을 다시 완료한 뒤 새 보행을 시작하세요.",
            )
        }
        updatePriorityUserOnboardingUi()
        if (!firstRunRestart.accepted) {
            speakInteraction("안전 제한 안내부터 다시 시작합니다.")
        }
        if (::startupCapabilityProbe.isInitialized) refreshStartupCapabilityUi()
    }

    private fun confirmOfficialEnvironmentConditions() {
        if (developmentGuidanceStartBypassEnabled) return
        if (!isActivityForeground || !::walkSessionLifecycle.isInitialized) return
        if (!requireFirstRunOnboardingComplete("official_environment_confirmation")) return
        if (!developmentQuickStartEnabled &&
            (priorityUserOnboardingActorId != reporterUserId ||
                !priorityUserOnboardingPolicy.snapshot().nativeEducationComplete)) return
        if (activeEnvironmentProfiles == null) {
            updateStatus(
                "실제 상태 점검 기준 없음",
                "출시 후보 또는 승인된 환경·장착 측정 프로필이 없어 보행을 시작하지 않습니다.",
            )
            return
        }
        val snapshot = walkSessionLifecycle.snapshot()
        if (
            snapshot.state !in setOf(
                WalkSessionState.READY,
                WalkSessionState.PAUSED,
            )
        ) {
            updateStatus(
                "공식 사용환경 확인 불가",
                "새 보행 준비 또는 일시중지 재검사 상태에서 다시 확인하세요.",
            )
            return
        }
        if (
            officialEnvironmentCameraPreflightActive ||
            officialEnvironmentCameraCleanupPending
        ) {
            stopOfficialEnvironmentCameraPreflight(
                onReleased = ::confirmOfficialEnvironmentConditions,
            )
            return
        }
        resetPrewalkCameraEvidenceForNewAttempt()
        officialEnvironmentGpsEvidence = null
        officialEnvironmentGpsDiagnosticAccuracyMeters = null
        officialEnvironmentGpsDiagnosticDetail = null
        officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.IDLE
        officialEnvironmentReadyGraceGeneration = -1L
        prewalkGuidanceStage = 0
        // Do not convert scope education to current weather, sidewalk or mounting evidence.
        // Preserve any real observed adverse condition; missing current conditions stay UNKNOWN.
        if (developmentQuickStartEnabled && snapshot.state == WalkSessionState.READY &&
            nativePhoneMountingCheckRequest == null) {
            // Only the initial manual mounting choice is assumed; camera/GPS evidence stays real.
            phoneMountingUserConfirmation = PhoneMountingUserConfirmation(
                epoch = snapshot.epoch,
                confirmedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                method = PhoneMountingMethod.CHEST_FORWARD,
                postFaultCorrectionConfirmed = false,
            )
        }
        val requireLocation = postLoginDeviceFeatureEnabled(
            PostLoginDeviceCheckFeature.LOCATION_GUIDANCE,
        )
        val requireCamera = cameraAnalysisFeaturesEnabled()
        val decision = startupCapabilityDecision
        if (requireLocation && !hasLocationPermission()) {
            if (decision != null) maybeRequestMissingWalkSessionPermissions(decision)
            updateStatus(
                "정확한 위치 권한 필요",
                "환경 위치 품질을 확인하려면 정확한 위치 권한을 허용한 뒤 공식 사용환경을 다시 확인하세요.",
            )
        } else if (requireLocation && !isLocationServiceEnabledForDeviceCheck()) {
            officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.FAILED
            updateStatus(
                "Android 위치 서비스 필요",
                "위치 서비스를 켠 뒤 실제 상태 점검을 다시 실행하세요.",
            )
        } else if (requireCamera) {
            if (startOfficialEnvironmentCameraPreflight(snapshot.epoch) && requireLocation) {
                requestOfficialEnvironmentGpsPreflight(snapshot.epoch)
            }
        } else if (requireLocation) {
            requestOfficialEnvironmentGpsPreflight(snapshot.epoch)
        }
        updateOfficialEnvironmentUi()
        refreshStartupCapabilityUi()
        if (nativePhoneMountingCheckRequest != null) {
            speakInteraction("안내를 준비합니다. 휴대전화를 앞을 향하게 유지해 주세요. 실제 센서 점검 후 자동으로 안내를 시작합니다.")
        } else {
            speakInteraction(
                "$OFFICIAL_ENVIRONMENT_SUPPORT_NOTICE_KO " +
                    "사용범위 교육은 현재 환경의 안전을 증명하지 않습니다. 활성화된 기능의 실제 센서 품질과 장착 상태를 점검합니다.",
            )
        }
    }

    @androidx.annotation.OptIn(markerClass = [ExperimentalGetImage::class])
    private fun startOfficialEnvironmentCameraPreflight(epoch: WalkRuntimeEpoch): Boolean {
        if (
            officialEnvironmentCameraPreflightActive ||
            officialEnvironmentCameraCleanupPending ||
            !isActivityForeground ||
            walkSessionLifecycle.snapshot().epoch != epoch ||
            walkSessionLifecycle.snapshot().state !in
            setOf(WalkSessionState.READY, WalkSessionState.PAUSED) ||
            activeCameraFrameQualityProfile == null
        ) return false
        val startFailure = when {
            !hasCameraPermission() -> "CAMERA_PERMISSION_MISSING"
            cameraXReleaseBlocked -> "PREVIOUS_CAMERA_RELEASE_TIMED_OUT"
            postLoginCameraPipelinePreflightActive -> "POST_LOGIN_CAMERA_CHECK_ACTIVE"
            postLoginCameraPipelineCleanupPending ->
                "POST_LOGIN_CAMERA_CHECK_CLEANUP_PENDING"
            postLoginMetricPreflightStarted || metricPreflightPostLoginBinding != null ->
                "POST_LOGIN_METRIC_CHECK_ACTIVE"
            arSessionPurpose != ArSessionPurpose.NONE || session != null ->
                "AR_CAMERA_PIPELINE_BUSY"
            cameraFallbackCleanupPending -> "CAMERA_PIPELINE_CLEANUP_PENDING"
            cameraFallbackRequested -> "CAMERA_PIPELINE_BUSY"
            !phoneMountingSensorProbe.start() -> "MOUNTING_SENSOR_UNAVAILABLE"
            else -> null
        }
        if (startFailure != null) {
            officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.FAILED
            officialEnvironmentCameraDiagnosticReason = startFailure
            observeOfficialEnvironmentCameraFrame(
                epoch = epoch,
                observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                frameAvailable = null,
            )
            updateStatus(
                "카메라·장착 센서 점검 불가",
                "카메라 권한과 자이로·중력 센서를 확인한 뒤 실제 상태 점검을 다시 실행하세요.",
            )
            if (BuildConfig.DEBUG) {
                android.util.Log.d(
                    CAMERA_PREFLIGHT_LOG_TAG,
                    "status=UNAVAILABLE reason=$startFailure",
                )
            }
            return false
        }

        val generation = ++officialEnvironmentCameraPreflightGeneration
        officialEnvironmentCameraPreflightActive = true
        officialEnvironmentCameraPreflightLastAnalysisMs = 0L
        officialEnvironmentCameraStabilityGate.reset()
        officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.MEASURING
        cameraFallbackLifecycleOwner.moveTo(Lifecycle.State.RESUMED)
        scheduleOfficialEnvironmentPreflightTimeout(
            epoch = epoch,
            generation = generation,
            delayMs = OFFICIAL_ENVIRONMENT_CAMERA_PREFLIGHT_MAX_DURATION_MS,
        )
        val providerFuture = ProcessCameraProvider.getInstance(this)
        providerFuture.addListener(
            {
                if (!isOfficialEnvironmentCameraPreflightCurrent(epoch, generation)) {
                    return@addListener
                }
                try {
                    val provider = providerFuture.get()
                    val resolutionSelector = ResolutionSelector.Builder()
                        .setResolutionStrategy(
                            ResolutionStrategy(
                                Size(CAMERA_FALLBACK_WIDTH, CAMERA_FALLBACK_HEIGHT),
                                ResolutionStrategy.FALLBACK_RULE_CLOSEST_LOWER_THEN_HIGHER,
                            ),
                        )
                        .build()
                    val analysis = ImageAnalysis.Builder()
                        .setResolutionSelector(resolutionSelector)
                        .setTargetRotation(displayRotation())
                        .setOutputImageFormat(ImageAnalysis.OUTPUT_IMAGE_FORMAT_YUV_420_888)
                        .setOutputImageRotationEnabled(true)
                        .setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST)
                        .build()
                    analysis.setAnalyzer(detectorExecutor) { imageProxy ->
                        try {
                            val nowMs = SystemClock.elapsedRealtime()
                            if (!isOfficialEnvironmentCameraPreflightCurrent(epoch, generation)) {
                                return@setAnalyzer
                            }
                            if (
                                nowMs - officialEnvironmentCameraPreflightLastAnalysisMs <
                                OFFICIAL_ENVIRONMENT_CAMERA_PREFLIGHT_INTERVAL_MS
                            ) return@setAnalyzer
                            officialEnvironmentCameraPreflightLastAnalysisMs = nowMs
                            val plane = imageProxy.planes.firstOrNull()
                            val observation = cameraFrameQualityObservation(
                                epoch = epoch,
                                // Sensor samples are read at analysis time. CameraX capture
                                // timestamps are not guaranteed to be comparable across devices.
                                observedAtElapsedRealtimeMs = nowMs,
                                frameAvailable = imageProxy.image != null,
                                width = imageProxy.width,
                                height = imageProxy.height,
                                yPlaneBuffer = plane?.buffer,
                                yPlaneRowStride = plane?.rowStride,
                                yPlanePixelStride = plane?.pixelStride,
                            )
                            observeOfficialEnvironmentCameraFrame(
                                observation = observation,
                                expectedCameraPreflightGeneration = generation,
                            )
                        } finally {
                            imageProxy.close()
                        }
                    }
                    cameraFallbackProvider = provider
                    cameraFallbackAnalysis = analysis
                    cameraFallbackCamera = provider.bindToLifecycle(
                        cameraFallbackLifecycleOwner,
                        CameraSelector.DEFAULT_BACK_CAMERA,
                        analysis,
                    )
                } catch (_: Exception) {
                    if (!isOfficialEnvironmentCameraPreflightCurrent(epoch, generation)) {
                        return@addListener
                    }
                    stopOfficialEnvironmentCameraPreflight()
                    officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.FAILED
                    observeOfficialEnvironmentCameraFrame(
                        epoch = epoch,
                        observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                        frameAvailable = false,
                    )
                    officialEnvironmentCameraDiagnosticReason = "CAMERA_BIND_FAILED"
                    updateStatus(
                        "보행 전 카메라 점검 실패",
                        "카메라를 다른 앱이 사용 중인지 확인한 뒤 다시 점검하세요.",
                    )
                    updateOfficialEnvironmentUi()
                    refreshStartupCapabilityUi()
                }
            },
            ContextCompat.getMainExecutor(this),
        )
        return true
    }

    private fun scheduleOfficialEnvironmentPreflightTimeout(
        epoch: WalkRuntimeEpoch,
        generation: Long,
        delayMs: Long,
    ) {
        officialEnvironmentCameraPreflightTimeout?.let {
            officialEnvironmentStatusText.removeCallbacks(it)
        }
        lateinit var timeout: Runnable
        timeout = Runnable {
            if (
                officialEnvironmentCameraPreflightTimeout !== timeout ||
                !isOfficialEnvironmentCameraPreflightCurrent(epoch, generation)
            ) return@Runnable
            stopOfficialEnvironmentCameraPreflight()
            synchronized(phoneMountingObservationLock) {
                officialEnvironmentGpsEvidence = null
                officialEnvironmentCameraEvidence = null
            }
            officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.TIMED_OUT
            updateOfficialEnvironmentUi()
            refreshStartupCapabilityUi()
            updateStatus(
                "보행 전 상태 점검 시간 초과",
                "마지막 실제 측정 원인은 화면에 유지했습니다. 환경과 장착을 확인한 뒤 다시 점검하세요.",
            )
        }
        officialEnvironmentCameraPreflightTimeout = timeout
        officialEnvironmentStatusText.postDelayed(timeout, delayMs)
    }

    private fun isOfficialEnvironmentCameraPreflightCurrent(
        epoch: WalkRuntimeEpoch,
        generation: Long,
    ): Boolean =
        officialEnvironmentCameraPreflightActive &&
            generation == officialEnvironmentCameraPreflightGeneration &&
            isActivityForeground &&
            walkSessionLifecycle.snapshot().epoch == epoch &&
            walkSessionLifecycle.snapshot().state in
            setOf(WalkSessionState.READY, WalkSessionState.PAUSED)

    private fun stopOfficialEnvironmentCameraPreflight(
        releaseMountingSensor: Boolean = true,
        onReleased: (() -> Unit)? = null,
    ) {
        if (onReleased != null) {
            officialEnvironmentAfterCameraRelease = onReleased
        }
        var stopped = false
        synchronized(phoneMountingObservationLock) {
            if (officialEnvironmentCameraPreflightActive) {
                officialEnvironmentCameraPreflightActive = false
                officialEnvironmentCameraPreflightGeneration += 1L
                stopped = true
            }
        }
        if (releaseMountingSensor && ::phoneMountingSensorProbe.isInitialized) {
            phoneMountingSensorProbe.stop()
        }
        if (!stopped) {
            stopOfficialEnvironmentGpsPreflight()
            if (!officialEnvironmentCameraCleanupPending) {
                val afterRelease = officialEnvironmentAfterCameraRelease
                officialEnvironmentAfterCameraRelease = null
                afterRelease?.invoke()
            }
            return
        }
        if (::officialEnvironmentStatusText.isInitialized) {
            officialEnvironmentCameraPreflightTimeout?.let {
                officialEnvironmentStatusText.removeCallbacks(it)
            }
        }
        officialEnvironmentCameraPreflightTimeout = null
        val ownedProvider = cameraFallbackProvider
        val ownedCamera = cameraFallbackCamera
        val ownedAnalysis = cameraFallbackAnalysis
        val ownedPreview = cameraFallbackPreview
        cameraFallbackAnalysis = null
        cameraFallbackPreview = null
        cameraFallbackProvider = null
        cameraFallbackCamera = null
        ownedAnalysis?.clearAnalyzer()
        stopOfficialEnvironmentGpsPreflight()
        val releaseClaim = AtomicBoolean(false)
        val analyzerBarrierTimedOut = AtomicBoolean(false)
        lateinit var release: Runnable
        lateinit var releaseDeadline: Runnable
        release = Runnable {
            if (!releaseClaim.compareAndSet(false, true)) return@Runnable
            cameraReleaseHandler.removeCallbacks(releaseDeadline)
            if (ownedAnalysis != null) {
                runCatching { ownedProvider?.unbind(ownedAnalysis) }
            }
            if (ownedPreview != null) {
                runCatching { ownedProvider?.unbind(ownedPreview) }
            }
            if (::cameraFallbackLifecycleOwner.isInitialized) {
                cameraFallbackLifecycleOwner.moveTo(Lifecycle.State.CREATED)
            }
            awaitCameraXClosed(ownedCamera) { closed ->
                officialEnvironmentCameraCleanupPending = false
                val afterRelease = officialEnvironmentAfterCameraRelease
                officialEnvironmentAfterCameraRelease = null
                val releasedSafely = closed && !analyzerBarrierTimedOut.get()
                if (releasedSafely) {
                    afterRelease?.invoke()
                } else {
                    cameraXReleaseBlocked = true
                    cancelRuntimeCameraHandoff()
                    officialEnvironmentPreflightPhase =
                        OfficialEnvironmentPreflightPhase.FAILED
                    officialEnvironmentCameraDiagnosticReason =
                        "CAMERA_RELEASE_TIMED_OUT"
                    if (isWalkSessionRuntimeActive()) {
                        enterWalkSessionSafetyStopAndCancelOutputs(
                            "camera_release_timed_out",
                        )
                    } else if (!isFinishing && !isDestroyed) {
                        updateOfficialEnvironmentUi()
                        refreshStartupCapabilityUi()
                        updateStatus(
                            "카메라 정리 실패",
                            "카메라 자원이 닫히지 않아 다음 단계를 시작하지 않았습니다. 앱을 다시 시작한 뒤 점검하세요.",
                        )
                    }
                }
            }
        }
        releaseDeadline = Runnable {
            analyzerBarrierTimedOut.set(true)
            release.run()
        }
        if (ownedAnalysis == null && ownedCamera == null) {
            release.run()
            return
        }
        officialEnvironmentCameraCleanupPending = true
        cameraReleaseHandler.postDelayed(
            releaseDeadline,
            CAMERA_ANALYZER_RELEASE_BARRIER_TIMEOUT_MS,
        )
        try {
            detectorExecutor.execute {
                runOnUiThread(release)
            }
        } catch (_: RejectedExecutionException) {
            analyzerBarrierTimedOut.set(true)
            runOnUiThread(release)
        }
    }

    @SuppressLint("MissingPermission")
    private fun requestOfficialEnvironmentGpsPreflight(
        epoch: WalkRuntimeEpoch,
        clearExistingEvidence: Boolean = true,
    ) {
        stopOfficialEnvironmentGpsPreflight()
        if (clearExistingEvidence) {
            officialEnvironmentGpsEvidence = null
            officialEnvironmentGpsDiagnosticAccuracyMeters = null
            officialEnvironmentGpsDiagnosticDetail = null
        }
        val generation = ++officialEnvironmentPreflightGeneration
        val cameraRequired = cameraAnalysisFeaturesEnabled()
        if (
            !isActivityForeground ||
            !hasLocationPermission() ||
            !isLocationServiceEnabledForDeviceCheck() ||
            (cameraRequired && !officialEnvironmentCameraPreflightActive) ||
            walkSessionLifecycle.snapshot().epoch != epoch ||
            walkSessionLifecycle.snapshot().state !in setOf(
                WalkSessionState.READY,
                WalkSessionState.PAUSED,
            )
        ) {
            return
        }
        lateinit var callback: LocationCallback
        callback = object : LocationCallback() {
            override fun onLocationResult(result: LocationResult) {
                if (!isOfficialEnvironmentGpsPreflightCurrent(epoch, generation, callback)) return
                result.locations
                    .sortedBy(Location::getElapsedRealtimeNanos)
                    .forEach { location ->
                        if (isOfficialEnvironmentGpsPreflightCurrent(epoch, generation, callback)) {
                            observeOfficialEnvironmentGpsLocation(epoch, location)
                        }
                    }
            }

            override fun onLocationAvailability(availability: LocationAvailability) {
                if (
                    BuildConfig.DEBUG &&
                    isOfficialEnvironmentGpsPreflightCurrent(epoch, generation, callback) &&
                    !availability.isLocationAvailable
                ) {
                    android.util.Log.d(
                        GPS_PREFLIGHT_LOG_TAG,
                        "generation=$generation status=WAITING reason=LOCATION_TEMPORARILY_UNAVAILABLE",
                    )
                }
            }
        }
        officialEnvironmentGpsCallback = callback
        if (!cameraRequired) {
            officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.MEASURING
            scheduleOfficialEnvironmentGpsOnlyPreflightTimeout(
                epoch = epoch,
                generation = generation,
                callback = callback,
            )
        }
        val request = LocationRequest.Builder(
            Priority.PRIORITY_HIGH_ACCURACY,
            OFFICIAL_ENVIRONMENT_GPS_INTERVAL_MS,
        )
            .setGranularity(Granularity.GRANULARITY_FINE)
            .setMaxUpdateAgeMillis(0L)
            .setMinUpdateIntervalMillis(OFFICIAL_ENVIRONMENT_GPS_MIN_INTERVAL_MS)
            .setWaitForAccurateLocation(true)
            .setDurationMillis(OFFICIAL_ENVIRONMENT_GPS_REQUEST_MAX_DURATION_MS)
            .build()
        val registration = runCatching {
            fusedLocationClient.requestLocationUpdates(
                request,
                callback,
                Looper.getMainLooper(),
            )
        }.getOrElse {
            failOfficialEnvironmentGpsPreflight(epoch, generation, callback)
            return
        }
        registration
            .addOnSuccessListener(ContextCompat.getMainExecutor(this)) {
                if (!isOfficialEnvironmentGpsPreflightCurrent(epoch, generation, callback)) {
                    fusedLocationClient.removeLocationUpdates(callback)
                }
            }
            .addOnFailureListener(ContextCompat.getMainExecutor(this)) {
                failOfficialEnvironmentGpsPreflight(epoch, generation, callback)
            }
    }

    private fun failOfficialEnvironmentGpsPreflight(
        epoch: WalkRuntimeEpoch,
        generation: Long,
        callback: LocationCallback,
    ) {
        if (!isOfficialEnvironmentGpsPreflightCurrent(epoch, generation, callback)) {
            if (::fusedLocationClient.isInitialized) {
                fusedLocationClient.removeLocationUpdates(callback)
            }
            return
        }
        officialEnvironmentGpsDiagnosticDetail = "LOCATION_REQUEST_FAILED"
        officialEnvironmentGpsEvidence = OfficialEnvironmentPolicy.assessGpsQuality(
            currentEpoch = epoch,
            nowElapsedRealtimeMs = SystemClock.elapsedRealtime(),
            observation = null,
            approvedProfile = activeOfficialEnvironmentProfile,
        )
        stopOfficialEnvironmentCameraPreflight()
        officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.FAILED
        updateOfficialEnvironmentUi()
        refreshStartupCapabilityUi()
        updateStatus(
            "위치 점검 실패",
            "Android 위치 서비스를 확인한 뒤 실제 상태 점검을 다시 실행하세요.",
        )
    }

    private fun scheduleOfficialEnvironmentGpsOnlyPreflightTimeout(
        epoch: WalkRuntimeEpoch,
        generation: Long,
        callback: LocationCallback,
    ) {
        officialEnvironmentCameraPreflightTimeout?.let {
            officialEnvironmentStatusText.removeCallbacks(it)
        }
        lateinit var timeout: Runnable
        timeout = Runnable {
            if (officialEnvironmentCameraPreflightTimeout !== timeout) return@Runnable
            officialEnvironmentCameraPreflightTimeout = null
            if (!isOfficialEnvironmentGpsPreflightCurrent(epoch, generation, callback)) {
                return@Runnable
            }
            stopOfficialEnvironmentGpsPreflight()
            officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.TIMED_OUT
            updateOfficialEnvironmentUi()
            refreshStartupCapabilityUi()
            updateStatus(
                "보행 전 위치 점검 시간 초과",
                "현재 위치 품질을 확인하지 못했습니다. 위치 서비스와 주변 환경을 확인한 뒤 다시 점검하세요.",
            )
        }
        officialEnvironmentCameraPreflightTimeout = timeout
        officialEnvironmentStatusText.postDelayed(
            timeout,
            OFFICIAL_ENVIRONMENT_GPS_REQUEST_MAX_DURATION_MS,
        )
    }

    private fun observeOfficialEnvironmentGpsLocation(
        epoch: WalkRuntimeEpoch,
        location: Location,
    ) {
        val nowMs = SystemClock.elapsedRealtime()
        val observedAtMs = location.elapsedRealtimeNanos / NANOS_PER_MILLISECOND
        val accuracyMeters = location.accuracy.takeIf { location.hasAccuracy() }?.toDouble()
        val candidate = OfficialEnvironmentGpsPreflightPolicy.assess(
            currentEpoch = epoch,
            nowElapsedRealtimeMs = nowMs,
            sample = OfficialEnvironmentGpsSample(
                observedAtElapsedRealtimeMs = observedAtMs,
                latitude = location.latitude,
                longitude = location.longitude,
                horizontalAccuracyMeters = accuracyMeters,
                mock = isMockLocationCompat(location),
            ),
            approvedProfile = activeOfficialEnvironmentProfile,
        )
        val previous = officialEnvironmentGpsEvidence
        val selected = OfficialEnvironmentGpsPreflightPolicy.selectEvidence(
            previous = previous,
            candidate = candidate,
            nowElapsedRealtimeMs = nowMs,
        )
        officialEnvironmentGpsEvidence = selected
        if (selected === candidate) {
            officialEnvironmentGpsDiagnosticAccuracyMeters = accuracyMeters
            officialEnvironmentGpsDiagnosticDetail = selected.detail
        }
        if (BuildConfig.DEBUG) {
            android.util.Log.d(
                GPS_PREFLIGHT_LOG_TAG,
                "accuracyMeters=$accuracyMeters " +
                    "maximumAccuracyMeters=" +
                    "${activeOfficialEnvironmentProfile?.maximumGpsHorizontalAccuracyMeters} " +
                    "ageMs=${nowMs - observedAtMs} mock=${isMockLocationCompat(location)} " +
                    "status=${candidate.status} reason=${candidate.detail} " +
                    "retainedRecentPass=" +
                    "${officialEnvironmentGpsEvidence !== candidate}",
            )
        }
        if (
            selected.status == EnvironmentEvidenceStatus.PASS &&
            !cameraAnalysisFeaturesEnabled()
        ) {
            officialEnvironmentCameraPreflightTimeout?.let {
                officialEnvironmentStatusText.removeCallbacks(it)
            }
            officialEnvironmentCameraPreflightTimeout = null
            stopOfficialEnvironmentGpsPreflight()
            officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.IDLE
        }
        updateOfficialEnvironmentUi()
        refreshStartupCapabilityUi()
    }

    private fun stopOfficialEnvironmentGpsPreflight() {
        officialEnvironmentPreflightGeneration += 1L
        val callback = officialEnvironmentGpsCallback
        officialEnvironmentGpsCallback = null
        if (::fusedLocationClient.isInitialized) {
            callback?.let(fusedLocationClient::removeLocationUpdates)
        }
    }

    @Suppress("DEPRECATION")
    private fun isMockLocationCompat(location: Location): Boolean {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            location.isMock
        } else {
            location.isFromMockProvider
        }
    }

    private fun isOfficialEnvironmentGpsPreflightCurrent(
        epoch: WalkRuntimeEpoch,
        generation: Long,
        callback: LocationCallback,
    ): Boolean {
        val snapshot = walkSessionLifecycle.snapshot()
        return officialEnvironmentGpsCallback === callback &&
            generation == officialEnvironmentPreflightGeneration &&
            (
                officialEnvironmentCameraPreflightActive ||
                    !cameraAnalysisFeaturesEnabled()
            ) &&
            snapshot.epoch == epoch &&
            snapshot.isForeground &&
            snapshot.state in setOf(WalkSessionState.READY, WalkSessionState.PAUSED) &&
            isActivityForeground
    }

    private fun currentOfficialEnvironmentAssessment(
        epoch: WalkRuntimeEpoch = walkSessionLifecycle.snapshot().epoch,
        nowElapsedRealtimeMs: Long = SystemClock.elapsedRealtime(),
    ): OfficialEnvironmentAssessment {
        if (walkSessionLifecycle.isRuntimeEpochCurrent(epoch)) {
            runtimeGpsQualityGate.current(nowElapsedRealtimeMs)?.let {
                officialEnvironmentGpsEvidence = it
            }
            synchronized(phoneMountingObservationLock) {
                runtimeCameraQualityGate.current(nowElapsedRealtimeMs)?.let { evidence ->
                    officialEnvironmentCameraEvidence = evidence
                    latestRuntimeRawCameraAssessment?.takeIf {
                        it.epoch == evidence.epoch &&
                            it.observedAtElapsedRealtimeMs == evidence.observedAtElapsedRealtimeMs &&
                            it.status == evidence.status
                    }?.let { latestPhoneMountingCameraAssessment = it }
                }
            }
        }
        val assessed = OfficialEnvironmentPolicy.assess(
            currentEpoch = epoch,
            nowElapsedRealtimeMs = nowElapsedRealtimeMs,
            gpsQuality = officialEnvironmentGpsEvidence,
            cameraQuality = officialEnvironmentCameraEvidence,
            userConfirmation = officialEnvironmentUserConfirmation,
            approvedProfile = activeOfficialEnvironmentProfile,
            usageLimitsAcknowledged = ::priorityUserOnboardingPolicy.isInitialized &&
                reporterUserId != null && priorityUserOnboardingActorId == reporterUserId &&
                priorityUserOnboardingPolicy.snapshot().nativeEducationComplete,
        )
        val enabledMeasuredFactors = buildSet {
            if (postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE)) {
                add(OfficialEnvironmentFactor.GPS_QUALITY)
            }
            if (cameraAnalysisFeaturesEnabled()) {
                add(OfficialEnvironmentFactor.CAMERA_QUALITY)
            }
        }
        val runtimeUnavailableMeasuredFactors = synchronized(phoneMountingObservationLock) {
            if (OfficialEnvironmentFactor.CAMERA_QUALITY in enabledMeasuredFactors &&
                walkSessionLifecycle.isRuntimeEpochCurrent(epoch) &&
                phoneMountingRuntimeState?.epoch == epoch && !phoneMountingOutputsAllowed
            ) {
                setOf(OfficialEnvironmentFactor.CAMERA_QUALITY)
            } else {
                emptySet()
            }
        }
        return assessed.copy(
            enabledMeasuredFactors = enabledMeasuredFactors,
            runtimeUnavailableMeasuredFactors = runtimeUnavailableMeasuredFactors,
        )
    }

    private fun officialEnvironmentReadiness(
        epoch: WalkRuntimeEpoch,
    ): Pair<WalkSessionReadinessStatus, String> {
        if (developmentGuidanceStartBypassEnabled) return WalkSessionReadinessStatus.READY to ""
        val snapshot = walkSessionLifecycle.snapshot()
        val runtimeGuard = officialEnvironmentRuntimeGuard
        if (
            snapshot.state == WalkSessionState.ACTIVE &&
            runtimeGuard != null &&
            runtimeGuard.epoch == epoch &&
            walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
        ) {
            return when (runtimeGuard.decision().action) {
                OfficialEnvironmentRuntimeAction.CONTINUE,
                OfficialEnvironmentRuntimeAction.SUPPRESS_OUTPUTS_AND_RETRY,
                -> WalkSessionReadinessStatus.READY to ""
                OfficialEnvironmentRuntimeAction.SAFE_STOP ->
                    WalkSessionReadinessStatus.UNAVAILABLE to
                        "official_environment:runtime_retry_exhausted"
            }
        }
        val assessment = currentOfficialEnvironmentAssessment(epoch)
        if (activeOfficialEnvironmentProfile == null) {
            return WalkSessionReadinessStatus.UNAVAILABLE to
                "official_environment:approved_profile_unavailable"
        }
        if (assessment.canStartWalk) return WalkSessionReadinessStatus.READY to ""
        return when (assessment.support) {
            OfficialEnvironmentSupport.SUPPORTED ->
                WalkSessionReadinessStatus.READY to ""
            OfficialEnvironmentSupport.LIMITED ->
                WalkSessionReadinessStatus.PENDING to
                    "official_environment:unknown:" +
                    assessment.blockingFactors.joinToString(",") { it.name.lowercase(Locale.US) }
            OfficialEnvironmentSupport.UNSUPPORTED ->
                WalkSessionReadinessStatus.UNAVAILABLE to
                    "official_environment:unsupported:" +
                    assessment.blockingFactors.joinToString(",") { it.name.lowercase(Locale.US) }
        }
    }

    private fun officialEnvironmentBlockReason(
        epoch: WalkRuntimeEpoch = walkSessionLifecycle.snapshot().epoch,
    ): String? {
        val (status, _) = officialEnvironmentReadiness(epoch)
        if (status == WalkSessionReadinessStatus.READY) return null
        return officialEnvironmentStatusMessage(currentOfficialEnvironmentAssessment(epoch))
    }

    private fun updateOfficialEnvironmentUi() {
        if (
            !::officialEnvironmentStatusText.isInitialized ||
            !::officialEnvironmentConfirmButton.isInitialized ||
            !::walkSessionLifecycle.isInitialized
        ) return
        val snapshot = walkSessionLifecycle.snapshot()
        val assessment = currentOfficialEnvironmentAssessment(snapshot.epoch)
        val message = officialEnvironmentStatusMessage(assessment)
        if (officialEnvironmentStatusText.text.toString() != message) {
            applyWsStatusText(officialEnvironmentStatusText, message)
            officialEnvironmentStatusText.contentDescription = message
        }
        officialEnvironmentConfirmButton.apply {
            isEnabled =
                activeOfficialEnvironmentProfile != null &&
                firstRunOnboardingComplete() &&
                isActivityForeground &&
                    snapshot.state in setOf(WalkSessionState.READY, WalkSessionState.PAUSED) &&
                    !officialEnvironmentCameraPreflightActive &&
                    !officialEnvironmentCameraCleanupPending
            text = when {
                activeOfficialEnvironmentProfile == null ->
                    "승인된 환경 프로필 없음"
                officialEnvironmentCameraPreflightActive &&
                    assessment.canStartWalk ->
                    if (assessment.conditionallyAllowed) "센서 품질 통과 · 현재 환경은 미확인"
                    else "환경 측정 통과 · 장착 확인 또는 계속 버튼 사용"
                officialEnvironmentCameraPreflightActive ->
                    "위치·카메라 자동 점검 중"
                officialEnvironmentCameraCleanupPending ->
                    "이전 카메라 점검 정리 중"
                officialEnvironmentPreflightPhase == OfficialEnvironmentPreflightPhase.TIMED_OUT ->
                    "환경과 장착 다시 점검"
                officialEnvironmentUserConfirmation?.epoch == snapshot.epoch ->
                    "환경 조건 다시 확인"
                activeEnvironmentProfiles?.approvedForProduction == false ->
                    "출시 후보 환경 실제 점검"
                else -> OFFICIAL_ENVIRONMENT_CONFIRM_ACTION_KO
            }
            contentDescription = text
        }
    }

    private fun updatePrewalkGuidance(
        epoch: WalkRuntimeEpoch,
        officialEnvironmentReady: Boolean,
        phoneMountingReady: Boolean,
    ) {
        if (nativePrewalkStartEpoch != null) {
            continueNativePrewalkIfReady()
        }
        if (
            !officialEnvironmentCameraPreflightActive ||
            walkSessionLifecycle.snapshot().state !in
            setOf(WalkSessionState.READY, WalkSessionState.PAUSED)
        ) {
            prewalkGuidanceStage = 0
            return
        }
        if (
            officialEnvironmentReady &&
            phoneMountingReady &&
            officialEnvironmentCameraPreflightActive &&
            officialEnvironmentReadyGraceGeneration !=
            officialEnvironmentCameraPreflightGeneration
        ) {
            officialEnvironmentReadyGraceGeneration =
                officialEnvironmentCameraPreflightGeneration
            scheduleOfficialEnvironmentPreflightTimeout(
                epoch = epoch,
                generation = officialEnvironmentCameraPreflightGeneration,
                delayMs = OFFICIAL_ENVIRONMENT_READY_GRACE_MS,
            )
        }
        val nextStage = when {
            officialEnvironmentReady && phoneMountingReady -> 2
            officialEnvironmentReady -> 1
            else -> 0
        }
        if (nextStage == 0 || nextStage <= prewalkGuidanceStage) return
        val target = when (nextStage) {
            1 -> phoneMountingChestConfirmButton
            2 -> startupCapabilityConfirmButton
            else -> error("unreachable pre-walk guidance stage")
        }
        if (!target.isShown || !target.isEnabled) return
        prewalkGuidanceStage = nextStage
        target.contentDescription = when (nextStage) {
            1 -> "환경 측정 통과. 휴대전화를 정면으로 고정한 뒤 확인하세요."
            else -> "환경과 장착 점검 통과. 보행 시작 확인"
        }
        target.post {
            if (
                prewalkGuidanceStage != nextStage ||
                !target.isShown ||
                !target.isEnabled ||
                walkSessionLifecycle.snapshot().epoch != epoch
            ) return@post
            target.requestRectangleOnScreen(Rect(0, 0, target.width, target.height), true)
            target.performAccessibilityAction(
                android.view.accessibility.AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS,
                null,
            )
        }
    }

    private fun officialEnvironmentStatusMessage(
        assessment: OfficialEnvironmentAssessment,
    ): String {
        if (developmentGuidanceStartBypassEnabled) return "안내 시작 전 환경 점검을 생략합니다."
        if (activeOfficialEnvironmentProfile == null) {
            return "$OFFICIAL_ENVIRONMENT_SUPPORT_NOTICE_KO\n사용 불가\n" +
                "원인: 실제 기기·현장시험으로 승인된 카메라·환경 품질 프로필이 없습니다.\n" +
                "다음 행동: 승인 기록이 생길 때까지 WalkSafe 보행 안내를 시작하지 마세요."
        }
        val candidateNotice = if (
            activeEnvironmentProfiles?.approvedForProduction == false
        ) {
            "출시 전 시험 기준입니다. 정식 지원 승인 결과가 아닙니다.\n"
        } else {
            ""
        }
        val supportedLabel = if (candidateNotice.isNotEmpty()) "시험 기준 통과" else "지원"
        val blocking = assessment.blockingFactors.joinToString(", ") { it.labelKo() }
        val measurement = officialEnvironmentMeasurementDetail(assessment)
        val locationQualityEnabled =
            postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE)
        val cameraQualityEnabled = cameraAnalysisFeaturesEnabled()
        val skippedQualityNotice = when {
            !locationQualityEnabled && !cameraQualityEnabled ->
                "기기 제한: 위치·카메라 품질 점검은 생략했습니다.\n"
            !locationQualityEnabled -> "기기 제한: 위치 품질 점검은 생략했습니다.\n"
            !cameraQualityEnabled -> "기기 제한: 카메라 품질 점검은 생략했습니다.\n"
            else -> ""
        }
        if (assessment.conditionallyAllowed) {
            return candidateNotice + "$OFFICIAL_ENVIRONMENT_SUPPORT_NOTICE_KO\n제한 상태에서 조건부 사용\n" +
                "활성화된 센서 품질은 기준을 충족했습니다. 날씨와 보도 등 현재 조건은 미확인입니다.\n" +
                "사용범위를 이해한 기록은 현장 안전의 증명이 아닙니다. 불확실하거나 범위를 벗어나면 멈추세요.\n" +
                skippedQualityNotice + measurement + "장착 미확인 시 아래에서 실제 장착 방식을 확인하세요."
        }
        val supportedReason = when {
            locationQualityEnabled && cameraQualityEnabled ->
                "밝고 건조하며 짙은 안개가 없는 일반 도심 보도와 위치·카메라 품질을 확인했습니다."
            locationQualityEnabled ->
                "밝고 건조하며 짙은 안개가 없는 일반 도심 보도와 위치 품질을 확인했습니다. " +
                    "제한된 카메라 품질 점검은 생략했습니다."
            cameraQualityEnabled ->
                "밝고 건조하며 짙은 안개가 없는 일반 도심 보도와 카메라 품질을 확인했습니다. " +
                    "제한된 위치 품질 점검은 생략했습니다."
            else ->
                "밝고 건조하며 짙은 안개가 없는 일반 도심 보도를 확인했습니다. " +
                    "제한된 위치·카메라 품질 점검은 생략했습니다."
        }
        return candidateNotice + when (assessment.support) {
            OfficialEnvironmentSupport.SUPPORTED ->
                "$OFFICIAL_ENVIRONMENT_SUPPORT_NOTICE_KO\n$supportedLabel\n" +
                    "원인: $supportedReason\n" +
                    measurement +
                    "다음 행동: 장착 방식을 아직 선택하지 않았다면 아래에서 선택하고, " +
                    "완료했다면 보행 시작 확인 버튼을 누르세요."
            OfficialEnvironmentSupport.LIMITED ->
                "$OFFICIAL_ENVIRONMENT_SUPPORT_NOTICE_KO\n" +
                    when (officialEnvironmentPreflightPhase) {
                        OfficialEnvironmentPreflightPhase.MEASURING -> "측정 중\n"
                        OfficialEnvironmentPreflightPhase.TIMED_OUT -> "점검 시간 초과\n"
                        OfficialEnvironmentPreflightPhase.FAILED -> "점검 실패\n"
                        OfficialEnvironmentPreflightPhase.IDLE -> "확인 필요\n"
                    } +
                    "원인: ${blocking.ifBlank { "공식 환경 조건" }}을 확인하지 못했습니다.\n" +
                    skippedQualityNotice +
                    measurement +
                    "다음 행동: 화면 안내에 따라 기다리거나 자세·장소를 조정하세요. " +
                    "점검이 끝났다면 다시 점검 버튼을 누르세요."
            OfficialEnvironmentSupport.UNSUPPORTED ->
                "$OFFICIAL_ENVIRONMENT_SUPPORT_NOTICE_KO\n" +
                    (if (officialEnvironmentCameraPreflightActive) "조정 필요\n" else "사용 불가\n") +
                    "원인: ${blocking.ifBlank { "현재 환경" }}이 공식 지원 조건과 다릅니다.\n" +
                    skippedQualityNotice +
                    measurement +
                    "다음 행동: 안내된 문제를 바로잡는 동안 보행 안내를 시작하지 마세요."
        }
    }

    private fun officialEnvironmentMeasurementDetail(
        assessment: OfficialEnvironmentAssessment,
    ): String {
        val details = buildList {
            if (
                OfficialEnvironmentFactor.GPS_QUALITY in assessment.blockingFactors ||
                officialEnvironmentCameraPreflightActive
            ) {
                val accuracy = officialEnvironmentGpsDiagnosticAccuracyMeters
                val limit = activeOfficialEnvironmentProfile?.maximumGpsHorizontalAccuracyMeters
                add(
                    when (officialEnvironmentGpsDiagnosticDetail) {
                        "GPS_ACCURACY_OUTSIDE_APPROVED_RANGE" ->
                            if (accuracy != null && limit != null) {
                                "위치: 현재 정확도 ${oneDecimal(accuracy)}m · 기준 " +
                                    "${oneDecimal(limit)}m 이하. 열린 하늘이 보이는 곳에서 잠시 기다리세요."
                            } else {
                                "위치: 정확도가 기준을 넘었습니다. 열린 하늘이 보이는 곳에서 기다리세요."
                            }
                        "GPS_QUALITY_PASSED" -> if (officialEnvironmentCameraPreflightActive) {
                            "위치: 정확도 기준을 통과했고 계속 갱신 중입니다."
                        } else {
                            "위치: 마지막 측정은 통과했지만 전체 점검이 만료되어 다시 측정해야 합니다."
                        }
                        "TRUSTED_FIX_UNAVAILABLE" ->
                            "위치: 신뢰할 수 있는 실제 위치를 받지 못했습니다. 모의 위치 설정을 끄고 이동하지 않은 상태로 기다리세요."
                        "INVALID_ACCURACY" -> "위치: 정확도 값이 아직 없어 새 위치를 기다리고 있습니다."
                        "STALE_OR_INVALID_TIMESTAMP" -> "위치: 최신 위치가 아니어서 새 위치를 기다리고 있습니다."
                        "LOCATION_REQUEST_FAILED" -> "위치: Android 위치 요청을 시작하지 못했습니다."
                        else -> if (officialEnvironmentCameraPreflightActive) {
                            "위치: 고정밀 위치를 받는 중입니다."
                        } else {
                            "위치: 새 측정이 필요합니다."
                        }
                    },
                )
            }
            if (
                OfficialEnvironmentFactor.CAMERA_QUALITY in assessment.blockingFactors ||
                officialEnvironmentCameraPreflightActive
            ) {
                val observation = officialEnvironmentCameraDiagnosticObservation
                val profile = activeCameraFrameQualityProfile
                add(
                    when (officialEnvironmentCameraDiagnosticReason) {
                        "PASSED" -> if (officialEnvironmentCameraPreflightActive) {
                            "카메라: 밝기·렌즈·흔들림·정면 각도 기준을 통과했고 계속 확인 중입니다."
                        } else {
                            "카메라: 마지막 측정은 통과했지만 전체 점검이 만료되어 다시 측정해야 합니다."
                        }
                        "CAMERA_STABILIZING" -> "카메라: 안정된 화면을 연속 확인하는 중입니다. 휴대전화를 그대로 유지하세요."
                        CameraFrameQualityReason.BRIGHTNESS_OUTSIDE_APPROVED_RANGE.name ->
                            "카메라: 현재 밝기 ${oneDecimal(observation?.normalizedBrightness)} · " +
                                "기준 ${oneDecimal(profile?.minimumNormalizedBrightness)} 이상입니다. 더 밝은 곳으로 이동하세요."
                        CameraFrameQualityReason.OCCLUSION_OUTSIDE_APPROVED_RANGE.name ->
                            "카메라: 렌즈 가림 ${percentOneDecimal(observation?.occludedFraction)} · " +
                                "기준 ${percentOneDecimal(profile?.maximumOccludedFraction)} 이하입니다. 렌즈를 완전히 열어 주세요."
                        CameraFrameQualityReason.SHAKE_OUTSIDE_APPROVED_RANGE.name ->
                            "카메라: 흔들림 ${oneDecimal(observation?.angularShakeDegreesPerSecond)}도/초 · " +
                                "기준 ${oneDecimal(profile?.maximumAngularShakeDegreesPerSecond)}도/초 이하입니다. 거치대를 고정하세요."
                        CameraFrameQualityReason.MOUNT_ANGLE_OUTSIDE_APPROVED_RANGE.name ->
                            "카메라: 정면 각도 ${oneDecimal(observation?.mountPitchDegrees)}도 · " +
                                "기준 ${oneDecimal(profile?.minimumMountPitchDegrees)}도 이상 " +
                                "${oneDecimal(profile?.maximumMountPitchDegrees)}도 이하입니다. " +
                                "휴대전화 뒷면 카메라가 앞을 향하도록 세우세요."
                        CameraFrameQualityReason.FRAME_UNAVAILABLE.name,
                        "CAMERA_BIND_FAILED",
                        -> "카메라: 영상을 받을 수 없습니다. 다른 카메라 앱을 닫고 다시 점검하세요."
                        "MOUNTING_SENSOR_UNAVAILABLE" ->
                            "카메라: 자이로·중력 센서를 사용할 수 없어 장착 상태를 측정하지 못했습니다."
                        else -> if (officialEnvironmentCameraPreflightActive) {
                            "카메라: 영상과 장착 센서 값을 받는 중입니다."
                        } else {
                            "카메라: 새 측정이 필요합니다."
                        }
                    },
                )
            }
        }
        return details.joinToString(separator = "\n", postfix = if (details.isEmpty()) "" else "\n")
    }

    private fun oneDecimal(value: Double?): String =
        value?.takeIf { it.isFinite() }?.let { String.format(Locale.US, "%.1f", it) }
            ?: "확인 중"

    private fun percentOneDecimal(value: Double?): String =
        value?.takeIf { it.isFinite() }?.let { String.format(Locale.US, "%.1f%%", it * 100.0) }
            ?: "확인 중"

    private fun OfficialEnvironmentFactor.labelKo(): String = when (this) {
        OfficialEnvironmentFactor.GPS_QUALITY -> "위치 품질"
        OfficialEnvironmentFactor.CAMERA_QUALITY -> "카메라 품질"
        OfficialEnvironmentFactor.BRIGHT_TIME -> "밝은 시간"
        OfficialEnvironmentFactor.DRY_WEATHER -> "비·눈 없음"
        OfficialEnvironmentFactor.NO_DENSE_FOG -> "짙은 안개 없음"
        OfficialEnvironmentFactor.ORDINARY_URBAN_SIDEWALK -> "일반 도심 보도"
        OfficialEnvironmentFactor.NO_CONSTRUCTION -> "공사구간 아님"
        OfficialEnvironmentFactor.NO_SEVERE_CROWDING -> "심한 혼잡 없음"
        OfficialEnvironmentFactor.SUPPORT_LIMITS_NOTICE_ACKNOWLEDGED ->
            "지원범위와 제한사항 고지 확인"
    }

    private fun invalidateOfficialEnvironmentEvidence(reason: String) {
        cancelRuntimeCameraHandoff()
        officialEnvironmentAfterCameraRelease = null
        stopOfficialEnvironmentCameraPreflight()
        if (::phoneMountingSensorProbe.isInitialized) phoneMountingSensorProbe.stop()
        officialEnvironmentPreflightGeneration += 1L
        officialEnvironmentWatchdogGeneration += 1L
        officialEnvironmentUserConfirmation = null
        officialEnvironmentGpsEvidence = null
        officialEnvironmentCameraEvidence = null
        officialEnvironmentGpsDiagnosticAccuracyMeters = null
        officialEnvironmentGpsDiagnosticDetail = null
        officialEnvironmentCameraDiagnosticObservation = null
        officialEnvironmentCameraDiagnosticReason = null
        officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.IDLE
        officialEnvironmentReadyGraceGeneration = -1L
        prewalkGuidanceStage = 0
        officialEnvironmentRuntimeGuard = null
        runtimeGpsQualityGate.reset()
        runtimeCameraQualityGate.reset()
        latestRuntimeRawCameraAssessment = null
        lastOfficialEnvironmentRuntimeAction = null
        lastOfficialEnvironmentUnavailableFactors = emptySet()
        officialEnvironmentOutputsAllowed = false
        if (::fieldSessionLog.isInitialized) {
            fieldSessionLog.recordEvent(
                "official_environment_evidence_invalidated",
                mapOf("reason" to reason),
            )
        }
        if (::officialEnvironmentStatusText.isInitialized) {
            updateOfficialEnvironmentUi()
        }
    }

    private fun confirmPhoneMounting(method: PhoneMountingMethod) {
        if (developmentGuidanceStartBypassEnabled) return
        if (!isActivityForeground || !::walkSessionLifecycle.isInitialized) return
        if (!requireFirstRunOnboardingComplete("phone_mounting_confirmation")) return
        if (!cameraAnalysisFeaturesEnabled()) {
            updateStatus(
                "휴대전화 장착 점검 생략",
                "카메라 분석 기능이 제한되어 관련 장착 점검을 생략합니다.",
            )
            return
        }
        val snapshot = walkSessionLifecycle.snapshot()
        val runtimeState = phoneMountingRuntimeState
        val activeCorrection =
            snapshot.state == WalkSessionState.ACTIVE &&
                runtimeState?.epoch == snapshot.epoch &&
                runtimeState.correctionRequiredSinceElapsedRealtimeMs != null &&
                walkSessionLifecycle.isRuntimeEpochCurrent(snapshot.epoch)
        if (
            snapshot.state !in setOf(
                WalkSessionState.READY,
                WalkSessionState.PAUSED,
            ) &&
            !activeCorrection
        ) {
            updateStatus(
                "휴대전화 장착 확인 불가",
                "새 보행 준비, 일시중지 재검사 또는 장착 교정 상태에서 다시 확인하세요.",
            )
            return
        }
        if (
            !activeCorrection &&
                officialEnvironmentReadiness(snapshot.epoch).first !=
                WalkSessionReadinessStatus.READY
        ) {
            updateStatus(
                "환경 확인 먼저 필요",
                "지원 환경 확인과 위치·카메라 측정을 먼저 통과한 뒤 휴대전화 정면 고정을 확인하세요.",
            )
            officialEnvironmentConfirmButton.post {
                if (officialEnvironmentConfirmButton.isShown) {
                    officialEnvironmentConfirmButton.requestFocus()
                }
            }
            return
        }
        if (
            activeCorrection &&
            phoneMountingRuntimeRetryArmedAtElapsedRealtimeMs != null
        ) {
            updateStatus(
                "휴대전화 장착 재검사 중",
                "교정 확인 뒤의 새 카메라 결과를 기다리고 있습니다.",
            )
            return
        }
        if (
            !activeCorrection &&
            (
                officialEnvironmentCameraPreflightActive ||
                    officialEnvironmentCameraCleanupPending
            )
        ) {
            stopOfficialEnvironmentCameraPreflight(
                onReleased = { confirmPhoneMounting(method) },
            )
            return
        }
        if (!activeCorrection) {
            resetPrewalkCameraEvidenceForNewAttempt()
            officialEnvironmentReadyGraceGeneration = -1L
            prewalkGuidanceStage = 0
        }
        val confirmedAtMs = if (activeCorrection) {
            synchronized(phoneMountingObservationLock) {
                val value = SystemClock.elapsedRealtime()
                phoneMountingUserConfirmation = PhoneMountingUserConfirmation(
                    epoch = snapshot.epoch,
                    confirmedAtElapsedRealtimeMs = value,
                    method = method,
                    postFaultCorrectionConfirmed = true,
                )
                phoneMountingRuntimeRetryArmedAtElapsedRealtimeMs = value
                phoneMountingAppliedFaultSequence = maxOf(
                    phoneMountingAppliedFaultSequence,
                    phoneMountingPendingFaultSequence,
                )
                value
            }
        } else {
            synchronized(phoneMountingObservationLock) {
                SystemClock.elapsedRealtime().also { value ->
                    phoneMountingUserConfirmation = PhoneMountingUserConfirmation(
                        epoch = snapshot.epoch,
                        confirmedAtElapsedRealtimeMs = value,
                        method = method,
                        postFaultCorrectionConfirmed = false,
                    )
                }
            }
        }
        if (activeCorrection) {
            schedulePhoneMountingRuntimeRetryTimeout(
                epoch = snapshot.epoch,
                armedAtElapsedRealtimeMs = confirmedAtMs,
            )
            updatePhoneMountingUi()
            updateStatus(
                "휴대전화 장착 재검사 중",
                "교정 확인 뒤의 새 카메라 결과를 기다리고 있습니다.",
            )
            speakInteraction(
                "장착 교정을 확인했습니다. 새 카메라 검사를 진행합니다.",
            )
            return
        } else {
            if (startOfficialEnvironmentCameraPreflight(snapshot.epoch)) {
                if (
                    postLoginDeviceFeatureEnabled(
                        PostLoginDeviceCheckFeature.LOCATION_GUIDANCE,
                    )
                ) {
                    requestOfficialEnvironmentGpsPreflight(
                        epoch = snapshot.epoch,
                        clearExistingEvidence = false,
                    )
                }
            } else {
                officialEnvironmentPreflightPhase = OfficialEnvironmentPreflightPhase.FAILED
            }
            updatePhoneMountingUi()
            refreshStartupCapabilityUi()
        }
        speakInteraction(
            "휴대전화가 앞을 향하도록 고정된 상태를 기록했습니다. " +
                "카메라 품질과 현재 장착 측정 기준도 통과해야 하며, " +
                "흰지팡이와 안내견을 대신하지 않습니다.",
        )
    }

    private fun resetPrewalkCameraEvidenceForNewAttempt() {
        synchronized(phoneMountingObservationLock) {
            runtimeCameraQualityGate.reset()
            latestRuntimeRawCameraAssessment = null
            phoneMountingObservationGeneration += 1L
            officialEnvironmentCameraStabilityGate.reset()
            officialEnvironmentCameraDiagnosticObservation = null
            officialEnvironmentCameraDiagnosticReason = null
            latestPhoneMountingCameraAssessment = null
            phoneMountingObservationSequence = 0L
            phoneMountingPendingFaultSequence = 0L
            phoneMountingAppliedFaultSequence = 0L
        }
        officialEnvironmentCameraEvidence = null
    }

    private fun currentPhoneMountingAssessment(
        epoch: WalkRuntimeEpoch = walkSessionLifecycle.snapshot().epoch,
        nowElapsedRealtimeMs: Long = SystemClock.elapsedRealtime(),
        phase: PhoneMountingAssessmentPhase = PhoneMountingAssessmentPhase.PREFLIGHT,
        previousState: PhoneMountingRuntimeState? = null,
        cameraFrameQualityOverride: CameraFrameQualityAssessment? = null,
        runtimeRetryRequested: Boolean = false,
    ): PhoneMountingAssessment {
        val cameraFrameQuality =
            cameraFrameQualityOverride ?: latestPhoneMountingCameraAssessment
        return PhoneMountingPolicy.assess(
            phase = phase,
            currentEpoch = epoch,
            nowElapsedRealtimeMs = nowElapsedRealtimeMs,
            userConfirmation = phoneMountingUserConfirmation,
            cameraFrameQuality = cameraFrameQuality,
            previousState = previousState ?: PhoneMountingPolicy.initialState(
                epoch = epoch,
                approvedProfile = activePhoneMountingProfile,
            ),
            runtimeRetryRequested = runtimeRetryRequested,
            checkRequest = nativePhoneMountingCheckRequest?.takeIf {
                isActivityForeground && it.actorId == reporterUserId &&
                    it.gatewayGeneration == GatewaySessionProcessCoordinator.snapshot().generation &&
                    it.checkRequest.epoch == epoch
            }?.checkRequest,
        )
    }

    private fun phoneMountingReadiness(
        epoch: WalkRuntimeEpoch,
    ): Pair<WalkSessionReadinessStatus, String> {
        if (developmentGuidanceStartBypassEnabled) return WalkSessionReadinessStatus.READY to ""
        if (!cameraAnalysisFeaturesEnabled()) {
            return WalkSessionReadinessStatus.READY to ""
        }
        val snapshot = walkSessionLifecycle.snapshot()
        val runtimeState = phoneMountingRuntimeState
        if (
            snapshot.state == WalkSessionState.ACTIVE &&
            runtimeState != null &&
            runtimeState.epoch == epoch &&
            walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
        ) {
            // A mounting fault restricts camera outputs; GPS guidance has its own gate.
            return WalkSessionReadinessStatus.READY to ""
        }
        val assessment = currentPhoneMountingAssessment(epoch)
        if (activePhoneMountingProfile == null) {
            return WalkSessionReadinessStatus.UNAVAILABLE to
                "phone_mounting:approved_profile_unavailable"
        }
        return when (assessment.status) {
            PhoneMountingStatus.SUITABLE ->
                WalkSessionReadinessStatus.READY to ""
            PhoneMountingStatus.CORRECTION_REQUIRED ->
                WalkSessionReadinessStatus.PENDING to
                    "phone_mounting:${assessment.reason.name.lowercase(Locale.US)}"
            PhoneMountingStatus.UNUSABLE ->
                WalkSessionReadinessStatus.UNAVAILABLE to
                    "phone_mounting:${assessment.reason.name.lowercase(Locale.US)}"
        }
    }

    private fun phoneMountingBlockReason(
        epoch: WalkRuntimeEpoch = walkSessionLifecycle.snapshot().epoch,
    ): String? {
        val (status, _) = phoneMountingReadiness(epoch)
        if (status == WalkSessionReadinessStatus.READY) return null
        return phoneMountingStatusMessage(currentPhoneMountingAssessment(epoch))
    }

    private fun updatePhoneMountingUi() {
        if (
            !::phoneMountingStatusText.isInitialized ||
            !::phoneMountingChestConfirmButton.isInitialized ||
            !::phoneMountingNecklaceConfirmButton.isInitialized ||
            !::walkSessionLifecycle.isInitialized
        ) return
        val snapshot = walkSessionLifecycle.snapshot()
        if (developmentGuidanceStartBypassEnabled) {
            phoneMountingStatusText.visibility = View.GONE
            phoneMountingChestConfirmButton.visibility = View.GONE
            phoneMountingNecklaceConfirmButton.visibility = View.GONE
            return
        }
        if (!cameraAnalysisFeaturesEnabled()) {
            val message =
                "카메라 분석 기능이 제한되어 휴대전화 장착 점검을 생략합니다."
            applyWsStatusText(phoneMountingStatusText, message)
            phoneMountingStatusText.contentDescription = message
            phoneMountingChestConfirmButton.visibility = View.GONE
            phoneMountingNecklaceConfirmButton.visibility = View.GONE
            return
        }
        val mountingChoiceVisibility = if (
            developmentQuickStartEnabled && snapshot.state == WalkSessionState.READY
        ) View.GONE else View.VISIBLE
        phoneMountingChestConfirmButton.visibility = mountingChoiceVisibility
        phoneMountingNecklaceConfirmButton.visibility = View.GONE
        val runtimeState = phoneMountingRuntimeState
        val activeCorrection =
            snapshot.state == WalkSessionState.ACTIVE &&
                runtimeState?.epoch == snapshot.epoch &&
                runtimeState.correctionRequiredSinceElapsedRealtimeMs != null &&
                !runtimeState.safetyStopRequired
        val assessment = if (runtimeState?.epoch == snapshot.epoch) {
            currentPhoneMountingAssessment(
                epoch = snapshot.epoch,
                phase = PhoneMountingAssessmentPhase.ACTIVE,
                previousState = runtimeState,
            )
        } else {
            currentPhoneMountingAssessment(snapshot.epoch)
        }
        val message = phoneMountingStatusMessage(assessment)
        if (phoneMountingStatusText.text.toString() != message) {
            applyWsStatusText(phoneMountingStatusText, message)
            phoneMountingStatusText.contentDescription = message
        }
        val buttonsEnabled =
            activePhoneMountingProfile != null &&
                firstRunOnboardingComplete() &&
                isActivityForeground &&
                (
                    activeCorrection ||
                        officialEnvironmentReadiness(snapshot.epoch).first ==
                        WalkSessionReadinessStatus.READY
                ) &&
                (
                    snapshot.state in setOf(WalkSessionState.READY, WalkSessionState.PAUSED) ||
                        activeCorrection
                )
        updatePhoneMountingButton(
            button = phoneMountingChestConfirmButton,
            baseLabel = "휴대전화 정면 고정",
            enabled = buttonsEnabled,
            activeCorrection = activeCorrection,
            epoch = snapshot.epoch,
        )
    }

    private fun updatePhoneMountingButton(
        button: Button,
        baseLabel: String,
        enabled: Boolean,
        activeCorrection: Boolean,
        epoch: WalkRuntimeEpoch,
    ) {
        val runtimeRetryPending =
            activeCorrection &&
                phoneMountingRuntimeRetryArmedAtElapsedRealtimeMs != null
        button.isEnabled = enabled && !runtimeRetryPending
        button.text = when {
            runtimeRetryPending ->
                "$baseLabel 카메라 재검사 중"
            activeCorrection -> "$baseLabel 교정 완료 후 재검사"
            phoneMountingUserConfirmation?.let {
                it.epoch == epoch &&
                    (it.method == PhoneMountingMethod.CHEST_FORWARD ||
                        it.method == PhoneMountingMethod.NECKLACE_FORWARD)
            } == true -> "$baseLabel 다시 확인"
            else -> "$baseLabel 확인"
        }
        button.contentDescription = button.text
    }

    private fun phoneMountingStatusMessage(
        assessment: PhoneMountingAssessment,
    ): String {
        if (developmentGuidanceStartBypassEnabled) return "안내 시작 전 장착·교정 점검을 생략합니다."
        val status = when (assessment.status) {
            PhoneMountingStatus.SUITABLE -> "적합"
            PhoneMountingStatus.CORRECTION_REQUIRED -> "교정 필요"
            PhoneMountingStatus.UNUSABLE -> "사용 불가"
        }
        val candidateNotice = if (
            activeEnvironmentProfiles?.approvedForProduction == false
        ) {
            "출시 전 현장시험 후보 기준이며 정식 승인 결과가 아닙니다.\n"
        } else {
            ""
        }
        return candidateNotice +
            "휴대전화를 가슴 앞에 밀착해 세로로 고정하고 후면 카메라를 바깥으로 향하게 하세요. " +
            "손에 들거나 주머니에 넣지 마세요. " +
            "WalkSafe는 흰지팡이·안내견 등 기존 보조수단을 대신하지 않습니다.\n" +
            "$status\n원인: ${assessment.accessibleReasonKo}\n" +
            "다음 행동: ${assessment.accessibleActionKo}"
    }

    private fun invalidatePhoneMountingEvidence(reason: String) {
        cancelRuntimeCameraHandoff()
        synchronized(phoneMountingObservationLock) {
            runtimeCameraQualityGate.reset()
            latestRuntimeRawCameraAssessment = null
            phoneMountingObservationGeneration += 1L
            latestPhoneMountingCameraAssessment = null
            phoneMountingObservationSequence = 0L
            phoneMountingPendingFaultSequence = 0L
            phoneMountingAppliedFaultSequence = 0L
            phoneMountingOutputsAllowed = false
            phoneMountingRuntimeRetryGeneration += 1L
            phoneMountingRuntimeRetryArmedAtElapsedRealtimeMs = null
        }
        phoneMountingWatchdogGeneration += 1L
        phoneMountingUserConfirmation = null
        phoneMountingRuntimeState = null
        if (::fieldSessionLog.isInitialized) {
            fieldSessionLog.recordEvent(
                "phone_mounting_evidence_invalidated",
                mapOf("reason" to reason),
            )
        }
        if (::phoneMountingStatusText.isInitialized) {
            updatePhoneMountingUi()
        }
    }

    private fun cameraFrameQualityObservation(
        epoch: WalkRuntimeEpoch,
        observedAtElapsedRealtimeMs: Long,
        frameAvailable: Boolean?,
        width: Int? = null,
        height: Int? = null,
        yPlaneBuffer: ByteBuffer? = null,
        yPlaneRowStride: Int? = null,
        yPlanePixelStride: Int? = null,
    ): CameraFrameQualityObservation {
        val luma = if (
            frameAvailable == true &&
            width != null &&
            height != null &&
            yPlaneBuffer != null &&
            yPlaneRowStride != null &&
            yPlanePixelStride != null
        ) {
            CameraLumaMeasurementPolicy.measure(
                buffer = yPlaneBuffer,
                width = width,
                height = height,
                rowStride = yPlaneRowStride,
                pixelStride = yPlanePixelStride,
            )
        } else {
            null
        }
        val mounting = if (frameAvailable == true) {
            // Read sensor freshness against the current sensor clock. A callback can arrive
            // while luma is being measured and be newer than the frame observation time.
            phoneMountingSensorProbe.latestNow()
        } else {
            null
        }
        return CameraFrameQualityObservation(
            epoch = epoch,
            observedAtElapsedRealtimeMs = observedAtElapsedRealtimeMs,
            frameAvailable = frameAvailable,
            normalizedBrightness = luma?.normalizedBrightness,
            occludedFraction = luma?.darkOrOccludedFraction,
            angularShakeDegreesPerSecond = mounting?.angularShakeDegreesPerSecond,
            mountPitchDegrees = mounting?.cameraPitchFromHorizontalDegrees,
        )
    }

    private fun observeOfficialEnvironmentCameraFrame(
        observation: CameraFrameQualityObservation,
        expectedCameraPreflightGeneration: Long? = null,
    ): CameraFrameQualityObservation? {
        if (developmentGuidanceStartBypassEnabled) return observation
        val epoch = observation.epoch
        val observedAtElapsedRealtimeMs = observation.observedAtElapsedRealtimeMs
        val observationGeneration = phoneMountingObservationGeneration
        if (
            walkSessionLifecycle.snapshot().epoch != epoch ||
            (
                expectedCameraPreflightGeneration != null &&
                    !isOfficialEnvironmentCameraPreflightCurrent(
                        epoch,
                        expectedCameraPreflightGeneration,
                    )
                )
        ) return null
        var cameraAssessment = CameraFrameQualityPolicy.assess(
            currentEpoch = epoch,
            nowElapsedRealtimeMs = SystemClock.elapsedRealtime(),
            observation = observation,
            approvedProfile = activeCameraFrameQualityProfile,
        )
        if (expectedCameraPreflightGeneration == null) {
            val handoffStartedAtMs = synchronized(phoneMountingObservationLock) {
                runtimeCameraHandoffStartedAtElapsedRealtimeMs.takeIf {
                    runtimeCameraHandoffEpoch == epoch
                }
            }
            if (handoffStartedAtMs != null) {
                if (
                    observedAtElapsedRealtimeMs < handoffStartedAtMs ||
                    cameraAssessment.status != EnvironmentEvidenceStatus.PASS
                ) return observation
                synchronized(phoneMountingObservationLock) {
                    if (runtimeCameraHandoffEpoch == epoch) {
                        runtimeCameraHandoffEpoch = null
                        runtimeCameraHandoffStartedAtElapsedRealtimeMs = null
                        runtimeCameraHandoffGeneration += 1L
                    }
                }
            }
        }
        if (BuildConfig.DEBUG && expectedCameraPreflightGeneration != null) {
            val profile = activeCameraFrameQualityProfile
            android.util.Log.d(
                CAMERA_PREFLIGHT_LOG_TAG,
                "generation=$expectedCameraPreflightGeneration " +
                    "frameAvailable=${observation.frameAvailable} " +
                    "brightness=${observation.normalizedBrightness} " +
                    "minimumBrightness=${profile?.minimumNormalizedBrightness} " +
                    "occludedFraction=${observation.occludedFraction} " +
                    "maximumOccludedFraction=${profile?.maximumOccludedFraction} " +
                    "shakeDegreesPerSecond=${observation.angularShakeDegreesPerSecond} " +
                    "maximumShakeDegreesPerSecond=${profile?.maximumAngularShakeDegreesPerSecond} " +
                    "mountPitchDegrees=${observation.mountPitchDegrees} " +
                    "mountPitchRange=${profile?.minimumMountPitchDegrees}.." +
                    "${profile?.maximumMountPitchDegrees} " +
                    "status=${cameraAssessment.status} reason=${cameraAssessment.reason}",
            )
        }
        val mountingProfile = activePhoneMountingProfile
        var mountingFault = false
        val rawEvidence = cameraAssessment.asMeasuredEnvironmentEvidence()
        val commit = synchronized(phoneMountingObservationLock) {
            if (
                observationGeneration != phoneMountingObservationGeneration ||
                (
                    expectedCameraPreflightGeneration != null &&
                        !isOfficialEnvironmentCameraPreflightCurrent(
                            epoch,
                            expectedCameraPreflightGeneration,
                        )
                    )
            ) {
                null
            } else {
                val previous = officialEnvironmentCameraEvidence
                val previousObservedAtMs = previous?.observedAtElapsedRealtimeMs
                val candidateObservedAtMs = rawEvidence.observedAtElapsedRealtimeMs
                if (
                    previousObservedAtMs != null &&
                    (candidateObservedAtMs == null || candidateObservedAtMs < previousObservedAtMs)
                ) {
                    return@synchronized null
                }
                val stabilityDecision = if (expectedCameraPreflightGeneration != null) {
                    officialEnvironmentCameraStabilityGate.observe(
                        status = cameraAssessment.status,
                        transientQualityFailure =
                            cameraAssessment.reason.isTransientPreflightQualityFailure(),
                    )
                } else {
                    CameraPreflightStabilityDecision.ACCEPT
                }
                val preflightEvidence = when (stabilityDecision) {
                    CameraPreflightStabilityDecision.STABILIZING -> rawEvidence.copy(
                        status = EnvironmentEvidenceStatus.UNKNOWN,
                        detail = "CAMERA_STABILIZING",
                    )
                    CameraPreflightStabilityDecision.RETAIN_PREVIOUS_PASS ->
                        previous?.takeIf { it.status == EnvironmentEvidenceStatus.PASS }
                            ?: rawEvidence
                    CameraPreflightStabilityDecision.ACCEPT -> rawEvidence
                }
                val evidence = if (expectedCameraPreflightGeneration == null &&
                    walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
                ) {
                    latestRuntimeRawCameraAssessment = cameraAssessment
                    runtimeCameraQualityGate.observe(rawEvidence, SystemClock.elapsedRealtime())
                } else {
                    preflightEvidence
                }
                if (evidence !== rawEvidence &&
                    evidence.status == EnvironmentEvidenceStatus.PASS
                ) {
                    latestPhoneMountingCameraAssessment?.takeIf {
                        it.status == EnvironmentEvidenceStatus.PASS &&
                            it.epoch == evidence.epoch &&
                            it.profileId == evidence.measurementProfileId &&
                            it.observedAtElapsedRealtimeMs == evidence.observedAtElapsedRealtimeMs
                    }?.let { cameraAssessment = it }
                }
                mountingFault = cameraAssessment.status != EnvironmentEvidenceStatus.PASS ||
                    mountingProfile == null ||
                    cameraAssessment.profileId != mountingProfile.cameraFrameQualityProfileId
                phoneMountingObservationSequence += 1L
                val sequence = phoneMountingObservationSequence
                val latestObservedAt =
                    latestPhoneMountingCameraAssessment?.observedAtElapsedRealtimeMs
                val currentObservedAt = cameraAssessment.observedAtElapsedRealtimeMs
                if (
                    stabilityDecision !=
                    CameraPreflightStabilityDecision.RETAIN_PREVIOUS_PASS &&
                    currentObservedAt != null &&
                    (latestObservedAt == null || currentObservedAt >= latestObservedAt)
                ) {
                    latestPhoneMountingCameraAssessment = cameraAssessment
                }
                if (
                    mountingFault &&
                    phoneMountingRuntimeState?.epoch == epoch
                ) {
                    phoneMountingOutputsAllowed = false
                    val retryArmedAt =
                        phoneMountingRuntimeRetryArmedAtElapsedRealtimeMs
                    if (
                        retryArmedAt != null &&
                        currentObservedAt != null &&
                        currentObservedAt <= retryArmedAt
                    ) {
                        phoneMountingAppliedFaultSequence = maxOf(
                            phoneMountingAppliedFaultSequence,
                            sequence,
                        )
                    } else {
                        phoneMountingPendingFaultSequence = maxOf(
                            phoneMountingPendingFaultSequence,
                            sequence,
                        )
                    }
                }
                officialEnvironmentCameraEvidence = evidence
                if (
                    stabilityDecision !=
                    CameraPreflightStabilityDecision.RETAIN_PREVIOUS_PASS
                ) {
                    officialEnvironmentCameraDiagnosticObservation = observation
                    officialEnvironmentCameraDiagnosticReason = evidence.detail
                }
                Triple(sequence, previous, evidence)
            }
        }
        val observationSequence = commit?.first
        val previous = commit?.second
        val evidence = commit?.third ?: return null
        if (observationSequence == null || walkSessionLifecycle.snapshot().epoch != epoch) {
            return null
        }
        val shouldReassessRuntime =
            (
                evidence.status == EnvironmentEvidenceStatus.PASS &&
                    previous?.status != EnvironmentEvidenceStatus.PASS
            ) || (
                officialEnvironmentOutputsAllowed &&
                    evidence.status != EnvironmentEvidenceStatus.PASS
            )
        runOnUiThread {
            if (
                observationGeneration != phoneMountingObservationGeneration ||
                (
                    expectedCameraPreflightGeneration != null &&
                        expectedCameraPreflightGeneration !=
                        officialEnvironmentCameraPreflightGeneration
                    ) ||
                walkSessionLifecycle.snapshot().epoch != epoch
            ) return@runOnUiThread
            if (isWalkSessionRuntimeActive()) {
                val retryArmedAt =
                    phoneMountingRuntimeRetryArmedAtElapsedRealtimeMs
                val runtimeRetryRequested =
                    retryArmedAt != null &&
                        cameraAssessment.observedAtElapsedRealtimeMs?.let {
                            it > retryArmedAt
                        } == true
                val assessment = applyCurrentPhoneMountingRuntimeAssessment(
                    runtimeRetryRequested = runtimeRetryRequested,
                    cameraFrameQualityOverride = cameraAssessment,
                    observationSequence = observationSequence,
                    observationGeneration = observationGeneration,
                    observationIsFault = mountingFault,
                )
                if (runtimeRetryRequested && assessment != null) {
                    synchronized(phoneMountingObservationLock) {
                        if (
                            phoneMountingRuntimeRetryArmedAtElapsedRealtimeMs ==
                            retryArmedAt
                        ) {
                            phoneMountingRuntimeRetryArmedAtElapsedRealtimeMs = null
                            phoneMountingRuntimeRetryGeneration += 1L
                        }
                    }
                    updatePhoneMountingUi()
                }
                if (mountingFault && assessment != null) {
                    synchronized(phoneMountingObservationLock) {
                        if (observationGeneration == phoneMountingObservationGeneration) {
                            phoneMountingAppliedFaultSequence = maxOf(
                                phoneMountingAppliedFaultSequence,
                                observationSequence,
                            )
                        }
                    }
                }
                if ((shouldReassessRuntime || runtimeRetryRequested && assessment != null) &&
                    walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
                ) {
                    applyCurrentOfficialEnvironmentRuntimeAssessment()
                } else if (runtimeCameraQualityGate.pendingFailureDeadlineElapsedRealtimeMs() != null) {
                    scheduleOfficialEnvironmentRuntimeWatchdog(epoch)
                }
            } else {
                updatePhoneMountingUi()
                refreshStartupCapabilityUi()
            }
        }
        return observation
    }

    private fun observeOfficialEnvironmentCameraFrame(
        epoch: WalkRuntimeEpoch,
        observedAtElapsedRealtimeMs: Long,
        frameAvailable: Boolean?,
    ): CameraFrameQualityObservation? = observeOfficialEnvironmentCameraFrame(
        cameraFrameQualityObservation(
            epoch = epoch,
            observedAtElapsedRealtimeMs = observedAtElapsedRealtimeMs,
            frameAvailable = frameAvailable,
        ),
    )

    private fun recordOfficialEnvironmentGpsObservation(
        epoch: WalkRuntimeEpoch,
        observedAtElapsedRealtimeMs: Long,
        trustedFixAvailable: Boolean?,
        horizontalAccuracyMeters: Double?,
    ) {
        if (walkSessionLifecycle.snapshot().epoch != epoch) return
        val previous = officialEnvironmentGpsEvidence
        val nowMs = SystemClock.elapsedRealtime()
        val rawEvidence = OfficialEnvironmentPolicy.assessGpsQuality(
            currentEpoch = epoch,
            nowElapsedRealtimeMs = nowMs,
            observation = GpsQualityObservation(
                epoch = epoch,
                observedAtElapsedRealtimeMs = observedAtElapsedRealtimeMs,
                trustedFixAvailable = trustedFixAvailable,
                horizontalAccuracyMeters = horizontalAccuracyMeters,
            ),
            approvedProfile = activeOfficialEnvironmentProfile,
        )
        val evidence = if (walkSessionLifecycle.isRuntimeEpochCurrent(epoch)) {
            runtimeGpsQualityGate.observe(rawEvidence, nowMs)
        } else {
            rawEvidence
        }
        officialEnvironmentGpsEvidence = evidence
        val shouldReassessRuntime =
            (
                evidence.status == EnvironmentEvidenceStatus.PASS &&
                    previous?.status != EnvironmentEvidenceStatus.PASS
            ) || (
                officialEnvironmentOutputsAllowed &&
                    evidence.status != EnvironmentEvidenceStatus.PASS
            )
        if (isWalkSessionRuntimeActive() && shouldReassessRuntime) {
            applyCurrentOfficialEnvironmentRuntimeAssessment()
        } else if (isWalkSessionRuntimeActive() &&
            runtimeGpsQualityGate.pendingFailureDeadlineElapsedRealtimeMs() != null
        ) {
            scheduleOfficialEnvironmentRuntimeWatchdog(epoch)
        }
    }

    private fun activateOfficialEnvironmentRuntime(): Boolean {
        if (developmentGuidanceStartBypassEnabled) {
            officialEnvironmentOutputsAllowed = true
            return true
        }
        val epoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return false
        val guard = OfficialEnvironmentRuntimeGuard(
            epoch = epoch,
            approvedProfile = activeOfficialEnvironmentProfile,
        )
        officialEnvironmentRuntimeGuard = guard
        val nowMs = SystemClock.elapsedRealtime()
        runtimeGpsQualityGate.reset()
        runtimeCameraQualityGate.reset()
        officialEnvironmentGpsEvidence?.let { runtimeGpsQualityGate.observe(it, nowMs) }
        officialEnvironmentCameraEvidence?.let { runtimeCameraQualityGate.observe(it, nowMs) }
        latestRuntimeRawCameraAssessment = latestPhoneMountingCameraAssessment
        lastOfficialEnvironmentRuntimeAction = null
        lastOfficialEnvironmentUnavailableFactors = emptySet()
        val runtimeDecision = guard.onAssessment(
            assessment = currentOfficialEnvironmentAssessment(epoch, nowMs),
            nowElapsedRealtimeMs = nowMs,
        )
        applyOfficialEnvironmentRuntimeDecision(runtimeDecision)
        return runtimeDecision.action != OfficialEnvironmentRuntimeAction.SAFE_STOP
    }

    private fun activatePhoneMountingRuntime(): Boolean {
        if (developmentGuidanceStartBypassEnabled) {
            phoneMountingOutputsAllowed = true
            return true
        }
        val epoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return false
        if (!cameraAnalysisFeaturesEnabled()) {
            cancelRuntimeCameraHandoff()
            synchronized(phoneMountingObservationLock) {
                phoneMountingRuntimeState = null
                latestPhoneMountingCameraAssessment = null
                phoneMountingObservationGeneration += 1L
                phoneMountingObservationSequence = 0L
                phoneMountingPendingFaultSequence = 0L
                phoneMountingAppliedFaultSequence = 0L
                phoneMountingOutputsAllowed = true
                phoneMountingRuntimeRetryGeneration += 1L
                phoneMountingRuntimeRetryArmedAtElapsedRealtimeMs = null
            }
            phoneMountingWatchdogGeneration += 1L
            phoneMountingSensorProbe.stop()
            return true
        }
        if (!phoneMountingSensorProbe.start()) {
            phoneMountingRuntimeState = PhoneMountingPolicy.initialState(
                epoch = epoch,
                approvedProfile = activePhoneMountingProfile,
            )
            observeOfficialEnvironmentCameraFrame(
                epoch = epoch,
                observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                frameAvailable = false,
            )
            updateStatus(
                "장착 센서 시작 실패",
                "자이로·중력 센서를 사용할 수 없어 카메라 인식과 거리 안내를 제한합니다. 위치 품질이 확인되면 경로 안내는 계속됩니다.",
            )
            return walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
        }
        val initialState = PhoneMountingPolicy.initialState(
            epoch = epoch,
            approvedProfile = activePhoneMountingProfile,
        )
        phoneMountingRuntimeState = initialState
        val assessment = currentPhoneMountingAssessment(
            epoch = epoch,
            phase = PhoneMountingAssessmentPhase.ACTIVE,
            previousState = initialState,
        )
        phoneMountingRuntimeState = assessment.nextState
        applyPhoneMountingRuntimeAssessment(
            assessment = assessment,
            announceCorrection =
                assessment.status == PhoneMountingStatus.CORRECTION_REQUIRED,
            outputsAlreadyRevoked = false,
        )
        return walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
    }

    private fun beginRuntimeCameraHandoff(epoch: WalkRuntimeEpoch) {
        if (developmentGuidanceStartBypassEnabled) {
            phoneMountingOutputsAllowed = true
            return
        }
        val startedAtMs = SystemClock.elapsedRealtime()
        val generation = synchronized(phoneMountingObservationLock) {
            runtimeCameraHandoffEpoch = epoch
            runtimeCameraHandoffStartedAtElapsedRealtimeMs = startedAtMs
            officialEnvironmentCameraEvidence = null
            latestPhoneMountingCameraAssessment = null
            runtimeCameraQualityGate.reset()
            latestRuntimeRawCameraAssessment = null
            phoneMountingOutputsAllowed = false
            phoneMountingObservationSequence = 0L
            phoneMountingPendingFaultSequence = 0L
            phoneMountingAppliedFaultSequence = 0L
            runtimeCameraHandoffGeneration += 1L
            runtimeCameraHandoffGeneration
        }
        officialEnvironmentWatchdogGeneration += 1L
        phoneMountingWatchdogGeneration += 1L
        applyCurrentOfficialEnvironmentRuntimeAssessment()
        statusText.postDelayed(
            {
                val timedOut = synchronized(phoneMountingObservationLock) {
                    if (
                        generation != runtimeCameraHandoffGeneration ||
                        runtimeCameraHandoffEpoch != epoch ||
                        !walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
                    ) {
                        false
                    } else {
                        runtimeCameraHandoffEpoch = null
                        runtimeCameraHandoffStartedAtElapsedRealtimeMs = null
                        runtimeCameraHandoffGeneration += 1L
                        true
                    }
                }
                if (!timedOut) return@postDelayed
                observeOfficialEnvironmentCameraFrame(
                    epoch = epoch,
                    observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                    frameAvailable = false,
                )
                updateStatus(
                    "런타임 카메라 연결 시간 초과",
                    "카메라 전환 뒤 유효한 영상을 받지 못해 보행 출력을 계속 중지합니다. 카메라를 사용하는 다른 앱을 닫고 장착 상태를 다시 확인하세요.",
                )
            },
            RUNTIME_CAMERA_HANDOFF_TIMEOUT_MS,
        )
    }

    private fun cancelRuntimeCameraHandoff() {
        synchronized(phoneMountingObservationLock) {
            runtimeCameraHandoffEpoch = null
            runtimeCameraHandoffStartedAtElapsedRealtimeMs = null
            runtimeCameraHandoffGeneration += 1L
        }
    }

    private fun applyCurrentPhoneMountingRuntimeAssessment(
        runtimeRetryRequested: Boolean,
        cameraFrameQualityOverride: CameraFrameQualityAssessment? = null,
        observationSequence: Long? = null,
        observationGeneration: Long? = null,
        observationIsFault: Boolean = false,
    ): PhoneMountingAssessment? {
        val previousState = phoneMountingRuntimeState ?: return null
        if (!walkSessionLifecycle.isRuntimeEpochCurrent(previousState.epoch)) return null
        val transition = synchronized(phoneMountingObservationLock) {
            if (phoneMountingRuntimeState !== previousState) return@synchronized null
            if (observationSequence != null) {
                if (
                    observationGeneration != phoneMountingObservationGeneration ||
                    (
                        observationIsFault &&
                            observationSequence <= phoneMountingAppliedFaultSequence
                    ) ||
                    (
                        !observationIsFault &&
                            (
                                phoneMountingPendingFaultSequence >
                                    phoneMountingAppliedFaultSequence ||
                                    observationSequence <=
                                    phoneMountingAppliedFaultSequence
                            )
                    )
                ) {
                    return@synchronized null
                }
            }
            val assessment = currentPhoneMountingAssessment(
                epoch = previousState.epoch,
                phase = PhoneMountingAssessmentPhase.ACTIVE,
                previousState = previousState,
                cameraFrameQualityOverride = cameraFrameQualityOverride,
                runtimeRetryRequested = runtimeRetryRequested,
            )
            val firstFault =
                previousState.correctionRequiredSinceElapsedRealtimeMs == null &&
                    assessment.nextState.correctionRequiredSinceElapsedRealtimeMs != null
            val outputsRevoked = assessment.status != PhoneMountingStatus.SUITABLE
            if (outputsRevoked) revokePhoneMountingReportOutputLease()
            phoneMountingRuntimeState = assessment.nextState
            Triple(assessment, firstFault, outputsRevoked)
        } ?: return null
        val (assessment, firstFault, outputsRevoked) = transition
        applyPhoneMountingRuntimeAssessment(
            assessment = assessment,
            announceCorrection = firstFault || runtimeRetryRequested,
            outputsAlreadyRevoked = outputsRevoked,
        )
        return assessment
    }

    private fun revokePhoneMountingReportOutputLease() {
        if (developmentGuidanceStartBypassEnabled) return
        synchronized(phoneMountingObservationLock) {
            phoneMountingOutputsAllowed = false
            synchronized(reportUploadSafetyLock) {
                reportUploadSafetyGeneration += 1L
                reportPrivacyConsentSession.cancelActiveCalls()
            }
        }
    }

    private fun applyPhoneMountingRuntimeAssessment(
        assessment: PhoneMountingAssessment,
        announceCorrection: Boolean,
        outputsAlreadyRevoked: Boolean,
    ) {
        if (developmentGuidanceStartBypassEnabled) {
            phoneMountingOutputsAllowed = true
            return
        }
        val epoch = assessment.nextState.epoch
        if (!walkSessionLifecycle.isRuntimeEpochCurrent(epoch)) return
        if (
            assessment.status != PhoneMountingStatus.SUITABLE &&
            !outputsAlreadyRevoked
        ) {
            revokePhoneMountingReportOutputLease()
        }
        when (assessment.status) {
            PhoneMountingStatus.SUITABLE -> {
                val outputEnabled = synchronized(phoneMountingObservationLock) {
                    if (
                        phoneMountingPendingFaultSequence >
                        phoneMountingAppliedFaultSequence
                    ) {
                        false
                    } else {
                        phoneMountingOutputsAllowed = true
                        true
                    }
                }
                if (!outputEnabled) return
                schedulePhoneMountingEvidenceWatchdog(epoch)
                updatePhoneMountingUi()
            }
            PhoneMountingStatus.CORRECTION_REQUIRED -> {
                phoneMountingOutputsAllowed = false
                phoneMountingWatchdogGeneration += 1L
                if (announceCorrection) {
                    invalidatePhoneMountingDetectionOutputs(epoch)
                }
                clearExplicitReportFrameState("phone_mounting_correction")
                latestFeedbackDeliveryState = FeedbackDeliveryState()
                feedbackPolicy.cancelPendingFeedbackDeliveries()
                if (announceCorrection) {
                    cancelVoiceCommandRecognition()
                    feedbackLifecycleGeneration += 1
                    feedbackActuator?.close()
                    feedbackActuator = null
                    updateStatus(
                        "휴대전화 장착 교정 필요",
                        "${assessment.accessibleReasonKo} ${assessment.accessibleActionKo} " +
                            "교정 뒤 화면에서 장착 상태를 명시적으로 다시 확인하세요.",
                    )
                    ensureFeedbackActuator().playPhoneMountingCorrectionVibration()
                    speakStatusExplanation(
                        "휴대전화 장착을 교정하세요. ${assessment.spokenGuidanceKo}",
                    )
                }
                updatePhoneMountingUi()
            }
            PhoneMountingStatus.UNUSABLE -> {
                phoneMountingOutputsAllowed = false
                val detail =
                    "${assessment.accessibleReasonKo} ${assessment.accessibleActionKo} " +
                        "카메라 인식·거리·위험 안내를 제한합니다. 위치 품질이 확인되면 경로 안내는 계속됩니다."
                if (announceCorrection) {
                    invalidatePhoneMountingDetectionOutputs(epoch)
                    updateStatus("휴대전화 장착 · 카메라 기능 제한", detail)
                    ensureFeedbackActuator().playPhoneMountingSafetyStopVibration()
                    speakStatusExplanation(detail)
                }
                updatePhoneMountingUi()
            }
        }
    }

    private fun invalidatePhoneMountingDetectionOutputs(epoch: WalkRuntimeEpoch) {
        synchronized(frameStateLock) {
            if (!walkSessionLifecycle.isRuntimeEpochCurrent(epoch)) return
            detectorGeneration += 1
            resetVisualTrackingState()
            latestDetectionSnapshot = DetectionSnapshot.empty()
            latestExplicitReportOutput = null
            latestExplicitReportImage = null
            latestExplicitReportGateState = null
            latestExplicitReportCapturedAtMs = 0L
            adaptiveInferencePacing.reset()
            lastOverlayUpdateMs = 0L
            lastUiUpdateMs = 0L
            captureLog.clear()
            objectDepthPipeline = ObjectDepthRuntimePipeline(rawDepthMotionOnly = true).also { pipeline ->
                pipeline.setUserStepLength(stepLengthEstimator.stepLengthM)
            }
        }
        nonMetricAdvisoryPolicy.reset()
        if (::debugBboxOverlay.isInitialized) {
            debugBboxOverlay.clear()
        }
    }

    private fun schedulePhoneMountingEvidenceWatchdog(epoch: WalkRuntimeEpoch) {
        val state = phoneMountingRuntimeState ?: return
        val profile = state.approvedProfile ?: return
        if (
            state.epoch != epoch ||
            !phoneMountingOutputsAllowed ||
            !walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
        ) return
        val confirmation = phoneMountingUserConfirmation
        val camera = latestPhoneMountingCameraAssessment
        val nowMs = SystemClock.elapsedRealtime()
        val expiryDelays = buildList {
            if (confirmation?.epoch == epoch) {
                add(
                    remainingEvidenceLifetimeMs(
                        observedAtMs = confirmation.confirmedAtElapsedRealtimeMs,
                        nowMs = nowMs,
                        maximumAgeMs = profile.maximumUserConfirmationAgeMs,
                    ),
                )
            }
            if (
                camera?.epoch == epoch &&
                camera.observedAtElapsedRealtimeMs != null &&
                camera.maximumEvidenceAgeMs != null
            ) {
                add(
                    remainingEvidenceLifetimeMs(
                        observedAtMs = checkNotNull(camera.observedAtElapsedRealtimeMs),
                        nowMs = nowMs,
                        maximumAgeMs = minOf(
                            profile.maximumEvidenceAgeMs,
                            checkNotNull(camera.maximumEvidenceAgeMs),
                        ),
                    ),
                )
            }
        }
        val delayMs = expiryDelays.minOrNull() ?: 1L
        val generation = ++phoneMountingWatchdogGeneration
        phoneMountingStatusText.postDelayed(
            {
                if (
                    generation == phoneMountingWatchdogGeneration &&
                    walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
                ) {
                    applyCurrentPhoneMountingRuntimeAssessment(
                        runtimeRetryRequested = false,
                    )
                }
            },
            delayMs,
        )
    }

    private fun schedulePhoneMountingRuntimeRetryTimeout(
        epoch: WalkRuntimeEpoch,
        armedAtElapsedRealtimeMs: Long,
    ) {
        val profile = phoneMountingRuntimeState?.approvedProfile ?: return
        val generation = ++phoneMountingRuntimeRetryGeneration
        val delayMs = remainingEvidenceLifetimeMs(
            observedAtMs = armedAtElapsedRealtimeMs,
            nowMs = SystemClock.elapsedRealtime(),
            maximumAgeMs = profile.maximumEvidenceAgeMs,
        )
        phoneMountingStatusText.postDelayed(
            {
                if (!walkSessionLifecycle.isRuntimeEpochCurrent(epoch)) {
                    return@postDelayed
                }
                val timeoutClaimed = synchronized(phoneMountingObservationLock) {
                    if (
                        generation != phoneMountingRuntimeRetryGeneration ||
                        phoneMountingRuntimeRetryArmedAtElapsedRealtimeMs !=
                        armedAtElapsedRealtimeMs
                    ) {
                        false
                    } else {
                        phoneMountingRuntimeRetryArmedAtElapsedRealtimeMs = null
                        phoneMountingRuntimeRetryGeneration += 1L
                        true
                    }
                }
                if (!timeoutClaimed) return@postDelayed
                applyCurrentPhoneMountingRuntimeAssessment(
                    runtimeRetryRequested = true,
                )
            },
            delayMs,
        )
    }

    private fun remainingEvidenceLifetimeMs(
        observedAtMs: Long,
        nowMs: Long,
        maximumAgeMs: Long,
    ): Long {
        if (observedAtMs < 0L || nowMs < observedAtMs) return 1L
        val remainingMs = maximumAgeMs - (nowMs - observedAtMs)
        return when {
            remainingMs < 1L -> 1L
            remainingMs == Long.MAX_VALUE -> Long.MAX_VALUE
            else -> remainingMs + 1L
        }
    }

    private fun walkSafetyOutputsAllowed(): Boolean =
        navigationEnvironmentOutputsAllowed() && cameraEnvironmentOutputsAllowed()

    private fun navigationEnvironmentOutputsAllowed(): Boolean =
        developmentGuidanceStartBypassEnabled || (firstRunOnboardingComplete() && officialEnvironmentOutputsAllowed &&
            postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE) &&
            officialEnvironmentRuntimeGuard?.decision()?.navigationOutputsAllowed == true)

    private fun cameraEnvironmentOutputsAllowed(): Boolean =
        (developmentGuidanceStartBypassEnabled && hasCameraPermission()) || (firstRunOnboardingComplete() && officialEnvironmentOutputsAllowed &&
            cameraAnalysisFeaturesEnabled() && hasCameraPermission() &&
            officialEnvironmentRuntimeGuard?.decision()?.cameraOutputsAllowed == true &&
            phoneMountingOutputsAllowed)

    private fun applyCurrentOfficialEnvironmentRuntimeAssessment() {
        if (developmentGuidanceStartBypassEnabled) return
        val guard = officialEnvironmentRuntimeGuard ?: return
        if (!walkSessionLifecycle.isRuntimeEpochCurrent(guard.epoch)) return
        val nowMs = SystemClock.elapsedRealtime()
        val assessment = currentOfficialEnvironmentAssessment(guard.epoch, nowMs)
        if (cameraAnalysisFeaturesEnabled() &&
            runtimeCameraHandoffEpoch != guard.epoch &&
            assessment.factorStatuses[OfficialEnvironmentFactor.CAMERA_QUALITY] !=
            EnvironmentEvidenceStatus.PASS
        ) {
            applyCurrentPhoneMountingRuntimeAssessment(runtimeRetryRequested = false)
        }
        applyOfficialEnvironmentRuntimeDecision(
            guard.onAssessment(
                assessment = assessment,
                nowElapsedRealtimeMs = nowMs,
            ),
        )
    }

    private fun applyOfficialEnvironmentRuntimeDecision(
        decision: kr.co.hanium.dreamup.walksafe.session.OfficialEnvironmentRuntimeDecision,
    ) {
        if (developmentGuidanceStartBypassEnabled) return
        if (!walkSessionLifecycle.isRuntimeEpochCurrent(decision.epoch)) return
        when (decision.action) {
            OfficialEnvironmentRuntimeAction.CONTINUE -> {
                officialEnvironmentOutputsAllowed = true
                val newlyUnavailable = decision.unavailableFactors -
                    lastOfficialEnvironmentUnavailableFactors
                if (newlyUnavailable.isNotEmpty()) {
                    clearExplicitReportFrameState("measured_environment_feature_limited")
                    synchronized(reportUploadSafetyLock) {
                        reportUploadSafetyGeneration += 1L
                        reportPrivacyConsentSession.cancelActiveCalls()
                    }
                }
                if (OfficialEnvironmentFactor.GPS_QUALITY in newlyUnavailable) {
                    directionGuidancePauseReason = "environment_gps_quality"
                    cancelVoiceCommandRecognition()
                    feedbackLifecycleGeneration += 1
                    feedbackPolicy.cancelPendingFeedbackDeliveries()
                    cancelPendingFeedbackTerminalResolution()
                    latestFeedbackDeliveryState = FeedbackDeliveryState()
                    feedbackActuator?.close()
                    feedbackActuator = null
                    updateStatus(
                        "위치 안내 제한",
                        "위치 품질을 확인할 수 없어 경로 방향 안내와 위치가 필요한 신고를 제한합니다. 카메라 상태가 정상이면 장애물 인식은 계속됩니다.",
                    )
                    speakStatusExplanation(
                        "위치 품질을 확인할 수 없어 경로 방향 안내를 잠시 제한합니다. 안전한 곳에서 위치가 회복될 때까지 기다리세요.",
                    )
                } else if (decision.navigationOutputsAllowed &&
                    OfficialEnvironmentFactor.GPS_QUALITY in lastOfficialEnvironmentUnavailableFactors
                ) {
                    if (directionGuidancePauseReason == "environment_gps_quality") {
                        directionGuidancePauseReason = null
                    }
                    startNavigationServicesIfNeeded()
                }
                scheduleOfficialEnvironmentRuntimeWatchdog(decision.epoch)
            }
            OfficialEnvironmentRuntimeAction.SUPPRESS_OUTPUTS_AND_RETRY -> {
                val newlySuppressed = lastOfficialEnvironmentRuntimeAction != decision.action
                officialEnvironmentOutputsAllowed = false
                clearExplicitReportFrameState("official_environment_retry")
                synchronized(reportUploadSafetyLock) {
                    reportUploadSafetyGeneration += 1L
                    reportPrivacyConsentSession.cancelActiveCalls()
                }
                latestFeedbackDeliveryState = FeedbackDeliveryState()
                feedbackPolicy.cancelPendingFeedbackDeliveries()
                if (newlySuppressed) {
                    cancelVoiceCommandRecognition()
                    feedbackLifecycleGeneration += 1
                    feedbackActuator?.close()
                    feedbackActuator = null
                    updateStatus(
                        "환경 품질 재확인 중",
                        "위치 또는 카메라 품질을 신뢰할 수 없어 경로·위험·신고 출력을 멈췄습니다. 센서를 제한된 횟수로 다시 확인합니다.",
                    )
                    speakStatusExplanation(
                        "환경 품질을 신뢰할 수 없어 보행 출력을 멈췄습니다. 휴대전화를 안정적으로 유지하고 열린 하늘이 보이는 안전한 곳에서 기다리세요.",
                    )
                }
                scheduleOfficialEnvironmentRuntimeWatchdog(decision.epoch)
            }
            OfficialEnvironmentRuntimeAction.SAFE_STOP -> {
                officialEnvironmentOutputsAllowed = false
                enterWalkSessionSafetyStopAndCancelOutputs(
                    "official_environment_quality_persisted",
                )
                val detail =
                    "위치 또는 카메라 품질 저하가 제한된 재확인 뒤에도 계속되어 모든 보행 기능을 안전 중지했습니다. 전체 상태를 다시 확인하고 새 보행을 시작하세요."
                updateStatus("공식 사용환경 이탈 · 안전 중지", detail)
                speakStatusExplanation(detail)
            }
        }
        lastOfficialEnvironmentRuntimeAction = decision.action
        lastOfficialEnvironmentUnavailableFactors = decision.unavailableFactors
    }

    private fun scheduleOfficialEnvironmentRuntimeWatchdog(epoch: WalkRuntimeEpoch) {
        val profile = activeOfficialEnvironmentProfile ?: return
        if (!walkSessionLifecycle.isRuntimeEpochCurrent(epoch)) return
        val generation = ++officialEnvironmentWatchdogGeneration
        val unavailableFactors = officialEnvironmentRuntimeGuard?.decision()?.unavailableFactors
            ?: emptySet()
        val locationRequired = postLoginDeviceFeatureEnabled(
            PostLoginDeviceCheckFeature.LOCATION_GUIDANCE,
        )
        val cameraRequired = cameraAnalysisFeaturesEnabled()
        if (!locationRequired && !cameraRequired) return
        val nowMs = SystemClock.elapsedRealtime()
        val evidenceDelayMs = if (officialEnvironmentOutputsAllowed) {
            listOfNotNull(
                officialEnvironmentGpsEvidence.takeIf { locationRequired },
                officialEnvironmentCameraEvidence.takeIf { cameraRequired },
            ).filter { evidence ->
                evidence.epoch == epoch &&
                    evidence.status == EnvironmentEvidenceStatus.PASS &&
                    evidence.factor !in unavailableFactors &&
                    evidence.observedAtElapsedRealtimeMs != null &&
                    evidence.maximumEvidenceAgeMs != null
            }.minOfOrNull { evidence ->
                val observedAtMs = checkNotNull(evidence.observedAtElapsedRealtimeMs)
                val evidenceMaximumAgeMs = checkNotNull(evidence.maximumEvidenceAgeMs)
                val effectiveMaximumAgeMs =
                    minOf(profile.maximumMeasuredEvidenceAgeMs, evidenceMaximumAgeMs)
                if (observedAtMs < 0L || nowMs < observedAtMs) {
                    1L
                } else {
                    val remainingMs = effectiveMaximumAgeMs - (nowMs - observedAtMs)
                    when {
                        remainingMs < 1L -> 1L
                        remainingMs == Long.MAX_VALUE -> Long.MAX_VALUE
                        else -> remainingMs + 1L
                    }
                }
            } ?: profile.runtimeRetryIntervalMs
        } else {
            profile.runtimeRetryIntervalMs
        }
        val qualityFailureDelayMs = listOfNotNull(
            runtimeGpsQualityGate.pendingFailureDeadlineElapsedRealtimeMs(),
            runtimeCameraQualityGate.pendingFailureDeadlineElapsedRealtimeMs(),
        ).minOfOrNull { deadlineMs -> (deadlineMs - nowMs).coerceAtLeast(1L) }
        val delayMs = minOf(
            evidenceDelayMs,
            profile.runtimeRetryIntervalMs,
            qualityFailureDelayMs ?: evidenceDelayMs,
        )
        statusText.postDelayed(
            {
                if (
                    generation == officialEnvironmentWatchdogGeneration &&
                    walkSessionLifecycle.isRuntimeEpochCurrent(epoch)
                ) {
                    applyCurrentOfficialEnvironmentRuntimeAssessment()
                }
            },
            delayMs,
        )
    }

    private fun resolveCurrentStartupCapabilityDecision(
        metricDistanceOverride: Boolean? = metricDistanceCapabilityOverride,
    ): WalkSafeStartupCapabilityDecision {
        val decision = applyPostLoginDeviceFeatureRestrictions(
            startupCapabilityProbe.decision(
                metricDistanceOverride = metricDistanceOverride,
                onDeviceSpeechRecognitionOverride = onDeviceSpeechRecognitionCapabilityOverride,
                offlineKoreanTextToSpeechOverride = offlineKoreanTextToSpeechCapabilityOverride,
                approvedDeviceProfileRequired = false,
            ),
        )
        if (developmentGuidanceStartBypassEnabled) {
            return decision.copy(
                tier = if (metricDistanceOverride == false) WalkSafeStartupCapabilityTier.LIMITED
                    else WalkSafeStartupCapabilityTier.FULL,
                unavailableRequirements = if (metricDistanceOverride == false)
                    listOf(WalkSafeStartupRequirement.METRIC_DISTANCE) else emptyList(),
                pendingRequirements = emptyList(),
                noticeKo = "개발 전용: 안내 시작 제한을 통과 처리합니다. 실제 카메라·Depth·위치 결과는 별도 점검 화면에서 확인하세요.",
            )
        }
        if (!developmentQuickStartEnabled) return decision
        val requiredCapabilityUnavailable =
            WalkSafeStartupRequirement.ANDROID_VERSION in decision.unavailableRequirements ||
                WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS in decision.unavailableRequirements
        // This grants a runtime attempt, not a successful sensor or speech measurement.
        return decision.copy(
            tier = if (requiredCapabilityUnavailable) {
                WalkSafeStartupCapabilityTier.BLOCKED
            } else {
                WalkSafeStartupCapabilityTier.LIMITED
            },
            pendingRequirements = decision.pendingRequirements.filterNot {
                it in setOf(
                    WalkSafeStartupRequirement.METRIC_DISTANCE,
                    WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS,
                    WalkSafeStartupRequirement.ON_DEVICE_STT,
                )
            },
            noticeKo = if (requiredCapabilityUnavailable) {
                decision.noticeKo
            } else {
                "개발 전용: 초기 기기 성능 점검을 생략합니다. " +
                    "환경 확인과 실제 카메라·위치·장착 판정, 사용 중 재점검은 유지합니다."
            },
        )
    }

    private fun refreshStartupCapabilityUi() {
        if (!::startupCapabilityProbe.isInitialized || !::startupCapabilityText.isInitialized) return
        val previousDecision = startupCapabilityDecision
        val decision = resolveCurrentStartupCapabilityDecision()
        val walkBeforeDecisionChange = walkSessionLifecycle.snapshot()
        val dynamicallyChangeableRequirements = setOf(
            WalkSafeStartupRequirement.CAMERA,
            WalkSafeStartupRequirement.GPS,
            WalkSafeStartupRequirement.MICROPHONE,
            WalkSafeStartupRequirement.VIBRATION,
            WalkSafeStartupRequirement.ON_DEVICE_STT,
            WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS,
            WalkSafeStartupRequirement.METRIC_DISTANCE,
        )
        val changedUnavailableRequirements = if (previousDecision == null) {
            emptySet()
        } else {
            val previousUnavailable = previousDecision.unavailableRequirements.toSet()
            val currentUnavailable = decision.unavailableRequirements.toSet()
            (previousUnavailable - currentUnavailable) +
                (currentUnavailable - previousUnavailable)
        }
        val automaticallyRebindActiveFeatureDecision =
            previousDecision != null &&
                walkBeforeDecisionChange.state == WalkSessionState.ACTIVE &&
                confirmedStartupCapabilityDecision == previousDecision &&
                decision.mayConfirmAndStart &&
                decision.pendingRequirements.isEmpty() &&
                changedUnavailableRequirements.all(dynamicallyChangeableRequirements::contains)
        startupCapabilityDecision = decision
        persistStartupCapabilityDecision(decision)
        if (confirmedStartupCapabilityDecision != decision) {
            confirmedStartupCapabilityDecision = if (
                automaticallyRebindActiveFeatureDecision
            ) {
                decision
            } else {
                null
            }
        }
        if (previousDecision != null && previousDecision != decision) {
            startupCapabilityConfirmationPending = false
            startupCapabilityRetryRequiresUserAction = false
        }
        applyRuntimeReadinessIfActive(decision)
        val confirmed = isStartupCapabilityConfirmed()
        val priorityUserDecision = priorityUserOnboardingPolicy.evaluate(
            currentPriorityUserSupportEnvironment(decision),
        )
        updateOfficialEnvironmentUi()
        val officialEnvironmentReady =
            officialEnvironmentReadiness(walkSessionLifecycle.snapshot().epoch).first ==
                WalkSessionReadinessStatus.READY
        val phoneMountingReady =
            phoneMountingReadiness(walkSessionLifecycle.snapshot().epoch).first ==
                WalkSessionReadinessStatus.READY
        val installableUnavailable = decision.unavailableRequirements
            .filter(USER_INSTALLABLE_REQUIREMENTS::contains)
        val capabilityMessage = buildString {
            append(decision.noticeKo)
            append("\n기기 점검: ")
            append(
                when (postLoginDeviceCheckSnapshot.state) {
                    PostLoginDeviceCheckState.NOT_RUN -> "시작 전"
                    PostLoginDeviceCheckState.REQUESTING_PERMISSIONS -> "권한 확인 중"
                    PostLoginDeviceCheckState.RUNNING -> "전경 점검 중"
                    PostLoginDeviceCheckState.FULL -> if (
                        hasCurrentPostLoginDeviceRestrictions()
                    ) {
                        "기기 사양 통과·현재 제한(" +
                            "${postLoginDeviceCheckDisabledFeatureText()})"
                    } else {
                        "모든 기능 통과"
                    }
                    PostLoginDeviceCheckState.LIMITED ->
                        "제한 모드 통과(${postLoginDeviceCheckDisabledFeatureText()})"
                    PostLoginDeviceCheckState.FAIL ->
                        postLoginDeviceCheckFailureMessage(postLoginDeviceCheckSnapshot.failure)
                },
            )
            append("\n")
            append(postLoginDeviceCheckItemsMessage())
            if (installableUnavailable.isNotEmpty()) {
                append("\n다음 행동: ")
                append(installableUnavailable.joinToString(", ") { it.labelKo })
                append("은(는) 아래 버튼에서 휴대폰 음성 설정을 열어 설치할 수 있습니다.")
            }
            if (confirmed) append("\n확인 완료: WalkSafe 기능을 시작할 수 있습니다.")
            append("\n${priorityUserDecision.noticeKo}")
        }
        if (startupCapabilityText.text.toString() != capabilityMessage) {
            applyWsStatusText(startupCapabilityText, capabilityMessage)
            startupCapabilityText.contentDescription = capabilityMessage
        }
        startupMetricPreflightButton.apply {
            val deviceCheckStage = firstRunOnboardingSnapshot.stage in setOf(
                FirstRunOnboardingStage.JIT_PERMISSION_OBSERVATION,
                FirstRunOnboardingStage.DEVICE_CHECK,
                FirstRunOnboardingStage.FP004_TRAINING,
                FirstRunOnboardingStage.COMPLETE,
            )
            val showDeviceCheckAction =
                currentPostLoginDeviceCheckSessionBinding() != null &&
                    deviceCheckStage &&
                    (
                        !postLoginDeviceCheckSnapshot.passesFeatureGate ||
                            deferredCameraDependentChecksCanBeRetried()
                    )
            visibility = if (showDeviceCheckAction) View.VISIBLE else View.GONE
            isEnabled = showDeviceCheckAction &&
                !storedDeviceCheckBindingValidationPending &&
                walkSessionLifecycle.snapshot().state != WalkSessionState.ACTIVE &&
                    postLoginDeviceCheckSnapshot.state !in setOf(
                        PostLoginDeviceCheckState.REQUESTING_PERMISSIONS,
                        PostLoginDeviceCheckState.RUNNING,
                    )
            text = if (storedDeviceCheckBindingValidationPending) {
                "저장된 기기 점검 결과 확인 중"
            } else if (deferredCameraDependentChecksCanBeRetried()) {
                "카메라·거리 기능 다시 점검"
            } else when (postLoginDeviceCheckSnapshot.state) {
                PostLoginDeviceCheckState.NOT_RUN -> "권한과 기기 기능 점검 시작"
                PostLoginDeviceCheckState.REQUESTING_PERMISSIONS -> "권한 확인 중"
                PostLoginDeviceCheckState.RUNNING -> "기기 기능 점검 중"
                PostLoginDeviceCheckState.FULL -> "기기 점검 완료"
                PostLoginDeviceCheckState.LIMITED -> "제한 기능을 적용하고 점검 완료"
                PostLoginDeviceCheckState.FAIL -> "기기 점검 다시 시도"
            }
            contentDescription = text
        }
        postLoginDeviceCheckSettingsButton.apply {
            val transientRestriction =
                postLoginDeviceCheckSnapshot.passesFeatureGate &&
                    (
                        requiredPostLoginDeviceCheckPermissions().isNotEmpty() ||
                            !isLocationServiceEnabledForDeviceCheck()
                    )
            visibility = if (
                transientRestriction ||
                (
                postLoginDeviceCheckSnapshot.state == PostLoginDeviceCheckState.FAIL &&
                postLoginDeviceCheckSnapshot.failure in setOf(
                    PostLoginDeviceCheckFailure.REQUIRED_PERMISSION,
                    PostLoginDeviceCheckFailure.LOCATION_SERVICE_DISABLED,
                    PostLoginDeviceCheckFailure.LOCATION_FIX_UNAVAILABLE,
                )
                )
            ) View.VISIBLE else View.GONE
            text = when {
                transientRestriction &&
                    requiredPostLoginDeviceCheckPermissions().isEmpty() &&
                    !isLocationServiceEnabledForDeviceCheck() ->
                    "Android 위치 설정 열기"
                postLoginDeviceCheckSnapshot.failure ==
                    PostLoginDeviceCheckFailure.LOCATION_SERVICE_DISABLED ->
                    "Android 위치 설정 열기"
                postLoginDeviceCheckSnapshot.failure ==
                    PostLoginDeviceCheckFailure.LOCATION_FIX_UNAVAILABLE -> when {
                    postLoginLocationFixTerminalFailure ==
                        PostLoginLocationFixTerminalFailure.REQUEST_FAILED ->
                        "Android 앱 권한 설정 열기"
                    postLoginLocationFixDecision?.reason ==
                        DeviceCheckLocationFixReason.MOCK_LOCATION ->
                        "Android 개발자 옵션 열기"
                    else -> "Android 위치 설정 열기"
                }
                postLoginDeviceCheckSnapshot.failure ==
                    PostLoginDeviceCheckFailure.KOREAN_TTS_UNAVAILABLE ->
                    "한국어 음성 데이터 설치 열기"
                else -> "Android 앱 권한 설정 열기"
            }
            contentDescription = text
        }
        voiceDataInstallButton.visibility =
            if (installableUnavailable.isEmpty()) View.GONE else View.VISIBLE
        val interactiveCheckRunning =
            postLoginDeviceCheckSnapshot.state == PostLoginDeviceCheckState.RUNNING
        val needsWakePhrase = interactiveCheckRunning &&
            postLoginWakePhraseSignal == PostLoginDeviceCheckSignal.PENDING
        postLoginDeviceCheckWakePhraseInstructionText.visibility =
            if (interactiveCheckRunning) View.VISIBLE else View.GONE
        postLoginDeviceCheckWakePhraseInstructionText.text =
            "호출어 시험을 누른 뒤 “길라잡이”라고 말해 주세요."
        postLoginDeviceCheckWakePhraseInstructionText.contentDescription =
            postLoginDeviceCheckWakePhraseInstructionText.text
        postLoginDeviceCheckWakePhraseStartButton.visibility =
            if (needsWakePhrase) View.VISIBLE else View.GONE
        postLoginDeviceCheckWakePhraseStartButton.isEnabled = needsWakePhrase &&
            handsFreeVoiceModelDirectory != null && postLoginWakePhraseProbe == null &&
            postLoginWakePhraseStartRunnable == null
        postLoginDeviceCheckWakePhraseStartButton.text = when {
            postLoginWakePhraseProbe != null -> "길라잡이 호출어 듣는 중"
            handsFreeVoiceModelDirectory == null -> "호출어 음성 모델 준비 중"
            else -> "호출어 테스트 시작"
        }
        postLoginDeviceCheckWakePhraseStartButton.contentDescription =
            postLoginDeviceCheckWakePhraseStartButton.text
        postLoginDeviceCheckHapticQuestionText.visibility = View.GONE
        postLoginDeviceCheckHapticConfirmButton.visibility = View.GONE
        postLoginDeviceCheckHapticConfirmButton.isEnabled = false
        postLoginDeviceCheckHapticRejectButton.visibility = View.GONE
        startupCapabilityConfirmButton.apply {
            val walkSession = walkSessionLifecycle.snapshot()
            val paused = walkSession.state == WalkSessionState.PAUSED
            val preparesNewWalk = walkSession.state in setOf(
                WalkSessionState.SAFE_STOP,
                WalkSessionState.ENDED,
            )
            val resumeRecheckRequired =
                paused &&
                    walkSession.recoveryStage == WalkSessionRecoveryStage.RECHECK_REQUIRED
            val awaitingExplicitResume =
                permissionRecoveryGate.state ==
                    PermissionRecoveryGateState.AWAITING_EXPLICIT_RESUME
            val mayConfirmSession = walkSession.state in setOf(
                WalkSessionState.READY,
                WalkSessionState.PAUSED,
                WalkSessionState.SAFE_STOP,
                WalkSessionState.ENDED,
            )
            val confirmationTokenReady = when {
                resumeRecheckRequired -> true
                walkSession.state in setOf(WalkSessionState.READY, WalkSessionState.PAUSED) ->
                    walkSession.confirmationToken != null
                else -> true
            }
            if (awaitingExplicitResume && !preparesNewWalk) {
                renderAwaitingExplicitResumeControl()
            } else {
                isEnabled = firstRunOnboardingComplete() &&
                    mayConfirmSession &&
                    !startupCapabilityConfirmationPending &&
                    !walkSessionResumePromptPending &&
                    (
                        preparesNewWalk ||
                            (
                                decision.mayConfirmAndStart &&
                                    (developmentQuickStartEnabled || priorityUserDecision.mayStartWalk) &&
                                    officialEnvironmentReady &&
                                    phoneMountingReady &&
                                    confirmationTokenReady &&
                                    (!confirmed || paused)
                            )
                    )
                text = when {
                    !firstRunOnboardingComplete() -> "첫 실행 등록 완료 필요"
                    preparesNewWalk -> "새 보행 준비"
                    !developmentQuickStartEnabled && !priorityUserDecision.mayStartWalk ->
                        "교육과 연습 완료 필요"
                    !officialEnvironmentReady -> "공식 사용환경 확인 필요"
                    !phoneMountingReady -> "휴대전화 장착 확인 필요"
                    resumeRecheckRequired -> "보행 재개 상태 다시 확인"
                    !confirmationTokenReady -> "보행 준비 확인 중"
                    paused && walkSessionResumePromptPending -> "보행 재개 음성 확인 중"
                    paused -> "보행 안내 재개 확인"
                    startupCapabilityRetryRequiresUserAction -> "보행 시작 다시 시도"
                    confirmed && decision.tier == WalkSafeStartupCapabilityTier.FULL -> "목적과 안전 제한 확인 완료"
                    confirmed -> "기능 제한 확인 완료"
                    startupCapabilityConfirmationPending -> "안전 제한 음성 안내 중"
                    decision.tier == WalkSafeStartupCapabilityTier.FULL -> "목적과 안전 제한 확인 후 계속"
                    decision.tier == WalkSafeStartupCapabilityTier.LIMITED -> "기능 제한 확인 후 계속"
                    decision.pendingRequirements.isNotEmpty() -> "기기 기능 확인 중"
                    else -> "이 휴대폰에서 시작할 수 없음"
                }
            }
        }
        updatePrewalkGuidance(
            epoch = walkSessionLifecycle.snapshot().epoch,
            officialEnvironmentReady = officialEnvironmentReady,
            phoneMountingReady = phoneMountingReady,
        )
        updatePriorityUserOnboardingUi(decision)
        updateFirstRunOnboardingUi()
        updatePhoneMountingUi()
        updateFieldSessionLogButton()
        applyActionButtonState()
        maybeAdvanceWalkSessionAfterCapabilityCheck()
    }

    private fun applyRuntimeReadinessIfActive(
        decision: WalkSafeStartupCapabilityDecision,
    ) {
        if (applyingRuntimeReadiness) return
        val current = walkSessionLifecycle.snapshot()
        if (current.state != WalkSessionState.ACTIVE) return
        applyingRuntimeReadiness = true
        try {
            val readiness = captureWalkSessionReadiness(
                decision = decision,
                action = WalkSessionAction.START_WALK,
            )
            val transition = transitionWalkSession(
                WalkSessionEvent.RuntimeReadinessChanged(readiness),
            )
            if (
                transition.previous.state == WalkSessionState.ACTIVE &&
                transition.current.state == WalkSessionState.SAFE_STOP
            ) {
                persistWalkSessionInterruptionMarker()
                walkSessionResumePromptPending = false
                walkSessionResumeRetryRequiresUserAction = false
                walkSessionResumeConfirmationToken = null
                invalidateOfficialEnvironmentEvidence("runtime_readiness_changed")
                invalidatePhoneMountingEvidence("runtime_readiness_changed")
                cancelWalkSessionOutputs("runtime_readiness_changed")
                stopCameraFallbackSession(updateUi = false)
                stopDepthSession(closeSession = true)
                val reason = readiness.blockingReasons.joinToString(", ").ifBlank {
                    "필수 기능 상태가 바뀌어 새 보행 준비가 필요합니다."
                }
                updateStatus("필수 기능 변경 · 안전 중지", reason)
                speakInteraction(
                    "보행 기능을 안전 중지했습니다. $reason",
                )
            }
        } finally {
            applyingRuntimeReadiness = false
        }
    }

    private fun currentRawCollectionRuntimeContextOrNull(): RawCollectionRuntimeContext? {
        if (
            !::rawCollectionRuntimeCoordinator.isInitialized ||
            !::walkSessionLifecycle.isInitialized
        ) return null
        val gateway = GatewaySessionProcessCoordinator.snapshot()
        val walk = walkSessionLifecycle.snapshot()
        val session = gateway.session?.takeUnless {
            gateway.storageBlocked ||
                gateway.deletionRecoveryOnly ||
                accountDeletionStateMachine.processingBlocked()
        }
        val transport = if (::networkStateProbe.isInitialized) {
            networkStateProbe.currentTransport()
        } else {
            ActiveNetworkTransport.OFFLINE
        }
        return RawCollectionRuntimeContext(
            session = session,
            sessionGeneration = gateway.generation,
            deviceCheck = postLoginDeviceCheckSnapshot,
            consentSession = integratedConsentSession,
            walk = walk,
            gatewayWalkLease = session?.let {
                gatewayWalkAuthorityController.activeLeaseOrNull(walk.epoch)
            },
            networkTransport = transport,
            networkBinding = if (::networkStateProbe.isInitialized) {
                networkStateProbe.currentIntegratedConsentBinding()
            } else {
                null
            },
        )
    }

    private fun executeRawCollectionTask(task: () -> Unit) {
        if (
            !::rawCollectionRuntimeCoordinator.isInitialized ||
            rawCollectionExecutor.isShutdown
        ) return
        try {
            rawCollectionExecutor.execute(task)
        } catch (_: RejectedExecutionException) {
            Unit
        }
    }

    private fun clearRawDetectionWindow(clearPendingDropCount: Boolean = true) {
        rawDetectionWindowWalkId = null
        rawDetectionWindowStartedAtElapsedMs = 0L
        rawDetectionProcessedFrameCount = 0
        rawDetectionDroppedFrameCount = 0
        rawDetectionCount = 0
        rawDetectionInferenceTotalMs = 0L
        rawDetectionModelRevision = null
        if (clearPendingDropCount) {
            rawDetectionDueButInFlightDropCount.set(0)
        }
    }

    private fun recordRawCollectionDetectionMetadata(
        expectedWalkEpoch: WalkRuntimeEpoch,
        detectionCount: Int,
        inferenceMs: Long,
        modelRevision: String?,
    ) {
        val observedAtEpochMs = System.currentTimeMillis()
        val observedAtElapsedMs = SystemClock.elapsedRealtime()
        val detectorWasAvailable = detectorAvailable
        val dueButInFlightDropCount = rawDetectionDueButInFlightDropCount.getAndSet(0)
        executeRawCollectionTask {
            val context = currentRawCollectionRuntimeContextOrNull()
            if (
                context == null ||
                context.walk.state != WalkSessionState.ACTIVE ||
                context.walk.epoch != expectedWalkEpoch
            ) {
                clearRawDetectionWindow()
                return@executeRawCollectionTask
            }
            if (rawDetectionWindowWalkId != expectedWalkEpoch.walkSessionId) {
                clearRawDetectionWindow(clearPendingDropCount = false)
                rawDetectionWindowWalkId = expectedWalkEpoch.walkSessionId
                rawDetectionWindowStartedAtElapsedMs = observedAtElapsedMs
            }
            rawDetectionProcessedFrameCount += 1
            rawDetectionDroppedFrameCount += dueButInFlightDropCount
            rawDetectionCount += detectionCount.coerceAtLeast(0)
            rawDetectionInferenceTotalMs += inferenceMs.coerceAtLeast(0L)
            rawDetectionModelRevision = modelRevision?.takeIf {
                RAW_COLLECTION_MODEL_REVISION.matches(it)
            }
            val elapsedWindowMs =
                observedAtElapsedMs - rawDetectionWindowStartedAtElapsedMs
            if (elapsedWindowMs < RAW_COLLECTION_CAPTURE_INTERVAL_MS) {
                return@executeRawCollectionTask
            }
            val capturedWindowStartedAtEpochMs =
                (observedAtEpochMs - elapsedWindowMs).coerceAtLeast(0L)
            val processedFrames = rawDetectionProcessedFrameCount
            val averageProcessingFrameMs = if (processedFrames == 0) {
                0L
            } else {
                rawDetectionInferenceTotalMs / processedFrames
            }
            val detectionSample = RawDetectionMetadataSample(
                windowStartedAtEpochMs = capturedWindowStartedAtEpochMs,
                capturedAtEpochMs = observedAtEpochMs,
                processedFrameCount = processedFrames,
                detectionCount = rawDetectionCount,
                averageInferenceMs = averageProcessingFrameMs,
                detectorAvailable = detectorWasAvailable,
                modelRevision = rawDetectionModelRevision,
            )
            val performanceSample = RawPerformanceMetadataSample(
                windowStartedAtEpochMs = capturedWindowStartedAtEpochMs,
                capturedAtEpochMs = observedAtEpochMs,
                processedFrameCount = processedFrames,
                droppedFrameCount = rawDetectionDroppedFrameCount,
                averageFrameDurationMs = averageProcessingFrameMs,
                thermalThrottled = if (::walkSessionResourceProbe.isInitialized) {
                    runCatching {
                        walkSessionResourceProbe.snapshot().thermalThrottled
                    }.getOrNull()
                } else {
                    null
                },
            )
            clearRawDetectionWindow(clearPendingDropCount = false)
            rawCollectionRuntimeCoordinator.captureMetadataBatch(
                context,
                detectionSample,
                performanceSample,
            )
        }
    }

    private fun revalidateRawCollectionRuntime() {
        if (!::rawCollectionRuntimeCoordinator.isInitialized) return
        val context = currentRawCollectionRuntimeContextOrNull()
        if (context == null) {
            rawCollectionRuntimeCoordinator.cancelActiveUpload()
        } else {
            rawCollectionRuntimeCoordinator.revalidate(context)
        }
    }

    private fun scheduleRawCollectionPausedUpload() {
        executeRawCollectionTask {
            val initial = currentRawCollectionRuntimeContextOrNull()
                ?: return@executeRawCollectionTask
            rawCollectionRuntimeCoordinator.revalidate(initial)
            if (
                initial.walk.state != WalkSessionState.PAUSED ||
                initial.walk.recoveryStage != WalkSessionRecoveryStage.RECHECK_REQUIRED ||
                rawCollectionUploadWalkId != initial.walk.epoch.walkSessionId ||
                initial.networkTransport != ActiveNetworkTransport.WIFI ||
                initial.networkBinding?.transport != IntegratedConsentNetworkTransport.WIFI ||
                initial.gatewayWalkLease == null
            ) return@executeRawCollectionTask
            rawCollectionRuntimeCoordinator.sealActiveSegment(initial)
            while (true) {
                val fallback = currentRawCollectionRuntimeContextOrNull()
                    ?: return@executeRawCollectionTask
                val call = rawCollectionRuntimeCoordinator.startNextUpload {
                    currentRawCollectionRuntimeContextOrNull()
                        ?: fallback.copy(session = null, gatewayWalkLease = null)
                } ?: run {
                    rawCollectionUploadWalkId = null
                    return@executeRawCollectionTask
                }
                val completed = runCatching { call.execute() }.getOrNull()
                if (
                    completed != RawCollectionUploadOutcome.DELETED_AFTER_EXACT_RECEIPT
                ) return@executeRawCollectionTask
            }
        }
    }

    private fun handleRawCollectionTransition(
        transition: WalkSessionTransition,
        event: WalkSessionEvent,
    ) {
        if (!transition.changed || !::rawCollectionRuntimeCoordinator.isInitialized) return
        revalidateRawCollectionRuntime()
        when {
            transition.current.state == WalkSessionState.ENDED -> {
                rawCollectionUploadWalkId = null
                rawCollectionRuntimeCoordinator.cancelActiveUpload()
                executeRawCollectionTask {
                    val context = currentRawCollectionRuntimeContextOrNull()
                        ?: return@executeRawCollectionTask
                    rawCollectionRuntimeCoordinator.onWalkEnded(context)
                    rawCollectionRuntimeCoordinator.discardEndedPartials(context)
                    clearRawDetectionWindow()
                }
            }
            transition.current.state == WalkSessionState.PAUSED &&
                transition.current.recoveryStage ==
                WalkSessionRecoveryStage.RECHECK_REQUIRED &&
                event == WalkSessionEvent.RecheckRequested -> {
                rawCollectionUploadWalkId = transition.current.epoch.walkSessionId
                scheduleRawCollectionPausedUpload()
            }
            transition.current.state != WalkSessionState.PAUSED -> {
                rawCollectionUploadWalkId = null
                executeRawCollectionTask(::clearRawDetectionWindow)
            }
        }
    }

    private fun handleWalkSessionForegroundReturn() {
        if (!::walkSessionLifecycle.isInitialized) return
        transitionWalkSession(WalkSessionEvent.EnteredForeground)
        if (::fieldSessionLog.isInitialized) {
            val snapshot = walkSessionLifecycle.snapshot()
            fieldSessionLog.recordEvent(
                "walk_session_foreground_returned",
                mapOf(
                    "state" to snapshot.state.name,
                    "recovery_stage" to (snapshot.recoveryStage?.name ?: "none"),
                ),
            )
        }
    }

    private fun transitionWalkSession(event: WalkSessionEvent): kr.co.hanium.dreamup.walksafe.session.WalkSessionTransition {
        val before = walkSessionLifecycle.snapshot()
        val reportQueueDrainCandidate =
            captureReportQueueDrainTriggerBeforeTransition(before, event)
        val gatewaySessionForEnd = if (event == WalkSessionEvent.EndRequested) {
            gatewayFieldSession
        } else {
            null
        }
        val endOperation = if (event == WalkSessionEvent.EndRequested) {
            gatewayWalkAuthorityController.beginEnd(before.epoch)
        } else {
            null
        }
        val transition = walkSessionLifecycle.handle(event)
        if (transition.current.state !in setOf(WalkSessionState.READY, WalkSessionState.ENDED)) {
            cancelDeviceRuntimeCalibration("walk_transition")
        }
        if (
            transition.changed &&
            (
                transition.previous.epoch != transition.current.epoch ||
                    transition.current.state != WalkSessionState.ACTIVE
            )
        ) {
            stopHandsFreeVoiceService()
            invalidatePendingExplicitReport()
        }
        updateReportQueueDrainForTransition(transition)
        if (
            transition.changed &&
            transition.previous.state != transition.current.state &&
            (
                transition.previous.state == WalkSessionState.ACTIVE ||
                    transition.current.state == WalkSessionState.ACTIVE
            )
        ) {
            activityOriginalUploadAdmission.onSessionActiveChanged(
                active = transition.current.state == WalkSessionState.ACTIVE,
                observedAtMs = SystemClock.elapsedRealtime(),
                cancelActiveUploads = ::cancelActivityOriginalUploads,
            )
        }
        if (
            transition.changed &&
            transition.current.state == WalkSessionState.PAUSED &&
            transition.previous.epoch != transition.current.epoch
        ) {
            gatewayWalkAuthorityController.rebindEpoch(
                transition.previous.epoch,
                transition.current.epoch,
            )
            scheduleGatewayWalkRenewal()
        }
        if (
            transition.changed &&
            transition.current.state == WalkSessionState.SAFE_STOP
        ) {
            gatewayWalkRenewalHandler.removeCallbacks(gatewayWalkRenewalRunnable)
            gatewayWalkAuthorityController.invalidate(transition.previous.epoch)
            gatewayWalkResumeRevalidationPending = false
        }
        if (transition.changed && ::fieldSessionLog.isInitialized) {
            fieldSessionLog.recordEvent(
                "walk_session_transition",
                mapOf(
                    "walk_session_id" to transition.current.epoch.walkSessionId,
                    "recovery_generation" to transition.current.epoch.recoveryGeneration,
                    "previous_state" to transition.previous.state.name,
                    "current_state" to transition.current.state.name,
                    "previous_mode" to transition.previous.mode.name,
                    "current_mode" to transition.current.mode.name,
                    "reason" to transition.reason.name,
                    "occurred_at_epoch_ms" to transition.occurredAtEpochMs,
                ),
            )
        }
        handleRawCollectionTransition(transition, event)
        if (endOperation != null && gatewaySessionForEnd != null) {
            gatewayWalkRenewalHandler.removeCallbacks(gatewayWalkRenewalRunnable)
            endGatewayWalkBestEffort(gatewaySessionForEnd, endOperation)
        }
        startReportQueueDrainAfterTransition(reportQueueDrainCandidate, transition, event)
        maybeStartPausedReportQueueRecoveryObservation()
        return transition
    }

    private fun captureReportQueueDrainTriggerBeforeTransition(
        before: WalkSessionSnapshot,
        event: WalkSessionEvent,
    ): ReportQueueDrainTrigger? {
        if (
            before.state != WalkSessionState.ACTIVE ||
            event != WalkSessionEvent.RecheckRequested ||
            !isActivityForeground ||
            !::networkStateProbe.isInitialized ||
            !reportPrivacyConsentSession.isGranted()
        ) {
            return null
        }
        val stationarySnapshot = activityOriginalUploadAdmission.stationarySnapshot(
            SystemClock.elapsedRealtime(),
        ) ?: return null
        return buildReportQueueDrainTrigger(
            walkSessionId = before.epoch.walkSessionId,
            stationarySnapshot = stationarySnapshot,
        )
    }

    private fun buildReportQueueDrainTrigger(
        walkSessionId: String,
        stationarySnapshot: ActivityOriginalStationarySnapshot,
    ): ReportQueueDrainTrigger? {
        if (
            !isActivityForeground ||
            !::networkStateProbe.isInitialized ||
            !reportPrivacyConsentSession.isGranted()
        ) return null
        val consentConfirmation =
            integratedConsentSession.currentConfirmationOrNull() ?: return null
        val reporter = currentReporterUserId() ?: return null
        val gatewaySnapshot = GatewaySessionProcessCoordinator.snapshot()
        val gatewaySession = gatewaySnapshot.session ?: return null
        if (
            gatewaySnapshot.storageBlocked ||
            gatewaySnapshot.deletionRecoveryOnly ||
            gatewaySession.sessionScope != GatewaySessionScope.GENERAL ||
            !gatewaySession.isUsableFor(reporter) ||
            approvedReportQueueGatewayOriginOrNull(gatewaySession.gatewayBaseUrl) !=
            gatewaySession.gatewayBaseUrl
        ) {
            return null
        }
        val networkTransport = networkStateProbe.currentTransport()
        val networkPreference = permissionSessionPolicy.snapshot().mobileNetworkPreference
        if (!AndroidNetworkTransferPolicy.isAllowed(networkPreference, networkTransport)) {
            return null
        }
        val networkBinding = networkStateProbe.currentIntegratedConsentBinding() ?: return null
        if (!networkBinding.matches(networkTransport)) return null
        val generations = synchronized(reportQueueDrainLock) {
            if (reportQueueDrainTrigger != null) return@synchronized null
            reportQueueDrainMovementGeneration to reportQueueDrainNetworkGeneration
        } ?: return null
        return ReportQueueDrainTrigger(
            reporterActorId = reporter,
            walkSessionId = walkSessionId,
            stationarySnapshot = stationarySnapshot,
            consentConfirmation = consentConfirmation,
            gatewaySession = gatewaySession,
            gatewaySessionGeneration = gatewaySnapshot.generation,
            networkBinding = networkBinding,
            networkTransport = networkTransport,
            networkGeneration = generations.second,
            movementGeneration = generations.first,
        )
    }

    private fun updateReportQueueDrainForTransition(
        transition: WalkSessionTransition,
    ) {
        val cancelActiveDrain = synchronized(reportQueueDrainLock) {
            reportQueueDrainWalkState = transition.current.state
            reportQueueDrainWalkSessionId = transition.current.epoch.walkSessionId
            if (
                reportQueuePausedRecoveryObservationActive &&
                transition.current.state != WalkSessionState.PAUSED
            ) {
                reportQueuePausedRecoveryObservationActive = false
                reportQueuePausedRecoveryObservationGeneration += 1L
                reportQueuePausedRecoveryStationaryCheckScheduled = false
                reportQueuePausedRecoveryMotionEvidence.reset()
            }
            val active = reportQueueDrainTrigger
            if (
                active != null &&
                (
                    transition.current.state != WalkSessionState.PAUSED ||
                        transition.current.epoch.walkSessionId != active.walkSessionId
                )
            ) {
                reportQueueDrainTrigger = null
                reportQueueDrainMovementGeneration += 1L
                true
            } else {
                false
            }
        }
        if (cancelActiveDrain) {
            reportQueueDrainCoordinator.cancelActive()
            stopStepTrackingNow()
        }
    }

    private fun startReportQueueDrainAfterTransition(
        trigger: ReportQueueDrainTrigger?,
        transition: WalkSessionTransition,
        event: WalkSessionEvent,
    ) {
        if (
            trigger == null ||
            transition.previous.state != WalkSessionState.ACTIVE ||
            event != WalkSessionEvent.RecheckRequested ||
            transition.current.state != WalkSessionState.PAUSED ||
            transition.current.recoveryStage != WalkSessionRecoveryStage.RECHECK_REQUIRED ||
            transition.current.epoch.walkSessionId != trigger.walkSessionId
        ) {
            return
        }
        startBoundedReportQueueDrain(trigger)
    }

    private fun startBoundedReportQueueDrain(trigger: ReportQueueDrainTrigger): Boolean {
        val initialCount = reportQueueStore.countForRecoveryDrain(trigger.reporterActorId)
        if (initialCount <= 0) return false
        val installed = synchronized(reportQueueDrainLock) {
            if (
                reportQueueDrainTrigger != null ||
                reportQueueDrainMovementGeneration != trigger.movementGeneration ||
                reportQueueDrainNetworkGeneration != trigger.networkGeneration ||
                reportQueueDrainWalkState != WalkSessionState.PAUSED ||
                reportQueueDrainWalkSessionId != trigger.walkSessionId
            ) {
                false
            } else {
                reportQueueDrainTrigger = trigger
                stepTrackingEpoch = null
                true
            }
        }
        if (!installed) return false
        if (!reportQueueDrainContext(trigger).allRequiredBaseGatesAllowed()) {
            cancelReportQueueDrain()
            return false
        }
        return try {
            reportQueueDrainExecutor.execute {
                drainInitialExactReportQueue(trigger, initialCount)
            }
            true
        } catch (_: RejectedExecutionException) {
            cancelReportQueueDrain()
            false
        }
    }

    private fun maybeStartPausedReportQueueRecoveryObservation() {
        if (Looper.myLooper() != Looper.getMainLooper()) {
            runOnUiThread(::maybeStartPausedReportQueueRecoveryObservation)
            return
        }
        if (
            !isActivityForeground ||
            !::walkSessionLifecycle.isInitialized ||
            !::stepTracker.isInitialized ||
            !hasActivityRecognitionPermission()
        ) return
        val walk = walkSessionLifecycle.snapshot()
        if (
            walk.state != WalkSessionState.PAUSED ||
            !walk.isForeground ||
            !reportQueueRecoveryBaseGatesAvailable()
        ) return
        val reporter = currentReporterUserId() ?: return
        if (reportQueueStore.countForRecoveryDrain(reporter) <= 0) return
        val started = synchronized(reportQueueDrainLock) {
            if (
                reportQueueDrainTrigger != null ||
                reportQueuePausedRecoveryObservationActive
            ) {
                false
            } else {
                reportQueueDrainWalkState = walk.state
                reportQueueDrainWalkSessionId = walk.epoch.walkSessionId
                reportQueuePausedRecoveryObservationActive = true
                reportQueuePausedRecoveryObservationGeneration += 1L
                reportQueuePausedRecoveryStationaryCheckScheduled = false
                reportQueuePausedRecoveryMotionEvidence.beginObservation()
                true
            }
        }
        if (!started) return
        stepTrackingEpoch = null
        stepTracker.start()
    }

    private fun reportQueueRecoveryBaseGatesAvailable(): Boolean {
        if (
            PRODUCTION_REPORT_QUEUE_CAPACITY_PROFILE == null ||
            !reportPrivacyConsentSession.isGranted() ||
            !::networkStateProbe.isInitialized
        ) return false
        val reporter = currentReporterUserId() ?: return false
        val confirmation = integratedConsentSession.currentConfirmationOrNull() ?: return false
        val gateway = GatewaySessionProcessCoordinator.snapshot()
        val session = gateway.session ?: return false
        if (
            gateway.storageBlocked ||
            gateway.deletionRecoveryOnly ||
            session.sessionScope != GatewaySessionScope.GENERAL ||
            !session.isUsableFor(reporter) ||
            approvedReportQueueGatewayOriginOrNull(session.gatewayBaseUrl) !=
            session.gatewayBaseUrl
        ) return false
        val transport = networkStateProbe.currentTransport()
        val binding = networkStateProbe.currentIntegratedConsentBinding() ?: return false
        return binding.matches(transport) &&
            AndroidNetworkTransferPolicy.isAllowed(
                permissionSessionPolicy.snapshot().mobileNetworkPreference,
                transport,
            ) &&
            confirmation.backendConsentReceiptSha256.isNotEmpty()
    }

    private fun onPausedReportQueueRecoveryMotionSample(
        stepCount: Int,
        observedAtMs: Long,
    ) {
        val active = synchronized(reportQueueDrainLock) {
            reportQueuePausedRecoveryObservationActive
        }
        if (!active) return
        reportQueuePausedRecoveryMotionEvidence.observeStepCount(stepCount, observedAtMs)
        schedulePausedReportQueueRecoveryStationaryCheck()
    }

    private fun schedulePausedReportQueueRecoveryStationaryCheck() {
        val generation = synchronized(reportQueueDrainLock) {
            if (
                !reportQueuePausedRecoveryObservationActive ||
                reportQueuePausedRecoveryStationaryCheckScheduled
            ) {
                null
            } else {
                reportQueuePausedRecoveryStationaryCheckScheduled = true
                reportQueuePausedRecoveryObservationGeneration
            }
        } ?: return
        reportCleanupCallbackHandler.postDelayed(
            {
                val current = synchronized(reportQueueDrainLock) {
                    val matches =
                        reportQueuePausedRecoveryObservationActive &&
                            reportQueuePausedRecoveryObservationGeneration == generation
                    if (matches) reportQueuePausedRecoveryStationaryCheckScheduled = false
                    matches
                }
                if (!current) return@postDelayed
                val stationary = reportQueuePausedRecoveryMotionEvidence.stationarySnapshotAt(
                    SystemClock.elapsedRealtime(),
                )
                if (stationary == null) {
                    schedulePausedReportQueueRecoveryStationaryCheck()
                    return@postDelayed
                }
                startPausedReportQueueRecoveryIfCurrent(generation, stationary)
            },
            REPORT_QUEUE_PAUSED_STATIONARY_RECHECK_MS,
        )
    }

    private fun startPausedReportQueueRecoveryIfCurrent(
        observationGeneration: Long,
        stationarySnapshot: ActivityOriginalStationarySnapshot,
    ) {
        val walk = walkSessionLifecycle.snapshot()
        if (
            !isActivityForeground ||
            walk.state != WalkSessionState.PAUSED ||
            !walk.isForeground
        ) {
            cancelPausedReportQueueRecoveryObservation()
            return
        }
        val trigger = buildReportQueueDrainTrigger(
            walkSessionId = walk.epoch.walkSessionId,
            stationarySnapshot = stationarySnapshot,
        )
        if (trigger == null) {
            schedulePausedReportQueueRecoveryStationaryCheck()
            return
        }
        val claimed = synchronized(reportQueueDrainLock) {
            if (
                !reportQueuePausedRecoveryObservationActive ||
                reportQueuePausedRecoveryObservationGeneration != observationGeneration ||
                reportQueueDrainTrigger != null
            ) {
                false
            } else {
                reportQueuePausedRecoveryObservationActive = false
                reportQueuePausedRecoveryObservationGeneration += 1L
                reportQueuePausedRecoveryStationaryCheckScheduled = false
                reportQueuePausedRecoveryMotionEvidence.reset()
                true
            }
        }
        if (!claimed) return
        if (!startBoundedReportQueueDrain(trigger)) stopStepTrackingNow()
    }

    private fun cancelPausedReportQueueRecoveryObservation(): Boolean =
        synchronized(reportQueueDrainLock) {
            if (!reportQueuePausedRecoveryObservationActive) {
                false
            } else {
                reportQueuePausedRecoveryObservationActive = false
                reportQueuePausedRecoveryObservationGeneration += 1L
                reportQueuePausedRecoveryStationaryCheckScheduled = false
                reportQueuePausedRecoveryMotionEvidence.reset()
                true
            }
        }

    private fun IntegratedConsentNetworkBinding.matches(
        transport: ActiveNetworkTransport,
    ): Boolean = when (transport) {
        ActiveNetworkTransport.WIFI ->
            this.transport == IntegratedConsentNetworkTransport.WIFI
        ActiveNetworkTransport.CELLULAR ->
            this.transport == IntegratedConsentNetworkTransport.CELLULAR
        ActiveNetworkTransport.OFFLINE,
        ActiveNetworkTransport.OTHER,
        -> false
    }

    private fun reportQueueDrainContext(
        trigger: ReportQueueDrainTrigger,
    ): ReportQueueDrainContext {
        val runtime = synchronized(reportQueueDrainLock) {
            ReportQueueDrainRuntimeSnapshot(
                triggerCurrent = reportQueueDrainTrigger === trigger,
                walkState = reportQueueDrainWalkState,
                walkSessionId = reportQueueDrainWalkSessionId,
                movementGeneration = reportQueueDrainMovementGeneration,
                networkGeneration = reportQueueDrainNetworkGeneration,
            )
        }
        val currentConfirmation = integratedConsentSession.currentConfirmationOrNull()
        val consentAllowed =
            runtime.triggerCurrent &&
                reportPrivacyConsentSession.isGranted() &&
                currentConfirmation == trigger.consentConfirmation
        val currentGateway = GatewaySessionProcessCoordinator.snapshot()
        val reporter = currentReporterUserId()
        val authorityAllowed =
            runtime.triggerCurrent &&
                reporter == trigger.reporterActorId &&
                currentGateway.generation == trigger.gatewaySessionGeneration &&
                currentGateway.session === trigger.gatewaySession &&
                !currentGateway.storageBlocked &&
                !currentGateway.deletionRecoveryOnly &&
                trigger.gatewaySession.sessionScope == GatewaySessionScope.GENERAL &&
                trigger.gatewaySession.isUsableFor(reporter)
        val currentTransport = if (::networkStateProbe.isInitialized) {
            networkStateProbe.currentTransport()
        } else {
            ActiveNetworkTransport.OFFLINE
        }
        val currentBinding = if (::networkStateProbe.isInitialized) {
            networkStateProbe.currentIntegratedConsentBinding()
        } else {
            null
        }
        val preference = permissionSessionPolicy.snapshot().mobileNetworkPreference
        val networkAllowed =
            runtime.triggerCurrent &&
                runtime.networkGeneration == trigger.networkGeneration &&
                currentTransport == trigger.networkTransport &&
                currentBinding != null &&
                currentBinding.matches(currentTransport) &&
                trigger.networkBinding.isSameNetworkBinding(currentBinding) &&
                AndroidNetworkTransferPolicy.isAllowed(preference, currentTransport)
        return ReportQueueDrainContext(
            walkState = runtime.walkState ?: WalkSessionState.ACTIVE,
            appForeground = runtime.triggerCurrent && isActivityForeground,
            stationary =
                runtime.triggerCurrent &&
                    runtime.movementGeneration == trigger.movementGeneration,
            networkAllowed = networkAllowed,
            consentAllowed = consentAllowed,
            automaticReportingAllowed =
                consentAllowed &&
                    currentConfirmation?.selections?.automaticReporting == true,
            authorityAllowed = authorityAllowed,
            reporterActorId = reporter.orEmpty(),
            walkSessionId = runtime.walkSessionId.orEmpty(),
            consentReceiptSha256 =
                currentConfirmation?.backendConsentReceiptSha256.orEmpty(),
            movementGeneration = runtime.movementGeneration,
        )
    }

    private data class ReportQueueDrainRuntimeSnapshot(
        val triggerCurrent: Boolean,
        val walkState: WalkSessionState?,
        val walkSessionId: String?,
        val movementGeneration: Long,
        val networkGeneration: Long,
    )

    private fun ReportQueueDrainContext.allRequiredBaseGatesAllowed(): Boolean =
        walkState == WalkSessionState.PAUSED &&
            appForeground &&
            stationary &&
            networkAllowed &&
            consentAllowed &&
            authorityAllowed

    private fun drainInitialExactReportQueue(
        trigger: ReportQueueDrainTrigger,
        initialCount: Int,
    ) {
        val transport = AndroidReportQueueTransport(
            uploader = AndroidReportUploader(),
            session = trigger.gatewaySession,
            consentConfirmation = trigger.consentConfirmation,
            networkBinding = trigger.networkBinding,
            permitProvider = reportPrivacyConsentSession::issueUploadPermit,
        )
        var remaining = initialCount
        try {
            while (remaining > 0) {
                val context = reportQueueDrainContext(trigger)
                if (!context.allRequiredBaseGatesAllowed()) break
                val call = reportQueueDrainCoordinator.startNext(
                    contextProvider = { reportQueueDrainContext(trigger) },
                    transport = transport,
                    beforeDeleteAfterReceipt =
                        ::persistAutomaticReportCooldownBeforeQueueDelete,
                ) ?: break
                val outcome = try {
                    call.execute()
                } catch (_: Exception) {
                    break
                }
                if (
                    outcome != ReportQueueDrainOutcome.DELETED_AFTER_STATUS &&
                    outcome != ReportQueueDrainOutcome.DELETED_AFTER_UPLOAD
                ) {
                    break
                }
                remaining -= 1
            }
        } finally {
            finishReportQueueDrain(trigger)
        }
    }

    private fun persistAutomaticReportCooldownBeforeQueueDelete(
        report: QueuedReport,
    ): Boolean {
        if (report.priority != ReportQueuePriority.AUTOMATIC) return true
        val scope = report.automaticCooldownScopeOrNull() ?: return false
        val nowMs = System.currentTimeMillis()
        val admission = reportAttemptStore.acquire(
            scope = scope,
            nowMs = nowMs,
            bypassAutomaticCooldown = true,
        ) as? AndroidReportAttemptResult.Allowed ?: return false
        return try {
            if (
                !persistReportCooldownForSuccess(
                    AndroidReportSuccessfulCooldown(scope, nowMs),
                )
            ) {
                false
            } else {
                reportAttemptStore.markSucceeded(admission.lease, nowMs)
                true
            }
        } finally {
            reportAttemptStore.release(admission.lease)
        }
    }

    private fun finishReportQueueDrain(trigger: ReportQueueDrainTrigger) {
        val finished = synchronized(reportQueueDrainLock) {
            if (reportQueueDrainTrigger !== trigger) {
                false
            } else {
                reportQueueDrainTrigger = null
                reportQueueDrainMovementGeneration += 1L
                true
            }
        }
        if (finished) {
            reportQueueDrainCoordinator.cancelActive()
            stopStepTrackingNow()
        }
    }

    private fun cancelReportQueueDrain() {
        val observationCancelled = cancelPausedReportQueueRecoveryObservation()
        val cancelled = synchronized(reportQueueDrainLock) {
            if (reportQueueDrainTrigger == null) {
                false
            } else {
                reportQueueDrainTrigger = null
                reportQueueDrainMovementGeneration += 1L
                stepTrackingEpoch = null
                true
            }
        }
        if (cancelled) {
            reportQueueDrainCoordinator.cancelActive()
        }
        if (cancelled || observationCancelled) {
            stopStepTrackingNow()
        }
    }

    private fun onReportQueueDrainNetworkChanged() {
        if (::rawCollectionRuntimeCoordinator.isInitialized) {
            rawCollectionRuntimeCoordinator.cancelActiveUpload()
            revalidateRawCollectionRuntime()
            scheduleRawCollectionPausedUpload()
        }
        val observationCancelled = cancelPausedReportQueueRecoveryObservation()
        val cancelled = synchronized(reportQueueDrainLock) {
            reportQueueDrainNetworkGeneration += 1L
            if (reportQueueDrainTrigger == null) {
                false
            } else {
                reportQueueDrainTrigger = null
                reportQueueDrainMovementGeneration += 1L
                stepTrackingEpoch = null
                true
            }
        }
        if (cancelled) {
            reportQueueDrainCoordinator.cancelActive()
        }
        if (cancelled || observationCancelled) {
            stopStepTrackingNow()
        }
        maybeStartPausedReportQueueRecoveryObservation()
    }

    private fun onReportQueueDrainStepSample(
        stepCount: Int,
        observedAtMs: Long,
    ) {
        val movementDetected = synchronized(reportQueueDrainLock) {
            val trigger = reportQueueDrainTrigger ?: return@synchronized false
            if (
                stepCount == trigger.stationarySnapshot.stepCount &&
                observedAtMs >= trigger.stationarySnapshot.observedAtMs
            ) {
                false
            } else {
                reportQueueDrainTrigger = null
                reportQueueDrainMovementGeneration += 1L
                stepTrackingEpoch = null
                true
            }
        }
        if (movementDetected) {
            reportQueueDrainCoordinator.cancelActive()
            stopStepTrackingNow()
        }
    }

    private fun maybeAdvanceWalkSessionAfterCapabilityCheck() {
        if (gatewayWalkStartConfirmationToken != null) return
        if (permissionRecoveryGate.blocksAutomaticResourceStart && !developmentGuidanceStartBypassEnabled) {
            completePermissionRecoveryRecheckIfPossible()
            if (permissionRecoveryGate.blocksAutomaticResourceStart) return
        }
        if (
            !::walkSessionLifecycle.isInitialized ||
            !isActivityForeground ||
            startupCapabilityConfirmationPending ||
            startupCapabilityRetryRequiresUserAction ||
            walkSessionResumePromptPending ||
            walkSessionResumeRetryRequiresUserAction ||
            gatewayWalkResumeRevalidationPending
        ) return

        val decision = startupCapabilityDecision ?: return
        var session = walkSessionLifecycle.snapshot()
        if (
            session.state == WalkSessionState.ACTIVE ||
            session.state == WalkSessionState.SAFE_STOP ||
            session.state == WalkSessionState.ENDED
        ) return
        if (
            session.state == WalkSessionState.PAUSED &&
            gatewayWalkAuthorityController.activeLeaseOrNull(session.epoch) == null
        ) {
            handleGatewayWalkAuthorityLost("walk_lease_missing_on_resume")
            return
        }

        val blockReason = walkSessionReadinessBlockReason(decision)
        if (blockReason != null) {
            if (
                decision.tier == WalkSafeStartupCapabilityTier.BLOCKED &&
                decision.pendingRequirements.isEmpty() &&
                decision.unavailableRequirements.isNotEmpty()
            ) {
                val action = if (session.state == WalkSessionState.PAUSED) {
                    WalkSessionAction.RESUME_WALK
                } else {
                    WalkSessionAction.START_WALK
                }
                val readiness = captureWalkSessionReadiness(decision, action)
                val event = if (session.state == WalkSessionState.PAUSED) {
                    WalkSessionEvent.RecoveryRecheckCompleted(readiness)
                } else {
                    WalkSessionEvent.InitialCheckCompleted(readiness)
                }
                transitionWalkSession(event)
                persistWalkSessionInterruptionMarker()
            } else {
                maybeRequestMissingWalkSessionPermissions(decision)
            }
            updateStatus("보행 시작 대기", blockReason)
            return
        }

        when {
            session.state == WalkSessionState.READY -> {
                val tokenWasMissing = session.confirmationToken == null
                if (session.readiness == null) {
                    transitionWalkSession(
                        WalkSessionEvent.InitialCheckCompleted(
                            captureWalkSessionReadiness(
                                decision = decision,
                                action = WalkSessionAction.START_WALK,
                            ),
                        ),
                    )
                    session = walkSessionLifecycle.snapshot()
                }
                val createdConfirmationToken =
                    tokenWasMissing && session.confirmationToken != null
                if (createdConfirmationToken) {
                    refreshStartupCapabilityUi()
                    return
                }
                val token = session.confirmationToken
                if (token == null) {
                    updateStatus(
                        "보행 시작 대기",
                        session.readiness?.blockingReasons?.joinToString()
                            ?: "필수 기능 점검을 완료하지 못했습니다.",
                    )
                    return
                }
                if (!isStartupCapabilityConfirmed()) {
                    updateStatus(
                        "보행 시작 확인 필요",
                        "필수 기능 점검을 통과했습니다. 안전 제한 안내를 확인한 뒤 시작하세요.",
                    )
                    return
                }
                requestGatewayWalkStart(token)
            }
            session.state == WalkSessionState.PAUSED &&
                session.recoveryStage == WalkSessionRecoveryStage.RECHECK_REQUIRED -> {
                transitionWalkSession(
                    WalkSessionEvent.RecoveryRecheckCompleted(
                        captureWalkSessionReadiness(
                            decision = decision,
                            action = WalkSessionAction.RESUME_WALK,
                        ),
                    ),
                )
                session = walkSessionLifecycle.snapshot()
                if (
                    session.recoveryStage ==
                    WalkSessionRecoveryStage.AWAITING_RESUME_CONFIRMATION
                ) {
                    refreshStartupCapabilityUi()
                    return
                }
            }
            session.state == WalkSessionState.PAUSED &&
                session.recoveryStage == WalkSessionRecoveryStage.AWAITING_RESUME_CONFIRMATION -> {
                if (developmentGuidanceStartBypassEnabled &&
                    developmentGuidanceResumeRequestedEpoch == session.epoch
                ) {
                    developmentGuidanceResumeRequestedEpoch = null
                    confirmWalkSessionResumeFromButton()
                } else if (isStartupCapabilityConfirmed()) {
                    requestWalkSessionResumeConfirmation()
                } else {
                    updateStatus(
                        "보행 재개 확인 필요",
                        "재검사를 통과했습니다. 안전 제한 안내를 확인한 뒤 재개 여부를 말해 주세요.",
                    )
                }
            }
        }
    }

    private fun requestGatewayWalkStart(token: WalkSessionConfirmationToken) {
        val snapshot = walkSessionLifecycle.snapshot()
        if (
            snapshot.state != WalkSessionState.READY ||
            snapshot.epoch != token.epoch ||
            snapshot.confirmationToken != token
        ) return
        if (currentGatewayWalkStartReadinessOrNull(token) == null) {
            makeGatewayWalkStartRetryAvailable(
                detail =
                    "환경·장착·기기 상태가 바뀌었거나 측정값이 만료되었습니다. " +
                        "실제 상태를 다시 점검하세요.",
            )
            return
        }
        val gatewaySession = gatewaySessionOrNull("walk_start") ?: run {
            makeGatewayWalkStartRetryAvailable(
                detail = "로그인 연결을 확인한 뒤 보행 시작을 다시 시도하세요.",
            )
            return
        }
        val operation = gatewayWalkAuthorityController.beginStart(snapshot.epoch) ?: run {
            makeGatewayWalkStartRetryAvailable(
                detail = "보행 시작 요청을 준비하지 못했습니다. 다시 시도하세요.",
            )
            return
        }
        gatewayWalkStartConfirmationToken = token
        updateStatus("보행 권한 확인", "계정의 활성 보행 권한을 확인하고 있습니다.")
        try {
            gatewaySessionExecutor.execute {
                val outcome = runCatching {
                    gatewayWalkSessionClient.startWithOwnedWalkRecovery(
                        session = gatewaySession,
                        walkId = operation.epoch.walkSessionId,
                        requestId = operation.requestId,
                        nowElapsedMs = { SystemClock.elapsedRealtime() },
                        isCurrent = {
                            val check = java.util.concurrent.FutureTask {
                                isGatewayWalkOperationCurrent(operation, token, gatewaySession)
                            }
                            runOnUiThread(check)
                            runCatching {
                                check.get(2, java.util.concurrent.TimeUnit.SECONDS)
                            }.getOrDefault(false)
                        },
                    )
                }
                runOnUiThread {
                    if (!isGatewayWalkOperationCurrent(operation, token, gatewaySession)) {
                        gatewayWalkAuthorityController.cancel(operation)
                        return@runOnUiThread
                    }
                    outcome.fold(
                        onSuccess = { result ->
                            handleGatewayWalkStartResult(
                                operation = operation,
                                token = token,
                                gatewaySession = gatewaySession,
                                result = result,
                            )
                        },
                        onFailure = {
                            gatewayWalkAuthorityController.cancel(operation)
                            makeGatewayWalkStartRetryAvailable(
                                detail =
                                    "서버 보행 권한을 확인하지 못해 시작하지 않았습니다. " +
                                        "연결을 확인한 뒤 다시 시도하세요.",
                                spoken =
                                    "서버 보행 권한을 확인하지 못해 보행 안내를 시작하지 않았습니다.",
                            )
                        },
                    )
                }
            }
        } catch (_: RejectedExecutionException) {
            gatewayWalkAuthorityController.cancel(operation)
            makeGatewayWalkStartRetryAvailable(
                detail = "보행 권한 확인 작업을 시작하지 못했습니다. 다시 시도하세요.",
            )
        }
    }

    private fun handleGatewayWalkStartResult(
        operation: GatewayWalkAuthorityOperation,
        token: WalkSessionConfirmationToken,
        gatewaySession: GatewayFieldSession,
        result: GatewayWalkStartResult,
    ) {
        when (gatewayWalkAuthorityController.completeStart(operation, result)) {
            GatewayWalkAuthorityCompletion.LEASE_ACTIVE ->
                completeGatewayWalkActivation(token)
            GatewayWalkAuthorityCompletion.CONFLICT -> {
                val conflict =
                    gatewayWalkAuthorityController.currentConflictOrNull(operation.epoch)
                        ?: run {
                            makeGatewayWalkStartRetryAvailable(
                                detail = "다른 기기의 보행 상태를 확인하지 못했습니다. 다시 시도하세요.",
                            )
                            return
                        }
                requestGatewayWalkTakeoverConfirmation(
                    operation = operation,
                    token = token,
                    gatewaySession = gatewaySession,
                    activeDeviceId = conflict.activeDeviceId,
                )
            }
            GatewayWalkAuthorityCompletion.STALE,
            GatewayWalkAuthorityCompletion.INVALID,
            -> {
                makeGatewayWalkStartRetryAvailable(
                    detail = "보행 권한 응답이 현재 시작 요청과 일치하지 않습니다. 다시 시도하세요.",
                )
            }
        }
    }

    private fun makeGatewayWalkStartRetryAvailable(
        detail: String,
        spoken: String? = null,
    ) {
        gatewayWalkStartConfirmationToken = null
        gatewayWalkTakeoverPromptPending = false
        gatewayWalkTakeoverPromptOperationId = null
        startupCapabilityConfirmationPending = false
        confirmedStartupCapabilityDecision = null
        startupCapabilityRetryRequiresUserAction = true
        refreshStartupCapabilityUi()
        updateStatus("보행 시작 대기", detail)
        spoken?.let(::speakInteraction)
    }

    private fun requestGatewayWalkTakeoverConfirmation(
        operation: GatewayWalkAuthorityOperation,
        token: WalkSessionConfirmationToken,
        gatewaySession: GatewayFieldSession,
        activeDeviceId: String,
    ) {
        if (
            !isCurrentGatewaySession(gatewaySession) ||
            walkSessionLifecycle.snapshot().epoch != operation.epoch ||
            walkSessionLifecycle.snapshot().confirmationToken != token
        ) {
            gatewayWalkAuthorityController.clearConflict(operation.epoch)
            makeGatewayWalkStartRetryAvailable(
                detail = "로그인 또는 보행 상태가 바뀌었습니다. 다시 시도하세요.",
            )
            return
        }
        gatewayWalkTakeoverPromptPending = true
        gatewayWalkTakeoverPromptOperationId = operation.operationId
        val sameDevice = activeDeviceId == gatewaySession.deviceId
        val conflictTitle = if (sameDevice) "이전 로그인에서 보행 중" else "다른 기기에서 보행 중"
        val prompt = "${conflictTitle}입니다. 이전 보행을 종료하고 이 기기에서 시작할까요? 예 또는 아니요라고 말해 주세요."
        val delivered = {
            runOnUiThread {
                if (
                    gatewayWalkTakeoverPromptPending &&
                    gatewayWalkTakeoverPromptOperationId == operation.operationId &&
                    gatewayWalkAuthorityController.currentConflictOrNull(operation.epoch) != null
                ) {
                    if (
                        !startVoiceCommandRecognition(
                            purpose = VoiceRecognitionPurpose.WALK_SESSION_TAKEOVER,
                            expectedGatewayWalkOperationId = operation.operationId,
                        )
                    ) {
                        cancelGatewayWalkTakeoverConfirmation(
                            operation.epoch,
                            "takeover_voice_not_started",
                        )
                    }
                }
            }
        }
        val failed = {
            runOnUiThread {
                cancelGatewayWalkTakeoverConfirmation(
                    operation.epoch,
                    "takeover_prompt_not_delivered",
                )
            }
        }
        updateStatus(
            conflictTitle,
            "이전 보행 종료 여부를 음성으로 확인합니다.",
        )
        val accepted = ensureFeedbackActuator().speakInteraction(
            message = prompt,
            onCompleted = delivered,
            onFailed = failed,
        ) == NavigationSpeechDispatchResult.ACCEPTED
        if (!accepted) failed()
    }

    private fun handleGatewayWalkTakeoverRecognition(phrases: List<String>) {
        val token = gatewayWalkStartConfirmationToken ?: return
        val epoch = token.epoch
        gatewayWalkTakeoverPromptPending = false
        gatewayWalkTakeoverPromptOperationId = null
        when (
            GatewayWalkTakeoverConfirmation.fromRecognizedText(
                phrases.firstOrNull { it.isNotBlank() },
            )
        ) {
            GatewayWalkTakeoverConfirmation.YES -> {
                val operation =
                    gatewayWalkAuthorityController.beginTakeover(epoch)
                        ?: run {
                            cancelGatewayWalkTakeoverConfirmation(
                                epoch,
                                "takeover_conflict_stale",
                            )
                            return
                        }
                executeGatewayWalkTakeover(operation, token)
            }
            GatewayWalkTakeoverConfirmation.NO -> {
                gatewayWalkAuthorityController.clearConflict(epoch)
                makeGatewayWalkStartRetryAvailable(
                    detail = "이전 기기의 보행을 유지합니다. 원할 때 다시 시도할 수 있습니다.",
                    spoken =
                        "이전 기기의 보행을 유지합니다. 이 기기에서는 시작하지 않았습니다.",
                )
            }
            GatewayWalkTakeoverConfirmation.NO_RESPONSE,
            GatewayWalkTakeoverConfirmation.UNRECOGNIZED,
            -> cancelGatewayWalkTakeoverConfirmation(
                epoch,
                "takeover_voice_unconfirmed",
            )
        }
    }

    private fun executeGatewayWalkTakeover(
        operation: GatewayWalkAuthorityOperation,
        token: WalkSessionConfirmationToken,
    ) {
        val gatewaySession = gatewaySessionOrNull("walk_takeover") ?: run {
            gatewayWalkAuthorityController.cancel(operation, clearConflict = true)
            makeGatewayWalkStartRetryAvailable(
                detail = "로그인 연결을 확인한 뒤 보행 시작을 다시 시도하세요.",
            )
            return
        }
        val conflict = operation.sourceConflict ?: run {
            gatewayWalkAuthorityController.cancel(operation, clearConflict = true)
            makeGatewayWalkStartRetryAvailable(
                detail = "이전 기기의 보행 상태가 만료되었습니다. 다시 시도하세요.",
            )
            return
        }
        updateStatus("보행 권한 이전", "이전 보행 종료와 새 권한 발급을 요청하고 있습니다.")
        try {
            gatewaySessionExecutor.execute {
                val outcome = runCatching {
                    gatewayWalkSessionClient.takeover(
                        session = gatewaySession,
                        walkId = operation.epoch.walkSessionId,
                        requestId = operation.requestId,
                        conflict = conflict,
                        localNowElapsedMs = SystemClock.elapsedRealtime(),
                    )
                }
                runOnUiThread {
                    if (!isGatewayWalkOperationCurrent(operation, token, gatewaySession)) {
                        gatewayWalkAuthorityController.cancel(
                            operation,
                            clearConflict = true,
                        )
                        return@runOnUiThread
                    }
                    outcome.fold(
                        onSuccess = { lease ->
                            if (
                                gatewayWalkAuthorityController.completeTakeover(
                                    operation,
                                    lease,
                                ) == GatewayWalkAuthorityCompletion.LEASE_ACTIVE
                            ) {
                                completeGatewayWalkActivation(token)
                            } else {
                                makeGatewayWalkStartRetryAvailable(
                                    detail =
                                        "권한 이전 응답이 현재 요청과 일치하지 않습니다. " +
                                            "다시 시도하세요.",
                                )
                            }
                        },
                        onFailure = {
                            gatewayWalkAuthorityController.cancel(
                                operation,
                                clearConflict = true,
                            )
                            makeGatewayWalkStartRetryAvailable(
                                detail =
                                    "이전 보행 종료와 권한 이전을 확인하지 못했습니다. " +
                                        "다시 시도하세요.",
                                spoken =
                                    "보행 권한을 이전하지 못해 이 기기에서는 시작하지 않았습니다.",
                            )
                        },
                    )
                }
            }
        } catch (_: RejectedExecutionException) {
            gatewayWalkAuthorityController.cancel(operation, clearConflict = true)
            makeGatewayWalkStartRetryAvailable(
                detail = "보행 권한 이전 작업을 시작하지 못했습니다. 다시 시도하세요.",
            )
        }
    }

    private fun completeGatewayWalkActivation(token: WalkSessionConfirmationToken) {
        val snapshot = walkSessionLifecycle.snapshot()
        val currentReadiness = if (
            snapshot.state == WalkSessionState.READY &&
            snapshot.epoch == token.epoch &&
            snapshot.confirmationToken == token
        ) {
            currentGatewayWalkStartReadinessOrNull(token)
        } else {
            null
        }
        if (
            (permissionRecoveryGate.blocksAutomaticResourceStart && !developmentGuidanceStartBypassEnabled) ||
            currentReadiness == null ||
            gatewayWalkAuthorityController.activeLeaseOrNull(snapshot.epoch) == null
        ) {
            val endOperation = gatewayWalkAuthorityController.beginEnd(token.epoch)
            val currentGatewaySession = gatewayFieldSession
            if (endOperation != null && currentGatewaySession != null) {
                endGatewayWalkBestEffort(currentGatewaySession, endOperation)
            } else {
                gatewayWalkAuthorityController.invalidate(token.epoch)
            }
            makeGatewayWalkStartRetryAvailable(
                detail =
                    "서버 응답을 기다리는 동안 실제 상태가 바뀌어 " +
                        "보행 안내를 시작하지 않았습니다. 다시 시도하세요.",
            )
            return
        }
        gatewayWalkStartConfirmationToken = null
        transitionWalkSession(WalkSessionEvent.StartRequested(token))
        if (isWalkSessionRuntimeActive()) {
            scheduleGatewayWalkRenewal()
            activateWalkSessionRuntime()
        }
    }

    private fun currentGatewayWalkStartReadinessOrNull(
        token: WalkSessionConfirmationToken,
    ): WalkSessionReadinessSnapshot? {
        val decision = startupCapabilityDecision ?: return null
        val readiness = captureWalkSessionReadiness(
            decision = decision,
            action = WalkSessionAction.START_WALK,
        )
        return readiness.takeIf {
            it.isReady &&
                it.epoch == token.epoch &&
                it.plan.action == token.readiness.plan.action &&
                it.plan.mode == token.readiness.plan.mode
        }
    }

    private fun isGatewayWalkOperationCurrent(
        operation: GatewayWalkAuthorityOperation,
        token: WalkSessionConfirmationToken,
        gatewaySession: GatewayFieldSession,
    ): Boolean {
        val snapshot = walkSessionLifecycle.snapshot()
        return gatewayWalkAuthorityController.isCurrent(operation) &&
            snapshot.epoch == operation.epoch &&
            snapshot.state == WalkSessionState.READY &&
            snapshot.confirmationToken == token &&
            gatewayWalkStartConfirmationToken == token &&
            isCurrentGatewaySession(gatewaySession)
    }

    private fun scheduleGatewayWalkRenewal() {
        gatewayWalkRenewalHandler.removeCallbacks(gatewayWalkRenewalRunnable)
        val snapshot = walkSessionLifecycle.snapshot()
        if (snapshot.state !in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED)) return
        val renewDelayMs = gatewayWalkAuthorityController.nextRenewDelayMs(
            snapshot.epoch,
            GATEWAY_WALK_RENEW_INTERVAL_MS,
        ) ?: run {
            handleGatewayWalkAuthorityLost("walk_lease_local_expiry")
            return
        }
        gatewayWalkRenewalHandler.postDelayed(
            gatewayWalkRenewalRunnable,
            renewDelayMs,
        )
    }

    private fun requestGatewayWalkRenewal() {
        gatewayWalkRenewalHandler.removeCallbacks(gatewayWalkRenewalRunnable)
        val snapshot = walkSessionLifecycle.snapshot()
        if (snapshot.state !in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED)) return
        val operation = gatewayWalkAuthorityController.beginRenew(snapshot.epoch)
            ?: run {
                if (
                    gatewayWalkAuthorityController.activeLeaseOrNull(snapshot.epoch) == null
                ) {
                    handleGatewayWalkAuthorityLost("walk_lease_local_expiry")
                }
                return
            }
        val lease = operation.sourceLease ?: run {
            handleGatewayWalkAuthorityLost("walk_lease_missing")
            return
        }
        val gatewaySession = gatewaySessionOrNull("walk_renew", speak = false) ?: run {
            gatewayWalkAuthorityController.cancel(operation)
            handleGatewayWalkAuthorityLost("walk_lease_gateway_session_missing")
            return
        }
        try {
            gatewaySessionExecutor.execute {
                val outcome = runCatching {
                    gatewayWalkSessionClient.renew(
                        session = gatewaySession,
                        lease = lease,
                        requestId = operation.requestId,
                        localNowElapsedMs = SystemClock.elapsedRealtime(),
                    )
                }
                runOnUiThread {
                    val callbackSnapshot = walkSessionLifecycle.snapshot()
                    if (
                        callbackSnapshot.epoch != operation.epoch ||
                        callbackSnapshot.state !in
                        setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED)
                    ) return@runOnUiThread
                    when (gatewayWalkAuthorityController.currentOperationStatus(operation)) {
                        GatewayWalkAuthorityCompletion.INVALID -> {
                            handleGatewayWalkAuthorityLost(
                                "walk_lease_expired_during_renew",
                            )
                            return@runOnUiThread
                        }
                        GatewayWalkAuthorityCompletion.LEASE_ACTIVE -> Unit
                        else -> return@runOnUiThread
                    }
                    val renewed = outcome.getOrNull()
                    if (
                        renewed == null ||
                        gatewayWalkAuthorityController.completeRenew(
                            operation,
                            renewed,
                        ) != GatewayWalkAuthorityCompletion.LEASE_ACTIVE
                    ) {
                        gatewayWalkAuthorityController.cancel(operation)
                        handleGatewayWalkAuthorityLost("walk_lease_renew_failed")
                        return@runOnUiThread
                    }
                    gatewayWalkResumeRevalidationPending = false
                    scheduleGatewayWalkRenewal()
                    if (
                        walkSessionLifecycle.snapshot().state == WalkSessionState.PAUSED &&
                        isActivityForeground
                    ) {
                        scheduleRawCollectionPausedUpload()
                        refreshStartupCapabilityUi()
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            gatewayWalkAuthorityController.cancel(operation)
            handleGatewayWalkAuthorityLost("walk_lease_renew_rejected")
        }
    }

    private fun revalidateGatewayWalkAfterForegroundReturn() {
        val snapshot = walkSessionLifecycle.snapshot()
        if (snapshot.state != WalkSessionState.PAUSED) return
        if (gatewayWalkAuthorityController.activeLeaseOrNull(snapshot.epoch) == null) {
            handleGatewayWalkAuthorityLost("walk_lease_expired_while_backgrounded")
            return
        }
        gatewayWalkResumeRevalidationPending = true
        requestGatewayWalkRenewal()
    }

    private fun handleGatewayWalkAuthorityLost(reason: String) {
        gatewayWalkRenewalHandler.removeCallbacks(gatewayWalkRenewalRunnable)
        gatewayWalkResumeRevalidationPending = false
        gatewayWalkTakeoverPromptPending = false
        gatewayWalkTakeoverPromptOperationId = null
        gatewayWalkStartConfirmationToken = null
        val snapshot = walkSessionLifecycle.snapshot()
        gatewayWalkAuthorityController.invalidate(snapshot.epoch)
        if (snapshot.state in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED)) {
            enterWalkSessionSafetyStopAndCancelOutputs(reason)
        }
        updateStatus(
            "보행 권한 만료 · 안전 중지",
            "서버의 단일 활성 보행 권한을 확인하지 못했습니다.",
        )
    }

    private fun cancelGatewayWalkTakeoverConfirmation(
        epoch: WalkRuntimeEpoch,
        reason: String,
    ) {
        gatewayWalkTakeoverPromptPending = false
        gatewayWalkTakeoverPromptOperationId = null
        gatewayWalkAuthorityController.clearConflict(epoch)
        makeGatewayWalkStartRetryAvailable(
            detail = "이전 보행 종료를 확인하지 않아 시작하지 않았습니다. 다시 시도할 수 있습니다.",
        )
        updateNavigationStatus("walk=takeover_not_confirmed reason=$reason")
    }

    private fun cancelPendingGatewayWalkStart() {
        val token = gatewayWalkStartConfirmationToken
        gatewayWalkStartConfirmationToken = null
        gatewayWalkTakeoverPromptPending = false
        gatewayWalkTakeoverPromptOperationId = null
        if (token != null) gatewayWalkAuthorityController.invalidate(token.epoch)
    }

    private fun endGatewayWalkBestEffort(
        gatewaySession: GatewayFieldSession,
        operation: GatewayWalkAuthorityOperation,
    ) {
        val lease = operation.sourceLease ?: return
        try {
            gatewaySessionExecutor.execute {
                runCatching {
                    gatewayWalkSessionClient.end(
                        session = gatewaySession,
                        lease = lease,
                        requestId = operation.requestId,
                    )
                }
            }
        } catch (_: RejectedExecutionException) {
            // The server lease expires after its bounded lifetime.
        }
    }

    private fun captureWalkSessionReadiness(
        decision: WalkSafeStartupCapabilityDecision,
        action: WalkSessionAction,
    ): WalkSessionReadinessSnapshot {
        val epoch = walkSessionLifecycle.snapshot().epoch
        var effectiveDecision = decision
        if (
            firstRunOnboardingComplete() &&
            action in setOf(WalkSessionAction.START_WALK, WalkSessionAction.RESUME_WALK) &&
            cameraAnalysisFeaturesEnabled() &&
            hasCameraPermission() &&
            WalkSafeStartupRequirement.CAMERA !in decision.pendingRequirements &&
            WalkSafeStartupRequirement.CAMERA !in decision.unavailableRequirements
        ) {
            val restrictionsBeforeDetectorLoad = currentPostLoginDisabledFeatures()
            loadDetectorAfterCameraGate()
            if (currentPostLoginDisabledFeatures() != restrictionsBeforeDetectorLoad) {
                effectiveDecision = applyPostLoginDeviceFeatureRestrictions(decision)
            }
        }
        val plan = WalkSessionReadinessPlan(
            action = action,
            mode = effectiveDecision.effectiveWalkSessionMode(),
        )
        val deviceResources = walkSessionResourceProbe.snapshot()
        val collector = WalkSessionReadinessCollector(epoch = epoch, plan = plan)
        plan.requiredRequirements.forEach { requirement ->
            val (status, reason) = if (
                developmentGuidanceStartBypassEnabled &&
                requirement !in setOf(
                    WalkSessionReadinessRequirement.GATEWAY,
                    WalkSessionReadinessRequirement.ROUTE_SERVICE,
                )
            ) {
                WalkSessionReadinessStatus.READY to "debug_guidance_start_bypass"
            } else when (requirement) {
                WalkSessionReadinessRequirement.FIRST_RUN_ONBOARDING -> {
                    if (firstRunOnboardingComplete()) {
                        WalkSessionReadinessStatus.READY to ""
                    } else {
                        WalkSessionReadinessStatus.UNAVAILABLE to
                            "first_run_onboarding_incomplete:" +
                            firstRunOnboardingSnapshot.stage.name.lowercase(Locale.US)
                    }
                }
                WalkSessionReadinessRequirement.PRIORITY_USER_ONBOARDING -> {
                    val onboarding = priorityUserOnboardingPolicy.evaluate(
                        environment = currentPriorityUserSupportEnvironment(effectiveDecision),
                        walkIsActive = isWalkSessionRuntimeActive(),
                    )
                    if (
                        (developmentQuickStartEnabled || onboarding.mayStartWalk) &&
                        currentReporterUserId() != null
                    ) {
                        WalkSessionReadinessStatus.READY to ""
                    } else {
                        WalkSessionReadinessStatus.UNAVAILABLE to
                            "priority_user_onboarding:" +
                            (
                                onboarding.walkBlockReason?.name?.lowercase(Locale.US)
                                    ?: "account_profile_unbound"
                            )
                    }
                }
                WalkSessionReadinessRequirement.OFFICIAL_ENVIRONMENT ->
                    officialEnvironmentReadiness(epoch)
                WalkSessionReadinessRequirement.PHONE_MOUNTING ->
                    phoneMountingReadiness(epoch)
                WalkSessionReadinessRequirement.PERMISSIONS -> {
                    WalkSessionReadinessStatus.READY to ""
                }
                WalkSessionReadinessRequirement.CAMERA ->
                    if (!cameraAnalysisFeaturesEnabled()) {
                        WalkSessionReadinessStatus.READY to ""
                    } else {
                        combineReadinessChecks(
                            startupRequirementCheck(
                                effectiveDecision,
                                setOf(WalkSafeStartupRequirement.CAMERA),
                            ),
                            if (hasCameraPermission()) {
                                WalkSessionReadinessStatus.READY to ""
                            } else {
                                WalkSessionReadinessStatus.UNAVAILABLE to
                                    "camera_permission_missing"
                            },
                        )
                    }
                WalkSessionReadinessRequirement.LOCATION ->
                    if (
                        !postLoginDeviceFeatureEnabled(
                            PostLoginDeviceCheckFeature.LOCATION_GUIDANCE,
                        )
                    ) {
                        WalkSessionReadinessStatus.READY to ""
                    } else {
                        combineReadinessChecks(
                            startupRequirementCheck(
                                effectiveDecision,
                                setOf(WalkSafeStartupRequirement.GPS),
                            ),
                            if (hasLocationPermission()) {
                                WalkSessionReadinessStatus.READY to ""
                            } else {
                                WalkSessionReadinessStatus.UNAVAILABLE to
                                    "precise_location_permission_missing"
                            },
                        )
                    }
                WalkSessionReadinessRequirement.METRIC_DISTANCE ->
                    startupRequirementCheck(
                        effectiveDecision,
                        setOf(
                            WalkSafeStartupRequirement.METRIC_DISTANCE,
                            WalkSafeStartupRequirement.APPROVED_DEVICE_PROFILE,
                        ),
                    )
                WalkSessionReadinessRequirement.MODEL ->
                    if (!cameraAnalysisFeaturesEnabled() || detectorAvailable) {
                        WalkSessionReadinessStatus.READY to ""
                    } else {
                        WalkSessionReadinessStatus.UNAVAILABLE to
                            "model_unavailable:${detectorLoadReason ?: "not_loaded"}"
                    }
                WalkSessionReadinessRequirement.VOICE_INPUT -> if (
                    !effectiveDecision.allowsRequirement(WalkSafeStartupRequirement.MICROPHONE) ||
                    !effectiveDecision.allowsRequirement(WalkSafeStartupRequirement.ON_DEVICE_STT)
                ) {
                    WalkSessionReadinessStatus.READY to ""
                } else {
                    if (hasRecordAudioPermission()) {
                        WalkSessionReadinessStatus.READY to ""
                    } else {
                        WalkSessionReadinessStatus.UNAVAILABLE to "microphone_permission_missing"
                    }
                }
                WalkSessionReadinessRequirement.VOICE_OUTPUT -> if (
                    !effectiveDecision.allowsRequirement(
                        WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS,
                    )
                ) {
                    WalkSessionReadinessStatus.READY to ""
                } else {
                    startupRequirementCheck(
                        effectiveDecision,
                        setOf(WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS),
                    )
                }
                WalkSessionReadinessRequirement.ROUTE_SERVICE -> {
                    val endpointReady = if (BuildConfig.DEBUG) {
                        GatewayEndpointPolicy.debugOriginOrNull(
                            BuildConfig.WALKSAFE_GATEWAY_ORIGIN,
                        ) != null
                    } else {
                        GatewayEndpointPolicy.approvedReleaseOriginOrNull(
                            raw = BuildConfig.WALKSAFE_GATEWAY_ORIGIN,
                            approvedOrigin = BuildConfig.WALKSAFE_GATEWAY_ORIGIN,
                        ) != null
                    }
                    if (endpointReady) {
                        WalkSessionReadinessStatus.READY to ""
                    } else {
                        WalkSessionReadinessStatus.UNAVAILABLE to "route_service_endpoint_unavailable"
                    }
                }
                WalkSessionReadinessRequirement.GATEWAY -> {
                    if (isGatewaySessionReadyForCurrentActor()) {
                        WalkSessionReadinessStatus.READY to ""
                    } else {
                        WalkSessionReadinessStatus.UNAVAILABLE to "gateway_session_unavailable"
                    }
                }
                WalkSessionReadinessRequirement.DEVICE_RESOURCES -> combineReadinessChecks(
                    startupRequirementCheck(
                        effectiveDecision,
                        setOf(
                            WalkSafeStartupRequirement.ANDROID_VERSION,
                        ),
                    ),
                    deviceResources.readinessStatus to deviceResources.reason,
                )
            }
            collector.record(
                WalkSessionReadinessObservation(
                    epoch = epoch,
                    requirement = requirement,
                    status = status,
                    reason = reason,
                ),
            )
        }
        return collector.build(assessedAtEpochMs = SystemClock.elapsedRealtime())
    }

    private fun startupRequirementCheck(
        decision: WalkSafeStartupCapabilityDecision,
        requirements: Set<WalkSafeStartupRequirement>,
    ): Pair<WalkSessionReadinessStatus, String> {
        val unavailable = decision.unavailableRequirements.filter(requirements::contains)
        if (unavailable.isNotEmpty()) {
            return WalkSessionReadinessStatus.UNAVAILABLE to
                "startup_unavailable:${unavailable.joinToString(",") { it.name }}"
        }
        val pending = decision.pendingRequirements.filter(requirements::contains)
        if (pending.isNotEmpty()) {
            return WalkSessionReadinessStatus.PENDING to
                "startup_pending:${pending.joinToString(",") { it.name }}"
        }
        return WalkSessionReadinessStatus.READY to ""
    }

    private fun combineReadinessChecks(
        vararg checks: Pair<WalkSessionReadinessStatus, String>,
    ): Pair<WalkSessionReadinessStatus, String> {
        val unavailable = checks.filter { it.first == WalkSessionReadinessStatus.UNAVAILABLE }
        if (unavailable.isNotEmpty()) {
            return WalkSessionReadinessStatus.UNAVAILABLE to
                unavailable.map(Pair<WalkSessionReadinessStatus, String>::second)
                    .filter(String::isNotBlank)
                    .joinToString(",")
        }
        val pending = checks.filter { it.first == WalkSessionReadinessStatus.PENDING }
        if (pending.isNotEmpty()) {
            return WalkSessionReadinessStatus.PENDING to
                pending.map(Pair<WalkSessionReadinessStatus, String>::second)
                    .filter(String::isNotBlank)
                    .joinToString(",")
        }
        return WalkSessionReadinessStatus.READY to ""
    }

    private fun walkSessionReadinessBlockReason(
        decision: WalkSafeStartupCapabilityDecision,
    ): String? {
        if (!firstRunOnboardingComplete()) {
            return "첫 실행 등록과 안전교육이 완료될 때까지 보행 안내를 시작하지 않습니다."
        }
        if (developmentGuidanceStartBypassEnabled) return null
        if (!decision.mayConfirmAndStart) return decision.noticeKo
        if (
            !postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.VOICE_GUIDANCE) ||
                !decision.allowsRequirement(WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS)
        ) {
            return KOREAN_TTS_WALK_BLOCK_DETAIL
        }
        val onboarding = priorityUserOnboardingPolicy.evaluate(
            currentPriorityUserSupportEnvironment(decision),
        )
        if (!developmentQuickStartEnabled && !onboarding.mayStartWalk) return onboarding.noticeKo
        if (currentReporterUserId() == null) return "로그인이 완료될 때까지 보행 안내를 시작하지 않습니다."
        if (!isGatewaySessionReadyForCurrentActor()) {
            return "게이트웨이 로그인을 확인한 뒤 보행 안내를 시작할 수 있습니다."
        }
        officialEnvironmentBlockReason()?.let { return it }
        phoneMountingBlockReason()?.let { return it }
        val action = if (
            walkSessionLifecycle.snapshot().state == WalkSessionState.PAUSED
        ) {
            WalkSessionAction.RESUME_WALK
        } else {
            WalkSessionAction.START_WALK
        }
        val missingPermissions = missingRequiredWalkSessionPermissions(action)
        if (missingPermissions.isNotEmpty()) {
            return "필수 권한이 필요합니다: ${missingPermissions.joinToString(", ") { it.permissionLabelKo() }}"
        }
        return null
    }

    private fun missingRequiredWalkSessionPermissions(
        action: WalkSessionAction,
    ): List<String> = buildList {
        if (cameraAnalysisFeaturesEnabled() && !hasCameraPermission()) {
            add(Manifest.permission.CAMERA)
        }
        val locationGuidanceEnabled = postLoginDeviceFeatureEnabled(
            PostLoginDeviceCheckFeature.LOCATION_GUIDANCE,
        )
        if (locationGuidanceEnabled && !hasLocationPermission()) {
            add(Manifest.permission.ACCESS_FINE_LOCATION)
            add(Manifest.permission.ACCESS_COARSE_LOCATION)
        }
    }

    private fun missingWalkSessionPermissions(
        decision: WalkSafeStartupCapabilityDecision,
    ): List<String> {
        val missing = mutableListOf<String>()
        if (
            cameraAnalysisFeaturesEnabled() &&
            decision.allowsRequirement(WalkSafeStartupRequirement.CAMERA) &&
            !hasCameraPermission()
        ) {
            missing += Manifest.permission.CAMERA
        }
        if (
            postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.HANDS_FREE_VOICE) &&
            decision.allowsRequirement(WalkSafeStartupRequirement.MICROPHONE) &&
            decision.allowsRequirement(WalkSafeStartupRequirement.ON_DEVICE_STT) &&
            !hasRecordAudioPermission()
        ) {
            missing += Manifest.permission.RECORD_AUDIO
        }
        val locationGuidanceEnabled = postLoginDeviceFeatureEnabled(
            PostLoginDeviceCheckFeature.LOCATION_GUIDANCE,
        )
        if (locationGuidanceEnabled && !hasLocationPermission()) {
            missing += Manifest.permission.ACCESS_FINE_LOCATION
            missing += Manifest.permission.ACCESS_COARSE_LOCATION
        }
        if (
            locationGuidanceEnabled &&
            !hasActivityRecognitionPermission() &&
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q
        ) {
            missing += Manifest.permission.ACTIVITY_RECOGNITION
        }
        return missing.distinct()
    }

    private fun maybeRequestMissingWalkSessionPermissions(
        decision: WalkSafeStartupCapabilityDecision,
    ) {
        if (
            !firstRunOnboardingComplete() ||
            !decision.mayConfirmAndStart ||
            currentReporterUserId() == null ||
            walkSessionPermissionRequestInFlight ||
            walkSessionPermissionRequestAttempted
        ) return
        val requestable = missingWalkSessionPermissions(decision).filterNot { permission ->
            permission == Manifest.permission.RECORD_AUDIO ||
                permission == Manifest.permission.ACTIVITY_RECOGNITION
        }
        if (requestable.isEmpty()) return
        walkSessionPermissionRequestAttempted = true
        walkSessionPermissionRequestInFlight = true
        walkSessionPermissionRequestCode = try {
            requestPermissionsWithLease(
                requestable.toTypedArray(),
                PermissionRequestPurpose.WALK_SESSION,
            )
        } catch (error: RuntimeException) {
            walkSessionPermissionRequestInFlight = false
            throw error
        }
    }

    private fun String.permissionLabelKo(): String = when (this) {
        Manifest.permission.CAMERA -> "카메라"
        Manifest.permission.ACCESS_FINE_LOCATION,
        Manifest.permission.ACCESS_COARSE_LOCATION,
        -> "정확한 위치"
        Manifest.permission.RECORD_AUDIO -> "마이크"
        Manifest.permission.ACTIVITY_RECOGNITION -> "보행 센서"
        else -> this
    }

    private fun WalkSafeStartupCapabilityDecision.allowsRequirement(
        requirement: WalkSafeStartupRequirement,
    ): Boolean =
        tier != WalkSafeStartupCapabilityTier.BLOCKED &&
            requirement !in unavailableRequirements &&
            requirement !in pendingRequirements

    private fun WalkSafeStartupCapabilityDecision.allowsMetricDistance(): Boolean =
        allowsRequirement(WalkSafeStartupRequirement.METRIC_DISTANCE)

    private fun WalkSafeStartupCapabilityDecision.toWalkSessionMode(): WalkSessionMode = when {
        tier == WalkSafeStartupCapabilityTier.BLOCKED -> WalkSessionMode.UNAVAILABLE
        !allowsMetricDistance() -> WalkSessionMode.DISTANCE_LIMITED
        else -> WalkSessionMode.FULL
    }

    private fun WalkSafeStartupCapabilityDecision.effectiveWalkSessionMode(): WalkSessionMode =
        toWalkSessionMode()

    private fun isWalkSessionRuntimeActive(): Boolean {
        if (!::walkSessionLifecycle.isInitialized) return false
        val snapshot = walkSessionLifecycle.snapshot()
        return firstRunOnboardingComplete() &&
            (!permissionRecoveryGate.blocksAutomaticResourceStart || developmentGuidanceStartBypassEnabled) &&
            isActivityForeground &&
            snapshot.state == WalkSessionState.ACTIVE &&
            snapshot.isForeground &&
            gatewayWalkAuthorityController.activeLeaseOrNull(snapshot.epoch) != null
    }

    @SuppressLint("ApplySharedPref")
    private fun persistWalkSessionInterruptionMarker() {
        if (!::stepLengthPrefs.isInitialized || !::walkSessionLifecycle.isInitialized) return
        val state = walkSessionLifecycle.snapshot().state
        val interrupted = state == WalkSessionState.ACTIVE ||
            state == WalkSessionState.PAUSED ||
            state == WalkSessionState.SAFE_STOP
        stepLengthPrefs.edit().putBoolean(PREF_WALK_SESSION_INTERRUPTED, interrupted).commit()
    }

    private fun activateWalkSessionRuntime() {
        if (!isWalkSessionRuntimeActive()) return handleGatewayWalkAuthorityLost(
            "walk_lease_missing_before_runtime",
        )
        val runtimeEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull()
            ?: return handleGatewayWalkAuthorityLost("walk_epoch_missing_before_runtime")
        if (!walkRuntimeSafetyCoordinator.beginEpoch(runtimeEpoch).safetyOutputsAllowed) return
        ensureWalkSessionResourceMonitoring()
        if (!observeWalkRuntimeResourceSafety(runtimeEpoch)) return
        scheduleGatewayWalkRenewal()
        persistWalkSessionInterruptionMarker()
        walkSessionResumePromptPending = false
        walkSessionResumeRetryRequiresUserAction = false
        if (!activateOfficialEnvironmentRuntime()) return
        if (!activatePhoneMountingRuntime()) return
        if (developmentGuidanceStartBypassEnabled) {
            // Navigation is independent of camera teardown, ARCore and detector readiness.
            startNavigationServicesIfNeeded()
            maybeStartHandsFreeVoiceService()
        }
        if (cameraAnalysisFeaturesEnabled()) {
            beginRuntimeCameraHandoff(runtimeEpoch)
        } else {
            cancelRuntimeCameraHandoff()
        }
        stopOfficialEnvironmentCameraPreflight(
            releaseMountingSensor = false,
            onReleased = {
                startWalkSessionRuntimeAfterCameraRelease(runtimeEpoch)
            },
        )
        if (developmentGuidanceStartBypassEnabled) refreshStartupCapabilityUi()
    }

    private fun startWalkSessionRuntimeAfterCameraRelease(
        expectedEpoch: WalkRuntimeEpoch,
    ) {
        if (
            !isWalkSessionRuntimeActive() ||
            !walkSessionLifecycle.isRuntimeEpochCurrent(expectedEpoch)
        ) {
            cancelRuntimeCameraHandoff()
            return
        }
        if (cameraFallbackCleanupPending) {
            stopCameraFallbackSession(
                updateUi = false,
                onReleased = { startWalkSessionRuntimeAfterCameraRelease(expectedEpoch) },
            )
            return
        }
        if (!cameraAnalysisFeaturesEnabled()) {
            startWalkSessionRuntimeWithoutCamera()
            return
        }
        if (cameraXReleaseBlocked) {
            cancelRuntimeCameraHandoff()
            enterWalkSessionSafetyStopAndCancelOutputs("camera_release_timed_out")
            return
        }
        if (::cameraFallbackLifecycleOwner.isInitialized) {
            cameraFallbackLifecycleOwner.moveTo(Lifecycle.State.RESUMED)
        }
        if (::surfaceView.isInitialized) {
            val arSessionReady =
                session != null && arSessionPurpose != ArSessionPurpose.NONE
            if (arSessionReady) surfaceView.onResume()
            syncGlSurfaceRenderMode(forceFrame = true)
            if (!arSessionReady) surfaceView.onPause()
        }
        if (::earthOrientationTracker.isInitialized) earthOrientationTracker.start()
        syncActiveSessionScreenPolicy()
        if (cameraFallbackRequested) {
            if (!cameraFallbackRunning) bindCameraFallbackSession()
        } else if (session == null) {
            if (pendingSessionStartAfterInstall) pendingSessionStartAfterInstall = false
            ensurePermissionsThenStart()
        }
        startNavigationServicesIfNeeded()
        maybeStartHandsFreeVoiceService()
        refreshStartupCapabilityUi()
    }

    private fun startWalkSessionRuntimeWithoutCamera() {
        cancelRuntimeCameraHandoff()
        if (::surfaceView.isInitialized) {
            syncGlSurfaceRenderMode(forceFrame = true)
            surfaceView.onPause()
        }
        retainLocationCompassOrStop()
        startNavigationServicesIfNeeded()
        maybeStartHandsFreeVoiceService()
        syncActiveSessionScreenPolicy()
        refreshStartupCapabilityUi()
    }

    private fun requestWalkSessionResumeConfirmation() {
        if (!::walkSessionLifecycle.isInitialized || walkSessionResumePromptPending) return
        val snapshot = walkSessionLifecycle.snapshot()
        if (
            snapshot.state != WalkSessionState.PAUSED ||
            snapshot.recoveryStage != WalkSessionRecoveryStage.AWAITING_RESUME_CONFIRMATION ||
            !snapshot.isForeground ||
            !isStartupCapabilityConfirmed()
        ) return

        if (!voiceResumeConfirmationAvailable()) {
            walkSessionResumeRetryRequiresUserAction = true
            updateStatus(
                "보행 재개 확인 필요",
                "음성 확인 기능이 제한되어 있습니다. 화면의 보행 안내 재개 확인 버튼을 눌러 주세요.",
            )
            if (::startupCapabilityConfirmButton.isInitialized) {
                startupCapabilityConfirmButton.isEnabled = true
                startupCapabilityConfirmButton.text = "보행 안내 재개 확인"
            }
            return
        }

        val confirmationToken = snapshot.confirmationToken ?: return
        val expectedWalkEpoch = snapshot.epoch
        walkSessionResumeConfirmationToken = confirmationToken
        walkSessionResumePromptPending = true
        val prompt = "보행 안내를 다시 시작할까요? 시작 또는 취소라고 말해 주세요"
        val generation = feedbackLifecycleGeneration
        val delivered = {
            runOnUiThread {
                if (
                    isFeedbackLifecycleCurrent(generation) &&
                    walkSessionResumePromptPending &&
                    walkSessionLifecycle.snapshot().epoch == expectedWalkEpoch &&
                    walkSessionLifecycle.snapshot().confirmationToken == confirmationToken
                ) {
                    if (
                        !startVoiceCommandRecognition(
                            VoiceRecognitionPurpose.WALK_SESSION_RESUME,
                        )
                    ) {
                        handleWalkSessionResumeRecognizerNotStarted()
                    }
                }
            }
        }
        val failed = {
            runOnUiThread {
                val currentSnapshot = walkSessionLifecycle.snapshot()
                if (
                    feedbackLifecycleGeneration == generation &&
                    currentSnapshot.epoch == expectedWalkEpoch &&
                    currentSnapshot.confirmationToken == confirmationToken &&
                    walkSessionResumeConfirmationToken == confirmationToken
                ) {
                    walkSessionResumePromptPending = false
                    walkSessionResumeConfirmationToken = null
                    walkSessionResumeRetryRequiresUserAction = true
                    updateStatus("보행 재개 확인 필요", "안내 음성을 재생하지 못했습니다. 보행 재개 확인 버튼으로 다시 시도해 주세요.")
                    if (::startupCapabilityConfirmButton.isInitialized) {
                        startupCapabilityConfirmButton.isEnabled = true
                        startupCapabilityConfirmButton.text = "보행 안내 재개 확인"
                    }
                }
            }
        }
        val accepted = ensureFeedbackActuator().speakInteraction(
            message = prompt,
            onCompleted = delivered,
            onFailed = failed,
        ) == NavigationSpeechDispatchResult.ACCEPTED
        if (!accepted) failed()
    }

    private fun handleWalkSessionResumeRecognizerNotStarted() {
        val snapshot = walkSessionLifecycle.snapshot()
        if (
            snapshot.state != WalkSessionState.PAUSED ||
            snapshot.recoveryStage != WalkSessionRecoveryStage.AWAITING_RESUME_CONFIRMATION
        ) return
        walkSessionResumePromptPending = false
        walkSessionResumeRetryRequiresUserAction = true
        walkSessionResumeConfirmationToken = null
        updateStatus(
            "보행 안내 일시중지",
            "재개 응답을 들을 준비가 되지 않아 일시중지를 유지합니다. 재개 확인을 다시 눌러 주세요.",
        )
        if (::startupCapabilityConfirmButton.isInitialized) {
            startupCapabilityConfirmButton.isEnabled = true
            startupCapabilityConfirmButton.text = "보행 안내 재개 확인"
        }
    }

    private fun handleWalkSessionResumeRecognition(phrases: List<String>) {
        val confirmationToken = walkSessionResumeConfirmationToken ?: return
        walkSessionResumePromptPending = false
        walkSessionResumeConfirmationToken = null
        val response = WalkSessionResumeConfirmation.fromRecognizedText(phrases.firstOrNull())
        transitionWalkSession(
            WalkSessionEvent.ResumeConfirmationReceived(
                confirmation = response,
                token = confirmationToken,
            ),
        )
        walkSessionResumeRetryRequiresUserAction =
            response != WalkSessionResumeConfirmation.START
        persistWalkSessionInterruptionMarker()
        if (isWalkSessionRuntimeActive()) {
            activateWalkSessionRuntime()
            updateStatus("보행 안내 재개", "필수 기능 재검사와 사용자 확인을 마쳐 새 판단으로 재개했습니다.")
            // A walker who cannot see the screen has no other way to know guidance is back, and
            // this is the sentence the practice screen rehearsed.
            speakInteraction(PriorityUserPractice.RESUME.instructionKo)
        } else {
            val detail = when (response) {
                WalkSessionResumeConfirmation.CANCEL -> "사용자가 취소해 일시중지를 유지합니다."
                WalkSessionResumeConfirmation.NO_RESPONSE -> "응답이 없어 일시중지를 유지합니다."
                WalkSessionResumeConfirmation.UNRECOGNIZED -> "재개 응답을 확인하지 못해 일시중지를 유지합니다."
                WalkSessionResumeConfirmation.START -> "재검사 상태가 바뀌어 일시중지를 유지합니다."
            }
            updateStatus("보행 안내 일시중지", detail)
            if (::startupCapabilityConfirmButton.isInitialized) {
                startupCapabilityConfirmButton.isEnabled = true
                startupCapabilityConfirmButton.text = "보행 안내 재개 확인"
            }
        }
    }

    private fun voiceResumeConfirmationAvailable(): Boolean {
        val decision = startupCapabilityDecision ?: return false
        return hasRecordAudioPermission() &&
            handsFreeVoiceModelDirectory != null && !handsFreeVoiceDestroyed &&
            !oneShotSpeechRecognitionLimited &&
            postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.VOICE_GUIDANCE) &&
            decision.allowsRequirement(WalkSafeStartupRequirement.MICROPHONE) &&
            decision.allowsRequirement(WalkSafeStartupRequirement.ON_DEVICE_STT) &&
            decision.allowsRequirement(WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS)
    }

    private fun confirmWalkSessionResumeFromButton() {
        val snapshot = walkSessionLifecycle.snapshot()
        val token = snapshot.confirmationToken ?: return
        if (
            snapshot.state != WalkSessionState.PAUSED ||
            snapshot.recoveryStage != WalkSessionRecoveryStage.AWAITING_RESUME_CONFIRMATION
        ) return
        walkSessionResumePromptPending = false
        walkSessionResumeRetryRequiresUserAction = false
        walkSessionResumeConfirmationToken = null
        transitionWalkSession(
            WalkSessionEvent.ResumeConfirmationReceived(
                confirmation = WalkSessionResumeConfirmation.START,
                token = token,
            ),
        )
        persistWalkSessionInterruptionMarker()
        if (isWalkSessionRuntimeActive()) {
            activateWalkSessionRuntime()
            updateStatus(
                "보행 안내 재개",
                "화면의 재개 버튼 확인으로 보행 안내를 다시 시작했습니다.",
            )
            speakInteraction(PriorityUserPractice.RESUME.instructionKo)
        }
    }

    private fun canBeginRuntimeMetricPreflight(): Boolean {
        if (!::startupCapabilityProbe.isInitialized || !isActivityForeground) return false
        if (!firstRunDeviceCheckAllowsPreflight()) return false
        if (
            postLoginCameraPipelinePreflightActive ||
            postLoginCameraPipelineCleanupPending ||
            postLoginCameraPipelineCamera != null ||
            cameraFallbackCleanupPending ||
            cameraFallbackCamera != null ||
            cameraXReleaseBlocked
        ) return false
        val walkSession = walkSessionLifecycle.snapshot()
        if (
            !walkSession.isForeground ||
            walkSession.state !in setOf(WalkSessionState.READY, WalkSessionState.PAUSED)
        ) return false
        if (arSessionPurpose != ArSessionPurpose.NONE || session != null) return false
        if (::fieldSessionLog.isInitialized && isFieldSessionActive()) return false
        val input = startupCapabilityProbe.snapshot()
        val coreAvailable = listOf(
            input.androidVersionSupported,
            input.cameraAvailable,
        ).all { it == true }
        val effectiveMetricDistance = metricDistanceCapabilityOverride ?: input.metricDistanceAvailable
        return coreAvailable && effectiveMetricDistance == null
    }

    private fun beginRuntimeMetricPreflight() {
        if (!canBeginRuntimeMetricPreflight()) return
        val binding = postLoginDeviceCheckSnapshot.bindingOrNull ?: return
        if (!isPostLoginDeviceCheckBindingCurrent(binding)) return
        postLoginMetricPreflightStarted = true
        metricPreflightOwner = RuntimeMetricPreflightOwner.DEVICE_CHECK
        metricPreflightFirstRunLease = currentFirstRunAsyncLease()
        metricPreflightPostLoginBinding = binding
        confirmedStartupCapabilityDecision = null
        startupCapabilityConfirmationPending = false
        val generation = ++runtimeMetricPreflightGeneration
        metricPreflightLifecycleGeneration = feedbackLifecycleGeneration
        pendingMetricPreflightPermissionGeneration = generation
        runtimeMetricOutputAllowed = false
        runtimeMetricInitialNavigationStartPending = false
        refreshStartupCapabilityUi()
        if (!hasCameraPermission()) {
            requestPermissionsWithLease(
                arrayOf(Manifest.permission.CAMERA),
                PermissionRequestPurpose.METRIC_PREFLIGHT_CAMERA,
            )
            return
        }
        pendingMetricPreflightPermissionGeneration = null
        startRuntimeMetricPreflight(generation, metricPreflightLifecycleGeneration)
    }

    private fun startRuntimeMetricPreflight(
        generation: Long,
        lifecycleGeneration: Int,
    ) {
        if (!isRuntimeMetricPreflightAttemptCurrent(generation, lifecycleGeneration)) return
        val availability = ArCoreApk.getInstance().checkAvailability(this)
        if (shouldRecheckArCoreAvailability(availability)) {
            startupMetricPreflightButton.isEnabled = false
            startupMetricPreflightButton.text = "ARCore 지원 확인 중"
            ArCoreApk.getInstance().checkAvailabilityAsync(this) { resolved ->
                runOnUiThread {
                    if (isRuntimeMetricPreflightAttemptCurrent(generation, lifecycleGeneration)) {
                        continueRuntimeMetricPreflightStart(resolved, generation, lifecycleGeneration)
                    }
                }
            }
            return
        }
        continueRuntimeMetricPreflightStart(availability, generation, lifecycleGeneration)
    }

    private fun continueRuntimeMetricPreflightStart(
        availability: ArCoreApk.Availability,
        generation: Long,
        lifecycleGeneration: Int,
    ) {
        if (!isRuntimeMetricPreflightAttemptCurrent(generation, lifecycleGeneration)) return
        var diagnosticReason = availability.name
        val depthSupport = when {
            !hasCameraPermission() -> {
                diagnosticReason = "CAMERA_PERMISSION_MISSING"
                RuntimeMetricDepthSupport.UNKNOWN
            }
            availability == ArCoreApk.Availability.UNSUPPORTED_DEVICE_NOT_CAPABLE ->
                RuntimeMetricDepthSupport.UNSUPPORTED
            availability != ArCoreApk.Availability.SUPPORTED_INSTALLED ->
                RuntimeMetricDepthSupport.UNKNOWN
            else -> try {
                val supportSession = Session(this)
                try {
                    if (
                        supportSession.isDepthModeSupported(
                            com.google.ar.core.Config.DepthMode.AUTOMATIC,
                        )
                    ) {
                        diagnosticReason = "DEPTH_MODE_AUTOMATIC_SUPPORTED"
                        RuntimeMetricDepthSupport.SUPPORTED
                    } else {
                        diagnosticReason = "DEPTH_MODE_AUTOMATIC_UNSUPPORTED"
                        RuntimeMetricDepthSupport.UNSUPPORTED
                    }
                } finally {
                    supportSession.close()
                }
            } catch (_: UnavailableDeviceNotCompatibleException) {
                diagnosticReason = "ARCORE_DEVICE_NOT_COMPATIBLE"
                RuntimeMetricDepthSupport.UNSUPPORTED
            } catch (error: Exception) {
                diagnosticReason = error.javaClass.simpleName
                RuntimeMetricDepthSupport.UNKNOWN
            }
        }
        finishDeviceMetricDepthSupportCheck(
            generation = generation,
            lifecycleGeneration = lifecycleGeneration,
            depthSupport = depthSupport,
            diagnosticReason = diagnosticReason,
        )
    }

    private fun finishDeviceMetricDepthSupportCheck(
        generation: Long,
        lifecycleGeneration: Int,
        depthSupport: RuntimeMetricDepthSupport,
        diagnosticReason: String,
    ) {
        if (!isRuntimeMetricPreflightAttemptCurrent(generation, lifecycleGeneration)) return
        val completedBinding = metricPreflightPostLoginBinding ?: return
        val completedOwner = metricPreflightOwner
        if (
            completedOwner != RuntimeMetricPreflightOwner.DEVICE_CHECK &&
            completedOwner != RuntimeMetricPreflightOwner.STORED_DEPTH_REFRESH
        ) return
        val supportsMetricDistance = when (depthSupport) {
            RuntimeMetricDepthSupport.SUPPORTED -> true
            RuntimeMetricDepthSupport.UNSUPPORTED -> false
            RuntimeMetricDepthSupport.UNKNOWN -> null
        }
        val supportState = when (depthSupport) {
            RuntimeMetricDepthSupport.SUPPORTED -> PostLoginMetricDepthState.SUPPORTED
            RuntimeMetricDepthSupport.UNSUPPORTED -> PostLoginMetricDepthState.EXPLICITLY_UNSUPPORTED
            RuntimeMetricDepthSupport.UNKNOWN -> PostLoginMetricDepthState.UNKNOWN
        }
        runtimeMetricPreflightGeneration += 1
        pendingMetricPreflightPermissionGeneration = null
        metricPreflightFirstRunLease = null
        metricPreflightPostLoginBinding = null
        metricPreflightOwner = RuntimeMetricPreflightOwner.NONE
        postLoginMetricPreflightStarted = false
        runtimeMetricOutputAllowed = false
        runtimeMetricInitialNavigationStartPending = false
        android.util.Log.i(
            "WalkSafeDepthCheck",
            "owner=$completedOwner support=$depthSupport evidence=DEPTH_API_SUPPORT_ONLY " +
                "reason=$diagnosticReason",
        )
        if (completedOwner == RuntimeMetricPreflightOwner.STORED_DEPTH_REFRESH) {
            if (!completeStoredMetricDepthRefresh(supportsMetricDistance, completedBinding)) {
                postLoginMetricDepthState = PostLoginMetricDepthState.UNKNOWN
                metricDistanceCapabilityOverride = null
            }
        } else {
            postLoginMetricDepthState = supportState
            metricDistanceCapabilityOverride = supportsMetricDistance
            maybeContinuePostLoginDeviceCheck(completedBinding)
        }
        val detail = when (depthSupport) {
            RuntimeMetricDepthSupport.SUPPORTED ->
                "Depth API 지원을 확인했습니다. 실제 거리 안내는 사용 중 유효한 거리 데이터가 확보된 경우에만 제공합니다."
            RuntimeMetricDepthSupport.UNSUPPORTED ->
                "이 기기는 Depth API를 지원하지 않습니다. 미터 단위 거리 안내가 제한됩니다."
            RuntimeMetricDepthSupport.UNKNOWN ->
                "Depth API 지원을 확인하지 못했습니다. 카메라 권한과 Google Play Services for AR 설치·업데이트 상태를 확인해 주세요."
        }
        updateStatus("Depth API 지원 확인", detail)
        refreshStartupCapabilityUi()
    }

    private fun startRuntimeMetricPreflightSession(
        preflightSession: Session,
        provider: ArCoreFrameProvider,
        generation: Long,
        lifecycleGeneration: Int,
    ) {
        if (!isRuntimeMetricPreflightAttemptCurrent(generation, lifecycleGeneration)) {
            preflightSession.close()
            return
        }
        val startedAtMs = SystemClock.elapsedRealtime()
        val evaluator = RuntimeMetricPreflightSession(
            generation = generation,
            startedAtElapsedRealtimeMs = startedAtMs,
            depthSupport = RuntimeMetricDepthSupport.SUPPORTED,
        )
        val resumeRenderer = pauseRendererForSessionClose()
        try {
            val textureBound = resumeArSessionBeforePublish(preflightSession)
            synchronized(runtimeMetricStateLock) {
                session = preflightSession
                frameProvider = provider
                arSessionPurpose = ArSessionPurpose.PREFLIGHT
                metricPreflightArSessionGeneration = ++arSessionGeneration
                runtimeMetricPreflightSession = evaluator
                metricPreflightTerminalDispatchedGeneration = 0L
                runtimeMetricOutputAllowed = false
                runtimeMetricInitialNavigationStartPending = false
                runtimeMetricLastFrameTimestampNanos = 0L
                cameraTextureBound = textureBound
            }
        } finally {
            resumeRendererAfterSessionClose(resumeRenderer)
        }
        arCoreSupported = true
        depthSupported = true
        syncActiveSessionScreenPolicy()
        updateStatus(
            "미터 거리 기능 확인 중",
            "보행 기능과 신고는 시작하지 않고 실제 Depth 프레임만 확인합니다.",
        )
        refreshStartupCapabilityUi()
        startupMetricPreflightButton.postDelayed(
            {
                val active = runtimeMetricPreflightSession
                if (
                    active != null &&
                    active.generation == generation &&
                    arSessionPurpose == ArSessionPurpose.PREFLIGHT
                ) {
                    val result = active.expire(SystemClock.elapsedRealtime())
                    if (result.status != RuntimeMetricPreflightStatus.IN_PROGRESS) {
                        finishRuntimeMetricPreflight(
                            result,
                            expectedArSessionGeneration = metricPreflightArSessionGeneration,
                            expectedLifecycleGeneration = lifecycleGeneration,
                        )
                    }
                }
            },
            RuntimeMetricPreflightPolicy.MAX_DURATION_MS,
        )
    }

    private fun finishRuntimeMetricPreflightWithoutSession(
        generation: Long,
        lifecycleGeneration: Int,
        depthSupport: RuntimeMetricDepthSupport,
    ) {
        if (!isRuntimeMetricPreflightAttemptCurrent(generation, lifecycleGeneration)) return
        val evaluator = RuntimeMetricPreflightSession(
            generation = generation,
            startedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
            depthSupport = depthSupport,
        )
        val result = if (depthSupport == RuntimeMetricDepthSupport.UNKNOWN) {
            evaluator.failTransiently(SystemClock.elapsedRealtime())
        } else {
            evaluator.result()
        }
        finishRuntimeMetricPreflight(
            result,
            expectedArSessionGeneration = null,
            expectedLifecycleGeneration = lifecycleGeneration,
        )
    }

    private fun isRuntimeMetricPreflightAttemptCurrent(
        generation: Long,
        lifecycleGeneration: Int,
    ): Boolean {
        val binding = metricPreflightPostLoginBinding ?: return false
        val ownerCurrent = when (metricPreflightOwner) {
            RuntimeMetricPreflightOwner.DEVICE_CHECK ->
                metricPreflightFirstRunLease?.let(::isFirstRunAsyncLeaseCurrent) == true &&
                    firstRunDeviceCheckAllowsPreflight()
            RuntimeMetricPreflightOwner.STORED_DEPTH_REFRESH ->
                storedMetricDepthRefreshContext?.let {
                    it.binding == binding &&
                        isStoredMetricDepthRefreshContextCurrent(it)
                } == true
            RuntimeMetricPreflightOwner.NONE -> false
        }
        return ownerCurrent &&
            isPostLoginDeviceCheckSnapshotBindingLive(binding) &&
            generation == runtimeMetricPreflightGeneration &&
            lifecycleGeneration == feedbackLifecycleGeneration &&
            lifecycleGeneration == metricPreflightLifecycleGeneration &&
            isActivityForeground &&
            !isFinishing &&
            !isDestroyed
    }

    private fun finishRuntimeMetricPreflight(
        result: RuntimeMetricPreflightResult,
        expectedArSessionGeneration: Long?,
        expectedLifecycleGeneration: Int,
    ) {
        val completedBinding = metricPreflightPostLoginBinding ?: return
        var completedOwner = RuntimeMetricPreflightOwner.NONE
        var acquisitionDiagnostics = "not_started"
        val currentSession = synchronized(runtimeMetricStateLock) {
            if (!isRuntimeMetricPreflightAttemptCurrent(result.generation, expectedLifecycleGeneration)) return
            if (
                expectedArSessionGeneration != null &&
                (
                    arSessionPurpose != ArSessionPurpose.PREFLIGHT ||
                        arSessionGeneration != expectedArSessionGeneration
                    )
            ) {
                return
            }
            completedOwner = metricPreflightOwner
            acquisitionDiagnostics = frameProvider?.preflightDiagnostics() ?: "not_started"
            val ownedSession = session
            session = null
            frameProvider?.close()
            frameProvider = null
            arSessionPurpose = ArSessionPurpose.NONE
            arSessionGeneration += 1
            runtimeMetricPreflightGeneration += 1
            runtimeMetricPreflightSession = null
            runtimeMetricActivationSession = null
            runtimeMetricOutputAllowed = false
            runtimeMetricInitialNavigationStartPending = false
            runtimeMetricLastValidFrameAtMs = 0L
            runtimeMetricLastFrameTimestampNanos = 0L
            metricPreflightArSessionGeneration = 0L
            pendingMetricPreflightPermissionGeneration = null
            metricPreflightFirstRunLease = null
            metricPreflightPostLoginBinding = null
            metricPreflightOwner = RuntimeMetricPreflightOwner.NONE
            ownedSession
        }
        val resumeRenderer = pauseRendererForSessionClose()
        if (currentSession != null) {
            runCatching { currentSession.pause() }
            currentSession.close()
        }
        cameraTextureBound = false
        arCoreSupported = false
        depthSupported = false
        syncActiveSessionScreenPolicy()
        resumeRendererAfterSessionClose(resumeRenderer)

        if (completedOwner == RuntimeMetricPreflightOwner.STORED_DEPTH_REFRESH) {
            android.util.Log.i(
                "WalkSafeDepthCheck",
                "owner=$completedOwner status=${result.status} reason=${result.reason} " +
                    "distinct=${result.distinctFrameCount} passing=${result.passingFrameCount} " +
                    "spanMs=${result.observationSpanMs} $acquisitionDiagnostics",
            )
            val saved = completeStoredMetricDepthRefresh(result.metricDistanceAvailable, completedBinding)
            if (saved) {
                val profileMatch = startupCapabilityProbe.deviceProfileMatch()
                persistRuntimeMetricPreflightResult(result, profileMatch)
                val detail = if (result.status == RuntimeMetricPreflightStatus.AVAILABLE) {
                    "저장된 다른 기기 점검 결과는 유지하고 미터 거리 기능만 사용할 수 있도록 갱신했습니다."
                } else {
                    "저장된 다른 기기 점검 결과는 유지하고 미터 거리 기능만 제한 상태로 갱신했습니다."
                }
                updateStatus("기기 거리 기능 자동 갱신 완료", detail)
            }
            refreshStartupCapabilityUi()
            return
        }
        if (completedOwner != RuntimeMetricPreflightOwner.DEVICE_CHECK) return
        metricDistanceCapabilityOverride = result.metricDistanceAvailable
        postLoginMetricPreflightStarted = false
        if (
            postLoginDeviceCheckSnapshot.state == PostLoginDeviceCheckState.RUNNING &&
            PostLoginDeviceCheckPolicy.isCurrent(postLoginDeviceCheckSnapshot, completedBinding)
        ) {
            postLoginMetricDepthState = when (result.status) {
                RuntimeMetricPreflightStatus.AVAILABLE -> PostLoginMetricDepthState.AVAILABLE
                RuntimeMetricPreflightStatus.UNSUPPORTED ->
                    PostLoginMetricDepthState.EXPLICITLY_UNSUPPORTED
                RuntimeMetricPreflightStatus.UNKNOWN -> if (
                    result.reason == RuntimeMetricPreflightReason.TIMEOUT
                ) {
                    PostLoginMetricDepthState.TIMED_OUT
                } else {
                    PostLoginMetricDepthState.UNKNOWN
                }
                RuntimeMetricPreflightStatus.IN_PROGRESS -> PostLoginMetricDepthState.PENDING
            }
            maybeContinuePostLoginDeviceCheck(completedBinding)
        }
        val profileMatch = startupCapabilityProbe.deviceProfileMatch()
        persistRuntimeMetricPreflightResult(result, profileMatch)
        refreshStartupCapabilityUi()
        val detail = when (result.status) {
            RuntimeMetricPreflightStatus.AVAILABLE ->
                "휴대폰 모델 목록이 아니라 실제 거리 프레임으로 미터 단위 측정 기능을 확인했습니다."
            RuntimeMetricPreflightStatus.UNSUPPORTED -> WALKSAFE_LIMITED_DISTANCE_NOTICE_KO
            RuntimeMetricPreflightStatus.UNKNOWN,
            RuntimeMetricPreflightStatus.IN_PROGRESS,
            -> "거리 기능을 확정할 수 없어 시작을 차단했습니다. 기기 상태를 확인한 뒤 다시 검사하세요."
        }
        updateStatus("기기 거리 기능 확인 완료", detail)
    }

    private fun invalidateRuntimeMetricEvidence(reason: String) {
        if (BuildConfig.DEBUG) runCatching {
            android.util.Log.d("WalkSafeNavigation", "output=metric_evidence_invalidated reason=$reason")
        }
        val runtimeFailureRequiresSafetyStop =
            reason.startsWith("runtime_") &&
                ::walkSessionLifecycle.isInitialized &&
                walkSessionLifecycle.snapshot().state == WalkSessionState.ACTIVE
        if (runtimeFailureRequiresSafetyStop) {
            transitionWalkSession(WalkSessionEvent.SafetyStopRequested)
            persistWalkSessionInterruptionMarker()
        }
        val invalidated = synchronized(runtimeMetricStateLock) {
            val wasPreflight = arSessionPurpose == ArSessionPurpose.PREFLIGHT
            val wasRuntime = arSessionPurpose == ArSessionPurpose.RUNTIME
            val snapshot = RuntimeMetricInvalidation(
                wasPreflight = wasPreflight,
                wasRuntime = wasRuntime,
                hadCameraFallback =
                    cameraFallbackRequested ||
                        cameraFallbackRunning ||
                        cameraFallbackCleanupPending ||
                        cameraFallbackCamera != null ||
                        cameraFallbackAfterRelease != null,
                hadAvailableEvidence = metricDistanceCapabilityOverride == true,
                evaluator = runtimeMetricPreflightSession,
                sessionToClose = session.takeIf { wasPreflight || wasRuntime },
            )
            runtimeMetricPreflightGeneration += 1
            pendingMetricPreflightPermissionGeneration = null
            metricPreflightFirstRunLease = null
            metricPreflightPostLoginBinding = null
            metricPreflightOwner = RuntimeMetricPreflightOwner.NONE
            runtimeMetricPreflightSession = null
            metricPreflightTerminalDispatchedGeneration = 0L
            metricPreflightArSessionGeneration = 0L
            runtimeMetricActivationSession = null
            runtimeMetricOutputAllowed = false
            runtimeMetricInitialNavigationStartPending = false
            runtimeMetricLastValidFrameAtMs = 0L
            runtimeMetricLastFrameTimestampNanos = 0L
            if (wasPreflight || wasRuntime) {
                session = null
                frameProvider?.close()
                frameProvider = null
                arSessionPurpose = ArSessionPurpose.NONE
                arSessionGeneration += 1
            }
            snapshot
        }
        invalidated.evaluator?.cancelForLifecycle(SystemClock.elapsedRealtime())
        cameraFallbackAfterRelease = null
        if (
            invalidated.wasRuntime ||
            invalidated.hadCameraFallback ||
            invalidated.hadAvailableEvidence ||
            runtimeFailureRequiresSafetyStop
        ) {
            feedbackLifecycleGeneration += 1
            invalidateArCoreAvailabilityRecheck()
            metricDistanceCapabilityOverride = null
            confirmedStartupCapabilityDecision = null
            startupCapabilityConfirmationPending = false
            startupCapabilityRetryRequiresUserAction = false
            pendingCameraFallbackStart = null
            cancelVoiceCommandRecognition()
            synchronized(reportUploadSafetyLock) {
                reportUploadSafetyGeneration += 1L
                reportPrivacyConsentSession.cancelActiveCalls()
            }
            val navigationCancellation = cancelNavigationRequestsForPause()
            clearActiveRouteRequestState(navigationCancellation.routeCancelled)
            clearDestinationSearchState(navigationCancellation.destinationSearchCancelled)
            resetRouteState()
            invalidateFrameStateForPause()
            clearExplicitReportFrameState("runtime_metric_unavailable")
            stopCameraFallbackSession(updateUi = false)
            stopLocationUpdates()
            stopStepTracking()
            if (::earthOrientationTracker.isInitialized) earthOrientationTracker.stop()
            feedbackPolicy.cancelPendingFeedbackDeliveries()
            if (::statusText.isInitialized) {
                pendingTalkBackInteraction?.let(statusText::removeCallbacks)
            }
            pendingTalkBackInteraction = null
            cancelPendingFeedbackTerminalResolution()
            latestFeedbackDeliveryState = FeedbackDeliveryState()
            feedbackActuator?.close()
            feedbackActuator = null
            if (runtimeFailureRequiresSafetyStop) {
                if (::cameraFallbackLifecycleOwner.isInitialized) {
                    cameraFallbackLifecycleOwner.moveTo(Lifecycle.State.CREATED)
                }
                if (::surfaceView.isInitialized) {
                    syncGlSurfaceRenderMode(forceFrame = true)
                    surfaceView.onPause()
                }
            }
            if (::fieldSessionLog.isInitialized && !invalidated.wasPreflight) {
                fieldSessionLog.recordEvent("runtime_metric_evidence_invalidated", mapOf("reason" to reason))
            }
        }
        val resumeRenderer = if (invalidated.sessionToClose != null) pauseRendererForSessionClose() else false
        invalidated.sessionToClose?.let { sessionToClose ->
            runCatching { sessionToClose.pause() }
            sessionToClose.close()
        }
        if (invalidated.sessionToClose != null) {
            cameraTextureBound = false
            arCoreSupported = false
            depthSupported = false
            syncActiveSessionScreenPolicy()
        }
        resumeRendererAfterSessionClose(resumeRenderer)

        if (::startupCapabilityText.isInitialized && isActivityForeground) {
            refreshStartupCapabilityUi()
        }
    }

    private fun pauseRendererForSessionClose(): Boolean {
        val shouldResume = isActivityForeground && ::surfaceView.isInitialized
        if (shouldResume) {
            syncGlSurfaceRenderMode(forceFrame = true)
            surfaceView.onPause()
        }
        return shouldResume
    }

    private fun resumeRendererAfterSessionClose(shouldResume: Boolean) {
        val rendererRequired =
            isActivityForeground &&
                session != null &&
                arSessionPurpose != ArSessionPurpose.NONE
        if (shouldResume && rendererRequired && !isFinishing && !isDestroyed) {
            surfaceView.onResume()
        }
        syncGlSurfaceRenderMode(forceFrame = true)
    }

    private fun syncGlSurfaceRenderMode(
        forceFrame: Boolean = false,
        allowContinuousRendering: Boolean = true,
    ) {
        if (!::surfaceView.isInitialized) return
        val continuousRenderingRequired =
            allowContinuousRendering &&
                isActivityForeground &&
                session != null &&
                arSessionPurpose != ArSessionPurpose.NONE
        val targetRenderMode = if (continuousRenderingRequired) {
            GLSurfaceView.RENDERMODE_CONTINUOUSLY
        } else {
            GLSurfaceView.RENDERMODE_WHEN_DIRTY
        }
        val renderModeChanged = surfaceView.renderMode != targetRenderMode
        if (renderModeChanged) {
            surfaceView.renderMode = targetRenderMode
        }
        if (forceFrame || renderModeChanged) {
            surfaceView.requestRender()
        }
    }

    private fun handleStartupCapabilityConfirmAction() {
        val session = walkSessionLifecycle.snapshot()
        val preparesNewWalk = session.state in setOf(
            WalkSessionState.SAFE_STOP,
            WalkSessionState.ENDED,
        )
        startupCapabilityRetryRequiresUserAction = false
        if (session.state == WalkSessionState.PAUSED) {
            walkSessionResumePromptPending = false
            walkSessionResumeRetryRequiresUserAction = false
        }
        if (preparesNewWalk) {
            startFreshWalk("user_requested_after_${session.state.name.lowercase(Locale.US)}")
            refreshStartupCapabilityUi()
            return
        }
        if (resumePermissionRecoveryFromExplicitUserAction()) return
        when (session.state) {
            WalkSessionState.PAUSED -> {
                if (session.recoveryStage == WalkSessionRecoveryStage.RECHECK_REQUIRED) {
                    refreshStartupCapabilityUi()
                } else if (isStartupCapabilityConfirmed()) {
                    if (voiceResumeConfirmationAvailable()) {
                        refreshStartupCapabilityUi()
                    } else {
                        confirmWalkSessionResumeFromButton()
                    }
                } else {
                    confirmStartupCapabilityDecision()
                }
            }
            else -> confirmStartupCapabilityDecision()
        }
    }

    private fun confirmStartupCapabilityDecision() {
        val decision = startupCapabilityDecision ?: return
        if (!decision.mayConfirmAndStart || startupCapabilityConfirmationPending) return
        val blockReason = walkSessionReadinessBlockReason(decision)
        if (blockReason != null) {
            maybeRequestMissingWalkSessionPermissions(decision)
            updateStatus("보행 시작 대기", blockReason)
            return
        }
        if (walkSessionLifecycle.snapshot().confirmationToken == null) {
            updateStatus(
                "보행 시작 대기",
                "같은 보행 점검 세대의 필수 기능 확인이 끝나지 않았습니다.",
            )
            return
        }
        startupCapabilityConfirmationPending = true
        refreshStartupCapabilityUi()
        val accepted = deliverStartupCapabilityNotice(
            decision = decision,
            onDelivered = { completeStartupCapabilityConfirmation(decision) },
            onFailed = { failStartupCapabilityConfirmation(decision) },
        )
        if (!accepted) failStartupCapabilityConfirmation(decision)
    }

    private fun deliverStartupCapabilityNotice(
        decision: WalkSafeStartupCapabilityDecision,
        onDelivered: () -> Unit,
        onFailed: () -> Unit,
    ): Boolean {
        if (!isActivityForeground || startupCapabilityDecision != decision) return false
        val generation = feedbackLifecycleGeneration
        val deliveredOnMain = {
            runOnUiThread {
                if (isFeedbackLifecycleCurrent(generation)) onDelivered()
            }
        }
        val failedOnMain = {
            runOnUiThread {
                if (feedbackLifecycleGeneration == generation) onFailed()
            }
        }
        return ensureFeedbackActuator().speakInteraction(
            message = decision.noticeKo,
            onCompleted = deliveredOnMain,
            onFailed = failedOnMain,
        ) == NavigationSpeechDispatchResult.ACCEPTED
    }

    private fun completeStartupCapabilityConfirmation(expected: WalkSafeStartupCapabilityDecision) {
        if (!isActivityForeground || startupCapabilityDecision != expected) {
            startupCapabilityConfirmationPending = false
            refreshStartupCapabilityUi()
            return
        }
        startupCapabilityConfirmationPending = false
        startupCapabilityRetryRequiresUserAction = false
        confirmedStartupCapabilityDecision = expected
        refreshStartupCapabilityUi()
    }

    private fun failStartupCapabilityConfirmation(expected: WalkSafeStartupCapabilityDecision) {
        if (startupCapabilityDecision != expected || !startupCapabilityConfirmationPending) return
        startupCapabilityConfirmationPending = false
        confirmedStartupCapabilityDecision = null
        startupCapabilityRetryRequiresUserAction = true
        refreshStartupCapabilityUi()
        updateStatus(
            "안전 제한 안내 확인 필요",
            "필수 안내가 전달되지 않았습니다. 음성 기능을 확인한 뒤 다시 시도하세요.",
        )
    }

    private fun persistStartupCapabilityDecision(decision: WalkSafeStartupCapabilityDecision) {
        if (developmentQuickStartEnabled || developmentGuidanceStartBypassEnabled) return
        if (lastPersistedStartupCapabilityDecision == decision) return
        lastPersistedStartupCapabilityDecision = decision
        val profileMatch = startupCapabilityProbe.deviceProfileMatch()
        stepLengthPrefs.edit()
            .putString("startup_capability_tier", decision.tier.name)
            .putString(
                "startup_capability_unavailable",
                decision.unavailableRequirements.joinToString(",") { it.name },
            )
            .putString(
                "startup_capability_pending",
                decision.pendingRequirements.joinToString(",") { it.name },
            )
            .putString("startup_capability_device_model", Build.MODEL)
            .putString("startup_capability_android_version", Build.VERSION.RELEASE)
            .putString("startup_capability_app_version", BuildConfig.VERSION_NAME)
            .putString("startup_capability_source_commit", BuildConfig.WALKSAFE_SOURCE_COMMIT)
            .putString(
                "startup_capability_device_profile_status",
                if (profileMatch.approved) {
                    "APPROVED_DESIGNATED_DEVICE_PROFILE"
                } else {
                    WALKSAFE_DEVICE_PROFILE_POLICY_STATUS
                },
            )
            .putString("startup_capability_device_profile_id", profileMatch.profileId)
            .putString(
                "startup_capability_device_profile_version",
                profileMatch.profileVersion,
            )
            .putString("startup_capability_device_profile_reason", profileMatch.reason.name)
            .putLong("startup_capability_evaluated_at_epoch_ms", System.currentTimeMillis())
            .apply()
    }

    private fun persistRuntimeMetricPreflightResult(
        result: RuntimeMetricPreflightResult,
        profileMatch: ApprovedDeviceProfileMatch,
    ) {
        stepLengthPrefs.edit()
            .putString("runtime_metric_preflight_policy", RUNTIME_METRIC_PREFLIGHT_POLICY_VERSION)
            .putString("runtime_metric_preflight_status", result.status.name)
            .putString("runtime_metric_preflight_reason", result.reason.name)
            .putLong("runtime_metric_preflight_generation", result.generation)
            .putInt("runtime_metric_preflight_distinct_frames", result.distinctFrameCount)
            .putInt("runtime_metric_preflight_passing_frames", result.passingFrameCount)
            .putLong("runtime_metric_preflight_observation_span_ms", result.observationSpanMs)
            .putLong(
                "runtime_metric_preflight_completed_at_elapsed_ms",
                result.completedAtElapsedRealtimeMs ?: -1L,
            )
            .putLong("runtime_metric_preflight_recorded_at_epoch_ms", System.currentTimeMillis())
            .putString("runtime_metric_preflight_app_version", BuildConfig.VERSION_NAME)
            .putString("runtime_metric_preflight_source_commit", BuildConfig.WALKSAFE_SOURCE_COMMIT)
            .putString("runtime_metric_preflight_device_manufacturer", Build.MANUFACTURER)
            .putString("runtime_metric_preflight_device_model", Build.MODEL)
            .putString("runtime_metric_preflight_device_code", Build.DEVICE)
            .putInt("runtime_metric_preflight_android_sdk", Build.VERSION.SDK_INT)
            .putBoolean("runtime_metric_preflight_profile_approved", profileMatch.approved)
            .putString("runtime_metric_preflight_profile_id", profileMatch.profileId)
            .putString("runtime_metric_preflight_profile_version", profileMatch.profileVersion)
            .putString("runtime_metric_preflight_profile_reason", profileMatch.reason.name)
            .putString(
                "runtime_metric_preflight_profile_registry_id",
                WalkSafeApprovedDeviceProfiles.REGISTRY_ID,
            )
            .putString(
                "runtime_metric_preflight_profile_registry_revision",
                WalkSafeApprovedDeviceProfiles.REGISTRY_REVISION,
            )
            .putString(
                "runtime_metric_preflight_profile_registry_sha256",
                WalkSafeApprovedDeviceProfiles.registryContentSha256,
            )
            .apply()
    }

    private fun isStartupCapabilityConfirmed(): Boolean {
        val decision = startupCapabilityDecision ?: return false
        if (developmentGuidanceStartBypassEnabled && firstRunOnboardingComplete() &&
            currentReporterUserId() != null) return true
        return decision.mayConfirmAndStart && confirmedStartupCapabilityDecision == decision
    }

    private fun requireStartupCapabilityConfirmation(): Boolean {
        refreshStartupCapabilityUi()
        if (isStartupCapabilityConfirmed()) return true
        return false
    }

    private fun ensurePermissionsThenStart() {
        if (cameraFallbackCleanupPending) {
            stopCameraFallbackSession(
                updateUi = false,
                onReleased = ::ensurePermissionsThenStart,
            )
            return
        }
        if (!requireFirstRunOnboardingComplete("runtime_start")) return
        if (!requireStartupCapabilityConfirmation()) return
        if (!requireReporterUserId("login_required_depth_start")) return
        if (!cameraAnalysisFeaturesEnabled()) {
            startWalkSessionRuntimeWithoutCamera()
            return
        }
        if (runtimeCameraStartBlockedByAnotherOwner()) return
        val missing = missingCameraPermissions()
        if (missing.isEmpty()) {
            startConfirmedRuntimeAfterCameraPermission()
            return
        }
        requestPermissionsWithLease(
            missing.toTypedArray(),
            PermissionRequestPurpose.RUNTIME_CAMERA,
        )
    }

    private fun startConfirmedRuntimeAfterCameraPermission() {
        if (!isWalkSessionRuntimeActive()) return
        if (!requireStartupCapabilityConfirmation()) return
        if (!cameraAnalysisFeaturesEnabled()) {
            startWalkSessionRuntimeWithoutCamera()
            return
        }
        val pendingFallback = pendingCameraFallbackStart
        if (pendingFallback != null) {
            pendingCameraFallbackStart = null
            startCameraFallbackSession(pendingFallback.reason, pendingFallback.availability)
            return
        }
        if (startupCapabilityDecision?.allowsMetricDistance() != true) {
            val availability = runCatching {
                ArCoreApk.getInstance().checkAvailability(this)
            }.getOrDefault(ArCoreApk.Availability.UNKNOWN_ERROR)
            startCameraFallbackSession(CameraFallbackStartReason.CAPABILITY_DISTANCE_UNAVAILABLE, availability)
            return
        }
        startDepthSession()
    }

    private fun currentReporterUserId(): String? {
        if (developmentQuickStartEnabled) return developmentQuickStartSessionOrNull()?.actorId
        if (!firstRunOnboardingComplete()) return null
        val verifiedActorId =
            firstRunOnboardingSnapshot.reporterActorBinding?.value ?: return null
        if (!::priorityUserOnboardingPolicy.isInitialized) return null
        return reporterUserId.takeIf {
            it == verifiedActorId &&
            priorityUserOnboardingActorId == it &&
                priorityUserOnboardingPolicy.accountBlockReason() == null
        }
    }

    private fun accountDeletionRev0RecoveryBindingOrNull(
        requireReauthentication: Boolean = true,
    ): AccountDeletionRev0RecoveryBinding? {
        if (!::sensitivePrefs.isInitialized || !::stepLengthPrefs.isInitialized) {
            return null
        }
        return runCatching {
            exactAccountDeletionRev0RecoveryBindingOrNull(
                journal = accountDeletionStateMachine.snapshotOrNull(),
                markerState = accountDeletionStartupFallbackState,
                configuredGatewayOrigin = configuredGatewayOriginOrNull(),
                persistedActorHash = sensitivePrefs.getString(
                    PREF_ACCOUNT_DELETION_ACTOR_HASH,
                    null,
                ),
                authorityConfirmed =
                    accountDeletionAuthorityAtStartup.aggregateState ==
                    AccountDeletionAggregateAuthorityState.CONFIRMED &&
                        accountDeletionAuthorityAtStartup.fileState ==
                        AccountDeletionIntentAuthorityState.Confirmed,
                sensitiveFenceConfirmed =
                    sensitivePrefs.getBoolean(
                        PREF_ACCOUNT_DELETION_FAIL_CLOSED_MARKER,
                        false,
                    ) &&
                        !sensitivePrefs.contains(
                            PREF_ACCOUNT_DELETION_FAIL_CLOSED_REASON,
                        ),
                remoteResumeBlocked = accountDeletionRemoteResumeBlocked,
                reauthenticationRequestId =
                    accountDeletionRev0ReauthenticationRequestId,
                requireReauthentication = requireReauthentication,
            )
        }.getOrNull()
    }

    private fun accountDeletionRecoveryLoginRequired(): Boolean =
        accountDeletionStateMachine.durableConfirmationRecoveryRequired() ||
            accountDeletionRev0RecoveryBindingOrNull() != null ||
            accountDeletionLegacyRev0ActorCandidateOrNull() != null

    private fun activateAccountDeletionRev0Reauthentication(
        workerAttempt: AccountDeletionWorkerAttempt,
    ): Boolean {
        val binding =
            accountDeletionRev0RecoveryBindingOrNull(
                requireReauthentication = false,
            ) ?: return false
        if (
            workerAttempt.gatewayOrigin != binding.journal.gatewayOrigin ||
            workerAttempt.installationId != binding.journal.installationId ||
            workerAttempt.requestId != binding.journal.requestId
        ) return false
        accountDeletionRev0ReauthenticationRequestId = binding.journal.requestId
        return accountDeletionRev0RecoveryBindingOrNull() == binding
    }

    private fun bindLegacyAccountDeletionRev0RecoveryActor(
        workerAttempt: AccountDeletionWorkerAttempt,
    ): Boolean {
        if (!::sensitivePrefs.isInitialized || !::stepLengthPrefs.isInitialized) {
            return false
        }
        val processSnapshot = GatewaySessionProcessCoordinator.snapshot()
        val binding = runCatching {
            exactLegacyAccountDeletionRev0ActorBindingOrNull(
                journal = accountDeletionStateMachine.snapshotOrNull(),
                markerState = accountDeletionStartupFallbackState,
                configuredGatewayOrigin = configuredGatewayOriginOrNull(),
                persistedActorHash = sensitivePrefs.getString(
                    PREF_ACCOUNT_DELETION_ACTOR_HASH,
                    null,
                ),
                authorityConfirmed =
                    accountDeletionAuthorityAtStartup.aggregateState ==
                    AccountDeletionAggregateAuthorityState.CONFIRMED &&
                        accountDeletionAuthorityAtStartup.fileState ==
                        AccountDeletionIntentAuthorityState.Confirmed,
                sensitiveFenceConfirmed =
                    sensitivePrefs.getBoolean(
                        PREF_ACCOUNT_DELETION_FAIL_CLOSED_MARKER,
                        false,
                    ) &&
                        !sensitivePrefs.contains(
                            PREF_ACCOUNT_DELETION_FAIL_CLOSED_REASON,
                        ),
                remoteResumeBlocked = accountDeletionRemoteResumeBlocked,
                liveActorId = currentReporterUserId(),
                session = processSnapshot.session,
                processSession = processSnapshot.session,
                deletionRecoveryOnly = processSnapshot.deletionRecoveryOnly,
                storageBlocked = processSnapshot.storageBlocked,
            )
        }.getOrNull() ?: return false
        if (
            workerAttempt.gatewayOrigin != binding.journal.gatewayOrigin ||
            workerAttempt.installationId != binding.journal.installationId ||
            workerAttempt.requestId != binding.journal.requestId
        ) return false
        val boundRecord = binding.markerRecord.copy(
            recoveryActorId = binding.actorId,
        )
        val persisted = runAccountDeletionWorkerDurableStage(workerAttempt) {
            accountDeletionFallbackMarker.update(boundRecord) &&
                accountDeletionFallbackMarker.read() ==
                AndroidAccountDeletionFallbackMarker.State.Present(boundRecord)
        } ?: return false
        if (!persisted) return false
        accountDeletionStartupFallbackState =
            AndroidAccountDeletionFallbackMarker.State.Present(boundRecord)
        accountDeletionLegacyRev0GeneralReauthenticationRequestId = null
        accountDeletionRev0ReauthenticationRequestId = binding.journal.requestId
        val recovered = accountDeletionRev0RecoveryBindingOrNull() ?: return false
        val exactRecovered = recovered.journal == binding.journal &&
            recovered.markerRecord == boundRecord &&
            recovered.actorId == binding.actorId
        if (exactRecovered && processSnapshot.session != null) {
            clearGatewaySession(
                logoutRemote = true,
                expectedSession = processSnapshot.session,
                expectedActivityLease = accountDeletionActivityLease,
            )
        }
        return exactRecovered
    }

    private fun handleLegacyAccountDeletionRev0NotFound(
        workerAttempt: AccountDeletionWorkerAttempt,
    ): Boolean {
        val markerBinding = accountDeletionLegacyRev0MarkerBindingOrNull()
            ?: return false
        if (
            workerAttempt.gatewayOrigin != markerBinding.journal.gatewayOrigin ||
            workerAttempt.installationId != markerBinding.journal.installationId ||
            workerAttempt.requestId != markerBinding.journal.requestId
        ) return false
        val actorBinding = accountDeletionLegacyRev0ActorCandidateOrNull(
            requireReauthentication = false,
        )
        if (actorBinding != null) {
            accountDeletionLegacyRev0GeneralReauthenticationRequestId =
                actorBinding.journal.requestId
            return accountDeletionLegacyRev0ActorCandidateOrNull() == actorBinding
        }
        accountDeletionLegacyRev0GeneralReauthenticationRequestId = null
        runAccountDeletionWorkerTerminalStage(
            workerAttempt,
            "account_deletion_legacy_reauthentication_identity_unavailable",
        ) ?: return true
        integratedConsentSession.failClosed()
        postAccountDeletionUiRefresh()
        return true
    }

    private fun accountDeletionLegacyRev0MarkerBindingOrNull() =
        if (!::sensitivePrefs.isInitialized || !::stepLengthPrefs.isInitialized) {
            null
        } else {
            runCatching {
                exactLegacyAccountDeletionRev0MarkerBindingOrNull(
                    journal = accountDeletionStateMachine.snapshotOrNull(),
                    markerState = accountDeletionStartupFallbackState,
                    configuredGatewayOrigin = configuredGatewayOriginOrNull(),
                    persistedActorHash = sensitivePrefs.getString(
                        PREF_ACCOUNT_DELETION_ACTOR_HASH,
                        null,
                    ),
                    authorityConfirmed =
                        accountDeletionAuthorityAtStartup.aggregateState ==
                        AccountDeletionAggregateAuthorityState.CONFIRMED &&
                            accountDeletionAuthorityAtStartup.fileState ==
                            AccountDeletionIntentAuthorityState.Confirmed,
                    sensitiveFenceConfirmed =
                        sensitivePrefs.getBoolean(
                            PREF_ACCOUNT_DELETION_FAIL_CLOSED_MARKER,
                            false,
                        ) &&
                            !sensitivePrefs.contains(
                                PREF_ACCOUNT_DELETION_FAIL_CLOSED_REASON,
                            ),
                    remoteResumeBlocked = accountDeletionRemoteResumeBlocked,
                )
            }.getOrNull()
        }

    private fun accountDeletionLegacyRev0ActorCandidateOrNull(
        requireReauthentication: Boolean = true,
    ) = accountDeletionLegacyRev0MarkerBindingOrNull()?.let { markerBinding ->
        if (
            requireReauthentication &&
            accountDeletionLegacyRev0GeneralReauthenticationRequestId !=
            markerBinding.journal.requestId
        ) return@let null
        exactLegacyAccountDeletionRev0ActorCandidateOrNull(
            journal = markerBinding.journal,
            markerState = AndroidAccountDeletionFallbackMarker.State.Present(
                markerBinding.markerRecord,
            ),
            configuredGatewayOrigin = configuredGatewayOriginOrNull(),
            persistedActorHash = markerBinding.markerRecord.identity.actorHash,
            authorityConfirmed = true,
            sensitiveFenceConfirmed = true,
            remoteResumeBlocked = false,
            liveActorId = currentReporterUserId(),
        )
    }

    private fun retainAccountDeletionRev0ReauthenticationAfterSessionFailure(
        workerAttempt: AccountDeletionWorkerAttempt,
    ): Boolean {
        val binding = accountDeletionRev0RecoveryBindingOrNull() ?: return false
        return workerAttempt.gatewayOrigin == binding.journal.gatewayOrigin &&
            workerAttempt.installationId == binding.journal.installationId &&
            workerAttempt.requestId == binding.journal.requestId
    }

    private fun clearAccountDeletionRev0RecoverySessionIfCurrent() {
        val binding = accountDeletionRev0RecoveryBindingOrNull() ?: return
        val snapshot = GatewaySessionProcessCoordinator.snapshot()
        val session = snapshot.session ?: return
        if (
            snapshot.deletionRecoveryOnly &&
            session.sessionScope == GatewaySessionScope.ACCOUNT_DELETION_RECOVERY &&
            session.actorId == binding.actorId &&
            session.gatewayBaseUrl == binding.journal.gatewayOrigin
        ) {
            GatewaySessionProcessCoordinator.clear(snapshot.generation)
        }
    }

    private fun completeAccountDeletionRev0ReauthenticationAfterAcceptance(
        journal: AccountDeletionJournal,
    ) {
        if (journal.serverRevision <= 0L) return
        val snapshot = GatewaySessionProcessCoordinator.snapshot()
        val exactRecoverySession = isExactAcceptedRev0RecoverySessionRetirement(
            journal = journal,
            markerState = accountDeletionStartupFallbackState,
            persistedActorHash = sensitivePrefs.getString(
                PREF_ACCOUNT_DELETION_ACTOR_HASH,
                null,
            ),
            session = snapshot.session,
            processSession = snapshot.session,
            deletionRecoveryOnly = snapshot.deletionRecoveryOnly,
        )
        if (
            accountDeletionRev0ReauthenticationRequestId != journal.requestId &&
            !exactRecoverySession
        ) return
        accountDeletionRev0ReauthenticationRequestId = null
        accountDeletionLegacyRev0GeneralReauthenticationRequestId = null
        if (exactRecoverySession) {
            GatewaySessionProcessCoordinator.clear(snapshot.generation)
        }
    }

    private fun accountDeletionRecoveryActorIdOrNull(): String? {
        accountDeletionLegacyRev0ActorCandidateOrNull()?.let { return it.actorId }
        accountDeletionRev0RecoveryBindingOrNull()?.let { return it.actorId }
        if (!accountDeletionStateMachine.durableConfirmationRecoveryRequired()) {
            return null
        }
        val preparedRecord =
            (accountDeletionStartupFallbackState
                as? AndroidAccountDeletionFallbackMarker.State.Present)
                ?.record
                ?.takeIf {
                    it.phase == AndroidAccountDeletionFallbackMarker.Phase.PREPARED &&
                        it.gatewayOrigin == configuredGatewayOriginOrNull()
                }
        preparedRecord?.recoveryActorId?.let { actorId ->
            if (
                sha256Hex(actorId.toByteArray(Charsets.UTF_8)) ==
                preparedRecord.identity.actorHash
            ) return actorId
        }
        if (
            ::firstRunOnboardingSnapshot.isInitialized &&
            firstRunOnboardingSnapshot.isComplete &&
            ::priorityUserOnboardingPolicy.isInitialized
        ) {
            val liveActorId = firstRunOnboardingSnapshot.reporterActorBinding?.value
            if (
                liveActorId != null &&
                reporterUserId == liveActorId &&
                priorityUserOnboardingActorId == liveActorId &&
                priorityUserOnboardingPolicy.accountBlockReason() == null &&
                (
                    preparedRecord == null ||
                        sha256Hex(liveActorId.toByteArray(Charsets.UTF_8)) ==
                        preparedRecord.identity.actorHash
                    )
            ) return liveActorId
        }
        return null
    }

    private fun gatewayLoginActorIdOrNull(): String? =
        if (accountDeletionRecoveryLoginRequired()) {
            accountDeletionRecoveryActorIdOrNull()
        } else {
            currentReporterUserId()
        }

    private fun isAccountDeletionRecoveryLoginTarget(
        actorId: String,
        gatewayBaseUrl: String,
    ): Boolean {
        if (accountDeletionLegacyRev0ActorCandidateOrNull() != null) return false
        return accountDeletionStateMachine.processingBlocked() &&
            accountDeletionRecoveryLoginRequired() &&
            accountDeletionRecoveryActorIdOrNull() == actorId &&
            configuredGatewayOriginOrNull() == gatewayBaseUrl
    }

    private fun accountDeletionRecoveryGatewaySessionOrNull(
        session: GatewayFieldSession? = GatewaySessionProcessCoordinator.snapshot().session,
        speak: Boolean = false,
    ): GatewayFieldSession? {
        val rev0Recovery = accountDeletionRev0RecoveryBindingOrNull()
        val durableConfirmationRecovery =
            accountDeletionStateMachine.durableConfirmationRecoveryRequired()
        val actorId = accountDeletionRecoveryActorIdOrNull()
        val processSnapshot = GatewaySessionProcessCoordinator.snapshot()
        val trustedOrigin = configuredGatewayOriginOrNull()
        val ready =
            accountDeletionStateMachine.processingBlocked() &&
                (durableConfirmationRecovery || rev0Recovery != null) &&
            actorId != null &&
                !processSnapshot.storageBlocked &&
                session != null &&
                processSnapshot.session === session &&
                (
                    if (rev0Recovery != null) {
                        isExactAccountDeletionRev0RecoverySessionReady(
                            binding = rev0Recovery,
                            session = session,
                            processSession = processSnapshot.session,
                            deletionRecoveryOnly =
                                processSnapshot.deletionRecoveryOnly,
                            storageBlocked = processSnapshot.storageBlocked,
                        )
                    } else {
                        (
                            processSnapshot.deletionRecoveryOnly &&
                                session.sessionScope ==
                                GatewaySessionScope.ACCOUNT_DELETION_RECOVERY
                            ) ||
                            (
                            !processSnapshot.deletionRecoveryOnly &&
                                session.sessionScope == GatewaySessionScope.GENERAL &&
                                currentReporterUserId() == actorId
                            )
                    }
                    ) &&
                session.verificationState == GatewaySessionVerificationState.VERIFIED &&
                session.isUsableFor(actorId) &&
                session.gatewayBaseUrl == trustedOrigin
        if (ready) return session
        if (speak) {
            updateNavigationStatus(
                "gateway=session_required reason=account_deletion_recovery",
            )
            speakInteraction("현장 게이트웨이에 다시 로그인하세요.")
        }
        return null
    }

    private fun requireReporterUserId(reason: String): Boolean {
        if (currentReporterUserId() != null) return true
        updateNavigationStatus("login=required reason=$reason")
        speakInteraction("로그인이 필요합니다.")
        return false
    }

    private fun gatewaySessionOrNull(reason: String, speak: Boolean = true): GatewayFieldSession? {
        val session = gatewayFieldSession
        if (isGatewaySessionReadyForCurrentActor(session)) return session
        if (session != null) clearExpiredGatewaySessionIfCurrent(session)
        if (speak) {
            updateNavigationStatus("gateway=session_required reason=$reason")
            speakInteraction("현장 게이트웨이에 먼저 로그인하세요.")
        }
        return null
    }

    private fun ensureNavigationPermissions(requireActivityRecognition: Boolean) {
        val missing = mutableListOf<String>()
        if (!hasLocationPermission()) {
            missing += Manifest.permission.ACCESS_FINE_LOCATION
            missing += Manifest.permission.ACCESS_COARSE_LOCATION
        }
        if (
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q &&
            requireActivityRecognition &&
            !hasActivityRecognitionPermission()
        ) {
            updateNavigationStatus(
                "navigation=activity_recognition_permission_missing step_tracking_limited",
            )
        }
        if (missing.isEmpty()) return
        requestPermissionsWithLease(
            missing.toTypedArray(),
            PermissionRequestPurpose.NAVIGATION,
        )
    }

    private fun ensureNavigationPermissionForRouteOrStep(): Boolean {
        navigationPermissionsRequestedForRoute = true
        if (isRouteLocationPermissionReady()) return true
        ensureNavigationPermissions(requireActivityRecognition = true)
        return false
    }

    private fun ensureNavigationPermissionForReport(): Boolean {
        if (!postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE)) {
            updateNavigationStatus("report_location=device_feature_limited")
            return false
        }
        navigationPermissionsRequestedForReport = true
        if (hasLocationPermission()) return true
        ensureNavigationPermissions(requireActivityRecognition = false)
        return false
    }

    private fun startNavigationServicesIfNeeded() {
        if (!currentLocationCollectionAllowsWork()) {
            stopLocationUpdates()
        } else {
            startLocationUpdatesIfAllowed()
        }
        if (!currentStepTrackingCollectionAllowsWork()) {
            stopStepTracking()
            return
        }
        val fieldSessionActive = isFieldSessionActive()
        if (isRouteActive || navigationPermissionsRequestedForRoute || navigationPermissionsRequestedForReport || fieldSessionActive) {
            if (isRouteActive || navigationPermissionsRequestedForRoute || fieldSessionActive) {
                startStepTrackingIfAllowed()
            }
        }
    }

    private fun currentLocationCollectionAllowsWork(): Boolean {
        return currentLocationCollectionOwnerOrNull() != null
    }

    private fun currentLocationCollectionOwnerOrNull(): LocationCollectionOwner? {
        if (!isActivityForeground || !hasLocationPermission()) return null
        if (!isLocationServiceEnabledForDeviceCheck()) return null
        val process = GatewaySessionProcessCoordinator.snapshot()
        if (
            process.storageBlocked || process.deletionRecoveryOnly ||
            accountDeletionStateMachine.processingBlocked()
        ) return null
        val session = process.session
        val actorId = if (developmentQuickStartEnabled) {
            developmentQuickStartSessionOrNull()?.actorId
        } else {
            firstRunOnboardingSnapshot.verifiedActorBinding?.value
        }
        if (
            actorId != null && session != null &&
            session.actorId == actorId &&
            session.sessionScope == GatewaySessionScope.GENERAL &&
            session.verificationState == GatewaySessionVerificationState.VERIFIED &&
            session.isUsableFor(actorId)
        ) {
            return LocationCollectionOwner(actorId, session, process.generation)
        }
        if (!currentPositionFieldCollectionAllowsWork()) return null
        return LocationCollectionOwner(
            actorId = null,
            gatewaySession = session,
            gatewayGeneration = process.generation,
            fieldWalkEpoch = positionFieldWalkEpoch,
            fieldScopeId = positionFieldLeaseScopeId,
        )
    }

    private fun currentStepTrackingCollectionAllowsWork(): Boolean {
        if (currentPositionFieldCollectionAllowsWork()) return true
        if (!firstRunOnboardingComplete()) return false
        if (!isWalkSessionRuntimeActive()) return false
        if (!isStartupCapabilityConfirmed()) return false
        if (!navigationEnvironmentOutputsAllowed()) return false
        return true
    }

    private fun currentNavigationCollectionAllowsWork(): Boolean {
        if (!postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE)) return false
        return currentStepTrackingCollectionAllowsWork()
    }

    private fun currentPositionFieldCollectionAllowsWork(): Boolean {
        if (!BuildConfig.DEBUG || positionFieldStorageBlocked || positionFieldLease == null) return false
        if (!isActivityForeground || !isWalkSessionRuntimeActive() || !hasLocationPermission()) return false
        val currentEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull()
        val currentGatewayGeneration = GatewaySessionProcessCoordinator.snapshot().generation
        return currentEpoch == positionFieldWalkEpoch &&
            currentGatewayGeneration == positionFieldGatewayGeneration &&
            positionFieldLocalScopeId != null &&
            positionFieldLocalScopeId == positionFieldLeaseScopeId
    }

    private fun missingCameraPermissions(): List<String> {
        val permissions = mutableListOf(
            Manifest.permission.CAMERA.takeIf { !hasCameraPermission() },
        )
        return permissions.filterNotNull()
    }

    private fun currentObservedPermissionSnapshot(): ObservedPermissionSnapshot =
        ObservedPermissionSnapshot(
            cameraGranted = hasCameraPermission(),
            preciseLocationGranted = hasLocationPermission(),
            microphoneGranted = hasRecordAudioPermission(),
            activityRecognitionGranted = hasActivityRecognitionPermission(),
        )

    private fun requiredStartWalkObservedPermissions(): Set<ObservedPermission> = buildSet {
        if (cameraAnalysisFeaturesEnabled()) add(ObservedPermission.CAMERA)
        if (
            postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.LOCATION_GUIDANCE)
        ) {
            add(ObservedPermission.PRECISE_LOCATION)
        }
    }

    private fun String.toObservedPermission(): ObservedPermission? = when (this) {
        Manifest.permission.CAMERA -> ObservedPermission.CAMERA
        Manifest.permission.ACCESS_FINE_LOCATION,
        Manifest.permission.ACCESS_COARSE_LOCATION,
        -> ObservedPermission.PRECISE_LOCATION
        Manifest.permission.RECORD_AUDIO -> ObservedPermission.MICROPHONE
        Manifest.permission.ACTIVITY_RECOGNITION -> ObservedPermission.ACTIVITY_RECOGNITION
        else -> null
    }

    private fun ObservedPermission.labelKo(): String = when (this) {
        ObservedPermission.CAMERA -> "카메라"
        ObservedPermission.PRECISE_LOCATION -> "정확한 위치"
        ObservedPermission.MICROPHONE -> "마이크"
        ObservedPermission.ACTIVITY_RECOGNITION -> "보행 센서"
    }

    private fun ObservedPermission.denialReasonKo(): String = when (this) {
        ObservedPermission.CAMERA ->
            "장애물 인식·미터 거리 안내와 카메라 기반 신고 전송을 사용할 수 없습니다."
        ObservedPermission.PRECISE_LOCATION ->
            "위치·경로 안내와 위치가 필요한 신고 전송을 사용할 수 없습니다."
        ObservedPermission.MICROPHONE -> "음성 명령과 음성 재개 확인을 사용할 수 없습니다."
        ObservedPermission.ACTIVITY_RECOGNITION ->
            "걸음 수 추적과 정지 확인 후 대기 신고 자동 전송을 사용할 수 없습니다."
    }

    private fun persistPermissionRecoveryGate() {
        val editor = stepLengthPrefs.edit()
        if (permissionRecoveryGate.state == PermissionRecoveryGateState.CLEAR) {
            editor
                .remove(PREF_PERMISSION_RECOVERY_GATE_STATE)
                .remove(PREF_PERMISSION_RECOVERY_GATE_ITEMS)
        } else {
            editor
                .putString(
                    PREF_PERMISSION_RECOVERY_GATE_STATE,
                    permissionRecoveryGate.state.name,
                )
                .putString(
                    PREF_PERMISSION_RECOVERY_GATE_ITEMS,
                    permissionRecoveryGate.affectedPermissions
                        .sortedBy(ObservedPermission::ordinal)
                        .joinToString(",") { it.name },
                )
        }
        editor.commit()
    }

    private fun enterPermissionRecoveryBarrier(
        missingPermissions: Set<ObservedPermission>,
        reason: String,
    ) {
        permissionRecoveryGate = permissionRecoveryGate.blocked(missingPermissions)
        persistPermissionRecoveryGate()
        if (::fieldSessionLog.isInitialized) {
            fieldSessionLog.blockActiveSessionRestore()
        }
        showPermissionDenialPanel(
            missingPermissions = missingPermissions,
            reason = reason,
        )
    }

    private fun completePermissionRecoveryRecheckIfPossible() {
        if (!permissionRecoveryGate.blocksAutomaticResourceStart) return
        val observed = currentObservedPermissionSnapshot()
        val missing = requiredStartWalkObservedPermissions()
            .filterNot(observed::isGranted)
            .toSet()
        if (missing.isNotEmpty()) {
            permissionRecoveryGate = permissionRecoveryGate.blocked(missing)
            persistPermissionRecoveryGate()
            updatePermissionRecoveryUi()
            return
        }
        val decision = startupCapabilityDecision ?: run {
            updatePermissionRecoveryUi()
            return
        }
        val allPrerequisitesReady =
            firstRunOnboardingComplete() &&
                currentReporterUserId() != null &&
                isGatewaySessionReadyForCurrentActor() &&
                decision.mayConfirmAndStart &&
                walkSessionReadinessBlockReason(decision) == null
        permissionRecoveryGate = permissionRecoveryGate.completeFullRecheck(
            observed = observed,
            requiredPermissions = requiredStartWalkObservedPermissions(),
            allPrerequisitesReady = allPrerequisitesReady,
        )
        persistPermissionRecoveryGate()
        if (
            permissionRecoveryGate.state ==
            PermissionRecoveryGateState.AWAITING_EXPLICIT_RESUME
        ) {
            renderAwaitingExplicitResumeControl()
        }
        updatePermissionRecoveryUi()
    }

    private fun updatePermissionRecoveryUi() {
        if (!::permissionDenialPanel.isInitialized) return
        when (permissionRecoveryGate.state) {
            PermissionRecoveryGateState.CLEAR,
            PermissionRecoveryGateState.REQUEST_PENDING,
            -> permissionDenialPanel.visibility = View.GONE
            PermissionRecoveryGateState.BLOCKED,
            PermissionRecoveryGateState.SETTINGS_PENDING,
            -> showPermissionDenialPanel(
                missingPermissions = permissionRecoveryGate.affectedPermissions,
                reason = "permission_recovery_blocked",
            )
            PermissionRecoveryGateState.RECHECK_REQUIRED -> {
                permissionDenialPanel.visibility = View.VISIBLE
                permissionDenialSummaryText.text =
                    "가입, 동의, 권한과 필수 기능 전체 상태를 다시 확인하고 있습니다. 자동으로 보행, 수집 또는 전송을 시작하지 않습니다."
                permissionDenialSummaryText.contentDescription =
                    permissionDenialSummaryText.text
                permissionDenialConfirmButton.text = "전체 상태 확인 중"
                permissionDenialConfirmButton.isEnabled = false
                permissionDenialSettingsButton.visibility = View.VISIBLE
            }
            PermissionRecoveryGateState.AWAITING_EXPLICIT_RESUME -> {
                permissionDenialPanel.visibility = View.VISIBLE
                permissionDenialSummaryText.text =
                    "가입, 동의, 권한과 필수 기능 전체 재확인을 마쳤습니다. 확인하기 전에는 보행, 수집 또는 전송을 시작하지 않습니다."
                permissionDenialSummaryText.contentDescription =
                    permissionDenialSummaryText.text
                permissionDenialConfirmButton.text = "재검사 결과 확인"
                permissionDenialConfirmButton.isEnabled = true
                permissionDenialSettingsButton.visibility = View.GONE
            }
        }
    }

    private fun showPermissionDenialPanel(
        missingPermissions: Set<ObservedPermission>,
        reason: String,
    ) {
        if (!::permissionDenialPanel.isInitialized) return
        val ordered = ObservedPermission.entries.filter(missingPermissions::contains)
        val itemSummary = if (ordered.isEmpty()) {
            "현재 필요한 권한 상태를 확인할 수 없습니다."
        } else {
            ordered.joinToString(" ") { permission ->
                "${permission.labelKo()} 권한: ${permission.denialReasonKo()}"
            }
        }
        val message =
            "일부 기능에 필요한 권한이 거부되었거나 철회되었습니다. " +
                "$itemSummary 해당 기능만 제한되며 나머지 기능은 계속 사용할 수 있습니다."
        permissionDenialPanel.visibility = View.VISIBLE
        permissionDenialSummaryText.text = message
        permissionDenialSummaryText.contentDescription = message
        permissionDenialConfirmButton.text = "확인"
        permissionDenialConfirmButton.isEnabled = true
        permissionDenialSettingsButton.visibility = View.VISIBLE
        permissionDenialSummaryText.post {
            if (permissionDenialPanel.visibility == View.VISIBLE) {
                permissionDenialSummaryText.requestFocus()
                permissionDenialSummaryText.performAccessibilityAction(
                    android.view.accessibility.AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS,
                    null,
                )
            }
        }
    }

    private fun onPermissionDenialConfirmed() {
        when (permissionRecoveryGate.state) {
            PermissionRecoveryGateState.BLOCKED -> {
                if (::fieldSessionLog.isInitialized) {
                    fieldSessionLog.blockActiveSessionRestore()
                }
                permissionRecoveryGate = PermissionRecoveryGate()
                persistPermissionRecoveryGate()
                permissionDenialPanel.visibility = View.GONE
                refreshStartupCapabilityUi()
                updateStatus(
                    "일부 기능 제한",
                    "권한이 필요한 기능만 제한하고 나머지 앱 기능을 계속 사용합니다.",
                )
            }
            PermissionRecoveryGateState.AWAITING_EXPLICIT_RESUME -> {
                permissionDenialPanel.visibility = View.GONE
                renderAwaitingExplicitResumeControl()
                startupCapabilityConfirmButton.post {
                    if (
                        permissionRecoveryGate.state ==
                        PermissionRecoveryGateState.AWAITING_EXPLICIT_RESUME &&
                        startupCapabilityConfirmButton.visibility == View.VISIBLE &&
                        startupCapabilityConfirmButton.isEnabled
                    ) {
                        startupCapabilityConfirmButton.requestFocus()
                        startupCapabilityConfirmButton.performAccessibilityAction(
                            android.view.accessibility.AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS,
                            null,
                        )
                    }
                }
                updateStatus(
                    "권한 재개 대기",
                    "차단 상태를 유지합니다. 보행 안내 시작 또는 재개를 다시 선택하세요.",
                )
            }
            PermissionRecoveryGateState.SETTINGS_PENDING,
            PermissionRecoveryGateState.RECHECK_REQUIRED,
            PermissionRecoveryGateState.REQUEST_PENDING,
            PermissionRecoveryGateState.CLEAR,
            -> {
                permissionDenialPanel.visibility = View.GONE
            }
        }
    }

    private fun renderAwaitingExplicitResumeControl() {
        startupCapabilityConfirmButton.visibility = View.VISIBLE
        startupCapabilityConfirmButton.isEnabled = true
        startupCapabilityConfirmButton.text = "보행 안내 다시 시작"
        runtimeControls.visibility = View.GONE
    }

    private fun resumePermissionRecoveryFromExplicitUserAction(): Boolean {
        if (
            permissionRecoveryGate.state !=
            PermissionRecoveryGateState.AWAITING_EXPLICIT_RESUME
        ) {
            return false
        }
        permissionRecoveryGate = permissionRecoveryGate.acknowledgeExplicitResume()
        persistPermissionRecoveryGate()
        ensurePermissionsThenStart()
        return true
    }

    private fun applyObservedPermissionStateChange(reason: String) {
        if (!::walkSessionLifecycle.isInitialized) return
        val sessionSnapshot = walkSessionLifecycle.snapshot()
        if (!hasCameraPermission()) {
            cancelRuntimeCameraHandoff()
            stopDepthSession(closeSession = true)
            stopCameraFallbackSession(updateUi = false)
        }
        if (!hasLocationPermission() || !isLocationServiceEnabledForDeviceCheck()) {
            cancelDestinationSearchLocation()
            navigationPermissionsRequestedForReport = false
            stopLocationUpdates()
            if (sessionSnapshot.state == WalkSessionState.ACTIVE && isRouteActive) {
                navigationRequests.cancelRoute()
                resetRouteState()
                updateNavigationStatus("navigation=stopped location_unavailable reason=$reason")
            }
        }
        if (!hasHandsFreeNotificationPermission()) {
            stopHandsFreeVoiceService()
        }
        if (!hasRecordAudioPermission()) {
            stopHandsFreeVoiceService()
            cancelVoiceCommandRecognition()
        }
        if (!hasActivityRecognitionPermission()) {
            cancelReportQueueDrain()
            stopStepTracking()
        }
        if (
            sessionSnapshot.state in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED) &&
            hasCurrentPostLoginDeviceRestrictions()
        ) {
            val stoppedOnly = setOfNotNull(
                ObservedPermission.CAMERA.takeIf { !hasCameraPermission() },
                ObservedPermission.PRECISE_LOCATION.takeIf { !hasLocationPermission() },
                ObservedPermission.MICROPHONE.takeIf { !hasRecordAudioPermission() },
                ObservedPermission.ACTIVITY_RECOGNITION.takeIf {
                    !hasActivityRecognitionPermission()
                },
            )
            if (stoppedOnly.isNotEmpty()) showPermissionDenialPanel(stoppedOnly, reason)
            updateStatus(
                "일부 기능 제한",
                "제한 기능: ${postLoginDeviceCheckDisabledFeatureText()}. " +
                    "해당 기능만 중지하고 나머지 기능은 계속 사용합니다.",
            )
        } else if (
            sessionSnapshot.state in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED) &&
            !hasCurrentPostLoginDeviceRestrictions() &&
            !permissionRecoveryGate.blocksAutomaticResourceStart &&
            ::permissionDenialPanel.isInitialized
        ) {
            permissionDenialPanel.visibility = View.GONE
        }
        if (::startupCapabilityProbe.isInitialized) {
            refreshStartupCapabilityUi()
            if (sessionSnapshot.state == WalkSessionState.ACTIVE) {
                if (!cameraAnalysisFeaturesEnabled()) {
                    activatePhoneMountingRuntime()
                    applyCurrentOfficialEnvironmentRuntimeAssessment()
                    startWalkSessionRuntimeWithoutCamera()
                } else {
                    applyCurrentOfficialEnvironmentRuntimeAssessment()
                    startNavigationServicesIfNeeded()
                    maybeStartHandsFreeVoiceService()
                }
            }
        }
        startLocationUpdatesIfAllowed()
    }

    private fun isRouteLocationPermissionReady(): Boolean = hasLocationPermission()

    private fun hasCameraPermission(): Boolean {
        return checkSelfPermission(Manifest.permission.CAMERA) == PackageManager.PERMISSION_GRANTED
    }

    /** Route arrival and damage coordinates require precise location; approximate-only is insufficient. */
    private fun hasLocationPermission(): Boolean {
        return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED
    }

    private fun hasActivityRecognitionPermission(): Boolean {
        return Build.VERSION.SDK_INT < Build.VERSION_CODES.Q ||
            checkSelfPermission(Manifest.permission.ACTIVITY_RECOGNITION) == PackageManager.PERMISSION_GRANTED
    }

    private fun hasRecordAudioPermission(): Boolean {
        return checkSelfPermission(Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED
    }

    private fun hasHandsFreeNotificationPermission(): Boolean =
        Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU ||
            checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) ==
            PackageManager.PERMISSION_GRANTED

    // FastSAM load/release owns its inference engine, not the camera. Its readiness must not
    // consume a camera start request; calibration and camera cleanup still retain their leases.
    private fun runtimeCameraStartBlockedByAnotherOwner(): Boolean =
        runtimeCalibration != null || unknownCalibration != null ||
            runtimeTuningPreparing || runtimeOldDetectorReleasePending ||
            cameraXReleaseBlocked ||
            officialEnvironmentCameraPreflightActive ||
            officialEnvironmentCameraCleanupPending ||
            postLoginCameraPipelinePreflightActive ||
            postLoginCameraPipelineCleanupPending ||
            postLoginCameraPipelineCamera != null

    private fun startDepthSession() {
        if (!firstRunOnboardingComplete()) return
        if (!isWalkSessionRuntimeActive()) return
        if (!requireStartupCapabilityConfirmation()) return
        if (session != null) {
            updateStatus("ARCore Depth 실행 중", "이미 session이 시작돼 있습니다.")
            return
        }
        arCoreAvailabilityCheckPending = false
        val requestGeneration = ++arCoreAvailabilityRequestGeneration
        val lifecycleGeneration = feedbackLifecycleGeneration
        val availability = ArCoreApk.getInstance().checkAvailability(this)
        if (shouldRecheckArCoreAvailability(availability)) {
            requestArCoreAvailabilityRecheck(requestGeneration, lifecycleGeneration)
            return
        }
        continueDepthSessionStart(availability)
    }

    private fun requestArCoreAvailabilityRecheck(
        requestGeneration: Int,
        lifecycleGeneration: Int,
    ) {
        arCoreSupported = false
        arCoreAvailabilityCheckPending = true
        setActionButton("ARCore 지원 확인 중", ActionMode.START, enabled = false)
        updateStatus("ARCore 지원 확인 중", "기기 지원 상태를 다시 확인하고 있습니다.")
        ArCoreApk.getInstance().checkAvailabilityAsync(this) { availability ->
            if (isArCoreAvailabilityCallbackCurrent(requestGeneration, lifecycleGeneration)) {
                arCoreAvailabilityCheckPending = false
                when {
                    session != null || cameraFallbackRequested -> Unit
                    !hasCameraPermission() -> {
                        setActionButton("ARCore Depth 시작", ActionMode.START, enabled = true)
                        updateStatus("카메라 권한 필요", "ARCore Depth를 시작하려면 카메라 권한을 허용해야 합니다.")
                    }
                    !requireReporterUserId("login_required_depth_start") -> {
                        setActionButton("ARCore Depth 시작", ActionMode.START, enabled = true)
                    }
                    else -> continueDepthSessionStart(availability)
                }
            }
        }
    }

    private fun isArCoreAvailabilityCallbackCurrent(
        requestGeneration: Int,
        lifecycleGeneration: Int,
    ): Boolean {
        return arCoreAvailabilityCheckPending &&
            requestGeneration == arCoreAvailabilityRequestGeneration &&
            lifecycleGeneration == feedbackLifecycleGeneration &&
            isWalkSessionRuntimeActive() &&
            !isFinishing &&
            !isDestroyed
    }

    private fun invalidateArCoreAvailabilityRecheck() {
        val wasPending = arCoreAvailabilityCheckPending
        arCoreAvailabilityRequestGeneration += 1
        arCoreAvailabilityCheckPending = false
        if (wasPending && ::actionButton.isInitialized) {
            setActionButton("ARCore Depth 시작", ActionMode.START, enabled = true)
        }
    }

    private fun continueDepthSessionStart(availability: ArCoreApk.Availability) {
        if (!firstRunOnboardingComplete()) return
        if (!isWalkSessionRuntimeActive()) return
        if (
            runtimeCameraStartBlockedByAnotherOwner() ||
            session != null ||
            arSessionPurpose != ArSessionPurpose.NONE
        ) return
        val gate = resolveArCoreStartGate(availability)
        if (
            gate == ArCoreStartGate.READY &&
            CameraFallbackTestOverride.consumeForceCameraNonMetricFallback(intent)
        ) {
            arCoreSupported = false
            requestCameraFallbackStart(CameraFallbackStartReason.DEBUG_FORCED_SUPPORTED, availability)
            return
        }
        when (gate) {
            ArCoreStartGate.READY -> Unit
            ArCoreStartGate.CAMERA_FALLBACK -> {
                arCoreSupported = false
                requestCameraFallbackStart(CameraFallbackStartReason.ARCORE_AVAILABILITY_UNSUPPORTED, availability)
                return
            }
            ArCoreStartGate.RETRY_LATER -> {
                arCoreSupported = false
                invalidateRuntimeMetricEvidence("runtime_arcore_availability_unknown")
                setActionButton("ARCore 다시 확인", ActionMode.START, enabled = true)
                updateStatus(
                    "ARCore 지원 확인 실패",
                    "네트워크 또는 Google Play Services for AR 상태를 확인한 뒤 다시 시도하세요.",
                )
                return
            }
        }
        if (
            cameraFallbackRequested ||
            cameraFallbackRunning ||
            cameraFallbackCleanupPending ||
            cameraFallbackCamera != null
        ) {
            val expectedEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return
            val expectedLifecycleGeneration = feedbackLifecycleGeneration
            stopCameraFallbackSession(
                updateUi = false,
                onReleased = {
                    if (
                        feedbackLifecycleGeneration == expectedLifecycleGeneration &&
                        walkSessionLifecycle.isRuntimeEpochCurrent(expectedEpoch) &&
                        isWalkSessionRuntimeActive()
                    ) {
                        continueDepthSessionStart(availability)
                    }
                },
            )
            return
        }
        arCoreSupported = true

        var candidateSession: Session? = null
        try {
            when (ArCoreApk.getInstance().requestInstall(this, !installRequested)) {
                ArCoreApk.InstallStatus.INSTALL_REQUESTED -> {
                    installRequested = true
                    pendingSessionStartAfterInstall = false
                    invalidateRuntimeMetricEvidence("runtime_arcore_install_required")
                    setActionButton("기기 거리 기능 다시 확인", ActionMode.START, enabled = true)
                    updateStatus(
                        "ARCore 설치 필요",
                        "Google Play Services for AR 설치 후 기기 거리 기능을 다시 확인해 주세요.",
                    )
                    return
                }
                ArCoreApk.InstallStatus.INSTALLED -> Unit
            }

            val newSession = Session(this).also { candidateSession = it }
            val provider = ArCoreFrameProvider(newSession)
            depthSupported = provider.configureDepthMode()
            loadDetectorAfterCameraGate()
            if (!detectorAvailable) {
                newSession.close()
                candidateSession = null
                invalidateRuntimeMetricEvidence("runtime_detector_start_unavailable")
                updateStatus(
                    "객체 탐지 사용 불가 · 안전 중지",
                    "탐지 모델을 사용할 수 없어 보행 기능을 시작하지 않았습니다.",
                )
                return
            }
            if (!depthSupported) {
                newSession.close()
                candidateSession = null
                requestCameraFallbackStart(CameraFallbackStartReason.ARCORE_DEPTH_UNSUPPORTED, availability)
                return
            }
            val runtimeStartedAtMs = SystemClock.elapsedRealtime()
            val resumeRenderer = pauseRendererForSessionClose()
            val runtimeGeneration = try {
                val textureBound = resumeArSessionBeforePublish(newSession)
                synchronized(runtimeMetricStateLock) {
                    session = newSession
                    frameProvider = provider
                    arSessionPurpose = ArSessionPurpose.RUNTIME
                    val generation = ++arSessionGeneration
                    runtimeMetricOutputAllowed = false
                    runtimeMetricInitialNavigationStartPending = true
                    runtimeMetricLastValidFrameAtMs = runtimeStartedAtMs
                    runtimeMetricLastFrameTimestampNanos = 0L
                    runtimeMetricActivationSession = RuntimeMetricPreflightSession(
                        generation = generation,
                        startedAtElapsedRealtimeMs = runtimeStartedAtMs,
                        depthSupport = RuntimeMetricDepthSupport.SUPPORTED,
                    )
                    cameraTextureBound = textureBound
                    generation
                }
            } finally {
                resumeRendererAfterSessionClose(resumeRenderer)
            }
            candidateSession = null
            syncActiveSessionScreenPolicy()
            setActionButton("ARCore Depth 실행 중", ActionMode.START, enabled = false)
            updateStatus(
                status = if (depthSupported) "ARCore 미터 거리 재확인 중" else "ARCore Depth 미지원",
                detail = if (depthSupported) {
                    "새 ARCore 세션의 실제 미터 거리 프레임을 다시 확인한 뒤 보행 출력을 시작합니다."
                } else {
                    "이 기기는 ARCore DepthMode.AUTOMATIC을 지원하지 않아 metric depth가 제한됩니다."
                },
            )
            surfaceView.postDelayed(
                {
                    val activation = runtimeMetricActivationSession
                    if (
                        activation != null &&
                        activation.generation == runtimeGeneration &&
                        arSessionPurpose == ArSessionPurpose.RUNTIME &&
                        arSessionGeneration == runtimeGeneration
                    ) {
                        val result = activation.expire(SystemClock.elapsedRealtime())
                        if (result.status == RuntimeMetricPreflightStatus.UNKNOWN) {
                            handleRuntimeMetricLoss(runtimeGeneration)
                        }
                    }
                },
                RuntimeMetricPreflightPolicy.MAX_DURATION_MS,
            )
            fieldSessionLog.recordEvent(
                "arcore_session_started",
                mapOf(
                    "depth_supported" to depthSupported,
                    "detector_available" to detectorAvailable,
                    "loaded_model" to (detectorLoadedModelKey ?: "none"),
                    "model_fallback_used" to detectorModelFallbackUsed,
                ),
            )
        } catch (_: UnavailableDeviceNotCompatibleException) {
            runCatching { candidateSession?.close() }
            arCoreSupported = false
            stopDepthSession(closeSession = true)
            requestCameraFallbackStart(CameraFallbackStartReason.ARCORE_SESSION_INCOMPATIBLE, availability)
        } catch (error: Exception) {
            runCatching { candidateSession?.close() }
            updateStatus("ARCore 시작 실패", error.message ?: error::class.java.simpleName)
            invalidateRuntimeMetricEvidence("runtime_session_start_failed")
        }
    }

    private fun stopDepthSession(closeSession: Boolean = false) {
        val sessionToStop = synchronized(runtimeMetricStateLock) {
            val ownedSession = session
            session = null
            frameProvider?.close()
            frameProvider = null
            arSessionPurpose = ArSessionPurpose.NONE
            arSessionGeneration += 1
            runtimeMetricOutputAllowed = false
            runtimeMetricInitialNavigationStartPending = false
            runtimeMetricActivationSession = null
            runtimeMetricLastValidFrameAtMs = 0L
            runtimeMetricLastFrameTimestampNanos = 0L
            ownedSession
        }
        val hadSession = sessionToStop != null
        val resumeRenderer = if (hadSession) pauseRendererForSessionClose() else false
        runCatching { sessionToStop?.pause() }
        if (closeSession) {
            sessionToStop?.close()
        }
        syncActiveSessionScreenPolicy()
        cameraTextureBound = false
        arCoreSupported = false
        depthSupported = false
        latestTactileRouteState = "localRoute=tmap:tactile_not_visible"
        latestReportCandidateStatus = "reportCandidate=blocked"
        detectorGeneration += 1
        resetVisualTrackingState()
        latestDetectionSnapshot = DetectionSnapshot.empty()
        adaptiveInferencePacing.reset()
        captureLog.clear()
        if (::metadataLogUploader.isInitialized) {
            metadataLogUploader.setEnabled(false)
        }
        if (::debugBboxOverlay.isInitialized) {
            runOnUiThread { debugBboxOverlay.clear() }
        }
        if (::actionButton.isInitialized) setActionButton("ARCore Depth 시작", ActionMode.START, enabled = true)
        if (::debugUploadButton.isInitialized) updateDebugUploadButton()
        if (hadSession && ::fieldSessionLog.isInitialized) {
            fieldSessionLog.recordEvent("arcore_session_stopped", mapOf("closed" to closeSession))
        }
        resumeRendererAfterSessionClose(resumeRenderer)
    }

    private fun bindCameraTextureIfReady() {
        val currentSession = session ?: return
        if (cameraTextureId == 0 || cameraTextureBound) return
        currentSession.setCameraTextureNames(intArrayOf(cameraTextureId))
        cameraTextureBound = true
    }

    private fun resumeArSessionBeforePublish(currentSession: Session): Boolean {
        val textureBound = cameraTextureId != 0
        if (textureBound) {
            currentSession.setCameraTextureNames(intArrayOf(cameraTextureId))
        }
        if (surfaceWidth > 0 && surfaceHeight > 0) {
            currentSession.setDisplayGeometry(displayRotation(), surfaceWidth, surfaceHeight)
        }
        currentSession.resume()
        return textureBound
    }

    private fun updateDisplayGeometryIfReady() {
        val currentSession = session ?: return
        if (surfaceWidth <= 0 || surfaceHeight <= 0) return
        currentSession.setDisplayGeometry(displayRotation(), surfaceWidth, surfaceHeight)
    }

    private fun displayRotation(): Int {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            display?.rotation ?: Surface.ROTATION_0
        } else {
            @Suppress("DEPRECATION")
            windowManager.defaultDisplay.rotation
        }
    }

    private fun requestCameraFallbackStart(
        reason: CameraFallbackStartReason,
        availability: ArCoreApk.Availability,
    ) {
        val walkBeforeChange = walkSessionLifecycle.snapshot()
        val decisionBeforeChange = startupCapabilityDecision
        // Test guidance can have a valid confirmation without a stored confirmation object.
        // Capture the same admission decision before changing the available feature set.
        val capabilityWasConfirmed = isStartupCapabilityConfirmed()
        metricDistanceCapabilityOverride = false
        val distanceLimitedDecision = resolveCurrentStartupCapabilityDecision(
            metricDistanceOverride = false,
        )
        val automaticallyContinueMetricOnlyDowngrade =
            reason == CameraFallbackStartReason.RUNTIME_METRIC_LOST &&
                walkBeforeChange.state == WalkSessionState.ACTIVE &&
                decisionBeforeChange != null &&
                capabilityWasConfirmed &&
                decisionBeforeChange.allowsMetricDistance() &&
                distanceLimitedDecision.mayConfirmAndStart &&
                distanceLimitedDecision.pendingRequirements.isEmpty() &&
                distanceLimitedDecision.unavailableRequirements.toSet() ==
                decisionBeforeChange.unavailableRequirements.toSet() +
                WalkSafeStartupRequirement.METRIC_DISTANCE
        if (automaticallyContinueMetricOnlyDowngrade) {
            confirmedStartupCapabilityDecision = distanceLimitedDecision
        } else if (walkBeforeChange.state == WalkSessionState.ACTIVE) {
            enterWalkSessionForegroundRecheckAndCancelOutputs(
                reason = "runtime_mode_changed_to_distance_limited",
            )
        }
        pendingCameraFallbackStart = PendingCameraFallbackStart(reason, availability)
        refreshStartupCapabilityUi()
        val walkAfterChange = walkSessionLifecycle.snapshot()
        val automaticTransitionReady =
            automaticallyContinueMetricOnlyDowngrade &&
                walkAfterChange.epoch == walkBeforeChange.epoch &&
                walkAfterChange.state == WalkSessionState.ACTIVE &&
                walkAfterChange.mode == WalkSessionMode.DISTANCE_LIMITED &&
                isStartupCapabilityConfirmed()
        if (automaticTransitionReady || isStartupCapabilityConfirmed()) {
            pendingCameraFallbackStart = null
            if (cameraAnalysisFeaturesEnabled()) {
                startCameraFallbackSession(reason, availability)
            } else {
                startWalkSessionRuntimeWithoutCamera()
            }
            return
        }
        setActionButton("거리 제한 모드 시작", ActionMode.START, enabled = true)
        updateStatus("거리 제한 확인 필요", WALKSAFE_LIMITED_DISTANCE_NOTICE_KO)
    }

    private fun startCameraFallbackSession(
        reason: CameraFallbackStartReason,
        availability: ArCoreApk.Availability,
    ) {
        if (!firstRunOnboardingComplete()) return
        if (!isWalkSessionRuntimeActive()) return
        if (!hasCameraPermission()) return
        if (cameraXReleaseBlocked) {
            continueAfterCameraFallbackFailure(
                "카메라 자원을 다시 열 수 없습니다.",
            )
            return
        }
        if (
            runtimeCameraStartBlockedByAnotherOwner() ||
            session != null ||
            arSessionPurpose != ArSessionPurpose.NONE
        ) return
        cameraFallbackStartReason = reason
        cameraFallbackAvailability = availability
        loadDetectorAfterCameraGate()
        latestExplicitReportOutput = null
        latestExplicitReportImage = null
        latestExplicitReportGateState = null
        latestExplicitReportCapturedAtMs = 0L
        if (!detectorAvailable) {
            cameraFallbackRequested = false
            cameraFallbackStartReason = null
            cameraFallbackAvailability = null
            continueAfterCameraFallbackFailure(
                "대체 장애물 탐지기를 사용할 수 없습니다.",
            )
            return
        }
        startNavigationServicesIfNeeded()
        cameraFallbackRequested = true
        latestTactileRouteState = "localRoute=disabled:camera_non_metric_advisory"
        latestReportCandidateStatus = "reportCandidate=blocked:camera_non_metric_tier"
        setActionButton("카메라 보조 경고 실행 중", ActionMode.START, enabled = false)
        updateStatus(
            status = "카메라 보조 경고 · 거리 제한 모드",
            detail = "미터 거리 안내와 거리 수치가 필요한 자동 위험 판정만 제한됩니다. " +
                "카메라 방향 장애물 안내와 현재 사용 가능한 위치·경로·걸음 수·음성·진동 기능은 계속됩니다.",
        )
        bindCameraFallbackSession()
    }

    @androidx.annotation.OptIn(markerClass = [ExperimentalGetImage::class])
    private fun bindCameraFallbackSession() {
        val expectedWalkEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return
        if (
            !cameraFallbackRequested ||
            cameraFallbackRunning ||
            cameraFallbackCleanupPending ||
            runtimeCameraStartBlockedByAnotherOwner() ||
            session != null ||
            arSessionPurpose != ArSessionPurpose.NONE ||
            !detectorAvailable
        ) return
        val startReason = cameraFallbackStartReason ?: return
        val availabilityState = cameraFallbackAvailability?.name ?: return
        val generation = ++cameraFallbackGeneration
        val providerFuture = ProcessCameraProvider.getInstance(this)
        providerFuture.addListener(
            {
                if (
                    !isCameraFallbackLeaseCurrent(expectedWalkEpoch, generation) ||
                    isDestroyed
                ) {
                    return@addListener
                }
                try {
                    val provider = providerFuture.get()
                    val resolutionSelector = ResolutionSelector.Builder()
                        .setResolutionStrategy(
                            ResolutionStrategy(
                                Size(CAMERA_FALLBACK_WIDTH, CAMERA_FALLBACK_HEIGHT),
                                ResolutionStrategy.FALLBACK_RULE_CLOSEST_LOWER_THEN_HIGHER,
                            ),
                        )
                        .build()
                    val analysis = ImageAnalysis.Builder()
                        .setResolutionSelector(resolutionSelector)
                        .setTargetRotation(displayRotation())
                        .setOutputImageFormat(ImageAnalysis.OUTPUT_IMAGE_FORMAT_YUV_420_888)
                        .setOutputImageRotationEnabled(true)
                        .setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST)
                        .build()
                    val preview = Preview.Builder()
                        .setResolutionSelector(resolutionSelector)
                        .setTargetRotation(displayRotation())
                        .build()
                    preview.setSurfaceProvider(cameraFallbackPreviewView.surfaceProvider)
                    analysis.setAnalyzer(detectorExecutor) { imageProxy ->
                        analyzeCameraFallbackFrame(
                            imageProxy,
                            expectedWalkEpoch,
                            generation,
                        )
                    }
                    cameraFallbackCamera = provider.bindToLifecycle(
                        cameraFallbackLifecycleOwner,
                        CameraSelector.DEFAULT_BACK_CAMERA,
                        preview,
                        analysis,
                    )
                    cameraFallbackProvider = provider
                    cameraFallbackAnalysis = analysis
                    cameraFallbackPreview = preview
                    cameraFallbackRunning = true
                    syncActiveSessionScreenPolicy()
                    cameraFallbackPreviewView.visibility = View.VISIBLE
                    adaptiveInferencePacing.reset()
                    cameraFallbackFrameAnalyzedGeneration = -1
                    fieldSessionLog.recordEvent(
                        "camera_non_metric_session_started",
                        mapOf(
                            "loaded_model" to (detectorLoadedModelKey ?: "none"),
                            "model_fallback_used" to detectorModelFallbackUsed,
                            "metric" to false,
                            "reports_allowed" to false,
                            "reason" to startReason.fieldValue,
                            "state" to availabilityState,
                        ),
                    )
                    updateStatus(
                        status = "카메라 보조 경고 · 거리 제한 모드",
                        detail = "미터 거리 안내와 거리 수치가 필요한 자동 위험 판정만 제한됩니다. " +
                            "카메라 방향 장애물 안내와 현재 사용 가능한 위치·경로·걸음 수·음성·진동 기능은 계속됩니다.",
                    )
                } catch (error: Exception) {
                    if (!isCameraFallbackLeaseCurrent(expectedWalkEpoch, generation)) {
                        return@addListener
                    }
                    cameraFallbackRunning = false
                    stopCameraFallbackSession(
                        updateUi = false,
                        onReleased = {
                            if (
                                walkSessionLifecycle.isRuntimeEpochCurrent(expectedWalkEpoch) &&
                                isWalkSessionRuntimeActive()
                            ) {
                                continueAfterCameraFallbackFailure(
                                    "대체 카메라를 시작하지 못했습니다.",
                                )
                            }
                        },
                    )
                    return@addListener
                }
            },
            ContextCompat.getMainExecutor(this),
        )
    }

    private fun continueAfterCameraFallbackFailure(detail: String) {
        pendingCameraFallbackStart = null
        metricDistanceCapabilityOverride = false
        runtimeObstacleDetectionCapabilityOverride = false
        latestTactileRouteState = "localRoute=tmap:tactile_not_visible"
        latestReportCandidateStatus = "reportCandidate=blocked:camera_non_metric_unavailable"
        refreshStartupCapabilityUi()
        activatePhoneMountingRuntime()
        applyCurrentOfficialEnvironmentRuntimeAssessment()
        startWalkSessionRuntimeWithoutCamera()
        setActionButton("카메라·거리 기능 제한", ActionMode.START, enabled = false)
        updateStatus(
            "카메라·거리 기능 제한",
            "$detail 카메라 장애물 인식과 미터 거리 안내만 제한하고, " +
                "위치·경로·걸음 수와 현재 사용 가능한 음성·진동 기능은 계속합니다.",
        )
    }

    private fun isCameraFallbackLeaseCurrent(
        expectedWalkEpoch: WalkRuntimeEpoch,
        expectedFallbackGeneration: Int,
        requireRunning: Boolean = false,
    ): Boolean =
        firstRunOnboardingComplete() &&
            walkSessionLifecycle.isRuntimeEpochCurrent(expectedWalkEpoch) &&
            cameraFallbackRequested &&
            expectedFallbackGeneration == cameraFallbackGeneration &&
            (!requireRunning || cameraFallbackRunning)

    private fun stopCameraFallbackSession(
        updateUi: Boolean = true,
        onReleased: (() -> Unit)? = null,
    ) {
        val stoppedWalkEpoch = if (::walkSessionLifecycle.isInitialized) {
            walkSessionLifecycle.currentRuntimeEpochOrNull()
        } else {
            null
        }
        if (onReleased != null || !cameraFallbackCleanupPending) {
            cameraFallbackAfterRelease = onReleased
        }
        val wasRequested = cameraFallbackRequested
        val ownedProvider = cameraFallbackProvider
        val ownedCamera = cameraFallbackCamera
        val ownedAnalysis = cameraFallbackAnalysis
        val ownedPreview = cameraFallbackPreview
        val hadOwnedResources =
            ownedCamera != null || ownedAnalysis != null || ownedPreview != null
        cameraFallbackRequested = false
        cameraFallbackRunning = false
        syncActiveSessionScreenPolicy()
        cameraFallbackGeneration += 1
        cameraFallbackCamera = null
        cameraFallbackAnalysis = null
        cameraFallbackPreview = null
        cameraFallbackProvider = null
        if (::cameraFallbackPreviewView.isInitialized) {
            cameraFallbackPreviewView.visibility = View.GONE
        }
        adaptiveInferencePacing.reset()
        cameraFallbackFrameAnalyzedGeneration = -1
        nonMetricAdvisoryPolicy.reset()
        if (wasRequested && ::fieldSessionLog.isInitialized) {
            fieldSessionLog.recordEvent("camera_non_metric_session_stopped")
        }
        if (updateUi && ::actionButton.isInitialized) {
            setActionButton("ARCore Depth 시작", ActionMode.START, enabled = true)
        }
        cameraFallbackStartReason = null
        cameraFallbackAvailability = null
        if (!hadOwnedResources) {
            if (!cameraFallbackCleanupPending) {
                val afterRelease = cameraFallbackAfterRelease
                cameraFallbackAfterRelease = null
                afterRelease?.invoke()
            }
            return
        }
        cameraFallbackCleanupPending = true
        ownedAnalysis?.clearAnalyzer()
        val releaseClaim = AtomicBoolean(false)
        val analyzerBarrierTimedOut = AtomicBoolean(false)
        lateinit var release: Runnable
        lateinit var releaseDeadline: Runnable
        release = Runnable {
            if (!releaseClaim.compareAndSet(false, true)) return@Runnable
            cameraReleaseHandler.removeCallbacks(releaseDeadline)
            if (ownedAnalysis != null) {
                runCatching { ownedProvider?.unbind(ownedAnalysis) }
            }
            if (ownedPreview != null) {
                runCatching { ownedProvider?.unbind(ownedPreview) }
            }
            if (::cameraFallbackLifecycleOwner.isInitialized) {
                cameraFallbackLifecycleOwner.moveTo(Lifecycle.State.CREATED)
            }
            awaitCameraXClosed(ownedCamera) { closed ->
                cameraFallbackCleanupPending = false
                val afterRelease = cameraFallbackAfterRelease
                cameraFallbackAfterRelease = null
                if (closed && !analyzerBarrierTimedOut.get()) {
                    afterRelease?.invoke()
                } else {
                    cameraXReleaseBlocked = true
                    if (
                        stoppedWalkEpoch != null &&
                        walkSessionLifecycle.isRuntimeEpochCurrent(stoppedWalkEpoch)
                    ) {
                        continueAfterCameraFallbackFailure(
                            "대체 카메라 자원을 정상적으로 닫지 못했습니다.",
                        )
                    } else if (
                        stoppedWalkEpoch == null &&
                        walkSessionLifecycle.currentRuntimeEpochOrNull() == null &&
                        !isFinishing &&
                        !isDestroyed
                    ) {
                        updateStatus(
                            "카메라 정리 실패",
                            "카메라 보조 기능을 닫지 못했습니다. 앱을 다시 시작한 뒤 점검하세요.",
                        )
                    }
                }
            }
        }
        releaseDeadline = Runnable {
            analyzerBarrierTimedOut.set(true)
            release.run()
        }
        if (ownedAnalysis == null) {
            if (Looper.myLooper() == Looper.getMainLooper()) {
                release.run()
            } else {
                runOnUiThread(release)
            }
            return
        }
        cameraReleaseHandler.postDelayed(
            releaseDeadline,
            CAMERA_ANALYZER_RELEASE_BARRIER_TIMEOUT_MS,
        )
        try {
            detectorExecutor.execute {
                runOnUiThread(release)
            }
        } catch (_: RejectedExecutionException) {
            analyzerBarrierTimedOut.set(true)
            runOnUiThread(release)
        }
    }

    @androidx.annotation.OptIn(markerClass = [ExperimentalGetImage::class])
    private fun analyzeCameraFallbackFrame(
        imageProxy: ImageProxy,
        expectedWalkEpoch: WalkRuntimeEpoch,
        expectedFallbackGeneration: Int,
    ) {
        var pacingTicket: InferencePacingTicket? = null
        var detectorInvoked = false
        var inferenceDurationMs: Long? = null
        var detectorSucceeded = false
        try {
            if (!postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION)) {
                return
            }
            val nowMs = SystemClock.elapsedRealtime()
            if (
                !isActivityForeground ||
                !isCameraFallbackLeaseCurrent(
                    expectedWalkEpoch,
                    expectedFallbackGeneration,
                    requireRunning = true,
                )
            ) return
            runtimeCameraFrameBudgetMs = null
            runtimeLoadFrameScope = RuntimeFeatureScope.CAMERA_TRACKING
            runtimeLoadNormalFrameAtMs = if (cameraEnvironmentOutputsAllowed()) nowMs else null
            runtimeLoadObservationSource.recordFrame(
                imageProxy.imageInfo.timestamp, nowMs, null, null, null, runtimeLoadEnvironmentKey(),
            )
            observeRuntimeInferenceLoad(inputObserved = true)
            pacingTicket = tryStartDetectionWork(nowMs) ?: return
            val lifecycleGeneration = feedbackLifecycleGeneration
            val detectorFrameGeneration = detectorGeneration
            val mediaImage = imageProxy.image ?: return
            val yPlane = imageProxy.planes.firstOrNull()
            val qualityObservation = observeOfficialEnvironmentCameraFrame(
                cameraFrameQualityObservation(
                    epoch = expectedWalkEpoch,
                    observedAtElapsedRealtimeMs = nowMs,
                    frameAvailable = true,
                    width = imageProxy.width,
                    height = imageProxy.height,
                    yPlaneBuffer = yPlane?.buffer,
                    yPlaneRowStride = yPlane?.rowStride,
                    yPlanePixelStride = yPlane?.pixelStride,
                ),
            ) ?: return
            if (!cameraEnvironmentOutputsAllowed()) return
            var detectorStartedAtElapsedRealtimeMs = nowMs
            var result = AndroidDetectionResult.empty()
            val admission = CameraDetectorAdmissionPolicy.admit(
                currentEpoch = expectedWalkEpoch,
                nowElapsedRealtimeMs = nowMs,
                observation = qualityObservation,
                approvedProfile = activeCameraFrameQualityProfile,
            ) {
                detectorInvoked = true
                detectorStartedAtElapsedRealtimeMs = SystemClock.elapsedRealtime()
                result = try {
                    frameDetector.detectOriented(
                        cameraImage = mediaImage,
                        timestampMs = imageProxy.imageInfo.timestamp / NANOS_PER_MILLISECOND,
                        quarterTurns = (imageProxy.imageInfo.rotationDegrees / 90) % 4,
                    ).also {
                        if (
                            isCurrentFrameGeneration(
                                detectorFrameGeneration,
                                expectedWalkEpoch,
                            )
                        ) {
                            detectorRuntimeSupervisor.onSuccess()
                        }
                        detectorSucceeded = true
                    }
                } catch (error: RuntimeException) {
                    handleDetectorRuntimeFailure(
                        error,
                        detectorFrameGeneration,
                        expectedWalkEpoch,
                    )
                    AndroidDetectionResult.empty()
                } finally {
                    inferenceDurationMs = SystemClock.elapsedRealtime() - detectorStartedAtElapsedRealtimeMs
                }
            }
            if (!admission.detectorInvocationAllowed) return
            inferenceDurationMs = result.timing.totalMs ?: inferenceDurationMs
            if (detectorSucceeded) {
                val completedAtElapsedRealtimeMs = SystemClock.elapsedRealtime()
                val inferenceLatencyMs = result.timing.totalMs
                    ?: (completedAtElapsedRealtimeMs - detectorStartedAtElapsedRealtimeMs)
                if (
                    !observeWalkRuntimeDetectorTiming(
                        epoch = expectedWalkEpoch,
                        frameCapturedAtElapsedRealtimeMs = nowMs,
                        observedAtElapsedRealtimeMs = completedAtElapsedRealtimeMs,
                        inferenceLatencyMs = inferenceLatencyMs,
                    )
                ) return
            }
            if (
                !isCameraFallbackLeaseCurrent(
                    expectedWalkEpoch,
                    expectedFallbackGeneration,
                    requireRunning = true,
                ) ||
                lifecycleGeneration != feedbackLifecycleGeneration ||
                !isCurrentFrameGeneration(
                    detectorFrameGeneration,
                    expectedWalkEpoch,
                ) ||
                !cameraEnvironmentOutputsAllowed() ||
                !isActivityForeground
            ) return
            if (detectorSucceeded) {
                recordCameraFallbackFrameAnalyzedOnce(
                    expectedWalkEpoch,
                    expectedFallbackGeneration,
                    lifecycleGeneration,
                )
                recordRawCollectionDetectionMetadata(
                    expectedWalkEpoch = expectedWalkEpoch,
                    detectionCount = result.detections.size,
                    inferenceMs = result.timing.totalMs
                        ?: (
                            SystemClock.elapsedRealtime() -
                                detectorStartedAtElapsedRealtimeMs
                            ).coerceAtLeast(0L),
                    modelRevision = result.timing.modelKey ?: detectorLoadedModelKey,
                )
            }
            val advisoryGate = currentCameraFallbackAdvisoryGate(nowMs)
            val tier = resolveAndroidLocalTactileTier(advisoryGate)
            if (detectorSucceeded) {
                recordCameraFallbackInferenceSample(result, tier, advisoryGate, nowMs)
            }
            val action = nonMetricAdvisoryPolicy.evaluate(
                detections = result.detections,
                gate = advisoryGate,
                frameId = imageProxy.imageInfo.timestamp,
                nowMs = nowMs,
            )
            if (
                !isCameraFallbackLeaseCurrent(
                    expectedWalkEpoch,
                    expectedFallbackGeneration,
                    requireRunning = true,
                ) ||
                lifecycleGeneration != feedbackLifecycleGeneration ||
                !isCurrentFrameGeneration(
                    detectorFrameGeneration,
                    expectedWalkEpoch,
                ) ||
                !cameraEnvironmentOutputsAllowed() ||
                !isActivityForeground
            ) {
                nonMetricAdvisoryPolicy.reset()
                return
            }
            if (tier == AndroidLocalTactileTier.CAMERA_IMU_NON_METRIC && action != null) {
                runOnUiThread {
                    emitCameraFallbackAdvisory(
                        action,
                        expectedWalkEpoch,
                        expectedFallbackGeneration,
                        lifecycleGeneration,
                    )
                }
            }
        } finally {
            try {
                imageProxy.close()
            } finally {
                pacingTicket?.let { ticket ->
                    finishDetectionWork(ticket, detectorInvoked, inferenceDurationMs, validCompletion = detectorSucceeded)
                }
            }
        }
    }

    private fun recordCameraFallbackFrameAnalyzedOnce(
        expectedWalkEpoch: WalkRuntimeEpoch,
        fallbackGeneration: Int,
        lifecycleGeneration: Int,
    ) {
        if (
            cameraFallbackFrameAnalyzedGeneration == fallbackGeneration ||
            !isCameraFallbackLeaseCurrent(
                expectedWalkEpoch,
                fallbackGeneration,
                requireRunning = true,
            ) ||
            lifecycleGeneration != feedbackLifecycleGeneration ||
            !isActivityForeground ||
            !cameraFallbackRunning
        ) return
        cameraFallbackFrameAnalyzedGeneration = fallbackGeneration
        fieldSessionLog.recordEvent(
            "camera_non_metric_frame_analyzed",
            mapOf(
                "loaded_model" to (detectorLoadedModelKey ?: "none"),
                "model_fallback_used" to detectorModelFallbackUsed,
                "metric" to false,
                "reports_allowed" to false,
                "state" to "detector_succeeded",
            ),
        )
    }

    private fun recordCameraFallbackInferenceSample(
        result: AndroidDetectionResult,
        tier: AndroidLocalTactileTier,
        advisoryGate: NonMetricAdvisoryGate,
        nowMs: Long,
    ) {
        fieldSessionLog.appendCameraNonMetricSample(
            CameraNonMetricFieldSample(
                elapsedRealtimeMs = nowMs,
                inferenceMs = result.timing.totalMs ?: return,
                detectionCount = result.detections.size,
                capabilityTier = tier.name,
                cameraPermissionGranted = advisoryGate.cameraPermissionGranted,
                cameraFallbackRunning = advisoryGate.cameraFallbackRunning,
                detectorAvailable = advisoryGate.detectorAvailable,
                imuFresh = advisoryGate.imuFresh,
                tmapRouteActive = advisoryGate.tmapRouteActive,
            ),
        )
    }

    private fun observeWalkRuntimeDetectorTiming(
        epoch: WalkRuntimeEpoch,
        frameCapturedAtElapsedRealtimeMs: Long,
        observedAtElapsedRealtimeMs: Long,
        inferenceLatencyMs: Long,
    ): Boolean {
        if (developmentGuidanceStartBypassEnabled) {
            return walkSessionLifecycle.isRuntimeEpochCurrent(epoch) &&
                frameCapturedAtElapsedRealtimeMs >= 0L &&
                observedAtElapsedRealtimeMs >= frameCapturedAtElapsedRealtimeMs &&
                inferenceLatencyMs >= 0L
        }
        return walkRuntimeSafetyCoordinator.observe(
            WalkRuntimeSafetyObservation(
                epoch = epoch,
                observedAtElapsedRealtimeMs = observedAtElapsedRealtimeMs,
                frameCapturedAtElapsedRealtimeMs = frameCapturedAtElapsedRealtimeMs,
                inferenceLatencyMs = inferenceLatencyMs,
            ),
        ).safetyOutputsAllowed
    }

    private fun emitCameraFallbackAdvisory(
        action: NonMetricObstacleAdvisoryAction,
        expectedWalkEpoch: WalkRuntimeEpoch,
        fallbackGeneration: Int,
        lifecycleGeneration: Int,
    ) {
        if (
            !isCameraFallbackAdvisoryStillDeliverable(
                action,
                expectedWalkEpoch,
                fallbackGeneration,
                lifecycleGeneration,
            )
        ) {
            nonMetricAdvisoryPolicy.rejectDelivery(action)
            return
        }
        if (!nonMetricAdvisoryPolicy.claimDelivery(action)) return
        if (
            !isCameraFallbackAdvisoryStillDeliverable(
                action,
                expectedWalkEpoch,
                fallbackGeneration,
                lifecycleGeneration,
            ) ||
            !nonMetricAdvisoryPolicy.isDeliveryCurrent(action)
        ) {
            nonMetricAdvisoryPolicy.rejectDelivery(action)
            return
        }
        val speechAccepted = speakAdvisory(
            action = action,
            expectedWalkEpoch = expectedWalkEpoch,
            fallbackGeneration = fallbackGeneration,
            lifecycleGeneration = lifecycleGeneration,
            onDelivered = {
                runOnUiThread {
                    if (
                        isCameraFallbackAdvisoryStillDeliverable(
                            action,
                            expectedWalkEpoch,
                            fallbackGeneration,
                            lifecycleGeneration,
                        ) &&
                        nonMetricAdvisoryPolicy.isDeliveryCurrent(action)
                    ) {
                        confirmCameraFallbackAdvisoryDelivery(
                            action = action,
                            expectedWalkEpoch = expectedWalkEpoch,
                            fallbackGeneration = fallbackGeneration,
                            lifecycleGeneration = lifecycleGeneration,
                        )
                    } else {
                        nonMetricAdvisoryPolicy.rejectDelivery(action)
                    }
                }
            },
            onFailed = { nonMetricAdvisoryPolicy.rejectDelivery(action) },
        )
        if (!speechAccepted) nonMetricAdvisoryPolicy.rejectDelivery(action)
    }

    private fun confirmCameraFallbackAdvisoryDelivery(
        action: NonMetricObstacleAdvisoryAction,
        expectedWalkEpoch: WalkRuntimeEpoch,
        fallbackGeneration: Int,
        lifecycleGeneration: Int,
    ) {
        if (
            !isCameraFallbackAdvisoryStillDeliverable(
                action,
                expectedWalkEpoch,
                fallbackGeneration,
                lifecycleGeneration,
            ) ||
            !nonMetricAdvisoryPolicy.isDeliveryCurrent(action)
        ) {
            nonMetricAdvisoryPolicy.rejectDelivery(action)
            return
        }
        val nowMs = SystemClock.elapsedRealtime()
        val confirmed = synchronized(phoneMountingObservationLock) {
            if (!phoneMountingOutputsAllowed) {
                nonMetricAdvisoryPolicy.rejectDelivery(action)
                false
            } else {
                nonMetricAdvisoryPolicy.confirmDelivery(action, nowMs)
            }
        }
        if (!confirmed) return
        fieldSessionLog.recordEvent(
            "camera_non_metric_advisory_emitted",
            mapOf(
                "direction" to action.direction.name,
                "loaded_model" to (detectorLoadedModelKey ?: "none"),
                "model_fallback_used" to detectorModelFallbackUsed,
                "metric" to false,
                "tmap_authoritative" to true,
                "tmap_route_active" to currentCameraFallbackAdvisoryGate(nowMs).tmapRouteActive,
                "reports_allowed" to false,
            ),
        )
    }

    private fun isCameraFallbackAdvisoryStillDeliverable(
        action: NonMetricObstacleAdvisoryAction,
        expectedWalkEpoch: WalkRuntimeEpoch,
        fallbackGeneration: Int,
        lifecycleGeneration: Int,
    ): Boolean {
        val nowMs = SystemClock.elapsedRealtime()
        return nowMs <= action.validUntilMs &&
            cameraEnvironmentOutputsAllowed() &&
            phoneMountingOutputsAllowed &&
            isCameraFallbackLeaseCurrent(
                expectedWalkEpoch,
                fallbackGeneration,
                requireRunning = true,
            ) &&
            lifecycleGeneration == feedbackLifecycleGeneration &&
            currentAndroidLocalTactileTier(nowMs) == AndroidLocalTactileTier.CAMERA_IMU_NON_METRIC
    }

    private fun currentAndroidLocalTactileTier(nowMs: Long): AndroidLocalTactileTier {
        return resolveAndroidLocalTactileTier(currentCameraFallbackAdvisoryGate(nowMs))
    }

    private fun currentCameraFallbackAdvisoryGate(nowMs: Long): NonMetricAdvisoryGate {
        return NonMetricAdvisoryGate(
            cameraPermissionGranted = hasCameraPermission(),
            cameraFallbackRunning = cameraFallbackRunning,
            detectorAvailable = detectorAvailable,
            imuFresh = hasFreshCameraFallbackImu(nowMs),
            tmapRouteActive = hasFreshTmapFallbackContext(nowMs),
        )
    }

    private fun resolveAndroidLocalTactileTier(
        advisoryGate: NonMetricAdvisoryGate,
    ): AndroidLocalTactileTier {
        return AndroidLocalTactileCapability.resolve(
            AndroidLocalTactileCapabilityInput(
                cameraPermissionGranted = advisoryGate.cameraPermissionGranted,
                detectorAvailable = advisoryGate.detectorAvailable,
                arCoreSupported = arCoreSupported,
                depthSupported = depthSupported,
                arSessionRunning = session != null,
                cameraFallbackRunning = advisoryGate.cameraFallbackRunning,
                imuFresh = advisoryGate.imuFresh,
                tmapRouteActive = advisoryGate.tmapRouteActive,
            ),
        )
    }

    private fun hasFreshCameraFallbackImu(nowMs: Long): Boolean {
        val orientation = earthOrientationTracker.latest() ?: return false
        val ageMs = nowMs - orientation.observedAtElapsedRealtimeMs
        return ageMs in 0L..CAMERA_FALLBACK_IMU_MAX_AGE_MS &&
            orientation.accuracy != EarthOrientationAccuracy.UNRELIABLE &&
            orientation.deviceToMagneticEnu.isOrthonormal()
    }

    private fun hasFreshTmapFallbackContext(nowMs: Long): Boolean {
        val location = LocationTrustPolicy.freshOrNull(latestTrustedLocation, nowMs) ?: return false
        return isRouteActive &&
            latestTmapOnRoute &&
            !routeRequestInFlight.get() &&
            routeNavigator.hasRoute() &&
            location.accuracyM.isFinite()
    }

    /** ARCore and CameraX share one physical detector and never enqueue replacement frames. */
    private fun tryStartDetectionWork(nowElapsedRealtimeMs: Long): InferencePacingTicket? =
        synchronized(frameStateLock) {
            if (unknownFrameCopyInFlight.get()) return@synchronized null
            if (detectionInFlight.get()) {
                if (nowElapsedRealtimeMs >= adaptiveInferencePacing.snapshot().nextEligibleAtElapsedRealtimeMs) {
                    rawDetectionDueButInFlightDropCount.incrementAndGet()
                }
                return@synchronized null
            }
            if (!adaptiveInferencePacing.isDue(nowElapsedRealtimeMs)) return@synchronized null
            if (!detectionInFlight.compareAndSet(false, true)) {
                rawDetectionDueButInFlightDropCount.incrementAndGet()
                return@synchronized null
            }
            adaptiveInferencePacing.tryStart(nowElapsedRealtimeMs) ?: run {
                detectionInFlight.set(false)
                null
            }
        }

    private fun finishDetectionWork(
        ticket: InferencePacingTicket,
        detectorInvoked: Boolean,
        inferenceDurationMs: Long? = null,
        validCompletion: Boolean = false,
    ) = synchronized(frameStateLock) {
        try {
            if (detectorInvoked) {
                val completedAt = SystemClock.elapsedRealtime()
                val loadObservation = runtimeLoadObservationSource.latestObservation(completedAt)
                latestUnknownLoadObservation = loadObservation
                val accepted = adaptiveInferencePacing.complete(
                    ticket = ticket,
                    completedAtElapsedRealtimeMs = completedAt,
                    inferenceDurationMs = inferenceDurationMs,
                    thermalThrottled = latestInferenceThermalThrottled,
                    loadObservation = loadObservation,
                )
                if (accepted && validCompletion) {
                    val endToEnd = completedAt - ticket.startedAtElapsedRealtimeMs
                    observeRuntimeInferenceLoad(completion = RuntimeLoadCompletion(
                        endToEndMs = endToEnd,
                        staleOrDropped = endToEnd > MAX_DEPTH_DETECTION_SOURCE_AGE_MS,
                    ))
                }
            } else {
                adaptiveInferencePacing.cancel(ticket)
            }
        } finally {
            detectionInFlight.set(false)
        }
    }

    private fun runtimeLoadEnvironmentKey(): String =
        "${runtimeSelectionBinding ?: "unmeasured"}:${runtimeActiveCandidate}:${runtimeLoadFrameScope}:${detectorGeneration}:${visualGeometryVersion}"

    private fun observeRuntimeInferenceLoad(inputObserved: Boolean = false, completion: RuntimeLoadCompletion? = null) {
        val now = SystemClock.elapsedRealtime()
        val lastNormal = runtimeLoadNormalFrameAtMs
        val normal = detectorAvailable && !runtimeTuningPreparing && runtimeCalibration == null && unknownCalibration == null &&
            isActivityForeground && isWalkSessionRuntimeActive() &&
            latestInferenceThermalThrottled == false &&
            runCatching { !getSystemService(android.os.PowerManager::class.java).isPowerSaveMode }.getOrDefault(false) &&
            lastNormal != null && now - lastNormal in 0L..1_000L
        val observation = runtimeLoadMonitor.observe(now, runtimeLoadEnvironmentKey(), normal, inputObserved, completion)
        observeUnknownRuntimeLoad(now, normal, inputObserved, primaryCompletion = completion)
        val binding = runtimeSelectionBinding
        if (observation.pendingReason != null && binding != null && runtimeLoadPendingRecordedBinding != binding) {
            runtimeLoadPendingRecordedBinding = binding
            deviceTuningExecutor.execute {
                if (runtimeSelectionBinding == binding) {
                    val saved = deviceTuningStore.markAttemptFinished(binding, DeviceTuningRecheckReason.PERSISTENT_DEGRADATION)
                    if (!saved) runtimeLoadPendingRecordedBinding = null
                }
            }
        }
    }

    private fun observeUnknownRuntimeLoad(
        nowMs: Long,
        normal: Boolean,
        inputObserved: Boolean = false,
        primaryCompletion: RuntimeLoadCompletion? = null,
        auxiliaryCompletion: RuntimeLoadCompletion? = null,
    ) {
        val binding = unknownRuntimeBinding ?: return
        val service = unknownRuntimeService ?: return
        val key = binding.hashOrNull() ?: return
        val pending = unknownLoadControl.observe(nowMs, "$key:${service.sessionEpoch}", normal,
            inputObserved, primaryCompletion, auxiliaryCompletion)
        if (pending && !unknownLoadRecheckRecorded) {
            unknownLoadRecheckRecorded = true
            runCatching { deviceTuningExecutor.execute {
                if (unknownRuntimeBinding == binding && !unknownTuningStore.markPending(
                        binding, DeviceTuningRecheckReason.PERSISTENT_DEGRADATION,
                    )) unknownLoadRecheckRecorded = false
            } }
        }
    }

    private fun adaptiveInferencePacingStatusText(): String {
        val pacing = adaptiveInferencePacing.snapshot()
        return "pacing=${pacing.targetIntervalMs}ms idle=${pacing.cooldownMs}ms " +
            "e2e=${pacing.lastEndToEndMs ?: "unknown"}ms " +
            "detectorTotal=${pacing.lastInferenceMs ?: "unknown"}ms " +
            "thermal=${pacing.thermalThrottled ?: "unknown"} " +
            "loadPressure=${pacing.observedLoadPressure} workHeadroom=${pacing.workHeadroomMultiplier} " +
            "overFreshnessBudget=${pacing.overFreshnessBudget ?: "unknown"} reason=${pacing.reason}"
    }

    /**
     * Runs inference off the GL thread. Published snapshots retain both capture and completion
     * timestamps so a fast partial result cannot be mistaken for a fresh current-frame result.
     */
    private fun scheduleDetectionIfDue(
        provider: ArCoreFrameProvider,
        frame: Frame,
        timestampMs: Long,
        capturedAtMs: Long,
        elapsedRealtimeMs: Long,
        capturedDepthSnapshot: DepthFrameSnapshot,
        frameGeneration: Int,
        expectedWalkEpoch: WalkRuntimeEpoch,
        expectedArSessionGeneration: Long,
        visualFrameKey: VisualFrameKey? = null,
    ) {
        if (!postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION)) return
        val (pacingTicket, shouldCaptureFrame) = synchronized(frameStateLock) {
            if (!isCurrentFrameGeneration(frameGeneration, expectedWalkEpoch)) return
            if (!detectorAvailable) return
            if (frame.timestamp <= 0L) return
            if (
                lastDetectionCaptureGeneration == frameGeneration &&
                lastDetectionCaptureArSessionGeneration == expectedArSessionGeneration &&
                frame.timestamp <= lastDetectionCaptureFrameId
            ) return
            val ticket = tryStartDetectionWork(elapsedRealtimeMs) ?: return
            ticket to frameCaptureRequested.getAndSet(false)
        }
        var acquiredImage: android.media.Image? = null
        var submittedToWorker = false
        try {
            val cameraImage = provider.acquireCameraImageOrNull(frame) ?: return
            acquiredImage = cameraImage
            synchronized(frameStateLock) {
                if (!isCurrentFrameGeneration(frameGeneration, expectedWalkEpoch)) {
                    return
                }
                lastDetectionCaptureFrameId = frame.timestamp
                lastDetectionCaptureGeneration = frameGeneration
                lastDetectionCaptureArSessionGeneration = expectedArSessionGeneration
            }
            val generation = frameGeneration
            val imageWidth = cameraImage.width
            val imageHeight = cameraImage.height
            val orientationBasis = FloatArray(6)
            frame.transformCoordinates2d(Coordinates2d.IMAGE_NORMALIZED,
                floatArrayOf(0f, 0f, 1f, 0f, 0f, 1f), Coordinates2d.VIEW, orientationBasis)
            val imageQuarterTurns = UprightCameraImage.quarterTurns(orientationBasis)
            val detectionIdentity = AndroidDetectionSnapshotFrameIdentity(
                captureFrameId = frame.timestamp,
                frameTimestampMs = timestampMs,
            )
            val frameEvidence = DetectionFrameEvidence(
                frameId = frame.timestamp,
                frameTimestampMs = timestampMs,
                depthSnapshot = capturedDepthSnapshot,
                depthMapper = createFrozenDepthMapper(
                    frame = frame,
                    frameId = frame.timestamp,
                    imageWidth = imageWidth,
                    imageHeight = imageHeight,
                    snapshot = capturedDepthSnapshot,
                ),
                tactileContext = buildTactileProjectionContext(frame, elapsedRealtimeMs),
                motionContext = buildDepthMotionContext(elapsedRealtimeMs),
                imageQuarterTurns = imageQuarterTurns,
                navigationActive = isRouteActive && !routeRequestInFlight.get(),
                tmapOnRoute = latestTmapOnRoute,
                visualFrameKey = visualFrameKey?.takeIf {
                    it.frameId == frame.timestamp && it.cameraTimestampNs == cameraImage.timestamp &&
                        it.cameraTimestampNs == capturedDepthSnapshot.cameraImageTimestampNs
                },
            )
            detectorExecutor.execute {
                var detectorInvoked = false
                var inferenceDurationMs: Long? = null
                var detectorSucceeded = false
                try {
                    if (!isCurrentFrameGeneration(generation, expectedWalkEpoch)) {
                        return@execute
                    }
                    val yPlane = cameraImage.planes.firstOrNull()
                    val qualityObservation = cameraFrameQualityObservation(
                        epoch = expectedWalkEpoch,
                        observedAtElapsedRealtimeMs = elapsedRealtimeMs,
                        frameAvailable = true,
                        width = cameraImage.width,
                        height = cameraImage.height,
                        yPlaneBuffer = yPlane?.buffer,
                        yPlaneRowStride = yPlane?.rowStride,
                        yPlanePixelStride = yPlane?.pixelStride,
                    )
                    observeOfficialEnvironmentCameraFrame(qualityObservation)
                    if (!currentRuntimeMetricOutputAllowsWork(expectedArSessionGeneration)) {
                        return@execute
                    }
                    val rawCollectionAllowed = integratedConsentSession.isAllowed(
                        IntegratedConsentItem.RAW_SOURCE_COLLECTION,
                    )
                    val reportJpeg = if (reportPrivacyConsentSession.isGranted()) {
                        encodeReportFrameJpeg(cameraImage)
                    } else {
                        null
                    }
                    val captureJpeg = if (
                        shouldCaptureFrame &&
                        rawCollectionAllowed &&
                        sensitiveDebugTransferAllowed()
                    ) {
                        encodeDebugFrameJpeg(cameraImage) ?: reportJpeg
                    } else {
                        null
                    }
                    val startedAtMs = System.currentTimeMillis()
                    var completedAtMs = startedAtMs
                    var detectorStartedAtElapsedRealtimeMs = SystemClock.elapsedRealtime()
                    var result = AndroidDetectionResult.empty()
                    val admission = CameraDetectorAdmissionPolicy.admit(
                        currentEpoch = expectedWalkEpoch,
                        nowElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                        observation = qualityObservation,
                        approvedProfile = activeCameraFrameQualityProfile,
                    ) {
                        detectorInvoked = true
                        detectorStartedAtElapsedRealtimeMs = SystemClock.elapsedRealtime()
                        result = try {
                            frameDetector.detectOriented(
                                cameraImage,
                                timestampMs = timestampMs,
                                quarterTurns = imageQuarterTurns,
                            ) { partialResult ->
                                val observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime()
                                val inferenceLatencyMs = partialResult.timing.totalMs
                                    ?: (
                                        observedAtElapsedRealtimeMs -
                                            detectorStartedAtElapsedRealtimeMs
                                    )
                                if (
                                    observeWalkRuntimeDetectorTiming(
                                        epoch = expectedWalkEpoch,
                                        frameCapturedAtElapsedRealtimeMs = elapsedRealtimeMs,
                                        observedAtElapsedRealtimeMs = observedAtElapsedRealtimeMs,
                                        inferenceLatencyMs = inferenceLatencyMs,
                                    )
                                ) {
                                    this@MainActivity.publishDetectionSnapshot(
                                        result = partialResult,
                                        generation = generation,
                                        detectionIdentity = detectionIdentity,
                                        capturedAtMs = capturedAtMs,
                                        startedAtMs = startedAtMs,
                                        completedAtMs = System.currentTimeMillis(),
                                        imageWidth = imageWidth,
                                        imageHeight = imageHeight,
                                        reportImageJpeg = reportJpeg,
                                        frameEvidence = frameEvidence,
                                        expectedWalkEpoch = expectedWalkEpoch,
                                        capturedAtElapsedRealtimeMs = elapsedRealtimeMs,
                                    )
                                }
                            }.also {
                                if (isCurrentFrameGeneration(generation, expectedWalkEpoch)) {
                                    detectorRuntimeSupervisor.onSuccess()
                                }
                                detectorSucceeded = true
                            }
                        } catch (error: RuntimeException) {
                            handleDetectorRuntimeFailure(error, generation, expectedWalkEpoch)
                            AndroidDetectionResult.empty()
                        } finally {
                            completedAtMs = System.currentTimeMillis()
                            inferenceDurationMs = SystemClock.elapsedRealtime() - detectorStartedAtElapsedRealtimeMs
                        }
                    }
                    if (!admission.detectorInvocationAllowed) {
                        completedAtMs = System.currentTimeMillis()
                        return@execute
                    }
                    inferenceDurationMs = result.timing.totalMs ?: inferenceDurationMs
                    if (detectorSucceeded) {
                        val observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime()
                        val inferenceLatencyMs = result.timing.totalMs
                            ?: (observedAtElapsedRealtimeMs - detectorStartedAtElapsedRealtimeMs)
                        if (
                            !observeWalkRuntimeDetectorTiming(
                                epoch = expectedWalkEpoch,
                                frameCapturedAtElapsedRealtimeMs = elapsedRealtimeMs,
                                observedAtElapsedRealtimeMs = observedAtElapsedRealtimeMs,
                                inferenceLatencyMs = inferenceLatencyMs,
                            )
                        ) return@execute
                    }
                    val published = this@MainActivity.publishDetectionSnapshot(
                        result = result,
                        generation = generation,
                        detectionIdentity = detectionIdentity,
                        capturedAtMs = capturedAtMs,
                        startedAtMs = startedAtMs,
                        completedAtMs = completedAtMs,
                        imageWidth = imageWidth,
                        imageHeight = imageHeight,
                        reportImageJpeg = reportJpeg,
                        frameEvidence = frameEvidence,
                        expectedWalkEpoch = expectedWalkEpoch,
                        capturedAtElapsedRealtimeMs = elapsedRealtimeMs,
                    )
                    if (published != null) {
                        recordRawCollectionDetectionMetadata(
                            expectedWalkEpoch = expectedWalkEpoch,
                            detectionCount = result.detections.size,
                            inferenceMs = result.timing.totalMs
                                ?: (completedAtMs - startedAtMs),
                            modelRevision = result.timing.modelKey ?: detectorLoadedModelKey,
                        )
                        synchronized(frameStateLock) {
                            if (!isCurrentFrameGeneration(generation, expectedWalkEpoch)) {
                                return@synchronized
                            }
                            if (captureJpeg != null) {
                                runIfActivityOriginalUploadAllowed {
                                    frameCaptureUploader.upload(
                                        imageJpeg = captureJpeg,
                                        metadataJson = buildFrameCaptureMetadataJson(
                                            frameTimestampMs = timestampMs,
                                            imageWidth = imageWidth,
                                            imageHeight = imageHeight,
                                            detectDurationMs = completedAtMs - startedAtMs,
                                            result = result,
                                            forcedCustom = shouldCaptureFrame,
                                        ),
                                    )
                                }
                            }
                        }
                        if (shouldCaptureFrame) {
                            runOnUiThread {
                                if (isCurrentFrameGeneration(generation, expectedWalkEpoch)) {
                                    updateFrameCaptureButton()
                                }
                            }
                        }
                    }
                } finally {
                    try {
                        cameraImage.close()
                    } finally {
                        finishDetectionWork(
                            pacingTicket, detectorInvoked, inferenceDurationMs,
                            validCompletion = detectorSucceeded && isCurrentFrameGeneration(generation, expectedWalkEpoch),
                        )
                    }
                }
            }
            submittedToWorker = true
        } catch (_: RejectedExecutionException) {
            Unit
        } finally {
            if (!submittedToWorker) {
                try {
                    acquiredImage?.close()
                } finally {
                    finishDetectionWork(pacingTicket, detectorInvoked = false)
                }
            }
        }
    }

    private fun encodeDebugFrameJpeg(cameraImage: android.media.Image): ByteArray? {
        return try {
            val argb = frameCapturePreprocessor.decode(cameraImage)
            argb.toScaledJpeg(maxDimension = DEBUG_FRAME_CAPTURE_MAX_DIMENSION, quality = DEBUG_FRAME_CAPTURE_JPEG_QUALITY)
        } catch (_: RuntimeException) {
            null
        }
    }

    private fun encodeReportFrameJpeg(cameraImage: android.media.Image): ByteArray? {
        return try {
            val argb = frameCapturePreprocessor.decode(cameraImage)
            argb.toScaledJpeg(
                maxDimension = REPORT_FRAME_CAPTURE_MAX_DIMENSION,
                quality = REPORT_FRAME_CAPTURE_JPEG_QUALITY,
            )
        } catch (_: RuntimeException) {
            null
        }
    }

    internal fun publishDetectionSnapshot(
        result: AndroidDetectionResult,
        generation: Int,
        detectionIdentity: AndroidDetectionSnapshotFrameIdentity,
        capturedAtMs: Long,
        startedAtMs: Long,
        completedAtMs: Long,
        imageWidth: Int,
        imageHeight: Int,
        reportImageJpeg: ByteArray?,
        frameEvidence: DetectionFrameEvidence,
        expectedWalkEpoch: WalkRuntimeEpoch? = null,
        capturedAtElapsedRealtimeMs: Long? = null,
    ): DetectionSnapshot? = synchronized(frameStateLock) {
        if (
            generation != detectorGeneration ||
            (
                expectedWalkEpoch != null &&
                    (
                        !walkSessionLifecycle.isRuntimeEpochCurrent(expectedWalkEpoch) ||
                            !cameraEnvironmentOutputsAllowed()
                    )
            )
        ) return@synchronized null
        DetectionSnapshot.published(
            result = result,
            identity = detectionIdentity,
            capturedAtMs = capturedAtMs,
            startedAtMs = startedAtMs,
            completedAtMs = completedAtMs,
            imageWidth = imageWidth,
            imageHeight = imageHeight,
            reportImageJpeg = reportImageJpeg,
            frameEvidence = frameEvidence,
            capturedAtElapsedRealtimeMs = capturedAtElapsedRealtimeMs,
        ).also { snapshot ->
            latestDetectionSnapshot = snapshot
        }
    }

    // Frozen FP-017 trace markers; the live contract below additionally binds
    // every callback to the exact walk epoch and component generation.
    /*
private fun isCurrentFrameGeneration(generation: Int)
generation != cameraFallbackGeneration
    */
    private fun isCurrentFrameGeneration(
        generation: Int,
        expectedWalkEpoch: WalkRuntimeEpoch? = null,
    ): Boolean =
        firstRunOnboardingComplete() &&
            isWalkSessionRuntimeActive() &&
            generation == detectorGeneration &&
            (
                expectedWalkEpoch == null ||
                    walkSessionLifecycle.isRuntimeEpochCurrent(expectedWalkEpoch)
            )

    private fun selectOverlayDetections(
        detectionSnapshot: DetectionSnapshot,
        nowMs: Long,
        currentFrameTimestampMs: Long,
    ): OverlayDetectionSelection {
        val staleReason = detectionSnapshot.staleReason(
            nowMs, currentFrameTimestampMs,
            MAX_OVERLAY_DETECTION_SOURCE_AGE_MS, MAX_OVERLAY_DETECTION_FRAME_DELTA_MS,
        )
        // Keep one capture identity. An empty/new result must not resurrect boxes from an older frame.
        val detections = if (staleReason == null) detectionSnapshot.detections else emptyList()
        return OverlayDetectionSelection(
            detections = detections,
            mappingSnapshot = detectionSnapshot,
            debugState = buildOverlayDebugState(
                selection = if (detections.isEmpty()) "empty" else "fresh_latest",
                detections = detections,
                mappingSnapshot = detectionSnapshot,
                nowMs = nowMs,
                currentFrameTimestampMs = currentFrameTimestampMs,
                staleReason = staleReason,
                holdApplied = false,
            ),
        )
    }

    private fun buildOverlayDebugState(
        selection: String,
        detections: List<DetectionCandidate>,
        mappingSnapshot: DetectionSnapshot,
        nowMs: Long,
        currentFrameTimestampMs: Long,
        staleReason: String?,
        holdApplied: Boolean,
    ): OverlayDebugState {
        return OverlayDebugState(
            selection = selection,
            detectionCount = detections.size,
            tactileDetectionCount = detections.count { it.isTactileDetection() },
            sourceAgeMs = mappingSnapshot.sourceAgeMs(nowMs),
            frameDeltaMs = mappingSnapshot.frameDeltaMs(currentFrameTimestampMs),
            staleReason = staleReason,
            holdApplied = holdApplied && detections.isNotEmpty(),
            snapshotPartial = mappingSnapshot.partial,
        )
    }

    private fun ArgbImage.toScaledJpeg(maxDimension: Int, quality: Int): ByteArray? {
        if (width <= 0 || height <= 0 || pixels.isEmpty()) return null
        val bitmap = Bitmap.createBitmap(pixels, width, height, Bitmap.Config.ARGB_8888)
        val maxSide = maxOf(width, height).coerceAtLeast(1)
        val scale = (maxDimension / maxSide.toFloat()).coerceAtMost(1f)
        val outputBitmap = if (scale < 1f) {
            Bitmap.createScaledBitmap(
                bitmap,
                (width * scale).toInt().coerceAtLeast(1),
                (height * scale).toInt().coerceAtLeast(1),
                true,
            )
        } else {
            bitmap
        }
        return try {
            ByteArrayOutputStream().use { output ->
                outputBitmap.compress(Bitmap.CompressFormat.JPEG, quality.coerceIn(1, 100), output)
                output.toByteArray()
            }
        } finally {
            if (outputBitmap !== bitmap) outputBitmap.recycle()
            bitmap.recycle()
        }
    }

    private fun buildFrameCaptureMetadataJson(
        frameTimestampMs: Long,
        imageWidth: Int,
        imageHeight: Int,
        detectDurationMs: Long,
        result: AndroidDetectionResult,
        forcedCustom: Boolean,
    ): String {
        val detections = result.detections
        val top = detections.maxByOrNull { it.detectionConfidence }
        val json = JSONObject()
            .put("frame_timestamp_ms", frameTimestampMs)
            .put("camera_image_width", imageWidth)
            .put("camera_image_height", imageHeight)
            .put("detect_duration_ms", detectDurationMs)
            .put("detection_count", detections.size)
            .put("capture_policy", "manual_jpeg_no_gps_no_depth_raw_full_detector")
            .put("force_custom_tactile", forcedCustom)
            .put("detector_completed_models", JSONArray(result.timing.completedModels))
            .put("detector_skipped_models", JSONArray(result.timing.skippedModels))
            .put("detector_partial", result.partial)
            .put("detector_loaded_model_key", detectorLoadedModelKey)
            .put("detector_model_fallback_used", detectorModelFallbackUsed)
            .put("detector_model_load_reason", detectorLoadReason)
        result.timing.customInferenceMs?.let { json.put("detector_custom_inference_ms", it) }
        result.timing.cocoInferenceMs?.let { json.put("detector_coco_inference_ms", it) }
        result.timing.modelKey?.let { json.put("detector_model_key", it) }
        result.timing.modelPreprocessMs?.let { json.put("detector_model_preprocess_ms", it) }
        result.timing.modelInferenceMs?.let { json.put("detector_model_inference_ms", it) }
        result.timing.modelParseMs?.let { json.put("detector_model_parse_ms", it) }
        json.put(
            "detections",
            JSONArray(
                detections
                    .sortedByDescending { it.detectionConfidence }
                    .take(MAX_FRAME_CAPTURE_DETECTIONS)
                    .map { detection ->
                        JSONObject()
                            .put("class_name", detection.className)
                            .put("confidence", detection.detectionConfidence)
                            .put("bbox", detection.bboxNorm.toJson())
                    },
            ),
        )
        if (top != null) {
            json.put("top_detection_class_name", top.className)
                .put("top_detection_confidence", top.detectionConfidence)
                .put("top_detection_bbox", top.bboxNorm.toJson())
            resolveReportThreshold(detectorModelKeyForReports, top.className)?.let { threshold ->
                json.put("top_detection_threshold_used", threshold)
            }
        }
        return json.toString()
    }

    private fun RectNorm.toJson(): JSONObject {
        return JSONObject()
            .put("x", x)
            .put("y", y)
            .put("width", width)
            .put("height", height)
    }

    private fun buildDebugOverlayBoxes(
        frame: Frame,
        detections: List<DetectionCandidate>,
        bestOutput: TrackedObjectDepth?,
        imageWidth: Int?,
        imageHeight: Int?,
    ): List<DebugBboxOverlayView.DebugOverlayBox> {
        if (imageWidth == null || imageHeight == null) {
            return emptyList()
        }
        val mappedDetectionBoxes = detections
            .sortedByDescending { it.detectionConfidence }
            .take(MAX_OVERLAY_DETECTION_BOXES)
            .mapNotNull { detection ->
                val rect = detection.bboxNorm.toViewRect(frame, imageWidth, imageHeight) ?: return@mapNotNull null
                DebugBboxOverlayView.DebugOverlayBox(
                    rectPx = rect,
                    label = "${detection.className} ${percent(detection.detectionConfidence)}",
                    best = false,
                    className = detection.className,
                )
            }
        val bestBox = bestOutput?.let { output ->
            output.bboxNorm.toViewRect(frame, imageWidth, imageHeight)?.let { rect ->
                DebugBboxOverlayView.DebugOverlayBox(
                    rectPx = rect,
                    label = buildString {
                        append(output.className)
                        append(" ")
                        append(percent(output.detectionConfidence))
                        append(" · ")
                        append(output.source.name)
                        output.riskDistanceM?.let { distance -> append(" · ${meters(distance)}") }
                        output.prediction?.let { predicted ->
                            append(String.format(Locale.US, " · 예측 %.2fm ±%.2fm · 공백 %dms",
                                predicted.distanceM, predicted.errorBoundM, predicted.predictionAgeMs))
                        }
                        append(" · samples ")
                        append(output.validSampleCount)
                        append(" · motion=${output.motionEstimate.direction}")
                        output.motionEstimate.objectSpeedMps?.let {
                            append(" · 물체 ${String.format(Locale.US, "%.1f", it)}m/s")
                        }
                        output.motionEstimate.relativeClosingSpeedMps?.let {
                            val direction = if (it >= 0f) "상대 접근" else "멀어짐"
                            append(" · $direction ${String.format(Locale.US, "%.1f", kotlin.math.abs(it))}m/s")
                        }
                    },
                    best = true,
                    className = output.className,
                )
            }
        }
        val boxes = if (bestBox == null) mappedDetectionBoxes else listOf(bestBox) +
            mappedDetectionBoxes.filterNot { it.className == bestBox.className && it.rectPx == bestBox.rectPx }
        return boxes
    }

    /** Freezes the current ARCore image-to-depth transform; the Frame is never retained. */
    private fun createFrozenDepthMapper(
        frame: Frame,
        frameId: Long,
        imageWidth: Int,
        imageHeight: Int,
        snapshot: DepthFrameSnapshot,
        allowMissingDepth: Boolean = false,
    ): FrozenImageToTextureCoordinateMapper? {
        if (imageWidth <= 0 || imageHeight <= 0) return null
        val depthSize = when {
            snapshot.rawDepth != null -> ImageSize(snapshot.rawDepth.width, snapshot.rawDepth.height)
            snapshot.fullDepth != null -> ImageSize(snapshot.fullDepth.width, snapshot.fullDepth.height)
            // The mapper returns normalized UVs. With no depth samples this neutral size permits
            // current geometry validation only; it does not create pixels or reuse an old mapping.
            allowMissingDepth -> ImageSize(1, 1)
            else -> return null
        }
        if (depthSize.width <= 0 || depthSize.height <= 0) return null
        val input = floatArrayOf(
            0f, 0f,
            imageWidth.toFloat(), 0f,
            0f, imageHeight.toFloat(),
            imageWidth.toFloat(), imageHeight.toFloat(),
            imageWidth / 2f, imageHeight / 2f,
        )
        val output = FloatArray(input.size)
        return try {
            frame.transformCoordinates2d(
                Coordinates2d.IMAGE_PIXELS,
                input,
                Coordinates2d.TEXTURE_NORMALIZED,
                output,
            )
            val points = output.toList().chunked(2).map { values -> Point2(values[0], values[1]) }
            val transform = FrozenImageToDepthTransform.create(
                frameId = frameId,
                mappedCorners = points.take(4),
                mappedCenter = points[4],
            ) ?: return null
            FrozenImageToTextureCoordinateMapper(
                frameId = frameId,
                transform = transform,
                depthSize = depthSize,
            )
        } catch (_: RuntimeException) {
            null
        }
    }

    private fun RectNorm.toViewRect(frame: Frame, imageWidth: Int, imageHeight: Int): RectF? {
        if (imageWidth <= 0 || imageHeight <= 0) return null
        val left = x.coerceIn(0f, 1f) * imageWidth
        val top = y.coerceIn(0f, 1f) * imageHeight
        val right = (x + width).coerceIn(0f, 1f) * imageWidth
        val bottom = (y + height).coerceIn(0f, 1f) * imageHeight
        val imageCorners = floatArrayOf(
            left, top,
            right, top,
            right, bottom,
            left, bottom,
        )
        val viewCorners = FloatArray(imageCorners.size)
        return try {
            frame.transformCoordinates2d(
                Coordinates2d.IMAGE_PIXELS,
                imageCorners,
                Coordinates2d.VIEW,
                viewCorners,
            )
            if (viewCorners.any { !it.isFinite() }) return null
            val xs = floatArrayOf(viewCorners[0], viewCorners[2], viewCorners[4], viewCorners[6])
            val ys = floatArrayOf(viewCorners[1], viewCorners[3], viewCorners[5], viewCorners[7])
            val maxWidth = surfaceWidth.takeIf { it > 0 }?.toFloat() ?: return null
            val maxHeight = surfaceHeight.takeIf { it > 0 }?.toFloat() ?: return null
            val mappedLeft = xs.minOrNull()?.coerceIn(0f, maxWidth) ?: return null
            val mappedTop = ys.minOrNull()?.coerceIn(0f, maxHeight) ?: return null
            val mappedRight = xs.maxOrNull()?.coerceIn(mappedLeft, maxWidth) ?: return null
            val mappedBottom = ys.maxOrNull()?.coerceIn(mappedTop, maxHeight) ?: return null
            RectF(mappedLeft, mappedTop, mappedRight, mappedBottom)
        } catch (_: RuntimeException) {
            null
        }
    }

    private fun setActionButton(text: String, mode: ActionMode, enabled: Boolean) {
        actionMode = mode
        actionRequestedEnabled = enabled
        if (::actionButton.isInitialized) {
            actionButton.text = text
            applyActionButtonState()
        }
    }

    private fun applyActionButtonState() {
        if (!::actionButton.isInitialized) return
        actionButton.isEnabled = actionRequestedEnabled &&
            (
                actionMode != ActionMode.START ||
                    (
                        firstRunOnboardingComplete() &&
                            isStartupCapabilityConfirmed()
                    )
            )
    }

    private fun openAppSettings() {
        val missing = requiredStartWalkObservedPermissions()
            .filterNot(currentObservedPermissionSnapshot()::isGranted)
            .toSet()
        if (missing.isNotEmpty() || permissionRecoveryGate.blocksAutomaticResourceStart) {
            if (!permissionRecoveryGate.blocksAutomaticResourceStart) {
                enterPermissionRecoveryBarrier(missing, "settings_requested")
            }
            permissionRecoveryGate = permissionRecoveryGate.settingsPending()
            persistPermissionRecoveryGate()
        }
        startActivity(
            Intent(
                Settings.ACTION_APPLICATION_DETAILS_SETTINGS,
                Uri.fromParts("package", packageName, null),
            ),
        )
    }

    private fun unknownFrameCaptureIsDue(nowMs: Long): Boolean {
        if (detectionInFlight.get() || unknownFrameCopyInFlight.get()) return false
        val service = unknownRuntimeService ?: return false
        val state = service.stats()
        if (state.stopping || state.inflight || state.pending || state.copying) return false
        val context = unknownProcessingContext?.takeIf { it.service === service } ?: return true
        // Backstop for an owner that terminated without a result callback. Do not invent a latency
        // sample; normal discards carry their actual completion time through onDiscard below.
        synchronized(frameStateLock) {
            context.activeTicket?.takeIf {
                nowMs - it.startedAtElapsedRealtimeMs > MAX_DEPTH_DETECTION_SOURCE_AGE_MS
            }?.let {
                context.pacing.cancel(it)
                if (context.activeTicket === it) context.activeTicket = null
            }
        }
        return context.pacing.isDue(nowMs)
    }

    private fun currentUnknownCaptureProcessingAllowsWork(capture: UnknownCaptureProcessingLease): Boolean =
        synchronized(runtimeMetricStateLock) {
            val nowMs = SystemClock.elapsedRealtime()
            capture.frameId > 0L && capture.frameId <= runtimeMetricLastFrameTimestampNanos &&
                nowMs - capture.capturedAtElapsedRealtimeMs in 0L..MAX_DEPTH_DETECTION_SOURCE_AGE_MS &&
                (capture.gapDeadlineElapsedRealtimeMs == null || nowMs <= capture.gapDeadlineElapsedRealtimeMs) &&
                runtimeVisualDepthFrameTracking &&
                currentRuntimeVisualDepthProcessingAllowsWork(
                    capture.arLease, runtimeMetricLastFrameTimestampNanos, runtimeVisualDepthFrameTracking,
                )
        }

    /** Capture on the GL owner, then copy off-thread before releasing the Image. No primary result
     * or old primary capture waits in front of this auxiliary frame. Native inference/postprocessing
     * retain the service's one-flight bound and may overlap the next primary invocation. */
    private fun scheduleUnknownDetectionIfDue(
        provider: ArCoreFrameProvider,
        frame: Frame,
        snapshot: DepthFrameSnapshot,
        capturedElapsedMs: Long,
        generation: Int,
        epoch: WalkRuntimeEpoch,
        arLease: ArSessionLease,
    ) {
        if (provider !== arLease.provider ||
            !postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.OBSTACLE_DETECTION) ||
            !currentRuntimeVisualDepthProcessingAllowsWork(
                arLease, frame.timestamp, frame.camera.trackingState == TrackingState.TRACKING,
            )
        ) return
        val arGeneration = arLease.generation
        val processingLease = synchronized(runtimeMetricStateLock) {
            UnknownCaptureProcessingLease(
                arLease, frame.timestamp, capturedElapsedMs,
                if (runtimeMetricOutputAllowed) null else runtimeMetricLastValidFrameAtMs + 600L,
            )
        }
        if (!currentUnknownCaptureProcessingAllowsWork(processingLease)) return
        val service = unknownRuntimeService ?: return
        val geometryVersion = synchronized(frameStateLock) {
            if (!isCurrentFrameGeneration(generation, epoch) ||
                !unknownFrameCaptureIsDue(capturedElapsedMs) ||
                !unknownFrameCopyInFlight.compareAndSet(false, true)
            ) return
            visualGeometryVersion
        }
        var image: android.media.Image? = null
        var queued = false
        try {
            val owned = provider.acquireCameraImageOrNull(frame) ?: return
            image = owned
            if (owned.timestamp <= 0L || owned.timestamp != snapshot.cameraImageTimestampNs) return
            val basis = FloatArray(6)
            frame.transformCoordinates2d(Coordinates2d.IMAGE_NORMALIZED,
                floatArrayOf(0f, 0f, 1f, 0f, 0f, 1f), Coordinates2d.VIEW, basis)
            val evidence = UnknownCaptureEvidence(
                frameId = frame.timestamp,
                depthSnapshot = snapshot,
                depthMapper = createFrozenDepthMapper(
                    frame, frame.timestamp, owned.width, owned.height, snapshot, allowMissingDepth = true,
                ),
                motionContext = buildDepthMotionContext(capturedElapsedMs),
                imageQuarterTurns = UprightCameraImage.quarterTurns(basis),
                processingLease = processingLease,
            )
            detectorExecutor.execute {
                try {
                    if (unknownRuntimeService !== service || !isCurrentFrameGeneration(generation, epoch) ||
                        synchronized(frameStateLock) { visualGeometryVersion != geometryVersion }
                    ) return@execute
                    val yPlane = owned.planes.firstOrNull()
                    val qualityObservation = cameraFrameQualityObservation(
                        epoch = epoch,
                        observedAtElapsedRealtimeMs = capturedElapsedMs,
                        frameAvailable = true,
                        width = owned.width,
                        height = owned.height,
                        yPlaneBuffer = yPlane?.buffer,
                        yPlaneRowStride = yPlane?.rowStride,
                        yPlanePixelStride = yPlane?.pixelStride,
                    )
                    observeOfficialEnvironmentCameraFrame(qualityObservation)
                    if (!currentUnknownCaptureProcessingAllowsWork(processingLease)) return@execute
                    CameraDetectorAdmissionPolicy.admit(
                        currentEpoch = epoch,
                        nowElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                        observation = qualityObservation,
                        approvedProfile = activeCameraFrameQualityProfile,
                    ) {
                        submitUnknownObjectFrame(owned, evidence, generation, epoch, arGeneration,
                            capturedElapsedMs, geometryVersion)
                    }
                } finally {
                    try { owned.close() } finally { unknownFrameCopyInFlight.set(false) }
                }
            }
            queued = true
        } catch (error: RuntimeException) {
            if (isCurrentFrameGeneration(generation, epoch)) {
                unknownRuntimeStatus = "추가 물체 프레임 대기: ${error.javaClass.simpleName}"
            }
        } finally {
            if (!queued) {
                try { image?.close() } finally { unknownFrameCopyInFlight.set(false) }
            }
        }
    }

    /** Copies only admitted auxiliary frames while this worker still owns the open CPU Image. */
    private fun submitUnknownObjectFrame(
        image: android.media.Image,
        evidence: UnknownCaptureEvidence,
        generation: Int,
        epoch: WalkRuntimeEpoch,
        arGeneration: Long,
        capturedElapsedMs: Long,
        geometryVersion: Long,
    ) {
        val service = unknownRuntimeService ?: return
        if (service.stats().stopping) {
            latestUnknownFeedback = null
            unknownRuntimeStatus = "추가 물체 인식 확인 필요"
            return
        }
        if (!isCurrentFrameGeneration(generation, epoch) ||
            !currentUnknownCaptureProcessingAllowsWork(evidence.processingLease) || !isActivityForeground
        ) return
        val geometryId = "$arGeneration:$geometryVersion:${image.width}x${image.height}"
        val context = synchronized(frameStateLock) {
            if (unknownRuntimeService !== service || !isCurrentFrameGeneration(generation, epoch) ||
                visualGeometryVersion != geometryVersion
            ) return
            unknownProcessingContext?.takeIf {
                it.service === service && it.detectorGeneration == generation && it.walkEpoch == epoch &&
                    it.arSessionGeneration == arGeneration && it.geometryId == geometryId
            } ?: UnknownProcessingContext(
                unknownContextSequence.incrementAndGet(), service, generation, epoch,
                arGeneration, geometryId, stepLengthEstimator.stepLengthM,
            ).also { unknownProcessingContext = it; latestUnknownFeedback = null }
        }
        // A service can discard an expired capture without calling the depth consumer. Do not let
        // its old pacing ticket prevent all later fresh work; never cancel an active native flight.
        context.activeTicket?.let { old ->
            val state = service.stats()
            if (!state.inflight && !state.pending && !state.copying &&
                SystemClock.elapsedRealtime() - old.startedAtElapsedRealtimeMs > MAX_DEPTH_DETECTION_SOURCE_AGE_MS
            ) {
                context.pacing.cancel(old)
                context.activeTicket = null
            }
        }
        val ticket = context.pacing.tryStart(capturedElapsedMs) ?: return
        context.activeTicket = ticket
        context.activeFrameId = evidence.frameId
        var submitted = false
        try {
            val token = FastSamFrameToken(
                FastSamFrameToken.Source.LIVE_CAMERA, service.sessionEpoch, evidence.frameId,
                evidence.depthSnapshot.frameTimestampNs, image.timestamp, capturedElapsedMs * 1_000_000L,
                geometryId, image.width, image.height,
            )
            if (!token.isFreshAt(SystemClock.elapsedRealtimeNanos(), MAX_DEPTH_DETECTION_SOURCE_AGE_MS)) {
                handleUnknownFrameDiscard(token, "stale_before_copy")
                return
            }
            val capture = FrozenUnknownDepthCapture.freeze(
                token, evidence.depthSnapshot,
                evidence.depthMapper?.imagePixelsToDepthUvMatrix(image.width, image.height),
                evidence.depthMapper?.frameId ?: evidence.frameId,
                evidence.motionContext,
                imageQuarterTurns = evidence.imageQuarterTurns,
            ) ?: return
            if (!isUnknownCaptureContextCurrent(context, evidence.processingLease)) return
            val admission = service.submit(image, token, UnknownFrameAttachment(context, capture, ticket, evidence.processingLease))
            submitted = admission == FastSamRuntimeService.Admission.ACCEPTED ||
                admission == FastSamRuntimeService.Admission.REPLACED_PENDING
            if (admission == FastSamRuntimeService.Admission.STALE) {
                handleUnknownFrameDiscard(token, "stale_during_copy")
            }
        } catch (error: RuntimeException) {
            if (isUnknownCaptureContextCurrent(context, evidence.processingLease)) {
                unknownRuntimeStatus = "추가 물체 프레임 확인 실패: ${error.javaClass.simpleName}"
            }
        } finally {
            if (!submitted) {
                context.pacing.cancel(ticket)
                if (context.activeTicket === ticket) context.activeTicket = null
            }
        }
    }

    /** Runs on FastSAM's CPU post owner, including the complete mask/depth/consumer flight. */
    private fun consumeUnknownObjectResult(result: FastSamResult<UnknownRuntimeAttachment>) {
        val attachment = result.attachment as? UnknownFrameAttachment ?: return
        val context = attachment.context
        val started = SystemClock.elapsedRealtime()
        try {
            if (!isUnknownCaptureContextCurrent(context, attachment.processingLease)) return
            val processed = context.pipeline.process(
                attachment.capture, result.token, result.masks, started,
            )
            val completed = SystemClock.elapsedRealtime()
            if (!isUnknownCaptureContextCurrent(context, attachment.processingLease)) return
            if (!isUnknownContextCurrent(context)) {
                unknownRuntimeStatus = "추가 영역 ${result.masks.size}개 · Depth 일시 공백 · 거리 안내 대기"
                return
            }
            val batch = context.feedback.admit(
                outputs = (processed.objects + processed.proximityObjects).map { output ->
                    output.copy(trackId = "unknown:${context.identity}:${output.trackId}")
                },
                sourceFrameId = result.token.frameId,
                sourceTimestampMs = attachment.capture.frameTimestampMs,
                sourceCapturedAtElapsedRealtimeNs = result.token.capturedElapsedNs,
                completedAtElapsedRealtimeMs = completed,
                sourceEpoch = context.walkEpoch,
                currentEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull(),
                nowElapsedRealtimeMs = completed,
            )
            synchronized(frameStateLock) {
                if (!isUnknownContextCurrent(context)) return
                val batches = UnknownObjectFeedbackPolicy.mergeRetainedRegions(
                    previous = latestUnknownFeedback?.takeIf { it.context === context }?.batches.orEmpty(),
                    fresh = batch,
                    retainedTrackIds = processed.retainedProximityRegionIds.mapTo(hashSetOf()) {
                        "unknown:${context.identity}:$it"
                    },
                    currentEpoch = context.walkEpoch,
                    nowMs = completed,
                )
                // Each retained region keeps its original capture and deadline alongside new depth.
                latestUnknownFeedback = batches.takeIf { it.isNotEmpty() }?.let { UnknownFeedbackObservation(context, it) }
                val measured = (processed.objects + processed.proximityObjects).count { it.source.metric && it.riskDistanceM != null }
                unknownRuntimeStatus = "추가 영역 ${result.masks.size}개 · 유효 거리 ${measured}개 · " +
                    "${completed - result.token.capturedElapsedNs / 1_000_000L}ms · ${result.runtime.actualBackend}"
            }
        } finally {
            context.pacing.complete(
                attachment.ticket, SystemClock.elapsedRealtime(),
                inferenceDurationMs = result.inferenceMs.toLong().coerceAtLeast(0L),
                thermalThrottled = latestInferenceThermalThrottled,
                loadObservation = latestUnknownLoadObservation?.takeIf {
                    SystemClock.elapsedRealtime() - it.observedAtElapsedRealtimeMs in 0L..1_000L
                },
            )
            if (isUnknownCaptureContextCurrent(context, attachment.processingLease)) {
                val now = SystemClock.elapsedRealtime()
                val age = now - result.token.capturedElapsedNs / 1_000_000L
                val normal = latestInferenceThermalThrottled == false &&
                    runCatching { !getSystemService(android.os.PowerManager::class.java).isPowerSaveMode }.getOrDefault(false)
                observeUnknownRuntimeLoad(now, normal, auxiliaryCompletion = RuntimeLoadCompletion(
                    age, staleOrDropped = age > MAX_DEPTH_DETECTION_SOURCE_AGE_MS,
                ))
            }
            if (context.activeTicket === attachment.ticket) context.activeTicket = null
        }
    }

    private fun handleUnknownFrameDiscard(token: FastSamFrameToken, reason: String) {
        if (token.source != FastSamFrameToken.Source.LIVE_CAMERA) return
        val now = SystemClock.elapsedRealtime()
        val context = synchronized(frameStateLock) {
            val active = unknownProcessingContext ?: return
            val ticket = active.activeTicket ?: return
            if (active.service.sessionEpoch != token.sessionEpoch || active.activeFrameId != token.frameId ||
                ticket.startedAtElapsedRealtimeMs != token.capturedElapsedNs / 1_000_000L
            ) return
            if (reason.startsWith("stale")) {
                active.pacing.complete(ticket, now, thermalThrottled = latestInferenceThermalThrottled,
                    loadObservation = latestUnknownLoadObservation?.takeIf {
                        now - it.observedAtElapsedRealtimeMs in 0L..1_000L
                    })
            } else active.pacing.cancel(ticket)
            if (active.activeTicket === ticket) active.activeTicket = null
            active
        }
        if (reason.startsWith("stale") && isUnknownContextCurrent(context)) {
            unknownRuntimeStatus = "추가 물체 입력 지연 · 다음 촬영 프레임으로 재시도"
            observeUnknownRuntimeLoad(now,
                normal = latestInferenceThermalThrottled == false &&
                    runCatching { !getSystemService(android.os.PowerManager::class.java).isPowerSaveMode }.getOrDefault(false),
                auxiliaryCompletion = RuntimeLoadCompletion(
                    now - token.capturedElapsedNs / 1_000_000L, staleOrDropped = true))
        }
    }

    private fun isUnknownContextCurrent(context: UnknownProcessingContext): Boolean =
        unknownProcessingContext === context && unknownRuntimeService === context.service &&
            isActivityForeground && !detectorClosing &&
            isCurrentFrameGeneration(context.detectorGeneration, context.walkEpoch) &&
            arSessionGeneration == context.arSessionGeneration &&
            currentRuntimeMetricOutputAllowsWork(context.arSessionGeneration)

    private fun isUnknownCaptureContextCurrent(
        context: UnknownProcessingContext,
        capture: UnknownCaptureProcessingLease,
    ): Boolean = unknownProcessingContext === context && unknownRuntimeService === context.service &&
        isActivityForeground && !detectorClosing &&
        isCurrentFrameGeneration(context.detectorGeneration, context.walkEpoch) &&
        context.arSessionGeneration == capture.arLease.generation &&
        currentUnknownCaptureProcessingAllowsWork(capture)

    private fun freshUnknownFeedbackBatches(nowMs: Long): List<UnknownObjectFeedbackBatch> {
        val observation = latestUnknownFeedback ?: return emptyList()
        if (!isUnknownContextCurrent(observation.context)) return emptyList()
        val epoch = walkSessionLifecycle.currentRuntimeEpochOrNull()
        return observation.batches.filter { it.sourceEpoch == epoch && it.isFreshAt(nowMs) }
    }

    private fun invalidateUnknownObjectObservations() {
        val invalidatedContext = unknownProcessingContext
        unknownProcessingContext = null
        latestUnknownFeedback = null
        invalidatedContext?.let { context ->
            val trackPrefix = "unknown:${context.identity}:"
            feedbackPolicy.cancelFeedbackForTrackPrefix(trackPrefix)
            // A producer restart invalidates its accepted output, while a reused depth frame
            // merely retains old evidence until its original deadline.
            runOnUiThread {
                if (pendingFeedbackTerminalResolution?.action?.trackId?.startsWith(trackPrefix) == true) {
                    cancelPendingFeedbackTerminalResolution()
                }
            }
        }
        unknownRuntimeService?.discardPending("runtime_evidence_invalidated")
    }

    /** Loads unified first and records an explicit legacy fallback reason for report provenance. */
    private fun loadDetectorAfterCameraGate() {
        if (!firstRunOnboardingComplete()) return
        loadDetectorForCurrentProcess()
        prepareRuntimeServices()
    }

    /** Loading execution services must not depend on opening a performance-check camera. */
    private fun prepareRuntimeServices() {
        if (runtimeServicesPreparing || isDestroyed || detectorClosing || !detectorAvailable) return
        val config = reportRuntimeConfig ?: return
        val baseline = frameDetector as? TfliteAndroidFrameDetector ?: return
        if (configuredRuntimeWarmupAttempted || config.unifiedWalksafe?.runtime?.delegate != "gpu") {
            startUnknownRuntimeForWalk()
            return
        }
        configuredRuntimeWarmupAttempted = true
        runtimeServicesPreparing = true
        val loadGeneration = detectorLoadGeneration
        deviceTuningExecutor.execute {
            var replacement: TfliteAndroidFrameDetector? = null
            try {
                val loaded = TfliteAndroidFrameDetector.createWithStatus(applicationContext, config)
                replacement = requireNotNull(loaded.detector) { loaded.reason }
                val fixtures = RuntimeCalibrationFixtures(applicationContext)
                val fixture = fixtures.loadManifest().fixtures.first { it.required }
                val result = replacement.detectCalibrationImage(fixtures.loadArgb(fixture))
                val ready = replacement
                val runtime = requireNotNull(result.timing.modelRuntime)
                detectorExecutor.execute {
                    val adopted = synchronized(frameStateLock) {
                        if (isDestroyed || detectorClosing || detectorLoadGeneration != loadGeneration || frameDetector !== baseline) false
                        else {
                            frameDetector = ready
                            detectorLoadGeneration++
                            runtimeActiveCandidate = RuntimeCandidate(
                                if (runtime.activeDelegate == "gpu") RuntimeBackend.GPU else RuntimeBackend.CPU,
                                runtime.numThreads)
                            true
                        }
                    }
                    if (adopted) baseline.close() else ready.close()
                    runOnUiThread {
                        runtimeServicesPreparing = false
                        if (adopted) {
                            detectorStatusText = "객체 모델 · ${runtime.activeDelegate} · RGB bilinear"
                            startUnknownRuntimeForWalk()
                        }
                    }
                }
                replacement = null // The detector executor now owns adoption or release.
            } catch (error: Exception) {
                replacement?.close()
                runOnUiThread {
                    runtimeServicesPreparing = false
                    if (!isDestroyed && !detectorClosing) {
                        detectorStatusText = "객체 모델 · CPU 유지 · GPU 준비 ${error.javaClass.simpleName}"
                        startUnknownRuntimeForWalk()
                    }
                }
            }
        }
    }

    private fun startUnknownRuntimeForWalk() {
        if (isDestroyed || detectorClosing || !isActivityForeground || !detectorAvailable ||
            unknownRuntimeService != null || unknownLoadingService != null || unknownRuntimeClosing) return
        val config = reportRuntimeConfig ?: return
        val candidate = runtimeActiveCandidate ?: return
        val scope = if (postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE))
            RuntimeFeatureScope.CAMERA_TRACKING_METRIC_DEPTH else RuntimeFeatureScope.CAMERA_TRACKING
        val binding = AndroidUnknownRuntimeProfileStore.createBinding(applicationContext, config, candidate, scope)
        val selected = binding?.let { unknownTuningStore.load(it) }?.candidate
        val epoch = unknownServiceSequence.incrementAndGet()
        val service = FastSamRuntimeService(applicationContext, epoch,
            FastSamRuntimeOptions(
                if (selected?.backend == RuntimeBackend.CPU) FastSamRuntimeOptions.Backend.CPU else FastSamRuntimeOptions.Backend.GPU,
                (selected?.numThreads ?: candidate.numThreads).coerceIn(1, Runtime.getRuntime().availableProcessors().coerceAtLeast(1)),
                true, SystemClock.elapsedRealtimeNanos() + 60_000_000_000L,
                MAX_DEPTH_DETECTION_SOURCE_AGE_MS, false, false, true),
            object : FastSamRuntimeService.Listener<UnknownRuntimeAttachment> {
                override fun onResult(result: FastSamResult<UnknownRuntimeAttachment>) = consumeUnknownObjectResult(result)
                override fun onDiscard(token: FastSamFrameToken, reason: String) = handleUnknownFrameDiscard(token, reason)
                override fun onError(error: Throwable) { runOnUiThread {
                    if (!isDestroyed && !detectorClosing) handleUnknownRuntimeError(epoch, error)
                } }
            })
        unknownLoadingService = service
        unknownRuntimeStatus = "이름 없는 물체 인식 준비 중"
        service.start().whenComplete { info, error -> runOnUiThread {
            if (unknownLoadingService !== service) return@runOnUiThread
            if (error == null && info != null && !isDestroyed && !detectorClosing) {
                unknownRuntimeService = service
                unknownLoadingService = null
                unknownRuntimeBinding = binding
                unknownLoadControl.reset()
                unknownRuntimeStatus = "이름 없는 물체 인식 · ${info.actualBackend}"
            } else {
                releaseUnknownLoadingService(service)
                unknownRuntimeStatus = "이름 없는 물체 준비 실패: ${error?.javaClass?.simpleName ?: "closed"}"
            }
        } }
    }

    private fun loadDetectorForPostLoginDeviceCheck() {
        if (postLoginDeviceCheckSnapshot.state != PostLoginDeviceCheckState.RUNNING) return
        loadDetectorForCurrentProcess()
    }

    private fun loadDetectorForCurrentProcess() {
        if (detectorLoadAttempted) return
        val metricDistanceWasEnabled = postLoginDeviceFeatureEnabled(
            PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE,
        )
        detectorLoadAttempted = true
        val runtimeConfig = reportRuntimeConfig ?: loadReportRuntimeConfig().also { reportRuntimeConfig = it }
        val gpuRuntime = runtimeConfig?.unifiedWalksafe?.runtime?.takeIf {
            runtimeConfig.primaryModelKey == TwoModelRuntimeConfig.UNIFIED_MODEL_KEY &&
                it.delegate.equals("gpu", ignoreCase = true) && it.fallbackToCpu
        }
        // Keep the synchronous readiness contract while native GPU kernels prepare off the UI thread.
        val bootstrapRuntime = gpuRuntime?.copy(
            delegate = "cpu",
            numThreads = gpuRuntime.numThreads.coerceAtMost(Runtime.getRuntime().availableProcessors().coerceAtLeast(1)),
        )
        val bootstrapConfig = runtimeConfig?.let { original ->
            if (bootstrapRuntime == null) original else original.copy(
                unifiedWalksafe = original.unifiedWalksafe?.copy(runtime = bootstrapRuntime),
            )
        }
        val detectorLoad = bootstrapConfig
            ?.let { TfliteAndroidFrameDetector.createWithStatus(
                applicationContext, it,
                preprocessingStrategy = YuvPreprocessingStrategy.FUSED_YUV_TO_TENSOR,
            ) }
            ?: TfliteAndroidFrameDetector.createWithStatus(
                applicationContext, preprocessingStrategy = YuvPreprocessingStrategy.FUSED_YUV_TO_TENSOR,
            )
        detectorConfigLoaded = detectorLoad.configLoaded
        detectorAvailable = detectorLoad.detectorAvailable
        detectorLoadedModelKey = detectorLoad.modelKey
        detectorModelFallbackUsed = detectorLoad.fallbackUsed
        detectorLoadReason = detectorLoad.reason
        detectorModelKeyForReports = detectorLoad.modelKey?.toReportModelKey()
        detectorStatusText = "detector=${detectorLoad.reason} model=${detectorLoad.modelKey ?: "-"} fallback=${detectorLoad.fallbackUsed}"
        detectorLoad.detector?.let { detector -> frameDetector = detector }
        val initialRuntime = bootstrapConfig?.unifiedWalksafe?.runtime
        runtimeActiveCandidate = initialRuntime?.takeIf {
            detectorLoad.modelKey == TwoModelRuntimeConfig.UNIFIED_MODEL_KEY && !detectorLoad.fallbackUsed
        }?.let { RuntimeCandidate(
            if (it.delegate.equals("gpu", true)) RuntimeBackend.GPU else RuntimeBackend.CPU, it.numThreads,
        ) }
        if (
            postLoginDeviceCheckSnapshot.passesFeatureGate &&
            !detectorAvailable
        ) {
            runtimeObstacleDetectionCapabilityOverride = false
            if (metricDistanceWasEnabled) {
                metricDistanceCapabilityOverride = false
            }
        }
    }

    /**
     * Measures the installed model with the versioned in-app calibration images only. This is a
     * device load check, not an ARCore or camera check, so users do not need to aim the phone.
     */
    private fun runFixedFixturePerformanceCheck() {
        if (fixedFixturePerformanceCheckRunning) return
        val detector = frameDetector as? TfliteAndroidFrameDetector
        if (detector == null || !detectorAvailable) {
            loadDetectorForCurrentProcess()
            updateStatus("고정 자료 성능 확인 대기", "객체 인식 모델을 준비한 뒤 다시 눌러 주세요.")
            return
        }
        val generation = detectorLoadGeneration
        fixedFixturePerformanceCheckRunning = true
        updateStatus("고정 자료 성능 확인 중", "카메라를 사용하지 않고 내장 768×768 자료 4종을 반복 실행합니다.")
        detectorExecutor.execute {
            val result = runCatching {
                val fixtures = RuntimeCalibrationFixtures(applicationContext)
                val required = fixtures.loadManifest().fixtures.filter { it.required }
                check(required.isNotEmpty())
                // Warm-up is deliberately excluded. Each measured item is a real production
                // detector call on an immutable app asset, with no camera frame involved.
                detector.detectCalibrationImage(fixtures.loadArgb(required.first()))
                val totalMs = mutableListOf<Long>()
                val inferenceMs = mutableListOf<Long>()
                val detectedObjects = mutableListOf<Int>()
                repeat(3) {
                    required.forEach { fixture ->
                        val detection = detector.detectCalibrationImage(fixtures.loadArgb(fixture))
                        totalMs += requireNotNull(detection.timing.totalMs)
                        inferenceMs += requireNotNull(detection.timing.modelInferenceMs)
                        detectedObjects += detection.detections.size
                    }
                }
                FixedFixturePerformanceResult(
                    fixtureCount = required.size,
                    samples = totalMs.size,
                    medianTotalMs = totalMs.sorted()[totalMs.size / 2],
                    medianInferenceMs = inferenceMs.sorted()[inferenceMs.size / 2],
                    activeDelegate = detector.detectCalibrationImage(
                        fixtures.loadArgb(required.first()),
                    ).timing.modelRuntime?.activeDelegate ?: "unknown",
                    totalDetectedObjects = detectedObjects.sum(),
                )
            }
            runOnUiThread {
                fixedFixturePerformanceCheckRunning = false
                if (generation != detectorLoadGeneration || frameDetector !== detector) return@runOnUiThread
                result.onSuccess { value ->
                    updateStatus(
                        "고정 자료 성능 확인 완료",
                        "카메라 미사용 · 자료 ${value.fixtureCount}종 · 측정 ${value.samples}회 · " +
                            "중앙 전체 ${value.medianTotalMs}ms · 추론 ${value.medianInferenceMs}ms · " +
                            "실행 ${value.activeDelegate} · 객체 출력 ${value.totalDetectedObjects}건",
                    )
                }.onFailure {
                    updateStatus("고정 자료 성능 확인 실패", "내장 시험 자료 또는 객체 인식 모델 실행을 완료하지 못했습니다.")
                }
            }
        }
    }

    private data class FixedFixturePerformanceResult(
        val fixtureCount: Int,
        val samples: Int,
        val medianTotalMs: Long,
        val medianInferenceMs: Long,
        val activeDelegate: String,
        val totalDetectedObjects: Int,
    )

    private fun openLiveCameraScreen() {
        if (!shouldShowNativeHome() || !isActivityForeground) return
        cancelDeviceRuntimeCalibration("live_camera_requested")
        if (BuildConfig.DEBUG) startActivity(Intent().setClassName(
            this, "$packageName.CameraTestActivity"))
    }

    private fun closeLiveCameraScreen() {
        cameraScreenVisible = false
        val stopOwnedWalk = cameraScreenOwnsWalk
        cameraScreenOwnsWalk = false
        if (stopOwnedWalk) {
            if (walkSessionLifecycle.snapshot().state == WalkSessionState.READY) {
                transitionWalkSession(WalkSessionEvent.EndRequested)
            }
            cancelNativeGuidanceAndReturnHome()
            developmentGuidanceStartRequested = false
        }
        updateLiveCameraScreenVisibility()
        renderMainUi()
    }

    private fun updateLiveCameraScreenVisibility() {
        if (!::cameraScreenControls.isInitialized || !::controlsScroll.isInitialized) return
        if (!shouldShowNativeHome()) cameraScreenVisible = false
        controlsScroll.visibility = if (cameraScreenVisible) View.GONE else View.VISIBLE
        cameraScreenControls.visibility = if (cameraScreenVisible) View.VISIBLE else View.GONE
        debugBboxOverlay.visibility = if (cameraScreenVisible) View.VISIBLE else View.GONE
    }

    private fun deviceRuntimeCalibrationContextAvailable(): Boolean =
        isActivityForeground && !isFinishing && !isDestroyed && !detectorClosing &&
            postLoginDeviceCheckSnapshot.passesFeatureGate &&
            postLoginDeviceCheckSnapshot.bindingOrNull == currentPostLoginDeviceCheckSessionBinding() &&
            currentPostLoginDeviceCheckSessionBinding() != null && hasCameraPermission() &&
            nativeUiPage in setOf(NativeUiPage.HOME, NativeUiPage.SETTINGS) &&
            nativePrewalkStartEpoch == null && !priorityUserEducationInFlight &&
            !permissionRecoveryGate.blocksAutomaticResourceStart &&
            (!::walkSessionLifecycle.isInitialized || walkSessionLifecycle.snapshot().state !in setOf(
                WalkSessionState.ACTIVE, WalkSessionState.PAUSED, WalkSessionState.SAFE_STOP,
            ))

    private fun calibrationCameraOwnerAvailable(): Boolean =
        session == null && arSessionPurpose == ArSessionPurpose.NONE &&
            !cameraFallbackRequested && !cameraFallbackRunning && !cameraFallbackCleanupPending &&
            cameraFallbackCamera == null && !runtimeCameraStartBlockedByAnotherOwner() &&
            metricPreflightOwner == RuntimeMetricPreflightOwner.NONE

    /** Wait only for owners already draining. This never polls or benchmarks during a walk. */
    private fun scheduleDeviceRuntimeCalibration(
        manual: Boolean = false,
        requestDeadlineMs: Long = SystemClock.elapsedRealtime() + 300_000L,
    ) {
        runtimeTuningSchedule?.let(cameraReleaseHandler::removeCallbacks)
        runtimeTuningSchedule = null
        // User-facing performance checks use fixed assets. Do not seize the camera on home entry.
        if (manual && SystemClock.elapsedRealtime() < requestDeadlineMs) runFixedFixturePerformanceCheck()
    }

    private fun cancelDeviceRuntimeCalibration(reason: String) {
        runtimeTuningSchedule?.let(cameraReleaseHandler::removeCallbacks)
        runtimeTuningSchedule = null
        runtimeTuningGeneration += 1L
        runtimeCalibration?.cancel(reason)
        unknownCalibration?.cancel(reason)
        unknownLoadingService?.let(::releaseUnknownLoadingService)
    }

    private fun prepareDeviceRuntimeCalibration(manual: Boolean, requestDeadlineMs: Long) {
        if (!deviceRuntimeCalibrationContextAvailable() || !calibrationCameraOwnerAvailable()) return
        loadDetectorForCurrentProcess()
        val baseline = frameDetector as? TfliteAndroidFrameDetector ?: return
        val config = reportRuntimeConfig ?: return
        val candidate = runtimeActiveCandidate ?: return
        if (detectorLoadedModelKey != TwoModelRuntimeConfig.UNIFIED_MODEL_KEY || detectorModelFallbackUsed) return
        val scope = if (postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE))
            RuntimeFeatureScope.CAMERA_TRACKING_METRIC_DEPTH else RuntimeFeatureScope.CAMERA_TRACKING
        val accountBinding = currentPostLoginDeviceCheckSessionBinding() ?: return
        val firstRunLease = currentFirstRunAsyncLease()
        val page = nativeUiPage
        val deviceCheck = postLoginDeviceCheckSnapshot
        val generation = ++runtimeTuningGeneration
        runtimeTuningPreparing = true
        val deadlineMs = requestDeadlineMs
        val flowCurrent = {
            generation == runtimeTuningGeneration && !detectorClosing &&
                deviceRuntimeCalibrationContextAvailable() &&
                accountBinding == currentPostLoginDeviceCheckSessionBinding() &&
                firstRunLease == currentFirstRunAsyncLease() && page == nativeUiPage &&
                deviceCheck == postLoginDeviceCheckSnapshot
        }
        val current = { flowCurrent() && frameDetector === baseline && SystemClock.elapsedRealtime() < deadlineMs }
        deviceTuningExecutor.execute {
            val binding = AndroidDeviceTuningProfileStore.createBinding(applicationContext, config, scope)
            val profile = binding?.let(deviceTuningStore::load)
            val attempt = binding?.let(deviceTuningStore::loadAttempt)
            var recheck = binding != null && deviceTuningStore.needsRecheck(binding, manual)
            if (binding == null || !current()) {
                runOnUiThread { runtimeTuningPreparing = false }
                return@execute
            }
            runtimeSelectionBinding = binding
            // The stored preference is not active until this executor-serialized swap succeeds.
            if (!manual && unknownRuntimeService == null && profile != null && runtimeRestoreAttemptedBinding != binding && profile.candidate != candidate) {
                runtimeRestoreAttemptedBinding = binding
                val unified = requireNotNull(config.unifiedWalksafe)
                val selectedConfig = config.copy(
                    unifiedWalksafe = unified.copy(runtime = unified.runtime.copy(
                        delegate = profile.candidate.backend.delegate, numThreads = profile.candidate.numThreads,
                        fallbackToCpu = false,
                    )), fallbackModelKey = null, customTactile = null, cocoGeneral = null,
                )
                val load = runCatching { TfliteAndroidFrameDetector.createWithStatus(
                    applicationContext, selectedConfig, preprocessingStrategy = YuvPreprocessingStrategy.FUSED_YUV_TO_TENSOR,
                ) }.getOrNull()
                val replacement = load?.detector
                if (replacement != null && !load.fallbackUsed && load.modelKey == TwoModelRuntimeConfig.UNIFIED_MODEL_KEY && current()) {
                    try {
                        detectorExecutor.execute {
                            val swapped = synchronized(frameStateLock) {
                                if (!current()) false else {
                                    frameDetector = replacement
                                    detectorLoadGeneration += 1L
                                    runtimeActiveCandidate = profile.candidate
                                    runtimeActiveProfile = profile
                                    adaptiveInferencePacing.reset()
                                    runtimeLoadMonitor.reset()
                                    runtimeLoadPendingRecordedBinding = null
                                    detectorStatusText = "detector=measured_profile runtime=${profile.candidate.backend} threads=${profile.candidate.numThreads}"
                                    true
                                }
                            }
                            if (swapped) {
                                closePreviousRuntimeDetector(baseline) {
                                    runtimeTuningPreparing = false
                                    scheduleDeviceRuntimeCalibration(requestDeadlineMs = deadlineMs)
                                }
                            } else {
                                runtimeRestoreAttemptedBinding = null
                                closePreviousRuntimeDetector(replacement) { runtimeTuningPreparing = false }
                            }
                        }
                    } catch (_: RejectedExecutionException) {
                        replacement.close()
                        runOnUiThread { runtimeTuningPreparing = false }
                    }
                    return@execute
                }
                replacement?.close()
                if (!current()) {
                    runtimeRestoreAttemptedBinding = null
                    runOnUiThread { runtimeTuningPreparing = false }
                    return@execute
                }
                deviceTuningStore.markAttemptStarted(binding, DeviceTuningRecheckReason.EXECUTION_RECOVERY)
                recheck = true
            } else if (profile?.candidate == candidate) {
                runtimeActiveProfile = profile
            }
            // Recheck the primary when required, then compare the supplementary workload.
            // Both stages retain the original request deadline and never share a candidate slot.
            if (!recheck) {
                prepareUnknownCompositionCalibration(config, baseline, candidate, scope, manual, deadlineMs, current)
                return@execute
            }
            if (unknownLoadingService != null || unknownRuntimeClosing) {
                runOnUiThread { runtimeTuningPreparing = false }
                return@execute
            }
            val auxiliaryToClose = unknownRuntimeService
            unknownRuntimeClosing = auxiliaryToClose != null
            unknownRuntimeService = null
            invalidateUnknownObjectObservations()
            if (auxiliaryToClose != null) {
                auxiliaryToClose.closeAsync()
                try { auxiliaryToClose.releasedFuture().get() } catch (_: Exception) {
                    unknownRuntimeStatus = "추가 물체 인식 정리 확인 필요"
                    runOnUiThread { runtimeTuningPreparing = false }
                    return@execute
                }
            }
            unknownRuntimeClosing = false
            if (!current() || !deviceTuningStore.markAttemptStarted(binding, cursor = attempt?.cursor)) {
                runOnUiThread { runtimeTuningPreparing = false }
                return@execute
            }
            runOnUiThread {
                runtimeTuningPreparing = false
                if (!current() || !calibrationCameraOwnerAvailable()) return@runOnUiThread
                cancelForegroundHomeWakeListening()
                var ownedSession: AndroidRuntimeCalibrationSession? = null
                // Leave preparation time for the second model (76 s GPU cold load on the S20).
                // Unfinished primary comparisons keep their cursor for the next device check.
                val primaryBudgetMs = ((deadlineMs - SystemClock.elapsedRealtime()) / 3L)
                    .coerceIn(1L, 100_000L)
                val controller = AndroidRuntimeCalibrationSession(
                    activity = this, featureScope = scope, bindingHash = binding,
                    budgetMs = primaryBudgetMs,
                    speechActive = { voiceRecognitionActive || feedbackActuator?.isAppSpeechActive() == true },
                    runnerFactory = { environmentProvider, progress, finished, liveDetection ->
                        AndroidRuntimeCalibrationRunner(
                            context = applicationContext, config = config, baselineDetector = baseline,
                            baselineExecutor = detectorExecutor, baselineCandidate = candidate,
                            bindingHash = binding, featureScope = scope,
                            preprocessingStrategy = YuvPreprocessingStrategy.FUSED_YUV_TO_TENSOR,
                            environmentProvider = environmentProvider,
                            isCurrent = { current() && runtimeCalibration === ownedSession },
                            callbackExecutor = java.util.concurrent.Executor { runOnUiThread(it) },
                            onProgress = progress, onFinished = finished, onLiveDetection = liveDetection,
                            speechActive = { voiceRecognitionActive || feedbackActuator?.isAppSpeechActive() == true },
                            baselinePreviouslyConfirmed = profile?.candidate == candidate,
                            restoredQueue = attempt?.cursor,
                            budgetMs = primaryBudgetMs,
                            onSelectionReady = { selection ->
                                adoptDeviceRuntimeSelection(selection, baseline, current)
                            },
                        )
                    },
                    onClosed = { result ->
                        val finishOwner: () -> Unit = {
                        if (runtimeCalibration === ownedSession) runtimeCalibration = null
                        deviceTuningExecutor.execute {
                            val pending = when {
                                result?.adopted == true -> null
                                result?.status == RuntimeSelectionStatus.INCONCLUSIVE -> DeviceTuningRecheckReason.INCONCLUSIVE
                                else -> DeviceTuningRecheckReason.INCOMPLETE_COMPARISON
                            }
                            deviceTuningStore.markAttemptFinished(binding, pending,
                                if (pending == null) null else result?.queueSnapshot)
                        }
                        if (detectorCloseAfterCalibration) {
                            detectorCloseAfterCalibration = false
                            closeDetectorAsync()
                        } else if (flowCurrent()) {
                            // Rebind after adoption: the previous primary identity is now obsolete.
                            val selectedPrimary = frameDetector as? TfliteAndroidFrameDetector
                            val selectedCandidate = runtimeActiveCandidate
                            if (selectedPrimary != null && selectedCandidate != null &&
                                SystemClock.elapsedRealtime() < deadlineMs) {
                                runtimeTuningPreparing = true
                                deviceTuningExecutor.execute {
                                    val nextCurrent = { flowCurrent() && frameDetector === selectedPrimary &&
                                        SystemClock.elapsedRealtime() < deadlineMs }
                                    prepareUnknownCompositionCalibration(config, selectedPrimary,
                                        selectedCandidate, scope, manual, deadlineMs, nextCurrent)
                                }
                            } else {
                                refreshStartupCapabilityUi()
                                speakInteraction("성능 확인 시간이 끝났습니다. 확인된 설정을 유지합니다.")
                            }
                        }
                        }
                        if (runtimeOldDetectorReleasePending) runtimeAfterOldDetectorRelease = finishOwner
                        else finishOwner()
                    },
                )
                ownedSession = controller
                runtimeCalibration = controller
                controller.start()
            }
        }
    }

    /** Called on the tuning worker; all cold loads and comparisons share the original deadline. */
    private fun prepareUnknownCompositionCalibration(
        config: TwoModelRuntimeConfig,
        primary: TfliteAndroidFrameDetector,
        primaryCandidate: RuntimeCandidate,
        scope: RuntimeFeatureScope,
        manual: Boolean,
        deadlineMs: Long,
        current: () -> Boolean,
    ) {
        if (unknownLoadingService != null || unknownRuntimeClosing) {
            runOnUiThread { runtimeTuningPreparing = false }
            return
        }
        val binding = AndroidUnknownRuntimeProfileStore.createBinding(applicationContext, config, primaryCandidate, scope)
        if (binding == null || !current()) {
            runOnUiThread { runtimeTuningPreparing = false }
            return
        }
        val profile = unknownTuningStore.load(binding)
        val recheck = unknownTuningStore.needsRecheck(binding, manual)
        val existing = unknownRuntimeService
        if (!recheck && existing != null && unknownRuntimeBinding == binding && !existing.stats().stopping) {
            runOnUiThread { runtimeTuningPreparing = false }
            return
        }
        // Native release is awaited off the UI and before allocating the next auxiliary owner.
        unknownRuntimeClosing = existing != null
        unknownRuntimeService = null
        invalidateUnknownObjectObservations()
        if (existing != null) {
            existing.closeAsync()
            try { existing.releasedFuture().get() } catch (_: Exception) {
                unknownRuntimeStatus = "추가 물체 인식 정리 확인 필요"
                runOnUiThread { runtimeTuningPreparing = false }
                return
            }
        }
        unknownRuntimeClosing = false
        if (!current()) {
            runOnUiThread { runtimeTuningPreparing = false }
            return
        }
        val serviceEpoch = unknownServiceSequence.incrementAndGet()
        if (!recheck) {
            val selected = profile?.candidate ?: RuntimeCandidate(RuntimeBackend.GPU, primaryCandidate.numThreads)
            lateinit var restored: FastSamRuntimeService<UnknownRuntimeAttachment>
            restored = FastSamRuntimeService(applicationContext, serviceEpoch,
                FastSamRuntimeOptions(FastSamRuntimeOptions.Backend.valueOf(selected.backend.name), selected.numThreads,
                    profile == null, deadlineMs * 1_000_000L, MAX_DEPTH_DETECTION_SOURCE_AGE_MS, false, false, true),
                object : FastSamRuntimeService.Listener<UnknownRuntimeAttachment> {
                    override fun onResult(result: FastSamResult<UnknownRuntimeAttachment>) = consumeUnknownObjectResult(result)
                    override fun onDiscard(token: FastSamFrameToken, reason: String) = handleUnknownFrameDiscard(token, reason)
                    override fun onError(error: Throwable) { handleUnknownRuntimeError(serviceEpoch, error) }
                })
            unknownLoadingService = restored
            if (!current()) {
                releaseUnknownLoadingService(restored)
                runOnUiThread { runtimeTuningPreparing = false }
                return
            }
            restored.start().whenComplete { info, error ->
                runOnUiThread {
                    runtimeTuningPreparing = false
                    if (error == null && info != null && current() && unknownLoadingService === restored && !unknownRuntimeClosing) {
                        unknownRuntimeService = restored
                        unknownLoadingService = null
                        unknownRuntimeBinding = binding
                        unknownLoadControl.reset()
                        unknownLoadRecheckRecorded = false
                        unknownRuntimeStatus = if (profile != null && !info.fallbackUsed)
                            "추가 물체 인식 · 저장된 ${info.actualBackend} 설정" else "추가 물체 인식 · ${info.actualBackend} 임시 설정"
                    } else {
                        if (error != null && current() && unknownLoadingService === restored && !unknownRuntimeClosing) {
                            deviceTuningExecutor.execute {
                                unknownTuningStore.markPending(binding, DeviceTuningRecheckReason.EXECUTION_RECOVERY)
                            }
                        }
                        releaseUnknownLoadingService(restored)
                        unknownRuntimeStatus = "추가 물체 인식 준비 미완료"
                    }
                }
            }
            return
        }
        runOnUiThread {
            runtimeTuningPreparing = false
            if (!current() || !calibrationCameraOwnerAvailable()) return@runOnUiThread
            cancelForegroundHomeWakeListening()
            val calibrationDepth = UnknownObjectDepthPipeline(
                maximumSourceAgeMs = MAX_DEPTH_DETECTION_SOURCE_AGE_MS, elapsedRealtimeMs = SystemClock::elapsedRealtime,
            )
            lateinit var calibration: UnknownRuntimeCalibration
            calibration = UnknownRuntimeCalibration(
                activity = this, binding = binding, primaryDetector = primary, primaryExecutor = detectorExecutor,
                sessionEpoch = serviceEpoch, requestDeadlineMs = deadlineMs,
                isCurrent = { current() && unknownCalibration === calibration },
                speechActive = { voiceRecognitionActive || feedbackActuator?.isAppSpeechActive() == true },
                onSelected = { selection ->
                    selection.tryAdopt {
                        if (!current() || unknownCalibration !== calibration || unknownRuntimeService != null) false else {
                            unknownRuntimeService = selection.readyService
                            unknownRuntimeBinding = binding
                            unknownLoadControl.reset()
                            unknownLoadRecheckRecorded = false
                            unknownRuntimeStatus = if (selection.profile != null) "추가 물체 인식 · 조합 성능 확인됨"
                                else "추가 물체 인식 · ${selection.candidate.backend} 임시 설정, 성능 비교 미확정"
                            true
                        }
                    }
                },
                onClosed = { result ->
                    if (unknownCalibration === calibration) unknownCalibration = null
                    if (detectorCloseAfterCalibration) {
                        detectorCloseAfterCalibration = false
                        closeDetectorAsync()
                    } else if (isActivityForeground && !isDestroyed && !isFinishing) {
                        refreshStartupCapabilityUi()
                        if (result?.adopted == true) speakInteraction("추가 물체 인식 준비를 마쳤습니다.")
                        else unknownRuntimeStatus = "추가 물체 인식 점검 미완료 · 설정에서 다시 확인 가능"
                    }
                },
                onProductionResult = ::consumeUnknownObjectResult,
                onProductionError = { handleUnknownRuntimeError(serviceEpoch, it) },
                onProductionDiscard = ::handleUnknownFrameDiscard,
                onCalibrationResult = { result, evidence ->
                    val snapshot = evidence.depthSnapshot
                    val mapperFrame = evidence.mapperFrameId
                    val capture = if (snapshot != null && mapperFrame != null) FrozenUnknownDepthCapture.freeze(
                        result.token, snapshot, evidence.imageToDepthUv, mapperFrame,
                    ) else null
                    if (capture == null) false else {
                        val outputs = calibrationDepth.process(capture, result.token, result.masks, SystemClock.elapsedRealtime())
                        outputs.rejectionReason == null && snapshot!!.hasFreshMetricRawDepth &&
                            evidence.positiveDepthSamples > 0 && evidence.poseValid
                    }
                },
            )
            unknownCalibration = calibration
            if (!calibration.start()) unknownCalibration = null
        }
    }

    private fun handleUnknownRuntimeError(serviceEpoch: Long, error: Throwable) {
        val failed = unknownRuntimeService?.takeIf { it.sessionEpoch == serviceEpoch } ?: return
        val failedBinding = unknownRuntimeBinding
        if (failedBinding != null) deviceTuningExecutor.execute {
            unknownTuningStore.markPending(failedBinding, DeviceTuningRecheckReason.EXECUTION_RECOVERY)
        }
        unknownRuntimeService = null
        invalidateUnknownObjectObservations()
        unknownRuntimeStatus = "추가 물체 인식 중지 · ${error.javaClass.simpleName}"
        unknownRuntimeClosing = true
        failed.closeAsync()
        failed.releasedFuture().whenComplete { _, releaseError ->
            if (releaseError == null) unknownRuntimeClosing = false
        }
    }

    private fun releaseUnknownLoadingService(service: FastSamRuntimeService<UnknownRuntimeAttachment>) {
        if (unknownLoadingService !== service) return
        unknownRuntimeClosing = true
        service.closeAsync()
        service.releasedFuture().whenComplete { _, error ->
            runOnUiThread {
                if (unknownLoadingService === service && error == null) {
                    unknownLoadingService = null
                    unknownRuntimeClosing = false
                }
            }
        }
    }

    private fun adoptDeviceRuntimeSelection(
        selection: RuntimeCalibrationSelection,
        baseline: TfliteAndroidFrameDetector,
        current: () -> Boolean,
    ) {
        deviceTuningExecutor.execute {
            if (!current() || !deviceTuningStore.save(selection.profile)) {
                selection.reject()
                return@execute
            }
            try {
                detectorExecutor.execute {
                    val adopted = selection.tryAdopt { load ->
                        synchronized(frameStateLock) {
                            if (!current() || load.detector == null) false else {
                                if (!selection.isBaseline) runtimeOldDetectorReleasePending = true
                                frameDetector = load.detector
                                runtimeActiveCandidate = selection.profile.candidate
                                runtimeActiveProfile = selection.profile
                                detectorLoadGeneration += 1L
                                adaptiveInferencePacing.reset()
                                runtimeLoadMonitor.reset()
                                runtimeLoadPendingRecordedBinding = null
                                detectorStatusText = "detector=measured_profile runtime=${selection.profile.candidate.backend} threads=${selection.profile.candidate.numThreads}"
                                true
                            }
                        }
                    }
                    if (adopted && !selection.isBaseline) {
                        closePreviousRuntimeDetector(baseline) {
                            runtimeOldDetectorReleasePending = false
                            val finish = runtimeAfterOldDetectorRelease
                            runtimeAfterOldDetectorRelease = null
                            finish?.invoke()
                        }
                    }
                }
            } catch (_: RejectedExecutionException) { selection.reject() }
        }
    }

    /** A native close failure must never be reported as a released execution slot. */
    private fun closePreviousRuntimeDetector(detector: TfliteAndroidFrameDetector, afterRelease: () -> Unit) {
        try {
            detector.close()
            runOnUiThread(afterRelease)
        } catch (error: RuntimeException) {
            runtimeOldDetectorReleasePending = true
            android.util.Log.e("WalkSafeRuntimeTuning", "Previous detector release failed", error)
            runOnUiThread {
                if (isActivityForeground && !isDestroyed && !isFinishing) {
                    updateStatus("성능 작업 정리 확인 필요", "실행 작업을 닫지 못했습니다. 앱을 다시 시작한 뒤 기기 점검을 진행하세요.")
                }
            }
        }
    }

    private fun handleDetectorRuntimeFailure(
        error: RuntimeException,
        expectedDetectorGeneration: Int,
        expectedWalkEpoch: WalkRuntimeEpoch,
    ) {
        if (!isCurrentFrameGeneration(expectedDetectorGeneration, expectedWalkEpoch)) return
        val runtimeConfig = reportRuntimeConfig
        val legacyAvailable = runtimeConfig?.fallbackModelKey == TwoModelRuntimeConfig.LEGACY_TWO_MODEL_KEY &&
            runtimeConfig.customTactile != null &&
            runtimeConfig.cocoGeneral != null
        when (
            detectorRuntimeSupervisor.onFailure(
                activeModelKey = detectorLoadedModelKey,
                legacyFallbackAvailable = legacyAvailable,
                activeWalk = true,
            )
        ) {
            DetectorRuntimeFailureAction.KEEP_CURRENT -> {
                if (isCurrentFrameGeneration(expectedDetectorGeneration, expectedWalkEpoch)) {
                    detectorStatusText =
                        "detector=runtime_failure_${detectorRuntimeSupervisor.consecutiveFailures} error=${error::class.java.simpleName}"
                } else {
                    detectorRuntimeSupervisor.onSuccess()
                }
            }
            DetectorRuntimeFailureAction.SAFE_STOP -> {
                if (developmentGuidanceStartBypassEnabled) {
                    disableDetectorAfterRuntimeFailure(error, expectedDetectorGeneration, expectedWalkEpoch)
                    return
                }
                val safetyDecision = walkRuntimeSafetyCoordinator.observe(
                    WalkRuntimeSafetyObservation(
                        epoch = expectedWalkEpoch,
                        observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                        riskTrusted = false,
                    ),
                )
                disableDetectorAfterRuntimeFailure(
                    error = error,
                    expectedDetectorGeneration = expectedDetectorGeneration,
                    expectedWalkEpoch = expectedWalkEpoch,
                    safetyStopHandledByCoordinator =
                        !safetyDecision.safetyOutputsAllowed &&
                            safetyDecision.epoch == expectedWalkEpoch,
                )
            }
            DetectorRuntimeFailureAction.LOAD_LEGACY_FOR_NEXT_WALK,
            DetectorRuntimeFailureAction.DISABLE,
            -> {
                disableDetectorAfterRuntimeFailure(
                    error,
                    expectedDetectorGeneration,
                    expectedWalkEpoch,
                )
            }
        }
    }

    private fun disableDetectorAfterRuntimeFailure(
        error: RuntimeException,
        expectedDetectorGeneration: Int,
        expectedWalkEpoch: WalkRuntimeEpoch,
        safetyStopHandledByCoordinator: Boolean = false,
    ) {
        val disabledGeneration = synchronized(frameStateLock) {
            if (
                !isCurrentFrameGeneration(
                    expectedDetectorGeneration,
                    expectedWalkEpoch,
                )
            ) {
                null
            } else {
                (frameDetector as? Closeable)?.close()
                frameDetector = NoopAndroidFrameDetector()
                detectorGeneration += 1
                resetVisualTrackingState()
                adaptiveInferencePacing.reset()
                detectorAvailable = false
                detectorLoadReason = "runtime_failed_unavailable"
                detectorStatusText =
                    "detector=runtime_failed_unavailable error=${error::class.java.simpleName}"
                detectorGeneration
            }
        }
        if (disabledGeneration == null) {
            detectorRuntimeSupervisor.onSuccess()
            return
        }
        clearDetectionStateAfterRuntimeTransition(expectedWalkEpoch)
        runOnUiThread {
            if (
                !isCurrentFrameGeneration(
                    disabledGeneration,
                    expectedWalkEpoch,
                )
            ) {
                return@runOnUiThread
            }
            if (!safetyStopHandledByCoordinator) {
                enterWalkSessionSafetyStopAndCancelOutputs("detector_runtime_failed")
            }
            stopCameraFallbackSession(updateUi = false)
            stopDepthSession(closeSession = true)
            latestReportCandidateStatus = "reportCandidate=blocked:camera_non_metric_unavailable"
            setActionButton("카메라 보조 경고 사용 불가", ActionMode.START, enabled = false)
            updateStatus(
                status = if (developmentGuidanceStartBypassEnabled) "객체 탐지 중지" else "객체 탐지 중지 · 안전 중지",
                detail = if (developmentGuidanceStartBypassEnabled)
                    "객체 탐지를 실행하지 못했습니다. 길안내 테스트는 계속합니다."
                else "detector 실행 오류로 보행 기능을 안전 중지했습니다.",
            )
        }
    }

    private fun clearDetectionStateAfterRuntimeTransition(
        expectedWalkEpoch: WalkRuntimeEpoch,
    ) {
        val expectedDetectorGeneration = synchronized(frameStateLock) {
            if (!walkSessionLifecycle.isRuntimeEpochCurrent(expectedWalkEpoch)) return
            latestDetectionSnapshot = DetectionSnapshot.empty()
            detectorGeneration
        }
        runOnUiThread {
            if (
                isCurrentFrameGeneration(
                    expectedDetectorGeneration,
                    expectedWalkEpoch,
                )
            ) {
                debugBboxOverlay.clear()
            }
        }
    }

    private fun emitTactileFrameFeedback(dispatch: TactileFrameFeedbackDispatch) {
        latestFeedbackDeliveryState = FeedbackDeliveryState(
            activeFeedbackDeliveryKeys = dispatch.activeFeedbackDeliveryKeys,
            deviceGateAllowsAlerts = dispatch.deviceGateAllowsAlerts,
            observedAtMs = dispatch.policyEvaluatedAtMs,
        )
        val feedbackGeneration = feedbackLifecycleGeneration
        val activeRiskTrackIds = dispatch.activeRiskTrackIds
        val feedbackAction = dispatch.action
        val elapsedRealtimeMs = dispatch.policyEvaluatedAtMs
        runOnUiThread {
            if (!isFeedbackLifecycleCurrent(feedbackGeneration)) {
                feedbackAction?.let { action ->
                    feedbackPolicy.rejectUndeliveredFeedback(action.trackId, elapsedRealtimeMs)
                }
                return@runOnUiThread
            }
            reconcileTalkBackRiskTracks(activeRiskTrackIds)
            feedbackAction?.let { emitFeedbackAction(it, elapsedRealtimeMs) }
        }
    }

    /** Avoids duplicate app TTS while TalkBack owns speech, but preserves the risk haptic. */
    private fun emitFeedbackAction(action: FeedbackAction, policyEvaluatedAtMs: Long) {
        val generation = feedbackLifecycleGeneration
        if (Looper.myLooper() != Looper.getMainLooper()) {
            runOnUiThread {
                if (!isFeedbackLifecycleCurrent(generation)) {
                    feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
                    return@runOnUiThread
                }
                emitFeedbackAction(action, policyEvaluatedAtMs)
            }
            return
        }
        if (!isFeedbackLifecycleCurrent(generation)) {
            feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
            return
        }
        if (!isFeedbackActionStillDeliverable(action)) {
            feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
            return
        }
        cancelPendingFeedbackTerminalResolution()
        if (!feedbackPolicy.claimFeedbackDelivery(action.trackId, policyEvaluatedAtMs)) return
        if (!isFeedbackActionStillDeliverable(action)) {
            feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
            return
        }
        val isRisk = action.level != kr.co.hanium.dreamup.walksafe.depth.MessageLevel.INFO
        if (isRisk) cancelGatewaySpeechInteraction("risk_feedback")
        if (isRisk && voiceRecognitionActive) cancelVoiceCommandRecognition()
        if (shouldSuppressFeedbackDuringVoiceRecognition(voiceRecognitionActive, isRisk)) {
            feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
            return
        }
        val actuator = ensureFeedbackActuator()
        if (isRisk) {
            val speechGeneration = generation
            val feedbackStartedAtMs = SystemClock.elapsedRealtime()
            var vibrationAccepted = false
            val dispatch = actuator.emit(
                action = action,
                isStillValidAtStart = {
                    isFeedbackLifecycleCurrent(speechGeneration) && isFeedbackActionStillDeliverable(action)
                },
                onSpeechCompleted = {
                    runOnUiThread {
                        if (isFeedbackLifecycleCurrent(speechGeneration)) {
                            confirmFeedbackDelivery(action, policyEvaluatedAtMs, outputCompleted = true)
                        } else {
                            feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
                        }
                    }
                },
                onSpeechFailed = {
                    runOnUiThread {
                        if (!isFeedbackLifecycleCurrent(speechGeneration)) {
                            feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
                        } else if (vibrationAccepted) {
                            scheduleFeedbackTerminalResolution(
                                action = action,
                                policyEvaluatedAtMs = policyEvaluatedAtMs,
                                generation = speechGeneration,
                                delayMs = (
                                    feedbackStartedAtMs + vibrationDurationMs(action) -
                                        SystemClock.elapsedRealtime()
                                    ).coerceAtLeast(1L),
                            )
                        } else {
                            feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
                        }
                    }
                },
            )
            vibrationAccepted = dispatch.vibrationAccepted
            if (dispatch.speech != NavigationSpeechDispatchResult.ACCEPTED) {
                if (vibrationAccepted) {
                    scheduleFeedbackTerminalResolution(
                        action = action,
                        policyEvaluatedAtMs = policyEvaluatedAtMs,
                        generation = generation,
                        delayMs = vibrationDurationMs(action),
                    )
                } else {
                    feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
                }
            }
        } else {
            val speechGeneration = generation
            val speech = actuator.speakNavigation(
                message = action.message,
                requiresExplicitTerminalCallback = true,
                onCompleted = {
                    runOnUiThread {
                        if (isFeedbackLifecycleCurrent(speechGeneration)) {
                            confirmFeedbackDelivery(action, policyEvaluatedAtMs)
                        } else {
                            feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
                        }
                    }
                },
                onFailed = {
                    feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
                },
            )
            if (speech != NavigationSpeechDispatchResult.ACCEPTED) {
                feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
            }
        }
    }

    private fun isFeedbackActionStillDeliverable(action: FeedbackAction): Boolean {
        val current = latestFeedbackDeliveryState
        val nowMs = SystemClock.elapsedRealtime()
        if (action.trackId.startsWith("unknown:") && freshUnknownFeedbackBatches(nowMs).none { batch ->
                batch.outputs.any { output ->
                    output.trackId == action.trackId && output.userFacing.message == action.message &&
                        output.userFacing.messageLevel == action.level
                }
            }
        ) return false
        return nowMs <= action.validUntilMs &&
            action.deliveryKey in current.activeFeedbackDeliveryKeys &&
            current.deviceGateAllowsAlerts &&
            current.observedAtMs <= nowMs &&
            currentFeedbackDeviceGateAllowsAlerts()
    }

    private fun currentFeedbackDeviceGateAllowsAlerts(): Boolean {
        if (!firstRunOnboardingComplete()) return false
        val decision = startupCapabilityDecision
        val capabilityGate = when {
            decision == null || decision.tier == WalkSafeStartupCapabilityTier.BLOCKED -> false
            decision.allowsMetricDistance() ->
                arSessionPurpose == ArSessionPurpose.RUNTIME &&
                    runtimeMetricOutputAllowed &&
                    currentRuntimeMetricOutputAllowsWork()
            else ->
                metricDistanceCapabilityOverride == false &&
                    cameraFallbackRequested &&
                    cameraFallbackRunning &&
                    isStartupCapabilityConfirmed()
        }
        return isActivityForeground &&
            isWalkSessionRuntimeActive() &&
            cameraEnvironmentOutputsAllowed() &&
            phoneMountingOutputsAllowed &&
            capabilityGate &&
            hasCameraPermission() &&
            detectorConfigLoaded &&
            detectorAvailable &&
            latestFeedbackDeliveryState.deviceGateAllowsAlerts
    }

    private fun vibrationDurationMs(action: FeedbackAction): Long =
        action.vibrationPatternMs?.sum()?.coerceAtLeast(1L) ?: 1L

    private fun scheduleFeedbackTerminalResolution(
        action: FeedbackAction,
        policyEvaluatedAtMs: Long,
        generation: Int,
        delayMs: Long,
    ) {
        cancelPendingFeedbackTerminalResolution()
        if (!::statusText.isInitialized) {
            feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
            return
        }
        lateinit var resolution: Runnable
        resolution = Runnable {
            if (pendingFeedbackTerminalResolution?.runnable !== resolution) return@Runnable
            pendingFeedbackTerminalResolution = null
            if (isFeedbackLifecycleCurrent(generation)) {
                // Only an accepted, uncancelled waveform owns this timer. Its completion can
                // outlive the capture deadline, which was checked before output started.
                confirmFeedbackDelivery(action, policyEvaluatedAtMs, outputCompleted = true)
            } else {
                feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
            }
        }
        pendingFeedbackTerminalResolution = PendingFeedbackTerminalResolution(
            action = action,
            policyEvaluatedAtMs = policyEvaluatedAtMs,
            runnable = resolution,
        )
        statusText.postDelayed(resolution, delayMs.coerceAtLeast(1L))
    }

    private fun cancelPendingFeedbackTerminalResolution() {
        val pending = pendingFeedbackTerminalResolution ?: return
        pendingFeedbackTerminalResolution = null
        if (::statusText.isInitialized) statusText.removeCallbacks(pending.runnable)
        feedbackPolicy.rejectUndeliveredFeedback(
            pending.action.trackId,
            pending.policyEvaluatedAtMs,
        )
    }

    private fun confirmFeedbackDelivery(
        action: FeedbackAction,
        policyEvaluatedAtMs: Long,
        outputCompleted: Boolean = false,
    ) {
        // Capture freshness limits output START, not completion of accepted speech/vibration.
        // Completion still requires the caller's lifecycle fence and the policy's claimed lease.
        val unknownContextCurrent = if (action.trackId.startsWith("unknown:")) {
            unknownProcessingContext?.let { context ->
                action.trackId.startsWith("unknown:${context.identity}:") && isUnknownContextCurrent(context)
            } == true
        } else true
        if (!unknownContextCurrent || (!outputCompleted && !isFeedbackActionStillDeliverable(action))) {
            feedbackPolicy.rejectUndeliveredFeedback(action.trackId, policyEvaluatedAtMs)
            return
        }
        val deliveredAtMs = SystemClock.elapsedRealtime()
        val confirmed = synchronized(phoneMountingObservationLock) {
            if (!phoneMountingOutputsAllowed) {
                feedbackPolicy.rejectUndeliveredFeedback(
                    action.trackId,
                    policyEvaluatedAtMs,
                )
                false
            } else {
                feedbackPolicy.confirmFeedbackDelivery(
                    action.trackId,
                    policyEvaluatedAtMs,
                    deliveredAtMs,
                )
            }
        }
        if (!confirmed) return
        fieldSessionLog.recordEvent(
            if (action.level == kr.co.hanium.dreamup.walksafe.depth.MessageLevel.INFO) {
                "path_guidance_emitted"
            } else {
                "risk_feedback_emitted"
            },
            mapOf("level" to action.level.name, "reason" to action.reason),
        )
    }

    private fun speakNavigation(message: String, onCompleted: (() -> Unit)? = null): Boolean =
        dispatchNavigationSpeech(message, onCompleted = onCompleted)

    private fun dispatchNavigationSpeech(
        message: String,
        onCompleted: (() -> Unit)? = null,
        onFailed: (() -> Unit)? = null,
    ): Boolean {
        val generation = feedbackLifecycleGeneration
        if (Looper.myLooper() != Looper.getMainLooper()) {
            runOnUiThread {
                if (!isFeedbackLifecycleCurrent(generation)) {
                    onFailed?.invoke()
                    return@runOnUiThread
                }
                dispatchNavigationSpeech(message, onCompleted, onFailed)
            }
            return true
        }
        if (!isFeedbackLifecycleCurrent(generation) ||
            !isWalkSessionRuntimeActive() || !navigationEnvironmentOutputsAllowed() ||
            deferredVoiceRecognitionStart != null ||
            shouldSuppressFeedbackDuringVoiceRecognition(voiceRecognitionActive, isRisk = false)
        ) {
            onFailed?.invoke()
            return false
        }
        val mainThreadCompletion = onCompleted?.let { completion ->
            {
                runOnUiThread {
                    if (isFeedbackLifecycleCurrent(generation) &&
                        isWalkSessionRuntimeActive() && navigationEnvironmentOutputsAllowed()
                    ) completion() else onFailed?.invoke()
                }
            }
        }
        val mainThreadFailure = onFailed?.let { failure ->
            { runOnUiThread { failure() } }
        }
        val accepted = ensureFeedbackActuator().speakNavigation(
            message = message,
            onCompleted = mainThreadCompletion,
            onFailed = mainThreadFailure,
            requiresExplicitTerminalCallback = onCompleted != null || onFailed != null,
        ) == NavigationSpeechDispatchResult.ACCEPTED
        if (!accepted) onFailed?.invoke()
        return accepted
    }

    private fun showWalkLastResult(message: String) {
        if (!::walkLastResultText.isInitialized) return
        val line = "마지막 안내: $message"
        walkLastResultText.visibility = View.VISIBLE
        if (walkLastResultText.text.toString() != line) {
            walkLastResultText.text = line
            walkLastResultText.contentDescription = line
        }
    }

    private fun speakInteraction(message: String): Boolean = speakCommandResponse(message)

    private fun speakStatusExplanation(message: String): Boolean =
        speakCommandResponse(message, statusExplanation = true)

    private fun speakCommandResponse(
        message: String,
        preparingInput: Boolean = false,
        onCompleted: (() -> Unit)? = null,
        onFailed: (() -> Unit)? = null,
        statusExplanation: Boolean = false,
    ): Boolean {
        val lifecycleGeneration = feedbackLifecycleGeneration
        if (Looper.myLooper() != Looper.getMainLooper()) {
            runOnUiThread {
                if (!isFeedbackLifecycleCurrent(lifecycleGeneration)) {
                    onFailed?.invoke()
                    return@runOnUiThread
                }
                speakCommandResponse(message, preparingInput, onCompleted, onFailed, statusExplanation)
            }
            return true
        }
        if (!isFeedbackLifecycleCurrent(lifecycleGeneration)) {
            onFailed?.invoke()
            return false
        }
        showWalkLastResult(message)
        val responsePage = nativeUiPage
        val visibleResponse = ::gatewayVoiceStatusText.isInitialized &&
            responsePage in setOf(
                NativeUiPage.DESTINATION_SEARCH,
                NativeUiPage.DESTINATION_CONFIRM,
                NativeUiPage.VOICE_COMMAND,
            )
        if (visibleResponse) updateGatewayVoiceStatus(message)
        if (shouldSuppressFeedbackDuringVoiceRecognition(
                voiceRecognitionActive || gatewayVoiceRecorder?.isRecording == true,
                isRisk = false,
            )
        ) {
            onFailed?.invoke()
            return false
        }
        // New output owns the visible response; cancellation of an older TTS cannot overwrite it.
        val responseGeneration = ++commandSpeechResponseGeneration
        // registerLatest retires old callbacks silently. Preserve retry for an interrupted
        // route decision before its callback is retired, without changing other response policy.
        failInterruptedRouteDecisionSpeech(responseGeneration - 1L)
        val responseId = "command-response-$responseGeneration"
        val recognitionGeneration = voiceRecognitionGeneration
        val responseActor = reporterUserId
        val gatewayGeneration = GatewaySessionProcessCoordinator.snapshot().generation
        val responseEpoch = if (::walkSessionLifecycle.isInitialized) walkSessionLifecycle.snapshot().epoch else null
        val homeResponse = nativeHomeFeatureContextAvailable() && visibleResponse
        var responseFailureDetail = "음성 안내를 완료하지 못했습니다. 화면 안내를 확인하고 다시 시도해 주세요."
        voiceCommandPromptPending = preparingInput
        if (!preparingInput) voiceCommandPromptReadyGeneration = null
        fun responseCurrent(): Boolean =
            responseGeneration == commandSpeechResponseGeneration &&
                isFeedbackLifecycleCurrent(lifecycleGeneration) && isActivityForeground &&
                recognitionGeneration == voiceRecognitionGeneration &&
                responseActor == reporterUserId &&
                (nativeUiPage == responsePage ||
                    (nativeUiPage.isVoiceInteractionPage() && responsePage.isVoiceInteractionPage())) &&
                GatewaySessionProcessCoordinator.snapshot().generation == gatewayGeneration &&
                !voiceRecognitionActive && gatewayVoiceRecorder?.isRecording != true &&
                (responseEpoch == null || (::walkSessionLifecycle.isInitialized &&
                    walkSessionLifecycle.snapshot().epoch == responseEpoch)) &&
                (!homeResponse || nativeHomeFeatureContextAvailable())
        commandSpeechResponseCallbacks.registerLatest(
            responseId,
            onCompleted = {
                val current = responseCurrent()
                if (!current && preparingInput && responseGeneration == commandSpeechResponseGeneration) {
                    voiceCommandPromptPending = false
                    voiceCommandPromptReadyGeneration = null
                }
                updateVoiceCommandButton(active = voiceRecognitionActive)
                if (current) {
                    updateNavigationStatus("voice=feedback_completed")
                    logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.OUTPUT_DONE)
                    onCompleted?.invoke()
                } else {
                    onFailed?.invoke()
                }
            },
            onFailed = {
                if (preparingInput && responseGeneration == commandSpeechResponseGeneration) {
                    voiceCommandPromptPending = false
                    voiceCommandPromptReadyGeneration = null
                }
                updateVoiceCommandButton(active = voiceRecognitionActive)
                if (responseCurrent()) {
                    if (visibleResponse) updateGatewayVoiceStatus(
                        "$message\n$responseFailureDetail",
                    )
                    updateNavigationStatus("voice=feedback_retry_required")
                    logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.OUTPUT_FAILED)
                }
                onFailed?.invoke()
            },
        )
        updateVoiceCommandButton(active = voiceRecognitionActive)
        val completed: () -> Unit = {
            runOnUiThread {
                commandSpeechResponseCallbacks.takeTerminalCallback(
                    responseId, completed = true, notifyFailure = true,
                )?.invoke()
                updateVoiceCommandButton(active = voiceRecognitionActive)
                refreshForegroundHomeWakeListening()
            }
        }
        val failed: () -> Unit = {
            runOnUiThread {
                commandSpeechResponseCallbacks.takeTerminalCallback(
                    responseId, completed = false, notifyFailure = true,
                )?.invoke()
                updateVoiceCommandButton(active = voiceRecognitionActive)
                refreshForegroundHomeWakeListening()
            }
        }
        val actuator = ensureFeedbackActuator()
        val readinessDeadlineMs = SystemClock.elapsedRealtime() +
            AndroidFeedbackActuator.INITIALIZATION_READINESS_TIMEOUT_MS
        val readinessHandler = android.os.Handler(android.os.Looper.getMainLooper())
        var waitingForReadiness = false
        fun dispatchWhenReady(): Boolean {
            when (commandSpeechResponseCallbacks.commandSpeechReadiness(
                utteranceId = responseId,
                requestCurrent = responseCurrent() && feedbackActuator === actuator,
                speechInitializing = actuator.isSpeechInitializing(),
                nowMs = SystemClock.elapsedRealtime(),
                deadlineMs = readinessDeadlineMs,
            )) {
                CommandSpeechReadiness.WAITING -> {
                    if (!waitingForReadiness) {
                        waitingForReadiness = true
                        if (visibleResponse) updateGatewayVoiceStatus("$message\n음성을 준비하고 있습니다.")
                        if (BuildConfig.DEBUG) android.util.Log.d(
                            "WalkSafeVoiceInput", "event=OUTPUT_READY_WAIT result=WAITING",
                        )
                    }
                    readinessHandler.postDelayed({ dispatchWhenReady() }, 100L)
                    return true
                }
                CommandSpeechReadiness.CANCELLED -> {
                    failed()
                    return false
                }
                CommandSpeechReadiness.TIMED_OUT -> {
                    responseFailureDetail = "한국어 음성 준비가 완료되지 않았습니다. 잠시 후 음성 명령을 다시 눌러 주세요."
                    if (BuildConfig.DEBUG) android.util.Log.d(
                        "WalkSafeVoiceInput", "event=OUTPUT_READY_WAIT result=TIMEOUT",
                    )
                    failed()
                    return false
                }
                CommandSpeechReadiness.DISPATCH -> Unit
            }
            cancelForegroundHomeWakeListening()
            val dispatch = if (homeResponse || statusExplanation) {
                actuator.speakHomeCommandInteraction(message, onFailed = failed, onCompleted = completed)
            } else {
                actuator.speakInteraction(message, onCompleted = completed, onFailed = failed)
            }
            if (BuildConfig.DEBUG) {
                android.util.Log.d("WalkSafeVoiceInput", "event=OUTPUT_DISPATCH result=${dispatch.name}")
            }
            if (dispatch != NavigationSpeechDispatchResult.ACCEPTED) failed()
            return dispatch == NavigationSpeechDispatchResult.ACCEPTED
        }
        return dispatchWhenReady()
    }

    private fun prepareOneShotVoiceCommandPrompt(): Boolean {
        val preparationGeneration = voiceRecognitionGeneration
        stopHandsFreeVoiceService()
        return speakCommandResponse(
            message = "안내가 끝나면 말씀해 주세요.",
            preparingInput = true,
            onCompleted = {
                if (voiceCommandPromptPending && voiceRecognitionGeneration == preparationGeneration) {
                    voiceCommandPromptPending = false
                    voiceCommandPromptReadyGeneration = preparationGeneration
                    // Exactly the explicit user's pending request continues after real TTS onDone.
                    if (!startVoiceCommandRecognition()) updateVoiceCommandButton(active = false)
                }
            },
            onFailed = {
                if (voiceRecognitionGeneration == preparationGeneration) {
                    voiceCommandPromptPending = false
                    voiceCommandPromptReadyGeneration = null
                    updateVoiceCommandButton(active = voiceRecognitionActive)
                }
            },
        )
    }

    private fun speakAdvisory(
        action: NonMetricObstacleAdvisoryAction,
        expectedWalkEpoch: WalkRuntimeEpoch,
        fallbackGeneration: Int,
        lifecycleGeneration: Int,
        onDelivered: () -> Unit,
        onFailed: () -> Unit,
    ): Boolean {
        val generation = feedbackLifecycleGeneration
        if (Looper.myLooper() != Looper.getMainLooper()) {
            runOnUiThread {
                if (!isFeedbackLifecycleCurrent(generation)) {
                    onFailed()
                    return@runOnUiThread
                }
                speakAdvisory(
                    action,
                    expectedWalkEpoch,
                    fallbackGeneration,
                    lifecycleGeneration,
                    onDelivered,
                    onFailed,
                )
            }
            return true
        }
        if (!isFeedbackLifecycleCurrent(generation)) {
            onFailed()
            return false
        }
        if (
            !isCameraFallbackAdvisoryStillDeliverable(
                action,
                expectedWalkEpoch,
                fallbackGeneration,
                lifecycleGeneration,
            ) ||
            !nonMetricAdvisoryPolicy.isDeliveryCurrent(action)
        ) {
            onFailed()
            return false
        }
        if (shouldSuppressFeedbackDuringVoiceRecognition(voiceRecognitionActive, isRisk = false)) {
            onFailed()
            return false
        }
        val accepted = ensureFeedbackActuator().speakAdvisory(
            message = action.message,
            validUntilMs = action.validUntilMs,
            isStillValid = {
                isCameraFallbackAdvisoryStillDeliverable(
                    action,
                    expectedWalkEpoch,
                    fallbackGeneration,
                    lifecycleGeneration,
                ) && nonMetricAdvisoryPolicy.isDeliveryCurrent(action)
            },
            onCompleted = onDelivered,
            onFailed = onFailed,
        )
        if (!accepted) onFailed()
        return accepted
    }

    private fun isScreenReaderActive(): Boolean {
        val accessibilityManager = getSystemService(AccessibilityManager::class.java) ?: return false
        return accessibilityManager.isEnabled && accessibilityManager.getEnabledAccessibilityServiceList(
            AccessibilityServiceInfo.FEEDBACK_SPOKEN,
        ).isNotEmpty()
    }

    private fun isFeedbackLifecycleCurrent(generation: Int): Boolean =
        isActivityForeground && feedbackLifecycleGeneration == generation

    private fun announceForTalkBack(
        message: String,
        priority: TalkBackAnnouncementPriority,
        onDelivered: (() -> Unit)? = null,
        riskRank: Int? = null,
        riskTrackId: String? = null,
    ): Boolean {
        if (message.isBlank()) return false
        if (
            shouldSuppressFeedbackDuringVoiceRecognition(
                voiceRecognitionActive,
                isRisk = priority == TalkBackAnnouncementPriority.RISK,
            )
        ) return false
        if (!::statusText.isInitialized) return false
        val nowMs = SystemClock.elapsedRealtime()
        when (priority) {
            TalkBackAnnouncementPriority.RISK -> {
                val rank = riskRank ?: 0
                val activeRiskHeld = nowMs < riskAnnouncementHoldUntilMs
                val preemptsActiveRisk = activeRiskHeld && rank > lastRiskAnnouncementRank
                if (activeRiskHeld && !preemptsActiveRisk) return false
                if (
                    !preemptsActiveRisk &&
                    message == lastRiskAnnouncement &&
                    nowMs - lastRiskAnnouncementMs < TALKBACK_RISK_DUP_WINDOW_MS
                ) return false
                lastRiskAnnouncement = message
                lastRiskAnnouncementTrackId = riskTrackId.orEmpty()
                lastRiskAnnouncementMs = nowMs
                lastRiskAnnouncementRank = rank
                riskAnnouncementHoldUntilMs = nowMs + utteranceTerminalTimeoutMs(message.length)
            }
            TalkBackAnnouncementPriority.INTERACTION -> {
                if (nowMs < riskAnnouncementHoldUntilMs) {
                    return scheduleTalkBackInteraction(
                        message,
                        riskAnnouncementHoldUntilMs - nowMs,
                        onDelivered,
                    )
                }
                if (
                    message == lastInteractionAnnouncement &&
                    nowMs - lastInteractionAnnouncementMs < TALKBACK_INTERACTION_DUP_WINDOW_MS
                ) return false
                lastInteractionAnnouncement = message
                lastInteractionAnnouncementMs = nowMs
            }
            TalkBackAnnouncementPriority.ADVISORY -> {
                if (nowMs < riskAnnouncementHoldUntilMs || nowMs < navigationAnnouncementHoldUntilMs) return false
                if (nowMs - lastInteractionAnnouncementMs < TALKBACK_INTERACTION_PRIORITY_WINDOW_MS) return false
                if (
                    message == lastAdvisoryAnnouncement &&
                    nowMs - lastAdvisoryAnnouncementMs < TALKBACK_ADVISORY_DUP_WINDOW_MS
                ) return false
                lastAdvisoryAnnouncement = message
                lastAdvisoryAnnouncementMs = nowMs
            }
            TalkBackAnnouncementPriority.NAVIGATION -> {
                if (nowMs < riskAnnouncementHoldUntilMs) return false
                if (nowMs - lastInteractionAnnouncementMs < TALKBACK_INTERACTION_PRIORITY_WINDOW_MS) return false
                if (
                    message == lastNavigationAnnouncement &&
                    nowMs - lastNavigationAnnouncementMs < TALKBACK_NAVIGATION_DUP_WINDOW_MS
                ) return false
                lastNavigationAnnouncement = message
                lastNavigationAnnouncementMs = nowMs
                navigationAnnouncementHoldUntilMs = nowMs + utteranceTerminalTimeoutMs(message.length)
            }
        }
        runOnUiThread {
            statusText.announceForAccessibility(message)
            onDelivered?.invoke()
        }
        return true
    }

    private fun scheduleTalkBackInteraction(
        message: String,
        delayMs: Long,
        onDelivered: (() -> Unit)? = null,
    ): Boolean {
        if (!::statusText.isInitialized) return false
        pendingTalkBackInteraction?.let(statusText::removeCallbacks)
        val delivery = Runnable {
            pendingTalkBackInteraction = null
            announceForTalkBack(
                message,
                TalkBackAnnouncementPriority.INTERACTION,
                onDelivered = onDelivered,
            )
        }
        pendingTalkBackInteraction = delivery
        statusText.postDelayed(delivery, delayMs.coerceAtLeast(1L))
        return true
    }

    private fun reconcileTalkBackRiskTracks(activeTrackIds: Set<String>) {
        if (lastRiskAnnouncementTrackId.isBlank() || lastRiskAnnouncementTrackId in activeTrackIds) return
        lastRiskAnnouncement = ""
        lastRiskAnnouncementMs = 0L
        lastRiskAnnouncementTrackId = ""
        lastRiskAnnouncementRank = -1
        riskAnnouncementHoldUntilMs = 0L
        if (activeTrackIds.isNotEmpty()) return
        val pendingInteraction = pendingTalkBackInteraction ?: return
        pendingTalkBackInteraction = null
        if (::statusText.isInitialized) statusText.removeCallbacks(pendingInteraction)
        pendingInteraction.run()
    }

    private fun navigationSpeechCapabilityAllowed(): Boolean =
        developmentGuidanceStartBypassEnabled ||
            startupCapabilityDecision?.allowsRequirement(
                WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS,
            ) != false

    private fun ensureFeedbackActuator(): AndroidFeedbackActuator {
        val current = feedbackActuator
        if (current != null) return current
        val generation = feedbackLifecycleGeneration
        var createdActuator: AndroidFeedbackActuator? = null
        return AndroidFeedbackActuator(
            context = this,
            onOfflineKoreanSpeechUnavailable = {
                runOnUiThread {
                    if (!isFeedbackLifecycleCurrent(generation) || createdActuator == null ||
                        feedbackActuator !== createdActuator) return@runOnUiThread
                    if (postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.VOICE_GUIDANCE)) {
                        handleRuntimeSpeechCapabilityFailure(
                            WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS,
                            "오프라인 한국어 음성 안내를 시작할 수 없어 음성 안내 기능을 제한합니다.",
                        )
                    }
                }
            },
            onOfflineKoreanSpeechReady = {
                runOnUiThread {
                    if (!isFeedbackLifecycleCurrent(generation) || createdActuator == null ||
                        feedbackActuator !== createdActuator) return@runOnUiThread
                    if (offlineKoreanTextToSpeechCapabilityOverride == false) {
                        offlineKoreanTextToSpeechCapabilityOverride = null
                    }
                    refreshStartupCapabilityUi()
                    updatePriorityUserOnboardingUi()
                    updateVoiceCommandButton(active = voiceRecognitionActive)
                    scheduleNavigationSpeechRetry(delayMs = 0L)
                }
            },
            speechAllowed = ::navigationSpeechCapabilityAllowed,
            hapticAllowed = {
                startupCapabilityDecision?.allowsRequirement(
                    WalkSafeStartupRequirement.VIBRATION,
                ) != false
            },
        ).also {
            createdActuator = it
            feedbackActuator = it
        }
    }

    private fun prepareHandsFreeVoiceModel() {
        if (handsFreeVoiceDestroyed || handsFreeVoiceModelDirectory != null || handsFreeVoiceModelPreparing) return
        if (!BundledVoskModelInstaller.bundledModelAvailable(this)) {
            handsFreeVoiceModelPreparationFailed = true
            updateNavigationStatus("voice_hands_free=model_asset_missing")
            maybeContinuePostLoginDeviceCheck()
            return
        }
        handsFreeVoiceModelPreparationFailed = false
        handsFreeVoiceModelPreparing = true
        updateVoiceCommandButton()
        val generation = ++handsFreeVoiceModelGeneration
        try {
            handsFreeVoiceModelExecutor.execute {
                val prepared = runCatching {
                    BundledVoskModelInstaller.installedModelOrNull(this)
                        ?: BundledVoskModelInstaller.install(this)
                }
                runOnUiThread {
                    if (
                        handsFreeVoiceDestroyed ||
                        generation != handsFreeVoiceModelGeneration
                    ) return@runOnUiThread
                    handsFreeVoiceModelPreparing = false
                    prepared.onSuccess { directory ->
                        oneShotSpeechRecognitionLimited = false
                        handsFreeVoiceModelPreparationFailed = false
                        handsFreeVoiceModelDirectory = directory
                        attachHandsFreeVoiceController(directory)
                        updateNavigationStatus("voice_hands_free=model_ready")
                        maybeContinuePostLoginDeviceCheck()
                        refreshStartupCapabilityUi()
                        updateVoiceCommandButton()
                        maybeStartHandsFreeVoiceService()
                    }.onFailure {
                        handsFreeVoiceModelPreparationFailed = true
                        updateVoiceCommandButton()
                        updateNavigationStatus("voice_hands_free=model_install_failed")
                        maybeContinuePostLoginDeviceCheck()
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            handsFreeVoiceModelPreparing = false
            updateVoiceCommandButton()
            handsFreeVoiceModelPreparationFailed = true
            updateNavigationStatus("voice_hands_free=model_install_rejected")
            maybeContinuePostLoginDeviceCheck()
        }
    }

    private fun attachHandsFreeVoiceController(modelDirectory: File) {
        if (handsFreeVoiceController != null || handsFreeVoiceDestroyed) return
        val controller = HandsFreeVoiceController(
            context = applicationContext,
            modelDirectory = modelDirectory,
            eligibility = {
                HandsFreeVoiceEligibility(
                    walkState = walkSessionLifecycle.snapshot().state,
                    microphoneGranted = hasRecordAudioPermission(),
                    disclosureAccepted = isHandsFreeVoiceDisclosureAccepted(),
                    modelReady = handsFreeVoiceModelDirectory?.isDirectory == true,
                )
            },
            isAppSpeechActive = ::isHandsFreeVoiceOutputActive,
            onCommand = command@{ text, confidence ->
                if (!isWalkSessionRuntimeActive()) return@command
                handleVoiceCommandPhrases(
                    phrases = listOf(text),
                    confidenceScores = floatArrayOf(confidence ?: Float.NaN),
                    expectedNavigationDecisionToken = routeNavigator.pendingDecisionToken(),
                    includeRecognizedTextInStatus = false,
                    redactedRecognitionSource = "on_device_hands_free",
                )
            },
            onStatus = ::updateNavigationStatus,
            onCommandListeningStarted = ::handleHandsFreeVoiceCommandListeningStarted,
            onTerminalFailure = ::handleHandsFreeVoiceTerminalFailure,
            onSessionEnded = ::handleHandsFreeVoiceSessionEnded,
            isSpeechRecognitionBlocked = ::isHandsFreeVoiceRecognitionBlocked,
        )
        handsFreeVoiceController = controller
        (application as? WalkSafeApplication)?.attachWalkVoiceSessionController(controller)
            ?: run {
                handsFreeVoiceController = null
                controller.close()
                updateNavigationStatus("voice_hands_free=application_provider_missing")
            }
    }

    private fun isHandsFreeVoiceOutputActive(): Boolean {
        if (foregroundHomeWakeAcknowledgement?.isPlaying() == true) return true
        return isHandsFreeVoiceSpeechOutputActive()
    }

    private fun isHandsFreeVoiceRecognitionBlocked(): Boolean =
        isHandsFreeVoiceOutputActive() || feedbackActuator?.isSpeechRecognitionBlocked() == true

    private fun isHandsFreeVoiceSpeechOutputActive(): Boolean {
        if (commandSpeechResponseCallbacks.size() > 0 || gatewaySpeechPlayer != null) return true
        if (feedbackActuator?.isAppSpeechActive() == true) return true
        if (!isScreenReaderActive()) return false
        val nowMs = SystemClock.elapsedRealtime()
        val interactionHoldUntil = lastInteractionAnnouncementMs +
            utteranceTerminalTimeoutMs(lastInteractionAnnouncement.length)
        val advisoryHoldUntil = lastAdvisoryAnnouncementMs +
            utteranceTerminalTimeoutMs(lastAdvisoryAnnouncement.length)
        return pendingTalkBackInteraction != null ||
            nowMs < maxOf(
                riskAnnouncementHoldUntilMs,
                navigationAnnouncementHoldUntilMs,
                interactionHoldUntil,
                advisoryHoldUntil,
            )
    }

    private fun handleHandsFreeVoiceCommandListeningStarted() {
        if (isWalkSessionRuntimeActive()) {
            handsFreeVoiceOwnsCommandPage = true
            if (nativeUiPage != NativeUiPage.DESTINATION_SEARCH) {
                showNativeUiPage(NativeUiPage.VOICE_COMMAND, preserveVoiceInteraction = true)
            }
        }
        runCatching { ensureFeedbackActuator().playVoiceListeningStartVibration() }
        updateGatewayVoiceStatus("호출어를 인식했습니다. 음성 명령을 듣고 있습니다.")
        updateNavigationStatus("voice_hands_free=listening_command")
    }

    private fun handleHandsFreeVoiceSessionEnded() {
        handsFreeVoiceRestartRunnable?.let { pending ->
            if (::statusText.isInitialized) statusText.removeCallbacks(pending)
        }
        handsFreeVoiceRestartRunnable = null
        handsFreeVoiceServiceRequested = false
        runCatching { stopService(Intent(this, WalkVoiceForegroundService::class.java)) }
    }

    private fun handleHandsFreeVoiceTerminalFailure(
        failure: HandsFreeVoiceTerminalFailure,
    ) {
        handsFreeVoiceRestartRunnable?.let { pending ->
            if (::statusText.isInitialized) statusText.removeCallbacks(pending)
        }
        handsFreeVoiceRestartRunnable = null
        handsFreeVoiceServiceRequested = false
        runCatching { stopService(Intent(this, WalkVoiceForegroundService::class.java)) }
        when (failure) {
            is HandsFreeVoiceTerminalFailure.Transcriber -> {
                val wasConfirmed = isStartupCapabilityConfirmed()
                onDeviceSpeechRecognitionCapabilityOverride = false
                refreshStartupCapabilityUi()
                if (wasConfirmed) {
                    confirmedStartupCapabilityDecision = startupCapabilityDecision?.takeIf {
                        it.mayConfirmAndStart
                    }
                    refreshStartupCapabilityUi()
                }
                updateStatus(
                    "호출어 음성 기능 제한",
                    "기기 내 Vosk 음성 처리 오류로 호출어 기능만 제한했습니다. " +
                        "화면 음성 명령과 보행의 다른 기능은 계속 사용할 수 있습니다.",
                )
                updateNavigationStatus(
                    "voice_hands_free=transcriber_limited_${failure.statusToken}",
                )
            }
            HandsFreeVoiceTerminalFailure.CommandDispatchFailed,
            HandsFreeVoiceTerminalFailure.OutputTimeout,
            -> {
                updateNavigationStatus(
                    "voice_hands_free=internal_restart_${failure.statusToken}",
                )
                scheduleHandsFreeVoiceRestart()
            }
        }
    }

    private fun maybeStartHandsFreeVoiceService() {
        refreshForegroundHomeWakeListening()
        if (foregroundHomeWakeProbe != null) return
        if (!isActivityForeground ||
            (nativeUiPage == NativeUiPage.VOICE_COMMAND && !handsFreeVoiceOwnsCommandPage) ||
            pendingNativeUiPage == NativeUiPage.VOICE_COMMAND
        ) return
        if (!postLoginDeviceFeatureEnabled(PostLoginDeviceCheckFeature.HANDS_FREE_VOICE)) {
            updateNavigationStatus("voice_hands_free=device_feature_limited")
            return
        }
        if (
            startupCapabilityDecision?.allowsRequirement(
                WalkSafeStartupRequirement.MICROPHONE,
            ) == false ||
            startupCapabilityDecision?.allowsRequirement(
                WalkSafeStartupRequirement.ON_DEVICE_STT,
            ) == false
        ) {
            updateNavigationStatus("voice_hands_free=runtime_feature_limited")
            return
        }
        if (!isHandsFreeVoiceDisclosureAccepted()) {
            updateNavigationStatus("voice_hands_free=disclosure_required")
            return
        }
        if (!hasHandsFreeNotificationPermission()) {
            updateNavigationStatus("voice_hands_free=notification_permission_required")
            return
        }
        if (
            handsFreeVoiceDestroyed ||
            handsFreeVoiceServiceRequested ||
            handsFreeVoiceController == null ||
            handsFreeVoiceModelDirectory?.isDirectory != true ||
            !hasRecordAudioPermission() ||
            voiceRecognitionActive || voiceCommandPromptPending || deferredVoiceRecognitionStart != null ||
            gatewayVoiceRecorder?.isRecording == true ||
            activeGatewaySpeechInteraction != null ||
            !isWalkSessionRuntimeActive()
        ) return
        val startIntent = Intent(this, WalkVoiceForegroundService::class.java)
            .setAction(WalkVoiceForegroundService.ACTION_START)
        try {
            android.util.Log.i("WalkSafeVoice", "service_start_requested")
            startService(startIntent)
            handsFreeVoiceServiceRequested = true
        } catch (_: RuntimeException) {
            handsFreeVoiceServiceRequested = false
            android.util.Log.w("WalkSafeVoice", "service_start_failed")
            updateNavigationStatus("voice_hands_free=service_start_failed")
        }
    }

    private fun scheduleHandsFreeVoiceRestart() {
        if (!::statusText.isInitialized || handsFreeVoiceDestroyed) return
        handsFreeVoiceRestartRunnable?.let(statusText::removeCallbacks)
        lateinit var restart: Runnable
        restart = Runnable {
            if (handsFreeVoiceRestartRunnable !== restart) return@Runnable
            handsFreeVoiceRestartRunnable = null
            maybeStartHandsFreeVoiceService()
        }
        handsFreeVoiceRestartRunnable = restart
        statusText.postDelayed(restart, HANDS_FREE_VOICE_RESTART_DELAY_MS)
    }

    private fun stopHandsFreeVoiceService() {
        handsFreeVoiceRestartRunnable?.let { pending ->
            if (::statusText.isInitialized) statusText.removeCallbacks(pending)
        }
        handsFreeVoiceRestartRunnable = null
        val controller = handsFreeVoiceController
        val serviceMayBeRunning = handsFreeVoiceServiceRequested || controller != null
        handsFreeVoiceServiceRequested = false
        controller?.stop()
        if (serviceMayBeRunning) {
            runCatching { stopService(Intent(this, WalkVoiceForegroundService::class.java)) }
        }
    }

    private fun closeHandsFreeVoice() {
        if (handsFreeVoiceDestroyed) return
        handsFreeVoiceOwnsCommandPage = false
        handsFreeVoiceDestroyed = true
        cancelForegroundHomeWakeAcknowledgement()
        foregroundHomeWakeAcknowledgement?.close()
        foregroundHomeWakeAcknowledgement = null
        handsFreeVoiceModelGeneration += 1L
        stopHandsFreeVoiceService()
        val controller = handsFreeVoiceController
        handsFreeVoiceController = null
        if (controller != null) {
            (application as? WalkSafeApplication)?.detachWalkVoiceSessionController(controller)
            controller.close()
        }
        handsFreeVoiceModelExecutor.shutdownNow()
    }

    private fun onWalkRuntimeSafetyStop(stop: WalkRuntimeSafetyStop) {
        runOnUiThread {
            if (developmentGuidanceStartBypassEnabled && stop.causes.none {
                    it == WalkRuntimeSafetyStopCause.EPOCH_MISMATCH ||
                        it == WalkRuntimeSafetyStopCause.INVALID_TIME
                }
            ) return@runOnUiThread
            if (
                !::walkSessionLifecycle.isInitialized ||
                !walkSessionLifecycle.isRuntimeEpochCurrent(stop.epoch)
            ) {
                return@runOnUiThread
            }
            val causes = stop.causes
                .map { it.name.lowercase(Locale.US) }
                .sorted()
                .joinToString("+")
            enterWalkSessionSafetyStopAndCancelOutputs(
                reason = "runtime_safety_coordinator:$causes",
            )
        }
    }

    private fun enterWalkSessionSafetyStopAndCancelOutputs(
        reason: String,
        persistInterruptionMarker: Boolean = true,
    ) {
        if (developmentGuidanceStartBypassEnabled && reason in setOf(
                "camera_release_timed_out", "detector_runtime_failed",
                "offline_korean_tts_runtime_failure", "required_app_permission_denied",
            )
        ) {
            updateNavigationStatus("navigation=test_continues unavailable=$reason")
            return
        }
        val walkSnapshot = if (::walkSessionLifecycle.isInitialized) {
            walkSessionLifecycle.snapshot()
        } else {
            null
        }
        val gatewaySessionForEnd = walkSnapshot?.takeIf {
            it.state in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED)
        }?.let { gatewayFieldSession }
        val endOperation = walkSnapshot?.takeIf {
            it.state in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED)
        }?.let { gatewayWalkAuthorityController.beginEnd(it.epoch) }
        if (::walkSessionLifecycle.isInitialized) {
            transitionWalkSession(WalkSessionEvent.SafetyStopRequested)
            if (persistInterruptionMarker) persistWalkSessionInterruptionMarker()
        }
        if (endOperation != null && gatewaySessionForEnd != null) {
            endGatewayWalkBestEffort(gatewaySessionForEnd, endOperation)
        }
        invalidateOfficialEnvironmentEvidence("safety_stop:$reason")
        invalidatePhoneMountingEvidence("safety_stop:$reason")
        walkSessionResumePromptPending = false
        walkSessionResumeRetryRequiresUserAction = false
        walkSessionResumeConfirmationToken = null
        cancelWalkSessionOutputs(reason)
        stopCameraFallbackSession(updateUi = false)
        stopDepthSession(closeSession = true)
        if (::startupCapabilityProbe.isInitialized) refreshStartupCapabilityUi()
    }

    private fun startFreshWalk(reason: String) {
        transitionWalkSession(WalkSessionEvent.NewWalkRequested)
        persistWalkSessionInterruptionMarker()
        invalidateOfficialEnvironmentEvidence("new_walk:$reason")
        invalidatePhoneMountingEvidence("new_walk:$reason")
        walkSessionResumePromptPending = false
        walkSessionResumeRetryRequiresUserAction = false
        walkSessionResumeConfirmationToken = null
        cancelWalkSessionOutputs(reason)
        resetWalkTransientStateForNewWalk()
    }

    private fun resetWalkTransientStateForNewWalk() {
        runtimeObstacleDetectionCapabilityOverride = null
        metricDistanceCapabilityOverride = if (postLoginCameraDependentChecksDeferred) {
            false
        } else if (postLoginDeviceCheckSnapshot.passesFeatureGate) {
            PostLoginDeviceCheckFeature.METRIC_DISTANCE_GUIDANCE !in
                postLoginDeviceCheckSnapshot.disabledFeatures
        } else {
            null
        }
        latestStepCount = 0
        tmapFailureGuard.reset()
        if (::stepTracker.isInitialized) stepTracker.resetForNewWalk()
        if (currentLocationCollectionAllowsWork()) {
            freshTrustedLocationOrNull()
            clearLocationDerivedState()
        } else {
            clearTrustedLocation()
        }
        pendingVoiceDestinationQuery = null
        feedbackPolicy.resetForNewWalk()
        nonMetricAdvisoryPolicy.reset()
        lastRiskAnnouncementMs = 0L
        lastRiskAnnouncement = ""
        lastRiskAnnouncementTrackId = ""
        lastRiskAnnouncementRank = -1
        riskAnnouncementHoldUntilMs = 0L
        lastNavigationAnnouncementMs = 0L
        lastNavigationAnnouncement = ""
        navigationAnnouncementHoldUntilMs = 0L
        lastAdvisoryAnnouncementMs = 0L
        lastAdvisoryAnnouncement = ""
        lastInteractionAnnouncementMs = 0L
        lastInteractionAnnouncement = ""
        lastProgressBeepAtMs = 0L
        latestNavigationState = "navigation=not_started"
    }

    private fun enterWalkSessionForegroundRecheckAndCancelOutputs(reason: String) {
        if (BuildConfig.DEBUG) runCatching {
            android.util.Log.d("WalkSafeNavigation", "output=foreground_recheck reason=$reason")
        }
        if (::walkSessionLifecycle.isInitialized) {
            transitionWalkSession(WalkSessionEvent.RecheckRequested)
            persistWalkSessionInterruptionMarker()
        }
        invalidateOfficialEnvironmentEvidence("foreground_recheck:$reason")
        invalidatePhoneMountingEvidence("foreground_recheck:$reason")
        walkSessionResumePromptPending = false
        walkSessionResumeRetryRequiresUserAction = false
        walkSessionResumeConfirmationToken = null
        cancelWalkSessionOutputs(reason)
        stopCameraFallbackSession(updateUi = false)
        stopDepthSession(closeSession = true)
    }

    private fun cancelWalkSessionOutputs(reason: String) {
        if (BuildConfig.DEBUG) runCatching {
            android.util.Log.d("WalkSafeNavigation", "output=session_outputs_cancelled reason=$reason")
        }
        feedbackLifecycleGeneration += 1
        invalidatePendingExplicitReport()
        invalidateArCoreAvailabilityRecheck()
        confirmedStartupCapabilityDecision = null
        startupCapabilityConfirmationPending = false
        startupCapabilityRetryRequiresUserAction = false
        pendingCameraFallbackStart = null
        stopHandsFreeVoiceService()
        cancelVoiceCommandRecognition()
        synchronized(reportUploadSafetyLock) {
            reportUploadSafetyGeneration += 1L
            reportPrivacyConsentSession.cancelActiveCalls()
        }
        val navigationCancellation = cancelNavigationRequestsForPause()
        clearDestinationSearchState(navigationCancellation.destinationSearchCancelled)
        if (
            ::walkSessionLifecycle.isInitialized &&
            walkSessionLifecycle.snapshot().state == WalkSessionState.PAUSED
        ) {
            resetRouteState(purgeRouteSnapshot = false)
        } else {
            resetRouteState()
        }
        invalidateFrameStateForPause()
        stopActivePositionFieldSession()
        if (!currentLocationCollectionAllowsWork()) stopLocationUpdates()
        stopStepTracking()
        if (::phoneMountingSensorProbe.isInitialized) phoneMountingSensorProbe.stop()
        retainLocationCompassOrStop()
        feedbackPolicy.cancelPendingFeedbackDeliveries()
        if (::statusText.isInitialized) {
            pendingTalkBackInteraction?.let(statusText::removeCallbacks)
        }
        pendingTalkBackInteraction = null
        cancelPendingFeedbackTerminalResolution()
        latestFeedbackDeliveryState = FeedbackDeliveryState()
        feedbackActuator?.close()
        feedbackActuator = null
        if (::cameraFallbackLifecycleOwner.isInitialized) {
            cameraFallbackLifecycleOwner.moveTo(Lifecycle.State.CREATED)
        }
        if (::surfaceView.isInitialized) {
            syncGlSurfaceRenderMode(
                forceFrame = true,
                allowContinuousRendering = false,
            )
            surfaceView.onPause()
        }
        syncActiveSessionScreenPolicy()
        if (::fieldSessionLog.isInitialized) {
            fieldSessionLog.recordEvent(
                "walk_session_outputs_cancelled",
                mapOf("reason" to reason),
            )
        }
        startLocationUpdatesIfAllowed()
    }

    private fun handleOneShotSpeechRecognitionFailure(
        detail: String,
        permanentlyLimit: Boolean,
    ) {
        if (permanentlyLimit) oneShotSpeechRecognitionLimited = true
        voiceRecognitionGeneration += 1
        voiceRecognitionActive = false
        voiceRecognitionPurpose = VoiceRecognitionPurpose.COMMAND
        clearVoiceEndConfirmation()
        speechRecognizer?.destroy()
        speechRecognizer = null
        updateGatewayVoiceStatus(
            if (permanentlyLimit) {
                "기기 내 화면 음성 명령을 사용할 수 없습니다."
            } else {
                "기기 내 화면 음성 듣기가 종료됐습니다. 다시 시도할 수 있습니다."
            },
        )
        updateVoiceCommandButton(active = false)
        scheduleHandsFreeVoiceRestart()
        speakInteraction(
            if (permanentlyLimit) detail else "$detail 음성 명령을 다시 눌러 주세요.",
        )
        if (permanentlyLimit) {
            updateStatus(
                "화면 음성 명령 기능 제한",
                "$detail 기기 내 호출어와 보행의 다른 기능은 계속 사용할 수 있습니다.",
            )
        } else {
            updateStatus(
                "화면 음성 명령 종료",
                "$detail 다시 시도할 수 있으며 호출어와 보행의 다른 기능은 계속 사용할 수 있습니다.",
            )
        }
    }

    private fun handleRuntimeSpeechCapabilityFailure(
        requirement: WalkSafeStartupRequirement,
        detail: String,
    ) {
        if (requirement != WalkSafeStartupRequirement.OFFLINE_KOREAN_TTS) return
        val wasConfirmed = isStartupCapabilityConfirmed()
        if (offlineKoreanTextToSpeechCapabilityOverride == false) return
        offlineKoreanTextToSpeechCapabilityOverride = false
        val activeWalk = ::walkSessionLifecycle.isInitialized &&
            walkSessionLifecycle.snapshot().state == WalkSessionState.ACTIVE
        if (activeWalk) {
            enterWalkSessionSafetyStopAndCancelOutputs("offline_korean_tts_runtime_failure")
        } else {
            refreshStartupCapabilityUi()
        }
        if (wasConfirmed) {
            confirmedStartupCapabilityDecision = startupCapabilityDecision?.takeIf {
                it.mayConfirmAndStart
            }
            refreshStartupCapabilityUi()
        }
        updateStatus(
            "한국어 음성 필요 · 보행 시작/재개 불가",
            if (activeWalk) {
                "$detail 실행 중인 보행 안내를 안전 중지했습니다. 한국어 음성 데이터를 설치한 뒤 기기 점검을 다시 실행하세요."
            } else {
                "$detail 한국어 음성 데이터를 설치하고 기기 점검을 다시 실행하기 전에는 보행 안내를 시작하거나 재개할 수 없습니다."
            },
        )
        if (isScreenReaderActive()) startupCapabilityText.announceForAccessibility(detail)
    }

    private fun feedbackActuatorStatusText(): String {
        return feedbackActuator?.statusText() ?: "tts=idle"
    }

    private fun buildDeviceGateState(
        bestOutput: TrackedObjectDepth?,
        staleReason: String?,
        expectedRuntimeMetricGeneration: Long? = null,
    ): DeviceGateState {
        val runtimeMetricReady = currentRuntimeMetricOutputAllowsWork(expectedRuntimeMetricGeneration)
        return DeviceGateState(
            cameraPermissionGranted = hasCameraPermission(),
            arCoreSupported = arCoreSupported && runtimeMetricReady,
            depthSupported = depthSupported && runtimeMetricReady,
            tfliteConfigLoaded = detectorConfigLoaded,
            detectorAvailable = detectorAvailable,
            arSessionRunning = runtimeMetricReady,
            freshDepthObject = runtimeMetricReady &&
                bestOutput != null &&
                bestOutput.source.metric &&
                bestOutput.confidence.finalScore >= FEEDBACK_MIN_DEPTH_CONFIDENCE,
            staleReason = staleReason,
        )
    }

    private fun DeviceGateState.statusText(): String {
        val state = if (actuatorsAllowed) "deviceGate=READY" else "deviceGate=WAIT:${blockedReason()}"
        val alertState = if (alertsAllowed) "alertGate=PASS" else "alertGate=WAIT:${blockedReason()}"
        return "$state $alertState startupReady=$startupReady depth=$depthSupported detector=$detectorAvailable"
    }

    internal fun publishCurrentFrameReportState(
        frameGeneration: Int,
        expectedRuntimeMetricGeneration: Long,
        automaticReportOutput: TrackedObjectDepth?,
        reportGateState: DeviceGateState,
        explicitReportOutput: TrackedObjectDepth?,
        explicitReportGateState: DeviceGateState,
        reportImage: ByteArray?,
        nowMs: Long,
        capturedAtMs: Long,
        expectedWalkEpoch: WalkRuntimeEpoch? = null,
    ): Boolean = synchronized(frameStateLock) frameLock@ {
        if (!isCurrentFrameGeneration(frameGeneration, expectedWalkEpoch)) {
            return@frameLock false
        }
        synchronized(runtimeMetricStateLock) runtimeLock@ {
            if (!currentRuntimeMetricOutputAllowsWork(expectedRuntimeMetricGeneration)) {
                return@runtimeLock false
            }
            latestReportCandidateStatus = prepareReportCandidate(
                reportOutput = automaticReportOutput,
                gateState = reportGateState,
                reportImage = reportImage,
                nowMs = nowMs,
                capturedAtMs = capturedAtMs,
            )
            latestExplicitReportOutput = explicitReportOutput
            latestExplicitReportImage = reportImage
            latestExplicitReportGateState = explicitReportGateState
            latestExplicitReportCapturedAtMs = capturedAtMs
            true
        }
    }

    /**
     * Report creation is fail-closed: session consent, damage class, metric depth, device gate,
     * model provenance, trusted GPS, local reporter id and a captured JPEG must all remain available.
     */
    private fun prepareReportCandidate(
        reportOutput: TrackedObjectDepth?,
        gateState: DeviceGateState,
        reportImage: ByteArray?,
        nowMs: Long,
        capturedAtMs: Long,
        trigger: String = "auto",
        explicitRequest: Boolean = false,
        explicitConfirmationContext: ExplicitReportConfirmationContext? = null,
        explicitConfirmationRequestedAtElapsedRealtimeMs: Long? = null,
    ): String {
        if (!reportPermissionsAllowWork()) {
            return "reportCandidate=blocked:permission_unavailable"
        }
        val expectedWalkEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull()
        if (expectedWalkEpoch == null) {
            return "reportCandidate=blocked:walk_session_inactive"
        }
        if (!reportPrivacyConsentSession.isGranted()) {
            return "reportCandidate=blocked:consent_confirmation_required"
        }
        if (
            !explicitRequest &&
            (
                !permissionSessionPolicy.snapshot().mayCreateAutomaticReport ||
                    !integratedConsentSession.isAllowed(
                        IntegratedConsentItem.AUTOMATIC_REPORTING,
                    )
            )
        ) {
            return "reportCandidate=blocked:automatic_report_consent_required"
        }
        if (
            !explicitRequest &&
            run {
                GatewayCapacityProcessState.fenceSessionGeneration(
                    GatewaySessionProcessCoordinator.snapshot().generation,
                )
                !GatewayCapacityProcessState.admission(
                    java.time.Instant.ofEpochMilli(nowMs),
                ).automaticReportCandidateAllowed
            }
        ) {
            return "reportCandidate=blocked:gateway_capacity"
        }
        val reporterId = currentReporterUserId() ?: return "reportCandidate=blocked:login_required"
        val output = reportOutput ?: return "reportCandidate=blocked:no_depth_object"
        if (!AndroidReportCandidatePolicy.isReportableDamageClass(output.className)) {
            return "reportCandidate=blocked:not_reportable_class"
        }
        val loadedReportModel = detectorModelKeyForReports
            ?: return "reportCandidate=blocked:model_unavailable"
        val modelKey = reportRuntimeConfig?.modelKeyForReportClass(output.className)
            ?.takeIf { loadedReportModel == reportRuntimeConfig?.primaryModelKey }
            ?: loadedReportModel
        if (modelKey !in AndroidReportCandidatePolicy.ALLOWED_MODEL_KEYS) {
            return "reportCandidate=blocked:model_not_allowed"
        }
        val sourceModel = resolveReportSourceModel(modelKey) ?: return "reportCandidate=blocked:source_model_missing"
        val threshold = resolveReportThreshold(modelKey, output.className) ?: return "reportCandidate=blocked:threshold_missing"
        if (!gateState.reportCandidatesAllowed) {
            return "reportCandidate=blocked:device_gate"
        }
        val deviceResources = walkSessionResourceProbe.snapshot()
        if (deviceResources.readinessStatus != WalkSessionReadinessStatus.READY) {
            return "reportCandidate=blocked:device_resources_${deviceResources.readinessStatus.name.lowercase(Locale.US)}"
        }
        val requestElapsedRealtimeMs = SystemClock.elapsedRealtime()
        val trustedLocation = freshTrustedLocationOrNull(requestElapsedRealtimeMs)
        if (trustedLocation == null) {
            if (explicitRequest) {
                ensureNavigationPermissionForReport()
                startNavigationServicesIfNeeded()
                speakInteraction("위치 정보가 필요합니다.")
            } else if (reportLocationStartScheduled.compareAndSet(false, true)) {
                runOnUiThread {
                    ensureNavigationPermissionForReport()
                    startNavigationServicesIfNeeded()
                }
            }
            return "reportCandidate=blocked:gps_missing"
        }
        val candidate = reportCandidatePolicy.prepare(
            AndroidReportCandidateInput(
                depth = output,
                location = trustedLocation,
                modelKey = modelKey,
                sourceModel = sourceModel,
                runtimeMode = "android",
                modelConfigSha256 = reportModelConfigSha256,
                modelVersion = BuildConfig.VERSION_NAME,
                sourceCommit = BuildConfig.WALKSAFE_SOURCE_COMMIT,
                threshold = threshold,
                capturedAtMs = capturedAtMs,
                requestElapsedRealtimeMs = requestElapsedRealtimeMs,
                trigger = trigger,
                reporterUserId = reporterId,
                traceId = "${output.frameId}-${output.trackId}",
                deviceGateAllowsReports = gateState.reportCandidatesAllowed,
                depthSampleCount = output.validSampleCount,
                depthValidSampleRatio = output.validSampleRatio,
                detectionAgeMs = (nowMs - capturedAtMs).coerceAtLeast(0L),
                coordinateGateStatus = "pass",
                heading = latestHeadingDeg,
                apkSha256 = reportApkSha256,
                fallbackUsed = detectorModelFallbackUsed,
                loadedModelKey = detectorLoadedModelKey,
                modelLoadReason = detectorLoadReason,
            ),
        )
        return if (candidate == null) {
            "reportCandidate=blocked"
        } else {
            processReportCandidate(
                candidate = candidate,
                reportImage = reportImage,
                explicitRequest = explicitRequest,
                expectedWalkEpoch = expectedWalkEpoch,
                expectedReporterActorId = reporterId,
                capturedAtMs = capturedAtMs,
                explicitConfirmationContext = explicitConfirmationContext,
                explicitConfirmationRequestedAtElapsedRealtimeMs =
                    explicitConfirmationRequestedAtElapsedRealtimeMs,
            )
        }
    }

    private fun processReportCandidate(
        candidate: AndroidReportCandidate,
        reportImage: ByteArray?,
        explicitRequest: Boolean = false,
        expectedWalkEpoch: WalkRuntimeEpoch,
        expectedReporterActorId: String,
        capturedAtMs: Long,
        explicitConfirmationContext: ExplicitReportConfirmationContext?,
        explicitConfirmationRequestedAtElapsedRealtimeMs: Long?,
    ): String {
        if (!reportPermissionsAllowWork()) {
            return "reportCandidate=blocked:permission_unavailable"
        }
        if (!walkSessionLifecycle.isRuntimeEpochCurrent(expectedWalkEpoch)) {
            return "reportCandidate=blocked:walk_session_changed"
        }
        if (currentReporterUserId() != expectedReporterActorId) {
            return "reportCandidate=blocked:reporter_changed"
        }
        if (!walkSafetyOutputsAllowed()) {
            return "reportCandidate=blocked:environment_changed"
        }
        if (!reportPrivacyConsentSession.isGranted()) {
            return "reportCandidate=blocked:consent_confirmation_required"
        }
        val consentConfirmation =
            integratedConsentSession.currentConfirmationOrNull()
                ?: return "reportCandidate=blocked:consent_confirmation_required"
        if (!explicitRequest && !consentConfirmation.selections.automaticReporting) {
            return "reportCandidate=blocked:automatic_report_consent_required"
        }
        val imageJpeg = reportImage ?: return "reportCandidate=blocked:no_report_image"
        val automaticAttemptLease = if (explicitRequest) {
            null
        } else {
            val cooldownScope = automaticReportCooldownScopeOrNull(candidate.metadata)
                ?: return "reportCandidate=blocked:cooldown_scope_invalid"
            when (
                val admission = reportAttemptStore.acquire(
                    scope = cooldownScope,
                    nowMs = System.currentTimeMillis(),
                    bypassAutomaticCooldown = false,
                )
            ) {
                is AndroidReportAttemptResult.Allowed -> admission.lease
                is AndroidReportAttemptResult.Blocked ->
                    return "reportCandidate=blocked:" +
                        admission.reason.name.lowercase(Locale.US)
            }
        }
        val metadataUtf8 = candidate.metadata.toString().toByteArray(Charsets.UTF_8)
        if (explicitConfirmationContext != null) {
            val requestedAt = explicitConfirmationRequestedAtElapsedRealtimeMs
            if (requestedAt == null) {
                metadataUtf8.fill(0)
                return "reportCandidate=blocked:confirmation_clock_missing"
            }
            if (
                !explicitRequest ||
                explicitConfirmationContext.walkSessionId != expectedWalkEpoch.walkSessionId ||
                explicitConfirmationContext.recoveryGeneration !=
                expectedWalkEpoch.recoveryGeneration ||
                explicitConfirmationContext.reporterId != expectedReporterActorId ||
                explicitConfirmationContext.consentReceiptSha256 !=
                consentConfirmation.backendConsentReceiptSha256 ||
                explicitConfirmationContext.gatewaySessionGeneration !=
                GatewaySessionProcessCoordinator.snapshot().generation
            ) {
                metadataUtf8.fill(0)
                return "reportCandidate=blocked:confirmation_context_changed"
            }
            val frozen = try {
                ExplicitReportFrozenPayload.freeze(
                    context = explicitConfirmationContext,
                    capturedAtEpochMs = capturedAtMs,
                    metadataUtf8 = metadataUtf8,
                    imageJpeg = imageJpeg,
                )
            } finally {
                metadataUtf8.fill(0)
            } ?: return "reportCandidate=blocked:explicit_payload_freeze_failed"
            explicitReportConfirmationPolicy.stage(frozen, requestedAt)
            return "reportCandidate=awaiting:explicit_transfer_confirmation"
        }
        val priority = if (explicitRequest) {
            ReportQueuePriority.EXPLICIT
        } else {
            ReportQueuePriority.AUTOMATIC
        }
        val queued = try {
            reportQueueStore.enqueue(
                expectedReporterActorId = expectedReporterActorId,
                metadataUtf8 = metadataUtf8,
                imageJpeg = imageJpeg,
                priority = priority,
                walkSessionId = expectedWalkEpoch.walkSessionId,
                consentReceiptSha256 =
                    consentConfirmation.backendConsentReceiptSha256,
            )
        } finally {
            metadataUtf8.fill(0)
            automaticAttemptLease?.let(reportAttemptStore::release)
        }
        if (queued == null) {
            return "reportCandidate=queue_disabled_or_rejected"
        }
        if (explicitRequest) speakInteraction("신고 후보를 안전하게 저장했습니다.")
        return "reportCandidate=queued id=${queued.payload.reportId.take(12)}"
    }

    private fun requestExplicitReport(source: ExplicitReportRequestSource) {
        if (!ensureExplicitReportAuthorityPreconditions()) {
            invalidatePendingExplicitReport()
            return
        }
        val context = currentExplicitReportConfirmationContextOrNull()
        if (context == null) {
            invalidatePendingExplicitReport()
            latestReportCandidateStatus = "reportCandidate=blocked:gateway_authority_unavailable"
            updateNavigationStatus(latestReportCandidateStatus)
            speakInteraction("현재 계정의 테스트 서버 로그인 상태를 확인한 뒤 다시 신고해 주세요.")
            return
        }
        val nowElapsedRealtimeMs = SystemClock.elapsedRealtime()
        val confirmed = explicitReportConfirmationPolicy.consumeIfConfirmed(
            context = context,
            nowElapsedRealtimeMs = nowElapsedRealtimeMs,
        )
        if (confirmed != null) {
            explicitReportConfirmationTimeoutGeneration += 1L
            submitFrozenExplicitReportAfterConfirmation(confirmed)
            return
        }
        if (explicitReportConfirmationPolicy.isAwaitingDisclosure(context)) {
            latestReportCandidateStatus =
                "reportCandidate=awaiting:explicit_transfer_disclosure"
            updateNavigationStatus(latestReportCandidateStatus)
            return
        }
        if (!ensureExplicitReportCapturePreconditions()) {
            invalidatePendingExplicitReport()
            return
        }
        val status = prepareExplicitReportCandidateIfCurrent(
            source = source,
            nowMs = System.currentTimeMillis(),
            confirmationContext = context,
            requestedAtElapsedRealtimeMs = nowElapsedRealtimeMs,
        )
        latestReportCandidateStatus = status
        updateNavigationStatus(status)
        if (status == "reportCandidate=awaiting:explicit_transfer_confirmation") {
            beginExplicitReportConfirmationDisclosure(context, source)
        } else if (
            status == "reportCandidate=blocked:no_depth_object" ||
            status.contains("blocked:not_reportable_class")
        ) {
            speakInteraction("신고할 손상 점자블록이 없습니다.")
        }
    }

    private fun ensureExplicitReportAuthorityPreconditions(): Boolean {
        if (PRODUCTION_REPORT_QUEUE_CAPACITY_PROFILE == null) {
            val message = "현재 앱 빌드에서는 신고 저장 기능을 사용할 수 없습니다."
            latestReportCandidateStatus = "reportCandidate=blocked:queue_disabled"
            updateNavigationStatus(latestReportCandidateStatus)
            speakInteraction(message)
            return false
        }
        if (!reportPermissionsAllowWork()) {
            latestReportCandidateStatus = "reportCandidate=blocked:permission_unavailable"
            updateNavigationStatus(latestReportCandidateStatus)
            speakInteraction("카메라와 정확한 위치 권한을 확인한 뒤 다시 신고해 주세요.")
            return false
        }
        if (!requireReporterUserId("login_required_explicit_report")) return false
        if (
            !reportPrivacyConsentSession.isGranted() ||
            integratedConsentSession.currentConfirmationOrNull() == null
        ) {
            latestReportCandidateStatus =
                "reportCandidate=blocked:consent_confirmation_required trigger=voice"
            updateNavigationStatus(latestReportCandidateStatus)
            speakInteraction("현재 계정의 신고 처리 확인을 서버에서 확인해야 직접 신고할 수 있습니다.")
            return false
        }
        if (currentExplicitReportConfirmationContextOrNull() == null) {
            latestReportCandidateStatus = "reportCandidate=blocked:gateway_authority_unavailable"
            updateNavigationStatus(latestReportCandidateStatus)
            speakInteraction("현재 계정의 테스트 서버 로그인 상태를 확인한 뒤 다시 신고해 주세요.")
            return false
        }
        return true
    }

    private fun ensureExplicitReportCapturePreconditions(): Boolean {
        if (!currentRuntimeMetricOutputAllowsWork()) {
            clearExplicitReportFrameState("runtime_metric_unavailable")
            updateNavigationStatus(latestReportCandidateStatus)
            return false
        }
        if (freshTrustedLocationOrNull() == null) {
            ensureNavigationPermissionForReport()
            startNavigationServicesIfNeeded()
            latestReportCandidateStatus = "reportCandidate=blocked:gps_missing trigger=voice"
            updateNavigationStatus(latestReportCandidateStatus)
            speakInteraction("위치 정보가 필요합니다.")
            return false
        }
        return true
    }

    private fun currentExplicitReportConfirmationContextOrNull():
        ExplicitReportConfirmationContext? {
        val epoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return null
        val reporter = currentReporterUserId() ?: return null
        val confirmation = integratedConsentSession.currentConfirmationOrNull() ?: return null
        if (!reportPrivacyConsentSession.isGranted()) return null
        val gateway = GatewaySessionProcessCoordinator.snapshot()
        val session = gateway.session ?: return null
        if (
            gateway.storageBlocked ||
            gateway.deletionRecoveryOnly ||
            session.sessionScope != GatewaySessionScope.GENERAL ||
            !session.isUsableFor(reporter) ||
            approvedReportQueueGatewayOriginOrNull(session.gatewayBaseUrl) !=
            session.gatewayBaseUrl
        ) return null
        return ExplicitReportConfirmationContext(
            walkSessionId = epoch.walkSessionId,
            recoveryGeneration = epoch.recoveryGeneration,
            reporterId = reporter,
            consentReceiptSha256 = confirmation.backendConsentReceiptSha256,
            gatewaySessionGeneration = gateway.generation,
        )
    }

    private fun submitFrozenExplicitReportAfterConfirmation(
        confirmed: ConfirmedExplicitReportPayload,
    ) {
        val status = try {
            if (
                !ensureExplicitReportAuthorityPreconditions() ||
                !walkSafetyOutputsAllowed() ||
                currentExplicitReportConfirmationContextOrNull() != confirmed.context
            ) {
                "reportCandidate=blocked:confirmation_context_changed"
            } else {
                confirmed.useExactBytes { metadataUtf8, imageJpeg ->
                    reportQueueStore.enqueue(
                        expectedReporterActorId = confirmed.context.reporterId,
                        metadataUtf8 = metadataUtf8,
                        imageJpeg = imageJpeg,
                        priority = ReportQueuePriority.EXPLICIT,
                        walkSessionId = confirmed.context.walkSessionId,
                        consentReceiptSha256 = confirmed.context.consentReceiptSha256,
                    )?.let { queued ->
                        "reportCandidate=queued id=${queued.payload.reportId.take(12)}"
                    } ?: "reportCandidate=queue_disabled_or_rejected"
                }
            }
        } finally {
            confirmed.close()
        }
        renderExplicitReportConfirmationIdle()
        latestReportCandidateStatus = status
        updateNavigationStatus(status)
        if (status.startsWith("reportCandidate=queued")) {
            speakInteraction("방금 확인한 신고 후보를 안전하게 저장했습니다.")
        } else if (status == "reportCandidate=blocked:confirmation_context_changed") {
            speakInteraction("신고 확인 중 상태가 바뀌어 저장하지 않았습니다. 다시 신고해 주세요.")
        }
    }

    private fun prepareExplicitReportCandidateIfCurrent(
        source: ExplicitReportRequestSource,
        nowMs: Long,
        confirmationContext: ExplicitReportConfirmationContext,
        requestedAtElapsedRealtimeMs: Long,
    ): String =
        synchronized(frameStateLock) frameLock@ {
            synchronized(runtimeMetricStateLock) runtimeLock@ {
                if (!currentRuntimeMetricOutputAllowsWork()) {
                    return@runtimeLock "reportCandidate=blocked:runtime_metric_unavailable"
                }
                val output = latestExplicitReportOutput
                prepareReportCandidate(
                    reportOutput = output,
                    gateState = latestExplicitReportGateState ?: buildDeviceGateState(
                        bestOutput = output,
                        staleReason = null,
                        expectedRuntimeMetricGeneration = arSessionGeneration,
                    ),
                    reportImage = latestExplicitReportImage,
                    nowMs = nowMs,
                    capturedAtMs = latestExplicitReportCapturedAtMs.takeIf { it > 0L } ?: nowMs,
                    trigger = source.reportTrigger,
                    explicitRequest = true,
                    explicitConfirmationContext = confirmationContext,
                    explicitConfirmationRequestedAtElapsedRealtimeMs =
                        requestedAtElapsedRealtimeMs,
                )
            }
        }

    private fun beginExplicitReportConfirmationDisclosure(
        context: ExplicitReportConfirmationContext,
        source: ExplicitReportRequestSource,
    ) {
        renderExplicitReportConfirmationDisclosure(armed = false)
        val generation = ++explicitReportConfirmationTimeoutGeneration
        scheduleExplicitReportDisclosureTimeout(generation)
        val delivered = {
            runOnUiThread {
                if (
                    generation != explicitReportConfirmationTimeoutGeneration ||
                    currentExplicitReportConfirmationContextOrNull() != context ||
                    !explicitReportConfirmationPolicy.arm(
                        context,
                        SystemClock.elapsedRealtime(),
                    )
                ) {
                    return@runOnUiThread
                }
                renderExplicitReportConfirmationDisclosure(armed = true)
                latestReportCandidateStatus =
                    "reportCandidate=awaiting:explicit_transfer_confirmation"
                updateNavigationStatus(latestReportCandidateStatus)
                scheduleExplicitReportConfirmationTimeout()
            }
        }
        val failed = {
            runOnUiThread {
                if (
                    generation == explicitReportConfirmationTimeoutGeneration &&
                    explicitReportConfirmationPolicy.invalidateIfContext(context)
                ) {
                    explicitReportConfirmationTimeoutGeneration += 1L
                    latestReportCandidateStatus =
                        "reportCandidate=blocked:confirmation_disclosure_failed"
                    updateNavigationStatus(latestReportCandidateStatus)
                    renderExplicitReportConfirmationIdle(
                        "신고 전송 안내를 전달하지 못해 저장하지 않았습니다. 다시 신고해 주세요.",
                    )
                }
            }
        }
        val accepted = if (source == ExplicitReportRequestSource.ON_SCREEN) {
            deliverExplicitReportDisclosureAfterDraw(delivered)
        } else {
            ensureFeedbackActuator().speakExplicitConfirmation(
                message = EXPLICIT_REPORT_CONFIRMATION_SUMMARY_KO,
                onCompleted = delivered,
                onFailed = failed,
            ) == NavigationSpeechDispatchResult.ACCEPTED
        }
        if (!accepted) failed()
    }

    private fun deliverExplicitReportDisclosureAfterDraw(
        onDelivered: () -> Unit,
    ): Boolean {
        if (
            !::explicitReportConfirmationText.isInitialized ||
            !explicitReportConfirmationText.isAttachedToWindow
        ) return false
        val observer = explicitReportConfirmationText.viewTreeObserver
        if (!observer.isAlive) return false
        var deliveryPosted = false
        lateinit var listener: android.view.ViewTreeObserver.OnDrawListener
        listener = android.view.ViewTreeObserver.OnDrawListener {
            if (deliveryPosted) return@OnDrawListener
            deliveryPosted = true
            explicitReportConfirmationText.post {
                if (observer.isAlive) observer.removeOnDrawListener(listener)
                onDelivered()
            }
        }
        observer.addOnDrawListener(listener)
        explicitReportConfirmationText.invalidate()
        return true
    }

    private fun scheduleExplicitReportDisclosureTimeout(generation: Long) {
        reportCleanupCallbackHandler.postDelayed(
            {
                if (
                    generation == explicitReportConfirmationTimeoutGeneration &&
                    explicitReportConfirmationPolicy.invalidateExpired(
                        SystemClock.elapsedRealtime(),
                    )
                ) {
                    explicitReportConfirmationTimeoutGeneration += 1L
                    latestReportCandidateStatus =
                        "reportCandidate=blocked:confirmation_disclosure_expired"
                    updateNavigationStatus(latestReportCandidateStatus)
                    renderExplicitReportConfirmationIdle(
                        "신고 전송 안내 시간이 지나 저장하지 않았습니다. 다시 신고해 주세요.",
                    )
                }
            },
            EXPLICIT_REPORT_DISCLOSURE_VALIDITY_MS + 1L,
        )
    }

    private fun scheduleExplicitReportConfirmationTimeout() {
        val generation = ++explicitReportConfirmationTimeoutGeneration
        reportCleanupCallbackHandler.postDelayed(
            {
                if (
                    generation == explicitReportConfirmationTimeoutGeneration &&
                    explicitReportConfirmationPolicy.invalidateExpired(
                        SystemClock.elapsedRealtime(),
                    )
                ) {
                    explicitReportConfirmationTimeoutGeneration += 1L
                    latestReportCandidateStatus =
                        "reportCandidate=blocked:confirmation_expired"
                    updateNavigationStatus(latestReportCandidateStatus)
                    renderExplicitReportConfirmationIdle(
                        "30초 확인 시간이 지나 저장하지 않았습니다. 다시 신고해 주세요.",
                    )
                }
            },
            EXPLICIT_REPORT_CONFIRMATION_VALIDITY_MS + 1L,
        )
    }

    private fun invalidatePendingExplicitReport() {
        explicitReportConfirmationTimeoutGeneration += 1L
        explicitReportConfirmationPolicy.invalidate()
        renderExplicitReportConfirmationIdle()
    }

    private fun renderExplicitReportConfirmationDisclosure(armed: Boolean) {
        if (!::explicitReportButton.isInitialized || !::explicitReportConfirmationText.isInitialized) {
            return
        }
        if (Looper.myLooper() != Looper.getMainLooper()) {
            runOnUiThread { renderExplicitReportConfirmationDisclosure(armed) }
            return
        }
        val action = if (armed) {
            "30초 안에 아래 ‘방금 고정한 신고 보내기’를 누르면 이 건만 저장합니다."
        } else {
            "음성 또는 접근성 안내가 끝나면 별도 보내기 동작이 열립니다."
        }
        val disclosure = "$REPORT_EXPLICIT_CONFIRMATION_DISCLOSURE_KO $action"
        explicitReportConfirmationText.visibility = View.VISIBLE
        explicitReportConfirmationText.text = disclosure
        explicitReportConfirmationText.contentDescription = disclosure
        explicitReportButton.isEnabled = armed
        explicitReportButton.text = if (armed) {
            "방금 고정한 신고 보내기"
        } else {
            "신고 전송 안내 확인 중"
        }
        explicitReportButton.contentDescription = if (armed) {
            "$EXPLICIT_REPORT_CONFIRMATION_SUMMARY_KO 방금 고정한 신고 보내기"
        } else {
            "$EXPLICIT_REPORT_CONFIRMATION_SUMMARY_KO 안내가 끝날 때까지 기다려 주세요."
        }
        refreshHomeCards()
    }

    private fun renderExplicitReportConfirmationIdle(message: String? = null) {
        if (!::explicitReportButton.isInitialized || !::explicitReportConfirmationText.isInitialized) {
            return
        }
        if (Looper.myLooper() != Looper.getMainLooper()) {
            runOnUiThread { renderExplicitReportConfirmationIdle(message) }
            return
        }
        val queueAvailable = PRODUCTION_REPORT_QUEUE_CAPACITY_PROFILE != null
        explicitReportConfirmationText.visibility = if (message == null) View.GONE else View.VISIBLE
        explicitReportConfirmationText.text = message.orEmpty()
        explicitReportConfirmationText.contentDescription = message.orEmpty()
        explicitReportButton.text = if (queueAvailable) {
            "손상 점자블록 직접 신고"
        } else {
            "손상 점자블록 신고 저장 기능 준비 중"
        }
        explicitReportButton.contentDescription = if (queueAvailable) {
            "손상 점자블록 직접 신고. 누르면 신고 사진과 정확한 위치 전송 내용을 확인합니다."
        } else {
            "현재 앱 빌드에서는 손상 점자블록 신고 저장 기능을 사용할 수 없습니다."
        }
        explicitReportButton.isEnabled = queueAvailable
        refreshHomeCards()
    }

    private fun ensureVoicePermissionThenListen() {
        val snapshot = walkSessionLifecycle.snapshot()
        if (
            !snapshot.isForeground ||
            (snapshot.state !in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED) &&
                !(nativeUiPage.isVoiceInteractionPage() && homeVoiceCommandAvailable()))
        ) {
            updateGatewayVoiceStatus("화면 음성 명령은 초기 설정과 기기 점검을 완료한 뒤 앱 화면에서 사용할 수 있습니다.")
            return
        }
        if (!hasRecordAudioPermission()) {
            updateNavigationStatus("voice_command=microphone_permission_missing feature_limited")
            showPermissionDenialPanel(
                missingPermissions = setOf(ObservedPermission.MICROPHONE),
                reason = "voice_command_microphone_missing",
            )
            updateVoiceCommandButton(active = false)
            return
        }
        if (pendingVoiceDestinationQuery != null) {
            updateGatewayVoiceStatus("목적지 검색이 끝나면 후보 안내를 듣고 말씀해 주세요.")
            return
        }
        val dialogState = currentVoiceDestinationDialogState()
        if (dialogState != null) {
            speakHomeDestinationVoicePrompt(dialogState, "다시 듣기 또는 해당 번호를 말해주세요.")
            return
        }
        startVoiceCommandRecognition()
    }

    /** Explicit foreground button capture only; this is not a 길라잡이 wake-word listener. */
    private fun toggleGatewayVoiceCapture() {
        if (gatewayVoiceRecorder?.isRecording == true) {
            stopGatewayVoiceCapture()
        } else {
            startGatewayVoiceCapture()
        }
    }

    private fun startGatewayVoiceCapture(): Boolean {
        if (activeGatewaySpeechInteraction != null || voiceRecognitionActive) return false
        if (!isGatewayNetworkAllowed(reason = "server_speech")) return false
        val (session, sessionGeneration) = currentGatewaySpeechSessionOrNull() ?: return false
        val networkTicket = gatewaySpeechNetworkGate.capture() ?: return false
        val walk = walkSessionLifecycle.snapshot()
        if (
            !walk.isForeground ||
            walk.state !in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED)
        ) return false
        if (!feedbackPolicy.canSpeakNavigation(SystemClock.elapsedRealtime())) return false
        if (isHandsFreeVoiceRecognitionBlocked() ||
            feedbackActuator?.prepareForSpeechRecognition() == false
        ) {
            updateGatewayVoiceStatus("음성 안내가 끝난 뒤 녹음 버튼을 다시 눌러 주세요.")
            return false
        }
        stopHandsFreeVoiceService()
        val interactionGeneration = ++gatewaySpeechInteractionGeneration
        val active = ActiveGatewaySpeechInteraction(
            fence = GatewaySpeechCallbackFence(
                actorId = session.actorId,
                sessionGeneration = sessionGeneration,
                sessionInstanceId = session.lease.instanceId,
                interactionGeneration = interactionGeneration,
            ),
            session = session,
            networkTicket = networkTicket,
            expectedWalkEpoch = walk.epoch,
            expectedNavigationDecisionToken = routeNavigator.pendingDecisionToken(),
        )
        val recorder = ForegroundAacRecorder(cacheDir) {
            runOnUiThread { stopGatewayVoiceCapture(interactionGeneration) }
        }
        activeGatewaySpeechInteraction = active
        gatewayVoiceRecorder = recorder
        if (!recorder.start()) {
            activeGatewaySpeechInteraction = null
            gatewayVoiceRecorder = null
            gatewaySpeechInteractionGeneration += 1L
            updateGatewayVoiceStatus("녹음을 시작하지 못했습니다.")
            speakInteraction("음성 녹음을 시작하지 못했습니다.")
            updateVoiceCommandButton(active = false)
            scheduleHandsFreeVoiceRestart()
            return false
        }
        runCatching { ensureFeedbackActuator().playVoiceListeningStartVibration() }
        voiceRecognitionActive = true
        voiceRecognitionPurpose = VoiceRecognitionPurpose.COMMAND
        updateGatewayVoiceStatus("녹음 중입니다. 버튼을 다시 눌러 전송하세요.")
        updateVoiceCommandButton(active = true)
        updateNavigationStatus("voice=gateway_recording")
        return true
    }

    private fun stopGatewayVoiceCapture(expectedInteractionGeneration: Long? = null) {
        val active = activeGatewaySpeechInteraction ?: return
        if (
            expectedInteractionGeneration != null &&
            active.fence.interactionGeneration != expectedInteractionGeneration
        ) return
        val recorder = gatewayVoiceRecorder ?: return
        gatewayVoiceRecorder = null
        voiceRecognitionActive = false
        val audioFile = recorder.stop()
        runCatching { ensureFeedbackActuator().playVoiceListeningEndVibration() }
        if (audioFile == null) {
            finishGatewaySpeechInteraction(active)
            updateGatewayVoiceStatus("녹음이 너무 짧거나 올바르지 않습니다.")
            speakInteraction("음성을 녹음하지 못했습니다. 버튼을 눌러 다시 말씀해 주세요.")
            return
        }
        updateGatewayVoiceStatus("음성을 처리하고 있습니다.")
        updateVoiceCommandButton(active = false)
        submitGatewayVoiceRecording(active, audioFile)
    }

    private fun submitGatewayVoiceRecording(
        active: ActiveGatewaySpeechInteraction,
        audioFile: File,
    ) {
        if (!isGatewaySpeechInteractionCurrent(active)) {
            audioFile.delete()
            finishGatewaySpeechInteraction(active)
            return
        }
        val requestId = UUID.randomUUID().toString()
        val call = runCatching {
            gatewaySpeechNetworkGate.bind(
                active.networkTicket,
                gatewaySpeechClient.transcribeCall(active.session, audioFile, requestId),
            )
        }.getOrElse {
            audioFile.delete()
            finishGatewaySpeechInteraction(active)
            speakInteraction("서버 음성 인식을 시작하지 못했습니다. 잠시 뒤 다시 시도해 주세요.")
            return
        }
        gatewayVoiceUploadFile = audioFile
        gatewaySpeechCall = call
        try {
            gatewaySpeechExecutor.execute {
                val result = runCatching { call.execute() }
                audioFile.delete()
                runOnUiThread {
                    if (gatewayVoiceUploadFile === audioFile) gatewayVoiceUploadFile = null
                    if (gatewaySpeechCall === call) gatewaySpeechCall = null
                    if (!isGatewaySpeechInteractionCurrent(active)) return@runOnUiThread
                    result.onSuccess { transcript ->
                        handleGatewaySpeechTranscript(active, transcript)
                    }.onFailure {
                        if (call.isCancelled()) return@onFailure
                        finishGatewaySpeechInteraction(active)
                        updateGatewayVoiceStatus("서버 음성 인식을 사용할 수 없습니다.")
                        speakInteraction("서버 음성 인식을 사용할 수 없습니다. 잠시 뒤 다시 시도해 주세요.")
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            call.cancel()
            audioFile.delete()
            if (gatewayVoiceUploadFile === audioFile) gatewayVoiceUploadFile = null
            finishGatewaySpeechInteraction(active)
        }
    }

    private fun handleGatewaySpeechTranscript(
        active: ActiveGatewaySpeechInteraction,
        speechTranscript: GatewaySpeechTranscript,
    ) {
        if (!speechTranscript.acoustic.executionAllowed) {
            updateGatewayVoiceStatus("음성 품질이 낮아 명령을 실행하지 않았습니다.")
            speakGatewayInteractionOrLocalFallback(
                "음성을 확실히 확인하지 못했습니다. 버튼을 눌러 다시 말씀해 주세요.",
                active,
            )
            return
        }
        finishGatewaySpeechInteraction(active)
        updateGatewayVoiceStatus("음성 명령을 로컬 안전 규칙으로 확인했습니다.")
        handleVoiceCommandPhrases(
            phrases = listOf(speechTranscript.transcript),
            confidenceScores = floatArrayOf(speechTranscript.acoustic.confidence.toFloat()),
            expectedNavigationDecisionToken = active.expectedNavigationDecisionToken,
            includeRecognizedTextInStatus = false,
            redactedRecognitionSource = "gateway_stt",
        )
    }

    private fun speakGatewayInteractionOrLocalFallback(
        message: String,
        active: ActiveGatewaySpeechInteraction,
    ) {
        if (!isGatewaySpeechInteractionCurrent(active) || isScreenReaderActive()) {
            finishGatewaySpeechInteraction(active)
            speakInteraction(message)
            return
        }
        val requestId = UUID.randomUUID().toString()
        val call = runCatching {
            gatewaySpeechNetworkGate.bind(
                active.networkTicket,
                gatewaySpeechClient.synthesizeCall(active.session, message, requestId, cacheDir),
            )
        }.getOrElse {
            finishGatewaySpeechInteraction(active)
            speakInteraction(message)
            return
        }
        gatewaySpeechCall = call
        updateGatewayVoiceStatus("음성 안내를 준비하고 있습니다.")
        try {
            gatewaySpeechExecutor.execute {
                val result = runCatching { call.execute() }
                runOnUiThread {
                    if (gatewaySpeechCall === call) gatewaySpeechCall = null
                    val audio = result.getOrNull()
                    if (!isGatewaySpeechInteractionCurrent(active)) {
                        audio?.temporaryFile?.delete()
                        return@runOnUiThread
                    }
                    if (audio == null) {
                        if (call.isCancelled()) return@runOnUiThread
                        finishGatewaySpeechInteraction(active)
                        speakInteraction(message)
                        return@runOnUiThread
                    }
                    updateGatewayVoiceStatus("서버 음성 안내를 재생하고 있습니다.")
                    val player = TemporaryGatewayWavPlayer()
                    gatewaySpeechPlayer = player
                    val started = player.play(
                        temporaryFile = audio.temporaryFile,
                        onCompleted = { finishGatewaySpeechInteraction(active) },
                        onFailed = {
                            if (isGatewaySpeechInteractionCurrent(active)) {
                                finishGatewaySpeechInteraction(active)
                                speakInteraction(message)
                            }
                        },
                    )
                    if (!started && isGatewaySpeechInteractionCurrent(active)) {
                        finishGatewaySpeechInteraction(active)
                        speakInteraction(message)
                    }
                }
            }
        } catch (_: RejectedExecutionException) {
            call.cancel()
            finishGatewaySpeechInteraction(active)
            speakInteraction(message)
        }
    }

    private fun currentGatewaySpeechSessionOrNull(): Pair<GatewayFieldSession, Long>? {
        if (
            !isGatewayFeatureNetworkAllowed() ||
            !isActivityForeground ||
            !::firstRunOnboardingSnapshot.isInitialized ||
            firstRunOnboardingSnapshot.flow != FirstRunOnboardingFlow.EMAIL_ACCOUNT_V4 ||
            !firstRunOnboardingSnapshot.isComplete ||
            !postLoginDeviceCheckPassesFeatureGate()
        ) return null
        val process = GatewaySessionProcessCoordinator.snapshot()
        val session = process.session?.takeUnless { process.deletionRecoveryOnly } ?: return null
        if (
            process.storageBlocked ||
            reporterUserId != session.actorId ||
            !session.isUsableFor(reporterUserId)
        ) return null
        return session to process.generation
    }

    private fun isGatewaySpeechInteractionCurrent(
        active: ActiveGatewaySpeechInteraction,
    ): Boolean {
        if (activeGatewaySpeechInteraction !== active) return false
        if (!gatewaySpeechNetworkGate.isCurrent(active.networkTicket)) return false
        val process = GatewaySessionProcessCoordinator.snapshot()
        return walkSessionLifecycle.snapshot().let { walk ->
            walk.epoch == active.expectedWalkEpoch &&
                walk.state in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED) &&
                isGatewaySpeechCallbackCurrent(
                    expected = active.fence,
                    currentActorId = process.session?.actorId,
                    currentSessionGeneration = process.generation,
                    currentSessionInstanceId = process.session?.lease?.instanceId,
                    currentInteractionGeneration = gatewaySpeechInteractionGeneration,
                    foreground = isActivityForeground && walk.isForeground,
                    featureGatePassed = currentGatewaySpeechSessionOrNull() != null,
                )
        }
    }

    private fun finishGatewaySpeechInteraction(active: ActiveGatewaySpeechInteraction) {
        if (activeGatewaySpeechInteraction !== active) return
        activeGatewaySpeechInteraction = null
        gatewayVoiceRecorder = null
        gatewayVoiceUploadFile?.delete()
        gatewayVoiceUploadFile = null
        gatewaySpeechCall = null
        gatewaySpeechPlayer = null
        gatewaySpeechInteractionGeneration += 1L
        voiceRecognitionActive = false
        updateVoiceCommandButton(active = false)
        scheduleHandsFreeVoiceRestart()
    }

    private fun cancelGatewaySpeechInteraction(reason: String) {
        if (
            activeGatewaySpeechInteraction == null &&
            gatewayVoiceRecorder == null &&
            gatewayVoiceUploadFile == null &&
            gatewaySpeechCall == null &&
            gatewaySpeechPlayer == null
        ) return
        gatewaySpeechInteractionGeneration += 1L
        val recorder = gatewayVoiceRecorder
        val wasRecording = recorder?.isRecording == true
        gatewayVoiceRecorder = null
        recorder?.cancel()
        if (wasRecording) {
            runCatching { ensureFeedbackActuator().playVoiceListeningEndVibration() }
        }
        gatewayVoiceUploadFile?.delete()
        gatewayVoiceUploadFile = null
        gatewaySpeechCall?.cancel()
        gatewaySpeechCall = null
        gatewaySpeechPlayer?.cancel()
        gatewaySpeechPlayer = null
        activeGatewaySpeechInteraction = null
        voiceRecognitionActive = false
        updateGatewayVoiceStatus("서버 음성 작업이 취소되었습니다.")
        updateNavigationStatus("voice=gateway_cancelled reason=$reason")
        updateVoiceCommandButton(active = false)
        scheduleHandsFreeVoiceRestart()
    }

    private fun updateGatewayVoiceStatus(message: String) {
        if (::gatewayVoiceStatusText.isInitialized) {
            gatewayVoiceStatusText.text = message
            gatewayVoiceStatusText.contentDescription = message
        }
        if (::walkSafetyVoiceStatusText.isInitialized) {
            walkSafetyVoiceStatusText.text = message
            walkSafetyVoiceStatusText.contentDescription = message
        }
    }

    private fun startVoiceCommandRecognition(
        purpose: VoiceRecognitionPurpose = VoiceRecognitionPurpose.COMMAND,
        expectedGatewayWalkOperationId: String? = null,
    ): Boolean {
        handsFreeVoiceOwnsCommandPage = false
        cancelForegroundHomeWakeAcknowledgement()
        cancelForegroundHomeWakeListening()
        val promptCompletedForThisRequest = voiceCommandPromptReadyGeneration == voiceRecognitionGeneration
        if (!hasRecordAudioPermission()) {
            updateNavigationStatus("voice_command=microphone_permission_missing")
            return false
        }
        if (
            !OneShotVoiceInputPolicy.isAvailable(
                contextAvailable = true,
                microphoneGranted = hasRecordAudioPermission(),
                capabilityDecision = startupCapabilityDecision,
            )
        ) {
            updateNavigationStatus("voice_command=microphone_limited")
            return false
        }
        val sessionSnapshot = walkSessionLifecycle.snapshot()
        val expectedWalkEpoch = sessionSnapshot.epoch
        val expectedResumeToken = if (purpose == VoiceRecognitionPurpose.WALK_SESSION_RESUME) {
            walkSessionResumeConfirmationToken
        } else {
            null
        }
        val expectedNavigationDecisionToken = if (purpose == VoiceRecognitionPurpose.COMMAND) {
            routeNavigator.pendingDecisionToken()
        } else {
            null
        }
        val mayListen = when (purpose) {
            VoiceRecognitionPurpose.COMMAND -> {
                sessionSnapshot.isForeground &&
                    sessionSnapshot.epoch == expectedWalkEpoch &&
                    when (sessionSnapshot.state) {
                        WalkSessionState.ACTIVE -> requireStartupCapabilityConfirmation()
                        WalkSessionState.PAUSED -> voiceResumeConfirmationAvailable()
                        WalkSessionState.READY, WalkSessionState.SAFE_STOP, WalkSessionState.ENDED ->
                            nativeUiPage.isVoiceInteractionPage() && homeVoiceCommandAvailable()
                        else -> false
                    }
            }
            VoiceRecognitionPurpose.WALK_SESSION_RESUME -> {
                sessionSnapshot.state == WalkSessionState.PAUSED &&
                    sessionSnapshot.recoveryStage ==
                    WalkSessionRecoveryStage.AWAITING_RESUME_CONFIRMATION &&
                    sessionSnapshot.isForeground &&
                    walkSessionResumePromptPending &&
                    expectedResumeToken != null &&
                    sessionSnapshot.confirmationToken == expectedResumeToken &&
                    isStartupCapabilityConfirmed()
            }
            VoiceRecognitionPurpose.WALK_SESSION_TAKEOVER -> {
                sessionSnapshot.state == WalkSessionState.READY &&
                    sessionSnapshot.isForeground &&
                    gatewayWalkTakeoverPromptPending &&
                    expectedGatewayWalkOperationId != null &&
                    gatewayWalkTakeoverPromptOperationId ==
                    expectedGatewayWalkOperationId &&
                    gatewayWalkStartConfirmationToken ==
                    sessionSnapshot.confirmationToken &&
                    gatewayWalkAuthorityController.currentConflictOrNull(
                        expectedWalkEpoch,
                    ) != null
            }
        }
        if (!mayListen) return false
        if (voiceRecognitionActive || voiceCommandPromptPending) return false
        if (isHandsFreeVoiceRecognitionBlocked() ||
            !feedbackPolicy.canSpeakNavigation(SystemClock.elapsedRealtime()) ||
            feedbackActuator?.prepareForSpeechRecognition() == false
        ) {
            return deferVoiceRecognitionUntilOutputIdle(purpose, expectedGatewayWalkOperationId)
        }
        clearDeferredVoiceRecognitionStart(notifyFailure = false)
        voiceCommandPromptReadyGeneration = null
        fun unavailable(detail: String, permanentlyLimit: Boolean): Boolean {
            updateNavigationStatus("voice=recognizer_unavailable")
            handleOneShotSpeechRecognitionFailure(detail, permanentlyLimit)
            return false
        }
        val preferPlatform = purpose == VoiceRecognitionPurpose.COMMAND &&
            nativeHomeFeatureContextAvailable()
        if (handsFreeVoiceModelDirectory == null) prepareHandsFreeVoiceModel()
        if (handsFreeVoiceModelDirectory == null && !preferPlatform) {
            updateGatewayVoiceStatus(
                if (handsFreeVoiceModelPreparationFailed) "음성 모델을 준비하지 못했습니다. 다시 눌러 재시도하세요."
                else "음성 모델을 준비하고 있습니다. 준비가 끝나면 음성 명령을 다시 눌러 주세요.",
            )
            updateVoiceCommandButton(active = false)
            speakInteraction(
                if (handsFreeVoiceModelPreparationFailed) "음성 모델 준비에 실패했습니다. 다시 시도해 주세요."
                else "음성 모델을 준비하고 있습니다. 잠시 뒤 다시 눌러 주세요.",
            )
            return false
        }
        oneShotSpeechRecognitionLimited = false
        if (purpose == VoiceRecognitionPurpose.COMMAND && !promptCompletedForThisRequest) {
            return prepareOneShotVoiceCommandPrompt()
        }
        stopHandsFreeVoiceService()
        val generation = ++voiceRecognitionGeneration
        val recognizer = speechRecognizer ?: runCatching {
            PreferredOfflineSpeechRecognizer(this) { handsFreeVoiceModelDirectory }
        }.getOrElse {
            updateNavigationStatus("voice=on_device_recognizer_creation_failed")
            return unavailable(
                "기기 내 음성 인식기를 만들 수 없습니다.",
                permanentlyLimit = false,
            )
        }.also {
            speechRecognizer = it
        }
        voiceRecognitionPurpose = purpose
        recognizer.setRecognitionListener(
            buildVoiceCommandRecognitionListener(
                generation = generation,
                purpose = purpose,
                expectedWalkEpoch = expectedWalkEpoch,
                expectedResumeToken = expectedResumeToken,
                expectedGatewayWalkOperationId = expectedGatewayWalkOperationId,
                expectedNavigationDecisionToken = expectedNavigationDecisionToken,
            ),
        )
        voiceRecognitionActive = true
        updateVoiceCommandButton(active = true)
        updateNavigationStatus(
            when (purpose) {
                VoiceRecognitionPurpose.COMMAND -> "voice=listening command"
                VoiceRecognitionPurpose.WALK_SESSION_RESUME ->
                    "voice=listening walk_session_resume"
                VoiceRecognitionPurpose.WALK_SESSION_TAKEOVER ->
                    "voice=listening walk_session_takeover"
            },
        )
        val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
            putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
            putExtra(RecognizerIntent.EXTRA_LANGUAGE, Locale.KOREAN.toLanguageTag())
            putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS, false)
            putExtra(RecognizerIntent.EXTRA_MAX_RESULTS, 3)
        }
        return runCatching {
            recognizer.startListening(
                intent,
                preferPlatform = preferPlatform,
                isRequestCurrent = {
                    isVoiceRecognitionLeaseCurrent(
                        generation,
                        purpose,
                        expectedWalkEpoch,
                        expectedResumeToken,
                        expectedGatewayWalkOperationId,
                    )
                },
            )
            true
        }.getOrElse {
            unavailable(
                "기기 내 음성 인식을 시작할 수 없습니다.",
                permanentlyLimit = false,
            )
        }
    }

    private fun cancelDeferredVoiceRecognitionStart() {
        clearDeferredVoiceRecognitionStart(notifyFailure = true)
    }

    private fun clearDeferredVoiceRecognitionStart(notifyFailure: Boolean) {
        val pending = deferredVoiceRecognitionStart ?: return
        val failure = deferredVoiceRecognitionFailure
        deferredVoiceRecognitionStart = null
        deferredVoiceRecognitionFailure = null
        reportCleanupCallbackHandler.removeCallbacks(pending)
        if (notifyFailure) failure?.invoke()
        updateVoiceCommandButton(active = voiceRecognitionActive)
    }

    private fun deferVoiceRecognitionUntilOutputIdle(
        purpose: VoiceRecognitionPurpose,
        expectedGatewayWalkOperationId: String?,
    ): Boolean {
        if (deferredVoiceRecognitionStart != null) return true
        stopHandsFreeVoiceService()
        val generation = voiceRecognitionGeneration
        val responseGeneration = commandSpeechResponseGeneration
        val lifecycleGeneration = feedbackLifecycleGeneration
        val epoch = walkSessionLifecycle.snapshot().epoch
        val actor = reporterUserId
        val sessionGeneration = GatewaySessionProcessCoordinator.snapshot().generation
        val page = nativeUiPage
        val routeGeneration = routeRequestGeneration
        val deadline = SystemClock.elapsedRealtime() + DEFERRED_VOICE_INPUT_MAX_WAIT_MS
        val resumeToken = walkSessionResumeConfirmationToken
        val inputNotStarted: () -> Unit = {
            if (reporterUserId == actor &&
                GatewaySessionProcessCoordinator.snapshot().generation == sessionGeneration &&
                walkSessionLifecycle.snapshot().epoch == epoch
            ) {
                // Output/input generations fence execution; confirmation tokens own cleanup.
                // A newer status message must not leave the old confirmation permanently pending.
                if (voiceRecognitionGeneration == generation &&
                    commandSpeechResponseGeneration == responseGeneration
                ) voiceCommandPromptReadyGeneration = null
                when (purpose) {
                    VoiceRecognitionPurpose.COMMAND -> {
                        if (voiceRecognitionGeneration == generation &&
                            commandSpeechResponseGeneration == responseGeneration
                        ) clearVoiceEndConfirmation()
                    }
                    VoiceRecognitionPurpose.WALK_SESSION_RESUME -> {
                        if (resumeToken != null && walkSessionResumeConfirmationToken == resumeToken) {
                            handleWalkSessionResumeRecognizerNotStarted()
                        }
                    }
                    VoiceRecognitionPurpose.WALK_SESSION_TAKEOVER -> {
                        if (expectedGatewayWalkOperationId != null &&
                            gatewayWalkTakeoverPromptOperationId == expectedGatewayWalkOperationId
                        ) {
                            cancelGatewayWalkTakeoverConfirmation(epoch, "takeover_voice_not_started")
                        }
                    }
                }
            }
        }
        updateGatewayVoiceStatus("현재 음성 안내가 끝나면 명령을 듣겠습니다.")
        updateNavigationStatus("voice=input_waiting_for_output")
        lateinit var pending: Runnable
        pending = Runnable {
            if (deferredVoiceRecognitionStart !== pending) return@Runnable
            val current = voiceRecognitionGeneration == generation &&
                commandSpeechResponseGeneration == responseGeneration &&
                isFeedbackLifecycleCurrent(lifecycleGeneration) && nativeUiPage == page &&
                reporterUserId == actor && routeRequestGeneration == routeGeneration &&
                GatewaySessionProcessCoordinator.snapshot().generation == sessionGeneration &&
                walkSessionLifecycle.snapshot().epoch == epoch &&
                !voiceRecognitionActive && !voiceCommandPromptPending
            if (!current) {
                cancelDeferredVoiceRecognitionStart()
                scheduleHandsFreeVoiceRestart()
                return@Runnable
            }
            if (SystemClock.elapsedRealtime() >= deadline) {
                cancelDeferredVoiceRecognitionStart()
                updateGatewayVoiceStatus("음성 안내가 끝난 뒤 음성 명령을 다시 눌러 주세요.")
                updateNavigationStatus("voice=input_wait_expired")
                scheduleHandsFreeVoiceRestart()
                return@Runnable
            }
            if (isHandsFreeVoiceRecognitionBlocked() ||
                !feedbackPolicy.canSpeakNavigation(SystemClock.elapsedRealtime())
            ) {
                reportCleanupCallbackHandler.postDelayed(pending, DEFERRED_VOICE_INPUT_POLL_MS)
                return@Runnable
            }
            deferredVoiceRecognitionStart = null
            deferredVoiceRecognitionFailure = null
            if (!startVoiceCommandRecognition(purpose, expectedGatewayWalkOperationId)) {
                inputNotStarted()
                updateVoiceCommandButton(active = false)
                scheduleHandsFreeVoiceRestart()
            }
        }
        deferredVoiceRecognitionStart = pending
        deferredVoiceRecognitionFailure = inputNotStarted
        updateVoiceCommandButton(active = false)
        reportCleanupCallbackHandler.postDelayed(pending, DEFERRED_VOICE_INPUT_POLL_MS)
        return true
    }

    private fun cancelCommandSpeechResponse() {
        cancelDeferredVoiceRecognitionStart()
        commandSpeechResponseGeneration += 1L
        failInterruptedRouteDecisionSpeech(commandSpeechResponseGeneration - 1L)
        commandSpeechResponseCallbacks.clear()
        voiceCommandPromptPending = false
        voiceCommandPromptReadyGeneration = null
        feedbackActuator?.cancelCommandInteraction()
    }

    private fun cancelVoiceCommandRecognition() {
        cancelForegroundHomeWakeAcknowledgement()
        cancelGatewaySpeechInteraction("voice_cancelled")
        voiceRecognitionGeneration += 1
        cancelCommandSpeechResponse()
        voiceRecognitionActive = false
        voiceRecognitionPurpose = VoiceRecognitionPurpose.COMMAND
        clearVoiceEndConfirmation()
        speechRecognizer?.cancel()
        updateVoiceCommandButton(active = false)
        scheduleHandsFreeVoiceRestart()
    }

    private fun buildVoiceCommandRecognitionListener(
        generation: Int,
        purpose: VoiceRecognitionPurpose,
        expectedWalkEpoch: WalkRuntimeEpoch,
        expectedResumeToken: WalkSessionConfirmationToken?,
        expectedGatewayWalkOperationId: String?,
        expectedNavigationDecisionToken: RouteNavigatorDecisionToken?,
    ): RecognitionListener {
        return object : RecognitionListener {
            override fun onReadyForSpeech(params: Bundle?) {
                if (
                    isVoiceRecognitionLeaseCurrent(
                        generation,
                        purpose,
                        expectedWalkEpoch,
                        expectedResumeToken,
                        expectedGatewayWalkOperationId,
                    )
                ) {
                    logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.ONE_SHOT_UI_READY)
                    ensureFeedbackActuator().playVoiceListeningStartVibration()
                    updateVoiceRecognitionSignal("말씀하세요")
                }
            }

            override fun onBeginningOfSpeech() {
                if (
                    isVoiceRecognitionLeaseCurrent(
                        generation,
                        purpose,
                        expectedWalkEpoch,
                        expectedResumeToken,
                        expectedGatewayWalkOperationId,
                    )
                ) updateVoiceRecognitionSignal("말씀하세요")
            }
            override fun onRmsChanged(rmsdB: Float) = Unit
            override fun onBufferReceived(buffer: ByteArray?) = Unit
            override fun onEndOfSpeech() {
                if (
                    isVoiceRecognitionLeaseCurrent(
                        generation,
                        purpose,
                        expectedWalkEpoch,
                        expectedResumeToken,
                        expectedGatewayWalkOperationId,
                    )
                ) updateVoiceRecognitionSignal("음성 처리 중")
            }
            override fun onEvent(eventType: Int, params: Bundle?) = Unit
            override fun onPartialResults(partialResults: Bundle?) = Unit

            override fun onError(error: Int) {
                if (
                    !isVoiceRecognitionLeaseCurrent(
                        generation,
                        purpose,
                        expectedWalkEpoch,
                        expectedResumeToken,
                        expectedGatewayWalkOperationId,
                    )
                ) return
                voiceRecognitionGeneration += 1
                voiceRecognitionActive = false
                voiceRecognitionPurpose = VoiceRecognitionPurpose.COMMAND
                updateVoiceCommandButton(active = false)
                updateNavigationStatus("voice=recognition_failed code=$error")
                logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.ONE_SHOT_UI_ERROR, errorCode = error)
                if (
                    error == SpeechRecognizer.ERROR_NO_MATCH ||
                    error == SpeechRecognizer.ERROR_SPEECH_TIMEOUT
                ) {
                    if (purpose == VoiceRecognitionPurpose.COMMAND) {
                        clearVoiceEndConfirmation()
                    }
                    when (purpose) {
                        VoiceRecognitionPurpose.WALK_SESSION_RESUME ->
                            handleWalkSessionResumeRecognition(emptyList())
                        VoiceRecognitionPurpose.WALK_SESSION_TAKEOVER ->
                            handleGatewayWalkTakeoverRecognition(emptyList())
                        VoiceRecognitionPurpose.COMMAND -> {
                            val dialogForDiagnostic = currentVoiceDestinationDialogState()
                            logVoiceDialogDiagnostic(
                                stage = VoiceDialogDiagnosticStage.INPUT_ERROR,
                                reason = when (error) {
                                    SpeechRecognizer.ERROR_NO_MATCH -> VoiceDialogDiagnosticReason.NO_MATCH
                                    SpeechRecognizer.ERROR_SPEECH_TIMEOUT -> VoiceDialogDiagnosticReason.SPEECH_TIMEOUT
                                    else -> VoiceDialogDiagnosticReason.OTHER_ERROR
                                },
                                dialogValid = dialogForDiagnostic != null,
                                pageIndex = dialogForDiagnostic?.pageIndex,
                                origin = classifyVoiceDialogDiagnosticOrigin("device_stt"),
                            )
                            if (!retryHomeDestinationVoiceDialog("말씀을 정확히 듣지 못했습니다.")) {
                                speakInteraction("음성 명령을 인식하지 못했습니다.")
                            }
                        }
                    }
                    scheduleHandsFreeVoiceRestart()
                    return
                }
                speechRecognizer?.destroy()
                speechRecognizer = null
                handleOneShotSpeechRecognitionFailure(
                    "휴대폰 내부 one-shot 음성 인식에 오류가 발생했습니다.",
                    // One backend failure cannot permanently disable the offline fallback.
                    permanentlyLimit = false,
                )
                when (purpose) {
                    VoiceRecognitionPurpose.WALK_SESSION_RESUME ->
                        handleWalkSessionResumeRecognizerNotStarted()
                    VoiceRecognitionPurpose.WALK_SESSION_TAKEOVER ->
                        handleGatewayWalkTakeoverRecognition(emptyList())
                    VoiceRecognitionPurpose.COMMAND -> Unit
                }
            }

            override fun onResults(results: Bundle?) {
                if (
                    !isVoiceRecognitionLeaseCurrent(
                        generation,
                        purpose,
                        expectedWalkEpoch,
                        expectedResumeToken,
                        expectedGatewayWalkOperationId,
                    )
                ) return
                voiceRecognitionGeneration += 1
                voiceRecognitionActive = false
                voiceRecognitionPurpose = VoiceRecognitionPurpose.COMMAND
                updateVoiceCommandButton(active = false)
                updateGatewayVoiceStatus("기기 내 음성 명령을 처리했습니다.")
                val phrases = results
                    ?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)
                    .orEmpty()
                val confidenceScores = results?.getFloatArray(SpeechRecognizer.CONFIDENCE_SCORES)
                logVoiceInputDiagnostic(
                    VoiceInputDiagnosticEvent.ONE_SHOT_UI_FINAL,
                    confidence = confidenceScores?.getOrNull(0),
                    resultCount = phrases.size,
                )
                when (purpose) {
                    VoiceRecognitionPurpose.WALK_SESSION_RESUME ->
                        handleWalkSessionResumeRecognition(phrases)
                    VoiceRecognitionPurpose.WALK_SESSION_TAKEOVER ->
                        handleGatewayWalkTakeoverRecognition(phrases)
                    VoiceRecognitionPurpose.COMMAND ->
                        handleVoiceCommandPhrases(
                            phrases,
                            confidenceScores,
                            expectedNavigationDecisionToken,
                            resultBackend = offlineSpeechResultEngine(results),
                            hasAdditionalAlternatives = hasAdditionalOfflineSpeechAlternatives(results),
                        )
                }
                scheduleHandsFreeVoiceRestart()
            }
        }
    }

    private fun isVoiceRecognitionLeaseCurrent(
        expectedGeneration: Int,
        expectedPurpose: VoiceRecognitionPurpose,
        expectedWalkEpoch: WalkRuntimeEpoch,
        expectedResumeToken: WalkSessionConfirmationToken?,
        expectedGatewayWalkOperationId: String?,
    ): Boolean {
        if (
            expectedGeneration != voiceRecognitionGeneration ||
            expectedPurpose != voiceRecognitionPurpose
        ) return false
        return when (expectedPurpose) {
            VoiceRecognitionPurpose.COMMAND ->
                walkSessionLifecycle.snapshot().let { snapshot ->
                    snapshot.epoch == expectedWalkEpoch &&
                        snapshot.isForeground &&
                        (snapshot.state in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED) ||
                            (nativeUiPage.isVoiceInteractionPage() && homeVoiceCommandAvailable()))
                }
            VoiceRecognitionPurpose.WALK_SESSION_RESUME -> {
                val snapshot = walkSessionLifecycle.snapshot()
                expectedResumeToken != null &&
                    snapshot.epoch == expectedWalkEpoch &&
                    snapshot.state == WalkSessionState.PAUSED &&
                    snapshot.recoveryStage ==
                    WalkSessionRecoveryStage.AWAITING_RESUME_CONFIRMATION &&
                    snapshot.confirmationToken == expectedResumeToken &&
                    walkSessionResumeConfirmationToken == expectedResumeToken
            }
            VoiceRecognitionPurpose.WALK_SESSION_TAKEOVER -> {
                val snapshot = walkSessionLifecycle.snapshot()
                expectedGatewayWalkOperationId != null &&
                    snapshot.epoch == expectedWalkEpoch &&
                    snapshot.state == WalkSessionState.READY &&
                    gatewayWalkTakeoverPromptPending &&
                    gatewayWalkTakeoverPromptOperationId ==
                    expectedGatewayWalkOperationId &&
                    gatewayWalkStartConfirmationToken ==
                    snapshot.confirmationToken &&
                    gatewayWalkAuthorityController.currentConflictOrNull(
                        expectedWalkEpoch,
                    ) != null
            }
        }
    }

    private fun handleVoiceCommandPhrases(
        phrases: List<String>,
        confidenceScores: FloatArray?,
        expectedNavigationDecisionToken: RouteNavigatorDecisionToken?,
        includeRecognizedTextInStatus: Boolean = true,
        redactedRecognitionSource: String = "device_stt",
        resultBackend: OfflineSpeechEngine? = null,
        hasAdditionalAlternatives: Boolean = false,
    ) {
        val recognized = phrases.firstOrNull().orEmpty()
        val snapshot = walkSessionLifecycle.snapshot()
        val walkDecision = walkSessionVoiceControlPolicy.evaluate(
            phrase = recognized,
            confidence = confidenceScores?.getOrNull(0) ?: Float.NaN,
            state = snapshot.state,
            epoch = snapshot.epoch,
        )
        logVoiceInputDiagnostic(
            VoiceInputDiagnosticEvent.WALK_DECISION,
            matched = walkDecision.action != WalkSessionVoiceAction.NO_OP,
        )
        if (walkDecision.action != WalkSessionVoiceAction.NO_OP) {
            executeWalkSessionVoiceAction(walkDecision.action, snapshot.epoch)
            return
        }
        if (voiceEndConfirmationPromptPending) {
            logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.COMMAND_GATE_BLOCKED)
            clearVoiceEndConfirmation()
            updateNavigationStatus("voice=walk_end_confirmation_unmatched")
            speakInteraction("보행 종료를 확인하지 못했습니다. 종료하려면 다시 요청해 주세요.")
            return
        }
        val destinationDialogState = currentVoiceDestinationDialogState()
        logVoiceDialogDiagnostic(
            stage = VoiceDialogDiagnosticStage.FINAL_RECEIVED,
            reason = when {
                destinationDialogState != null -> VoiceDialogDiagnosticReason.NONE
                homeDestinationVoiceDialogLease != null -> VoiceDialogDiagnosticReason.STALE_DIALOG_CONTEXT
                else -> VoiceDialogDiagnosticReason.NO_DIALOG_CONTEXT
            },
            dialogValid = destinationDialogState != null,
            pageIndex = destinationDialogState?.pageIndex,
            origin = classifyVoiceDialogDiagnosticOrigin(redactedRecognitionSource),
        )
        val allowBareDestinationIndex = destinationDialogState != null ||
            (!nativeHomeFeatureContextAvailable() &&
                destinationSearchVoiceState != null &&
                destinationSearchVoiceState?.query == destinationSearchQuery &&
                !destinationSearchInFlight && currentDestinationSearchAllowsWork())
        if (BuildConfig.DEBUG) {
            val candidate = kr.co.hanium.dreamup.walksafe.navigation.parseAndroidVoiceCommand(
                phrases.firstOrNull().orEmpty(),
                allowBareDestinationIndex = allowBareDestinationIndex,
            )
            logVoiceInputDiagnostic(
                VoiceInputDiagnosticEvent.COMMAND_CANDIDATE_PARSED,
                matched = candidate != null,
            )
        }
        val scoredAction = selectAndroidVoiceAction(
            phrases,
            confidenceScores,
            allowBareDestinationIndex = allowBareDestinationIndex,
        )
        val platformCandidate = if (scoredAction == null) {
            assessPlatformVoiceCandidate(
                phrases = phrases,
                confidenceScores = confidenceScores,
                backend = resultBackend,
                isFinal = true,
                isHomeContext = nativeHomeFeatureContextAvailable(),
                allowBareDestinationIndex = allowBareDestinationIndex,
                hasAdditionalAlternatives = hasAdditionalAlternatives,
                destinationDialogState = destinationDialogState,
            )
        } else null
        if (BuildConfig.DEBUG && platformCandidate != null) {
            android.util.Log.d(
                "WalkSafeVoiceInput",
                "event=PLATFORM_CANDIDATE_POLICY disposition=${platformCandidate.disposition.name}",
            )
            BoundedRuntimeDiagnosticLog.recordState(
                domain = RuntimeDiagnosticDomain.VOICE_DIALOG,
                stage = VoiceDialogDiagnosticStage.COMMAND_CLASSIFIED,
                reason = platformCandidate.disposition,
                context = if (destinationDialogState != null) VoiceDialogDiagnosticContext.VALID
                    else VoiceDialogDiagnosticContext.ABSENT_OR_STALE,
                origin = classifyVoiceDialogDiagnosticOrigin(redactedRecognitionSource),
                pageIndex = destinationDialogState?.pageIndex,
            )
        }
        val action = scoredAction ?: platformCandidate?.previewAction
        logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.COMMAND_SELECTED, matched = action != null)
        if (platformCandidate?.disposition == PlatformVoiceCandidateDisposition.CONFIRMATION_REQUIRED) {
            val showExistingDestinationConfirmation =
                platformCandidate.candidate ==
                    kr.co.hanium.dreamup.walksafe.navigation.AndroidVoiceCommand.StartNavigation &&
                    pendingUiDestination != null
            if (showExistingDestinationConfirmation) {
                showNativeUiPage(NativeUiPage.DESTINATION_CONFIRM)
            }
            val message = when {
                showExistingDestinationConfirmation ->
                    "안내 시작은 화면의 안내 시작 버튼을 눌러 확인해 주세요."
                destinationDialogState != null ->
                    "안내한 후보 번호를 확인하지 못했습니다."
                else ->
                    "확인이 필요한 실행 명령입니다. 음성 화면을 닫은 뒤 실행할 기능을 직접 선택해 주세요."
            }
            updateGatewayVoiceStatus(message)
            if (showExistingDestinationConfirmation || !retryHomeDestinationVoiceDialog(message)) {
                speakInteraction(message)
            }
            return
        }
        if (platformCandidate?.disposition == PlatformVoiceCandidateDisposition.UNRECOGNIZED) {
            // Saying it again cannot help; nothing said was a command. Same wording as the scored
            // path's miss below, so one dead end does not survive in a second place.
            val message = "못 알아들었습니다. ${unrecognizedCommandHintKo()}"
            updateGatewayVoiceStatus(message)
            if (!retryHomeDestinationVoiceDialog(message)) {
                speakInteraction(message)
            }
            return
        }
        if (platformCandidate?.disposition in setOf(
                PlatformVoiceCandidateDisposition.AMBIGUOUS,
                PlatformVoiceCandidateDisposition.INVALID_FINAL,
            )
        ) {
            val message = "음성 후보를 하나로 확정하지 못했습니다. 다시 말씀해 주세요."
            updateGatewayVoiceStatus(message)
            if (!retryHomeDestinationVoiceDialog(message)) {
                speakInteraction(message)
            }
            return
        }
        if (platformCandidate?.disposition == PlatformVoiceCandidateDisposition.PREVIEW_ONLY) {
            updateGatewayVoiceStatus(
                if (action is AndroidVoiceAction.SearchDestination) {
                    "음성 후보로 검색 결과를 보여드립니다. 목적지를 직접 선택해 주세요."
                } else {
                    "도움말을 읽어드립니다."
                },
            )
        }
        if (snapshot.state == WalkSessionState.PAUSED &&
            action !in setOf(AndroidVoiceAction.SpeakVoiceHelp, AndroidVoiceAction.OpenSettings)) {
            logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.COMMAND_GATE_BLOCKED)
            updateNavigationStatus("voice=paused_command_unmatched")
            speakInteraction("일시정지 중에는 보행 재개 또는 보행 종료라고 말씀해 주세요.")
            return
        }
        if (action == null) {
            updateNavigationStatus(
                if (includeRecognizedTextInStatus) {
                    "voice=command_unmatched phrase=${recognized.toStatusToken(maxLength = 48)}"
                } else {
                    "voice=command_unmatched source=$redactedRecognitionSource"
                },
            )
            if (!retryHomeDestinationVoiceDialog("명령을 이해하지 못했습니다.")) {
                speakInteraction("못 알아들었습니다. ${unrecognizedCommandHintKo()}")
            }
            return
        }
        if (
            action in setOf(
                AndroidVoiceAction.RequestReroute,
                AndroidVoiceAction.RecheckLocation,
                AndroidVoiceAction.CancelDestination,
                AndroidVoiceAction.ConfirmArrival,
                AndroidVoiceAction.RejectArrival,
                AndroidVoiceAction.StopNavigation,
            ) && expectedNavigationDecisionToken != routeNavigator.pendingDecisionToken()
        ) {
            logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.COMMAND_GATE_BLOCKED)
            updateNavigationStatus("voice=navigation_decision_stale")
            speakInteraction("경로 상태가 바뀌어 이전 음성 결정을 적용하지 않았습니다. 다시 확인해 주세요.")
            return
        }
        logVoiceInputDiagnostic(VoiceInputDiagnosticEvent.COMMAND_EXECUTION_REQUESTED)
        executeVoiceAction(action)
    }

    private fun executeWalkSessionVoiceAction(
        action: WalkSessionVoiceAction,
        expectedEpoch: WalkRuntimeEpoch,
    ) {
        if (walkSessionLifecycle.snapshot().epoch != expectedEpoch) return
        when (action) {
            WalkSessionVoiceAction.PAUSE -> {
                enterWalkSessionForegroundRecheckAndCancelOutputs("voice_pause")
                walkSessionResumeRetryRequiresUserAction = true
                syncActiveSessionScreenPolicy()
                updateStatus(
                    "보행 안내 일시정지",
                    "음성 요청으로 안내를 멈췄습니다. 재개 전 필수 기능을 다시 확인합니다.",
                )
                speakInteraction("보행 안내를 일시정지했습니다.")
            }
            WalkSessionVoiceAction.RESUME -> {
                walkSessionResumePromptPending = false
                walkSessionResumeRetryRequiresUserAction = false
                refreshStartupCapabilityUi()
                updateStatus(
                    "보행 재개 준비",
                    "필수 기능 재검사와 별도 시작 확인을 거친 뒤 보행 안내를 재개합니다.",
                )
                speakInteraction("필수 기능을 다시 확인한 뒤 보행 재개를 확인합니다.")
            }
            WalkSessionVoiceAction.REQUEST_END ->
                requestVoiceWalkEndConfirmation(expectedEpoch)
            WalkSessionVoiceAction.CONFIRM_END -> {
                voiceEndConfirmationPromptPending = false
                transitionWalkSession(WalkSessionEvent.EndRequested)
                persistWalkSessionInterruptionMarker()
                cancelWalkSessionOutputs("voice_walk_end_confirmed")
                stopCameraFallbackSession(updateUi = false)
                stopDepthSession(closeSession = true)
                syncActiveSessionScreenPolicy()
                refreshStartupCapabilityUi()
                updateStatus("보행 종료", "음성 확인을 거쳐 현재 보행을 종료했습니다.")
                speakInteraction("보행을 종료했습니다.")
            }
            WalkSessionVoiceAction.CANCEL_END -> {
                voiceEndConfirmationPromptPending = false
                updateNavigationStatus("voice=walk_end_cancelled")
                speakInteraction("보행 종료를 취소했습니다.")
            }
            WalkSessionVoiceAction.NO_OP -> Unit
        }
    }

    private fun requestVoiceWalkEndConfirmation(expectedEpoch: WalkRuntimeEpoch) {
        val snapshot = walkSessionLifecycle.snapshot()
        if (
            snapshot.epoch != expectedEpoch ||
            snapshot.state !in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED)
        ) {
            clearVoiceEndConfirmation()
            return
        }
        voiceEndConfirmationPromptPending = true
        val prompt = "보행을 종료할까요? 보행 종료 확인 또는 보행 종료 취소라고 말해 주세요."
        val generation = feedbackLifecycleGeneration
        val delivered = {
            runOnUiThread {
                val current = walkSessionLifecycle.snapshot()
                if (
                    feedbackLifecycleGeneration == generation &&
                    voiceEndConfirmationPromptPending &&
                    current.epoch == expectedEpoch &&
                    current.state in setOf(WalkSessionState.ACTIVE, WalkSessionState.PAUSED)
                ) {
                    if (!startVoiceCommandRecognition()) {
                        clearVoiceEndConfirmation()
                        updateNavigationStatus("voice=walk_end_confirmation_unavailable")
                    }
                }
            }
        }
        val failed = {
            runOnUiThread {
                if (
                    feedbackLifecycleGeneration == generation &&
                    walkSessionLifecycle.snapshot().epoch == expectedEpoch
                ) {
                    clearVoiceEndConfirmation()
                    updateNavigationStatus("voice=walk_end_prompt_failed")
                }
            }
        }
        val accepted = ensureFeedbackActuator().speakInteraction(
            message = prompt,
            onCompleted = delivered,
            onFailed = failed,
        ) == NavigationSpeechDispatchResult.ACCEPTED
        if (!accepted) failed()
    }

    private fun clearVoiceEndConfirmation() {
        voiceEndConfirmationPromptPending = false
        walkSessionVoiceControlPolicy.invalidatePendingEnd()
    }

    private fun executeVoiceAction(action: AndroidVoiceAction) {
        if (nativeHomeFeatureContextAvailable() &&
            action !is AndroidVoiceAction.SearchDestination &&
            action !is AndroidVoiceAction.SelectDestinationCandidate &&
            action !in setOf(
                AndroidVoiceAction.RepeatDestinationCandidates,
                AndroidVoiceAction.HearMoreDestinationCandidates,
                AndroidVoiceAction.CancelDestination,
                AndroidVoiceAction.StartNavigation,
                AndroidVoiceAction.SpeakCurrentGuidance,
                AndroidVoiceAction.SpeakVoiceHelp,
                AndroidVoiceAction.OpenSettings,
            )
        ) {
            updateNavigationStatus("voice=walk_action_requires_active_walk")
            speakInteraction("보행을 시작한 뒤 사용할 수 있는 명령입니다. 목적지를 먼저 검색해 주세요.")
            return
        }
        val commandPage = when (action.uiDestination()) {
            VoiceCommandUiDestination.VOICE_COMMAND -> NativeUiPage.VOICE_COMMAND
            VoiceCommandUiDestination.DESTINATION_SEARCH -> NativeUiPage.DESTINATION_SEARCH
            VoiceCommandUiDestination.SETTINGS -> NativeUiPage.SETTINGS
        }
        showNativeUiPage(commandPage, preserveVoiceInteraction = true)
        when (action) {
            AndroidVoiceAction.OpenSettings -> speakStatusExplanation("설정 화면을 열었습니다.")
            AndroidVoiceAction.StartNavigation -> {
                if (pendingUiDestination != null) startNativeDestinationGuidance()
                else speakInteraction(
                    if (isRouteActive) "이미 길안내 중입니다."
                    else "목적지를 검색하고 후보를 선택한 뒤 안내 시작이라고 말해 주세요.",
                )
            }
            AndroidVoiceAction.SpeakCurrentGuidance -> {
                if (isWalkSessionRuntimeActive()) speakNextNavigationInstruction()
                else speakInteraction("진행 중인 길안내가 없습니다. 목적지를 먼저 선택해 주세요.")
            }
            AndroidVoiceAction.SpeakVoiceHelp -> {
                val help = if (walkSessionLifecycle.snapshot().state == WalkSessionState.PAUSED) {
                    "일시정지 중에는 보행 재개 또는 보행 종료라고 말해 주세요. 종료할 때는 확인을 한 번 더 받습니다."
                } else {
                    "목적지는 서울역으로 안내해줘처럼 말해 주세요. 후보 안내 뒤에는 1번 또는 첫 번째라고 선택할 수 있습니다. " +
                        "더 듣기, 목적지 취소, 안내 시작, 설정을 사용할 수 있습니다. " +
                        "보행 중에는 다음 안내 알려줘, 다시 말해줘, 경로 다시 찾아줘, 위치 다시 확인, " +
                        "도착했어, 아직 도착 아니야, 길안내 종료, 신고해, 보행 일시정지, 보행 종료를 말할 수 있습니다. " +
                        "신고와 보행 종료는 확인 안내를 따라 주세요."
                }
                speakInteraction(help)
            }
            AndroidVoiceAction.CreateReport -> {
                updateNavigationStatus("voice=report_command_recognized")
                requestExplicitReport(ExplicitReportRequestSource.VOICE)
            }
            is AndroidVoiceAction.SearchDestination -> startVoiceDestinationSearch(action.query)
            is AndroidVoiceAction.SelectDestinationCandidate -> selectVoiceDestinationCandidate(action.oneBasedIndex)
            AndroidVoiceAction.RepeatDestinationCandidates -> repeatVoiceDestinationCandidates()
            AndroidVoiceAction.HearMoreDestinationCandidates -> hearMoreVoiceDestinationCandidates()
            AndroidVoiceAction.CancelDestination -> cancelDestinationFromVoice()
            AndroidVoiceAction.SpeakNextNavigationInstruction -> speakNextNavigationInstruction()
            AndroidVoiceAction.RequestReroute -> requestRerouteFromVoice()
            AndroidVoiceAction.RecheckLocation -> recheckLocationFromVoice()
            AndroidVoiceAction.ConfirmArrival -> confirmArrivalFromVoice()
            AndroidVoiceAction.RejectArrival -> rejectArrivalFromVoice()
            AndroidVoiceAction.StopNavigation -> stopNavigationFromVoice()
        }
    }

    /**
     * "다시 말씀해 주세요" asks a walker who cannot read the screen to guess. The destination
     * dialog already re-offers its numbers instead; everywhere else ended in a dead end. Each
     * hint names commands the parser accepts in the state the walk is actually in.
     */
    private fun unrecognizedCommandHintKo(): String = when {
        voiceEndConfirmationPromptPending -> "보행 종료 확인 또는 보행 종료 취소라고 말씀해 주세요."
        walkSessionLifecycle.snapshot().state == WalkSessionState.PAUSED ->
            "보행 재개 또는 보행 종료라고 말씀해 주세요."
        routeNavigator.pendingUserDecision() == RouteNavigatorUserDecision.ARRIVAL_CONFIRMATION ->
            "도착했어 또는 아직 도착 아니야라고 말씀해 주세요."
        routeNavigator.pendingUserDecision() == RouteNavigatorUserDecision.REROUTE ->
            "새 경로 요청, 위치 다시 확인, 길안내 종료 중에서 말씀해 주세요."
        routeNavigator.pendingUserDecision() == RouteNavigatorUserDecision.LOCATION_RECHECK ->
            "위치 다시 확인이라고 말씀해 주세요."
        isRouteActive -> "다음 안내 알려줘 또는 길안내 종료라고 말씀해 주세요."
        pendingUiDestination != null -> "안내 시작 또는 목적지 취소라고 말씀해 주세요."
        else -> "목적지를 말하거나 도움말이라고 말씀해 주세요."
    }

    private var homeDestinationVoiceDialogLease: HomeDestinationVoiceDialogLease? = null

    private fun clearHomeDestinationVoiceDialog() {
        clearHomeDestinationVoiceDialog(VoiceDialogDiagnosticReason.UNKNOWN)
    }

    private fun clearHomeDestinationVoiceDialog(reason: VoiceDialogDiagnosticReason) {
        val dialogForDiagnostic = currentVoiceDestinationDialogState()
        homeDestinationVoiceDialogLease?.close()
        homeDestinationVoiceDialogLease = null
        logVoiceDialogDiagnostic(
            stage = VoiceDialogDiagnosticStage.DIALOG_CLEARED,
            reason = reason,
            dialogValid = dialogForDiagnostic != null,
            pageIndex = dialogForDiagnostic?.pageIndex,
        )
    }

    private fun currentVoiceDestinationDialogState(): DestinationSearchVoiceState? =
        homeDestinationVoiceDialogLease?.currentState(
            actorId = reporterUserId,
            sessionGeneration = GatewaySessionProcessCoordinator.snapshot().generation,
            searchGeneration = destinationSearchGeneration,
            query = destinationSearchQuery,
            state = destinationSearchVoiceState,
            homeContextAvailable = nativeHomeFeatureContextAvailable(),
            voicePage = nativeUiPage.isVoiceInteractionPage(),
        )

    private fun retryHomeDestinationVoiceDialog(message: String): Boolean {
        val state = currentVoiceDestinationDialogState()
        if (state == null) {
            logVoiceDialogDiagnostic(
                stage = VoiceDialogDiagnosticStage.RETRY_SKIPPED,
                reason = if (homeDestinationVoiceDialogLease == null) {
                    VoiceDialogDiagnosticReason.NO_DIALOG_CONTEXT
                } else {
                    VoiceDialogDiagnosticReason.STALE_DIALOG_CONTEXT
                },
                dialogValid = false,
            )
            return false
        }
        logVoiceDialogDiagnostic(
            stage = VoiceDialogDiagnosticStage.RETRY_REQUESTED,
            dialogValid = true,
            pageIndex = state.pageIndex,
        )
        speakHomeDestinationVoicePrompt(
            state,
            "인식하지 못하였습니다. 다시 듣기 또는 해당 번호를 말해주세요.",
        )
        return true
    }

    private fun speakHomeDestinationVoicePrompt(
        state: DestinationSearchVoiceState,
        message: String = state.voicePrompt(),
    ): Boolean {
        clearHomeDestinationVoiceDialog()
        if (!nativeHomeFeatureContextAvailable() ||
            !nativeUiPage.isVoiceInteractionPage() || state.results.isEmpty()
        ) return speakInteraction(message)
        val actorId = reporterUserId ?: return false
        val lease = HomeDestinationVoiceDialogLease(
            actorId = actorId,
            sessionGeneration = GatewaySessionProcessCoordinator.snapshot().generation,
            searchGeneration = destinationSearchGeneration,
            state = state,
        )
        homeDestinationVoiceDialogLease = lease
        val dialogForDiagnostic = currentVoiceDestinationDialogState()
        logVoiceDialogDiagnostic(
            stage = VoiceDialogDiagnosticStage.DIALOG_OPENED,
            dialogValid = dialogForDiagnostic != null,
            pageIndex = dialogForDiagnostic?.pageIndex,
        )
        val preparationGeneration = voiceRecognitionGeneration
        return speakCommandResponse(
            message = message,
            preparingInput = true,
            onCompleted = {
                if (homeDestinationVoiceDialogLease === lease &&
                    voiceRecognitionGeneration == preparationGeneration
                ) {
                    val awaitingInput = voiceCommandPromptPending
                    voiceCommandPromptPending = false
                    val current = awaitingInput && currentVoiceDestinationDialogState() === state
                    voiceCommandPromptReadyGeneration = if (current) preparationGeneration else null
                    if (current) {
                        if (BuildConfig.DEBUG) android.util.Log.d(
                            "WalkSafeVoiceInput", "event=DESTINATION_VOICE_PROMPT_DONE dialog_current=true",
                        )
                        if (BuildConfig.DEBUG) android.util.Log.d(
                            "WalkSafeVoiceInput", "event=DESTINATION_VOICE_FOLLOW_UP_REQUESTED",
                        )
                        if (!startVoiceCommandRecognition()) {
                            voiceCommandPromptReadyGeneration = null
                            updateVoiceCommandButton(active = false)
                            if (BuildConfig.DEBUG) android.util.Log.d(
                                "WalkSafeVoiceInput", "event=DESTINATION_VOICE_FOLLOW_UP_BLOCKED",
                            )
                        }
                    } else {
                        updateVoiceCommandButton(active = voiceRecognitionActive)
                    }
                }
            },
            onFailed = {
                if (homeDestinationVoiceDialogLease === lease &&
                    voiceRecognitionGeneration == preparationGeneration
                ) {
                    voiceCommandPromptPending = false
                    voiceCommandPromptReadyGeneration = null
                    updateGatewayVoiceStatus(
                        "후보 안내를 완료하지 못했습니다. 음성 명령 버튼을 눌러 다시 시도해 주세요.",
                    )
                    updateVoiceCommandButton(active = voiceRecognitionActive)
                }
            },
        )
    }

    private fun startVoiceDestinationSearch(query: String) {
        if (!currentDestinationSearchAllowsWork()) {
            explainNavigationFeatureUnavailable()
            return
        }
        clearHomeDestinationVoiceDialog()
        if (destinationSearchInFlight) {
            cancelDestinationSearch()
        }
        destinationQueryInput.setText(query)
        pendingVoiceDestinationQuery = query
        pendingVoiceDestinationPageIndex = 0
        destinationSearchVoiceState = null
        if (performDestinationSearch(reset = true)) {
            updateNavigationStatus("voice=destination_search query=${query.toStatusToken(maxLength = 48)}")
            speakInteraction("${query} 목적지를 검색합니다.")
        } else {
            pendingVoiceDestinationQuery = null
            pendingVoiceDestinationPageIndex = null
        }
    }

    private fun repeatVoiceDestinationCandidates() {
        val state = if (nativeHomeFeatureContextAvailable()) {
            currentVoiceDestinationDialogState()
        } else {
            destinationSearchVoiceState
        }
        val transition = state?.onCommand(DestinationSearchVoiceCommand.RepeatPage)
        if (transition == null || !transition.accepted) {
            speakInteraction("먼저 목적지를 검색해 주세요.")
            return
        }
        speakHomeDestinationVoicePrompt(transition.state)
    }

    private fun hearMoreVoiceDestinationCandidates() {
        if (!currentDestinationSearchAllowsWork()) {
            explainNavigationFeatureUnavailable()
            return
        }
        val state = if (nativeHomeFeatureContextAvailable()) {
            currentVoiceDestinationDialogState()
        } else {
            destinationSearchVoiceState
        }
        if (state == null) {
            speakInteraction("먼저 목적지를 검색해 주세요.")
            return
        }
        val transition = state.onCommand(DestinationSearchVoiceCommand.HearMore)
        if (transition.accepted) {
            destinationSearchVoiceState = transition.state
            speakHomeDestinationVoicePrompt(transition.state)
            return
        }
        val canLoadMore = destinationSearchResults.size >= destinationSearchPage * DESTINATION_SEARCH_PAGE_SIZE &&
            destinationSearchResults.size < DESTINATION_SEARCH_MAX_RESULTS
        if (!canLoadMore || destinationSearchInFlight) {
            speakHomeDestinationVoicePrompt(
                state,
                "더 안내할 목적지 후보가 없습니다. 안내한 후보 번호를 말씀해 주세요.",
            )
            return
        }
        pendingVoiceDestinationQuery = destinationSearchQuery
        pendingVoiceDestinationPageIndex = state.pageIndex + 1
        if (!performDestinationSearch(reset = false)) {
            pendingVoiceDestinationQuery = null
            pendingVoiceDestinationPageIndex = null
        }
    }

    private fun cancelDestinationFromVoice() {
        if (blockRouteMutationWhileDeviationChoicePending()) return
        val hadDestination = isRouteActive ||
            routeRequestInFlight.get() ||
            destinationSearchInFlight ||
            currentDestination != null ||
            destinationQueryInput.text?.isNotBlank() == true ||
            (::destinationLatInput.isInitialized && destinationLatInput.text?.isNotBlank() == true) ||
            (::destinationLngInput.isInitialized && destinationLngInput.text?.isNotBlank() == true)
        pendingUiDestination = null
        pendingVoiceDestinationQuery = null
        pendingVoiceDestinationPageIndex = null
        destinationSearchVoiceState = null
        if (destinationSearchInFlight) cancelDestinationSearch()
        resetRouteState()
        destinationSearchQuery = ""
        destinationQueryInput.setText("")
        if (::destinationLatInput.isInitialized) destinationLatInput.setText("")
        if (::destinationLngInput.isInitialized) destinationLngInput.setText("")
        updateDestinationSearchUi()
        val message = if (hadDestination) {
            "목적지와 진행 중인 경로를 취소했습니다."
        } else {
            "취소할 목적지가 없습니다."
        }
        updateNavigationStatus("voice=destination_cancelled hadDestination=$hadDestination")
        speakInteraction(message)
    }

    private fun selectVoiceDestinationCandidate(oneBasedIndex: Int) {
        if (!currentDestinationSearchAllowsWork()) {
            explainNavigationFeatureUnavailable()
            return
        }
        if (!requireReporterUserId("login_required_voice_destination_select")) return
        val state = if (nativeHomeFeatureContextAvailable()) {
            currentVoiceDestinationDialogState()
        } else {
            destinationSearchVoiceState
        }
        val voiceSelection = state?.onCommand(
            DestinationSearchVoiceCommand.SelectCandidate(oneBasedIndex),
        )
        val selected = voiceSelection?.selectedResult
        if (selected == null) {
            val message = if (destinationSearchInFlight) {
                "목적지 검색이 끝난 뒤 후보 번호를 말씀해 주세요."
            } else {
                "선택할 ${oneBasedIndex}번 목적지 후보가 없습니다."
            }
            updateNavigationStatus("voice=destination_candidate_missing index=$oneBasedIndex")
            if (!retryHomeDestinationVoiceDialog(message)) {
                speakInteraction(message)
            }
            return
        }
        if (nativeHomeFeatureContextAvailable()) {
            pendingVoiceDestinationQuery = null
            pendingVoiceDestinationPageIndex = null
            destinationSearchVoiceState = null
            openNativeDestinationConfirmation(selected)
            updateNavigationStatus("voice=destination_candidate_selected index=$oneBasedIndex")
            speakInteraction(
                "${selected.name} 목적지를 선택했습니다. 길안내 시작을 선택하면 " +
                    "현재 상태를 확인한 뒤 안내를 시작합니다.",
            )
            return
        }
        if (!onDestinationSelected(selected)) {
            if (currentDestination == selected.point && currentRouteLocationOrNull() == null) {
                speakInteraction(
                    "${selected.name} 목적지를 유지했습니다. GPS 위치를 확인한 뒤 " +
                        "같은 후보 번호를 다시 말하거나 경로 시작을 선택해 주세요.",
                )
            }
            return
        }
        pendingVoiceDestinationQuery = null
        pendingVoiceDestinationPageIndex = null
        destinationSearchVoiceState = null
        updateNavigationStatus("voice=destination_candidate_selected index=$oneBasedIndex")
        speakInteraction("${selected.name} 목적지를 선택했습니다. 경로를 확인합니다.")
    }

    /**
     * Says what the walk is doing rather than why the command was refused.
     *
     * The walker cannot see the screen, so the state is the one thing they need and the one thing
     * the old wording buried. It only names a command where exactly one is left; the three-way
     * choice was already read out when the deviation was announced, and repeating it costs seconds
     * mid-walk.
     */
    private fun explainRouteCommandUnavailable(
        onRouteKo: String = "경로를 따라가는 중입니다.",
    ) {
        speakInteraction(
            when {
                !isRouteActive -> "길안내 중이 아닙니다."
                routeNavigator.pendingUserDecision() ==
                    RouteNavigatorUserDecision.LOCATION_RECHECK ->
                    "위치 다시 확인만 할 수 있습니다."
                routeNavigator.pendingUserDecision() ==
                    RouteNavigatorUserDecision.ARRIVAL_CONFIRMATION ->
                    "도착 확인을 기다리고 있습니다."
                routeNavigator.pendingUserDecision() == RouteNavigatorUserDecision.REROUTE ->
                    "경로를 벗어난 상태입니다."
                else -> onRouteKo
            },
        )
    }

    private fun requestRerouteFromVoice() {
        if (!currentNavigationCollectionAllowsWork()) {
            explainNavigationFeatureUnavailable()
            return
        }
        val destination = currentDestination
        if (
            destination == null ||
            !isRouteActive ||
            routeNavigator.pendingUserDecision() != RouteNavigatorUserDecision.REROUTE
        ) {
            explainRouteCommandUnavailable()
            return
        }
        val decision = routeNavigator.selectDeviationChoice(RouteDeviationChoice.NEW_ROUTE)
        updateRouteDeviationActions(decision.pendingUserDecision)
        updateNavigationStatus("navigation=off_route_reroute_user_confirmed")
        speakInteraction(requireNotNull(decision.instruction))
        requestRoute(destination, reason = "off_route")
        if (!routeRequestInFlight.get() && routeNavigator.hasRoute()) {
            retainRouteAfterRerouteFailure("TMAP 새 경로 요청을 시작할 수 없어 방향 안내를 중지했습니다.")
        }
    }

    private fun recheckLocationFromVoice() {
        if (!currentNavigationCollectionAllowsWork()) {
            explainNavigationFeatureUnavailable()
            return
        }
        if (
            !isRouteActive ||
            routeNavigator.pendingUserDecision() !in setOf(
                RouteNavigatorUserDecision.LOCATION_RECHECK,
                RouteNavigatorUserDecision.REROUTE,
            )
        ) {
            explainRouteCommandUnavailable()
            return
        }
        val decision = routeNavigator.selectDeviationChoice(RouteDeviationChoice.RECHECK_LOCATION)
        updateRouteDeviationActions(decision.pendingUserDecision)
        latestTmapOnRoute = false
        directionGuidancePauseReason = "off_route_recheck"
        startNavigationServicesIfNeeded()
        updateNavigationStatus("navigation=off_route_location_recheck_requested auto_resume=false")
        speakInteraction(requireNotNull(decision.instruction))
    }

    private fun endNavigationAfterDeviation() {
        if (
            !isRouteActive ||
            routeNavigator.pendingUserDecision() != RouteNavigatorUserDecision.REROUTE
        ) {
            explainRouteCommandUnavailable()
            return
        }
        val decision = routeNavigator.selectDeviationChoice(RouteDeviationChoice.END_NAVIGATION)
        if (decision.reason != "off_route_navigation_ended") return
        resetRouteState()
        if (routeSnapshotPurgeFailed) {
            val detail =
                "암호화 경로 기록을 삭제하지 못했습니다. 새 길안내를 시작하지 말고 앱 저장소를 확인해 주세요."
            updateStatus(
                "길안내 종료 저장소 확인 필요",
                detail,
            )
            updateNavigationStatus("navigation=route_snapshot_purge_failed")
            speakInteraction(detail)
        } else {
            updateNavigationStatus("navigation=off_route_navigation_ended_by_user")
            speakInteraction(requireNotNull(decision.instruction))
        }
    }

    private fun confirmArrivalFromVoice() {
        val decision = routeNavigator.confirmArrival()
        if (!decision.arrived) {
            explainRouteCommandUnavailable("아직 도착 안내가 없습니다.")
            return
        }
        resetRouteState()
        updateNavigationStatus("navigation=arrival_confirmed_by_user")
        speakInteraction(requireNotNull(decision.instruction))
    }

    private fun confirmArrivalFromButton(expectedToken: RouteNavigatorDecisionToken?) {
        val decision = if (expectedToken != null) {
            routeNavigator.confirmArrival(expectedToken)
        } else {
            null
        }
        if (decision?.arrived != true) {
            updateRouteDeviationActions(routeNavigator.pendingUserDecision())
            updateNavigationStatus("navigation=arrival_confirmation_stale")
            speakInteraction("도착 확인 상태가 변경되었습니다. 현재 경로 상태를 다시 확인해 주세요.")
            return
        }
        resetRouteState()
        updateNavigationStatus("navigation=arrival_confirmed_by_user")
        speakInteraction(requireNotNull(decision.instruction))
    }

    private fun rejectArrivalFromVoice() {
        val decision = routeNavigator.rejectArrival()
        if (decision.reason != "arrival_rejected_route_retained") {
            explainRouteCommandUnavailable("아직 도착 안내가 없습니다.")
            return
        }
        updateRouteDeviationActions(decision.pendingUserDecision)
        updateNavigationStatus("navigation=arrival_rejected_route_retained")
        speakInteraction(requireNotNull(decision.instruction))
    }

    private fun rejectArrivalFromButton(expectedToken: RouteNavigatorDecisionToken?) {
        val decision = if (expectedToken != null) {
            routeNavigator.rejectArrival(expectedToken)
        } else {
            null
        }
        if (decision?.reason != "arrival_rejected_route_retained") {
            updateRouteDeviationActions(routeNavigator.pendingUserDecision())
            updateNavigationStatus("navigation=arrival_confirmation_stale")
            speakInteraction("도착 확인 상태가 변경되었습니다. 현재 경로 상태를 다시 확인해 주세요.")
            return
        }
        updateRouteDeviationActions(decision.pendingUserDecision)
        updateNavigationStatus("navigation=arrival_rejected_route_retained")
        speakInteraction(requireNotNull(decision.instruction))
    }

    private fun speakNextNavigationInstruction() {
        if (!currentNavigationCollectionAllowsWork()) {
            explainNavigationFeatureUnavailable()
            return
        }
        val expectedWalkEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return
        updateNavigationStatus("voice=next_navigation_instruction active=$isRouteActive")
        if (routeRequestInFlight.get()) {
            speakInteraction("목적지까지의 경로를 계산하고 있습니다.")
            return
        }
        if (!isRouteActive) {
            speakInteraction("진행 중인 길안내가 없습니다.")
            return
        }
        routeNavigator.pendingDecisionToken()?.let { token ->
            val message = when (token.decision) {
                RouteNavigatorUserDecision.REROUTE ->
                    "경로를 벗어났습니다. 새 경로 요청, 위치 다시 확인, 길안내 종료 중에서 선택해 주세요."
                RouteNavigatorUserDecision.LOCATION_RECHECK ->
                    "현재 위치와 경로를 확인해야 합니다. 위치 다시 확인을 선택해 주세요."
                RouteNavigatorUserDecision.ARRIVAL_CONFIRMATION ->
                    "목적지에 도착하셨나요? 도착 확인 또는 도착 아님 중에서 선택해 주세요."
            }
            speakRouteDecision(message, token, repeatRequested = true)
            return
        }
        // Reuse the fresh automatic context without adding another location/motion observation.
        val nowMs = SystemClock.elapsedRealtime()
        val update = routeNavigator.currentGuidance(nowMs, currentRouteFacingObservation(nowMs))
        if (update == null) {
            speakInteraction("현재 위치를 확인한 뒤 다음 경로를 안내합니다.")
            return
        }
        tryDispatchRouteInstruction(update, expectedWalkEpoch)
    }

    private fun stopNavigationFromVoice() {
        val hadActiveNavigation = isRouteActive || routeRequestInFlight.get()
        if (
            isRouteActive &&
            routeNavigator.pendingUserDecision() == RouteNavigatorUserDecision.REROUTE
        ) {
            endNavigationAfterDeviation()
            return
        }
        if (routeRequestInFlight.get()) {
            cancelActiveRouteRequest()
        } else if (isRouteActive) {
            resetRouteState()
        }
        val message = if (hadActiveNavigation) "길안내를 중지했습니다." else "진행 중인 길안내가 없습니다."
        updateNavigationStatus("voice=navigation_stopped hadActive=$hadActiveNavigation")
        speakInteraction(message)
    }

    private fun updateVoiceCommandButton(active: Boolean = voiceRecognitionActive) {
        if (!::voiceReportButton.isInitialized || !::walkSafetyVoiceButton.isInitialized) return
        val snapshot = walkSessionLifecycle.snapshot()
        val gatewayRecording = gatewayVoiceRecorder?.isRecording == true
        val gatewayProcessing = activeGatewaySpeechInteraction != null && !gatewayRecording
        val responsePending = commandSpeechResponseCallbacks.size() > 0 || voiceCommandPromptPending ||
            deferredVoiceRecognitionStart != null
        val voiceCommandAvailable = hasRecordAudioPermission() &&
            when (snapshot.state) {
                WalkSessionState.ACTIVE -> !oneShotSpeechRecognitionLimited
                WalkSessionState.PAUSED -> voiceResumeConfirmationAvailable()
                WalkSessionState.READY, WalkSessionState.SAFE_STOP, WalkSessionState.ENDED ->
                    homeVoiceCommandAvailable()
                else -> false
            }
        val enabled = if (gatewayRecording) {
            snapshot.isForeground && isActivityForeground
        } else {
            !active &&
                !responsePending &&
                !handsFreeVoiceModelPreparing &&
                !gatewayProcessing &&
                snapshot.isForeground &&
                voiceCommandAvailable
        }
        val voiceCommandUnavailable = !gatewayRecording && !gatewayProcessing &&
            !active &&
            snapshot.state in setOf(
                WalkSessionState.ACTIVE, WalkSessionState.PAUSED, WalkSessionState.READY,
                WalkSessionState.SAFE_STOP, WalkSessionState.ENDED,
            ) &&
            !voiceCommandAvailable
        listOf(voiceReportButton, walkSafetyVoiceButton).forEach { button ->
            button.text = when {
                gatewayRecording -> "음성 듣는 중"
                gatewayProcessing -> "음성 처리 중"
                responsePending -> "음성 안내 처리 중"
                active -> "음성 듣는 중"
                handsFreeVoiceModelPreparing -> "음성 모델 준비 중"
                voiceCommandUnavailable -> "음성 명령 제한"
                else -> "음성 명령"
            }
            button.contentDescription = when {
                gatewayRecording -> "음성 명령 녹음 중지"
                gatewayProcessing -> "음성 명령 처리 중"
                responsePending -> "음성 안내가 끝난 뒤 다시 입력할 수 있습니다"
                active -> "음성 명령을 듣는 중"
                handsFreeVoiceModelPreparing -> "음성 모델을 준비하고 있습니다"
                voiceCommandUnavailable -> "음성 명령을 사용할 수 없음"
                else -> "음성 명령 듣기 시작"
            }
            button.isEnabled = enabled
        }
        refreshHomeCards()
    }

    private fun updateVoiceRecognitionSignal(label: String) {
        if (!::voiceReportButton.isInitialized || !::walkSafetyVoiceButton.isInitialized) return
        listOf(voiceReportButton, walkSafetyVoiceButton).forEach { button ->
            button.text = label
            button.contentDescription = label
        }
        updateGatewayVoiceStatus(label)
        updateNavigationStatus("voice=${label.toStatusToken(maxLength = 32)}")
    }

    @SuppressLint("MissingPermission")
    private fun startLocationUpdatesIfAllowed(forceRestart: Boolean = false) {
        val owner = currentLocationCollectionOwnerOrNull() ?: run {
            stopLocationUpdates()
            return
        }
        if (!::fusedLocationClient.isInitialized) return
        if (!forceRestart && locationCallback != null && locationCollectionOwner == owner) {
            startPositioningObservationSources()
            return
        }
        if (locationCallback != null) {
            stopLocationUpdates(stopFieldSession = false)
        }
        val generation = ++locationCallbackGeneration
        locationCollectionOwner = owner
        lateinit var callback: LocationCallback
        callback = object : LocationCallback() {
            override fun onLocationResult(result: LocationResult) {
                if (!isLocationCallbackCurrent(owner, generation, callback)) return
                result.lastLocation?.let { location ->
                    handleLocationUpdate(location, owner, generation)
                }
            }

            override fun onLocationAvailability(availability: LocationAvailability) {
                if (!isLocationCallbackCurrent(owner, generation, callback)) return
                if (!availability.isLocationAvailable) {
                    walkSessionLifecycle.currentRuntimeEpochOrNull()?.let { walkEpoch ->
                        recordOfficialEnvironmentGpsObservation(
                            epoch = walkEpoch,
                            observedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                            trustedFixAvailable = false,
                            horizontalAccuracyMeters = null,
                        )
                    }
                    clearTrustedLocation()
                    if (!currentNavigationCollectionAllowsWork() &&
                        !currentPositionFieldCollectionAllowsWork()
                    ) return
                    val positionDecisionRequired = handlePositioningUnavailable(
                        elapsedRealtimeMs = SystemClock.elapsedRealtime(),
                    )
                    updateNavigationStatus("navigation=gps_unavailable")
                    if (!positionDecisionRequired) {
                        pauseDirectionGuidance(
                            reason = "gps_unavailable",
                            message = "GPS 위치를 확인할 수 없어 방향 안내를 중지했습니다.",
                        )
                    }
                }
            }
        }
        locationCallback = callback
        startPositioningObservationSources()
        val request = LocationRequest.Builder(Priority.PRIORITY_HIGH_ACCURACY, LOCATION_UPDATE_INTERVAL_MS)
            .setMinUpdateIntervalMillis(LOCATION_FASTEST_INTERVAL_MS)
            .setGranularity(Granularity.GRANULARITY_FINE)
            .setMaxUpdateAgeMillis(0L)
            .build()
        try {
            fusedLocationClient.requestLocationUpdates(request, callback, Looper.getMainLooper())
        } catch (_: SecurityException) {
            val navigationWasAllowed = currentNavigationCollectionAllowsWork()
            stopLocationUpdates()
            if (!navigationWasAllowed) return
            val positionDecisionRequired = handlePositioningUnavailable(
                elapsedRealtimeMs = SystemClock.elapsedRealtime(),
            )
            updateNavigationStatus("navigation=gps_permission_revoked")
            if (!positionDecisionRequired) {
                pauseDirectionGuidance(
                    reason = "location_permission_revoked",
                    message = "정확한 위치 권한이 해제되어 방향 안내를 중지했습니다.",
                )
            }
        }
    }

    private fun stopLocationUpdates(stopFieldSession: Boolean = true) {
        if (stopFieldSession) stopActivePositionFieldSession()
        locationCallbackGeneration += 1
        val callback = locationCallback
        locationCallback = null
        locationCollectionOwner = null
        latestNavigationTestLocation = null
        if (::fusedLocationClient.isInitialized) {
            callback?.let { registeredCallback ->
                runCatching { fusedLocationClient.removeLocationUpdates(registeredCallback) }
            }
        }
        gnssQualityObserver?.close()
        gnssQualityObserver = null
        pedestrianMotionTracker?.close()
        pedestrianMotionTracker = null
        latestGnssQualitySnapshot = null
        latestWalkingSpeedObservation = null
        latestGpsCourseObservation = null
        latestRawRouteLocation = null
        positionGuidancePaused = false
        orientationLocationOwnerActive = false
        stopRouteCompassPresentationUpdates()
        refreshRouteCompassPresentation()
        lastRouteCompassStatusKey = null
        if (::earthOrientationTracker.isInitialized) earthOrientationTracker.clearGeomagneticReference()
        if (::earthOrientationTracker.isInitialized && session == null && !cameraFallbackRunning) {
            earthOrientationTracker.stop()
        }
        positioningCoordinator.reset()
        clearTrustedLocation()
    }

    private fun isLocationCallbackCurrent(
        owner: LocationCollectionOwner,
        generation: Int,
        callback: LocationCallback,
    ): Boolean =
        locationCallback === callback &&
            generation == locationCallbackGeneration &&
            locationCollectionOwner == owner &&
            currentLocationCollectionOwnerOrNull() == owner

    private fun currentRouteLocationOrNull(): TrustedLocation? {
        if (!developmentGuidanceStartBypassEnabled) return freshTrustedLocationOrNull()
        if (locationCollectionOwner == null ||
            currentLocationCollectionOwnerOrNull() != locationCollectionOwner
        ) return null
        return NavigationTestLocationPolicy.freshOrNull(
            latestNavigationTestLocation,
            SystemClock.elapsedRealtime(),
        )
    }

    private fun freshTrustedLocationOrNull(
        nowElapsedRealtimeMs: Long = SystemClock.elapsedRealtime(),
    ): TrustedLocation? {
        if (locationCollectionOwner == null ||
            currentLocationCollectionOwnerOrNull() != locationCollectionOwner
        ) {
            clearTrustedLocation()
            return null
        }
        val current = latestTrustedLocation
        val fresh = LocationTrustPolicy.freshOrNull(current, nowElapsedRealtimeMs)
        if (current != null && fresh == null) {
            latestTrustedLocation = null
            latestRawRouteLocation = null
            clearLocationDerivedState()
            if (currentNavigationCollectionAllowsWork() &&
                !handlePositioningUnavailable(nowElapsedRealtimeMs)
            ) {
                pauseDirectionGuidance(
                    reason = "gps_stale",
                    message = "GPS 위치가 오래되어 방향 안내를 중지했습니다.",
                )
            }
        }
        return fresh
    }

    private fun clearTrustedLocation(): Boolean {
        latestTrustedLocation = null
        latestRawRouteLocation = null
        clearLocationDerivedState()
        return false
    }

    private fun handleRouteLocationUntrusted(): Boolean {
        val update = routeNavigator.onUntrustedLocation() ?: return false
        if (Looper.myLooper() == Looper.getMainLooper()) {
            applyRouteDeviationSafetyUpdate(update)
        } else {
            val expectedToken = routeNavigator.pendingDecisionToken()
            runOnUiThread {
                if (expectedToken == routeNavigator.pendingDecisionToken()) {
                    applyRouteDeviationSafetyUpdate(update)
                }
            }
        }
        return true
    }

    private fun clearLocationDerivedState() {
        latestGpsMotionInputs = null
        gpsMotionInputHistory.clear()
        lastPositionZuptAtElapsedMs = null
        lastPositionFieldTelemetryAtElapsedMs = null
        latestWalkingSpeedObservation = null
        latestGpsCourseObservation = null
        latestHeadingDeg = null
        walkingCalibrationSegments.reset()
    }

    private fun startStepTrackingIfAllowed() {
        if (!currentStepTrackingCollectionAllowsWork()) {
            stopStepTracking()
            return
        }
        if (!::stepTracker.isInitialized) return
        if (!hasActivityRecognitionPermission()) {
            updateNavigationStatus("navigation=activity_recognition_permission_missing step_fallback_wait")
            return
        }
        stepTrackingEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull()
        stepTracker.start()
    }

    private fun stopStepTracking() {
        stepTrackingEpoch = null
        val retainedForReportQueueDrain = synchronized(reportQueueDrainLock) {
            reportQueueDrainTrigger != null
        }
        if (retainedForReportQueueDrain) return
        stopStepTrackingNow()
    }

    private fun stopStepTrackingNow() {
        activityOriginalUploadAdmission.onTrackingStopped(
            ::cancelActivityOriginalUploads,
        )
        if (!::stepTracker.isInitialized) return
        val stop = { stepTracker.stop() }
        if (Looper.myLooper() == Looper.getMainLooper()) {
            stop()
        } else {
            runOnUiThread {
                val drainCleared = synchronized(reportQueueDrainLock) {
                    reportQueueDrainTrigger == null
                }
                if (drainCleared && stepTrackingEpoch == null) stop()
            }
        }
    }

    private fun startPositioningObservationSources() {
        if (
            ContextCompat.checkSelfPermission(this, Manifest.permission.ACCESS_FINE_LOCATION) !=
            PackageManager.PERMISSION_GRANTED
        ) return
        val owner = locationCollectionOwner ?: return
        val generation = locationCallbackGeneration
        val callback = locationCallback ?: return
        if (!isLocationCallbackCurrent(owner, generation, callback)) return
        ensurePositioningProfileForCurrentActor()
        ensureEarthOrientationForLocation()
        if (gnssQualityObserver == null) {
            val locationManager = getSystemService(LOCATION_SERVICE) as LocationManager
            gnssQualityObserver = GnssQualityObserver(
                source = AndroidGnssObservationSource(
                    locationManager = locationManager,
                    executor = ContextCompat.getMainExecutor(this),
                ),
                onSnapshot = { snapshot ->
                    if (isLocationCallbackCurrent(owner, generation, callback)) {
                        latestGnssQualitySnapshot = snapshot
                    }
                },
            )
        }
        runCatching { gnssQualityObserver?.start() }
        if (!currentNavigationCollectionAllowsWork() &&
            !currentPositionFieldCollectionAllowsWork()
        ) {
            pedestrianMotionTracker?.stop()
            return
        }
        if (pedestrianMotionTracker == null) {
            pedestrianMotionTracker = AndroidPedestrianMotionTracker(this) motion@{ decision ->
                if (!isLocationCallbackCurrent(owner, generation, callback)) return@motion
                if (!currentNavigationCollectionAllowsWork() &&
                    !currentPositionFieldCollectionAllowsWork()
                ) return@motion
                val nowMs = SystemClock.elapsedRealtime()
                if (decision.accepted) {
                    latestPositionStationaryState = when (decision.state.name) {
                        "MOVING" -> PositionStationaryState.MOVING
                        "CANDIDATE" -> PositionStationaryState.CANDIDATE
                        "STATIONARY" -> PositionStationaryState.STATIONARY
                        else -> PositionStationaryState.UNKNOWN
                    }
                    latestPositionStationarySinceMs = when (latestPositionStationaryState) {
                        PositionStationaryState.CANDIDATE,
                        PositionStationaryState.STATIONARY,
                        -> decision.candidateSinceElapsedRealtimeMs ?: nowMs
                        else -> nowMs
                    }
                }
                if (decision.accepted && !decision.shouldApplyZeroVelocityUpdate) {
                    lastPositionZuptAtElapsedMs = null
                }
                val zuptDue = lastPositionZuptAtElapsedMs?.let { nowMs - it >= 1_000L } ?: true
                val zuptSnapshot = if (
                    decision.shouldApplyZeroVelocityUpdate && zuptDue &&
                    (
                        currentNavigationCollectionAllowsWork() ||
                            currentPositionFieldLeaseOrNull() != null
                    )
                ) {
                    lastPositionZuptAtElapsedMs = nowMs
                    positioningCoordinator.observeZupt(
                        ZuptObservation(nowMs),
                    )
                } else {
                    null
                }
                zuptSnapshot?.let(::applyPositioningMotionSnapshot)
                val telemetryDue = lastPositionFieldTelemetryAtElapsedMs
                    ?.let { nowMs - it >= 1_000L } ?: true
                if (currentPositionFieldCollectionAllowsWork() &&
                    (zuptSnapshot != null || decision.stateChanged || telemetryDue)
                ) {
                    lastPositionFieldTelemetryAtElapsedMs = nowMs
                    appendPositionFieldMotionTrace(
                        snapshot = zuptSnapshot,
                        stepDetected = false,
                        zuptApplied = zuptSnapshot != null,
                        measurementElapsedRealtimeMs = nowMs,
                    )
                }
            }
        }
        runCatching { pedestrianMotionTracker?.start() }
    }

    private fun ensurePositioningProfileForCurrentActor() {
        val actorId = locationCollectionOwner?.actorId ?: currentReporterUserId()
        if (positioningProfileLoaded && actorId == positioningProfileActorId) return
        positioningCoordinator = PositioningCoordinator()
        positioningProfileActorId = actorId
        positioningProfileLoaded = true
        walkingCalibrationSegments.reset()
        if (pedestrianProfileStore == null && ::stepLengthPrefs.isInitialized) {
            pedestrianProfileStore = runCatching {
                AndroidPedestrianProfileStore(stepLengthPrefs)
            }.getOrNull()
        }
        val restored = actorId?.let { id ->
            runCatching { pedestrianProfileStore?.load(id) }.getOrNull()
        }
        restored?.let(positioningCoordinator::restoreProfile)
        val stepLengthM = positioningCoordinator.currentProfile().stepLengthM.toFloat()
        stepLengthEstimator.setStepLengthM(stepLengthM)
        objectDepthPipeline.setUserStepLength(stepLengthM)
        currentObjectDepthPipeline.setUserStepLength(stepLengthM)
    }

    private fun persistPositioningProfileForCurrentActor() {
        val actorId = currentReporterUserId() ?: return
        if (actorId != positioningProfileActorId) return
        val profile = positioningCoordinator.snapshotProfileForPersistence() ?: return
        runCatching { pedestrianProfileStore?.save(actorId, profile) }
    }

    private fun updatePositioningHeadingInputs(location: Location, elapsedRealtimeMs: Long) {
        if (latestGpsMotionInputs?.evidence?.observedAtElapsedRealtimeMs
                ?.let { elapsedRealtimeMs <= it } == true
        ) return
        val speedAccuracy = if (
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.O && location.hasSpeedAccuracy()
        ) location.speedAccuracyMetersPerSecond.toDouble() else null
        latestWalkingSpeedObservation = location.speed
            .takeIf { location.hasSpeed() && it.isFinite() && it >= 0f }
            ?.let { speed ->
                WalkingSpeedObservation(
                    speedMps = speed.toDouble(),
                    accuracyMps = speedAccuracy,
                    elapsedRealtimeMs = elapsedRealtimeMs,
                )
            }
        val bearingAccuracy = if (
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.O && location.hasBearingAccuracy()
        ) {
            location.bearingAccuracyDegrees.toDouble()
                .takeIf { it.isFinite() && it in 0.0..45.0 }
        } else {
            null
        }
        latestGpsCourseObservation = location.bearing
            .takeIf {
                location.hasBearing() &&
                    it.isFinite() &&
                    bearingAccuracy != null
            }
            ?.let { bearing ->
                HeadingObservation(
                    headingDegreesTrueNorth = bearing.toDouble(),
                    accuracyDegrees = bearingAccuracy,
                    elapsedRealtimeMs = elapsedRealtimeMs,
                )
            }
        // Publish one immutable fix to the GL thread; speed/course may never come from different fixes.
        val inputs = GpsMotionInputs(
            speed = latestWalkingSpeedObservation,
            course = latestGpsCourseObservation,
            evidence = UserMotionLocationEvidence(
                observedAtElapsedRealtimeMs = elapsedRealtimeMs,
                horizontalAccuracyM = location.accuracy.toDouble().takeIf { location.hasAccuracy() },
                isMock = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) location.isMock
                    else location.isFromMockProvider,
            ),
        )
        latestGpsMotionInputs = inputs
        gpsMotionInputHistory.addLast(inputs)
        while (gpsMotionInputHistory.size > 64 || gpsMotionInputHistory.firstOrNull()?.let {
                elapsedRealtimeMs - it.evidence.observedAtElapsedRealtimeMs > 5_000L
            } == true
        ) gpsMotionInputHistory.removeFirst()
    }

    private fun handlePositioningStepEvent(event: StepEvent) {
        if (
            !currentNavigationCollectionAllowsWork() &&
            currentPositionFieldLeaseOrNull() == null
        ) return
        ensurePositioningProfileForCurrentActor()
        pedestrianMotionTracker?.recordStep(event.timestampMs)
        walkingCalibrationSegments.onStep(
            timestampMs = event.timestampMs,
            deltaSteps = event.deltaSteps,
            individualStepDetector = event.source == StepEventSource.STEP_DETECTOR &&
                event.confidence == StepEventConfidence.HIGH,
            receivedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
        ).forEach(::applyWalkingCalibrationSample)
        val quality = when (event.confidence) {
            StepEventConfidence.HIGH -> PdrStepQuality.HIGH
            StepEventConfidence.MEDIUM -> PdrStepQuality.MEDIUM
            StepEventConfidence.LOW -> PdrStepQuality.LOW
        }
        val chestHeading = chestMountedHeadingForStep(event.timestampMs)
        val gpsAtStep = gpsMotionInputHistory.lastOrNull {
            it.evidence.observedAtElapsedRealtimeMs <= event.timestampMs
        }
        val courseAtStep = gpsAtStep?.course
        val chestAtCourse = if (chestHeading != null && courseAtStep != null) {
            chestMountedHeadingForStep(courseAtStep.elapsedRealtimeMs, maximumAgeMs = 100L)
        } else null
        val snapshot = positioningCoordinator.observeStep(
                stepCount = event.deltaSteps,
                headingInput = PedestrianHeadingInput(
                    nowElapsedRealtimeMs = event.timestampMs,
                    speed = gpsAtStep?.speed,
                    gpsCourse = courseAtStep,
                    magneticTrueHeading = chestHeading,
                    magneticTrueHeadingAtGpsCourse = chestAtCourse,
                    phoneForwardMounted = chestHeading != null,
                ),
                quality = quality,
                receivedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
            )
        applyPositioningMotionSnapshot(snapshot)
        appendPositionFieldMotionTrace(
            snapshot = snapshot,
            stepDetected = true,
            zuptApplied = false,
            measurementElapsedRealtimeMs = event.timestampMs,
        )
    }

    private fun ensureEarthOrientationForLocation() {
        if (!::earthOrientationTracker.isInitialized) return
        orientationLocationOwnerActive = true
        earthOrientationTracker.start()
        scheduleRouteCompassPresentationUpdate()
    }

    /** A route/camera owner ending must not clear the authenticated location owner's compass. */
    private fun retainLocationCompassOrStop() {
        if (!::earthOrientationTracker.isInitialized) return
        val owner = locationCollectionOwner
        if (orientationLocationOwnerActive && locationCallback != null && owner != null &&
            currentLocationCollectionOwnerOrNull() == owner
        ) {
            ensureEarthOrientationForLocation()
        } else {
            earthOrientationTracker.stop()
        }
    }

    private fun scheduleRouteCompassPresentationUpdate() {
        if (pendingRouteCompassRefresh != null || !::nativeHomeCompassText.isInitialized) return
        val owner = locationCollectionOwner ?: return
        val generation = locationCallbackGeneration
        if (!isActivityForeground || !orientationLocationOwnerActive || locationCallback == null ||
            currentLocationCollectionOwnerOrNull() != owner
        ) return
        lateinit var refresh: Runnable
        refresh = Runnable {
            if (pendingRouteCompassRefresh !== refresh) return@Runnable
            pendingRouteCompassRefresh = null
            if (!isActivityForeground || !orientationLocationOwnerActive || locationCallback == null ||
                locationCollectionOwner != owner || locationCallbackGeneration != generation ||
                currentLocationCollectionOwnerOrNull() != owner
            ) return@Runnable
            // Observe even before a route exists; do not start TTS or speech recognition here.
            currentRouteFacingObservation(SystemClock.elapsedRealtime())
            refreshRouteCompassPresentation()
            scheduleRouteCompassPresentationUpdate()
        }
        pendingRouteCompassRefresh = refresh
        if (!nativeHomeCompassText.postDelayed(refresh, 500L)) pendingRouteCompassRefresh = null
    }

    private fun stopRouteCompassPresentationUpdates() {
        pendingRouteCompassRefresh?.let { callback ->
            if (::nativeHomeCompassText.isInitialized) nativeHomeCompassText.removeCallbacks(callback)
        }
        pendingRouteCompassRefresh = null
    }

    private fun refreshRouteCompassPresentation() {
        if (!::nativeHomeCompassText.isInitialized) return
        val message = routeCompassStatusMessage()
        if (nativeHomeCompassText.text.toString() != message) nativeHomeCompassText.text = message
        refreshHomeRouteStatus()
        scheduleRouteCompassPresentationUpdate()
    }

    private fun refreshHomeRouteStatus() {
        if (!::nativeHomeRouteStatusText.isInitialized) return
        if (Looper.myLooper() != Looper.getMainLooper()) {
            runOnUiThread { if (isActivityForeground) refreshHomeRouteStatus() }
            return
        }
        val message = homeRouteStatusMessage()
        if (nativeHomeRouteStatusText.text.toString() != message) nativeHomeRouteStatusText.text = message
    }

    private fun homeRouteStatusMessage(): String = when {
        routeRequestInFlight.get() -> "길안내: 목적지까지의 경로를 찾고 있습니다."
        isRouteActive && routeNavigator.hasRoute() -> "길안내: 목적지까지의 경로가 설정되었습니다."
        isRouteActive -> "길안내: 경로 확인이 필요합니다. 안내를 다시 시작해 주세요."
        latestNavigationState in setOf("navigation=route_failed", "navigation=reroute_failed") ->
            "길안내: 경로 요청을 완료하지 못했습니다. 안내를 다시 시작해 주세요."
        currentDestination != null || pendingUiDestination != null -> "길안내: 목적지가 선택되었습니다."
        else -> "길안내: 목적지를 선택해 주세요."
    }

    /** Route speech follows the rear camera axis; step/PDR mounting confirmation stays separate. */
    private fun currentRouteFacingObservation(nowMs: Long): RouteFacingObservation? {
        if (!isActivityForeground || !::earthOrientationTracker.isInitialized ||
            !orientationLocationOwnerActive || locationCallback == null || locationCollectionOwner == null ||
            currentLocationCollectionOwnerOrNull() != locationCollectionOwner
        ) return null
        val facing = earthOrientationTracker.latestRouteCompassHeading(nowMs)
        val observation = facing.observation
        val statusKey = "${facing.reason}:${observation?.source}"
        if (lastRouteCompassStatusKey != statusKey) {
            lastRouteCompassStatusKey = statusKey
            if (BuildConfig.DEBUG) runCatching {
                android.util.Log.d("WalkSafeNavigation", "compass=$statusKey heading=${observation?.degreesTrueNorth}")
            }
            if (::fieldSessionLog.isInitialized) {
                fieldSessionLog.recordEvent("route_compass_state_changed", mapOf(
                    "reason" to facing.reason.name,
                    "source" to observation?.source?.name,
                    "headingTrueNorthDeg" to observation?.degreesTrueNorth,
                    "reportedHeadingAccuracyDeg" to observation?.reportedHeadingAccuracyDegrees,
                    "sampleAgeMs" to observation?.let { nowMs - it.observedAtElapsedRealtimeMs },
                ))
            }
        }
        return observation
    }

    private fun routeCompassStatusMessage(): String {
        if (!isActivityForeground || !::earthOrientationTracker.isInitialized ||
            !orientationLocationOwnerActive || locationCallback == null || locationCollectionOwner == null ||
            currentLocationCollectionOwnerOrNull() != locationCollectionOwner
        ) return "위치 측정과 함께 나침반 방향을 준비합니다."
        val result = earthOrientationTracker.latestRouteCompassHeading(SystemClock.elapsedRealtime())
        result.observation?.let { observation ->
            val labels = listOf("북", "북동", "동", "남동", "남", "남서", "서", "북서")
            val index = ((observation.degreesTrueNorth + 22.5) / 45.0).toInt() % labels.size
            val degrees = observation.degreesTrueNorth.roundToInt() % 360
            val source = if (observation.source == RouteFacingSource.ROTATION_VECTOR) "" else " 보조 나침반 사용 중."
            return "나침반: 휴대폰 후면은 ${labels[index]}쪽(${degrees}도)을 향하고 있습니다.$source"
        }
        return when (result.reason) {
            RouteCompassHeadingReason.SENSOR_UNAVAILABLE -> "나침반 센서를 시작하지 못했습니다."
            RouteCompassHeadingReason.HEADING_ACCURACY_UNAVAILABLE -> "나침반 센서가 방향 오차 정보를 아직 제공하지 않습니다."
            RouteCompassHeadingReason.REFERENCE_MISSING -> "현재 위치를 확인해 나침반의 진북 기준을 맞추고 있습니다."
            RouteCompassHeadingReason.REAR_AXIS_VERTICAL -> "휴대폰 후면이 바닥이나 하늘을 향하고 있습니다. 후면을 걷는 방향으로 들어 주세요."
            RouteCompassHeadingReason.GRAVITY_MISSING, RouteCompassHeadingReason.MAGNETIC_FIELD_MISSING ->
                "보조 나침반에 필요한 센서 값을 기다리고 있습니다."
            RouteCompassHeadingReason.GRAVITY_UNSTABLE ->
                "휴대폰 움직임이 커서 방향을 다시 확인하고 있습니다. 잠시 안정적으로 잡아 주세요."
            RouteCompassHeadingReason.QUALITY_LOW, RouteCompassHeadingReason.HEADING_ACCURACY,
            RouteCompassHeadingReason.MAGNETIC_FIELD_ANOMALY ->
                "나침반 방향이 불안정합니다. 자석·금속에서 떨어져 휴대폰을 천천히 움직여 주세요."
            else -> "새 나침반 방향을 기다리고 있습니다."
        }
    }

    private fun updateRouteOrientationReference(location: Location) {
        if (!::earthOrientationTracker.isInitialized) return
        ensureEarthOrientationForLocation()
        earthOrientationTracker.updateGeomagneticReference(
            latitudeDegrees = location.latitude,
            longitudeDegrees = location.longitude,
            altitudeMeters = location.altitude
                .takeIf { location.hasAltitude() && it.isFinite() } ?: 0.0,
            timeMillis = System.currentTimeMillis(),
        )
    }

    private fun chestMountedHeadingForStep(
        timestampMs: Long,
        maximumAgeMs: Long = 500L,
    ): HeadingObservation? {
        if (!::earthOrientationTracker.isInitialized) return null
        val walkEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return null
        val explicitFieldConfirmation = positionFieldExplicitChestConfirmed &&
            currentPositionFieldLeaseOrNull() != null
        val existingChestMount = phoneMountingOutputsAllowed &&
            phoneMountingRuntimeState?.epoch == walkEpoch &&
            phoneMountingUserConfirmation?.epoch == walkEpoch &&
            phoneMountingUserConfirmation?.method == PhoneMountingMethod.CHEST_FORWARD
        if (!explicitFieldConfirmation && !existingChestMount) return null
        return earthOrientationTracker.chestMountedHeadingAt(timestampMs, maximumAgeMs)
    }

    private fun applyPositioningMotionSnapshot(snapshot: PositioningSnapshot) {
        val filtered = snapshot.filtered ?: return
        latestTrustedLocation = filtered.toTrustedLocation()
        applyPositionConfidenceDecision(snapshot)
    }

    private fun handlePositioningUnavailable(elapsedRealtimeMs: Long): Boolean {
        val snapshot = positioningCoordinator.observeGnss(
            GnssPositionObservation(
                latitude = Double.NaN,
                longitude = Double.NaN,
                horizontalAccuracyM = null,
                elapsedRealtimeMs = elapsedRealtimeMs,
                receivedAtElapsedRealtimeMs = elapsedRealtimeMs,
            ),
        )
        return applyPositionConfidenceDecision(snapshot)
    }

    private fun applyPositionConfidenceDecision(snapshot: PositioningSnapshot): Boolean {
        if (developmentGuidanceStartBypassEnabled) {
            positionGuidancePaused = false
            return false
        }
        val decision = snapshot.confidence
        val pauseReason = "position_quality_${decision.quality.name.lowercase(Locale.US)}"
        val positioningEvidenceInterrupted =
            decision.quality in setOf(PositionQuality.LOW, PositionQuality.UNAVAILABLE) &&
                decision.previousQuality != decision.quality
        if (positioningEvidenceInterrupted) {
            routeNavigator.onPositioningEvidenceInterrupted()
        }
        positionGuidancePaused = decision.guidancePaused
        if (positionGuidancePaused && isRouteActive) {
            feedbackActuator?.cancelNavigationSpeech()
            latestTmapOnRoute = false
            updateNavigationStatus("navigation=direction_paused reason=$pauseReason")
        }
        decision.announcementRequest?.let { request ->
            val message = when (request.kind) {
                PositionConfidenceAnnouncementKind.LOW ->
                    "위치 정확도가 낮아 방향 안내를 잠시 중지합니다."
                PositionConfidenceAnnouncementKind.UNAVAILABLE ->
                    "위치를 확인할 수 없어 방향 안내를 중지합니다."
                PositionConfidenceAnnouncementKind.RECOVERED ->
                    "위치 신뢰도가 회복되어 방향 안내를 다시 시작합니다."
            }
            if (request.kind != PositionConfidenceAnnouncementKind.RECOVERED) {
                ensureFeedbackActuator().playRouteGuidancePausedVibration()
            }
            val speechDelivered = speakInteraction(message)
            if (speechDelivered || request.kind != PositionConfidenceAnnouncementKind.RECOVERED) {
                positioningCoordinator.commitAnnouncementDelivered(
                    request.token,
                    SystemClock.elapsedRealtime(),
                )
            }
        }
        return decision.guidancePaused
    }

    private fun PositioningFilteredFix.toTrustedLocation(): TrustedLocation = TrustedLocation(
        latitude = coordinate.latitude,
        longitude = coordinate.longitude,
        accuracyM = horizontalUncertaintyM.toFloat(),
        elapsedRealtimeMs = elapsedRealtimeMs,
    )

    /** Coordinates GPS, pedestrian motion, and confidence before app consumers use a fix. */
    private fun explicitRouteStartContextOrNull(
        destination: RoutePoint,
    ): ExplicitRouteStartContext? {
        if (!isActivityForeground || !currentNavigationCollectionAllowsWork()) return null
        val walkEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return null
        val gateway = GatewaySessionProcessCoordinator.snapshot()
        if (gateway.session == null || gateway.deletionRecoveryOnly || gateway.storageBlocked) {
            return null
        }
        if (currentDestination != destination) return null
        return ExplicitRouteStartContext(
            walkSessionId = walkEpoch.walkSessionId,
            gatewayGeneration = gateway.generation,
            destination = destination,
        )
    }

    private fun retainPendingExplicitRouteStart(destination: RoutePoint): Boolean {
        val context = explicitRouteStartContextOrNull(destination) ?: return false
        clearPendingExplicitRouteStart()
        val request = pendingExplicitRouteStart.replace(
            context,
            SystemClock.elapsedRealtime(),
        )
        lateinit var timeout: Runnable
        timeout = Runnable {
            if (pendingExplicitRouteStartTimeout !== timeout) return@Runnable
            pendingExplicitRouteStartTimeout = null
            val current = explicitRouteStartContextOrNull(context.destination)
            if (current == null) {
                pendingExplicitRouteStart.cancel()
                return@Runnable
            }
            if (!pendingExplicitRouteStart.expireIfCurrent(
                    request,
                    current,
                    SystemClock.elapsedRealtime(),
                )
            ) return@Runnable
            val detail =
                "현재 위치를 확인하지 못했습니다. 선택한 목적지는 유지했습니다. " +
                    "GPS를 확인한 뒤 안내 시작을 다시 선택하세요."
            updateNavigationStatus(
                "navigation=route_waiting trusted_gps_missing timeout explicit_start_required",
            )
            updateStatus("현재 위치 확인 필요", detail)
            speakStatusExplanation(detail)
        }
        pendingExplicitRouteStartTimeout = timeout
        nativeDestinationConfirmationText.postDelayed(
            timeout,
            ROUTE_START_LOCATION_TIMEOUT_MS,
        )
        return true
    }

    private fun continuePendingExplicitRouteStartIfReady() {
        val request = pendingExplicitRouteStart.currentOrNull() ?: return
        val current = explicitRouteStartContextOrNull(request.context.destination)
        if (current == null) {
            clearPendingExplicitRouteStart()
            return
        }
        if (currentRouteLocationOrNull() == null) return
        val retained = pendingExplicitRouteStart.consumeIfCurrent(
            current,
            SystemClock.elapsedRealtime(),
        ) ?: return
        pendingExplicitRouteStartTimeout?.let(nativeDestinationConfirmationText::removeCallbacks)
        pendingExplicitRouteStartTimeout = null
        val generationBefore = routeRequestGeneration
        requestRoute(retained.destination, reason = "user_destination")
        if (routeRequestGeneration != generationBefore && routeRequestInFlight.get()) {
            clearNativeDestinationSearchState()
            showNativeUiPage(NativeUiPage.HOME)
        }
    }

    private fun clearPendingExplicitRouteStart() {
        pendingExplicitRouteStart.cancel()
        if (::nativeDestinationConfirmationText.isInitialized) {
            pendingExplicitRouteStartTimeout?.let(
                nativeDestinationConfirmationText::removeCallbacks,
            )
        }
        pendingExplicitRouteStartTimeout = null
    }

    private fun handleLocationUpdate(
        location: Location,
        owner: LocationCollectionOwner,
        locationGeneration: Int,
    ) {
        if (
            locationCollectionOwner != owner ||
            currentLocationCollectionOwnerOrNull() != owner ||
            locationGeneration != locationCallbackGeneration ||
            !currentLocationCollectionAllowsWork()
        ) return
        ensurePositioningProfileForCurrentActor()
        val accuracy = if (location.hasAccuracy()) location.accuracy else null
        val elapsedMs = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN_MR1) {
            location.elapsedRealtimeNanos / 1_000_000L
        } else {
            SystemClock.elapsedRealtime()
        }
        val mock = isMockLocationCompat(location)
        // Declination needs a fresh geographic reference, not a metre-accurate walking fix.
        // Set it before PDR filtering, including while logged in without an active route.
        if (RouteCompassLocationReference.accepts(
                location.latitude, location.longitude, elapsedMs,
                SystemClock.elapsedRealtime(), mock,
            )
        ) updateRouteOrientationReference(location)
        val currentGnssQualitySnapshot = runCatching {
            gnssQualityObserver?.snapshot(SystemClock.elapsedRealtimeNanos())
        }.getOrNull()
        latestGnssQualitySnapshot = currentGnssQualitySnapshot
        val measurementNoiseMultiplier = currentGnssQualitySnapshot
            ?.measurementNoiseMultiplier
            ?.takeIf { it.isFinite() && it >= 1.0 }
            ?: 1.0
        val effectiveAccuracyM = accuracy
            ?.takeIf { it.isFinite() && it >= 0f }
            ?.toDouble()
            ?.times(kotlin.math.sqrt(measurementNoiseMultiplier))
        var positioningSnapshot = positioningCoordinator.observeGnss(
            GnssPositionObservation(
                latitude = location.latitude,
                longitude = location.longitude,
                horizontalAccuracyM = effectiveAccuracyM,
                elapsedRealtimeMs = elapsedMs,
                receivedAtElapsedRealtimeMs = SystemClock.elapsedRealtime(),
                mock = mock,
            ),
        )
        currentGnssQualitySnapshot?.let { qualitySnapshot ->
            positioningSnapshot = positioningSnapshot.copy(
                raw = positioningSnapshot.raw?.copy(
                    reportedHorizontalAccuracyM = accuracy?.toDouble(),
                    effectiveHorizontalAccuracyM = effectiveAccuracyM,
                ),
                gnssQuality = qualitySnapshot,
            )
        }
        val filtered = positioningSnapshot.filtered
        val hardRejected = positioningSnapshot.gnssUpdate?.disposition ==
            GnssObservationDisposition.HARD_REJECTED
        if (BuildConfig.DEBUG) {
            positioningSnapshot.gnssUpdate?.let { update ->
                android.util.Log.d(
                    "WalkSafePositioning",
                    "gnss disposition=${update.disposition} reason=${update.hardRejectReason} " +
                        "ageMs=${SystemClock.elapsedRealtime() - elapsedMs} lagMs=${update.measurementLagMs} " +
                        "replayedMotion=${update.replayedMotionEventCount}",
                )
            }
        }
        walkSessionLifecycle.currentRuntimeEpochOrNull()?.let { walkEpoch ->
            recordOfficialEnvironmentGpsObservation(
                epoch = walkEpoch,
                observedAtElapsedRealtimeMs = elapsedMs,
                trustedFixAvailable = !hardRejected && filtered != null,
                horizontalAccuracyMeters = accuracy?.toDouble(),
            )
        }
        val navigationTestFix = if (developmentGuidanceStartBypassEnabled) {
            NavigationTestLocationPolicy.freshOrNull(
                TrustedLocation(location.latitude, location.longitude, accuracy ?: Float.MAX_VALUE, elapsedMs),
                SystemClock.elapsedRealtime(),
                mock = mock,
            )
        } else null
        latestNavigationTestLocation = navigationTestFix
        if (hardRejected || filtered == null) {
            clearTrustedLocation()
            if (navigationTestFix != null && currentNavigationCollectionAllowsWork()) {
                positionGuidancePaused = false
                continuePendingExplicitRouteStartIfReady()
                updateRouteGuidance(navigationTestFix, navigationTestFix)
                return
            }
            if (!currentNavigationCollectionAllowsWork() &&
                !currentPositionFieldCollectionAllowsWork()
            ) return
            val positionDecisionRequired = applyPositionConfidenceDecision(positioningSnapshot)
            val rejectedReason = if (mock) "gps_mock_rejected" else "gps_invalid_rejected"
            updateNavigationStatus(
                "navigation=$rejectedReason accuracy=${accuracy?.toInt() ?: "null"}m",
            )
            if (!positionDecisionRequired) {
                pauseDirectionGuidance(
                    reason = rejectedReason,
                    message = if (mock) {
                        "모의 위치를 사용할 수 없어 방향 안내를 중지했습니다."
                    } else {
                        "유효하지 않은 위치 정보로 방향 안내를 중지했습니다."
                    },
                )
            }
            return
        }
        updatePositioningHeadingInputs(location, elapsedMs)
        val filteredTrusted = filtered.toTrustedLocation()
        val rawRouteLocation = TrustedLocation(
            latitude = location.latitude,
            longitude = location.longitude,
            accuracyM = accuracy ?: Float.MAX_VALUE,
            elapsedRealtimeMs = elapsedMs,
        )
        latestTrustedLocation = filteredTrusted
        latestRawRouteLocation = rawRouteLocation
        if (!currentNavigationCollectionAllowsWork()) {
            if (currentPositionFieldCollectionAllowsWork()) {
                applyPositionConfidenceDecision(positioningSnapshot)
                appendPositionFieldGnssTrace(
                    snapshot = positioningSnapshot,
                    location = location,
                    matchedEvidenceCurrent = false,
                )
            }
            return
        }
        val positionGuidancePaused = applyPositionConfidenceDecision(positioningSnapshot)
        continuePendingExplicitRouteStartIfReady()
        reportLocationStartScheduled.set(false)
        latestHeadingDeg = latestGpsCourseObservation?.headingDegreesTrueNorth?.toFloat()
        attemptStepCalibration(location, positioningSnapshot)
        updateNavigationStatus(
            "navigation=position_${positioningSnapshot.quality.name.lowercase(Locale.US)} accuracy=${filteredTrusted.accuracyM.toInt()}m steps=$latestStepCount heading=${latestHeadingDeg?.let { String.format(Locale.US, "%.1f", it) } ?: "null"}",
        )
        if (isRouteActive && !routeRequestInFlight.get() && !routeNavigator.hasRoute()) {
            updateNavigationStatus("navigation=route_waiting user_route_decision_required trusted_gps_ready")
        }
        val matchedEvidenceCurrent = !positionGuidancePaused &&
            directionGuidancePauseReason != "tmap_unavailable"
        if (matchedEvidenceCurrent) {
            updateRouteGuidance(filteredTrusted, rawRouteLocation)
        }
        appendPositionFieldGnssTrace(
            snapshot = positioningSnapshot,
            location = location,
            matchedEvidenceCurrent = matchedEvidenceCurrent,
        )
    }

    private fun updateHeadingFromLocation(
        previous: TrustedLocation?,
        location: Location,
        trusted: TrustedLocation,
    ): Float? {
        val bearingAccuracy = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O && location.hasBearingAccuracy()) {
            location.bearingAccuracyDegrees
        } else {
            null
        }
        return reliableMovementHeadingDegrees(
            reportedBearingDeg = location.bearing.takeIf { location.hasBearing() },
            speedMps = location.speed.takeIf { location.hasSpeed() },
            bearingAccuracyDeg = bearingAccuracy,
            previous = previous,
            current = trusted,
        )
    }

    private fun currentUserMotionStatusText(): String {
        val nowMs = SystemClock.elapsedRealtime()
        val inputs = latestGpsMotionInputs
        val motion = UserMotionEstimateFactory.estimate(
            nowElapsedRealtimeMs = nowMs,
            speed = inputs?.speed,
            course = inputs?.course,
            phoneHeading = chestMountedHeadingForStep(nowMs),
            locationEvidence = inputs?.evidence,
        )
        fun number(value: Double?): String = value?.let { String.format(Locale.US, "%.1f", it) } ?: "unknown"
        return "userSpeed=${number(motion.speedMps)}m/s " +
            "travelCourse=${number(motion.courseDegreesTrueNorth)}deg " +
            "phoneHeading=${number(motion.phoneHeadingDegreesTrueNorth)}deg"
    }

    private fun buildDepthMotionContext(elapsedRealtimeMs: Long): MotionContext {
        // General obstacle confidence is independent of destination and route state. Route-bound
        // tactile guidance validates heading and corridor separately in TactileRoutePolicy.
        val freshness = freshTrustedLocationOrNull(elapsedRealtimeMs)?.let { trusted ->
            val ageMs = elapsedRealtimeMs - trusted.elapsedRealtimeMs
            when {
                ageMs < 0L -> 0.8f
                ageMs <= 2_500L -> 1f
                ageMs <= 7_500L -> 0.75f
                else -> 0.45f
            }
        } ?: 0.7f
        val gpsMotion = latestGpsMotionInputs
        return MotionContext(
            freshnessQuality = freshness,
            userMotion = UserMotionEstimateFactory.estimate(
                nowElapsedRealtimeMs = elapsedRealtimeMs,
                speed = gpsMotion?.speed,
                course = gpsMotion?.course,
                phoneHeading = chestMountedHeadingForStep(elapsedRealtimeMs),
                locationEvidence = gpsMotion?.evidence,
            ),
        )
    }

    internal fun processTactileSnapshotFrame(
        detectionSnapshot: DetectionSnapshot,
        nowMs: Long,
        currentFrameTimestampMs: Long,
        maxDetectionSourceAgeMs: Long,
        maxDetectionFrameDeltaMs: Long,
        detectionAgeMs: Long?,
        coordinator: AndroidTactileFrameCoordinator = tactileFrameCoordinator,
        processDepth: (DetectionFrameEvidence, List<DetectionCandidate>) -> List<TrackedObjectDepth>,
    ): TactileSnapshotFrameResult = coordinator.processSnapshot(
        detectionSnapshot = detectionSnapshot,
        nowMs = nowMs,
        currentFrameTimestampMs = currentFrameTimestampMs,
        maxDetectionSourceAgeMs = maxDetectionSourceAgeMs,
        maxDetectionFrameDeltaMs = maxDetectionFrameDeltaMs,
        detectionAgeMs = detectionAgeMs,
        navigationActiveNow = isRouteActive && !routeRequestInFlight.get(),
        tmapOnRouteNow = latestTmapOnRoute,
        activeRouteId = routeNavigator.currentRouteId(),
        processDepth = processDepth,
    )

