    internal fun <T> matchingFrameEvidenceOrNull(
        evidence: T?,
        identity: AndroidTactileFrameIdentity,
        context: TactileProjectionContext?,
        requireDepthMapper: Boolean,
    ): T? = tactileFrameCoordinator.matchingFrameEvidenceOrNull(
        evidence = evidence,
        identity = identity,
        context = context,
        requireDepthMapper = requireDepthMapper,
    )

    private fun buildTactileProjectionContext(
        frame: Frame,
        elapsedRealtimeMs: Long,
    ): TactileProjectionContext {
        val location = freshTrustedLocationOrNull(elapsedRealtimeMs)
        val expectedRouteId = routeNavigator.currentRouteId()
        val routeProjection = location?.let(routeNavigator::currentProjection)
        val magneticDeclinationDeg = location?.let { trusted ->
            runCatching {
                GeomagneticField(
                    trusted.latitude.toFloat(),
                    trusted.longitude.toFloat(),
                    0f,
                    System.currentTimeMillis(),
                ).declination
            }.getOrNull()
        }
        return ArCoreTactileProjectionContextFactory.create(
            frame = frame,
            elapsedRealtimeMs = elapsedRealtimeMs,
            expectedRouteId = expectedRouteId,
            routeProjection = routeProjection,
            trustedLocation = location,
            orientation = earthOrientationTracker.latest(),
            magneticDeclinationDeg = magneticDeclinationDeg,
        )
    }

    private fun attemptStepCalibration(location: Location, snapshot: PositioningSnapshot) {
        val raw = snapshot.raw ?: return walkingCalibrationSegments.reset()
        val receivedAtMs = SystemClock.elapsedRealtime()
        val freshMovingEvidence = latestPositionStationaryState == PositionStationaryState.MOVING &&
            latestPositionStationarySinceMs?.let { receivedAtMs - it in 0L..2_000L } == true
        val disposition = snapshot.gnssUpdate?.disposition
        if (disposition == GnssObservationDisposition.REINITIALIZED) {
            walkingCalibrationSegments.reset()
        }
        val acceptedRawFix = disposition == GnssObservationDisposition.INITIALIZED ||
            disposition == GnssObservationDisposition.REINITIALIZED ||
            disposition == GnssObservationDisposition.APPLIED
        walkingCalibrationSegments.onFix(
            fix = RawWalkingCalibrationFix(
                latitude = location.latitude,
                longitude = location.longitude,
                horizontalAccuracyM = raw.effectiveHorizontalAccuracyM,
                elapsedRealtimeMs = raw.elapsedRealtimeMs,
                receivedAtElapsedRealtimeMs = receivedAtMs,
                speedMps = location.speed.toDouble().takeIf { location.hasSpeed() },
                speedAccuracyMps = location.speedAccuracyMetersPerSecond.toDouble()
                    .takeIf { location.hasSpeedAccuracy() },
                courseDegrees = location.bearing.toDouble().takeIf { location.hasBearing() },
                courseAccuracyDegrees = location.bearingAccuracyDegrees.toDouble()
                    .takeIf { location.hasBearingAccuracy() },
                trustedRawFix = acceptedRawFix && !isMockLocationCompat(location) &&
                    freshMovingEvidence,
            ),
        ).forEach(::applyWalkingCalibrationSample)
    }

    private fun applyWalkingCalibrationSample(sample: WalkingCalibrationSample) {
        val calibration = positioningCoordinator.calibrateProfile(sample)
        if (calibration.rejectionReason == null) {
            val stepLengthM = positioningCoordinator.currentProfile().stepLengthM.toFloat()
            stepLengthEstimator.setStepLengthM(stepLengthM)
            objectDepthPipeline.setUserStepLength(stepLengthM)
            currentObjectDepthPipeline.setUserStepLength(stepLengthM)
            persistPositioningProfileForCurrentActor()
            val stepLengthText = String.format(Locale.US, "%.2f", stepLengthM)
            updateNavigationStatus("navigation=step_length_updated=${stepLengthText}m")
        }
    }

    private fun onRouteButtonClicked() {
        if (routeRequestInFlight.get()) {
            cancelActiveRouteRequest()
            return
        }
        if (isRouteActive) {
            resetRouteState()
            return
        }
        if (!currentNavigationCollectionAllowsWork()) {
            explainNavigationFeatureUnavailable()
            return
        }
        if (!requireReporterUserId("login_required_route")) return
        if (blockRouteMutationWhileDeviationChoicePending()) return
        if (!isRouteLocationPermissionReady()) {
            if (!ensureNavigationPermissionForRouteOrStep()) {
                return
            }
        }
        if (!navigationPermissionsRequestedForRoute) {
            navigationPermissionsRequestedForRoute = true
        }
        startNavigationServicesIfNeeded()
        if (!isRouteLocationPermissionReady()) {
            updateNavigationStatus("navigation=gps_permission_missing")
            return
        }
        val destination = currentDestination ?: parseDestinationInput()
        if (destination == null) {
            updateNavigationStatus("navigation=destination_missing")
            return
        }
        if (destinationSearchInFlight || navigationRequests.hasActiveDestinationSearch()) cancelDestinationSearch()
        currentDestination = destination
        isRouteActive = false
        latestTmapOnRoute = false
        updateRouteButtonText()
        requestRoute(destination, reason = "user_destination")
    }

    private fun routeSnapshotPurgeFenceAllowsRoute(): Boolean {
        // A failed cleanup remains recorded and retried; test guidance can run in memory.
        if (developmentGuidanceStartBypassEnabled) return true
        if (!routeSnapshotPurgeFailed) return true
        val detail =
            "암호화 경로 기록을 삭제하지 못해 새 길안내를 시작하지 않습니다. 저장소를 확인하고 새 보행을 시작해 주세요."
        enterWalkSessionSafetyStopAndCancelOutputs("route_snapshot_purge_failed")
        updateStatus("길안내 저장소 오류 · 안전 중지", detail)
        updateNavigationStatus("navigation=safety_stopped reason=route_snapshot_purge_failed")
        speakInteraction(detail)
        return false
    }

    private fun resetRouteState(purgeRouteSnapshot: Boolean = true) {
        cancelNavigationSpeechRetry()
        clearPendingExplicitRouteStart()
        navigationRequests.cancelRoute()
        isRouteActive = false
        latestTmapOnRoute = false
        latestTactileRouteState = "localRoute=tmap:navigation_inactive"
        routeRequestGeneration += 1
        routeRequestInFlight.set(false)
        currentDestination = null
        navigationPermissionsRequestedForRoute = false
        routeNavigator.clear()
        cancelRouteLocationStatusSpeech()
        feedbackActuator?.cancelNavigationSpeech()
        if (purgeRouteSnapshot) purgeEncryptedRouteSnapshot()
        cancelRouteDecisionSpeech()
        routeDeviationHapticDecision = null
        updateRouteDeviationActions(null)
        routeStartStepCount = null
        destinationSearchResults.clear()
        destinationSearchVoiceState = null
        updateDestinationSearchUi()
        updateRouteButtonText()
        updateNavigationStatus(
            if (routeSnapshotPurgeFailed) {
                "navigation=route_snapshot_purge_failed"
            } else {
                "navigation=destination_none hazard_only"
            },
        )
    }

    private fun purgeEncryptedRouteSnapshot(): Boolean {
        cancelEncryptedRouteSnapshotExpirySchedule()
        val purged = !::routeSnapshotStore.isInitialized || runCatching {
            routeSnapshotStore.clear()
        }.getOrDefault(false)
        routeSnapshotPurgeFailed = !purged
        return purged
    }

    private fun cancelEncryptedRouteSnapshotExpirySchedule() {
        routeSnapshotExpiryRunnable?.let(reportCleanupCallbackHandler::removeCallbacks)
        routeSnapshotExpiryRunnable = null
    }

    private fun scheduleEncryptedRouteSnapshotExpiry(
        walkSessionId: String,
        expiresAtEpochMs: Long,
    ) {
        cancelEncryptedRouteSnapshotExpirySchedule()
        lateinit var expiry: Runnable
        expiry = Runnable {
            if (routeSnapshotExpiryRunnable !== expiry) return@Runnable
            routeSnapshotExpiryRunnable = null
            val purged = purgeEncryptedRouteSnapshot()
            val activeSnapshotExpired = ::walkSessionLifecycle.isInitialized &&
                walkSessionLifecycle.currentRuntimeEpochOrNull()?.walkSessionId == walkSessionId &&
                isRouteActive
            if (activeSnapshotExpired && !developmentGuidanceStartBypassEnabled) {
                enterWalkSessionSafetyStopAndCancelOutputs("route_snapshot_expired")
                val detail =
                    "암호화 경로 기록의 24시간 보관 시간이 끝나 길안내를 중지했습니다."
                updateStatus(
                    "길안내 안전 중지",
                    detail,
                )
                updateNavigationStatus(
                    "navigation=safety_stopped reason=route_snapshot_expired purge=$purged",
                )
                speakInteraction(detail)
            } else if (!purged) {
                updateNavigationStatus("navigation=route_snapshot_purge_failed")
            }
        }
        routeSnapshotExpiryRunnable = expiry
        val remainingMs = (expiresAtEpochMs - System.currentTimeMillis())
            .coerceIn(0L, ROUTE_SNAPSHOT_TTL_MS)
        reportCleanupCallbackHandler.postDelayed(expiry, remainingMs)
    }

    private fun cancelActiveRouteRequest() {
        clearActiveRouteRequestState(navigationRequests.cancelRoute())
    }

    private fun clearActiveRouteRequestState(
        transportWasActive: Boolean,
        preserveExistingRoute: Boolean = false,
    ) {
        if (!routeRequestInFlight.get() && !transportWasActive) return
        routeRequestGeneration += 1
        routeRequestInFlight.set(false)
        if (preserveExistingRoute && isRouteActive && routeNavigator.hasRoute()) {
            navigationPermissionsRequestedForRoute = false
            updateRouteButtonText()
            updateNavigationStatus("navigation=route_request_cancelled existing_route_retained")
            return
        }
        isRouteActive = false
        latestTmapOnRoute = false
        latestTactileRouteState = "localRoute=tmap:navigation_inactive"
        currentDestination = null
        navigationPermissionsRequestedForRoute = false
        routeNavigator.clear()
        cancelNavigationSpeechRetry()
        cancelRouteLocationStatusSpeech()
        feedbackActuator?.cancelNavigationSpeech()
        purgeEncryptedRouteSnapshot()
        cancelRouteDecisionSpeech()
        routeDeviationHapticDecision = null
        updateRouteDeviationActions(null)
        routeStartStepCount = null
        updateRouteButtonText()
        updateNavigationStatus(
            if (routeSnapshotPurgeFailed) {
                "navigation=route_snapshot_purge_failed"
            } else {
                "navigation=route_request_cancelled hazard_only"
            },
        )
    }

    private fun suspendNavigationForRecovery(
        cancellation: AndroidNavigationCancellation,
    ) {
        val retainedDestination = currentDestination
        routeRequestGeneration += 1
        routeRequestInFlight.set(false)
        destinationSearchGeneration += 1
        destinationSearchInFlight = false
        pendingVoiceDestinationQuery = null
        pendingVoiceDestinationPageIndex = null
        destinationSearchVoiceState = null
        isRouteActive = false
        latestTmapOnRoute = false
        latestTactileRouteState = "localRoute=tmap:navigation_inactive"
        navigationPermissionsRequestedForRoute = false
        routeNavigator.clear()
        cancelNavigationSpeechRetry()
        cancelRouteLocationStatusSpeech()
        feedbackActuator?.cancelNavigationSpeech()
        cancelRouteDecisionSpeech()
        routeDeviationHapticDecision = null
        updateRouteDeviationActions(null)
        routeStartStepCount = null
        currentDestination = retainedDestination
        destinationSearchResults.clear()
        updateDestinationSearchUi()
        updateRouteButtonText()
        updateNavigationStatus(
            "navigation=route_revalidation_required " +
                "route_cancelled=${cancellation.routeCancelled} " +
                "search_cancelled=${cancellation.destinationSearchCancelled}",
        )
    }

    private fun parseDestinationInput(): RoutePoint? {
        if (!::destinationLatInput.isInitialized || !::destinationLngInput.isInitialized) return null
        val latText = destinationLatInput.text?.toString()?.trim().orEmpty()
        val lngText = destinationLngInput.text?.toString()?.trim().orEmpty()
        if (latText.isBlank() || lngText.isBlank()) return null
        val latitude = latText.toDoubleOrNull() ?: return null
        val longitude = lngText.toDoubleOrNull() ?: return null
        if (latitude !in -90.0..90.0 || longitude !in -180.0..180.0) return null
        return RoutePoint(latitude = latitude, longitude = longitude, name = "목적지")
    }

    private fun destinationSearchLocationLeaseOrNull(): DestinationSearchLocationLease? {
        if (!isActivityForeground || !currentDestinationSearchAllowsWork() ||
            !hasLocationPermission() || !isLocationServiceEnabledForDeviceCheck() ||
            (permissionRecoveryGate.blocksAutomaticResourceStart &&
                !(BuildConfig.DEBUG && BuildConfig.WALKSAFE_DEBUG_GUIDANCE_START_BYPASS))
        ) return null
        val actorId = currentReporterUserId()?.takeIf { it.isNotBlank() } ?: return null
        val snapshot = GatewaySessionProcessCoordinator.snapshot()
        if (snapshot.session == null || snapshot.deletionRecoveryOnly || snapshot.storageBlocked) return null
        return DestinationSearchLocationLease(actorId, snapshot.generation)
    }

    private fun destinationSearchLocationControllerOrNull(): DestinationSearchLocationController? {
        if (!::fusedLocationClient.isInitialized) return null
        return destinationSearchLocationController ?: DestinationSearchLocationController(
            AndroidDestinationSearchLocationSource(fusedLocationClient),
            SystemClock::elapsedRealtime,
        ).also { destinationSearchLocationController = it }
    }

    private fun cancelDestinationSearchLocation() {
        destinationSearchLocationController?.cancel()
        destinationSearchLocationMessage = null
    }

    private fun requestDestinationSearchLocation(query: String? = null, reset: Boolean = true): Boolean {
        val lease = destinationSearchLocationLeaseOrNull()
        val controller = destinationSearchLocationControllerOrNull()
        if (lease == null || controller == null) {
            cancelDestinationSearchLocation()
            destinationSearchLocationMessage = "현재 위치를 확인할 수 없습니다. 위치 권한과 위치 서비스를 켠 뒤 검색을 다시 눌러 주세요."
            updateDestinationSearchUi()
            if (query != null) speakInteraction(requireNotNull(destinationSearchLocationMessage))
            return false
        }
        if (query == null && (controller.isAcquiring || controller.originOrNull(lease) != null)) return true
        destinationSearchLocationMessage = "현재 위치를 확인하고 있습니다. 최대 10초 동안 기다려 주세요."
        destinationCancelButton.isEnabled = true
        updateDestinationSearchUi()
        return controller.acquire(
            lease,
            stillAllowed = { destinationSearchLocationLeaseOrNull() == lease },
        ) { origin ->
            if (destinationSearchLocationLeaseOrNull() != lease) return@acquire
            destinationSearchLocationMessage = if (origin == null) {
                "현재 위치를 확인하지 못했습니다. 위치 서비스를 확인하고 검색을 다시 눌러 주세요."
            } else null
            if (origin == null) {
                pendingVoiceDestinationQuery = null
                pendingVoiceDestinationPageIndex = null
                updateNavigationStatus("navigation=destination_search_location_unavailable")
                if (query != null) speakInteraction(requireNotNull(destinationSearchLocationMessage))
            }
            updateDestinationSearchUi()
            if (origin != null && query != null &&
                canonicalDestinationSearchQueryOrNull(destinationQueryInput.text?.toString().orEmpty()) == query
            ) performDestinationSearch(reset)
        }
    }

    private fun performDestinationSearch(reset: Boolean): Boolean {
        if (!currentDestinationSearchAllowsWork()) {
            explainNavigationFeatureUnavailable()
            return false
        }
        if (blockRouteMutationWhileDeviationChoicePending()) return false
        val rawQuery = destinationQueryInput.text?.toString().orEmpty()
        if (rawQuery.isBlank()) {
            updateNavigationStatus("navigation=destination_query_missing")
            return false
        }
        val query = canonicalDestinationSearchQueryOrNull(rawQuery) ?: run {
            updateNavigationStatus("navigation=destination_query_invalid max_code_points=80")
            speakInteraction("목적지는 80자 이하로 입력해 주세요.")
            return false
        }
        val expectedWalkEpoch = walkSessionLifecycle.snapshot().epoch
        if (!requireReporterUserId("login_required_destination_search")) return false
        if (!isGatewayNetworkAllowed(reason = "destination_search")) return false
        val gatewaySession = gatewaySessionOrNull("destination_search") ?: return false
        val gatewayProcessSnapshot = GatewaySessionProcessCoordinator.snapshot()
        if (
            gatewayProcessSnapshot.session !== gatewaySession ||
            gatewayProcessSnapshot.deletionRecoveryOnly ||
            gatewayProcessSnapshot.storageBlocked
        ) return false
        val expectedGatewaySessionGeneration = gatewayProcessSnapshot.generation
        GatewayCapacityProcessState.fenceSessionGeneration(
            expectedGatewaySessionGeneration,
        )
        if (destinationSearchInFlight || navigationRequests.hasActiveDestinationSearch()) return false
        if (!isRouteLocationPermissionReady() && !ensureNavigationPermissionForRouteOrStep()) {
            return false
        }
        val resetSearch = reset || destinationSearchQuery != query
        if (resetSearch) {
            destinationSearchPage = 1
            destinationSearchResults.clear()
            destinationSearchQuery = query
            destinationSearchVoiceState = null
            updateDestinationSearchUi()
        }
        val searchLocationLease = destinationSearchLocationLeaseOrNull()
        val origin = searchLocationLease?.let { destinationSearchLocationControllerOrNull()?.originOrNull(it) }
        if (origin == null) return requestDestinationSearchLocation(query, resetSearch)
        destinationSearchLocationMessage = null
        val requestId = destinationSearchGeneration + 1
        destinationSearchGeneration = requestId
        fun isCurrentSearchRequest(): Boolean =
            isDestinationSearchLeaseCurrent(expectedWalkEpoch, requestId) &&
                GatewaySessionProcessCoordinator.snapshot().generation == expectedGatewaySessionGeneration &&
                isCurrentGatewaySession(gatewaySession)
        if (!resetSearch) {
            destinationSearchPage += 1
        }
        val queryLimit = DESTINATION_SEARCH_PAGE_SIZE * destinationSearchPage
        destinationSearchInFlight = true
        destinationSearchButton.isEnabled = false
        destinationMoreButton.isEnabled = false
        destinationCancelButton.isEnabled = true
        val searchCall = trackDestinationSearchRequest(
            walkingRouteClient.searchDestinationsCall(
                session = gatewaySession,
                query = query,
                limit = queryLimit,
                origin = origin,
            ),
        )
        try {
            routeExecutor.execute {
                try {
                    if (
                        !isCurrentSearchRequest() ||
                        !isCurrentGatewaySession(gatewaySession)
                    ) {
                        completeDestinationSearchRequest(searchCall)
                        searchCall.cancel()
                        return@execute
                    }
                    val revalidation = gatewaySessionClient.revalidate(
                        gatewaySession,
                        currentReporterUserId(),
                        capacitySessionGeneration =
                            expectedGatewaySessionGeneration,
                    )
                    if (revalidation.status != GatewaySessionRevalidationStatus.READY) {
                        completeDestinationSearchRequest(searchCall)
                        searchCall.cancel()
                        runOnUiThread {
                            if (
                                !isCurrentSearchRequest()
                            ) return@runOnUiThread
                            if (
                                revalidation.status ==
                                GatewaySessionRevalidationStatus.NOT_READY
                            ) {
                                clearGatewaySession(
                                    logoutRemote = false,
                                    expectedSession = gatewaySession,
                                )
                            } else {
                                destinationSearchInFlight = false
                                destinationSearchButton.isEnabled = true
                                destinationCancelButton.isEnabled = false
                                updateDestinationSearchUi()
                            }
                            if (pendingVoiceDestinationQuery == query) {
                                pendingVoiceDestinationQuery = null
                                pendingVoiceDestinationPageIndex = null
                            }
                            updateNavigationStatus(
                                "navigation=destination_search_wait " +
                                    "gateway=${revalidation.status.name.lowercase(Locale.US)}",
                            )
                        }
                        return@execute
                    }
                    if (
                        !isCurrentSearchRequest() ||
                        !isCurrentGatewaySession(gatewaySession)
                    ) {
                        completeDestinationSearchRequest(searchCall)
                        searchCall.cancel()
                        return@execute
                    }
                    val result = searchCall.execute()
                    if (!isCurrentGatewaySession(gatewaySession)) {
                        completeDestinationSearchRequest(searchCall)
                        runOnUiThread {
                            if (
                                !isCurrentSearchRequest()
                            ) return@runOnUiThread
                            destinationSearchInFlight = false
                            destinationSearchButton.isEnabled = true
                            destinationCancelButton.isEnabled = false
                            updateDestinationSearchUi()
                            updateNavigationStatus("navigation=destination_search_cancelled session_changed")
                            if (pendingVoiceDestinationQuery == query) {
                                pendingVoiceDestinationQuery = null
                                pendingVoiceDestinationPageIndex = null
                            }
                        }
                        return@execute
                    }
                    completeDestinationSearchRequest(searchCall)
                    runOnUiThread {
                        if (
                            !isCurrentSearchRequest()
                        ) return@runOnUiThread
                        if (!isCurrentGatewaySession(gatewaySession)) {
                            destinationSearchInFlight = false
                            destinationSearchButton.isEnabled = true
                            destinationCancelButton.isEnabled = false
                            updateDestinationSearchUi()
                            updateNavigationStatus("navigation=destination_search_cancelled session_changed")
                            if (pendingVoiceDestinationQuery == query) {
                                pendingVoiceDestinationQuery = null
                                pendingVoiceDestinationPageIndex = null
                            }
                            return@runOnUiThread
                        }
                        destinationSearchInFlight = false
                        destinationSearchButton.isEnabled = true
                        destinationCancelButton.isEnabled = false
                        val merged = if (reset) result.results else {
                            destinationSearchResults + result.results
                        }
                        destinationSearchResults.clear()
                        destinationSearchResults.addAll(merged.distinctBy { "${it.id}:${it.point.latitude}:${it.point.longitude}" })
                        updateDestinationSearchUi()
                        updateNavigationStatus("navigation=search_results query=${result.query} count=${result.results.size}")
                        if (pendingVoiceDestinationQuery == query) {
                            pendingVoiceDestinationQuery = null
                            val requestedPageIndex = pendingVoiceDestinationPageIndex ?: 0
                            pendingVoiceDestinationPageIndex = null
                            val lastPageIndex = if (destinationSearchResults.isEmpty()) {
                                0
                            } else {
                                (destinationSearchResults.size - 1) / DESTINATION_SEARCH_PAGE_SIZE
                            }
                            if (requestedPageIndex <= lastPageIndex) {
                                destinationSearchVoiceState = DestinationSearchVoiceState(
                                    query = query,
                                    results = destinationSearchResults.toList(),
                                    pageIndex = requestedPageIndex,
                                    moreResultsAvailable =
                                        destinationSearchResults.size >=
                                            destinationSearchPage * DESTINATION_SEARCH_PAGE_SIZE &&
                                            destinationSearchResults.size < DESTINATION_SEARCH_MAX_RESULTS,
                                )
                                speakHomeDestinationVoicePrompt(requireNotNull(destinationSearchVoiceState))
                            } else {
                                destinationSearchVoiceState = DestinationSearchVoiceState(
                                    query = query,
                                    results = destinationSearchResults.toList(),
                                    pageIndex = lastPageIndex,
                                    moreResultsAvailable = false,
                                )
                                val state = requireNotNull(destinationSearchVoiceState)
                                speakHomeDestinationVoicePrompt(
                                    state,
                                    "더 안내할 목적지 후보가 없습니다. " + state.voicePrompt(),
                                )
                            }
                        }
                    }
                } catch (_: CancellationException) {
                    completeDestinationSearchRequest(searchCall)
                    runOnUiThread {
                        if (
                            !isCurrentSearchRequest()
                        ) return@runOnUiThread
                        destinationSearchInFlight = false
                        destinationSearchButton.isEnabled = true
                        destinationCancelButton.isEnabled = false
                        updateDestinationSearchUi()
                        updateNavigationStatus("navigation=destination_search_cancelled")
                    }
                } catch (error: Exception) {
                    if (error is InterruptedException) Thread.currentThread().interrupt()
                    completeDestinationSearchRequest(searchCall)
                    runOnUiThread {
                        if (
                            !isCurrentSearchRequest()
                        ) return@runOnUiThread
                        val failureGuard = gatewayFailureUiGuardOrNull(
                            session = gatewaySession,
                            expectedAuthenticationFailure =
                                error is GatewayProxyHttpException &&
                                    error.statusCode in setOf(401, 403),
                        )
                        destinationSearchInFlight = false
                        destinationSearchButton.isEnabled = true
                        destinationCancelButton.isEnabled = false
                        updateDestinationSearchUi()
                        val voiceRequest = pendingVoiceDestinationQuery == query
                        if (voiceRequest) {
                            pendingVoiceDestinationQuery = null
                            pendingVoiceDestinationPageIndex = null
                        }
                        if (failureGuard == null || !isGatewayFailureUiGuardCurrent(gatewaySession, failureGuard)) {
                            return@runOnUiThread
                        }
                        val failure = classifyNavigationBackendFailure(error)
                        destinationSearchLocationMessage = failure.kind.userMessage
                        updateDestinationSearchUi()
                        updateNavigationStatus("navigation=destination_search_failed ${failure.kind.statusToken}")
                        updateStatus("목적지 검색 실패", failure.kind.userMessage)
                        speakInteraction(failure.kind.userMessage)
                    }
                } finally {
                    completeDestinationSearchRequest(searchCall)
                }
            }
            return true
        } catch (_: RejectedExecutionException) {
            completeDestinationSearchRequest(searchCall)
            searchCall.cancel()
            if (!isCurrentSearchRequest()) {
                return false
            }
            destinationSearchInFlight = false
            destinationSearchButton.isEnabled = true
            destinationCancelButton.isEnabled = false
            destinationSearchResults.removeAll { true }
            updateDestinationSearchUi()
            updateNavigationStatus("navigation=destination_search_failed executor_rejected")
            if (pendingVoiceDestinationQuery == query) {
                pendingVoiceDestinationQuery = null
                pendingVoiceDestinationPageIndex = null
                speakInteraction("${query} 목적지 검색을 시작할 수 없습니다.")
            }
            return false
        }
    }

    private fun isDestinationSearchLeaseCurrent(
        expectedWalkEpoch: WalkRuntimeEpoch,
        expectedRequestId: Int,
    ): Boolean =
        expectedRequestId == destinationSearchGeneration &&
            ((walkSessionLifecycle.isRuntimeEpochCurrent(expectedWalkEpoch) &&
                (!isWalkSessionRuntimeActive() || navigationEnvironmentOutputsAllowed())) ||
                (nativeHomeFeatureContextAvailable() &&
                    walkSessionLifecycle.snapshot().epoch == expectedWalkEpoch &&
                    nativeUiPage in setOf(
                        NativeUiPage.VOICE_COMMAND, NativeUiPage.DESTINATION_SEARCH,
                        NativeUiPage.DESTINATION_CONFIRM,
                    ) &&
                    currentDestinationSearchAllowsWork()))

    private fun cancelDestinationSearch() {
        cancelDestinationSearchLocation()
        clearDestinationSearchState(navigationRequests.cancelDestinationSearch())
    }

    private fun clearDestinationSearchState(transportWasActive: Boolean) {
        if (!destinationSearchInFlight && !transportWasActive) return
        pendingVoiceDestinationQuery = null
        pendingVoiceDestinationPageIndex = null
        destinationSearchGeneration += 1
        destinationSearchInFlight = false
        destinationSearchButton.isEnabled = true
        destinationCancelButton.isEnabled = false
        destinationMoreButton.isEnabled = false
        destinationMoreButton.visibility = View.GONE
        updateDestinationSearchUi()
        updateNavigationStatus("navigation=destination_search_cancelled")
    }

    private fun onDestinationSelected(
        result: DestinationSearchResult,
        retainExplicitStartUntilTrustedLocation: Boolean = false,
    ): Boolean {
        if (!currentNavigationCollectionAllowsWork()) {
            explainNavigationFeatureUnavailable()
            return false
        }
        if (blockRouteMutationWhileDeviationChoicePending()) return false
        val cancellation = cancelNavigationRequestsForDestinationSelection()
        clearDestinationSearchState(cancellation.destinationSearchCancelled)
        if (!requireReporterUserId("login_required_route_select")) return false
        if (routeRequestInFlight.get() || cancellation.routeCancelled) {
            clearActiveRouteRequestState(cancellation.routeCancelled)
        } else if (isRouteActive) {
            resetRouteState()
        }
        if (::destinationLatInput.isInitialized) {
            destinationLatInput.setText(result.point.latitude.toString())
        }
        if (::destinationLngInput.isInitialized) {
            destinationLngInput.setText(result.point.longitude.toString())
        }
        currentDestination = result.point
        isRouteActive = false
        latestTmapOnRoute = false
        updateRouteButtonText()
        updateNavigationStatus("navigation=destination_selected ${result.name} ${formatDestinationDistance(result.distanceM)}")
        val routeRequestGenerationBefore = routeRequestGeneration
        requestRoute(
            result.point,
            reason = "user_destination",
            retainExplicitStartUntilTrustedLocation =
                retainExplicitStartUntilTrustedLocation,
        )
        return routeRequestGeneration != routeRequestGenerationBefore &&
            routeRequestInFlight.get()
    }

    private fun explainNavigationFeatureUnavailable() {
        val message =
            "위치 기능이 제한되어 목적지와 경로 안내를 사용할 수 없습니다. " +
                "위치 권한과 위치 서비스를 확인하세요. 다른 사용 가능한 기능은 계속됩니다."
        updateStatus("위치 기능 제한", message)
        speakInteraction(message)
    }

    private fun updateWalkFeatureAvailabilityUi() {
        if (
            !::destinationQueryInput.isInitialized ||
            !::destinationSearchButton.isInitialized ||
            !::destinationCancelButton.isInitialized ||
            !::destinationMoreButton.isInitialized ||
            !::routeButton.isInitialized
        ) return
        val destinationSearchAvailable = currentDestinationSearchAllowsWork()
        destinationQueryInput.isEnabled = destinationSearchAvailable && !destinationSearchInFlight
        destinationSearchButton.isEnabled = destinationSearchAvailable && !destinationSearchInFlight
        destinationCancelButton.isEnabled = true
        destinationMoreButton.isEnabled = destinationSearchAvailable && !destinationSearchInFlight
        routeButton.isEnabled =
            currentNavigationCollectionAllowsWork() || routeRequestInFlight.get() || isRouteActive
        if (::destinationSearchResultsContainer.isInitialized) {
            for (index in 0 until destinationSearchResultsContainer.childCount) {
                val child = destinationSearchResultsContainer.getChildAt(index)
                if (child is Button) {
                    child.isEnabled = destinationSearchAvailable && !destinationSearchInFlight
                }
            }
        }
        destinationQueryInput.hint = if (destinationSearchAvailable) {
            "목적지 검색"
        } else {
            "위치 기능 제한 · 목적지 검색 사용 불가"
        }
        destinationQueryInput.contentDescription = if (destinationSearchAvailable) {
            "목적지 입력"
        } else {
            "위치 기능이 제한되어 목적지와 경로 안내를 사용할 수 없습니다"
        }
    }

    private fun updateDestinationSearchUi() {
        if (!::destinationSearchResultsContainer.isInitialized) return
        destinationSearchResultsContainer.removeAllViews()
        if (destinationSearchResults.isEmpty()) {
            destinationSearchResultsContainer.addView(
                TextView(this).apply {
                    text = when {
                        !currentDestinationSearchAllowsWork() ->
                            "위치 기능 제한으로 목적지 검색을 사용할 수 없습니다."
                        destinationSearchLocationMessage != null -> requireNotNull(destinationSearchLocationMessage)
                        destinationSearchQuery.isBlank() -> "검색어를 입력하세요."
                        else -> "검색 결과 없음"
                    }
                    textSize = 18f
                    setTextColor(WS_COLOR_NOTICE_TEXT)
                    when {
                        !currentDestinationSearchAllowsWork() -> applyWsStatusCard(this)
                        destinationSearchQuery.isNotBlank() -> applyWsStatusCard(this)
                    }
                },
            )
            destinationMoreButton.visibility = View.GONE
            updateWalkFeatureAvailabilityUi()
            return
        }
        val density = resources.displayMetrics.density
        destinationSearchResults.forEach { result ->
            val details = "${result.address ?: "주소 없음"} · ${formatDestinationDistance(result.distanceM)}"
            val label = android.text.SpannableStringBuilder(result.name).apply {
                append("\n")
                val detailsStart = length
                append(details)
                setSpan(
                    android.text.style.AbsoluteSizeSpan(18, true),
                    detailsStart, length, android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
                )
                setSpan(
                    android.text.style.ForegroundColorSpan(WS_COLOR_NOTICE_TEXT),
                    detailsStart, length, android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE,
                )
            }
            destinationSearchResultsContainer.addView(
                Button(this).apply {
                    applyWsButtonStyle(this, WS_TOUCH_WALK_ACTION_DP)
                    applyNativePanelStyle(this)
                    text = label
                    textSize = 22f
                    setTextColor(0xff1b1b1d.toInt())
                    isAllCaps = false
                    setSingleLine(false)
                    gravity = Gravity.START or Gravity.CENTER_VERTICAL
                    minimumHeight = (200 * density).toInt()
                    setLineSpacing(0f, 1.4f)
                    layoutParams = LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT,
                        ViewGroup.LayoutParams.WRAP_CONTENT,
                    ).apply { bottomMargin = (12 * density).toInt() }
                    setOnClickListener {
                        openNativeDestinationConfirmation(result)
                    }
                },
            )
        }
        val canLoadMore = destinationSearchResults.size >= destinationSearchPage * DESTINATION_SEARCH_PAGE_SIZE &&
            destinationSearchResults.size < DESTINATION_SEARCH_MAX_RESULTS
        destinationMoreButton.visibility = if (canLoadMore) View.VISIBLE else View.GONE
        updateWalkFeatureAvailabilityUi()
    }

    private fun updateRouteButtonText() {
        refreshHomeRouteStatus()
        if (!::routeButton.isInitialized) return
        syncActiveSessionScreenPolicy()
        routeButton.text = when {
            routeRequestInFlight.get() -> "경로 취소"
            isRouteActive -> "경로 정지"
            else -> "경로 시작"
        }
        updateWalkFeatureAvailabilityUi()
    }

    /** Serializes route requests so user start and off-route reroute cannot race each other. */
    private fun requestRoute(
        destination: RoutePoint,
        reason: String,
        retainExplicitStartUntilTrustedLocation: Boolean = false,
    ) {
        if (!currentNavigationCollectionAllowsWork()) return
        if (reason != "off_route" && blockRouteMutationWhileDeviationChoicePending()) return
        if (!routeSnapshotPurgeFenceAllowsRoute()) return
        val expectedWalkEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return
        val deviceResources = walkSessionResourceProbe.snapshot()
        if (!developmentGuidanceStartBypassEnabled &&
            deviceResources.readinessStatus != WalkSessionReadinessStatus.READY
        ) {
            updateNavigationStatus(
                "navigation=route_blocked device_resources=" +
                    deviceResources.readinessStatus.name.lowercase(Locale.US),
            )
            return
        }
        val preserveExistingRoute = reason == "off_route" && isRouteActive
        if (!isGatewayNetworkAllowed(reason = "walking_route")) {
            if (!preserveExistingRoute) isRouteActive = false
            updateRouteButtonText()
            return
        }
        val gatewaySession = gatewaySessionOrNull("walking_route") ?: run {
            if (!preserveExistingRoute) isRouteActive = false
            latestTmapOnRoute = false
            if (!preserveExistingRoute) currentDestination = null
            updateRouteButtonText()
            return
        }
        val gatewayProcessSnapshot = GatewaySessionProcessCoordinator.snapshot()
        if (
            gatewayProcessSnapshot.session !== gatewaySession ||
            gatewayProcessSnapshot.deletionRecoveryOnly ||
            gatewayProcessSnapshot.storageBlocked
        ) return
        val expectedGatewaySessionGeneration = gatewayProcessSnapshot.generation
        GatewayCapacityProcessState.fenceSessionGeneration(
            expectedGatewaySessionGeneration,
        )
        val origin = currentRouteLocationOrNull()
        if (origin == null) {
            latestTmapOnRoute = false
            if (!preserveExistingRoute) {
                isRouteActive = false
                currentDestination = destination
                if (isRouteLocationPermissionReady()) {
                    navigationPermissionsRequestedForRoute = true
                    startNavigationServicesIfNeeded()
                }
            }
            updateRouteButtonText()
            val explicitStartRetained =
                retainExplicitStartUntilTrustedLocation &&
                    !preserveExistingRoute &&
                    isRouteLocationPermissionReady() &&
                    retainPendingExplicitRouteStart(destination)
            updateNavigationStatus(
                if (preserveExistingRoute) {
                    "navigation=reroute_blocked trusted_gps_missing existing_route_retained"
                } else if (explicitStartRetained) {
                    "navigation=route_waiting trusted_gps_missing start_request_pending"
                } else if (isRouteLocationPermissionReady()) {
                    "navigation=route_waiting trusted_gps_missing explicit_start_required"
                } else {
                    "navigation=route_blocked gps_permission_missing"
                },
            )
            if (explicitStartRetained) {
                val detail =
                    "선택한 목적지는 유지했습니다. 현재 위치를 확인 중이며, " +
                        "확인되면 방금 요청한 안내 시작을 이어갑니다."
                updateStatus("현재 위치 확인 중", detail)
                speakStatusExplanation(detail)
            }
            return
        }
        if (navigationRequests.hasActiveRoute() || !routeRequestInFlight.compareAndSet(false, true)) {
            updateNavigationStatus("navigation=route_blocked request_in_flight")
            return
        }
        isRouteActive = true
        currentDestination = destination
        val requestId = ++routeRequestGeneration
        updateNavigationStatus("navigation=route_requesting reason=$reason priority=STAIR_AVOID")
        updateRouteButtonText()
        val routeCall = trackRouteRequest(
            walkingRouteClient.fetchRouteCall(
                session = gatewaySession,
                request = WalkingRouteRequest(
                    origin = RoutePoint(origin.latitude, origin.longitude, "현재 위치"),
                    destination = destination,
                ),
            ),
        )
        try {
            routeExecutor.execute {
                var routeProviderCallInProgress = false
                try {
                    if (
                        !isRouteRequestLeaseCurrent(expectedWalkEpoch, requestId) ||
                        !isCurrentGatewaySession(gatewaySession)
                    ) {
                        completeRouteRequest(routeCall)
                        routeCall.cancel()
                        return@execute
                    }
                    val revalidation = gatewaySessionClient.revalidate(
                        gatewaySession,
                        currentReporterUserId(),
                        capacitySessionGeneration =
                            expectedGatewaySessionGeneration,
                    )
                    if (revalidation.status != GatewaySessionRevalidationStatus.READY) {
                        completeRouteRequest(routeCall)
                        routeCall.cancel()
                        runOnUiThread {
                            if (
                                !isRouteRequestLeaseCurrent(
                                    expectedWalkEpoch,
                                    requestId,
                                )
                            ) return@runOnUiThread
                            if (
                                revalidation.status ==
                                GatewaySessionRevalidationStatus.NOT_READY
                            ) {
                                clearGatewaySession(
                                    logoutRemote = false,
                                    expectedSession = gatewaySession,
                                )
                            } else if (preserveExistingRoute) {
                                routeRequestInFlight.set(false)
                                latestTmapOnRoute = false
                                retainRouteAfterRerouteFailure(
                                    "새 TMAP 경로를 아직 확인하지 못해 방향 안내를 중지했습니다.",
                                )
                                updateRouteButtonText()
                            } else {
                                routeRequestInFlight.set(false)
                                isRouteActive = false
                                latestTmapOnRoute = false
                                routeNavigator.clear()
                                routeStartStepCount = null
                                currentDestination = destination
                                updateRouteButtonText()
                            }
                            updateNavigationStatus(
                                "navigation=route_wait " +
                                    "gateway=${revalidation.status.name.lowercase(Locale.US)}",
                            )
                        }
                        return@execute
                    }
                    if (
                        !isRouteRequestLeaseCurrent(expectedWalkEpoch, requestId) ||
                        !isCurrentGatewaySession(gatewaySession)
                    ) {
                        completeRouteRequest(routeCall)
                        routeCall.cancel()
                        return@execute
                    }
                    routeProviderCallInProgress = true
                    val route = routeCall.execute()
                    routeProviderCallInProgress = false
                    if (!isCurrentGatewaySession(gatewaySession)) {
                        completeRouteRequest(routeCall)
                        runOnUiThread {
                            if (
                                !isRouteRequestLeaseCurrent(
                                    expectedWalkEpoch,
                                    requestId,
                                )
                            ) return@runOnUiThread
                            isRouteActive = false
                            latestTmapOnRoute = false
                            currentDestination = null
                            routeRequestInFlight.set(false)
                            updateRouteButtonText()
                            updateNavigationStatus("navigation=route_cancelled session_changed")
                        }
                        return@execute
                    }
                    if (!isRouteRequestLeaseCurrent(expectedWalkEpoch, requestId)) {
                        completeRouteRequest(routeCall)
                        return@execute
                    }
                    completeRouteRequest(routeCall)
                    runOnUiThread {
                        if (
                            !isRouteRequestLeaseCurrent(
                                expectedWalkEpoch,
                                requestId,
                            )
                        ) return@runOnUiThread
                        if (!isCurrentGatewaySession(gatewaySession)) {
                            isRouteActive = false
                            latestTmapOnRoute = false
                            currentDestination = null
                            routeRequestInFlight.set(false)
                            updateRouteButtonText()
                            updateNavigationStatus("navigation=route_cancelled session_changed")
                            return@runOnUiThread
                        }
                        if (!isRouteActive) return@runOnUiThread
                        if (!routeSnapshotPurgeFenceAllowsRoute()) return@runOnUiThread
                        val storedRouteSnapshot = runCatching {
                            val saved = routeSnapshotStore.saveFirstRoute(
                                walkSessionId = expectedWalkEpoch.walkSessionId,
                                route = route,
                                destination = destination,
                            )
                            if (!saved) null else routeSnapshotStore.load()
                        }.getOrNull()?.takeIf {
                            it.walkSessionId == expectedWalkEpoch.walkSessionId
                        }
                        if (storedRouteSnapshot == null && !developmentGuidanceStartBypassEnabled) {
                            routeRequestInFlight.set(false)
                            enterWalkSessionSafetyStopAndCancelOutputs("route_snapshot_store_failed")
                            val detail =
                                "최초 TMAP 경로를 암호화해 저장하지 못해 보행 기능을 중지했습니다."
                            updateStatus(
                                "길안내 안전 중지",
                                detail,
                            )
                            updateNavigationStatus("navigation=safety_stopped reason=route_snapshot_store_failed")
                            speakInteraction(detail)
                            return@runOnUiThread
                        }
                        if (storedRouteSnapshot != null) {
                            routeSnapshotPurgeFailed = false
                            scheduleEncryptedRouteSnapshotExpiry(
                                walkSessionId = storedRouteSnapshot.walkSessionId,
                                expiresAtEpochMs = storedRouteSnapshot.expiresAtEpochMs,
                            )
                        }
                        tmapFailureGuard.recordSuccess()
                        routeNavigator.setRoute(
                            route,
                            destination = destination,
                            origin = origin,
                        )
                        if (::fieldSessionLog.isInitialized) fieldSessionLog.recordEvent(
                            "route_installed",
                            mapOf(
                                "routeId" to routeNavigator.currentRouteId(),
                                "points" to route.polyline.size,
                                "guides" to route.guidePoints.size,
                                "distanceM" to route.summary.distanceM,
                            ),
                        )
                        routeStartStepCount = latestStepCount
                        directionGuidancePauseReason = null
                        latestTmapOnRoute = true
                        routeRequestInFlight.set(false)
                        updateRouteButtonText()
                        updateNavigationStatus(
                            "navigation=route_ready distance=${route.summary.distanceM}m priority=${route.priority}",
                        )
                        val routeLocation = currentRouteLocationOrNull()
                        if (routeLocation != null) {
                            updateRouteGuidance(routeLocation, latestRawRouteLocation ?: routeLocation)
                        } else {
                            val accepted = speakStatusExplanation(
                                "목적지까지 약 ${route.summary.distanceM}미터의 경로를 찾았습니다. " +
                                    "현재 위치를 확인하면 이동 방향을 안내하겠습니다.",
                            )
                            routeLocationStatusResponseGeneration =
                                commandSpeechResponseGeneration.takeIf { accepted }
                        }
                    }
                } catch (_: CancellationException) {
                    completeRouteRequest(routeCall)
                    runOnUiThread {
                        if (
                            !isRouteRequestLeaseCurrent(
                                expectedWalkEpoch,
                                requestId,
                            )
                        ) return@runOnUiThread
                        routeRequestInFlight.set(false)
                        if (!preserveExistingRoute) isRouteActive = false
                        latestTmapOnRoute = false
                        if (!preserveExistingRoute) currentDestination = null
                        if (preserveExistingRoute) {
                            retainRouteAfterRerouteFailure("TMAP 새 경로 요청이 취소되어 방향 안내를 중지했습니다.")
                        }
                        updateRouteButtonText()
                        updateNavigationStatus("navigation=route_cancelled")
                    }
                } catch (error: Exception) {
                    completeRouteRequest(routeCall)
                    val navigationFailure = classifyNavigationBackendFailure(error)
                    val countableTmapFailure = routeProviderCallInProgress &&
                        navigationFailure.kind != NavigationBackendErrorKind.AUTHENTICATION
                    runOnUiThread {
                        if (
                            !isRouteRequestLeaseCurrent(
                                expectedWalkEpoch,
                                requestId,
                            )
                        ) return@runOnUiThread
                        val failureGuard = gatewayFailureUiGuardOrNull(
                            session = gatewaySession,
                            expectedAuthenticationFailure =
                                navigationFailure.kind == NavigationBackendErrorKind.AUTHENTICATION,
                        )
                        routeRequestInFlight.set(false)
                        updateRouteButtonText()
                        if (failureGuard == null || !isGatewayFailureUiGuardCurrent(gatewaySession, failureGuard)) {
                            return@runOnUiThread
                        }
                        if (
                            countableTmapFailure &&
                            tmapFailureGuard.recordFailure() &&
                            !developmentGuidanceStartBypassEnabled
                        ) {
                            enterWalkSessionSafetyStopAndCancelOutputs("tmap_consecutive_failures")
                            val safetyStopDetail =
                                "${navigationFailure.kind.userMessage} " +
                                    "TMAP 경로 요청이 두 번 연속 실패해 모든 보행 기능을 중지했습니다. " +
                                    "새 보행을 직접 시작해 주세요."
                            updateStatus(
                                "길안내 안전 중지",
                                safetyStopDetail,
                            )
                            updateNavigationStatus(
                                "navigation=safety_stopped reason=tmap_consecutive_failures " +
                                    "kind=${navigationFailure.kind.statusToken}",
                            )
                            speakInteraction(safetyStopDetail)
                            return@runOnUiThread
                        }
                        if (!preserveExistingRoute) isRouteActive = false
                        latestTmapOnRoute = false
                        if (!preserveExistingRoute) currentDestination = null
                        updateRouteButtonText()
                        updateNavigationStatus(
                            if (preserveExistingRoute) {
                                "navigation=reroute_failed ${navigationFailure.kind.statusToken} existing_route_retained"
                            } else {
                                "navigation=route_failed ${navigationFailure.kind.statusToken}"
                            },
                        )
                        if (preserveExistingRoute) {
                            retainRouteAfterRerouteFailure(navigationFailure.kind.userMessage)
                        } else {
                            speakInteraction(navigationFailure.kind.userMessage)
                        }
                    }
                } finally {
                    completeRouteRequest(routeCall)
                }
            }
        } catch (_: RejectedExecutionException) {
            completeRouteRequest(routeCall)
            routeCall.cancel()
            if (!isRouteRequestLeaseCurrent(expectedWalkEpoch, requestId)) return
            routeRequestInFlight.set(false)
            if (!preserveExistingRoute) isRouteActive = false
            latestTmapOnRoute = false
            if (!preserveExistingRoute) currentDestination = null
            updateRouteButtonText()
            updateNavigationStatus(
                if (preserveExistingRoute) {
                    "navigation=reroute_failed executor_rejected existing_route_retained"
                } else {
                    "navigation=route_failed executor_rejected"
                },
            )
            if (preserveExistingRoute) {
                retainRouteAfterRerouteFailure("TMAP 새 경로를 확인할 수 없어 방향 안내를 중지했습니다.")
            } else {
                speakInteraction("TMAP 경로를 확인할 수 없어 길안내를 시작하지 않았습니다.")
            }
        }
    }

    private fun isRouteRequestLeaseCurrent(
        expectedWalkEpoch: WalkRuntimeEpoch,
        expectedRequestId: Int,
    ): Boolean =
        walkSessionLifecycle.isRuntimeEpochCurrent(expectedWalkEpoch) &&
            expectedRequestId == routeRequestGeneration &&
            (!isWalkSessionRuntimeActive() || navigationEnvironmentOutputsAllowed())

    private fun updateRouteGuidance(
        location: TrustedLocation,
        rawLocation: TrustedLocation = location,
    ) {
        // A location update may start this request earlier in the very same callback. Loading
        // has no installed route yet; it must not be treated as a lost/invalid saved route.
        if (!isRouteActive || routeRequestInFlight.get()) return
        val expectedWalkEpoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return
        if (!developmentGuidanceStartBypassEnabled &&
            (positionGuidancePaused || directionGuidancePauseReason == "tmap_unavailable")
        ) {
            latestTmapOnRoute = false
            val pauseReason = if (positionGuidancePaused) {
                "position_quality"
            } else {
                "tmap_unavailable"
            }
            updateNavigationStatus("navigation=direction_paused reason=$pauseReason")
            return
        }
        val nowMs = SystemClock.elapsedRealtime()
        val facing = currentRouteFacingObservation(nowMs)
        val update = routeNavigator.update(
            location = rawLocation,
            nowMs = nowMs,
            requestInFlight = routeRequestInFlight.get(),
            stepProgressM = routeStepProgressMOrNull(),
            facingObservation = facing,
            filteredPosition = FilteredRoutePosition(
                point = RoutePoint(location.latitude, location.longitude),
                horizontalAccuracyM = location.accuracyM.toDouble(),
                elapsedRealtimeMs = location.elapsedRealtimeMs,
                heading = latestGpsCourseObservation
                    ?.takeIf { latestWalkingSpeedObservation?.speedMps?.let { it > 0.5 } == true }
                    ?.let { heading ->
                    RouteHeadingEstimate(
                        degrees = heading.headingDegreesTrueNorth,
                        standardDeviationDeg = requireNotNull(heading.accuracyDegrees),
                    )
                },
            ),
        )
        recordRouteAlignmentDiagnostic(update, facing, location.accuracyM, nowMs)
        applyRouteDeviationSafetyUpdate(update)
        val acceptedPosition = routeNavigator.currentAcceptedRouteMatchFor(location.elapsedRealtimeMs) != null &&
            update.reason !in setOf("route_match_untrusted", "location_sample_not_newer")
        if (acceptedPosition && !update.userDecisionRequired && !update.offRoute) {
            directionGuidancePauseReason = null
        }
        latestTmapOnRoute = acceptedPosition && isRouteActive &&
            !routeRequestInFlight.get() &&
            update.reason != "route_missing" &&
            update.reason != "polyline_missing" &&
            !update.offRoute &&
            !update.shouldReroute &&
            !update.arrived &&
            !update.userDecisionRequired
        maybePlayProgressBeep(
            nowMs,
            offRoute = !acceptedPosition || update.offRoute || update.userDecisionRequired,
            arrived = update.arrived,
        )
        updateNavigationStatus(
            "navigation=${update.reason} offRoute=${update.offRoute} " +
                "arrived=${update.arrived} decisionRequired=${update.userDecisionRequired}",
        )
        if (update.reason in setOf("route_missing", "polyline_missing")) {
            pauseDirectionGuidance(
                reason = "route_invalid",
                message = "경로 데이터를 확인하지 못했습니다. 안내를 다시 시작해 주세요.",
            )
        }
        tryDispatchRouteInstruction(update, expectedWalkEpoch)
    }

    private fun recordRouteAlignmentDiagnostic(
        update: RouteNavigatorUpdate,
        facing: RouteFacingObservation?,
        positionUncertaintyM: Float,
        nowMs: Long,
    ) {
        val alignment = update.routeAlignmentDiagnostic ?: return
        val key = "${routeRequestGeneration}:${alignment.reason}:${alignment.segmentIndex}:${facing?.source}"
        if (lastRouteAlignmentDiagnosticKey == key && nowMs - lastRouteAlignmentDiagnosticAtMs in 0L..1_999L) return
        lastRouteAlignmentDiagnosticKey = key
        lastRouteAlignmentDiagnosticAtMs = nowMs
        val values = mapOf(
            "reason" to alignment.reason.name,
            "segmentIndex" to alignment.segmentIndex,
            "routeBearingDeg" to alignment.bearingDegreesTrueNorth,
            "rearHeadingDeg" to facing?.degreesTrueNorth,
            "compassSource" to facing?.source?.name,
            "compassAgeMs" to facing?.let { nowMs - it.observedAtElapsedRealtimeMs },
            "positionUncertaintyM" to positionUncertaintyM,
        )
        if (BuildConfig.DEBUG) runCatching {
            android.util.Log.d("WalkSafeNavigation", "route_alignment=$values")
        }
        if (::fieldSessionLog.isInitialized) fieldSessionLog.recordEvent("route_alignment", values)
    }

    private fun cancelRouteLocationStatusSpeech() {
        val generation = routeLocationStatusResponseGeneration ?: return
        routeLocationStatusResponseGeneration = null
        if (generation == commandSpeechResponseGeneration) cancelCommandSpeechResponse()
    }

    private fun cancelNavigationSpeechRetry() {
        val pending = navigationSpeechRetryRunnable ?: return
        navigationSpeechRetryRunnable = null
        reportCleanupCallbackHandler.removeCallbacks(pending)
    }

    private fun isRouteSpeechCurrent(
        epoch: WalkRuntimeEpoch,
        requestGeneration: Int,
        lifecycleGeneration: Int,
    ): Boolean =
        isFeedbackLifecycleCurrent(lifecycleGeneration) &&
            ::walkSessionLifecycle.isInitialized &&
            walkSessionLifecycle.isRuntimeEpochCurrent(epoch) &&
            isWalkSessionRuntimeActive() && navigationEnvironmentOutputsAllowed() &&
            isRouteActive && !routeRequestInFlight.get() &&
            routeRequestGeneration == requestGeneration

    private fun scheduleNavigationSpeechRetry(delayMs: Long = 250L) {
        if (!::walkSessionLifecycle.isInitialized || !isRouteActive) return
        val epoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return
        val requestGeneration = routeRequestGeneration
        val lifecycleGeneration = feedbackLifecycleGeneration
        if (!isRouteSpeechCurrent(epoch, requestGeneration, lifecycleGeneration)) return
        if (navigationSpeechRetryRunnable != null) {
            if (delayMs != 0L) return
            cancelNavigationSpeechRetry()
        }
        lateinit var retry: Runnable
        retry = Runnable {
            if (navigationSpeechRetryRunnable !== retry) return@Runnable
            navigationSpeechRetryRunnable = null
            if (!isRouteSpeechCurrent(epoch, requestGeneration, lifecycleGeneration)) return@Runnable
            val nowMs = SystemClock.elapsedRealtime()
            val update = routeNavigator.retryGuidance(
                nowMs, facingObservation = currentRouteFacingObservation(nowMs),
            ) ?: return@Runnable
            tryDispatchRouteInstruction(update, epoch)
        }
        navigationSpeechRetryRunnable = retry
        reportCleanupCallbackHandler.postDelayed(retry, delayMs)
    }

    private fun tryDispatchRouteInstruction(update: RouteNavigatorUpdate, expectedWalkEpoch: WalkRuntimeEpoch) {
        if (update.userDecisionRequired) return
        val instruction = update.instruction
        if (instruction == null) {
            if (update.reason in setOf(
                    "guidance_retry_wait", "guidance_rate_limited", "guidance_already_completed",
                )
            ) {
                scheduleNavigationSpeechRetry()
            }
            return
        }
        val requestGeneration = routeRequestGeneration
        val lifecycleGeneration = feedbackLifecycleGeneration
        if (!isRouteSpeechCurrent(expectedWalkEpoch, requestGeneration, lifecycleGeneration)) return
        if (deferredVoiceRecognitionStart != null ||
            !feedbackPolicy.canSpeakNavigation(SystemClock.elapsedRealtime())
        ) {
            scheduleNavigationSpeechRetry()
            return
        }
        if (!routeNavigator.reserveInstruction(update)) return
        cancelNavigationSpeechRetry()
        cancelRouteLocationStatusSpeech()
        val accepted = dispatchNavigationSpeech(
            instruction,
            onCompleted = {
                if (isRouteSpeechCurrent(expectedWalkEpoch, requestGeneration, lifecycleGeneration)) {
                    routeNavigator.acknowledgeInstruction(update, SystemClock.elapsedRealtime())
                    scheduleNavigationSpeechRetry()
                    showWalkLastResult(instruction)
                    if (BuildConfig.DEBUG) android.util.Log.d("WalkSafeNavigation", "speech=completed")
                } else {
                    routeNavigator.releaseInstruction(update, SystemClock.elapsedRealtime())
                }
            },
            onFailed = {
                routeNavigator.releaseInstruction(update, SystemClock.elapsedRealtime())
                if (isRouteSpeechCurrent(expectedWalkEpoch, requestGeneration, lifecycleGeneration)) {
                    if (BuildConfig.DEBUG) android.util.Log.d("WalkSafeNavigation", "speech=retry_pending")
                    scheduleNavigationSpeechRetry()
                }
            },
        )
        if (BuildConfig.DEBUG) android.util.Log.d(
            "WalkSafeNavigation",
            "speech=${if (accepted) "accepted" else "unavailable"} " +
                "${feedbackActuator?.statusText() ?: "tts=absent"}",
        )
    }

    private fun failInterruptedRouteDecisionSpeech(previousResponseGeneration: Long) {
        if (routeDecisionSpeechResponseGeneration != previousResponseGeneration) return
        commandSpeechResponseCallbacks.takeTerminalCallback(
            "command-response-$previousResponseGeneration", completed = false, notifyFailure = true,
        )?.invoke()
    }

    private fun cancelRouteDecisionSpeech() {
        routeDecisionSpeechAttempt += 1L
        routeDecisionSpeechRetryRunnable?.let(reportCleanupCallbackHandler::removeCallbacks)
        routeDecisionSpeechRetryRunnable = null
        pendingRouteDecisionSpeechToken = null
        lastAnnouncedRouteDecisionToken = null
        val responseGeneration = routeDecisionSpeechResponseGeneration
        routeDecisionSpeechResponseGeneration = null
        if (responseGeneration != null && responseGeneration == commandSpeechResponseGeneration) {
            cancelCommandSpeechResponse()
        }
    }

    private fun speakRouteDecision(
        message: String,
        token: RouteNavigatorDecisionToken,
        repeatRequested: Boolean = false,
    ): Boolean {
        if (token != routeNavigator.pendingDecisionToken()) return false
        if (pendingRouteDecisionSpeechToken == token) return true
        if (!repeatRequested && lastAnnouncedRouteDecisionToken == token) return true
        cancelRouteDecisionSpeech()
        val epoch = walkSessionLifecycle.currentRuntimeEpochOrNull() ?: return false
        val requestGeneration = routeRequestGeneration
        val lifecycleGeneration = feedbackLifecycleGeneration
        if (!isRouteSpeechCurrent(epoch, requestGeneration, lifecycleGeneration)) return false
        pendingRouteDecisionSpeechToken = token
        val attempt = ++routeDecisionSpeechAttempt
        fun current(): Boolean =
            attempt == routeDecisionSpeechAttempt && pendingRouteDecisionSpeechToken == token &&
                token == routeNavigator.pendingDecisionToken() &&
                isRouteSpeechCurrent(epoch, requestGeneration, lifecycleGeneration)

        fun retry() {
            if (!current() || routeDecisionSpeechRetryRunnable != null) return
            routeDecisionSpeechResponseGeneration = null
            lateinit var pending: Runnable
            pending = Runnable {
                if (routeDecisionSpeechRetryRunnable !== pending) return@Runnable
                routeDecisionSpeechRetryRunnable = null
                if (!current()) return@Runnable
                pendingRouteDecisionSpeechToken = null
                speakRouteDecision(message, token, repeatRequested)
            }
            routeDecisionSpeechRetryRunnable = pending
            reportCleanupCallbackHandler.postDelayed(pending, 1_000L)
        }
        // A failed decision remains pending, but cannot interrupt a newer command or voice input.
        if (commandSpeechResponseCallbacks.size() > 0 || voiceRecognitionActive ||
            gatewayVoiceRecorder?.isRecording == true || deferredVoiceRecognitionStart != null
        ) {
            retry()
            return false
        }
        var terminated = false
        val previousResponseGeneration = commandSpeechResponseGeneration
        val accepted = speakCommandResponse(
            message,
            onCompleted = {
                terminated = true
                if (current()) {
                    routeDecisionSpeechResponseGeneration = null
                    pendingRouteDecisionSpeechToken = null
                    lastAnnouncedRouteDecisionToken = token
                }
            },
            onFailed = {
                terminated = true
                retry()
            },
        )
        if (accepted && !terminated && current() &&
            commandSpeechResponseGeneration != previousResponseGeneration
        ) {
            routeDecisionSpeechResponseGeneration = commandSpeechResponseGeneration
        }
        if (!accepted && !terminated) retry()
        return accepted
    }

    private fun applyRouteDeviationSafetyUpdate(update: RouteNavigatorUpdate): Boolean {
        if (update.cancelStaleNavigationSpeech) {
            feedbackActuator?.cancelNavigationSpeech()
        }
        updateRouteDeviationActions(update.pendingUserDecision)
        maybePlayRouteDeviationHaptic(update.pendingUserDecision)
        if (!update.userDecisionRequired) {
            cancelRouteDecisionSpeech()
            return false
        }
        latestTmapOnRoute = false
        directionGuidancePauseReason = update.reason
        val token = routeNavigator.pendingDecisionToken()
        if (token != null) {
            update.instruction?.let { speakRouteDecision(it, token) }
        }
        return true
    }

    private fun updateRouteDeviationActions(decision: RouteNavigatorUserDecision?) {
        if (!::routeDeviationActions.isInitialized) return
        val suspected = decision == RouteNavigatorUserDecision.LOCATION_RECHECK
        val confirmed = decision == RouteNavigatorUserDecision.REROUTE
        val arrival = decision == RouteNavigatorUserDecision.ARRIVAL_CONFIRMATION
        val decisionVisible = suspected || confirmed || arrival
        renderedArrivalDecisionToken = if (arrival) routeNavigator.pendingDecisionToken() else null
        routeDeviationActions.visibility = if (decisionVisible) View.VISIBLE else View.GONE
        if (::routeDeviationSection.isInitialized) {
            routeDeviationSection.visibility =
                if (decisionVisible) View.VISIBLE else View.GONE
        }
        routeDeviationActions.contentDescription = when {
            confirmed -> "경로 이탈 확정. 새 경로 요청, 위치 다시 확인, 길안내 종료 중 선택"
            suspected -> "경로 이탈 의심. 위치 다시 확인 선택"
            arrival -> "도착 후보입니다. 도착 확인 또는 도착 아님 중 선택"
            else -> null
        }
        if (::offRouteNoticeText.isInitialized) {
            offRouteNoticeText.text = when {
                confirmed -> "경로를 벗어났습니다"
                suspected -> "경로를 벗어난 것으로 보입니다"
                arrival -> "목적지에 도착하셨나요?"
                else -> ""
            }
        }
        routeDeviationNewRouteButton.visibility = if (confirmed) View.VISIBLE else View.GONE
        routeDeviationRecheckButton.visibility = if (suspected || confirmed) View.VISIBLE else View.GONE
        routeDeviationEndButton.visibility = if (confirmed) View.VISIBLE else View.GONE
        arrivalConfirmButton.visibility = if (arrival) View.VISIBLE else View.GONE
        arrivalRejectButton.visibility = if (arrival) View.VISIBLE else View.GONE
        if (::routeButton.isInitialized) {
            routeButton.visibility = if (decisionVisible) View.GONE else View.VISIBLE
        }
        if (::destinationResetButton.isInitialized) {
            destinationResetButton.visibility = if (decisionVisible) View.GONE else View.VISIBLE
        }
    }

    private fun routeDeviationChoicePending(): Boolean =
        routeNavigator.pendingUserDecision() in setOf(
            RouteNavigatorUserDecision.LOCATION_RECHECK,
            RouteNavigatorUserDecision.REROUTE,
            RouteNavigatorUserDecision.ARRIVAL_CONFIRMATION,
        )

    private fun blockRouteMutationWhileDeviationChoicePending(): Boolean {
        if (developmentGuidanceStartBypassEnabled) return false
        if (!routeDeviationChoicePending()) return false
        updateNavigationStatus("navigation=route_deviation_choice_required")
        speakInteraction("음성 명령으로 현재 경로 상태를 먼저 확인해 주세요.")
        return true
    }

    private fun maybePlayRouteDeviationHaptic(decision: RouteNavigatorUserDecision?) {
        if (decision == routeDeviationHapticDecision) return
        routeDeviationHapticDecision = decision
        when (decision) {
            RouteNavigatorUserDecision.LOCATION_RECHECK ->
                ensureFeedbackActuator().playRouteGuidancePausedVibration()
            RouteNavigatorUserDecision.REROUTE ->
                ensureFeedbackActuator().playRouteDeviationConfirmedVibration()
            else -> Unit
        }
    }

    private fun routeStepProgressMOrNull(): Double? {
        val baseline = routeStartStepCount ?: return null
        if (!isRouteActive || !routeNavigator.hasRoute()) return null
        val deltaSteps = latestStepCount - baseline
        if (deltaSteps < 0) return null
        return deltaSteps * stepLengthEstimator.stepLengthM.toDouble()
    }

    private fun retainRouteAfterRerouteFailure(message: String) {
        if (developmentGuidanceStartBypassEnabled) {
            directionGuidancePauseReason = null
            speakInteraction("$message 기존 TMAP 경로를 유지합니다.")
            return
        }
        routeNavigator.rerouteRequestFailed()?.let(::applyRouteDeviationSafetyUpdate)
        pauseDirectionGuidance(reason = "tmap_unavailable", message = message)
    }

    private fun pauseDirectionGuidance(reason: String, message: String) {
        if (!isRouteActive) return
        latestTmapOnRoute = false
        updateNavigationStatus("navigation=direction_paused reason=$reason")
        if (isRouteActive && directionGuidancePauseReason != reason) {
            directionGuidancePauseReason = reason
            speakInteraction(message)
        }
    }

    private fun updateNavigationStatus(text: String) {
        val state = text.trim().substringBefore(' ').take(FIELD_STATUS_MAX_LENGTH).ifBlank { "navigation=unknown" }
        if (state != latestNavigationState) {
            if (BuildConfig.DEBUG && state.startsWith("navigation=")) {
                android.util.Log.d("WalkSafeNavigation", "state=$state")
            }
            latestNavigationState = state
            refreshHomeRouteStatus()
            if (::fieldSessionLog.isInitialized) {
                fieldSessionLog.recordEvent("navigation_state_changed", mapOf("state" to state))
            }
        }
        if (::navigationStatusText.isInitialized) {
            if (Looper.myLooper() == Looper.getMainLooper()) {
                navigationStatusText.text = text
                if (nativeUiPage == NativeUiPage.GUIDANCE) renderMainUi()
            } else {
                reportCleanupCallbackHandler.post {
                    if (
                        !privacyStartupInspectionDestroyed &&
                        ::navigationStatusText.isInitialized
                    ) {
                        navigationStatusText.text = text
                        if (nativeUiPage == NativeUiPage.GUIDANCE) renderMainUi()
                    }
                }
            }
        }
    }

    private fun updateProgressBeepButtons() {
        if (!::progressBeepToggleButton.isInitialized || !::progressBeepVolumeButton.isInitialized) return
        progressBeepToggleButton.text = if (progressBeepEnabled) "진행음 켜짐" else "진행음 꺼짐"
        progressBeepVolumeButton.text = "진행음 볼륨 ${progressBeepVolumePercent}%"
    }

    private fun updateLoginButtonText() {
        if (!::loginSaveButton.isInitialized) return
        val selectedUserId = reporterUserId
        loginSaveButton.text = when {
            selectedUserId == null -> "0. 교육 대상 로그인 ID 확인"
            currentReporterUserId() == null -> "교육 대상 ID 선택됨 · 조건 확인 필요"
            else -> "교육 대상 ID 확인됨"
        }
        loginSaveButton.contentDescription = loginSaveButton.text
        if (::accountLogoutButton.isInitialized) {
            accountLogoutButton.isEnabled =
                selectedUserId != null &&
                    !priorityUserEducationInFlight &&
                    priorityUserPracticeInFlight == null
        }
    }

